// Client-direct RPC: the user's own free toncenter API key (10 rps) speeds up reads + the message
// indexer. Stored locally; injected into the user-toncenter transport at build via
// globalThis.plathoToncenterApiKey. Keyless toncenter keeps working without it.
const TONCENTER_API_KEY_STORAGE_KEY = 'platho.toncenter.apiKey.v1';

// Compact RPC-key status (v651, owner: "key active" ate the row) — a single pictogram with the full text in the
// tooltip: ✓ active, ✕ rejected, ⏳ still checking/activating, empty when no key.
const TONCENTER_KEY_STATUS_ICONS = Object.freeze({
  active: { icon: '✓', state: 'ok', title: t('wallet.rpcKeyStatusActive') },
  error: { icon: '✕', state: 'error', title: t('wallet.rpcKeyStatusError') },
  checking: { icon: '⏳', state: '', title: t('wallet.rpcKeyStatusChecking') },
  activating: { icon: '⏳', state: '', title: t('wallet.rpcKeyStatusActivating') },
  empty: { icon: '', state: '', title: '' },
});

function setToncenterKeyStatusIcon(kind) {
  if (!toncenterKeyStatus) return;
  const entry = TONCENTER_KEY_STATUS_ICONS[kind] ?? TONCENTER_KEY_STATUS_ICONS.empty;
  toncenterKeyStatus.textContent = entry.icon;
  toncenterKeyStatus.title = entry.title;
  toncenterKeyStatus.setAttribute('aria-label', entry.title);
  if (entry.state) {
    toncenterKeyStatus.setAttribute('data-state', entry.state);
  } else {
    toncenterKeyStatus.removeAttribute('data-state');
  }
}

function refreshToncenterKeyUi() {
  let key = globalThis.plathoToncenterApiKey ?? null;
  if (key == null) {
    try { key = globalThis.localStorage?.getItem(TONCENTER_API_KEY_STORAGE_KEY) || null; } catch { key = null; }
  }
  setToncenterKeyStatusIcon(key ? 'active' : 'empty');
  if (toncenterApiKeyInput && document.activeElement !== toncenterApiKeyInput) {
    toncenterApiKeyInput.value = key ?? '';
  }
}

function applyToncenterApiKey(rawKey) {
  const key = String(rawKey ?? '').trim();
  try {
    if (key) globalThis.localStorage?.setItem(TONCENTER_API_KEY_STORAGE_KEY, key);
    else globalThis.localStorage?.removeItem(TONCENTER_API_KEY_STORAGE_KEY);
  } catch { /* ignore storage errors */ }
  globalThis.plathoToncenterApiKey = key || null;
  // The RPC transports captured the previous key at build; drop and rebuild so the new key applies now.
  globalThis.plathoTonRpcTransport = null;
  globalThis.plathoCapsuleHubRpcTransport = null;
  globalThis.plathoWalletRpcTransport = null;
  try {
    const rebuilt = globalThis.plathoTonRpcConfig ? createTonRpcTransport(globalThis.plathoTonRpcConfig) : null;
    if (rebuilt) globalThis.plathoTonRpcTransport = rebuilt;
  } catch { /* best-effort; the next read rebuilds */ }
  refreshToncenterKeyUi();
  return Boolean(key);
}

// Validate a TON Center API key with one lightweight authenticated call. toncenter returns 401
// "API key does not exist" for a bad key and 200 for a good one (verified against the live API). A
// network error / rate-limit is inconclusive — we report 'unverified' so the caller can still save
// (offline or throttled must not block the user; a wrong key just falls back to the keyless toncenter path).
async function validateToncenterApiKey(rawKey) {
  const key = String(rawKey ?? '').trim();
  if (!key) return { ok: false, reason: 'empty' };
  const controller = typeof AbortController === 'function' ? new AbortController() : null;
  const timer = controller ? setTimeout(() => controller.abort(), 10000) : null;
  try {
    const response = await fetch('https://toncenter.com/api/v3/masterchainInfo', {
      headers: { 'X-API-Key': key },
      signal: controller?.signal,
    });
    if (response.ok) return { ok: true };
    if (response.status === 401 || response.status === 403) return { ok: false, reason: 'invalid' };
    return { ok: false, reason: 'unverified' };
  } catch {
    return { ok: false, reason: 'unverified' };
  } finally {
    if (timer) clearTimeout(timer);
  }
}

// A BRAND-NEW toncenter key returns 401 "API key does not exist" for up to ~1 min after the @toncenter bot
// issues it (activation delay) — indistinguishable at the HTTP layer from a genuinely wrong key. So a 401 must
// NOT hard-block: we save the key optimistically (keyless toncenter stays the fallback meanwhile) and re-verify
// in the background across a grace window, flipping to 'key active' the moment toncenter accepts it. Only if it
// is STILL rejected after the window do we revert to keyless with a clear message (a real typo/wrong key).
let toncenterKeyReverifyTimers = [];
function clearToncenterKeyReverify() {
  for (const timer of toncenterKeyReverifyTimers) { try { clearTimeout(timer); } catch { /* best effort */ } }
  toncenterKeyReverifyTimers = [];
}
function scheduleToncenterKeyReverify(key) {
  clearToncenterKeyReverify();
  const attempt = async (isFinal) => {
    if ((globalThis.plathoToncenterApiKey ?? null) !== key) return; // superseded by a newer key / cleared
    const result = await validateToncenterApiKey(key);
    if ((globalThis.plathoToncenterApiKey ?? null) !== key) return;
    if (result.ok) {
      clearToncenterKeyReverify();
      setToncenterKeyStatusIcon('active');
      return;
    }
    if (isFinal && result.reason === 'invalid') {
      // Still rejected after the activation grace window → treat as a wrong key. Revert to keyless so a bad key
      // does not 401 every read forever; the user sees a clear, actionable status.
      applyToncenterApiKey('');
      if (toncenterApiKeyInput && document.activeElement !== toncenterApiKeyInput) toncenterApiKeyInput.value = '';
      setToncenterKeyStatusIcon('error');
    }
  };
  // THE WINDOW WAS TOO SHORT, and the first real user is how that was found. It was 25s plus a final 60s,
  // written on the belief that activation "typically lands within a minute". A genuinely valid key was still
  // 401-ing past that and got thrown away as wrong — the worst of the three outcomes: the user did nothing
  // wrong, the key was fine, and the app told them it was not.
  //
  // HOW LONG ACTIVATION ACTUALLY TAKES IS NOT KNOWN. Nobody has measured it and toncenter does not publish it,
  // so this ladder is deliberately generous rather than tuned: better to keep re-asking for ten minutes than to
  // discard a working key at sixty seconds. Each re-check is one request, so the whole window costs six.
  // If someone ever measures the real distribution, tighten it then — with the number in this comment.
  for (const at of [25_000, 60_000, 120_000, 240_000, 420_000]) {
    toncenterKeyReverifyTimers.push(setTimeout(() => { attempt(false).catch(() => {}); }, at));
  }
  toncenterKeyReverifyTimers.push(setTimeout(() => { attempt(true).catch(() => {}); }, 600_000));
}

// No Save button: validate + save when the field loses focus after an edit (or on Enter). On success shows
// 'key active'. On a 401/403 we SAVE anyway and show 'activating' + background re-verify (see above), because a
// fresh key is not active immediately. Offline/rate-limited (unverified) is also saved so the user is never
// blocked — a wrong key just falls back to the keyless toncenter path.
async function commitToncenterKeyFromInput() {
  if (!toncenterApiKeyInput) return;
  clearToncenterKeyReverify();
  const trimmed = String(toncenterApiKeyInput.value ?? '').trim();
  if (!trimmed) {
    applyToncenterApiKey('');
    return;
  }
  if (trimmed === (globalThis.plathoToncenterApiKey ?? null)) {
    refreshToncenterKeyUi();
    return;
  }
  setToncenterKeyStatusIcon('checking');
  // Keep "checking..." on screen for a perceptible beat even when the network validation returns fast,
  // so the user actually sees the key being verified before it flips to its result.
  const minCheckingVisible = new Promise((resolve) => setTimeout(resolve, 450));
  const result = await validateToncenterApiKey(trimmed);
  await minCheckingVisible;
  applyToncenterApiKey(trimmed);
  if (result.reason === 'invalid') {
    // Not a hard reject: a just-issued key is not active yet. Keep it, show activating, and re-verify.
    setToncenterKeyStatusIcon('activating');
    scheduleToncenterKeyReverify(trimmed);
  }
}

// Validate shortly after the key is pasted/edited (debounced), so the user sees "checking..." -> result
// right after pasting WITHOUT having to click away first; blur/Enter still validate immediately.
let toncenterKeyCheckTimer = null;
function scheduleToncenterKeyCheck() {
  if (toncenterKeyCheckTimer) clearTimeout(toncenterKeyCheckTimer);
  toncenterKeyCheckTimer = setTimeout(() => {
    toncenterKeyCheckTimer = null;
    commitToncenterKeyFromInput().catch((error) => console.error(error));
  }, 600);
}
toncenterApiKeyInput?.addEventListener('input', scheduleToncenterKeyCheck);
toncenterApiKeyInput?.addEventListener('change', () => {
  if (toncenterKeyCheckTimer) { clearTimeout(toncenterKeyCheckTimer); toncenterKeyCheckTimer = null; }
  commitToncenterKeyFromInput().catch((error) => console.error(error));
});
toncenterApiKeyInput?.addEventListener('keydown', (event) => {
  if (event.key === 'Enter') {
    event.preventDefault();
    toncenterApiKeyInput.blur();
  }
});

// The whole RPC-key row doubles as the "Get a key" button (opens the help modal that explains how to get a
// key and links to the @toncenter bot), EXCEPT when the click lands on the text field itself (tapping the
// field just focuses it). The explicit Get button bubbles up to this same handler.
rpcKeyRow?.addEventListener('click', (event) => {
  if (toncenterApiKeyInput
    && (event.target === toncenterApiKeyInput || toncenterApiKeyInput.contains(event.target))) {
    return;
  }
  openRpcKeyHelpDialog();
});

refreshToncenterKeyUi();
