// The reserve seller. `null` state means "not read yet / unreadable", which the buy dialog treats as UNKNOWN rather
// than as sold out — a confident "no" from a failed read is the worse of the two errors here.
let marketStabilityState = null;
let marketStabilityBuyInFlight = false;
function localStorageOrNull() {
  return typeof localStorage === 'undefined' ? null : localStorage;
}

// Scopes EVERY local key to the deployment, so a redeploy never serves the previous generation's cached state
// under the new contracts. clean-15 anchored on the Vault manifest hash; clean-17 anchors on the ProfileRegistry
// address, which is the contract the deployment is defined by — every KeyShard address derives from it, so two
// deployments cannot share it and a wrong one would already be a total identity mismatch, not a subtle cache bug.
function deploymentStorageSuffix() {
  const registry = String(appConfig.profileRegistry?.address ?? '').replace(/[^a-z0-9_-]/gi, '');
  return registry.slice(-16) || 'no-deployment';
}

function scopedStorageKey(baseKey) {
  return `${baseKey}:${deploymentStorageSuffix()}`;
}

function scopedIndexedDbName(baseName) {
  return `${baseName}.${deploymentStorageSuffix()}`;
}

// Profile-avatar media now lives in IndexedDB (per-record writes, large quota) instead of localStorage —
// whose iOS whole-store re-serialization on every write was the Vault-freeze root. Deployment-scoped (NOT
// wallet-scoped): avatars are content-addressed (sha256) and the public feed needs them before unlock.
// A single lazy DB open, cached as a promise; null if IndexedDB is unavailable (reads/writes then no-op).
const profileAvatarMediaStorePromise = (() => {
  try {
    return createProfileAvatarMediaStore({ dbName: scopedIndexedDbName('platho-profile-avatar-media-v1') }).catch(() => null);
  } catch {
    return Promise.resolve(null);
  }
})();
function profileAvatarMediaStore() {
  return profileAvatarMediaStorePromise;
}

// DURABLE cache of a post's loaded comments (assembled bodies + image data URLs), keyed `${channelId}:${entryId}`
// in IndexedDB. localStorage strips image data URLs (omitHeavyFeedMediaForPersist), so the feed cache cannot hold
// them; IndexedDB can. Survives a full reload, so re-opening a post shows its comments (WITH images) instantly
// instead of re-walking the chain + re-downloading every ~32KB comment image (owner-flagged). Reuses the media
// store shape as a generic key->JSON string KV (its LRU cap bounds growth).
const publicCommentCacheStorePromise = (() => {
  try {
    return createProfileAvatarMediaStore({ dbName: scopedIndexedDbName('platho-public-comments-v1'), cap: 50 }).catch(() => null);
  } catch {
    return Promise.resolve(null);
  }
})();

async function readCachedPublicComments(cacheKey) {
  if (!cacheKey) return null;
  try {
    const store = await publicCommentCacheStorePromise;
    const record = await store?.get(cacheKey);
    if (typeof record?.url !== 'string' || record.url.length === 0) return null;
    const parsed = JSON.parse(record.url);
    return Array.isArray(parsed?.comments) ? parsed : null;
  } catch {
    return null;
  }
}

async function writeCachedPublicComments(cacheKey, comments, parentExists, latestLink) {
  if (!cacheKey || !Array.isArray(comments)) return;
  try {
    const store = await publicCommentCacheStorePromise;
    await store?.put(cacheKey, JSON.stringify({
      comments,
      parentExists: parentExists === true,
      // The parent index's latest_entry_link at load time — the incremental cursor (append-only chain): an
      // unchanged link on the next open means ZERO body re-reads.
      latestLink: latestLink === undefined || latestLink === null ? null : String(latestLink),
    }));
  } catch {
    /* ignore (quota / unavailable) */
  }
}

// DECODED public POST image media persists as data-urls in IndexedDB — the SAME durable-media model as author
// avatars (platho-profile-avatar-media-v1, warmed before the first render) and post-detail comments
// (platho-public-comments-v1). Why a decoded store on top of the per-entry BODY cache: the localStorage feed
// cache STRIPS every image data-url on persist (omitHeavyFeedMediaForPersist — the iOS whole-store re-serialize
// freeze), so on reload a post loads image-LESS and the image previously only came back after the full serial
// chain re-walk (~a minute — owner-flagged "looks like it re-downloads from the blockchain every time"). The
// body IS a cache HIT, but the durable body cache is keyed by per-PART entry_ids that are NOT persisted, and it
// has no header_boc, so it can only be consulted from INSIDE the walk that rediscovers those ids — that walk is
// the minute. Warming THIS store before the first render restores the image in milliseconds with zero chain
// reads, exactly like the avatar warm. Keyed by post.id (stable, persisted, present by construction); value =
// JSON {imageUrl, blocks} — the exact render-consumed media, overlaid onto the stripped light item (chain posts
// are immutable, so captured media is authoritative forever). Deployment-scoped (public, pre-unlock), LRU-capped
// (eviction just re-decodes from the body cache on the next sync).
const publicPostMediaStorePromise = (() => {
  try {
    return createProfileAvatarMediaStore({ dbName: scopedIndexedDbName('platho-public-post-media-v1'), cap: 400 }).catch(() => null);
  } catch {
    return Promise.resolve(null);
  }
})();
function publicPostMediaStore() {
  return publicPostMediaStorePromise;
}

// The heavy render-consumed image media a post carries (its OWN image — the author avatar has its own store).
// Returns null when the post has no image. Keeps the FULL blocks array so a text+image post restores the image
// in its original position among text blocks; imageUrl covers the legacy image-only post shape.
function publicPostRenderableImageMedia(post) {
  if (!post || typeof post !== 'object') return null;
  const imageUrl = typeof post.imageUrl === 'string' && post.imageUrl.length > 0 ? post.imageUrl : null;
  const hasImageBlock = Array.isArray(post.blocks)
    && post.blocks.some((block) => block?.type === 'image' && typeof block.url === 'string' && block.url.length > 0);
  if (!imageUrl && !hasImageBlock) return null;
  return { imageUrl, blocks: Array.isArray(post.blocks) ? post.blocks : null };
}

function publicPostCacheKey(post) {
  return typeof post?.id === 'string' && post.id.length > 0 ? post.id : null;
}

// Overlay durable media back onto a stripped light item. Only fills what is MISSING so a freshly-synced post
// that already carries its image is never churned. Returns whether anything changed.
function applyPublicPostMediaRecord(post, media) {
  if (!post || typeof post !== 'object' || !media || typeof media !== 'object') return false;
  if (publicPostRenderableImageMedia(post)) return false; // already has a renderable image — leave it
  let changed = false;
  if (Array.isArray(media.blocks)
    && media.blocks.some((block) => block?.type === 'image' && typeof block.url === 'string' && block.url.length > 0)) {
    post.blocks = media.blocks;
    changed = true;
  }
  if ((typeof post.imageUrl !== 'string' || post.imageUrl.length === 0)
    && typeof media.imageUrl === 'string' && media.imageUrl.length > 0) {
    post.imageUrl = media.imageUrl;
    changed = true;
  }
  return changed;
}

function eachCachedPublicPost(callback) {
  for (const record of Object.values(publicChannelFeedCache ?? {})) {
    const feed = record?.feed ?? record;
    const posts = Array.isArray(feed?.posts) ? feed.posts : (Array.isArray(feed) ? feed : []);
    for (const post of posts) callback(post);
  }
}

// LOAD-TIME hydration: fill post images from IndexedDB into the in-memory feed cache BEFORE the first render,
// so a reloaded post shows its image in ms without waiting for the serial chain walk. Mutates cache posts in
// place (rebuildThreadsFromPublicSubscriptions then reads them). Returns whether anything changed.
async function warmPublicPostImagesFromCache() {
  try {
    const pending = [];
    eachCachedPublicPost((post) => {
      if (publicPostRenderableImageMedia(post)) return; // already carries its image
      const key = publicPostCacheKey(post);
      if (key) pending.push({ post, key });
    });
    if (pending.length === 0) return false;
    const store = await publicPostMediaStore();
    if (!store) return false;
    const raws = await store.getMany(pending.map((entry) => entry.key));
    let changed = false;
    for (const { post, key } of pending) {
      const raw = raws.get(key);
      if (!raw) continue;
      let media = null;
      try { media = JSON.parse(raw); } catch { media = null; }
      if (applyPublicPostMediaRecord(post, media)) changed = true;
    }
    return changed;
  } catch {
    return false;
  }
}

// Media is immutable per post → persist a given post.id's media at most once per session.
const persistedPublicPostMediaKeys = new Set();
function schedulePublicPostImageMediaPersist() {
  setTimeout(() => { void persistPublicPostImageMedia(); }, 0);
}
async function persistPublicPostImageMedia() {
  try {
    let store = null;
    const targets = [];
    eachCachedPublicPost((post) => {
      const key = publicPostCacheKey(post);
      if (!key || persistedPublicPostMediaKeys.has(key)) return;
      const media = publicPostRenderableImageMedia(post);
      if (!media) return; // no image yet — leave the key unmarked so a later sync persists it
      targets.push({ key, media });
    });
    if (targets.length === 0) return;
    store = await publicPostMediaStore();
    if (!store) return;
    for (const { key, media } of targets) {
      if (persistedPublicPostMediaKeys.has(key)) continue;
      await store.put(key, JSON.stringify(media));
      persistedPublicPostMediaKeys.add(key);
    }
  } catch {
    /* best effort (quota / unavailable) */
  }
}

// Single choke point for persisting the public feed cache: the light text/metadata goes to localStorage (image
// data-urls stripped to dodge the iOS freeze) and — SYMMETRICALLY — the heavy decoded image media goes to
// IndexedDB, so the strip never costs a chain re-walk on reload. Every feed-cache write goes through here.
function commitPublicChannelFeedCache() {
  writePublicChannelFeedCache(publicChannelStorage(), publicChannelFeedCache);
  schedulePublicPostImageMediaPersist();
}

function walletIndexedDbSuffix(walletAddress = plathoWallet?.address) {
  if (!walletAddress) return 'wallet-locked';
  try {
    const parsed = parseTonAddress(walletAddress).raw;
    return String(parsed).replace(/[^a-z0-9_-]/gi, '').slice(-18) || 'wallet-unknown';
  } catch {
    return String(walletAddress).replace(/[^a-z0-9_-]/gi, '').slice(-18) || 'wallet-unknown';
  }
}

function walletScopedIndexedDbName(baseName, walletAddress = plathoWallet?.address) {
  return `${scopedIndexedDbName(baseName)}.${walletIndexedDbSuffix(walletAddress)}`;
}

function currentMessageHistoryDbName(walletAddress = plathoWallet?.address) {
  return walletScopedIndexedDbName(LEGACY_MESSAGE_HISTORY_DB_NAME, walletAddress);
}

function currentReplayDbName(walletAddress = plathoWallet?.address) {
  return walletScopedIndexedDbName(LEGACY_REPLAY_DB_NAME, walletAddress);
}

// The INTRO lane's replay guard gets its OWN database, deliberately not the one above. The private-capsule guard keys
// on capsule ids; this one keys on intro nonces. Sharing a keyspace would let an accidental collision mark a genuine
// first contact as already-seen and drop it silently — the one failure this lane cannot afford, since an INTRO is
// paid for and arrives once.
function currentIntroReplayDbName(walletAddress = plathoWallet?.address) {
  return walletScopedIndexedDbName('platho-intro-replay-v1', walletAddress);
}

// The direct-pay CONV lane's sealed K_root store lives in a WALLET-SCOPED IndexedDB so one wallet's conversation keys
// never bleed into another's ([[cross-wallet-identity-bleed]]); the seal key is device-local within that DB.
function currentConvKeyDbName(walletAddress = plathoWallet?.address) {
  return walletScopedIndexedDbName('platho-conv-keys-v1', walletAddress);
}

function deploymentScopedStorage(storage, scopedKeys) {
  if (!storage) return storage;
  const keyFor = (key) => (scopedKeys.has(key) ? scopedStorageKey(key) : key);
  return {
    getItem(key) {
      return storage.getItem(keyFor(key));
    },
    setItem(key, value) {
      return storage.setItem(keyFor(key), value);
    },
    removeItem(key) {
      return storage.removeItem(keyFor(key));
    },
  };
}

const PUBLIC_CHANNEL_STORAGE_KEYS = new Set([
  PUBLIC_CHANNEL_SUBSCRIPTIONS_KEY,
  PUBLIC_CHANNEL_FEED_CACHE_KEY,
]);

function publicChannelStorage() {
  return deploymentScopedStorage(localStorageOrNull(), PUBLIC_CHANNEL_STORAGE_KEYS);
}

function rememberLocalStoragePersistenceStatus(status) {
  try {
    localStorageOrNull()?.setItem(PLATHO_STORAGE_PERSISTENCE_KEY, String(status));
  } catch {
    // Storage persistence status is advisory; wallet writes are checked separately.
  }
}

async function requestPersistentLocalStorage() {
  const storageManager = navigator.storage;
  if (!storageManager?.persist) {
    rememberLocalStoragePersistenceStatus('unsupported');
    return 'unsupported';
  }
  try {
    const alreadyPersisted = typeof storageManager.persisted === 'function'
      ? await storageManager.persisted()
      : false;
    if (alreadyPersisted) {
      rememberLocalStoragePersistenceStatus('granted');
      return 'granted';
    }
    const granted = await storageManager.persist();
    rememberLocalStoragePersistenceStatus(granted ? 'granted' : 'denied');
    return granted ? 'granted' : 'denied';
  } catch (error) {
    console.error(error);
    rememberLocalStoragePersistenceStatus('error');
    return 'error';
  }
}

function isStandaloneApp() {
  return window.matchMedia?.('(display-mode: standalone)')?.matches || window.navigator?.standalone === true;
}

function isIosDevice() {
  const ua = navigator.userAgent || '';
  return /iPad|iPhone|iPod/.test(ua) || (navigator.platform === 'MacIntel' && Number(navigator.maxTouchPoints || 0) > 1);
}

function installActionState() {
  if (isStandaloneApp()) return 'installed';
  if (installedRelatedPwaDetected) return 'open-in-app';
  if (deferredInstallPrompt) return 'prompt';
  return isIosDevice() ? 'ios-instructions' : 'instructions';
}

function setInstallSteps(steps = []) {
  if (!installSteps) return;
  installSteps.replaceChildren();
  if (!steps.length) {
    installSteps.hidden = true;
    return;
  }
  steps.forEach((text) => {
    const item = document.createElement('li');
    item.textContent = text;
    installSteps.append(item);
  });
  installSteps.hidden = false;
}

// EVERY word the install surfaces say, resolved from one state. [OWNER 2026-08-13] The install invitation became a
// quick-start step as well as a modal, and a second surface writing its own copy is how two screens start disagreeing
// about what "install" even means on this device. One definition, two readers — the dialog and the wizard step.
function installCopyForState(state = installActionState()) {
  return {
    state,
    buttonLabel: state === 'prompt'
      ? t('install.installPlatho')
      : state === 'open-in-app'
      ? t('install.openPlathoApp')
      : state === 'ios-instructions'
      ? t('install.howToInstallIphone')
      : t('install.openOrInstall'),
    title: state === 'prompt'
      ? t('install.installPlatho')
      : state === 'open-in-app'
      ? t('install.openPlathoApp')
      : state === 'ios-instructions'
      ? t('install.installOnIphone')
      : t('install.openOrInstall'),
    action: state === 'prompt' ? t('install.install') : t('install.gotIt'),
    lead: state === 'open-in-app'
      ? t('install.leadOpenInApp')
      : state === 'ios-instructions'
      ? t('install.leadIos')
      : state === 'instructions'
      ? t('install.leadInstructions')
      : t('install.leadPrompt'),
    body: state === 'open-in-app'
      ? t('install.bodyOpenInApp')
      : state === 'ios-instructions'
      ? t('install.bodyIos')
      : state === 'instructions'
      ? t('install.bodyInstructions')
      : t('install.bodyPrompt'),
    steps: state === 'ios-instructions'
      ? [t('install.iosStep1'), t('install.iosStep2'), t('install.iosStep3'), t('install.iosStep4')]
      : [],
    help: state === 'installed'
      ? t('install.helpInstalled')
      : state === 'open-in-app'
      ? t('install.helpOpenInApp')
      : state === 'ios-instructions'
      ? t('install.helpIos')
      : state === 'prompt'
      ? t('install.helpPrompt')
      : installHelpText(),
  };
}

function refreshInstallButtons() {
  if (isTelegramEnv()) {
    // PWA install is meaningless inside Telegram; keep every install affordance hidden.
    installButtons.forEach((button) => button.toggleAttribute('hidden', true));
    return;
  }
  const copy = installCopyForState();
  const state = copy.state;
  const canInstall = state !== 'installed';
  installButtons.forEach((button) => {
    button.toggleAttribute('hidden', !canInstall);
    button.setAttribute('aria-label', copy.buttonLabel);
    button.title = copy.buttonLabel;
    const icon = button.querySelector('.icon');
    icon?.classList.toggle('icon-install', state === 'prompt');
    icon?.classList.toggle('icon-open-app', state !== 'prompt');
  });
  if (installTitle) installTitle.textContent = copy.title;
  if (installConfirmButton) installConfirmButton.textContent = copy.action;
  if (installDismissButton) {
    installDismissButton.textContent = t('install.notNow');
    installDismissButton.hidden = state !== 'prompt';
  }
  if (installLead) installLead.textContent = copy.lead;
  if (installBody) installBody.textContent = copy.body;
  setInstallSteps(copy.steps);
  if (installHelp) installHelp.textContent = copy.help;
  // NOT refreshQuickStartInstallStep() from here, however tempting. This function RUNS AT MODULE TOP LEVEL (the
  // bootstrap call below the beforeinstallprompt listeners), and every piece of quick-start state it would touch —
  // quickStartStepsView, QUICK_START_STEPS, quickStartStepIndex — is declared several hundred lines further down.
  // Reading a `let`/`const` before its declaration is a TDZ ReferenceError at top level, which aborts the whole
  // script and the app never boots. The two events that actually change the install state call it themselves.
}

function installPromptDismissed() {
  return localStorageOrNull()?.getItem(INSTALL_PROMPT_DISMISSED_STORAGE_KEY) === '1';
}

function markInstallPromptDismissed() {
  localStorageOrNull()?.setItem(INSTALL_PROMPT_DISMISSED_STORAGE_KEY, '1');
}

// [OWNER 2026-08-09] The owner reported dialogs climbing on top of each other. They did: this one and the
// activation welcome are SEPARATE elements, each showing itself with no idea the other exists, so the order was
// whichever fired first — the install card appeared, then "Account activated" landed on top of it seconds later.
//
// One queue instead of two independent shows. The install prompt is the LOWEST priority thing the app ever says:
// it is an invitation, not news, so it waits for anything else to finish and is re-offered when the way is clear.
let installPromptDeferred = false;

function blockingDialogOpen() {
  return Boolean(activeActionDialog)
    || Boolean(quickStartDialog && !quickStartDialog.hidden)
    || Boolean(activationWelcomeDialog && !activationWelcomeDialog.hidden);
}

function openInstallDialogIfUseful() {
  if (isTelegramEnv()) return;
  if (!installDialog || installPromptDismissed() || isStandaloneApp()) return;
  if (blockingDialogOpen()) {
    // Remembered, not dropped: the moment that dialog closes this is offered again, so the invitation is delayed
    // rather than lost. Without the memory, activating an account would silently cost the user the install prompt.
    installPromptDeferred = true;
    return;
  }
  installPromptDeferred = false;
  installDialog.classList.remove('is-closing'); installDialog.hidden = false;
  refreshInstallButtons();
}

/** Called wherever a higher-priority dialog closes. Re-offers the install card only if it was actually deferred. */
function offerDeferredInstallPrompt() {
  if (!installPromptDeferred) return;
  installPromptDeferred = false;
  openInstallDialogIfUseful();
}

/**
 * Forget a deferred invitation instead of releasing it. [OWNER 2026-08-13] The quick-start now ENDS on an install
 * step of its own, so the modal that used to pop seconds after the wizard closed is the same invitation a second
 * time — "the last step is a modal, not in the wizard's style" was the complaint, and answering it with a styled
 * step plus the old modal would only have made it twice as loud.
 */
function dropDeferredInstallPrompt() {
  installPromptDeferred = false;
}

function closeInstallDialog({ dismissed = true } = {}) {
  if (dismissed) markInstallPromptDismissed();
  hideDialogAnimated(installDialog);
}

let composerViewportMaxHeight = 0; // largest visible viewport height seen AT THE CURRENT WIDTH = the no-soft-keyboard baseline
let composerViewportBaselineWidth = 0; // width the baseline was captured at; a width change (orientation/resize) re-baselines
let composerKeyboardWasOpen = false; // last-seen soft-keyboard state, to detect the up->down (dismissed) transition
// The soft keyboard shrinks the visual viewport; "open" = the current visible height is meaningfully below the baseline.
// ~150px filters browser-chrome (address bar) changes (~50-120px) from a real keyboard (~250px+). Used to (a) re-focus
// on maximize only while the keyboard is UP (typing), and (b) detect when it is DISMISSED (see the hide-blur below).
function composerKeyboardLikelyOpen() {
  const viewport = window.visualViewport;
  if (!viewport || composerViewportMaxHeight <= 0) return false;
  return (composerViewportMaxHeight - viewport.height) > 150;
}

// Blur the focused composer editor the moment the soft keyboard is DISMISSED. Root cause of the mobile keyboard re-pop:
// hiding the keyboard with its own button leaves the field FOCUSED (caret visible) but the keyboard down, and then ANY
// geometry change (maximize / restore, and other reflows) makes a touch browser re-show the keyboard for that still-
// focused editable. Blurring on dismissal eliminates that "focused-but-keyboard-hidden" state at the source, so nothing
// can re-pop it. Only on a coarse-pointer (touch) device with a real soft keyboard; desktop/mouse never blurs (no soft
// keyboard, and a fine-pointer window resize must not drop the caret). Scoped to .composer-input so other fields are
// untouched. keyboardWasOpen tracks the last state so this fires exactly on the up->down edge, not on every VV tick.
function composerHandleKeyboardVisibility() {
  const nowOpen = composerKeyboardLikelyOpen();
  if (composerKeyboardWasOpen && !nowOpen) {
    const active = document.activeElement;
    const coarse = !!(window.matchMedia && window.matchMedia('(pointer: coarse)').matches);
    if (coarse && active && active.classList && active.classList.contains('composer-input')) active.blur();
  }
  composerKeyboardWasOpen = nowOpen;
}

// A scroll-cancelling helper stood here (1.0.28) and is GONE. It watched for a scrolled document and put it back
// to zero, which the owner identified on sight as a hack: undoing his drag is literally what it did, hence the
// snap-back when he let go. Its successor, driving the shell's `top` from visualViewport.offsetTop (1.0.29), was
// worse — offsetTop changes every scroll frame while `top` is recomputed from an event handler, so the whole
// interface shook, and the maximized composer (fixed against the same viewport) came apart.
//
// Both existed to compensate for the shell following the keyboard's height on iOS, and that is the thing that has
// been removed instead. See the note on .app-shell in styles.css.

/**
 * While the composer is open FULL SCREEN, re-read the viewport every frame instead of waiting to be told.
 *
 * [OWNER 2026-08-14] "Nail the composer down so it stops shuddering." The jitter is a reporting delay, not a layout
 * bug: the browser announces a viewport change AFTER the frame that moved it, so a composer positioned from the
 * event handler is always one frame behind the finger — visible as a shudder on every scroll.
 *
 * A frame loop has nothing to be late for. It runs ONLY while a maximized composer is on screen, which is the one
 * moment this matters, and stops by itself the instant it closes — so it costs nothing the rest of the time.
 * Writes only when the number actually changed, so an idle frame does no work at all.
 */
let viewportVarsFrame = 0;
let viewportVarsLastGap = -1;

function viewportVarsLoopWanted() {
  // [OWNER 2026-08-14] Scoping this to the MAXIMIZED composer was too narrow — the shudder is there with the
  // ordinary one too, because it is the whole shell that follows the visible area now. The real condition is
  // simply "the visible area is not the whole page", i.e. the keyboard is up. Off the rest of the time, which is
  // every desktop, every Android, and every phone with the keyboard down.
  const viewport = window.visualViewport;
  if (!viewport) return false;
  // Height only, matching the gap it exists to keep fresh: with offsetTop in here the loop would also switch on
  // for a plain drag, which is exactly the state it must NOT react to.
  return Math.round(window.innerHeight - viewport.height) > 0
    || Boolean(document.querySelector('.composer.is-maximized'));
}

/**
 * How much of the page the keyboard covers, written to CSS — and the ONE place that writes it.
 *
 * THE VALUE IS LATCHED, NOT TRACKED. The keyboard's height is read ONCE, when it appears, and held until it goes
 * away. Nothing in between changes it.
 *
 * [OWNER 2026-08-14] Two attempts got this wrong in the same way, and his description of the second named the
 * mechanism exactly: "drag down and it shudders, then stops, and no matter how far down you drag it never shudders
 * again — but now it shudders upward." That is a THRESHOLD, and it was mine. iOS wobbles the visible height by a few
 * per frame during a drag; answering every wobble was the first shudder, so a 32px threshold was added — which
 * did not smooth anything, it ACCUMULATED. The difference crept up under the threshold in silence and then landed
 * all at once as a jump, and reversing direction started the same climb over again. Fine shudder became rare
 * lurches, alternating by direction, which is precisely what he saw.
 *
 * There is nothing to track. A keyboard is open or it is not; while it is open its height is a constant, and any
 * frame-to-frame variation in the reading is noise about a fixed thing. So: latch on open, release on close, and
 * re-latch only for a change far too large to be noise (switching to the emoji keyboard, a language with a
 * suggestion strip) — a jump there is correct, because the keyboard really did change size.
 */
const KEYBOARD_PRESENT_PX = 120;   // below this the visible area is merely inset (browser chrome), not covered
// HOW LONG A FINGER MUST SIT STILL BEFORE THE TOUCH BELONGS TO TEXT, NOT TO THE PAGE. Every iOS selection gesture —
// the loupe, the word grab, both grips — begins with a deliberate hold; a drag meant to move the page begins
// moving at once. So the hold, not the presence of a selection, is what tells them apart.
const EDITABLE_SELECTION_HOLD_MS = 350;
const KEYBOARD_RESIZE_PX = 60;     // a real change of keyboard, not the reading wobbling about one
let keyboardGapLatched = 0;

function writeVisibleBottomGap() {
  const viewport = window.visualViewport;
  const raw = Math.max(0, Math.round(window.innerHeight - (viewport?.height ?? window.innerHeight)));
  let next = keyboardGapLatched;
  if (raw < KEYBOARD_PRESENT_PX) {
    next = 0;                                             // gone: sit flush again
  } else if (keyboardGapLatched === 0) {
    next = raw;                                           // just appeared: take its height once
  } else if (Math.abs(raw - keyboardGapLatched) >= KEYBOARD_RESIZE_PX) {
    next = raw;                                           // genuinely a different keyboard
  }
  if (next === keyboardGapLatched) return false;
  keyboardGapLatched = next;
  document.documentElement.style.setProperty('--app-viewport-bottom-gap', `${next}px`);
  return true;   // the sizes derived from it are now stale — see the frame loop and syncViewportCssVars
}

// NOTHING HERE CORRECTS A POSITION, and that is the conclusion of the whole exercise.
//
// [MEASURED on the owner's iPhone, keyboard OPEN — the reading twelve attempts were made without] innerHeight 755,
// visible height 438, keyboard 317, offsetTop 0, scrollY 0, and a fixed element anchored at the top of the page
// sitting at 0: exactly where it belongs. The visible area does not slide when the keyboard opens. It shrinks from
// the bottom, and a top-anchored fixed element is already correct.
//
// Every correction attempted here — the bottom pinned to the keyboard gap, `top` driven from offsetTop, the
// document scrolled back — was moving something that was not out of place, so each one displaced the composer by
// exactly the amount it "corrected". The only number the layout needs is the visible HEIGHT.

/**
 * Refuse the drag that carries the whole app off the top of the screen while the keyboard is up.
 *
 * THIS IS NOT A WORKAROUND FOR A BUG OF OURS. It is one of the two known ways around an open WebKit defect, and
 * the owner was right to make me go and check which. What the sources say, so nobody re-litigates it:
 *
 *   - WebKit bug 191204, "position:fixed and viewport units are unusable while the software keyboard is up",
 *     filed 2018-11-02 and STILL OPEN (activity through 2025). When the keyboard appears, Safari does not resize
 *     the layout viewport the way Chrome on Android does; it adds a separate scrollable layer over the page. In
 *     that state position:fixed stops being fixed and rides up with the drag.
 *   - `interactive-widget=resizes-content` — the viewport-meta switch that makes Android shrink the LAYOUT
 *     viewport, which is the whole reason this works there — is Chrome 108+ and Firefox 132+, and WebKit has not
 *     shipped it (standards-positions issue 65 is still open as of iOS 26).
 *
 * Which is why "just make the page shorter" could not work, and did not: the layer being scrolled is not the
 * document, so no height on html/body has any authority over it. He asked the right question anyway, because the
 * measurement I answered it with was wrong — see the overlay for what clientHeight really reports on <html>.
 *
 * A scroll listener that puts the offset back cannot work either, and was tried: iOS scrolls off the main thread,
 * so the correction lands only after the finger lifts — exactly the "drag it up, let go, it jumps back" he saw.
 *
 * Of the two published cures — refuse the gesture, or make sure the inner scroller always has slack so iOS never
 * escalates the gesture to the page — the second buys its result with a screenful of dead space inside the text
 * field, which is a visible lie about how much you have written. So: refuse it. Only while the keyboard is up,
 * and only for gestures that start outside a real scroller, so every list, feed and message strip is untouched.
 *
 * THE DECISION IS MADE ONCE PER GESTURE, at touchstart. Deciding it per touchmove meant a getComputedStyle for
 * every ancestor of the target sixty times a second, and this app already has one device that freezes when the
 * main thread is asked for too much (iPhone SE2). touchmove then does nothing but honour the flag.
 */
let pageDragRefusalArmed = false;

/**
 * Does the field that has focus hold a selection with TWO ENDS — i.e. is there something for the grips to move?
 *
 * document.getSelection() is the whole story for a contenteditable. An <input>/<textarea> keeps its selection to
 * itself and answers through selectionStart/selectionEnd instead — and throws for the input types that have no
 * selection at all (number, email), hence the guard. Read at touchstart only, so it costs one property read per
 * gesture and nothing per frame.
 */
let pageDragRefusalStartedAt = 0;
let pageDragRefusalInText = false;

/**
 * DID THIS TOUCH LAND IN SOMETHING THE USER CAN SELECT TEXT IN?
 *
 * Read from the TARGET, not from document.activeElement: the loupe and the grips are worked with the field already
 * focused, but a tap that lands on a text node inside a contenteditable reports that node's element, and focus can
 * still be moving. isContentEditable is inherited, so this answers for the composer's inner blocks too.
 */
function touchBeganInEditable(event) {
  const target = event.target instanceof Element ? event.target : null;
  if (!target) return false;
  return Boolean(target.closest('input, textarea, [contenteditable]')) || target.isContentEditable;
}

function focusedEditableHoldsLiveSelection() {
  const active = document.activeElement;
  if (!(active instanceof Element)) return false;
  if (active.tagName === 'INPUT' || active.tagName === 'TEXTAREA') {
    try { return active.selectionEnd > active.selectionStart; } catch { return false; }
  }
  if (!active.isContentEditable) return false;
  const selection = document.getSelection?.();
  return Boolean(selection && selection.rangeCount > 0 && !selection.isCollapsed);
}

function armPageDragRefusal(event) {
  pageDragRefusalArmed = false;
  pageDragRefusalStartedAt = Date.now();
  pageDragRefusalInText = touchBeganInEditable(event);
  const viewport = window.visualViewport;
  if (!viewport) return;
  if (Math.round(window.innerHeight - viewport.height) < KEYBOARD_PRESENT_PX) return;   // no keyboard, no lock
  if (event.touches && event.touches.length > 1) return;                                // pinch is not ours
  // THE GRIPS ARE A DRAG TOO, and the note below used to say otherwise. [OWNER 2026-08-24: "the text does get
  // selected, but you cannot widen it using the grips"] — on the iPhone a long press still selects, but neither
  // grip will widen the selection. "Selection on iOS starts from a long press, not a drag, so nothing is taken away" was
  // half true: it covers MAKING a selection and stops there. EXTENDING one is a drag, and WebKit defers its
  // handle gesture until the page has said whether it prevents the touchmove — we prevent it, so the gesture is
  // failed and the grip never moves. That is also why making a selection still works: the long press is decided
  // by a timer, and WebKit hands us a touchcancel the moment it wins, so no touchmove of ours is in the way.
  //
  // THIS IS NOT THE OLD BLANKET EXEMPTION FOR EDITABLES [OWNER 2026-08-15: "you can still pull the page out by
  // the text field"], which waved a field through for BEING a field and left the one surface the keyboard is open
  // for handing its gestures to the browser. The condition here is a LIVE selection — two ends, in the field that
  // has focus — which exists only in the seconds after the user has selected something, and is what the grips
  // need. The honest cost: for those seconds a drag inside that field can carry the page again. A selection that
  // can never be widened is the worse of the two, and the next tap collapses this one.
  if (focusedEditableHoldsLiveSelection()) return;
  // Walk up looking for something that can actually consume this gesture. A scroller that is ALREADY at its limit
  // still counts: letting the browser rubber-band a list is fine, it is the PAGE that must not move.
  for (let node = event.target instanceof Element ? event.target : null; node && node !== document.body; node = node.parentElement) {
    const style = getComputedStyle(node);
    const scrollable = /(auto|scroll)/.test(`${style.overflowY} ${style.overflow}`);
    if (scrollable && node.scrollHeight > node.clientHeight) return;
    // NO BLANKET EXEMPTION FOR TEXT FIELDS. [OWNER 2026-08-15] "You can still pull the page out by the text
    // field. Dragging anywhere else and it does not move." One line here used to wave through anything editable, on
    // the theory that a drag there belongs to the caret — and the composer IS an editable, so the one surface the
    // keyboard is open for was the one still handing the gesture to the browser. That is also textbook for the
    // WebKit defect above: the escalation happens precisely when the element under the finger has nothing to
    // scroll, which is what an editable holding one line of text is.
    // Editables are covered by the same rule as everything else: a field with more text than fits scrolls (the
    // check above sees it), and one that fits has nothing to scroll and must not move the page instead. This once
    // ended "selection on iOS starts from a long press, not a drag, so nothing is taken away" — which was true of
    // MAKING a selection and false of extending one. The exception that answers it is above, not here.
  }
  pageDragRefusalArmed = true;
}

function refusePageDragWhileKeyboardIsUp(event) {
  if (!pageDragRefusalArmed) return;
  if (event.touches && event.touches.length > 1) { pageDragRefusalArmed = false; return; }   // became a pinch
  // A HELD FINGER IN A TEXT FIELD IS SELECTING [OWNER 2026-08-24: "on the iPhone I cannot select text in the
  // composer by the standard means — something intercepts it and resets it"]. The exemption used to require a LIVE
  // selection, i.e. two ends already placed. But on iOS the gesture that PLACES them starts with the loupe, and the
  // loupe carries a COLLAPSED caret — no second end, no exemption, and the very move that would make a selection
  // was the one refused. The hold answers for all of it: loupe, word grab and both grips begin with one, a page
  // drag never does, and an immediate drag from the field stays refused [OWNER 2026-08-15: "you can still pull the
  // page out by the text field"].
  if (pageDragRefusalInText && Date.now() - pageDragRefusalStartedAt >= EDITABLE_SELECTION_HOLD_MS) {
    pageDragRefusalArmed = false;
    return;
  }
  event.preventDefault();
}

// A REFUSAL BELONGS TO THE GESTURE THAT ARMED IT. The flag was raised by a touchstart and nothing lowered it, so
// it survived into whatever came next — and what comes next on iOS is not always a touchstart of its own: WebKit
// sends touchcancel the moment a native gesture (the selection assistant, above all) claims the touch, and
// anything delivered after that is no longer ours to refuse. Same defect as the grips, reached the other way.
function releasePageDragRefusal() {
  pageDragRefusalArmed = false;
}

/**
 * IS THE PAGE CARRYING AN OFFSET THAT ONLY THE KEYBOARD COULD HAVE GIVEN IT?
 *
 * [OWNER 2026-08-24: an empty dark strip along the bottom, BELOW the tab bar, appearing "sometimes" when the
 * message field is tapped.] The strip is bare <body> — the shell is position:fixed against the LAYOUT viewport
 * (WebKit 191204: a fixed element does not stay fixed while the keyboard is up), so a page scrolled by N draws
 * the whole shell N higher and leaves N pixels of nothing under the bar. It is the same defect as "the interface
 * flies up", measured small: MAX scroll 386, off 386, shell up 386 were one event, and any part of it left
 * behind is a proportional strip.
 *
 * Nothing here fights a scroll the user asked for, and there cannot be one: html/body are the visible height
 * with overflow hidden and overscroll-behavior none, and a finger cannot move the page either (see
 * armPageDragRefusal). While the keyboard is up, a non-zero offset is the system's own reveal-the-field scroll,
 * which was correct when it was decided and stale one frame later. That is the whole difference from the 1.0.28
 * hack this file threw out: that one hung off the scroll event and undid the owner's drag; this one is bounded
 * by the CONDITION, and in that condition the page has no legitimate offset to defend.
 */
function iosPageIsCarryingTheKeyboardsScroll() {
  if (!isIosDevice()) return false;                                                      // only WebKit does this
  if ((window.scrollY || document.documentElement.scrollTop || 0) === 0) return false;
  const viewport = window.visualViewport;
  return Boolean(viewport) && Math.round(window.innerHeight - viewport.height) >= KEYBOARD_PRESENT_PX;
}

function keepViewportVarsLiveWhileComposerIsOpen() {
  if (!viewportVarsLoopWanted()) {
    if (viewportVarsFrame) { cancelAnimationFrame(viewportVarsFrame); viewportVarsFrame = 0; }
    return;
  }
  if (viewportVarsFrame) return;
  const tick = () => {
    if (!viewportVarsLoopWanted()) { viewportVarsFrame = 0; return; }
    // THE PAGE STAYS AT THE TOP FOR AS LONG AS THE KEYBOARD IS UP, and this is where that costs nothing: the loop
    // already runs for exactly that period. holdPageAtTopWhileKeyboardArrives covers the ARRIVAL — it is armed by
    // a focus and expires on a clock (900ms), which is a guess at how long iOS takes — and the guess is the hole:
    // the reveal-the-field scroll can also land later (the caret moving while typing, a keyboard that changes
    // size, a return to a still-focused field with no focusin). A deadline cannot cover those. The condition can.
    if (iosPageIsCarryingTheKeyboardsScroll()) window.scrollTo(0, 0);
    // The SIZES are recomputed only when the latch moved — i.e. the keyboard appeared, left, or changed into a
    // different one. Every other frame does nothing but the comparison, which is the point: a keyboard that is
    // simply OPEN must produce no size writes at all, or they breathe with the noise and that IS the shudder.
    if (writeVisibleBottomGap()) syncViewportCssVars();
    viewportVarsFrame = requestAnimationFrame(tick);
  };
  viewportVarsFrame = requestAnimationFrame(tick);
}

/**
 * THE KEYBOARD MUST NOT SWALLOW THE END OF THE THREAD [OWNER 2026-08-23: "it really annoys me that when I tap the
 * composer, the keyboard that slides up covers the last messages — they should scroll, so I can see what I am even
 * replying to"], with a screenshot showing the two newest messages cut off above the composer.
 *
 * The shell already shrinks to the visible height when the keyboard opens, which is why the composer stays above
 * it. What nothing did was move the SCROLLER: a reader sitting at the end of a conversation loses exactly a
 * keyboard's worth of it, because the content keeps the scroll offset it had when the box was taller.
 *
 * Only for a reader who WAS at the end. Someone who scrolled up to read history and then tapped the composer to
 * answer something specific must keep their place — being thrown to the newest message would be the same defect
 * pointing the other way.
 */
function pinOpenThreadsToEndAfterViewportChange() {
  requestAnimationFrame(() => {   // after the new height has been laid out, or scrollHeight is the old one
    if (conversationStickToBottom && messageStrip && appShell?.dataset.view === 'chats') {
      messageStrip.scrollTop = messageStrip.scrollHeight;
    }
    if (publicPostDetailStickToBottom && publicPostDetailOpen && publicPostDetailBody) {
      publicPostDetailBody.scrollTop = publicPostDetailBody.scrollHeight;
    }
  });
}

/**
 * FOCUS A COMPOSER FIELD WITHOUT LETTING THE PAGE MOVE.
 *
 * [OWNER 2026-08-24: "there is still an iPhone bug. We treated it and thought it was cured, but it still shows up
 * sometimes — the interface flies up, it accounts for the keyboard the way Android does, and on iPhone that must not
 * be done. We fixed it, but it looks like some branch was missed."] Their memory is exact, and so is the miss: the
 * cure is focus({ preventScroll: true }), and it had been applied in ONE place — the maximize toggle — while the
 * other sixteen composer focus calls used a plain focus().
 *
 * A plain focus() asks the browser to bring the field into view. iOS obliges by scrolling the PAGE, and it decides
 * that at the moment of focus, when the shell is still full height and the composer is sitting exactly where the
 * keyboard is about to be. One frame later the shell shrinks to the visible height and the composer is near the
 * top — but the page scroll it was given stays, and that is the interface flying up. The app already places the
 * composer above the keyboard itself, so the browser's help is not needed anywhere, ever.
 *
 * One function so there cannot be a seventeenth branch that forgets. Also carries the disabled check every caller
 * was repeating.
 */
function focusComposerField(field) {
  if (!field || field.disabled) return;
  field.focus({ preventScroll: true });
}

/**
 * AND THE OTHER HALF — THE TAP, which is the one the owner actually sees.
 *
 * [OWNER 2026-08-24, on being shown the above: "toggleComposerMaximize is the composer's maximize, isn't it? But
 * our problem was that I TAP the composer and the interface flies up, and that is where we fixed it — you are
 * talking about the maximize, not the place with the problem."] Exactly right, and preventScroll cannot help
 * there: on a tap nothing of ours calls focus() at all. The browser focuses the field itself, and iOS then scrolls
 * the PAGE to bring it into view — the app ends up shoved off the top with the composer at the screen's edge.
 *
 * There WAS a cure for it: the single scrollTo(0, 0) in syncViewportCssVars. It fires once, on the frame the
 * measured height changes — and iOS animates its keyboard, so the scroll it decides on can land AFTER that frame,
 * with nothing left to undo it. That is the "sometimes".
 *
 * So the correction is held for as long as the keyboard takes to arrive, instead of being spent on one frame.
 * Bounded (a fixed window, then it stops by itself), iOS-only (Android shrinks the layout viewport properly and
 * never scrolls the page), and no threat to a dragging finger — a page drag while the keyboard is up is already
 * refused outright by armPageDragRefusal, which is the cure for the OTHER iOS defect and stays exactly as it was.
 */
const IOS_FOCUS_SCROLL_WATCH_MS = 900;
let iosFocusScrollWatchUntil = 0;
let iosFocusScrollFrame = 0;

function holdPageAtTopWhileKeyboardArrives() {
  if (!isIosDevice()) return;
  iosFocusScrollWatchUntil = performance.now() + IOS_FOCUS_SCROLL_WATCH_MS;
  if (iosFocusScrollFrame) return;   // a watch is already running; it just got a later deadline
  const settle = () => {
    if ((window.scrollY || document.documentElement.scrollTop || 0) !== 0) window.scrollTo(0, 0);
    if (performance.now() < iosFocusScrollWatchUntil) {
      iosFocusScrollFrame = requestAnimationFrame(settle);
    } else {
      iosFocusScrollFrame = 0;
    }
  };
  iosFocusScrollFrame = requestAnimationFrame(settle);
}

// Every field that can raise the keyboard, however it got focused — a tap, a caret move, or one of our own
// focusComposerField calls. Delegated once on the document, so a field added later is covered by construction.
document.addEventListener('focusin', (event) => {
  const target = event.target instanceof Element ? event.target : null;
  if (!target) return;
  if (!target.matches('input, textarea, [contenteditable="true"], [contenteditable=""]')) return;
  holdPageAtTopWhileKeyboardArrives();
}, { passive: true });

// The height below which a dialog stops being centred and rides the top instead — i.e. "the keyboard is up".
// One number, read by syncViewportCssVars and by nothing else; the stylesheet keys off the attribute it writes.
const APP_VIEWPORT_SHORT_PX = 620;

function syncViewportCssVars() {
  // Inside Telegram the WebView height is governed by the client (viewportStableHeight),
  // not window.visualViewport — using the latter alone clips content under Telegram's header.
  const telegramHeight = telegramViewportHeight();
  const viewport = window.visualViewport;
  const visual = Math.round(viewport?.height ?? window.innerHeight ?? document.documentElement.clientHeight ?? 0);
  let height;
  if (telegramHeight > 0) {
    // Prefer Telegram's stable height, but let an on-screen keyboard (which shrinks
    // visualViewport on Android/Desktop) reduce it so the composer stays above the keyboard.
    height = visual > 0 ? Math.min(telegramHeight, visual) : telegramHeight;
  } else {
    height = visual;
  }
  // Key the no-keyboard baseline to the viewport WIDTH: a soft keyboard changes only the HEIGHT, but an orientation flip
  // (or a desktop window resize) changes the WIDTH and brings a whole new baseline height. Without this the monotonic max
  // keeps the taller PORTRAIT height as the baseline in LANDSCAPE, so composerKeyboardLikelyOpen() reads "open" forever
  // there and the keyboard-hide blur never fires (the fix would be dead in landscape). On a width change, re-baseline to
  // the current height and reset the keyboard edge so the flip itself doesn't read as a dismiss.
  const visualWidth = Math.round(viewport?.width ?? window.innerWidth ?? 0);
  if (visual > 0) {
    if (visualWidth !== composerViewportBaselineWidth) {
      composerViewportMaxHeight = visual; composerViewportBaselineWidth = visualWidth; composerKeyboardWasOpen = false;
    } else {
      composerViewportMaxHeight = Math.max(composerViewportMaxHeight, visual); // tallest at THIS width = no-soft-keyboard baseline
    }
  }
  composerHandleKeyboardVisibility(); // blur the composer if the soft keyboard was just dismissed (kills the re-pop at its source)
  writeVisibleBottomGap();
  // THE VISIBLE HEIGHT, AS REPORTED. Nothing latched, nothing floored, nothing derived.
  //
  // [MEASURED in the owner's installed app, keyboard open] innerHeight 894, visible height 508 — and the app was
  // using 550. The 42px difference was mine: the keyboard's height had been LATCHED at 344 during the moment it
  // was still sliding up, its real value settled at 386, and the 60px re-latch threshold refused to correct a
  // 42px error. So the shell was built 42px taller than the screen can show and its bottom row sat under the
  // keyboard — which is the whole complaint, and it survived every attempt to fix it by moving things.
  //
  // The latch existed to stop a few pixels of frame-to-frame noise from moving the layout. It cost a 42px lie to
  // save that, which is a bad trade — and the shudder it was fighting had a different cause anyway (two corrections
  // applied to the same box; see the note on .composer.is-maximized). Read the number, use the number.
  //
  // Telegram keeps its own authority: its client-reported height still caps the result.
  const rounded = Math.max(0, Math.round(telegramHeight > 0 ? Math.min(telegramHeight, height || telegramHeight) : height));
  document.documentElement.style.setProperty('--app-viewport-height', `${rounded}px`);
  // AND THE ONE FLAG THE DIALOGS READ. It used to be `@media (max-height: 620px)`, which asks the LAYOUT viewport
  // — a second opinion on the same question, and on iOS a slower one: after a keyboard dismiss the layout viewport
  // is restored lazily, so the query stayed matched while this number was already right, and the dialog stayed
  // pinned to the top [OWNER 2026-08-24]. Written from the SAME number, on the same line, so they cannot drift.
  if (rounded > 0 && rounded <= APP_VIEWPORT_SHORT_PX) document.documentElement.dataset.appViewportShort = 'true';
  else delete document.documentElement.dataset.appViewportShort;
  // THE KEYBOARD'S SCROLL IS STALE THE MOMENT WE RESIZE, so undo it — once, here, and nowhere else.
  //
  // [MEASURED in the installed app] MAX scroll 386, off 386, shell up 386 — all three equal to the keyboard's
  // height, all three the same event. The ORDER is what makes it happen: at the moment of focus the shell is
  // still full height, so the composer is sitting exactly where the keyboard is about to appear. iOS sees a field
  // under the incoming keyboard and scrolls the page to lift it. Then the keyboard finishes, we shrink the shell
  // to the visible height, the composer is now near the top — and the scroll it was given stays. The system's
  // decision was correct when it was made and wrong one frame later; nothing was undoing it.
  //
  // This is NOT the 1.0.28 hack that fought every scroll and snapped back on release. It fires only when the
  // measured height actually CHANGES — i.e. the keyboard arrived or left — so a finger dragging the page (which
  // changes no size) is never touched. Once per keyboard, not once per frame.
  if (rounded !== viewportHeightLastWritten) {
    viewportHeightLastWritten = rounded;
    if ((window.scrollY || document.documentElement.scrollTop || 0) !== 0) window.scrollTo(0, 0);
    pinOpenThreadsToEndAfterViewportChange();
    // ...and then KEEP asking for a moment. On iOS the keyboard is drawn OVER the window, the geometry settles
    // lazily after this event, and the one-shot pin above lands on numbers still in motion — the ladder re-runs
    // the same idempotent enforcement until the world stops moving. A rung that finds a further height change
    // re-arms the ladder through this very branch, so a long animation extends its own watch.
    armViewportSettleLadder();
  }
  // Identical to the above now that the floor is gone. Kept as a separate name only because the stylesheet refers
  // to it in several places; both are simply "the visible height", with nothing added to either.
  if (rounded > 0) document.documentElement.style.setProperty('--app-viewport-height-exact', `${rounded}px`);
  keepViewportVarsLiveWhileComposerIsOpen();
}

// Last height written to CSS. Only a CHANGE means the keyboard arrived or left; anything else is a drag, and a
// drag must not be interfered with — that distinction is what separates this from the 1.0.28 scroll-fighting hack.
let viewportHeightLastWritten = -1;

// ---- Telegram Mini App adapter --------------------------------------------
// Single codebase: when Platho runs inside a Telegram Mini App we load the
// self-hosted Telegram WebApp SDK (index.html) and turn on a thin adapter —
// native theme chrome, viewport + safe-area from Telegram, BackButton, closing
// confirmation, hidden PWA-install UI, and a softer background auto-lock. In an
// ordinary browser the SDK reports platform 'unknown', isTelegramEnv() is false,
// and every branch below is inert, so the standalone PWA is unchanged. Every SDK
// call is version-gated (isVersionAtLeast) and wrapped so an old client can never
// throw the app down.

function telegramWebApp() {
  const tg = window.Telegram && window.Telegram.WebApp;
  return tg && typeof tg === 'object' ? tg : null;
}

let telegramEnvCache;
function isTelegramEnv() {
  if (telegramEnvCache !== undefined) return telegramEnvCache;
  const tg = telegramWebApp();
  telegramEnvCache = Boolean(
    tg && (
      (typeof tg.initData === 'string' && tg.initData.length > 0)
      || (typeof tg.platform === 'string' && tg.platform && tg.platform !== 'unknown')
    ),
  );
  return telegramEnvCache;
}

function telegramSupports(version) {
  const tg = telegramWebApp();
  if (!tg || typeof tg.isVersionAtLeast !== 'function') return false;
  try {
    return Boolean(tg.isVersionAtLeast(version));
  } catch {
    return false;
  }
}

function telegramPlatform() {
  const tg = telegramWebApp();
  return tg && typeof tg.platform === 'string' ? tg.platform : '';
}

// RE-ASK, BECAUSE THE FIRST ANSWER IS TAKEN MID-MOVE.
//
// Telegram reports viewportChanged while the window is still animating — minimise and restore both send it with
// isStateStable false — and viewportStableHeight can still be catching up when the "stable" one arrives. Reading
// once and stopping latches a height measured half-way through the move, and nothing ever asks again: the shell
// stays built to that number [OWNER 2026-08-25: "the interface flew almost off the screen ... it happened when I
// minimised the mini-app window and then restored it. I cannot reach it with a finger, the whole interface seems
// to have collapsed into a narrow strip."]
//
// So the event starts a short ladder instead of a single read. Each rung is the same idempotent sync — it writes
// the number it measures and nothing else — so a rung that lands on the settled value simply writes it again.
const VIEWPORT_SETTLE_RESYNC_MS = [60, 180, 420, 900];
let viewportSettleResyncTimers = [];

/**
 * ONE SETTLE LADDER FOR EVERY "THE WINDOW JUST MOVED" SOURCE.
 *
 * Built for the Telegram container (viewportChanged arrives mid-animation) and then found to be the same disease
 * on the plain iPhone [OWNER 2026-08-26: "Android resizes the app window when the keyboard appears; the iPhone
 * just draws the keyboard OVER the window — and the message repositioning does not account for that"]. The
 * owner's model is exact: on iOS the window never resizes, so this app rebuilds the shell from the VISUAL
 * viewport by hand — and iOS settles the real geometry LAZILY, after the one resize event, with no further
 * events. A one-shot pin therefore runs against numbers that are still moving [OWNER: "there are many messages
 * in the dialog, they are just above the screen"], and nothing ever asks again.
 *
 * Every rung is idempotent, which is what makes re-running free: the sync writes the number it measures, the
 * zero undoes only a scroll the SYSTEM made (the user cannot scroll the page — html/body are overflow:hidden and
 * the drag refusal holds the rest), and the pin fires only while the reader is at the end
 * (conversationStickToBottom / publicPostDetailStickToBottom — a reader who scrolled up clears both).
 */
function armViewportSettleLadder() {
  for (const timer of viewportSettleResyncTimers) clearTimeout(timer);
  viewportSettleResyncTimers = VIEWPORT_SETTLE_RESYNC_MS.map((delay) => setTimeout(() => {
    syncViewportCssVars();
    if ((window.scrollY || document.documentElement.scrollTop || 0) !== 0) window.scrollTo(0, 0);
    pinOpenThreadsToEndAfterViewportChange();
  }, delay));
}

function handleTelegramViewportChanged() {
  syncViewportCssVars();
  // Always, not only when the client admits the state is unstable: a client that reports stable BEFORE
  // viewportStableHeight has settled is the case a flag cannot describe, and re-running a pure write costs nothing.
  armViewportSettleLadder();
}

function telegramViewportHeight() {
  if (!isTelegramEnv()) return 0;
  const tg = telegramWebApp();
  const stable = Number(tg && tg.viewportStableHeight);
  if (Number.isFinite(stable) && stable > 0) return stable;
  const current = Number(tg && tg.viewportHeight);
  return Number.isFinite(current) && current > 0 ? current : 0;
}

function applyTelegramSafeArea() {
  // Telegram exposes safe areas via the SDK (>=8.0); env(safe-area-inset-*) is
  // unreliable inside the embed. We only override the CSS vars when the SDK can
  // report them, so older clients keep the env()-based fallback in styles.css.
  if (!isTelegramEnv() || !telegramSupports('8.0')) return;
  const tg = telegramWebApp();
  const root = document.documentElement.style;
  for (const side of ['top', 'right', 'bottom', 'left']) {
    const content = Number(tg && tg.contentSafeAreaInset && tg.contentSafeAreaInset[side]) || 0;
    const device = Number(tg && tg.safeAreaInset && tg.safeAreaInset[side]) || 0;
    const px = Math.max(0, Math.round(content + device));
    // Only override when we have a real inset. Setting 0 before the async
    // safe-area events arrive would clobber the env() fallback and let content
    // slide under the notch/home-indicator; leave it unset until the SDK reports one.
    if (px > 0) root.setProperty(`--app-safe-area-${side}`, `${px}px`);
    else root.removeProperty(`--app-safe-area-${side}`);
  }
}

// Back-navigation. The hardware/gesture Back (Android) — and the Telegram in-app BackButton — should return
// to the LIST when an overlay is open (a private conversation OR a public channel branch), and only exit the
// app from the list. Telegram env: drive the native BackButton (its click maps to Android Back). Non-Telegram
// (PWA/browser): keep exactly ONE history sentinel while an overlay is open, so a popstate (Android Back)
// closes the overlay instead of unloading the app.
function navOverlayIsOpen() {
  return appShell?.dataset?.chatOpen === 'true'
    || publicPane?.dataset?.postOpen === 'true'
    || publicPane?.dataset?.channelOpen === 'true';
}

let navHistorySentinel = false;
function syncNavBackAffordance() {
  const open = navOverlayIsOpen();
  if (isTelegramEnv()) {
    const tg = telegramWebApp();
    if (tg && tg.BackButton) { try { open ? tg.BackButton.show() : tg.BackButton.hide(); } catch {} }
    return;
  }
  if (open && !navHistorySentinel) {
    try { history.pushState({ plathoOverlay: 1 }, ''); navHistorySentinel = true; } catch {}
  }
}

function closeNavOverlay() {
  // A maximized composer is a full-screen overlay above the post detail / conversation; ANY back-navigation
  // (native/TG BackButton, hardware/swipe Back — these sit OUTSIDE the web viewport, so the overlay can't intercept
  // them) collapses it FIRST and consumes this Back, or the overlay strands the user over whatever they backed into.
  // A second Back then closes the underlying overlay.
  if (exitComposerMaximize()) {
    syncNavBackAffordance();
    return true;
  }
  // Public post detail -> back to the feed. Checked before the chat branch so Back closes whichever overlay is on.
  // closePublicPostDetail() also exits the composer's comment mode (setPublicCommentTarget(null)) — without it the
  // shared composer would stay pinned to the closed post and a feed "post" would publish as a comment.
  if (publicPane?.dataset?.postOpen === 'true') {
    closePublicPostDetail();
    syncNavBackAffordance();
    return true;
  }
  // Channel view -> back (to discovery when it launched the view, else the feed). Sits UNDER the post detail in
  // the stack: a post opened from the channel screen closes first (branch above), landing back on the channel.
  if (publicPane?.dataset?.channelOpen === 'true') {
    closePublicChannelView();
    syncNavBackAffordance();
    return true;
  }
  // Private conversation -> back to the dialog list. Clear activeThreadId so a later tab-return restores the
  // LIST, not this dialog: setView restores chatOpen from activeThreadId, and leaving it set re-opened the
  // dialog even when the user had backed out to the list.
  if (appShell?.dataset?.chatOpen === 'true') {
    appShell.dataset.chatOpen = 'false';
    activeThreadId = null;
    renderThreads();
    hideIdentityPopover();
    syncNavBackAffordance();
    return true;
  }
  return false;
}

function requestNavBack() {
  // Non-Telegram: pop the history sentinel so the stack stays consistent; popstate runs closeNavOverlay.
  if (!isTelegramEnv() && navHistorySentinel) {
    navHistorySentinel = false;
    try { history.back(); return; } catch { /* fall through to a direct close */ }
  }
  closeNavOverlay();
}

function installNavBackHandling() {
  if (!appShell) return;
  if (typeof MutationObserver === 'function') {
    const observer = new MutationObserver(syncNavBackAffordance);
    observer.observe(appShell, { attributes: true, attributeFilter: ['data-chat-open'] });
    if (publicPane) observer.observe(publicPane, { attributes: true, attributeFilter: ['data-post-open'] });
  }
  if (typeof window !== 'undefined' && !isTelegramEnv()) {
    window.addEventListener('popstate', () => {
      navHistorySentinel = false;
      closeNavOverlay();
    });
  }
  syncNavBackAffordance();
}

function openExternalLinkInTelegram(href) {
  const tg = telegramWebApp();
  if (!tg || typeof tg.openLink !== 'function') return false;
  try {
    tg.openLink(href);
    return true;
  } catch {
    return false;
  }
}

function openTelegramDeepLink(href) {
  const tg = telegramWebApp();
  if (tg && typeof tg.openTelegramLink === 'function') {
    try {
      tg.openTelegramLink(href);
      return true;
    } catch { /* fall through to openLink */ }
  }
  return openExternalLinkInTelegram(href);
}


function safeExternalUrl(raw) {
  if (typeof raw !== 'string' || raw.length === 0) return null;
  let url;
  try { url = new URL(raw); } catch { return null; }
  if (url.protocol !== 'https:' && url.protocol !== 'http:') return null;
  return url.href;
}

function trimTrailingUrlPunctuation(url) {
  let out = url;
  while (out.length > 0 && '.,;:!?…\'")]}»'.includes(out[out.length - 1])) {
    // Keep a ')' that closes a '(' inside the URL (e.g. a Wikipedia link), otherwise strip trailing punctuation.
    if (out[out.length - 1] === ')' && out.includes('(')) break;
    out = out.slice(0, -1);
  }
  return out;
}

// --- Safe message formatting renderer (v769) ---------------------------------------------------------------
// A lightweight, XSS-SAFE markdown subset for message/post/comment bodies. Built ENTIRELY via createElement +
// textContent (never innerHTML) — the same posture as appendLinkifiedText. Links go ONLY through
// buildExternalLinkAnchor (interstitial, NO live href): the Docs renderer's appendInlineMarkdown uses a LIVE
// href and MUST NOT be reused for messages (a live href leaks the reader's IP via middle-click / open-in-new-tab
// — the deanonymization vector buildExternalLinkAnchor exists to close). The composer's formatting toolbar
// inserts this markup; it rides inside the existing TEXT document block as raw UTF-8 (no wire change), so old
// clients that haven't updated simply show the literal markup (graceful degradation), never a broken message.
//
// Inline: **bold** -> <strong>, *italic* -> <em>, `code` -> <code>, [label](url) + bare urls -> safe anchor.
// Block (line-level): '# ' heading (1-3 -> small/smaller), '> ' blockquote, '- '/'* ' ul, '1. ' ol,
// and a '::center '/'::justify ' paragraph-leading alignment prefix (alignment is not standard markdown and is
// block-level, so it rides as a paragraph prefix parsed here; old clients show the literal prefix).
// The grammar itself lives in message-plain-text.mjs, imported above — the renderer here and the summarising
// readers (thread previews, reply quotes) must parse the SAME markers, and a second copy is how one of them ends
// up printing '# ' on screen. This regex is this renderer's own instance: it is global, so it carries lastIndex.
const INLINE_FORMAT_RE = createInlineFormatRegex();

function appendInlineFormatted(parent, text) {
  const str = String(text ?? '');
  if (!str) return;
  INLINE_FORMAT_RE.lastIndex = 0;
  let last = 0;
  let match;
  while ((match = INLINE_FORMAT_RE.exec(str)) !== null) {
    if (match.index > last) parent.append(document.createTextNode(str.slice(last, match.index)));
    let consumedEnd = match.index + match[0].length;
    if (match[1] !== undefined) {
      // ***bold+italic*** -> <strong><em>
      const strong = document.createElement('strong');
      const em = document.createElement('em');
      em.textContent = match[1];
      strong.append(em);
      parent.append(strong);
    } else if (match[2] !== undefined) {
      const el = document.createElement('strong');
      el.textContent = match[2];
      parent.append(el);
    } else if (match[3] !== undefined) {
      const el = document.createElement('em');
      el.textContent = match[3];
      parent.append(el);
    } else if (match[4] !== undefined) {
      const el = document.createElement('code');
      el.className = 'msg-code';
      el.textContent = match[4];
      parent.append(el);
    } else if (match[5] !== undefined) {
      // [label](url) — link ONLY if the url passes the scheme allowlist; else emit the literal typed text.
      const safe = safeExternalUrl(match[6]);
      parent.append(safe ? buildExternalLinkAnchor(match[5], safe) : document.createTextNode(match[0]));
    } else {
      // bare url (match[7]) — trim trailing punctuation like appendLinkifiedText does.
      const trimmed = trimTrailingUrlPunctuation(match[7]);
      const safe = safeExternalUrl(trimmed);
      parent.append(safe ? buildExternalLinkAnchor(trimmed, safe) : document.createTextNode(trimmed));
      consumedEnd = match.index + trimmed.length; // leave trailing punctuation for the next text node
    }
    last = consumedEnd;
    if (INLINE_FORMAT_RE.lastIndex <= match.index) INLINE_FORMAT_RE.lastIndex = match.index + match[0].length;
  }
  if (last < str.length) parent.append(document.createTextNode(str.slice(last)));
}

function messageTextHasBlockFormatting(text) {
  const str = String(text ?? '');
  if (!str.includes('\n') && !/^\s*(#{1,3}\s|>|[-*]\s|\d+\.\s|::(center|justify)\s)/.test(str)) {
    // Fast path: a single line with no leading block marker cannot carry block formatting.
    return false;
  }
  return str.split('\n').some((line) => (
    MSG_HEADING_RE.test(line) || MSG_QUOTE_RE.test(line) || MSG_ULIST_RE.test(line)
    || MSG_OLIST_RE.test(line) || MSG_ALIGN_RE.test(line)
  ));
}

// Render message body text with the safe formatting subset. Appends block/inline children to `container`.
// When no block markers are present, the inline fast path keeps the common (unformatted) message structurally
// identical to the old appendLinkifiedText output.
//
// THERE IS NO "INLINE ONLY" MODE ANY MORE, deliberately. It existed for the shared-post embed, whose text sat in a
// <p> — and a <p> cannot legally hold the block children this emits, so the option made "#" and "##" render as
// literal characters in a forwarded post while bold worked (owner, 2026-08-07). The embed now uses a DIV like every
// other body-text container, which leaves nothing that needs the option — and an unused switch on a shared renderer
// is how the same bug comes back.
function appendFormattedMessageText(container, text) {
  const str = String(text ?? '');
  if (!messageTextHasBlockFormatting(str)) {
    appendInlineFormatted(container, str);
    return;
  }
  const lines = str.split('\n');
  let index = 0;
  while (index < lines.length) {
    const line = lines[index];
    if (line.trim() === '') { index += 1; continue; }
    const headingMatch = MSG_HEADING_RE.exec(line);
    if (headingMatch) {
      const level = Math.min(headingMatch[1].length, 3);
      const heading = document.createElement('div');
      heading.className = `msg-block msg-heading msg-heading-${level}`;
      appendInlineFormatted(heading, headingMatch[2]);
      container.append(heading);
      index += 1;
      continue;
    }
    if (MSG_QUOTE_RE.test(line)) {
      const quoteLines = [];
      while (index < lines.length && MSG_QUOTE_RE.test(lines[index])) {
        quoteLines.push(lines[index].replace(MSG_QUOTE_RE, '$1'));
        index += 1;
      }
      const quote = document.createElement('blockquote');
      quote.className = 'msg-block msg-quote';
      appendInlineFormatted(quote, quoteLines.join('\n'));
      container.append(quote);
      continue;
    }
    if (MSG_ULIST_RE.test(line) || MSG_OLIST_RE.test(line)) {
      const ordered = MSG_OLIST_RE.test(line);
      const itemRe = ordered ? MSG_OLIST_RE : MSG_ULIST_RE;
      const list = document.createElement(ordered ? 'ol' : 'ul');
      list.className = 'msg-block msg-list';
      while (index < lines.length && itemRe.test(lines[index])) {
        const item = document.createElement('li');
        appendInlineFormatted(item, lines[index].replace(itemRe, '$1'));
        list.append(item);
        index += 1;
      }
      container.append(list);
      continue;
    }
    // Plain paragraph — its FIRST line may carry an alignment prefix (::center / ::justify) applied to the whole
    // paragraph. Collect consecutive non-block, non-blank lines.
    const paragraphLines = [];
    let align = null;
    while (index < lines.length) {
      const current = lines[index];
      if (current.trim() === '' || MSG_HEADING_RE.test(current) || MSG_QUOTE_RE.test(current)
        || MSG_ULIST_RE.test(current) || MSG_OLIST_RE.test(current)) break;
      let value = current;
      if (paragraphLines.length === 0) {
        const alignMatch = MSG_ALIGN_RE.exec(current);
        if (alignMatch) { align = alignMatch[1]; value = alignMatch[2]; }
      }
      paragraphLines.push(value);
      index += 1;
    }
    const paragraph = document.createElement('div');
    paragraph.className = `msg-block msg-p${align ? ` msg-align-${align}` : ''}`;
    appendInlineFormatted(paragraph, paragraphLines.join('\n'));
    container.append(paragraph);
  }
}

function buildExternalLinkAnchor(displayText, safeHref) {
  const anchor = document.createElement('a');
  anchor.className = 'msg-link';
  anchor.textContent = displayText; // the visible text (the literal URL, or a [text](url) label) — set via textContent
  // DELIBERATELY NO live href / target=_blank. A real href would let a MIDDLE-click (which fires 'auxclick', not
  // 'click') and the right-click "Open link in new tab" context item navigate DIRECTLY — bypassing the interstitial
  // and leaking the reader's IP to a per-recipient beacon URL (a deanonymization / read-receipt vector, the exact
  // thing this feature exists to prevent, and worse than a plain non-clickable URL). So the destination lives in a
  // dataset and EVERY activation path (left/middle click, Enter/Space) is forced through activateExternalLink →
  // the confirm. role=link + tabIndex keep it a real, keyboard-reachable link; the URL is the visible text, so it
  // is still selectable/copyable.
  anchor.dataset.externalUrl = safeHref;
  anchor.setAttribute('role', 'link');
  anchor.tabIndex = 0;
  const activate = (event) => {
    event.preventDefault();
    event.stopPropagation();
    activateExternalLink(safeHref, displayText);
  };
  anchor.addEventListener('click', activate);
  anchor.addEventListener('auxclick', activate); // middle-click (belt-and-suspenders; no href already means no nav)
  anchor.addEventListener('keydown', (event) => {
    if (event.key === 'Enter' || event.key === ' ') activate(event);
  });
  return anchor;
}

function openExternalUrl(safeHref) {
  // Telegram embed: target=_blank is unreliable, route through the SDK. Plain web: a fresh noopener window.
  if (isTelegramEnv() && openExternalLinkInTelegram(safeHref)) return;
  window.open(safeHref, '_blank', 'noopener,noreferrer');
}

const EXTERNAL_LINK_TRUSTED_DOMAINS_KEY = 'platho.externalLink.trustedDomains.v1';
function readTrustedExternalDomains() {
  try {
    const parsed = JSON.parse(localStorageOrNull()?.getItem(scopedStorageKey(EXTERNAL_LINK_TRUSTED_DOMAINS_KEY)) ?? '[]');
    return Array.isArray(parsed) ? parsed : [];
  } catch { return []; }
}
function externalLinkDomainTrusted(host) {
  return Boolean(host) && readTrustedExternalDomains().includes(String(host).toLowerCase());
}
function trustExternalDomain(host) {
  if (!host) return;
  const set = new Set(readTrustedExternalDomains());
  set.add(String(host).toLowerCase());
  try {
    localStorageOrNull()?.setItem(scopedStorageKey(EXTERNAL_LINK_TRUSTED_DOMAINS_KEY), JSON.stringify([...set].slice(-300)));
  } catch { /* quota/unavailable: just re-prompt next time */ }
}

function activateExternalLink(safeHref, displayText) {
  let host = '';
  try { host = new URL(safeHref).hostname; } catch { host = ''; }
  if (externalLinkDomainTrusted(host)) { openExternalUrl(safeHref); return; }
  showExternalLinkConfirm(safeHref, host, displayText);
}

let activeExternalLinkModal = null;
function closeExternalLinkModal() {
  if (!activeExternalLinkModal) return;
  const { backdrop, onKeydown, previousFocus } = activeExternalLinkModal;
  document.removeEventListener('keydown', onKeydown, true);
  activeExternalLinkModal = null;
  // The same exit every other sheet has (owner): the backdrop fades and the card pops out BEFORE the node leaves
  // the DOM; reduced motion removes it at once. The modal is built per open, so a reopen mid-exit gets a fresh node
  // and the old one just finishes leaving (pointer-events are off while it does, see .is-closing).
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) backdrop.remove();
  else {
    backdrop.classList.add('is-closing');
    window.setTimeout(() => backdrop.remove(), 200);
  }
  try { previousFocus?.focus?.(); } catch { /* focus target detached */ }
}
function showExternalLinkConfirm(safeHref, host, displayText) {
  closeExternalLinkModal();
  const previousFocus = document.activeElement instanceof HTMLElement ? document.activeElement : null;
  const domainLabel = host || safeHref;
  const backdrop = document.createElement('div');
  backdrop.className = 'modal-backdrop external-link-backdrop';
  const card = document.createElement('section');
  card.className = 'action-dialog external-link-dialog';
  card.setAttribute('role', 'dialog');
  card.setAttribute('aria-modal', 'true');

  const title = document.createElement('h2');
  title.textContent = t('link.confirmTitle');
  const body = document.createElement('p');
  body.textContent = t('link.confirmBody', { domain: domainLabel });
  // ANTI-PHISHING: when the visible text is a LABEL that differs from the destination (a [text](url) link), show
  // "shown as: <label>" so a mismatch between what the reader clicked and where it actually goes is obvious.
  const isLabeled = typeof displayText === 'string' && displayText.length > 0 && displayText !== safeHref;
  let shownAs = null;
  if (isLabeled) {
    shownAs = document.createElement('p');
    shownAs.className = 'external-link-shownas';
    shownAs.textContent = t('link.shownAs', { text: displayText });
  }
  const urlPreview = document.createElement('p');
  urlPreview.className = 'external-link-url';
  urlPreview.textContent = safeHref; // the exact destination, textContent-only
  const ipWarn = document.createElement('p');
  ipWarn.className = 'external-link-ip-warning';
  ipWarn.textContent = t('link.ipWarning');

  const dontAskRow = document.createElement('label');
  dontAskRow.className = 'external-link-dontask';
  const checkbox = document.createElement('input');
  checkbox.type = 'checkbox';
  const dontAskText = document.createElement('span');
  dontAskText.textContent = t('link.dontAskAgain', { domain: domainLabel });
  dontAskRow.append(checkbox, dontAskText);

  const actions = document.createElement('div');
  actions.className = 'external-link-actions';
  const cancelBtn = document.createElement('button');
  cancelBtn.type = 'button';
  cancelBtn.className = 'secondary-button';
  cancelBtn.textContent = t('common.cancel');
  const openBtn = document.createElement('button');
  openBtn.type = 'button';
  openBtn.className = 'external-link-open';
  openBtn.textContent = t('link.open');
  actions.append(cancelBtn, openBtn);

  card.append(title, body, ...(shownAs ? [shownAs] : []), urlPreview, ipWarn, dontAskRow, actions);
  backdrop.append(card);
  document.body.append(backdrop);

  const confirmOpen = () => {
    if (checkbox.checked && host) trustExternalDomain(host);
    closeExternalLinkModal();
    openExternalUrl(safeHref);
  };
  cancelBtn.addEventListener('click', closeExternalLinkModal);
  openBtn.addEventListener('click', confirmOpen);
  // v794: X-only — no outside/backdrop tap and no Escape dismiss; the user must choose Cancel or Open.
  const onKeydown = (event) => {
    if (event.key === 'Enter' && document.activeElement === openBtn) { event.preventDefault(); confirmOpen(); }
  };
  document.addEventListener('keydown', onKeydown, true);
  activeExternalLinkModal = { backdrop, onKeydown, previousFocus };
  cancelBtn.focus();
}

// ── Composer "Insert link" dialog (v750) ───────────────────────────────────────────────────
// So people don't hand-craft [text](url) markup: a small dialog takes an optional link text + a URL and inserts
// the correctly-formatted markup at the composer caret. The URL is scheme-checked (safeExternalUrl) exactly like
// a rendered link, and any '(' / ')' in the URL is percent-encoded so it can't break the [text](url) parse.
let activeLinkComposerModal = null;
function closeLinkComposerModal() {
  if (!activeLinkComposerModal) return;
  const { backdrop, onKeydown, previousFocus } = activeLinkComposerModal;
  if (onKeydown) document.removeEventListener('keydown', onKeydown, true);
  activeLinkComposerModal = null;
  // Same animated exit as the external-link sheet (the two were the only per-open modals that just vanished).
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) backdrop.remove();
  else {
    backdrop.classList.add('is-closing');
    window.setTimeout(() => backdrop.remove(), 200);
  }
  try { previousFocus?.focus?.(); } catch { /* detached */ }
}
function openLinkComposerDialog(targetInput, editChip = null) {
  if (!targetInput || targetInput.disabled) return;
  closeLinkComposerModal();
  // Capture the editor caret BEFORE the dialog steals focus, so the link lands where the user was typing (not at
  // the start). The editor DOM does not change while the dialog is open, so the cloned range stays valid.
  const savedRange = (() => {
    const sel = window.getSelection();
    if (sel && sel.rangeCount) { const r = sel.getRangeAt(0); if (targetInput.contains(r.commonAncestorContainer)) return r.cloneRange(); }
    return null;
  })();
  const previousFocus = document.activeElement instanceof HTMLElement ? document.activeElement : null;
  const backdrop = document.createElement('div');
  backdrop.className = 'modal-backdrop link-composer-backdrop';
  const card = document.createElement('section');
  card.className = 'action-dialog link-composer-dialog';
  card.setAttribute('role', 'dialog');
  card.setAttribute('aria-modal', 'true');

  const title = document.createElement('h2');
  title.textContent = t(editChip ? 'composer.editLink' : 'composer.insertLink');
  const textInput = document.createElement('input');
  textInput.type = 'text';
  textInput.className = 'link-composer-input';
  textInput.placeholder = t('composer.linkText');
  textInput.setAttribute('aria-label', t('composer.linkText'));
  textInput.maxLength = 200;
  // Pre-fill: editing an existing chip fills BOTH fields from its [label](url) marker (decoding the %28/%29 we
  // encode on insert); otherwise a SELECTED word pre-fills the link text (and the link replaces the selection).
  let editUrl = '';
  let prefilledText = false;
  if (editChip) {
    const m = String(editChip.dataset.marker || '').match(/^\[([\s\S]*)\]\(([\s\S]*)\)$/);
    if (m) { textInput.value = m[1]; editUrl = m[2].replace(/%28/g, '(').replace(/%29/g, ')'); prefilledText = true; }
  } else {
    const selectedText = savedRange && !savedRange.collapsed ? savedRange.toString().replace(/[[\]\n]/g, ' ').trim().slice(0, 200) : '';
    if (selectedText) { textInput.value = selectedText; prefilledText = true; }
  }
  const urlInput = document.createElement('input');
  urlInput.type = 'url';
  urlInput.className = 'link-composer-input';
  urlInput.placeholder = t('composer.linkUrl');
  urlInput.setAttribute('aria-label', t('composer.linkUrl'));
  urlInput.inputMode = 'url';
  if (editUrl) urlInput.value = editUrl;
  const errorLine = document.createElement('p');
  errorLine.className = 'link-composer-error';
  errorLine.hidden = true;

  const actions = document.createElement('div');
  actions.className = 'external-link-actions';
  const cancelBtn = document.createElement('button');
  cancelBtn.type = 'button';
  cancelBtn.className = 'secondary-button';
  cancelBtn.textContent = t('common.cancel');
  const insertBtn = document.createElement('button');
  insertBtn.type = 'button';
  insertBtn.className = 'external-link-open';
  insertBtn.textContent = t('composer.insert');
  actions.append(cancelBtn, insertBtn);

  card.append(title, textInput, urlInput, errorLine, actions);
  backdrop.append(card);
  document.body.append(backdrop);

  const doInsert = () => {
    let raw = String(urlInput.value ?? '').trim();
    if (!raw) { errorLine.textContent = t('composer.linkUrlInvalid'); errorLine.hidden = false; focusComposerField(urlInput); return; }
    if (!/^[a-z][a-z0-9+.-]*:/i.test(raw)) raw = `https://${raw}`; // a bare domain typed without a scheme -> assume https
    const safe = safeExternalUrl(raw);
    if (!safe) { errorLine.textContent = t('composer.linkUrlInvalid'); errorLine.hidden = false; focusComposerField(urlInput); return; }
    const label = String(textInput.value ?? '').replace(/[[\]\n]/g, ' ').trim();
    const encodedUrl = safe.replace(/\(/g, '%28').replace(/\)/g, '%29'); // keep parens out of the [text](url) parse
    const display = label || safe;
    const markup = `[${display}](${encodedUrl})`; // always a labeled link so the editor can render it as a link chip
    closeLinkComposerModal();
    if (editChip) {
      // Editing an existing chip: replace it in place (do nothing if it was removed while the dialog was open).
      if (editChip.isConnected) {
        const newBlock = buildComposerLinkBlock(markup, display);
        editChip.replaceWith(newBlock);
        composerEditorPlaceCaretAfter(newBlock);
        composerEditorAfterEdit(targetInput);
      }
    } else {
      composerEditorInsertLinkBlock(targetInput, markup, display, savedRange); // renders as a link chip at the caret
    }
  };
  cancelBtn.addEventListener('click', closeLinkComposerModal);
  insertBtn.addEventListener('click', doInsert);
  urlInput.addEventListener('keydown', (event) => { if (event.key === 'Enter') { event.preventDefault(); doInsert(); } });
  textInput.addEventListener('keydown', (event) => { if (event.key === 'Enter') { event.preventDefault(); focusComposerField(urlInput); } });
  // v794: X-only — no outside/backdrop tap and no Escape dismiss; the user must choose Cancel or Insert.
  activeLinkComposerModal = { backdrop, onKeydown: null, previousFocus };
  // If the link text is already filled (a selected word, or the chip being edited), jump straight to the URL field.
  focusComposerField(prefilledText ? urlInput : textInput);
}

// A bare window.open of a t.me/ link is a no-op inside the Telegram in-app WebView,
// so route the @toncenter bot link through the SDK first and fall back to a new tab
// (normal browser / SDK missing).
function openToncenterBotLink() {
  if (openTelegramDeepLink('https://t.me/toncenter')) return;
  try { globalThis.open?.('https://t.me/toncenter', '_blank', 'noopener'); } catch { /* ignore */ }
}

// "Get" no longer dumps the user straight into the @toncenter bot. It opens an explanatory modal first
// (what an RPC key is for + the exact steps), and the bot link is the modal's primary action. Dismissing
// the modal (✕ / outside-click) does nothing; only the CTA opens the bot.
async function openRpcKeyHelpDialog() {
  const proceed = await openActionDialog({
    title: t('wallet.rpcKeyHelpTitle'),
    hint: t('wallet.rpcKeyHelpHint'),
    fields: [{
      type: 'note',
      steps: [
        t('wallet.rpcKeyHelpStep1'),
        t('wallet.rpcKeyHelpStep2'),
        t('wallet.rpcKeyHelpStep3'),
        t('wallet.rpcKeyHelpStep4'),
      ],
    }],
    submitLabel: t('wallet.rpcKeyHelpOpenBot'),
  });
  if (proceed) openToncenterBotLink();
}

function markTelegramRootAttribute() {
  try {
    if (isTelegramEnv()) document.documentElement.dataset.plathoTelegram = 'true';
  } catch {}
}

function initTelegramMiniApp() {
  const tg = telegramWebApp();
  if (!tg) return;
  try {
    tg.ready();
  } catch {}
  if (!isTelegramEnv()) return; // SDK present but launched in a normal browser
  markTelegramRootAttribute();
  try {
    tg.expand();
  } catch {}
  // Keep the app's own fixed dark brand theme; only match Telegram's chrome to it.
  const APP_BG = '#0b0d0f';
  try {
    if (telegramSupports('6.9')) tg.setHeaderColor(APP_BG);
    else tg.setHeaderColor('bg_color');
  } catch {}
  try {
    tg.setBackgroundColor(APP_BG);
  } catch {}
  try {
    if (telegramSupports('7.10') && typeof tg.setBottomBarColor === 'function') tg.setBottomBarColor(APP_BG);
  } catch {}
  try {
    if (telegramSupports('6.2')) tg.enableClosingConfirmation();
  } catch {}
  try {
    if (telegramSupports('7.7') && typeof tg.disableVerticalSwipes === 'function') tg.disableVerticalSwipes();
  } catch {}
  applyTelegramSafeArea();
  try {
    tg.onEvent('safeAreaChanged', applyTelegramSafeArea);
    tg.onEvent('contentSafeAreaChanged', applyTelegramSafeArea);
  } catch {}
  syncViewportCssVars();
  try {
    tg.onEvent('viewportChanged', handleTelegramViewportChanged);
  } catch {}
  try {
    if (tg.BackButton && typeof tg.BackButton.onClick === 'function') {
      tg.BackButton.onClick(() => {
        try {
          requestNavBack();
        } catch {}
      });
    }
  } catch {}
}

// ---- Telegram durability: storage eviction is real on iOS WKWebView ---------
// localStorage (the only place the encrypted wallet key lives) can be evicted by
// the Telegram WebView between sessions. Two defenses: (1) force a confirmed
// 24-word backup right after generation, and (2) mirror the password-encrypted
// wallet record into Telegram CloudStorage (server-side, per-user) as a recovery
// channel. CloudStorage holds only ciphertext; without the user password it is
// useless, so this does not weaken the wallet.

const TELEGRAM_CLOUD_WALLET_KEY = 'platho_wallet_encrypted_v1';
const TELEGRAM_CLOUD_VALUE_MAX_BYTES = 4096;
const TELEGRAM_SEED_BACKUP_STORAGE_KEY = 'platho.wallet.telegram.seedbackup.v1';

function telegramCloudStorage() {
  const tg = telegramWebApp();
  return isTelegramEnv() && telegramSupports('6.9') && tg && tg.CloudStorage ? tg.CloudStorage : null;
}

function telegramCloudSet(key, value) {
  return new Promise((resolve) => {
    const cs = telegramCloudStorage();
    if (!cs || typeof cs.setItem !== 'function') {
      resolve(false);
      return;
    }
    try {
      cs.setItem(key, value, (error, ok) => resolve(!error && ok !== false));
    } catch {
      resolve(false);
    }
  });
}

function telegramCloudGet(key) {
  return new Promise((resolve) => {
    const cs = telegramCloudStorage();
    if (!cs || typeof cs.getItem !== 'function') {
      resolve(null);
      return;
    }
    try {
      cs.getItem(key, (error, value) => resolve(error ? null : (value || null)));
    } catch {
      resolve(null);
    }
  });
}

function telegramCloudGetKeys() {
  return new Promise((resolve) => {
    const cs = telegramCloudStorage();
    if (!cs || typeof cs.getKeys !== 'function') {
      resolve([]);
      return;
    }
    try {
      cs.getKeys((error, keys) => resolve(error || !Array.isArray(keys) ? [] : keys.map(String)));
    } catch {
      resolve([]);
    }
  });
}

function telegramCloudRemoveItems(keys) {
  return new Promise((resolve) => {
    const cs = telegramCloudStorage();
    if (keys.length === 0) {
      resolve(true);
      return;
    }
    if (!cs || typeof cs.removeItems !== 'function') {
      resolve(false);
      return;
    }
    try {
      cs.removeItems(keys, (error, ok) => resolve(!error && ok !== false));
    } catch {
      resolve(false);
    }
  });
}

// Wipe EVERY CloudStorage key this app ever wrote — ENUMERATED live (getKeys), not a hardcoded list, so a
// future cloud mirror cannot silently escape "Clear local data". Without this the Telegram Mini App
// resurrected the encrypted wallet from the cloud mirror on the very next boot (the owner's
// unlock-screen-right-after-clear report). Bounded by a timeout race: CloudStorage callbacks can hang on
// mobile Telegram (see the boot-restore race note), and the clear button must not wedge forever.
async function clearTelegramCloudAppData() {
  if (!telegramCloudStorage()) return true;
  const run = (async () => {
    const keys = await telegramCloudGetKeys();
    return telegramCloudRemoveItems(keys);
  })();
  const result = await Promise.race([run, delay(8_000).then(() => 'timeout')]);
  return result === true;
}

function mirrorWalletRecordToTelegramCloud(record) {
  if (!telegramCloudStorage() || !record || record.kind !== PLATHO_WALLET_STORAGE_KIND) return;
  let json = '';
  try {
    json = JSON.stringify(record);
  } catch {
    return;
  }
  // Telegram CloudStorage caps each value at 4096 bytes; the encrypted wallet
  // record (no message history) is well under that. Skip silently if it ever isn't.
  if (!json || json.length > TELEGRAM_CLOUD_VALUE_MAX_BYTES) return;
  telegramCloudSet(TELEGRAM_CLOUD_WALLET_KEY, json).catch(() => {});
}

async function restoreWalletRecordFromTelegramCloud() {
  if (!telegramCloudStorage()) return false;
  if (hasStoredPlathoWalletRecord()) return false; // a local copy always wins
  try {
    const json = await telegramCloudGet(TELEGRAM_CLOUD_WALLET_KEY);
    if (!json) return false;
    const record = JSON.parse(json);
    if (!record || record.kind !== PLATHO_WALLET_STORAGE_KIND) return false;
    const storage = localStorageOrNull();
    if (!storage) return false;
    storage.setItem(PLATHO_WALLET_STORAGE_KEY, JSON.stringify(record));
    return true;
  } catch {
    return false;
  }
}

function readTelegramSeedBackupSet() {
  try {
    const raw = localStorageOrNull()?.getItem(TELEGRAM_SEED_BACKUP_STORAGE_KEY);
    const list = raw ? JSON.parse(raw) : [];
    return Array.isArray(list) ? list.map(String) : [];
  } catch {
    return [];
  }
}

function isTelegramSeedBackupConfirmed(address) {
  if (!address) return false;
  return readTelegramSeedBackupSet().some((entry) => sameWalletAddress(entry, address));
}

function markTelegramSeedBackupConfirmed(address) {
  // Guard isTelegramEnv() so an ordinary-browser import never writes this key
  // (keeps non-Telegram localStorage byte-for-byte identical to before).
  if (!isTelegramEnv() || !address) return;
  try {
    const set = readTelegramSeedBackupSet();
    if (set.some((entry) => sameWalletAddress(entry, address))) return;
    set.push(String(address));
    localStorageOrNull()?.setItem(TELEGRAM_SEED_BACKUP_STORAGE_KEY, JSON.stringify(set.slice(-8)));
  } catch {}
}

// ---- Wallet-key backup safety net ------------------------------------------
// A newly-created wallet is stored on-device immediately, but exporting the encrypted KEY-FILE backup is a
// separate step. If the user is interrupted (screen off, reload, accidental close) before exporting it, the
// wallet can sit on the device with NO backup, and the quick-start would not re-appear (a wallet already
// exists). So we durably flag "this wallet's key was never exported" — mirrored to Telegram CloudStorage to
// survive iOS localStorage eviction — and keep re-surfacing the backup step until it is done. The flag is
// cleared on export; a wallet created by IMPORT is never flagged (the user already holds the seed / file).
const WALLET_KEY_BACKUP_PENDING_KEY = 'platho.wallet.keybackup.pending.v1';
const WALLET_KEY_BACKUP_PENDING_CLOUD_KEY = 'platho_wallet_keybackup_pending_v1';

function readWalletKeyBackupPendingSet() {
  try {
    const raw = localStorageOrNull()?.getItem(WALLET_KEY_BACKUP_PENDING_KEY);
    const list = raw ? JSON.parse(raw) : [];
    return Array.isArray(list) ? list.map(String) : [];
  } catch {
    return [];
  }
}

function writeWalletKeyBackupPendingSet(list) {
  const trimmed = Array.from(new Set(list.map(String))).slice(-8);
  try { localStorageOrNull()?.setItem(WALLET_KEY_BACKUP_PENDING_KEY, JSON.stringify(trimmed)); } catch { /* ignore */ }
  try { telegramCloudSet(WALLET_KEY_BACKUP_PENDING_CLOUD_KEY, JSON.stringify(trimmed)).catch(() => {}); } catch { /* ignore */ }
}

function isWalletKeyBackupPending(address) {
  if (!address) return false;
  return readWalletKeyBackupPendingSet().some((entry) => sameWalletAddress(entry, address));
}

function markWalletKeyBackupPending(address) {
  if (!address) return;
  const set = readWalletKeyBackupPendingSet();
  if (set.some((entry) => sameWalletAddress(entry, address))) return;
  set.push(String(address));
  writeWalletKeyBackupPendingSet(set);
  try { refreshWalletBackupWarning(); } catch { /* UI not ready */ }
}

function markWalletKeyBackupDone(address) {
  if (!address) return;
  const set = readWalletKeyBackupPendingSet();
  const next = set.filter((entry) => !sameWalletAddress(entry, address));
  if (next.length !== set.length) writeWalletKeyBackupPendingSet(next);
  try { refreshWalletBackupWarning(); } catch { /* UI not ready */ }
}

function walletKeyBackupPendingForStoredWallet() {
  if (!hasStoredPlathoWalletRecord()) return false;
  const record = readEncryptedPlathoWalletRecord();
  const address = record ? (storedWalletAddressForCopy(record) || record.address) : null;
  return Boolean(address && isWalletKeyBackupPending(address));
}

async function restoreWalletKeyBackupPendingFromTelegramCloud() {
  if (!telegramCloudStorage()) return;
  try {
    const json = await telegramCloudGet(WALLET_KEY_BACKUP_PENDING_CLOUD_KEY);
    if (!json) return;
    const cloud = JSON.parse(json);
    if (!Array.isArray(cloud)) return;
    // Union with local, erring toward "still pending": after iOS localStorage eviction the local set is
    // empty, so the cloud copy is what keeps the backup nudge alive until the key is actually exported.
    const merged = Array.from(new Set([...readWalletKeyBackupPendingSet(), ...cloud.map(String)]));
    writeWalletKeyBackupPendingSet(merged);
  } catch { /* ignore */ }
}

/** The seed-backup fields, as data — the same two nodes in the hard gate and in the wizard's backup step. */
function seedBackupFieldSpecs(phrase) {
  return [{
    id: 'recoveryPhrase',
    label: t('wallet.seedBackupPhraseLabel'),
    type: 'textarea',
    value: phrase,
    readOnly: true,
    required: false,
  }, {
    id: 'seedBackupConfirm',
    name: 'confirmText',
    label: t('wallet.seedBackupConfirmLabel'),
    type: 'text',
    placeholder: 'SAVED',
    autocomplete: 'off',
    autocapitalize: 'characters',
    spellcheck: false,
  }];
}

/** The typed word is the literal SAVED in every locale — the label says so and the comparison depends on it. */
function seedBackupConfirmAccepted(value) {
  return String(value ?? '').trim().toUpperCase() === 'SAVED';
}

async function enforceTelegramSeedBackupGate(wallet, { force = false } = {}) {
  if (!isTelegramEnv() || !wallet) return;
  if (!force && isTelegramSeedBackupConfirmed(wallet.address)) return;
  let phrase = '';
  try {
    phrase = exportPlathoWalletRecoveryPhrase(wallet);
  } catch {
    return;
  }
  if (!phrase) return;
  // Hard gate: no ✕, no outside-click dismiss. The user must read the words and
  // type SAVED. If they keep declining we stop after a few tries and re-gate on the
  // next unlock (the flag is only set once they confirm). The fallback depends on
  // neither clipboard nor file download — the words are shown for manual transcription.
  for (let attempt = 0; attempt < 4; attempt += 1) {
    // The ONE loop that re-opens a dialog it got a null from, so it is the one loop a lock has to be able to
    // stop: lockPlathoWallet closes the live dialog, and without this the next turn would put the recovery
    // words straight back on top of a locked app. Re-gating is already the design ("the flag is only set once
    // they confirm"), so leaving is free — the next unlock asks again.
    if (plathoWallet?.address !== wallet.address) return;
    // eslint-disable-next-line no-await-in-loop
    const result = await openActionDialog({
      title: t('wallet.seedBackupTitle'),
      hint: t('wallet.seedBackupHint'),
      tone: 'error',
      cancellable: false,
      dismissOnBackdrop: false,
      // [OWNER 2026-08-10] Plain "Continue", not "I wrote it down": the typed SAVED below is what confirms it,
      // so a second claim on the button was one assertion too many. Reuses the shared Continue label.
      submitLabel: t('common.continue'),
      fields: seedBackupFieldSpecs(phrase),
      summary: [t('wallet.seedBackupSummary')],
    });
    if (seedBackupConfirmAccepted(result?.confirmText)) {
      markTelegramSeedBackupConfirmed(wallet.address);
      return;
    }
  }
}

function showTelegramManualExportDialog(filename, content) {
  return openActionDialog({
    title: t('wallet.exportBackupTitle'),
    hint: t('wallet.exportBackupHint'),
    submitLabel: t('common.done'),
    fields: [{
      id: 'walletKeyBackup',
      label: filename,
      type: 'textarea',
      value: content,
      readOnly: true,
      required: false,
    }],
    summary: [t('wallet.exportBackupSummary')],
  }).catch(() => {});
}

// Mark the root as early as the module runs so the install-UI is hidden by CSS
// before first paint (the full bootstrap runs later, after handlers are wired).
markTelegramRootAttribute();

async function promptInstallApp() {
  const state = installActionState();
  if (state === 'installed') {
    closeInstallDialog({ dismissed: false });
    refreshInstallButtons();
    return;
  }
  if (state === 'instructions' || state === 'open-in-app' || state === 'ios-instructions') {
    if (installDialog?.hidden === false) {
      closeInstallDialog({ dismissed: false });
    } else if (installDialog) {
      installDialog.classList.remove('is-closing'); installDialog.hidden = false;
    }
    refreshInstallButtons();
    return;
  }
  closeInstallDialog({ dismissed: true });
  await firePendingInstallPrompt();
}

/**
 * Open the browser's own install sheet. THE only place the deferred event is spent — it is single-use, so a second
 * reader would find it already gone; the modal and the quick-start step both come through here.
 * Returns true if the user accepted, false if they declined, null when there was no sheet to open.
 */
async function firePendingInstallPrompt() {
  const promptEvent = deferredInstallPrompt;
  if (!promptEvent) return null;
  deferredInstallPrompt = null;
  refreshInstallButtons();
  try {
    await promptEvent.prompt();
    const choice = await promptEvent.userChoice.catch(() => null);
    return choice?.outcome === 'accepted';
  } finally {
    refreshInstallButtons();
  }
}

function installHelpText() {
  const ua = navigator.userAgent || '';
  if (/iPad|iPhone|iPod/.test(ua)) {
    return t('install.helpTextIos');
  }
  if (/Android/i.test(ua)) {
    return t('install.helpTextAndroid');
  }
  return t('install.helpTextDesktop');
}

async function refreshInstalledRelatedPwaState() {
  if (isStandaloneApp() || typeof navigator.getInstalledRelatedApps !== 'function') return;
  try {
    const installedApps = await navigator.getInstalledRelatedApps();
    installedRelatedPwaDetected = installedApps.some((app) => app?.platform === 'webapp');
    refreshInstallButtons();
  } catch {
    installedRelatedPwaDetected = false;
  }
}

function profileAvatarStorageKey(owner = plathoWallet?.address) {
  return owner ? `${PROFILE_AVATAR_POINTER_STORAGE_PREFIX}:${deploymentStorageSuffix()}:${owner}` : null;
}

function zeroAvatarHashHex() {
  return `0x${'00'.repeat(32)}`;
}

function normalizeAvatarHashHex(value) {
  const text = String(value ?? '').trim().toLowerCase();
  const hex = text.startsWith('0x') ? text.slice(2) : text;
  if (!/^[0-9a-f]{64}$/.test(hex)) throw new Error('Avatar hash must be uint256 hex');
  return `0x${hex}`;
}

function readStoredProfileAvatarPointer(owner = plathoWallet?.address) {
  const key = profileAvatarStorageKey(owner);
  if (!key) return null;
  try {
    const parsed = JSON.parse(localStorageOrNull()?.getItem(key) ?? 'null');
    if (!parsed || typeof parsed !== 'object') return null;
    const profileVersion = Number(parsed.profileVersion ?? parsed.profile_version ?? 0);
    const avatarHash = normalizeAvatarHashHex(parsed.avatarHash ?? parsed.avatar_hash ?? zeroAvatarHashHex());
    if (!Number.isSafeInteger(profileVersion) || profileVersion <= 0) return null;
    if (avatarHash === zeroAvatarHashHex()) return null;
    return { profileVersion, profile_version: profileVersion, avatarHash, avatar_hash: avatarHash };
  } catch {
    return null;
  }
}

function writeStoredProfileAvatarPointer(pointer, owner = plathoWallet?.address) {
  const key = profileAvatarStorageKey(owner);
  if (!key) return;
  const normalized = pointer ? {
    profileVersion: Number(pointer.profileVersion ?? pointer.profile_version ?? 0),
    avatarHash: normalizeAvatarHashHex(pointer.avatarHash ?? pointer.avatar_hash),
  } : null;
  if (!normalized || normalized.profileVersion <= 0) {
    localStorageOrNull()?.removeItem(key);
    localProfileAvatarPointer = null;
    return;
  }
  localStorageOrNull()?.setItem(key, JSON.stringify(normalized));
  localProfileAvatarPointer = {
    profileVersion: normalized.profileVersion,
    profile_version: normalized.profileVersion,
    avatarHash: normalized.avatarHash,
    avatar_hash: normalized.avatarHash,
  };
}

function currentProfileAvatarPointer() {
  localProfileAvatarPointer = localProfileAvatarPointer ?? readStoredProfileAvatarPointer();
  return localProfileAvatarPointer ?? {
    profileVersion: 0,
    profile_version: 0,
    avatarHash: zeroAvatarHashHex(),
    avatar_hash: zeroAvatarHashHex(),
  };
}

function currentProfilePointerFields() {
  const pointer = currentProfileAvatarPointer();
  return {
    profileVersion: pointer.profileVersion ?? 0,
    avatarHash: pointer.avatarHash ?? zeroAvatarHashHex(),
  };
}

function profileAvatarMediaHashKey(avatarHash) {
  try {
    const normalized = normalizeAvatarHashHex(avatarHash);
    if (normalized === zeroAvatarHashHex()) return null;
    return normalized;
  } catch {
    return null;
  }
}

function webpDataUrlToBytes(dataUrl) {
  const prefix = 'data:image/webp;base64,';
  if (typeof dataUrl !== 'string' || !dataUrl.startsWith(prefix)) return null;
  try {
    const binary = atob(dataUrl.slice(prefix.length));
    const bytes = new Uint8Array(binary.length);
    for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
    return bytes;
  } catch {
    return null;
  }
}

async function readProfileAvatarMediaCache(avatarHash) {
  const hash = profileAvatarMediaHashKey(avatarHash);
  if (!hash) return null;
  try {
    const store = await profileAvatarMediaStore();
    const url = (await store?.get(hash))?.url;
    if (typeof url !== 'string') return null;
    const bytes = webpDataUrlToBytes(url);
    if (!bytes) return null;
    const computedHash = await sha256Hex(bytes);
    if (computedHash.toLowerCase() !== hash.toLowerCase()) {
      await store?.delete(hash);
      return null;
    }
    return url;
  } catch {
    return null;
  }
}

async function writeProfileAvatarMediaCache(avatarHash, dataUrl) {
  const hash = profileAvatarMediaHashKey(avatarHash);
  if (!hash || typeof dataUrl !== 'string') return;
  try {
    const store = await profileAvatarMediaStore();
    await store?.put(hash, dataUrl);
  } catch {
    // Avatar media is reconstructable from chain; the local cache is best effort.
  }
}

// Warm the in-memory per-wallet public-avatar map from the IndexedDB media store BEFORE the first render, so a
// reloaded public feed shows faces immediately (no letter-tile placeholder + chain-refetch flash). The v504
// feed-cache media strip drops avatarImageUrl from the persisted feed, but avatarHash survives and the avatar
// bytes live in the media store. One batch read; no sha256 re-verify (the bytes were verified on write).
function collectCachedAvatarPointers(post, byWallet) {
  if (!post) return;
  const raw = rawWalletAddress(post.authorWallet ?? post.author_wallet);
  const hash = profileAvatarMediaHashKey(post.avatarHash ?? post.avatar_hash);
  if (raw && hash && !publicChannelAvatarUrlByWallet.has(raw) && !byWallet.has(raw)) byWallet.set(raw, hash);
  for (const comment of Array.isArray(post.comments) ? post.comments : []) collectCachedAvatarPointers(comment, byWallet);
}
// Synchronous read of a legacy localStorage avatar entry (pre-v512 format {hash,url,cachedAt}). Used as a
// first-boot fallback while the one-time IndexedDB migration has not yet run. Reads do NOT trigger the iOS
// whole-store re-serialization (only writes do), so this is safe.
function legacyAvatarMediaUrlFromLocalStorage(avatarHash) {
  const hash = profileAvatarMediaHashKey(avatarHash);
  if (!hash) return null;
  try {
    const parsed = JSON.parse(localStorageOrNull()?.getItem(`${PROFILE_AVATAR_MEDIA_CACHE_PREFIX}:${hash}`) ?? 'null');
    return parsed?.hash === hash && typeof parsed.url === 'string' ? parsed.url : null;
  } catch {
    return null;
  }
}
async function warmPublicChannelAvatarsFromCache() {
  try {
    const byWallet = new Map(); // raw wallet -> avatarHash, for authors not already in the in-memory map
    for (const record of Object.values(publicChannelFeedCache ?? {})) {
      // A cached channel record is { feed: { posts: [...] } } (sometimes the feed object directly, or just an
      // array). Extract the posts array robustly — iterating the wrong shape silently warmed NOTHING.
      const feed = record?.feed ?? record;
      const posts = Array.isArray(feed?.posts) ? feed.posts : (Array.isArray(feed) ? feed : []);
      for (const post of posts) collectCachedAvatarPointers(post, byWallet);
    }
    if (byWallet.size === 0) return;
    // 1) Legacy localStorage (pre-v512) — synchronous + instant, so the FIRST boot after the upgrade is clean
    //    before the deferred IndexedDB migration runs.
    const pending = new Map();
    for (const [raw, hash] of byWallet) {
      const url = legacyAvatarMediaUrlFromLocalStorage(hash);
      if (url) publicChannelAvatarUrlByWallet.set(raw, url);
      else pending.set(raw, hash);
    }
    // 2) IndexedDB — migrated + freshly-cached avatars.
    if (pending.size === 0) return;
    const store = await profileAvatarMediaStore();
    if (!store) return;
    const urls = await store.getMany([...pending.values()]);
    for (const [raw, hash] of pending) {
      const url = urls.get(hash);
      if (url && !publicChannelAvatarUrlByWallet.has(raw)) publicChannelAvatarUrlByWallet.set(raw, url);
    }
  } catch {
    // Best effort: a wallet whose avatar is not cached just hydrates from chain as before.
  }
}

// One-time migration of any avatars left in the OLD localStorage cache (platho.profile.avatar.media.v1:*) into
// IndexedDB, then delete them from localStorage — freeing the localStorage bloat the iOS freeze came from.
async function migrateLegacyAvatarMediaCacheToIndexedDb() {
  const ls = localStorageOrNull();
  if (!ls) return;
  let keys = [];
  try { keys = Object.keys(ls).filter((key) => key.startsWith(`${PROFILE_AVATAR_MEDIA_CACHE_PREFIX}:`)); } catch { return; }
  if (keys.length === 0) return;
  const store = await profileAvatarMediaStore().catch(() => null);
  for (const key of keys) {
    try {
      const parsed = JSON.parse(ls.getItem(key) ?? 'null');
      if (store && parsed?.hash && typeof parsed.url === 'string') await store.put(parsed.hash, parsed.url);
      ls.removeItem(key);
    } catch {
      // Skip a corrupt entry; it is reconstructable from chain.
    }
  }
}

function avatarPointerFromFields(profileVersion, avatarHash) {
  try {
    const version = Number(profileVersion ?? 0);
    const hash = normalizeAvatarHashHex(avatarHash ?? zeroAvatarHashHex());
    if (!Number.isSafeInteger(version) || version <= 0 || hash === zeroAvatarHashHex()) return null;
    return { profileVersion: version, profile_version: version, avatarHash: hash, avatar_hash: hash };
  } catch {
    return null;
  }
}

function avatarHashHexFromBigInt(value) {
  return normalizeAvatarHashHex(`0x${BigInt(value ?? 0n).toString(16).padStart(64, '0')}`);
}

function streamIdHexFromBigInt(value) {
  return `0x${BigInt(value ?? 0n).toString(16).padStart(32, '0')}`;
}

function setAvatarNode(node, fallback, imageUrl = null) {
  if (!node) return;
  // Reused nodes may have been the Saved-thread icon on the previous render.
  node.classList.remove('avatar-saved');
  if (imageUrl) {
    node.textContent = '';
    node.classList.add('has-image');
    node.style.backgroundImage = `url("${imageUrl}")`;
    // Tap-to-view (v651): the delegated document click opens any image-bearing avatar in the fullscreen
    // lightbox — the url rides in the dataset so the handler needs no re-resolution. Avatars inside BUTTONS
    // (thread list rows etc.) are excluded there: their click keeps its own meaning.
    node.dataset.avatarUrl = imageUrl;
    return;
  }
  node.classList.remove('has-image');
  node.style.backgroundImage = '';
  delete node.dataset.avatarUrl;
  node.textContent = String(fallback ?? 'P').slice(0, 2).toUpperCase();
}

/**
 * A contact who has neither a name nor a picture wears an ANONYMITY MASK, not two letters.
 *
 * [OWNER 2026-08-23: "I don't like that everyone has this UQ. For contacts with no username and no avatar, put an
 * anonymity icon in the contact's picture — an anonymous sort of thing."] The letters came from the first two
 * characters of whatever labelled the row, and for a bare wallet that is the ADDRESS — every basechain address a
 * user sees starts with the same "UQ", so every unnamed contact wore the same monogram. A monogram that is identical
 * for everyone is worse than none: it looks like an identity and identifies nobody.
 *
 * Static markup only — never interpolate user data into this.
 */
const ANONYMOUS_AVATAR_SVG =
  '<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">'
  + '<path d="M12 3a4.2 4.2 0 0 1 4.2 4.2A4.2 4.2 0 0 1 12 11.4a4.2 4.2 0 0 1-4.2-4.2A4.2 4.2 0 0 1 12 3Z" opacity="0.55"/>'
  + '<path d="M3.6 15.4c0-.7.35-1.32.95-1.63C6.2 12.9 8.9 12.3 12 12.3s5.8.6 7.45 1.47c.6.31.95.93.95 1.63v1.1H3.6v-1.1Z" opacity="0.55"/>'
  + '<path d="M3.2 17.9h17.6c.44 0 .8.36.8.8s-.36.8-.8.8H3.2a.8.8 0 0 1 0-1.6Z"/>'
  + '<path d="M7.4 17.9c-.5 1.6-1.4 2.6-2.7 2.6-1.2 0-2-.8-2-1.9 0-.3.05-.5.12-.7H7.4Zm9.2 0c.5 1.6 1.4 2.6 2.7 2.6 1.2 0 2-.8 2-1.9 0-.3-.05-.5-.12-.7H16.6Z"/>'
  + '</svg>';

// Static markup only — never interpolate user data into this.
const SAVED_MESSAGES_AVATAR_SVG =
  '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'
  + '<path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4Z"/></svg>';

// Thread avatars route through here so the Saved (My notes) thread gets its pencil icon instead of the
// wallet-letter fallback. The nodes are REUSED across threads (activeAvatar in the conversation header), so both
// branches fully undo the other's state.
/**
 * THE TIER, ON THE PICTURE AS WELL AS THE NAME [OWNER 2026-08-24: "let's colour the icon for silver and gold too.
 * Make the background so it's immediately clear it's silver."]
 *
 * Same source of truth as the name's colour — the tone identityTone hands out — so a name and its avatar can never
 * disagree about a tier. An attribute rather than a class because the avatar's content is rewritten by both
 * branches below and a class list is easier to lose than a data attribute; CSS keys the metal off it.
 */
function applyAvatarTier(node, tone) {
  if (!node) return;
  const tier = tone === 'platho-epic' ? 'epic' : tone === 'platho-rare' ? 'rare' : null;
  if (tier) node.dataset.tier = tier;
  else delete node.dataset.tier;
}

function setThreadAvatarNode(node, thread) {
  if (!node) return;
  applyAvatarTier(node, threadDisplayTone(thread));
  // THE PIN BADGE, on the avatar of a pinned contact (the corner pin in styles.css). Set here rather than in the
  // row builder because this is the ONE place every thread avatar routes through — the list, the conversation
  // header and the share sheet — so the badge cannot appear on one surface and not another. An attribute, not a
  // child node: both branches below rewrite the avatar's content, and a child would be wiped on the next render.
  if (isThreadPinned(thread) && !isSavedMessagesThread(thread)) node.dataset.pinned = 'true';
  else delete node.dataset.pinned;
  // The same reasoning for MUTED: one place, so a silenced contact cannot look silenced in the list and ordinary
  // in the header. Without a mark the setting is invisible and reads as not having worked.
  //
  // A CHILD, not a pseudo-element: ::after is the pin's and ::before is the avatar's own glow layer, and taking
  // that one stripped the layer from every muted contact. Appended AFTER the branches below have written the
  // avatar's content, since two of them rewrite innerHTML and would drop it.
  const muted = isThreadMuted(thread) && !isSavedMessagesThread(thread);
  if (muted) node.dataset.muted = 'true';
  else delete node.dataset.muted;
  const restoreMuteBadge = () => {
    node.querySelector(':scope > .avatar-mute-badge')?.remove();
    if (!muted) return;
    const badge = document.createElement('span');
    badge.className = 'avatar-mute-badge';
    badge.setAttribute('aria-hidden', 'true');
    node.append(badge);
  };
  if (isSavedMessagesThread(thread)) {
    node.classList.remove('has-image');
    node.classList.add('avatar-saved');
    node.style.backgroundImage = '';
    delete node.dataset.avatarUrl;
    node.innerHTML = SAVED_MESSAGES_AVATAR_SVG;
    restoreMuteBadge();
    return;
  }
  node.classList.remove('avatar-saved');
  // NO PICTURE AND NO NAME -> THE MASK, not a monogram of the address (see ANONYMOUS_AVATAR_SVG). Checked on the
  // same rule the rest of the app uses for "this contact is a bare wallet": no local label, and either no identity
  // at all or one that IS the wallet address. The moment a .ath name, a local name or a picture arrives, the row
  // goes back to the ordinary avatar — the mask means "nothing to show yet", never a state of its own.
  if (!thread?.avatarImageUrl && threadIsBareWalletAddress(thread)) {
    node.classList.remove('has-image');
    node.classList.add('avatar-anonymous');
    node.style.backgroundImage = '';
    delete node.dataset.avatarUrl;
    node.innerHTML = ANONYMOUS_AVATAR_SVG;
    restoreMuteBadge();
    return;
  }
  node.classList.remove('avatar-anonymous');
  // The LETTER derives from the same string the row's title shows, AT RENDER TIME — the persisted
  // thread.avatar can carry a stale initial from an older label (history snapshot restore), which made the
  // letter flip between renders depending on which code path wrote it last (owner: "sometimes U, sometimes A").
  setAvatarNode(node, threadDisplayLabel(thread) || thread?.avatar, thread?.avatarImageUrl);
  restoreMuteBadge();
}

/** No local name, and no identity beyond the wallet address itself — the same test the channel-name resolver uses. */
function threadIsBareWalletAddress(thread) {
  if (!thread || thread.localLabel) return false;
  const identity = threadSelectedIdentity(thread);
  return !identity || identity.type === RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS;
}

// Thread-list side label: today -> clock time, this week -> weekday, else a date (year only when it differs).
function formatThreadListTimestamp(ms) {
  if (!Number.isFinite(ms) || ms <= 0) return '';
  const date = new Date(ms);
  const now = new Date();
  const dayStart = (d) => new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime();
  const dayDiff = Math.round((dayStart(now) - dayStart(date)) / 86_400_000);
  // The APP locale, not the browser one — otherwise weekday/month names contradict the chosen UI language.
  if (dayDiff <= 0) return date.toLocaleTimeString(currentLocale(), { hour: '2-digit', minute: '2-digit' });
  if (dayDiff < 7) return date.toLocaleDateString(currentLocale(), { weekday: 'short' });
  if (date.getFullYear() === now.getFullYear()) return date.toLocaleDateString(currentLocale(), { month: 'short', day: 'numeric' });
  return date.toLocaleDateString(currentLocale(), { year: 'numeric', month: 'short', day: 'numeric' });
}

function setText(node, value) {
  if (node) node.textContent = value ?? '';
}

function walletAddressForCopy(wallet = plathoWallet) {
  return wallet?.friendlyAddress ?? wallet?.address ?? '';
}

function currentWalletReceiveAddress() {
  return walletAddressForCopy(plathoWallet) || storedWalletAddressForCopy();
}

function walletTonTransferUri(address) {
  return `ton://transfer/${encodeURIComponent(address)}`;
}

function createWalletReceiveQrNode(address) {
  const wrapper = document.createElement('div');
  wrapper.className = 'wallet-receive-card';
  const image = document.createElement('img');
  image.className = 'wallet-receive-qr';
  image.alt = t('wallet.qrAlt');
  image.src = createQrSvgDataUrl(walletTonTransferUri(address), { title: t('wallet.qrTitle') });
  const addressBox = document.createElement('div');
  addressBox.className = 'wallet-receive-address';
  addressBox.textContent = address;
  wrapper.append(image, addressBox);
  return wrapper;
}

function storedPlathoWalletRecord() {
  return readEncryptedPlathoWalletRecord() ?? readLegacyPlaintextPlathoWalletRecord();
}

function storedWalletAddressForCopy(record = storedPlathoWalletRecord()) {
  if (!record?.address) return '';
  try {
    return formatTonUserFriendlyAddress(record.address, {
      testOnly: Number(record.networkGlobalId) === PLATHO_WALLET_NETWORK_GLOBAL_IDS.TESTNET,
    });
  } catch {
    return String(record.address);
  }
}

function walletDisplayIdentityStorageKey(owner = plathoWallet?.address) {
  return owner ? `${WALLET_DISPLAY_IDENTITY_STORAGE_PREFIX}:${owner}` : null;
}

// --- Per-counterparty display preference (shared by Private dialogs and Public wallet channels) ---
// The stored shape is { displayIdentity: <recipient identity or null>, localLabel: <string or null> },
// mirroring exactly the two fields a Private thread carries (thread.displayIdentity / thread.localLabel)
// so the "Display as" choice is identical in both tabs for the same wallet.
function contactDisplayPreferenceStorageKey(counterpartyWallet) {
  const raw = rawWalletAddress(counterpartyWallet);
  return raw ? `${CONTACT_DISPLAY_PREFERENCE_STORAGE_PREFIX}:${raw}` : null;
}

function normalizeContactDisplayPreference(value) {
  if (!value || typeof value !== 'object') return null;
  const displayIdentity = normalizeRecipientIdentity(value.displayIdentity) ?? null;
  const rawLabel = typeof value.localLabel === 'string' ? value.localLabel.trim() : '';
  const localLabel = rawLabel.length > 0 ? rawLabel : null;
  // "Pin contact" and "Mute contact": LOCAL flags next to the local label. Strictly boolean true — anything else
  // (absent on every entry written before each flag existed) reads as off, so old entries need no migration.
  const pinned = value.pinned === true;
  const muted = value.muted === true;
  if (!displayIdentity && !localLabel && !pinned && !muted) return null;
  return { displayIdentity, localLabel, pinned, muted };
}

function readContactDisplayPreference(counterpartyWallet) {
  const key = contactDisplayPreferenceStorageKey(counterpartyWallet);
  if (!key) return null;
  try {
    return normalizeContactDisplayPreference(JSON.parse(localStorageOrNull()?.getItem(key) ?? 'null'));
  } catch {
    return null;
  }
}

function writeContactDisplayPreference(counterpartyWallet, preference) {
  const key = contactDisplayPreferenceStorageKey(counterpartyWallet);
  if (!key) return;
  // NEVER store a "Display as" preference for your OWN wallet. The own channel / self ("My notes") thread derives
  // its name from your own linked .ath, not a per-counterparty entry (resolveWalletChannelDisplay returns early for
  // the own wallet). A stray own-wallet entry — e.g. leaked by a cross-wallet thread merge — would bleed a peer's
  // name/avatar onto your own "You" channel. Refuse it at this single chokepoint AND clear any that already leaked in
  // (self-heal for devices already poisoned before this fix).
  const own = plathoWallet?.address ?? storedPlathoWalletRecord()?.address ?? null;
  if (own && sameWalletAddress(counterpartyWallet, own)) {
    try { localStorageOrNull()?.removeItem(key); } catch { /* cosmetic self-heal; ignore */ }
    return;
  }
  // The pin flag is CARRIED, never clobbered: every pre-existing writer (thread -> store sync, the Public "Display
  // as" pick, the one-time hydrate seed) passes only { displayIdentity, localLabel }. Unless the caller says `pinned`
  // explicitly (setContactPinned is the only one that does), the flag already in the store survives the write.
  const pinned = typeof preference?.pinned === 'boolean'
    ? preference.pinned
    : (readContactDisplayPreference(counterpartyWallet)?.pinned === true);
  const normalized = normalizeContactDisplayPreference({ ...(preference ?? {}), pinned });
  try {
    if (!normalized) {
      localStorageOrNull()?.removeItem(key);
    } else {
      localStorageOrNull()?.setItem(key, JSON.stringify({
        displayIdentity: normalized.displayIdentity,
        localLabel: normalized.localLabel,
        pinned: normalized.pinned === true,
        muted: normalized.muted === true,
      }));
    }
  } catch {
    // The cross-tab display preference is cosmetic; a failed write just means no sync this time.
  }
}

// "Pin contact" — the third per-counterparty LOCAL preference (next to the local label), shared by the Private dialog
// and the Public wallet channel exactly like the display choice: one entry, one flag, both menus. Pinned dialogs sort
// above the rest (thread-list-order.mjs) in the thread list AND the share sheet. Never for the own wallet:
// writeContactDisplayPreference refuses it, and "My notes" is first by its own rule anyway.
function isContactPinned(counterpartyWallet) {
  return readContactDisplayPreference(counterpartyWallet)?.pinned === true;
}

/**
 * "MUTE CONTACT" — the fourth per-counterparty local flag, and it silences rather than blocks.
 *
 * [OWNER 2026-08-24: "add mute to the chevron, so a user can choose not to receive messages from a contact. And
 * unmute too."] What it can honestly do is stop them COUNTING: a message is published to the chain by its sender,
 * and nothing on this device can prevent it being written or read. So a muted contact's messages still arrive and
 * are still there when the dialog is opened — they raise no unread count, which is what feeds both the row's badge
 * and the Private tab's. The hint says exactly that, rather than promising a delivery block we cannot perform.
 *
 * Local and per device, like the other three: it lives in the same entry, next to the pin.
 */
function isContactMuted(counterpartyWallet) {
  return readContactDisplayPreference(counterpartyWallet)?.muted === true;
}

function setContactMuted(counterpartyWallet, muted) {
  const stored = readContactDisplayPreference(counterpartyWallet);
  writeContactDisplayPreference(counterpartyWallet, {
    displayIdentity: stored?.displayIdentity ?? null,
    localLabel: stored?.localLabel ?? null,
    pinned: stored?.pinned === true,
    muted: muted === true,
  });
  const thread = findThreadByIdentityVariants(threads, privateWalletIdentityVariants(counterpartyWallet));
  if (thread) {
    thread.muted = muted === true;
    // Muting clears what has already piled up — otherwise the badge the user just silenced stays on screen until
    // they open the dialog, which reads as the setting not having worked.
    if (muted === true) thread.unreadCount = 0;
  }
  renderThreads();
  refreshChatsRailBadge();
}

function isThreadMuted(thread) {
  return thread?.muted === true;
}

function setContactPinned(counterpartyWallet, pinned) {
  const stored = readContactDisplayPreference(counterpartyWallet);
  writeContactDisplayPreference(counterpartyWallet, {
    displayIdentity: stored?.displayIdentity ?? null,
    localLabel: stored?.localLabel ?? null,
    muted: stored?.muted === true,
    pinned: pinned === true,
  });
  // Mirror onto the live thread (if any) so the next render orders it without re-reading storage per row; a thread
  // that materializes later picks the flag up in hydrateThreadDisplayFromContactStore.
  const thread = findThreadByIdentityVariants(threads, privateWalletIdentityVariants(counterpartyWallet));
  if (thread) thread.pinned = pinned === true;
  renderThreads();
}

// Resolve how a counterparty wallet should be shown (name + identity tone) from the shared store.
// Returns null when the user has not chosen anything for this wallet (callers then keep the default
// short-address presentation).
function resolveContactDisplay(counterpartyWallet) {
  const stored = readContactDisplayPreference(counterpartyWallet);
  if (!stored) return null;
  if (stored.displayIdentity) {
    return {
      name: displayIdentityLabel(stored.displayIdentity),
      tone: identityTone(stored.displayIdentity),
      identity: stored.displayIdentity,
      localLabel: stored.localLabel ?? null,
    };
  }
  if (stored.localLabel) {
    return { name: stored.localLabel, tone: null, identity: null, localLabel: stored.localLabel };
  }
  return null;
}

// How a Public wallet channel should be shown: an explicit shared-store choice wins; otherwise mirror
// the matching Private dialog's CURRENT display (so a chat started via an .ath name shows that name in
// Public too, even with no explicit choice). Returns null to keep the default short-address name.
function resolveWalletChannelDisplay(counterpartyWallet) {
  // Own wallet FIRST: the user's own public channel (feed author name + channels list + their own posts) shows
  // their OWN .ath / profile NFT choice — parity with the Profile header. Known locally (readLinkedPlathoUsername,
  // verified at mint) so no chain read. Resolved via the address persisted in storage so it works before the full
  // wallet finishes loading, and BEFORE the per-counterparty store so a stray self-entry (only writable via the
  // old pre-wallet-load flash, now fixed) can't pin your own channel to the bare wallet address.
  const ownAddress = plathoWallet?.address ?? storedPlathoWalletRecord()?.address ?? null;
  if (ownAddress && sameWalletAddress(counterpartyWallet, ownAddress)) {
    const ownLabel = readLinkedPlathoUsername(ownAddress)?.label;
    const ownIdentity = ownLabel ? plathoUsernameIdentity(ownLabel) : null;
    // Your OWN channel shows YOUR OWN .ath (or the bare address when you have none) — and NOTHING else. RETURN here
    // unconditionally: never fall through to the per-counterparty store or the private-thread fallback below for your
    // own wallet, or a stray entry / a mis-merged thread could pin a peer's name+avatar onto your "You" channel. This
    // matters most on a brand-new wallet, which has no linked .ath to short-circuit on.
    return ownIdentity
      ? { name: displayIdentityLabel(ownIdentity), tone: identityTone(ownIdentity), identity: ownIdentity, localLabel: null }
      : null;
  }
  const explicit = resolveContactDisplay(counterpartyWallet);
  if (explicit) return explicit;
  const thread = findThreadByIdentityVariants(threads, privateWalletIdentityVariants(counterpartyWallet));
  if (thread) {
    const threadIdentity = threadSelectedIdentity(thread);
    // A private thread that only knows the BARE wallet address (no username, no local name) must NOT pin the
    // channel to that address when a chain-VERIFIED .ath exists below — the username is primary everywhere the
    // user has not chosen otherwise (owner rule). A thread that DOES carry a username or a local name still wins
    // (it reflects how the user already sees that person in Private).
    const threadIsBareAddress = !thread.localLabel
      && (!threadIdentity || threadIdentity.type === RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS);
    if (!threadIsBareAddress) {
      const name = threadDisplayLabel(thread);
      if (name) {
        return {
          name,
          tone: threadDisplayTone(thread),
          identity: threadIdentity,
          localLabel: thread.localLabel ?? null,
        };
      }
    }
  }
  // No explicit choice and no username-bearing private thread → the channel's chain-VERIFIED .ath (proven owner
  // of the linked NFT, never the raw ownerUsername claim) is the DEFAULT. This is the SAME source the "Display as"
  // chevron already offers (contactDisplayContextForWallet injects it), so the default name a subscribed channel
  // shows now MATCHES the menu instead of defaulting to the bare address the user then has to override by hand.
  const verifiedUsername = publicChannelProfileCache[channelProfileCacheKey(counterpartyWallet)]?.verifiedUsername;
  if (verifiedUsername) {
    let identity = null;
    try { identity = plathoUsernameIdentity(verifiedUsername); } catch { identity = null; }
    if (identity) {
      return { name: displayIdentityLabel(identity), tone: identityTone(identity), identity, localLabel: null };
    }
  }
  return null;
}

function linkedPlathoUsernameStorageKey(owner = plathoWallet?.address) {
  return owner ? `${LINKED_PLATHO_USERNAME_STORAGE_PREFIX}:${deploymentStorageSuffix()}:${owner}` : null;
}

function privateSenderModeStorageKey(owner = plathoWallet?.address) {
  return owner ? `${PRIVATE_SENDER_MODE_STORAGE_PREFIX}:${owner}` : null;
}

function normalizeWalletDisplayMode(value) {
  return Object.values(WALLET_DISPLAY_MODES).includes(value) ? value : WALLET_DISPLAY_MODES.ADDRESS;
}

function normalizePrivateSenderMode(value) {
  return Object.values(PRIVATE_SENDER_MODES).includes(value) ? value : PRIVATE_SENDER_MODES.SHARE;
}

function privateSenderModeLabel(value) {
  return normalizePrivateSenderMode(value) === PRIVATE_SENDER_MODES.ANONYMOUS ? t('chat.senderModeAnonymous') : t('chat.senderModeShare');
}

function normalizeWalletDisplayIdentity(input) {
  const mode = normalizeWalletDisplayMode(input?.mode);
  if (mode === WALLET_DISPLAY_MODES.ADDRESS) {
    return { mode: WALLET_DISPLAY_MODES.ADDRESS, label: '' };
  }
  if (mode === WALLET_DISPLAY_MODES.PLATHO_NFT) {
    try {
      return {
        mode,
        label: `${normalizeUsernameInput(input?.label ?? input?.value ?? '')}.ath`,
        verified_at: Number.isSafeInteger(Number(input?.verified_at)) ? Number(input.verified_at) : 0,
      };
    } catch {
      return { mode: WALLET_DISPLAY_MODES.ADDRESS, label: '' };
    }
  }
  return { mode: WALLET_DISPLAY_MODES.ADDRESS, label: '' };
}

function sameWalletAddress(left, right) {
  try {
    return parseTonAddress(left).raw === parseTonAddress(right).raw;
  } catch {
    return false;
  }
}

function rawWalletAddress(address) {
  try {
    return parseTonAddress(address).raw;
  } catch {
    return null;
  }
}

function activeWalletRuntimeAddress() {
  return activeRuntimeWalletAddress ?? plathoWallet?.address ?? null;
}

function walletScopedRuntimeChanged(nextWallet) {
  const currentAddress = activeWalletRuntimeAddress();
  if (!currentAddress || !nextWallet?.address) return false;
  return !sameWalletAddress(currentAddress, nextWallet.address);
}

function prepareWalletScopedRuntimeForWallet(wallet, reason = 'wallet replaced') {
  if (walletScopedRuntimeChanged(wallet)) {
    clearWalletScopedRuntimeState(reason);
  }
  if (wallet?.address) activeRuntimeWalletAddress = wallet.address;
}

function clearWalletScopedRuntimeState(reason = 'wallet changed') {
  for (const job of privateSendRetryJobs.values()) {
    if (job?.timer) window.clearTimeout(job.timer);
  }
  privateSendRetryJobs.clear();
  privateSendRetrySeq = 0;
  for (const job of privatePublishConfirmJobs.values()) {
    if (job?.timer) window.clearTimeout(job.timer);
  }
  privatePublishConfirmJobs.clear();
  privatePublishConfirmSeq = 0;
  for (const job of publicPublishConfirmJobs.values()) {
    if (job?.timer) window.clearTimeout(job.timer);
  }
  publicPublishConfirmJobs.clear();
  publicPostCommentsCache.clear();
  // Public-feed sync cursors are per-account context (the walk reads THIS account's subscriptions + window). Reset
  // the in-memory heads / truncation / comment cursors + the last-synced gate so the next account re-walks fresh
  // instead of inheriting this account's cursors (which would skip the re-walk and could show a stale feed/hint).
  publicAuthorIndexHeads.clear();
  publicAuthorIndexTruncated.clear();
  publicParentIndexHeads.clear();
  publicAuthorRoundCursor = 0;
  publicAuthorRoundCovered.clear();
  publicAuthorRoundStartHead = null;
  publicFeedShownCap = PUBLIC_FEED_RENDER_CAP;
  invalidatePublicSyncFastPath(); // epoch bump: an in-flight walk of the OLD account must not re-commit the cursor
  lastSyncedPublicSyncWindow = null;
  activeRuntimeWalletAddress = null;
  clearMessageAutoSyncTimer();
  clearMessageAutoSyncCountdownTimer();
  // Also cancel any pending rail Vault-balance retry so a teardown (lock / account switch) doesn't leave a get_user
  // firing later and racing the next boot's reads (one of the concurrent-connection sources on iOS WebKit).
  clearNavVaultBalanceRetryTimer();
  privateChainSyncPromise = null;
  messageAutoSyncAt = 0;
  messageAutoSyncPhase = 'idle';
  messageAutoSyncLastResult = null;
  messageAutoSyncLastErrorLabel = null;
  threads = [];
  activeThreadId = null;
  if (appShell) appShell.dataset.chatOpen = 'false';
  localIdentity = null;
  localVaultAuthKeyPair = null;
  localRecipientKeyPair = null;
  localSignedPublicBundle = null;
  localVaultDraft = null;
  // Stop the INTRO scan and drop its per-wallet K_root state — a different wallet must never inherit these (bleed).
  stopIntroReceiveLane();
  // The CONV read lane and its per-shard marks are derived from THIS wallet's conversation keys. A shard address
  // cannot collide across wallets (it is f(K_root), and K_root is per key-id pair), so inheriting them could only
  // ever suppress a re-read — but "could only skip work" is precisely how the identity-bleed class starts, and the
  // marks cost nothing to rebuild: one full pass.
  convReadLaneInstance = null;
  convBucketSeqMarks.clear();
  // The own-send time index is derived from THIS wallet's history headers (restoreHistoryWindows rebuilds it for the
  // next one); an inherited entry could only suppress an insert in the next wallet's dialog — the bleed class again.
  storedOwnSendTimes = new Map();
  cancelAllConvDeliveryConfirms();   // drop pending delivery-confirm timers so none fires against a torn-down transport
  cancelPublicPublishVisibilityChecks();   // same rule for the public side: no tick may fire against a swapped wallet
  convKeyStore = null;
  introReplayGuard = null;
  convRecoveryRestoreAttempted = false;   // a new wallet must restore its OWN conversations from recovery
  convRecoveryBackupAllowed = false;      // block backups until the new wallet's restore proves the local map is complete
  if (recoveryBackupTimer) { clearTimeout(recoveryBackupTimer); recoveryBackupTimer = null; }
  // NOTE: convRecoveryDirtySlots deliberately survives — backups deferred by a background-lock are re-armed on unlock
  // (a stale slot from a switched-away wallet self-clears: the new wallet's partition for it is empty, so it is skipped).
  localReplayStore = createMemoryReplayStore();
  encryptedMessageStore = null;
  knownVaultKeyOwnerBySignPubkey.clear();
  knownVaultKeyRecordByWallet.clear();
  // The own-raw fallback cache is wallet-scoped: it exists to survive a TRANSIENT background lock (same account),
  // and must die with the account on a switch so the previous owner's address can never leak into the next
  // account's routing guards (clearWalletScopedRuntimeState runs ONLY on a wallet change, never on a mere lock).
  lastKnownOwnWalletRaw = null;
  // Supersede any in-flight prefs background confirm so it can't stamp "saved"/"not saved" onto the NEW wallet's
  // subscription state (prefs are per-wallet). The bump makes the stranded confirm bail on its generation guard, but
  // that same guard means it will NOT release the in-flight UI it was holding — so release it HERE, or a wallet switch
  // mid-confirm would leave the Save button disabled and the global sync spinner stuck forever.
  prefsConfirmGeneration += 1;
  prefsSyncInFlight = false;
  // Drop the external-balance retry: it was chasing the OLD wallet's balance.
  clearWalletTonProfileBalanceRetry();
  // Drop the previous wallet's cached balances so the NEW wallet never inherits them — the carry-forward that keeps a
  // known balance across a failed read must not surface wallet A's funds under wallet B. The new wallet's own reads
  // repopulate this; until then the UI shows unknown ("-"/pending), which is correct.
  vaultPocketState = { wallet: { ton_balance: null, ath_balance: null } };
  privateComposerDraftsByThread.clear();   // drafts are decrypted content — they leave with the wallet
  composerDraftThreadId = null;
  if (messageInput) messageInput.value = '';
  privateImageAttachments = [];
  privateFileAttachments = [];
  setPrivateReplyDraft(null);
  setPublicCommentReplyTo(null);
  setPrivateShareDraft(null);
  setPublicShareDraft(null);
  localProfileAvatarPointer = null;
  profileAvatarLoadPromises.clear();
  delete globalThis.plathoVaultBinding;
  clearPlathoActivationReread();   // the re-read ladder was climbing for the wallet being torn down (PWA-ACTIVATION-04)
  delete globalThis.plathoLastEncryptedHistoryRestore;
  globalThis.plathoLastWalletScopedRuntimeReset = {
    reason,
    at: new Date().toISOString(),
  };
  updateImageAttachmentUi('private');
  refreshComposerCostStatus();
  renderThreads();
  renderConversation();
}

function displayWalletAddress(address) {
  try {
    return formatTonUserFriendlyAddress(address, { bounceable: false, testOnly: false });
  } catch {
    return String(address ?? '');
  }
}

// Canonical display name for a username: the bare name, WITHOUT the ".ath" suffix (the suffix lives in the stored
// identity label for routing/matching, but is never shown).
function canonicalUsernameDisplay(label) {
  return String(label ?? '').replace(/\.ath$/i, '');
}

function displayIdentityLabel(identity) {
  if (!identity) return '';
  if (identity.type === RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS) {
    return shortAddress(identity.value ?? identity.label);
  }
  // PLATHO_NFT (and any future name type) is shown canonically — never with the ".ath" suffix.
  return canonicalUsernameDisplay(identity.label ?? identity.value ?? '');
}

async function verifyWalletDisplayIdentity(mode, label, wallet = plathoWallet) {
  const normalizedMode = normalizeWalletDisplayMode(mode);
  if (normalizedMode === WALLET_DISPLAY_MODES.ADDRESS) {
    return { mode: WALLET_DISPLAY_MODES.ADDRESS, label: '' };
  }
  const owner = requireBasechainAddress(wallet?.address, 'Connected wallet');
  if (normalizedMode === WALLET_DISPLAY_MODES.PLATHO_NFT) {
    const identity = await resolvePlathoUsernameOwner(label);
    if (!sameWalletAddress(identity.ownerWallet, owner)) {
      // CODED, so the dialog can say it in the reader's language. The sentence itself stays English for the
      // console: it is a diagnostic, and the screen no longer prints it — see usernameLinkErrorText.
      const error = new Error(`${identity.label} belongs to another wallet`);
      error.code = 'PLATHO_USERNAME_OTHER_WALLET';
      throw error;
    }
    return { mode: normalizedMode, label: identity.label, verified_at: Date.now() };
  }
  return { mode: WALLET_DISPLAY_MODES.ADDRESS, label: '' };
}

function readWalletDisplayIdentity(owner = plathoWallet?.address) {
  const key = walletDisplayIdentityStorageKey(owner);
  if (!key) return { mode: WALLET_DISPLAY_MODES.ADDRESS, label: '' };
  try {
    return normalizeWalletDisplayIdentity(JSON.parse(localStorageOrNull()?.getItem(key) ?? 'null'));
  } catch {
    return { mode: WALLET_DISPLAY_MODES.ADDRESS, label: '' };
  }
}

function readPrivateSenderMode(owner = plathoWallet?.address) {
  const key = privateSenderModeStorageKey(owner);
  if (!key) return PRIVATE_SENDER_MODES.SHARE;
  try {
    return normalizePrivateSenderMode(localStorageOrNull()?.getItem(key));
  } catch {
    return PRIVATE_SENDER_MODES.SHARE;
  }
}

function writePrivateSenderMode(value, owner = plathoWallet?.address) {
  const key = privateSenderModeStorageKey(owner);
  if (!key) return PRIVATE_SENDER_MODES.SHARE;
  const normalized = normalizePrivateSenderMode(value);
  try {
    if (normalized === PRIVATE_SENDER_MODES.SHARE) {
      localStorageOrNull()?.removeItem(key);
    } else {
      localStorageOrNull()?.setItem(key, normalized);
    }
  } catch {
    // Privacy preference is local-only; failed persistence should not block send.
  }
  return normalized;
}

function currentPrivateSenderMode() {
  return readPrivateSenderMode(plathoWallet?.address);
}

function currentPrivateSenderOptions() {
  // Saved (v652): anonymity to YOURSELF is meaningless and would make a self note render as INCOMING — the
  // self detection reads payload.senderWallet, which the anonymous mode strips. Self sends always carry it.
  const savedThread = isSavedMessagesThread(activeThread());
  const includeSenderWalletMetadata = savedThread || currentPrivateSenderMode() !== PRIVATE_SENDER_MODES.ANONYMOUS;
  const linkedUsername = includeSenderWalletMetadata ? readLinkedPlathoUsername(plathoWallet?.address) : null;
  return {
    includeSenderWalletMetadata,
    senderUsername: linkedUsername?.label ?? undefined,
  };
}

// The eye follows the full send-block state (owner: an inactive composer must not show live-looking
// buttons) — wallet/thread/read-only/activation/update/reserve reasons all come from the ONE send predicate,
// so this button dims exactly when the Send button does — plus its own extra rule: notes to yourself are
// never anonymous (v652). `sendBlock` is passed in (the callers already computed it) so this adds no extra
// send-plan build on the hot refresh paths.
function privateSenderModeToggleBlockReason(sendBlock) {
  if (sendBlock) return sendBlock;
  if (isSavedMessagesThread(activeThread())) return t('chat.blockSavedAnonymous');
  return null;
}

function canTogglePrivateSenderMode() {
  return privateSenderModeToggleBlockReason(privateSendBlockReason()) === null;
}

function updatePrivateSenderModeUi(sendBlockReason = privateSendBlockReason()) {
  const mode = currentPrivateSenderMode();
  const anonymous = mode === PRIVATE_SENDER_MODES.ANONYMOUS;
  if (privateSenderModeSelect) {
    privateSenderModeSelect.value = mode;
    privateSenderModeSelect.disabled = !plathoWallet;
  }
  if (privateAnonymousButton) {
    const icon = privateAnonymousButton.querySelector('.icon');
    const blockReason = privateSenderModeToggleBlockReason(sendBlockReason);
    privateAnonymousButton.disabled = Boolean(blockReason);
    privateAnonymousButton.setAttribute('aria-pressed', anonymous ? 'true' : 'false');
    privateAnonymousButton.setAttribute(
      'aria-label',
      anonymous ? t('chat.shareWalletAddress') : t('chat.sendPseudonymously'),
    );
    privateAnonymousButton.title = blockReason ?? (anonymous
      ? t('chat.anonymousOnTooltip')
      : t('chat.anonymousOffTooltip'));
    if (icon) {
      icon.classList.toggle('icon-eye', !anonymous);
      icon.classList.toggle('icon-eye-off', anonymous);
    }
  }
}

function normalizeLinkedPlathoUsername(input) {
  try {
    return {
      mode: WALLET_DISPLAY_MODES.PLATHO_NFT,
      label: `${normalizeUsernameInput(input?.label ?? input?.value ?? input ?? '')}.ath`,
      verified_at: Number.isSafeInteger(Number(input?.verified_at)) ? Number(input.verified_at) : 0,
    };
  } catch {
    return null;
  }
}

function readLinkedPlathoUsername(owner = plathoWallet?.address) {
  const key = linkedPlathoUsernameStorageKey(owner);
  if (key) {
    try {
      const linked = normalizeLinkedPlathoUsername(JSON.parse(localStorageOrNull()?.getItem(key) ?? 'null'));
      if (linked) return linked;
    } catch {
      // A malformed local display alias should not break wallet rendering.
    }
  }
  const legacy = readWalletDisplayIdentity(owner);
  return legacy.mode === WALLET_DISPLAY_MODES.PLATHO_NFT ? normalizeLinkedPlathoUsername(legacy) : null;
}

function writeLinkedPlathoUsername(identity, owner = plathoWallet?.address) {
  const key = linkedPlathoUsernameStorageKey(owner);
  const normalized = normalizeLinkedPlathoUsername(identity);
  if (!key || !normalized) return;
  try {
    localStorageOrNull()?.setItem(key, JSON.stringify(normalized));
  } catch {
    // Local display attachment is cosmetic and can be re-linked.
  }
}

// Drop the local linked-.ath alias entirely so outgoing messages carry NO username (used when the reconcile below
// finds the name was transferred away and there is no other owned name to fall back to). Clears BOTH the linked key
// AND the legacy wallet-display fallback (readLinkedPlathoUsername reads the linked key, then falls back to the
// display identity) — ADDRESS mode removes that key too.
function clearLinkedPlathoUsername(owner = plathoWallet?.address) {
  const key = linkedPlathoUsernameStorageKey(owner);
  try { if (key) localStorageOrNull()?.removeItem(key); } catch { /* cosmetic; still works without it */ }
  writeWalletDisplayIdentity({ mode: WALLET_DISPLAY_MODES.ADDRESS }, owner);
}

function knownPlathoUsernamesStorageKey(owner = plathoWallet?.address) {
  return owner ? `${KNOWN_PLATHO_USERNAMES_STORAGE_PREFIX}:${deploymentStorageSuffix()}:${owner}` : null;
}

// The .ath names this profile is already known to own — the ones the user has successfully linked or minted on
// this device. Offered as quick-picks in the "Link Platho name" dialog so a multi-username owner doesn't retype.
// Always unions the currently-linked name. A picked name is still re-verified on submit (it could have been
// transferred away since it was last seen).
function readKnownPlathoUsernames(owner = plathoWallet?.address) {
  // DE-DUPED BY NAME, NOT BY SPELLING [OWNER 2026-08-24: "the app periodically lies about how many usernames I have.
  // I have one and always had one, and it periodically decides there are two"]. One name has two written forms here —
  // "platho" and "platho.ath" — and this list is built from sources that do not agree on which: the linked name is
  // always normalised to the suffixed form, the chain reconcile writes the suffixed form, but a quick-pick entry
  // stored by an older build, or restored from a prefs snapshot one of them published, can still be bare. A plain
  // Set kept both, and the profile row counts what this returns. Compared canonically, the first spelling seen wins
  // — which also HEALS a device already holding the pair, on the next read, with no migration.
  const seen = new Set();
  const names = [];
  const remember = (label) => {
    const text = String(label ?? '').trim();
    const canonical = knownUsernameKey(text);
    if (!text || !canonical || seen.has(canonical)) return;
    seen.add(canonical);
    names.push(text);
  };
  remember(readLinkedPlathoUsername(owner)?.label);
  const key = knownPlathoUsernamesStorageKey(owner);
  if (key) {
    try {
      const stored = JSON.parse(localStorageOrNull()?.getItem(key) ?? '[]');
      if (Array.isArray(stored)) for (const label of stored) remember(label);
    } catch {
      // A malformed local quick-pick list must not break the link dialog.
    }
  }
  return names;
}

// WHAT MAKES TWO ENTRIES THE SAME NAME. "platho" and "platho.ath" are one .ath, so every list operation here
// compares through this and never by raw string — comparing spellings is what let one name be stored, counted and
// listed twice.
function knownUsernameKey(label) {
  return canonicalUsernameDisplay(String(label ?? '').trim()).toLowerCase();
}

// Drop a name from the quick-pick list. Its counterpart existed from the day names could be ACQUIRED; this one is
// new because until now there was no place in the app where a name could be given AWAY.
function removeKnownPlathoUsername(label, owner = plathoWallet?.address) {
  const dropped = knownUsernameKey(label);
  const key = knownPlathoUsernamesStorageKey(owner);
  if (!dropped || !key) return;
  try {
    localStorageOrNull()?.setItem(key, JSON.stringify(
      readKnownPlathoUsernames(owner).filter((entry) => knownUsernameKey(entry) !== dropped),
    ));
  } catch {
    // Cosmetic quick-pick list; safe to drop on a storage failure.
  }
}

function addKnownPlathoUsername(label, owner = plathoWallet?.address) {
  const normalized = typeof label === 'string' ? label.trim() : '';
  const added = knownUsernameKey(normalized);
  const key = knownPlathoUsernamesStorageKey(owner);
  if (!normalized || !added || !key) return;
  const next = [normalized, ...readKnownPlathoUsernames(owner).filter((entry) => knownUsernameKey(entry) !== added)].slice(0, 24);
  try {
    localStorageOrNull()?.setItem(key, JSON.stringify(next));
  } catch {
    // Cosmetic quick-pick list; safe to drop on a storage failure.
  }
}

function writeWalletDisplayIdentity(identity, owner = plathoWallet?.address) {
  const key = walletDisplayIdentityStorageKey(owner);
  if (!key) return;
  const normalized = normalizeWalletDisplayIdentity(identity);
  try {
    if (normalized.mode === WALLET_DISPLAY_MODES.ADDRESS) {
      localStorageOrNull()?.removeItem(key);
    } else {
      localStorageOrNull()?.setItem(key, JSON.stringify(normalized));
    }
  } catch {
    // Display preference is cosmetic; the wallet itself still works.
  }
}

function walletDisplayName(wallet = plathoWallet) {
  const identity = readWalletDisplayIdentity(wallet?.address);
  if (identity.mode === WALLET_DISPLAY_MODES.PLATHO_NFT) {
    return canonicalUsernameDisplay(readLinkedPlathoUsername(wallet?.address)?.label) || shortAddress(walletAddressForCopy(wallet));
  }
  return shortAddress(walletAddressForCopy(wallet));
}

function walletDisplaySubtitle(wallet = plathoWallet) {
  const identity = readWalletDisplayIdentity(wallet?.address);
  if (identity.mode === WALLET_DISPLAY_MODES.PLATHO_NFT && readLinkedPlathoUsername(wallet?.address)) return t('wallet.plathoName');
  return t('wallet.ready');
}

function renderWalletIdentity(status = null) {
  try { refreshWalletBackupWarning(); } catch { /* UI not ready */ }
  if (!plathoWallet) {
    const storedRecord = storedPlathoWalletRecord();
    const hasStored = Boolean(storedRecord);
    const storedAddress = storedWalletAddressForCopy(storedRecord);
    const storedLabel = storedAddress ? shortAddress(storedAddress) : storedWalletShortLabel();
    setText(identityName, hasStored ? storedLabel : t('wallet.noWallet'));
    setText(identitySubtitle, status ?? (hasStored ? t('wallet.unlockLocal') : t('wallet.createOrImport')));
    setText(walletAddressStatus, hasStored ? storedLabel : t('wallet.notCreated'));
    setText(walletDisplayModeStatus, t('wallet.addressMode'));
    setText(linkedUsernameStatus, t('wallet.verify'));
    renderMyUsernamesStatus();
    if (walletDisplayModeSelect) walletDisplayModeSelect.value = WALLET_DISPLAY_MODES.ADDRESS;
    if (copyWalletAddressButton) copyWalletAddressButton.disabled = !storedAddress;
    return;
  }
  const identity = readWalletDisplayIdentity(plathoWallet.address);
  const linkedUsername = readLinkedPlathoUsername(plathoWallet.address);
  setText(identityName, walletDisplayName(plathoWallet));
  setText(identitySubtitle, status ?? walletDisplaySubtitle(plathoWallet));
  setText(walletAddressStatus, shortAddress(walletAddressForCopy(plathoWallet)));
  setText(walletDisplayModeStatus, identity.mode === WALLET_DISPLAY_MODES.PLATHO_NFT
    ? canonicalUsernameDisplay(linkedUsername?.label) || t('wallet.optional')
    : t('wallet.addressMode'));
  setText(linkedUsernameStatus, canonicalUsernameDisplay(linkedUsername?.label) || t('wallet.optional'));
  renderMyUsernamesStatus();
  if (walletDisplayModeSelect) walletDisplayModeSelect.value = identity.mode;
  if (copyWalletAddressButton) copyWalletAddressButton.disabled = false;
}

function setProfileActionStatus(node, text, state = '') {
  if (!node) return;
  setText(node, text);
  if (state) {
    node.dataset.state = state;
  } else {
    delete node.dataset.state;
  }
}

function setProfileAvatarPending(pending) {
  const next = Boolean(pending);
  if (plathoProfileAvatarPending === next) return;
  plathoProfileAvatarPending = next;
  refreshMessagingControls();
}

function setProfileAvatarStatus(text, state = 'busy') {
  // Any terminal outcome releases the in-flight lock so the "Set avatar" button becomes clickable
  // again: an error tone, the success tone (''), or an "avatar active"/"active, ..." status. All
  // in-flight statuses (busy/default tone) keep the lock held.
  if (state === 'error' || state === '' || /^(avatar active|active,)/.test(String(text ?? ''))) {
    setProfileAvatarPending(false);
  }
  setProfileActionStatus(setAvatarStatus, text, state);
}

function setUsernameMintStatus(text, state = 'busy') {
  setProfileActionStatus(mintUsernameStatus, text, state);
}

function flashWalletIdentityStatus(status, durationMs = 1400) {
  if (walletIdentityFlashTimer) {
    clearTimeout(walletIdentityFlashTimer);
    walletIdentityFlashTimer = null;
  }
  renderWalletIdentity(status);
  walletIdentityFlashTimer = setTimeout(() => {
    walletIdentityFlashTimer = null;
    if (identitySubtitle?.textContent === status) renderWalletIdentity();
  }, durationMs);
}

function clearWalletAutoLockTimer() {
  if (walletAutoLockTimer) {
    clearTimeout(walletAutoLockTimer);
    walletAutoLockTimer = null;
  }
}

function clearWalletUnlockPromptTimer() {
  if (walletUnlockPromptTimer) {
    clearTimeout(walletUnlockPromptTimer);
    walletUnlockPromptTimer = null;
  }
}

function scheduleWalletAutoLock() {
  clearWalletAutoLockTimer();
  if (!plathoWallet) return;
  walletAutoLockTimer = setTimeout(() => {
    lockPlathoWallet(t('wallet.locked'));
  }, WALLET_AUTO_LOCK_MS);
}

function noteWalletActivity() {
  if (plathoWallet) scheduleWalletAutoLock();
}

function markWalletUnlocked() {
  lastWalletUnlockAt = Date.now();
  walletLeftForegroundSinceUnlock = false;   // the password was just typed: this foreground stretch is theirs
  walletUnlockPromptPending = false;
  walletUnlockPromptInterrupted = false;
  // A wallet in hand settles the question the flag was holding open.
  walletUnlockPromptDeclined = false;
  clearWalletUnlockPromptTimer();
  clearBackgroundGraceLock();
}

// Reasons a background lock may be POSTPONED — never reasons it may be skipped. Every caller of this that
// answers "yes" must arm scheduleBackgroundGraceLock, or the exemption becomes a cancellation: an open action
// dialog satisfies the first clause for as long as it is on screen, which is how a modal came back from the
// background sitting on top of an unmasked app. See lockPlathoWallet.
function shouldIgnoreTransientWalletLock() {
  return Boolean(activeActionDialog)
    || (Date.now() - lastWalletUnlockAt) < WALLET_TRANSIENT_LOCK_GRACE_MS
    // Don't tear down an in-flight send on a brief background: defer the lock while signing/broadcasting
    // actively holds the key (bounded by SEND_LOCK_MAX_GRACE_MS). Confirmation is keyless and not counted.
    || shouldDeferLockForActiveSend();
}

function shouldDeferServiceWorkerReload() {
  return Boolean(plathoWallet) || Boolean(walletUnlockPromise) || shouldIgnoreTransientWalletLock();
}

function serviceWorkerUpdateReloadError() {
  return new Error('App update ready. Reload before sending.');
}

function requireNoPendingServiceWorkerAppShellReload() {
  if (!pendingServiceWorkerAppShellReload) return;
  flashWalletIdentityStatus(t('wallet.updateReadyReload'));
  throw serviceWorkerUpdateReloadError();
}

function reloadForPendingServiceWorkerAppShellUpdate() {
  if (!pendingServiceWorkerAppShellReload) return false;
  window.location.reload();
  return true;
}

// What the server is serving RIGHT NOW, identified by build rather than by version.
//
// This used to read the #appVersionLabel and compare it with the running version const, which worked only while
// the version was a per-deploy counter. Under semantic versioning the label stands still across a hotfix, so that
// comparison would answer "same version, nothing new" for a bundle that HAS changed and leave the page running
// the old code until the user closed it. The build id is the thing that moves per deploy, so it is the thing to
// compare — and it is read from the script tag, which is also what the browser will actually fetch.
async function liveAppBuildId() {
  try {
    const response = await fetch(`./?platho_version_check=${Date.now()}`, {
      cache: 'no-store',
      credentials: 'same-origin',
    });
    if (!response.ok) return null;
    const html = await response.text();
    const match = html.match(/src="\.\/app\.js\?v=([A-Za-z0-9]+)"/);
    return match ? match[1] : null;
  } catch {
    return null;
  }
}

async function handleServiceWorkerControllerChange() {
  const liveBuildId = await liveAppBuildId();
  // Either side unknown means "cannot tell", and cannot-tell must NOT reload: an empty running id compared against
  // a real live one would differ forever and reload the page on every controller change.
  if (!liveBuildId || !PLATHO_APP_BUILD_ID || liveBuildId === PLATHO_APP_BUILD_ID) {
    pendingServiceWorkerAppShellReload = false;
    refreshMessagingControls();
    return;
  }
  if (shouldDeferServiceWorkerReload()) {
    pendingServiceWorkerAppShellReload = true;
    flashWalletIdentityStatus(t('wallet.updateReadyReload'));
    refreshMessagingControls();
    return;
  }
  window.location.reload();
}

/**
 * EVERY OVERLAY THE UNLOCKED SESSION OWNS, dismissed in one call.
 *
 * The lock tears down the session that put these on screen, so they go with it — otherwise a window outlives its
 * own keys and sits over a locked app, which is both a wrong picture and a real leak (the image lightbox holds a
 * decrypted photo). It also clears the way for the unlock prompt, which refuses to open over another dialog.
 *
 * A LIST, not a chain of one-offs: the action dialog used to be the only thing the lock closed, and it happened to
 * take the lightbox with it ONLY when the lightbox had been opened from inside it. Anything added here later is
 * covered by construction. The password dialog is deliberately absent — it belongs to the LOCKED state, and this
 * function only ever runs while a wallet is still live.
 */
function closeSessionOverlays() {
  closeActionDialog(null);
  closeImageLightbox();
  closeNewChatDialog();
  closeSharePostDialog();
  closeAppearanceDialog();
  closeDocsDialog();
  hideIdentityPopover();
}

function lockPlathoWallet(status = t('wallet.locked'), options = {}) {
  if (!plathoWallet) {
    reloadForPendingServiceWorkerAppShellUpdate();
    return;
  }
  if (options.transient === true && shouldIgnoreTransientWalletLock()) {
    // A deferral is a POSTPONEMENT, and this line is what makes that true. Without it the exemptions cancelled
    // the lock outright: an open action dialog satisfies shouldIgnoreTransientWalletLock for as long as it is on
    // screen, so backgrounding with a modal up left the keys in memory and the app unmasked until the 30-minute
    // idle backstop — and on a platform that SUSPENDS timers (iOS), not even then.
    // [OWNER 2026-08-19] "Backgrounded the app with the modal open, came back and saw the modal. Closed it and
    // saw the lock screen." The modal outliving the lock and the missing mask are the same missing deadline.
    scheduleWalletAutoLock();
    scheduleBackgroundGraceLock(WALLET_TRANSIENT_LOCK_GRACE_MS);
    return;
  }
  clearWalletAutoLockTimer();
  clearBackgroundGraceLock();
  clearVaultAutoRefreshTimer();
  // The session that owned whatever dialog is on screen is being torn down on the next line, so the dialog goes
  // with it. Everything else here already does that — keys, identity, vault state, lanes, timers — and the modal
  // was the one piece of the unlocked session left standing, which is what put a live "Buy ATH" sheet on top of
  // a locked app. It ALSO clears the way for the unlock prompt: shouldOpenWalletUnlockPrompt refuses to open
  // over another dialog (rightly — one opened while already locked is the user's own), so with the stale one
  // still up there was no prompt and no boot-screen mask either, and the app just sat there unlocked-looking.
  // Only reachable with a live wallet (the guard on the first line of this function), so the dialog is by
  // definition of the unlocked session — never the password dialog, which only runs while locked.
  //
  // ALL OF THEM, NOT THE ACTION DIALOG ALONE [OWNER 2026-08-24: "I was looking at an image, then closed the window
  // and saw the lock screen. The image lightbox definitely ignores the app lock — it behaves differently from
  // every other modal. Put it on the common mechanism."] Exactly the defect the note above describes, one window
  // over: the lock closed the action dialog, and the action dialog closes the lightbox — but a lightbox opened
  // straight from a message has no action dialog above it, so nothing closed it and the picture stayed on top of
  // a locked app. Naming every overlay in one place is what stops the next window being forgotten too.
  closeSessionOverlays();
  plathoWallet = null;
  localIdentity = null;
  ownedUsernameNftsVerified = null;   // the chain count belongs to the wallet being torn down, not the next one
  clearPlathoActivationReread();      // no wallet to re-read for; the re-unlock reads activation fresh (PWA-ACTIVATION-04)
  localVaultAuthKeyPair = null;
  localRecipientKeyPair = null;
  localSignedPublicBundle = null;
  localVaultDraft = null;
  localProfileAvatarPointer = null;
  stopIntroReceiveLane();
  cancelAllConvDeliveryConfirms();   // drop pending delivery-confirm timers so none fires against a torn-down transport
  cancelPublicPublishVisibilityChecks();   // same rule for the public side: no tick may fire against a swapped wallet
  convKeyStore = null;
  introReplayGuard = null;
  convRecoveryRestoreAttempted = false;   // a new wallet must restore its OWN conversations from recovery
  convRecoveryBackupAllowed = false;      // block backups until the new wallet's restore proves the local map is complete
  if (recoveryBackupTimer) { clearTimeout(recoveryBackupTimer); recoveryBackupTimer = null; }
  // NOTE: convRecoveryDirtySlots deliberately survives — backups deferred by a background-lock are re-armed on unlock
  // (a stale slot from a switched-away wallet self-clears: the new wallet's partition for it is empty, so it is skipped).
  delete globalThis.plathoVaultBinding;
  resetVaultPocketState();
  // THE LOCK TAKES THE CONVERSATIONS WITH IT. Everything above tears down the KEYS; what those keys already
  // decrypted stayed behind — the dialog list, every loaded message, the open conversation — in memory and on
  // screen. [OWNER 2026-08-25: "on the desktop, if you do not unlock and just close the window, everything is
  // clean, there are no conversations. On mobile I can close the window and read conversations."]
  //
  // The difference was never the app, it was the platform: closing a desktop window destroys the page, so the
  // leak could not be seen there, while a phone freezes the page and hands it back intact. And the unlock prompt
  // is dismissable by design — declining reveals the app "in its locked state", which was every private message
  // still sitting on it.
  //
  // PRIVATE ONLY. Public channel rows live in this same list (rebuildThreadsFromPublicSubscriptions keys them by
  // publicChannelId) and are not secrets: the public surface is meant to work while locked, and emptying it would
  // turn a leak fix into a feature loss.
  //
  // Not clearWalletScopedRuntimeState: that one is for a wallet CHANGE and drops caches this wallet will want back
  // in a moment. Re-unlocking restores these dialogs from the local encrypted history, the same path a cold boot
  // takes — which is exactly what the desktop has been doing all along.
  threads = threads.filter((thread) => Boolean(thread.publicChannelId));
  activeThreadId = null;
  if (appShell) appShell.dataset.chatOpen = 'false';
  renderThreads();
  renderConversation();
  renderWalletIdentity();
  flashWalletIdentityStatus(status);
  setText(encryptionStatus, t('wallet.unlockRequired'));
  setText(keyAuthStatus, t('common.locked'));
  setText(vaultDraftStatus, t('common.locked'));
  setText(vaultRecordStatus, t('common.locked'));
  setText(vaultRotateStatus, t('common.locked'));
  refreshMessagingControls();
  refreshComposerPublishPolicy();
  armWalletUnlockPrompt();
  reloadForPendingServiceWorkerAppShellUpdate();
}

// FIVE MINUTES OF GRACE, EVERYWHERE [OWNER 2026-08-25: "5 minutes is more adequate. We have things like
// getting an RPC key, which can take a while. 5 minutes is not critical in my view, and it makes the app much
// easier to work with."] It used to be Telegram's alone, because Telegram backgrounds its WebView on the smallest
// interaction and locking on each one made the wallet unusable. The same is true of any app you leave to fetch
// something and come straight back to.
//
// WHAT MADE THIS SAFE TO GENERALISE: the deadline is enforced on the RETURN door by the wall clock
// (enforceBackgroundGraceLockOnReturn), not by the timer that armed it. That is why the old iOS carve-out is gone
// too: it existed because a suspended WebView freezes timers, so a deferred lock would never fire — a timer
// problem, and the timer is no longer what decides.
//
// THE COST, STATED: for these five minutes the keys stay in memory and the conversations stay on screen, so a
// phone handed to someone within that window shows them. The owner weighed that against the friction and chose
// the grace. The 30-minute idle backstop and the on-return deadline both still govern.
const BACKGROUND_LOCK_GRACE_MS = 300_000;
let backgroundGraceLockTimer = null;
let backgroundGraceLockDeadline = 0;

function clearBackgroundGraceLock() {
  if (backgroundGraceLockTimer) {
    clearTimeout(backgroundGraceLockTimer);
    backgroundGraceLockTimer = null;
  }
  backgroundGraceLockDeadline = 0;
}

/**
 * ONE deferred background lock, for every reason a background lock gets deferred — Telegram's constant WebView
 * backgrounding (a long grace, because there it is usually not a departure at all) and the transient-lock
 * exemptions in shouldIgnoreTransientWalletLock (a blip-length grace). The deferral was previously Telegram's
 * alone; the exemptions simply returned, which is why an open modal could outlive the lock indefinitely.
 *
 * The deadline is stamped ONCE per departure — the SEND_LOCK_MAX_GRACE_MS idiom — so repeated hidden events
 * while away cannot push it out. The one thing allowed to re-arm the timer against the SAME deadline is an
 * active send, below.
 */
function scheduleBackgroundGraceLock(graceMs) {
  if (backgroundGraceLockDeadline !== 0) return;
  backgroundGraceLockDeadline = Date.now() + graceMs;
  armBackgroundGraceLockTimer(graceMs);
}

function armBackgroundGraceLockTimer(delayMs) {
  if (backgroundGraceLockTimer) clearTimeout(backgroundGraceLockTimer);
  backgroundGraceLockTimer = setTimeout(() => {
    backgroundGraceLockTimer = null;
    // Back in the foreground before the deadline: that was a blip, and the return doors own it from here.
    // The hard idle auto-lock still applies either way.
    if (!document.hidden || !plathoWallet) { clearBackgroundGraceLock(); return; }
    if (shouldDeferLockForActiveSend()) {
      // A send still holds the key — don't drop the background lock, re-arm and recheck.
      // Bounded by SEND_LOCK_MAX_GRACE_MS on the send side, so this cannot loop forever.
      armBackgroundGraceLockTimer(delayMs);
      return;
    }
    clearBackgroundGraceLock();
    lockPlathoWallet(t('wallet.locked'));
  }, delayMs);
}

/**
 * The other half of the deferral, and the half a timer cannot cover: iOS suspends the page while it is away, so
 * the timer above is frozen for exactly the interval it was meant to measure and thaws only once the app is back
 * on screen. Every return door therefore settles the deadline itself, BEFORE the unlock prompt resumes — past
 * it, lock now (which masks the app and closes the modal the departed session left open); short of it, the
 * absence really was a blip and the deferral is spent.
 */
function enforceBackgroundGraceLockOnReturn() {
  const deadline = backgroundGraceLockDeadline;
  clearBackgroundGraceLock();
  if (deadline === 0 || !plathoWallet || Date.now() < deadline) return;
  // A send still holding the key is the ONE exemption allowed to outlive the deadline here, and only because of
  // where "here" is: the app is back in the foreground with the user in front of it, so a lock buys no privacy
  // and would strand exactly the send PWA-SEND-LOCK-01 exists to let finish ("complete on foreground"). The
  // hidden half above locks it regardless once SEND_LOCK_MAX_GRACE_MS is out, and the 30-minute idle backstop
  // governs from here, so this cannot become an unlocked-forever state.
  if (shouldDeferLockForActiveSend()) return;
  lockPlathoWallet(t('wallet.locked'));
}

function lockPlathoWalletForBackground() {
  // GOING AWAY STARTS A DEADLINE, IT DOES NOT LOCK. Telegram backgrounds its WebView on the smallest interaction
  // — opening its own menu, the attachment sheet, switching chats — and locking on each one made the wallet
  // unusable; leaving any app to fetch something and coming straight back is the same shape of moment, which is
  // why the grace is no longer Telegram's alone (see BACKGROUND_LOCK_GRACE_MS for the owner's decision and its
  // cost). The deadline is enforced on the RETURN door by the wall clock, so a platform that freezes timers while
  // hidden is caught all the same — which is what retired the old iOS carve-out.
  //
  // The lock below still runs for the one case the grace cannot cover: no wallet to defer, or a transient lock
  // that something on screen is holding open (shouldIgnoreTransientWalletLock, which arms its own deadline).
  if (plathoWallet && !shouldIgnoreTransientWalletLock()) {
    scheduleBackgroundGraceLock(BACKGROUND_LOCK_GRACE_MS);
    return;
  }
  lockPlathoWallet(t('wallet.locked'), { transient: true });
}

/**
 * An unlock was on screen when the app went away — the dialog may not survive, so the intent has to.
 *
 * This is ALSO the one place that knows the app has left the foreground at all (both exit doors, visibilitychange
 * and pagehide, come through here), which is why the declined flag is dropped here: "not now" was an answer about
 * the session the user was in, and going away ends it. Coming back is a new arrival.
 */
// Has the app been to the BACKGROUND since the password was last typed? The seed plate's no-prompt rule hangs on
// "the password was entered in this session", and the 5-minute background grace changed what a session is: an
// unlocked wallet can now be inherited by whoever picks the device up inside the window. A background transition
// is exactly the boundary the thief must cross and the creating user never does, so it is the test.
let walletLeftForegroundSinceUnlock = false;

function noteWalletUnlockInterruptedByBackground() {
  walletLeftForegroundSinceUnlock = true;
  if (walletUnlockPromise) walletUnlockPromptInterrupted = true;
  walletUnlockPromptDeclined = false;
}

/**
 * Coming back to the foreground, and the only place that can put the intent back: lockPlathoWallet — the other
 * caller of armWalletUnlockPrompt — returns on its first line when the wallet is already locked, which it always
 * is by the time we get here.
 *
 * Three cases, and the middle one is the [OWNER 2026-08-13] fix:
 *   interrupted  — the OS took the dialog away mid-unlock. Re-arm.
 *   neither      — locked, a stored wallet exists, and nobody has declined in this foreground session. ASK. This
 *                  used to fall to scheduleWalletUnlockPrompt, which cannot raise the pending flag and therefore
 *                  did nothing at all whenever a previous attempt had ended without a wallet.
 *   declined     — the user closed the dialog on purpose. Do NOT re-open it on every app switch; just re-schedule,
 *                  which is a no-op unless something else armed it. This is the case the old code was protecting,
 *                  and it is the only one that should have been getting that treatment.
 *
 * armWalletUnlockPrompt is idempotent and self-guarding (it refuses on a live wallet or with no stored record), so
 * calling it here cannot open a dialog over an unlocked app.
 */
function resumeWalletUnlockPrompt() {
  if (walletUnlockPromptInterrupted) {
    walletUnlockPromptInterrupted = false;
    armWalletUnlockPrompt();
    return;
  }
  if (!walletUnlockPromptDeclined) {
    armWalletUnlockPrompt();
    return;
  }
  scheduleWalletUnlockPrompt();
}

/**
 * The user closed a dialog themselves (the ✕, the labelled dismiss, a tap outside a dismissible one, Escape).
 *
 * Only that may park the unlock prompt — and it is recorded HERE, at the tap, rather than at the `if (!wallet)`
 * branch downstream, because by the time the code gets there THREE different things look identical:
 *
 *   1. the user closed the password dialog  — a real decision;
 *   2. another dialog SUPERSEDED it (openActionDialog closes whatever is open, resolving it to null) — nobody
 *      decided anything, and this needs asking again;
 *   3. readStoredPlathoWallet caught an exception and returned null (its catch swallows everything) — likewise.
 *
 * Reading "declined" off the null would have marked all three as a decision, which is exactly the complaint:
 * [OWNER 2026-08-13] "I never pressed the ✕." He did not have to. Cases 2 and 3 need no user at all.
 *
 * walletUnlockPromise is live exactly while an unlock is being awaited, so it identifies the password dialog
 * without the dialog machinery needing to know anything about wallets — the same signal
 * noteWalletUnlockInterruptedByBackground uses.
 */
function noteActionDialogUserDismissed() {
  if (walletUnlockPromise) walletUnlockPromptDeclined = true;
}

function shouldOpenWalletUnlockPrompt() {
  return Boolean(walletUnlockPromptPending)
    && !document.hidden
    && !plathoWallet
    && !walletUnlockPromise
    && !activeActionDialog
    && hasStoredPlathoWalletRecord();
}

function scheduleWalletUnlockPrompt(delayMs = 180) {
  clearWalletUnlockPromptTimer();
  if (!shouldOpenWalletUnlockPrompt()) return;
  // Re-unlock on resume (after a background auto-lock): re-show the branded overlay NOW (synchronously, before
  // paint) so the unlock dialog opens on it — not on the bare, locked-but-visible app. No-op on cold boot
  // (overlay already up) — see showBootScreenForRelock. The core-ready lift hides it after unlock.
  showBootScreenForRelock();
  walletUnlockPromptTimer = setTimeout(async () => {
    walletUnlockPromptTimer = null;
    if (!shouldOpenWalletUnlockPrompt()) {
      // The branded overlay went up ABOVE, before this timer, and something in between (a dialog opening, the app
      // being hidden again) has since made the prompt unwanted. Bailing silently would leave the overlay covering
      // the whole app with nothing behind it to lift it — a worse failure than the missing prompt this fixes.
      markBootAppReady();
      return;
    }
    walletUnlockPromptPending = false;
    try {
      const wallet = await loadPlathoWallet();
      if (!wallet) {
        // No wallet — reveal the app in its locked state (public feed still works). NOT recorded as a decline
        // here: this null covers a real dismissal, a dialog superseded by another, and a swallowed decryption
        // error alike. Whether it was a decision was decided at the tap, in noteActionDialogUserDismissed.
        markBootAppReady();
        renderWalletIdentity();
        refreshMessagingControls();
        return;
      }
      await bootCrypto();
      // Re-gate the seed backup on the AUTO unlock path too (resume / foreground /
      // startup), not just the explicit unlock button — otherwise a user who once
      // declined the gate could keep using funds with no durable backup.
      await enforceTelegramSeedBackupGate(wallet);
      flashWalletIdentityStatus(t('wallet.unlocked'));
    } catch (error) {
      // Never strand the re-unlock behind the overlay on an error.
      markBootAppReady();
      console.error(error);
      renderWalletIdentity();
      refreshMessagingControls();
    }
  }, delayMs);
}

function armWalletUnlockPrompt() {
  if (plathoWallet || !hasStoredPlathoWalletRecord()) return;
  walletUnlockPromptPending = true;
  scheduleWalletUnlockPrompt();
}

function suppressProfileAvatarPicker(durationMs = 1000) {
  profileAvatarPickerSuppressedUntil = Math.max(profileAvatarPickerSuppressedUntil, Date.now() + durationMs);
}

function isProfileAvatarPickerSuppressed() {
  return Date.now() < profileAvatarPickerSuppressedUntil;
}

async function copyTextToClipboard(text) {
  const value = String(text ?? '');
  if (!value) throw new Error('Nothing to copy');
  if (navigator.clipboard?.writeText && window.isSecureContext) {
    await navigator.clipboard.writeText(value);
    return;
  }
  const area = document.createElement('textarea');
  area.value = value;
  area.setAttribute('readonly', '');
  area.style.position = 'fixed';
  area.style.left = '-9999px';
  area.style.top = '0';
  document.body.append(area);
  area.select();
  try {
    if (!document.execCommand('copy')) throw new Error('Clipboard copy blocked');
  } finally {
    area.remove();
  }
}

function renderPaneHeaders() {
  setText(chatCountLabel, t('nav.privateChats'));
  setText(publicSubtitle, t('nav.publicChannels'));
  setText(walletSubtitle, t('common.wallet'));
  setText(profileHandle, t('nav.profile'));
}

// Pane status lines are logged only when they CHANGE: renderPublicSurface re-runs several times per background
// tick (feed sync + post-avatar + channel-avatar hydration each trigger a re-render), so logging every call
// spammed the console with identical '[public] feed' packs and buried the [platho] diagnostics that matter.
let lastLoggedPublicStatus = null;
function setPublicStatus(value) {
  if (!value || value === lastLoggedPublicStatus) return;
  lastLoggedPublicStatus = value;
  console.debug('[public]', value);
}

let lastLoggedVaultStatus = null;
function setVaultStatus(value) {
  if (!value || value === lastLoggedVaultStatus) return;
  lastLoggedVaultStatus = value;
  console.debug('[vault]', value);
}

function appendIcon(parent, icon) {
  const span = document.createElement('span');
  span.className = `icon icon-${icon}`;
  parent.append(span);
}

function threadSelectedIdentity(thread) {
  const displayIdentity = primaryThreadIdentity({ displayIdentity: thread?.displayIdentity });
  if (displayIdentity) return displayIdentity;
  if (thread?.localLabel) return null;
  // The AUTOMATIC pick reads EVERYTHING known for the counterparty, not the sticky thread.identity. That identity
  // latches onto whatever the FIRST applied history snapshot carried, so a dialog reborn from an address-era
  // snapshot wore the address forever while its proven names sat right in its own menu — and a live claim was the
  // only thing that could re-dress it, which a peer who unlinked or toggled anonymity never sends [OWNER
  // 2026-08-26: "even if he sent anonymously the name must not fall off — I still see his wallet; he wrote to me
  // non-anonymously before"]. The wallet is the identity and name ownership is public chain fact, so a claim is
  // how a name is LEARNED, never how it is kept: absence is not renunciation (the public lane's rule, now both
  // lanes'). The one honest forgetter stays the PROVEN transfer — dropThreadIdentityVariant strips the variant
  // (and the remembered claim), and this preference falls back on its own. Among several proven names the peer's
  // LAST self-declared one wins; preferredInboundIdentity ranks any name above the raw address.
  const variants = threadIdentityVariants(thread);
  return claimedThreadIdentityFromVariants(thread, variants)
    ?? preferredInboundIdentity(variants)
    ?? primaryThreadIdentity(thread);
}

// The identity the peer LAST called themselves — but only if it is among the KNOWN (verified) variants. The claim
// string is typed by the sender and proves nothing, so an unverified claim never surfaces here; this only picks
// WHICH proven name to wear when the wallet owns several.
function claimedThreadIdentityFromVariants(thread, variants) {
  const claimedIdentity = plathoUsernameIdentity(String(thread?.claimedSenderUsername ?? '').trim());
  if (!claimedIdentity) return null;
  const key = identityKey(claimedIdentity);
  return variants.find((variant) => identityKey(variant) === key) ?? null;
}

function threadDisplayLabel(thread) {
  const identity = threadSelectedIdentity(thread);
  if (identity) return displayIdentityLabel(identity);
  if (thread?.localLabel) return thread.localLabel;
  // Fallback to a stored name — strip a stray ".ath" so a thread.name that was persisted with the suffix still
  // shows canonically.
  return canonicalUsernameDisplay(thread?.name ?? '');
}

function threadDisplayTone(thread) {
  const identity = threadSelectedIdentity(thread);
  return identity ? identityTone(identity) : null;
}

function routeIdentitySubtitle(thread) {
  const identity = primaryThreadIdentity(thread);
  if (!identity) return thread?.subtitle ?? '';
  const label = displayIdentityLabel(identity);
  return label ? t('chat.identityTypeWithLabel', { type: identityTypeLabel(identity), label }) : identityTypeLabel(identity);
}

function applyThreadDisplayFields(thread) {
  if (!thread) return thread;
  // Read through the view (the thread's own variants PLUS anything else known for that wallet), write onto the
  // thread. An explicit choice still wins: threadSelectedIdentity looks at displayIdentity before any variant.
  const view = threadDisplayView(thread);
  const label = threadDisplayLabel(view);
  const identity = threadSelectedIdentity(view);
  if (label) {
    thread.name = label;
    thread.avatar = String(label || 'P').slice(0, 1).toUpperCase() || thread.avatar || 'P';
  }
  thread.subtitle = identity ? identityTypeLabel(identity) : routeIdentitySubtitle(thread);
  return thread;
}

function persistThreadDisplayPreference(thread) {
  if (!thread?.messages?.length) return;
  Promise.all((thread.messages ?? [])
    .filter((message) => message?.localHistoryId)
    .map((message) => updateMessageInEncryptedHistory(thread, message)))
    .catch((error) => console.error(error));
}

// Mirror a Private thread's "Display as" choice into the shared per-counterparty store so the same
// person's Public wallet channel shows the same name. Cheap: writes localStorage and re-overlays the
// public registry names (no render — the Public surface re-resolves names from the registry on its
// next paint / sync).
function syncThreadDisplayToContactStore(thread) {
  const wallet = ownerWalletFromThread(thread);
  if (!wallet) return;
  writeContactDisplayPreference(wallet, {
    displayIdentity: thread.displayIdentity ?? null,
    localLabel: thread.localLabel ?? null,
  });
  rebuildPublicChannelRegistry();
}

// Apply a display choice that originated in the Public tab back to the shared store AND to any live
// Private thread for the same wallet, then refresh both surfaces. This is the Public -> Private half
// of the sync (the Private -> Public half is syncThreadDisplayToContactStore above).
function applyContactDisplaySelection(counterpartyWallet, { displayIdentity = null, localLabel = null } = {}) {
  writeContactDisplayPreference(counterpartyWallet, { displayIdentity, localLabel });
  const thread = findThreadByIdentityVariants(threads, privateWalletIdentityVariants(counterpartyWallet));
  if (thread) {
    thread.displayIdentity = displayIdentity ?? null;
    if (localLabel) thread.localLabel = localLabel;
    else delete thread.localLabel;
    applyThreadDisplayFields(thread);
    persistThreadDisplayPreference(thread);
  }
  // rebuildThreadsFromPublicSubscriptions re-overlays the registry itself, so no separate rebuild here.
  rebuildThreadsFromPublicSubscriptions({ preserveActive: true });
  renderThreads();
  renderConversation();
  renderPublicSurface({ anchorUnread: false });
  // A choice made from a Discovery card's chevron (an unsubscribed channel not in the feed) must relabel that
  // card too. renderPublicSurface only rebuilds the feed; this debounced+guarded refresh re-renders the discovery
  // sample (no-op when discovery isn't on screen), so buildDiscoveryCard re-reads resolveWalletChannelDisplay.
  scheduleDiscoveryLabelRefresh();
}

// Build a thread-shaped object for a wallet that has NO open Private dialog, so the Public "Display as"
// menu can reuse the exact same option-builder (identityDisplayOptions) the Private menu uses. When a
// real Private thread exists, callers pass that instead and full parity (incl. a known .ath username)
// is automatic.
/**
 * EVERY NAME THIS APP KNOWS FOR A WALLET, wherever it learned it.
 *
 * A private dialog learns the peer's .ath from ONE source only: the senderUsername the sender stamps on a message,
 * verified against the chain. The public side learns it independently — it proves a channel's .ath against the
 * chain and remembers it — and when it builds a name it already looks INTO the private threads first. Nothing ever
 * looked the other way [OWNER 2026-08-24: "the counterparty's username gets lost in the app — this contact has one
 * and I don't see it"], so one person could be a name on the Public surface and a bare address on the Private one,
 * with the name sitting in the app the whole time.
 *
 * This is the one answer both surfaces ask, so they cannot disagree again.
 */
function walletKnownIdentityVariants(counterpartyWallet) {
  if (!counterpartyWallet) return [];
  const found = [];
  // The user's OWN wallet must offer their OWN linked username (.ath): a counterparty's name arrives on their
  // messages and posts, your own never does — you receive neither from yourself — so without this your own channel
  // and your Saved thread show the bare address while everyone else sees your name.
  if (plathoWallet?.address && sameWalletAddress(counterpartyWallet, plathoWallet.address)) {
    const ownUsername = readLinkedPlathoUsername(plathoWallet.address);
    const ownIdentity = ownUsername?.label ? plathoUsernameIdentity(ownUsername.label) : null;
    if (ownIdentity) found.push(ownIdentity);
  }
  // The channel's VERIFIED .ath — chain-proven owner of the linked NFT, never the raw ownerUsername claim.
  const verifiedUsername = publicChannelProfileCache[channelProfileCacheKey(counterpartyWallet)]?.verifiedUsername;
  if (verifiedUsername) {
    let channelIdentity = null;
    try { channelIdentity = plathoUsernameIdentity(verifiedUsername); } catch { channelIdentity = null; }
    if (channelIdentity) found.push(channelIdentity);
  }
  return found;
}

/**
 * A read-only VIEW of a thread/context carrying those names as identity variants.
 *
 * Non-mutating on purpose: the input is often a live thread object, and grafting a derived name onto it as a side
 * effect of a repaint would outlive the thing it was derived from. Recomputed instead — it is an object lookup and
 * a parse, and uniqueDisplayIdentityVariants de-dupes downstream, so a name known from two sources is one row.
 */
function withWalletKnownIdentities(context, counterpartyWallet) {
  const extra = walletKnownIdentityVariants(counterpartyWallet);
  if (extra.length === 0) return context;
  return { ...context, identityVariants: normalizeIdentityVariants([...extra, ...threadIdentityVariants(context)]) };
}

function contactDisplayContextForWallet(counterpartyWallet) {
  return withWalletKnownIdentities(baseContactDisplayContextForWallet(counterpartyWallet), counterpartyWallet);
}

// The PRIVATE surface's half of the same answer: the header title, the thread row and the "Display as" menu all
// read the thread through this, so a name the public side proved shows up in the dialog too.
function threadDisplayView(thread) {
  const wallet = thread ? ownerWalletFromThread(thread) : null;
  return wallet ? withWalletKnownIdentities(thread, wallet) : thread;
}

function baseContactDisplayContextForWallet(counterpartyWallet) {
  const existing = findThreadByIdentityVariants(threads, privateWalletIdentityVariants(counterpartyWallet));
  if (existing) return existing;
  const created = createRecipientThread(counterpartyWallet);
  const base = created.ok
    ? created.thread
    : { id: `wallet:${rawWalletAddress(counterpartyWallet) ?? counterpartyWallet}`, identityVariants: privateWalletIdentityVariants(counterpartyWallet) };
  const stored = readContactDisplayPreference(counterpartyWallet);
  if (stored?.displayIdentity) {
    base.identityVariants = normalizeIdentityVariants([stored.displayIdentity, ...threadIdentityVariants(base)]);
    base.displayIdentity = stored.displayIdentity;
  }
  if (stored?.localLabel) base.localLabel = stored.localLabel;
  return base;
}

// Pull a Private thread's display fields into line with the shared per-counterparty store. This is the
// load-time half of the Public <-> Private sync: a choice made in Public for a wallet whose dialog was
// not loaded at the time lands on the thread when it next materializes. If the store has nothing yet
// but the thread already carries a preference (a user who chose a name before this feature shipped), the
// thread seeds the store so the choice propagates to Public. Returns true when the thread changed.
//
// Runs ONCE per thread object (thread.contactDisplaySynced, a runtime-only flag not persisted in the
// thread snapshot). One-time is correct AND necessary: after the first sync every live edit updates the
// thread directly (Private via the popover callback, Public via applyContactDisplaySelection), so the
// store never gets ahead of a loaded thread. Re-running it on every renderThreads would (a) revert a
// just-made choice when the render happens before the store write, and (b) hammer localStorage on every
// keystroke-triggered render (slow-device path).
function hydrateThreadDisplayFromContactStore(thread) {
  if (!thread || thread.contactDisplaySynced) return false;
  const wallet = ownerWalletFromThread(thread);
  if (!wallet) return false; // no wallet yet (unresolved peer): retry once it resolves
  // The self/Saved ("My notes") thread must NEVER pull a display from the per-counterparty store: its label is always
  // "My notes" and its name derives from your own linked .ath. Reading a (possibly leaked) own-wallet entry here
  // would re-latch a peer's identity onto the Saved thread every session — so short-circuit for the own wallet.
  const own = plathoWallet?.address ?? storedPlathoWalletRecord()?.address ?? null;
  if (own && sameWalletAddress(wallet, own)) { thread.contactDisplaySynced = true; return false; }
  thread.contactDisplaySynced = true;
  const stored = readContactDisplayPreference(wallet);
  // The pin and the mute ride the same entry (runtime mirrors on the thread, read by thread-list-order via
  // isThreadPinned and by markIncomingThreadMessage via isThreadMuted). Set BEFORE the display compare: an entry
  // that carries only a flag carries no display choice and must not count as one.
  thread.pinned = stored?.pinned === true;
  thread.muted = stored?.muted === true;
  const storedDisplay = stored && (stored.displayIdentity || stored.localLabel) ? stored : null;
  if (!storedDisplay) {
    if (thread.displayIdentity || thread.localLabel) {
      writeContactDisplayPreference(wallet, {
        displayIdentity: thread.displayIdentity ?? null,
        localLabel: thread.localLabel ?? null,
      });
    }
    return false;
  }
  const sameIdentity = identityKey(storedDisplay.displayIdentity) === identityKey(thread.displayIdentity ?? null);
  const sameLabel = (storedDisplay.localLabel ?? null) === (thread.localLabel ?? null);
  if (sameIdentity && sameLabel) return false;
  thread.displayIdentity = storedDisplay.displayIdentity ?? null;
  if (storedDisplay.localLabel) thread.localLabel = storedDisplay.localLabel;
  else delete thread.localLabel;
  applyThreadDisplayFields(thread);
  return true;
}

function setIdentityLabel(node, thread, baseClass = 'identity-label') {
  const tone = threadDisplayTone(thread);
  // Saved display name is RENDER-ONLY (threadDisplayLabel feeds the contact store + the own public channel name).
  node.textContent = isSavedMessagesThread(thread) ? t('chat.myNotes') : threadDisplayLabel(thread);
  node.className = `${baseClass}${tone ? ` identity-label-${tone}` : ''}`;
}

function identityVariantRow(option, selected, onSelect) {
  const row = document.createElement('button');
  row.type = 'button';
  row.className = `identity-variant${option.identity ? ` identity-label-${identityTone(option.identity)}` : ''}`;
  row.setAttribute('role', 'menuitemradio');
  row.setAttribute('aria-checked', selected ? 'true' : 'false');
  const label = document.createElement('strong');
  label.textContent = option.label;
  const type = document.createElement('span');
  type.textContent = selected ? t('chat.subtitleSelected', { subtitle: option.subtitle }) : option.subtitle;
  row.append(label, type);
  row.addEventListener('click', () => onSelect(option));
  return row;
}

function identityDisplayKey(identity) {
  if (!identity) return null;
  if (identity.type === RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS) {
    const raw = rawWalletAddress(identity.value);
    if (raw) return `${identity.type}:${raw}`;
  }
  return identityKey(identity);
}

function uniqueDisplayIdentityVariants(thread) {
  const out = [];
  const seen = new Set();
  for (const identity of threadIdentityVariants(thread)) {
    const key = identityDisplayKey(identity);
    if (!key || seen.has(key)) continue;
    seen.add(key);
    out.push(identity);
  }
  return out;
}

function identityDisplayOptions(thread) {
  const options = [];
  if (thread?.localLabel) {
    options.push({
      key: 'local-label',
      label: thread.localLabel,
      subtitle: t('chat.localName'),
      identity: null,
    });
  }
  const variantOptions = [];
  for (const identity of uniqueDisplayIdentityVariants(thread)) {
    const key = identityDisplayKey(identity);
    if (!key) continue;
    variantOptions.push({
      key,
      label: displayIdentityLabel(identity),
      subtitle: identityTypeLabel(identity),
      identity,
    });
  }
  // Order: name identities (Platho NFT / TON DNS) first, alphabetically, then the raw wallet address last — so the
  // human-readable handles group together above the address. (The local name, if any, stays first; the "Set local
  // name" action is placed at the top of the popover separately.)
  variantOptions.sort((a, b) => {
    const aWallet = a.identity?.type === RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS ? 1 : 0;
    const bWallet = b.identity?.type === RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS ? 1 : 0;
    if (aWallet !== bWallet) return aWallet - bWallet;
    return String(a.label ?? '').localeCompare(String(b.label ?? ''));
  });
  options.push(...variantOptions);
  return options;
}

function selectedIdentityDisplayOptionKey(thread) {
  const selected = threadSelectedIdentity(thread);
  if (selected) return identityDisplayKey(selected);
  return thread?.localLabel ? 'local-label' : null;
}

function ensureIdentityPopover() {
  if (identityPopover) return identityPopover;
  identityPopover = document.createElement('div');
  identityPopover.className = 'identity-popover';
  identityPopover.hidden = true;
  document.body.append(identityPopover);
  return identityPopover;
}

// Place a (visible) identity popover next to its anchor using its REAL measured size, not a hardcoded guess. The old
// code clamped top against a magic 220px height, so a taller box still overflowed the bottom (description cut off) and
// low anchors snapped to a fixed line ("appears haphazardly"). The popover height is bounded by the CSS max-height, so
// this always lands the WHOLE box on-screen: below the anchor when it fits, else above it, else clamped to the top.
function positionIdentityPopover(popover, anchor) {
  if (!popover || popover.hidden || !anchor) return;
  const rect = anchor.getBoundingClientRect();
  const margin = 8;
  const w = popover.offsetWidth;
  const h = popover.offsetHeight;
  const left = Math.max(margin, Math.min(rect.left, window.innerWidth - w - margin));
  let top = rect.bottom + margin;
  if (top + h > window.innerHeight - margin) {
    const above = rect.top - margin - h;
    top = above >= margin ? above : Math.max(margin, window.innerHeight - h - margin);
  }
  popover.style.left = `${left}px`;
  popover.style.top = `${top}px`;
}

function hideIdentityPopover() {
  hidePopoverAnimated(identityPopover);
  // Reset whichever button opened the popover (Private header or a Public channel detail button).
  if (identityPopoverAnchor) {
    identityPopoverAnchor.setAttribute('aria-expanded', 'false');
    identityPopoverAnchor = null;
  }
  identityMenuButton?.setAttribute('aria-expanded', 'false');
}

// Set or edit the thread's private local label from the "Display as" menu. A thread created via New Chat
// can be given a local label up front, but a thread auto-created from an INCOMING message could not — the
// menu only ever offered an existing local-label as a display choice, never a way to add one. This closes
// that gap: any thread can now be (re)named locally. The label never leaves the device (it is not sent to
// the other side); it is persisted in the thread snapshot exactly like the displayIdentity preference.
async function promptThreadLocalLabel(thread) {
  if (!thread) return;
  const current = typeof thread.localLabel === 'string' ? thread.localLabel : '';
  const result = await openActionDialog({
    title: current ? t('chat.editLocalName') : t('chat.setLocalName'),
    hint: t('chat.localNameHint'),
    submitLabel: t('common.save'),
    fields: [
      {
        id: 'localLabel',
        label: t('chat.localName'),
        placeholder: t('chat.localNamePlaceholder'),
        value: current,
        required: false,
        autocomplete: 'off',
      },
    ],
  });
  if (!result) return;
  const next = (result.localLabel ?? '').trim();
  if (next) {
    thread.localLabel = next;
    thread.displayIdentity = null; // show the just-set local name
  } else if (thread.localLabel) {
    delete thread.localLabel;
    // The cleared label may have been the shown name; applyThreadDisplayFields falls back to the identity.
  }
  applyThreadDisplayFields(thread);
  syncThreadDisplayToContactStore(thread); // write the store BEFORE rendering (hydrate reads it)
  renderThreads();
  renderConversation();
  persistThreadDisplayPreference(thread);
}

// Public-side twin of promptThreadLocalLabel: set/edit the local name for a wallet channel that may
// have no open Private dialog. Writes the shared store (and the matching live thread, if any).
async function promptContactLocalLabel(counterpartyWallet) {
  const stored = readContactDisplayPreference(counterpartyWallet);
  const current = stored?.localLabel ?? '';
  const result = await openActionDialog({
    title: current ? t('chat.editLocalName') : t('chat.setLocalName'),
    hint: t('chat.localNameHint'),
    submitLabel: t('common.save'),
    fields: [
      {
        id: 'localLabel',
        label: t('chat.localName'),
        placeholder: t('chat.localNamePlaceholder'),
        value: current,
        required: false,
        autocomplete: 'off',
      },
    ],
  });
  if (!result) return;
  const next = (result.localLabel ?? '').trim();
  // Setting a local name clears the identity choice (mirrors promptThreadLocalLabel); clearing it falls
  // back to the wallet/identity default.
  applyContactDisplaySelection(counterpartyWallet, { displayIdentity: null, localLabel: next || null });
}

// Small inline pencil glyph for the local-name edit affordance. Kept inline (createElementNS) so it
// needs no new asset file / SW-precache entry / bundle-allowlist entry.
function createPencilIcon() {
  const ns = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(ns, 'svg');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('fill', 'none');
  svg.setAttribute('stroke', 'currentColor');
  svg.setAttribute('stroke-width', '2');
  svg.setAttribute('stroke-linecap', 'round');
  svg.setAttribute('stroke-linejoin', 'round');
  svg.setAttribute('aria-hidden', 'true');
  const path = document.createElementNS(ns, 'path');
  path.setAttribute('d', 'M12 20h9M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4 12.5-12.5z');
  svg.append(path);
  return svg;
}

// Small inline "channel about" glyph — an outline speech bubble with two short text lines ("what this channel says
// about itself"). Deliberately distinct from the (i) Docs header icon AND the document-lines "edit description"
// header icon (owner: the same icon must not sit on two different buttons), and from the filled double-bubble chat
// nav icon. Inline like createPencilIcon so it needs no new asset / SW-precache entry.
function createChannelAboutIcon() {
  const ns = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(ns, 'svg');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('fill', 'none');
  svg.setAttribute('stroke', 'currentColor');
  svg.setAttribute('stroke-width', '2');
  svg.setAttribute('stroke-linecap', 'round');
  svg.setAttribute('stroke-linejoin', 'round');
  svg.setAttribute('aria-hidden', 'true');
  const bubble = document.createElementNS(ns, 'path');
  bubble.setAttribute('d', 'M20 14a2 2 0 0 1-2 2H8l-4 4V6a2 2 0 0 1 2-2h12a2 2 0 0 1 2 2z');
  const line1 = document.createElementNS(ns, 'path');
  line1.setAttribute('d', 'M8 8h8');
  const line2 = document.createElementNS(ns, 'path');
  line2.setAttribute('d', 'M8 11.5h5');
  svg.append(bubble, line1, line2);
  return svg;
}

// Small inline copy glyph (two overlapping cards) for the "copy wallet address" affordance on the address row of
// the "Display as" popover. Inline like createPencilIcon/createChannelAboutIcon so it needs no new asset / SW-precache entry.
function createCopyIcon() {
  const ns = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(ns, 'svg');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('fill', 'none');
  svg.setAttribute('stroke', 'currentColor');
  svg.setAttribute('stroke-width', '2');
  svg.setAttribute('stroke-linecap', 'round');
  svg.setAttribute('stroke-linejoin', 'round');
  svg.setAttribute('aria-hidden', 'true');
  const rect = document.createElementNS(ns, 'rect');
  rect.setAttribute('x', '9');
  rect.setAttribute('y', '9');
  rect.setAttribute('width', '12');
  rect.setAttribute('height', '12');
  rect.setAttribute('rx', '2');
  const back = document.createElementNS(ns, 'path');
  back.setAttribute('d', 'M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1');
  svg.append(rect, back);
  return svg;
}

// Anchored popover showing a channel's PROFILE (description + tags), reusing the shared identity-popover element
// (position + outside-click-close for free). Cache-first: a warm profile renders instantly; a cold miss shows a
// loading line and resolves via resolveChannelProfile (bounded per-author walk). For the user's OWN channel the
// empty/filled states offer an add/edit affordance.
async function showChannelDescriptionPopover(authorWallet, anchor, options = {}) {
  if (!authorWallet || !anchor) return;
  const isOwn = options.isOwn === true;
  const popover = ensureIdentityPopover();
  popover.setAttribute('role', 'dialog');
  popover.replaceChildren();
  const title = document.createElement('div');
  title.className = 'identity-popover-title';
  title.textContent = t('public.channelAbout');
  const body = document.createElement('div');
  body.className = 'channel-about-popover';
  popover.append(title, body);
  const renderBody = (profile) => {
    body.replaceChildren();
    const description = typeof profile?.description === 'string' ? profile.description.trim() : '';
    const tags = (profile?.tags ?? []).filter(Boolean);
    if (description) {
      const paragraph = document.createElement('p');
      paragraph.className = 'channel-about-description';
      paragraph.textContent = description;
      body.append(paragraph);
    }
    if (tags.length > 0) {
      const tagRow = document.createElement('div');
      tagRow.className = 'channel-about-tags';
      for (const tag of tags) {
        const chip = document.createElement('span');
        chip.className = 'channel-about-tag';
        chip.textContent = `#${tag}`;
        tagRow.append(chip);
      }
      body.append(tagRow);
    }
    if (!description && tags.length === 0) {
      const empty = document.createElement('p');
      empty.className = 'channel-about-empty';
      empty.textContent = t('public.noDescriptionYet');
      body.append(empty);
    }
    // Jump from the about card straight to the channel screen (this channel's posts only).
    const openChannelButton = document.createElement('button');
    openChannelButton.type = 'button';
    openChannelButton.className = 'discovery-cta-action channel-about-open';
    openChannelButton.textContent = t('public.openChannel');
    openChannelButton.addEventListener('click', () => {
      hideIdentityPopover();
      openPublicChannelView({ authorWallet });
    });
    body.append(openChannelButton);
    if (isOwn) {
      const editButton = document.createElement('button');
      editButton.type = 'button';
      editButton.className = 'discovery-cta-action channel-about-edit';
      editButton.textContent = (description || tags.length > 0) ? t('public.editDescription') : t('public.addDescription');
      editButton.addEventListener('click', () => {
        hideIdentityPopover();
        openEditChannelProfileDialog().catch((error) => console.error(error));
      });
      body.append(editButton);
    }
  };
  const cached = cachedChannelProfile(authorWallet);
  if (cached && cached.fetchedAt) {
    renderBody(cached);
  } else {
    const loading = document.createElement('p');
    loading.className = 'channel-about-empty';
    loading.textContent = t('public.loadingDescription');
    body.append(loading);
  }
  popover.classList.remove('is-closing');   // a reopen mid-exit owns the node again (hidePopoverAnimated stands down)
  popover.hidden = false; // unhide FIRST so positionIdentityPopover can measure the real height (bounded by the CSS max-height)
  positionIdentityPopover(popover, anchor);
  if (identityPopoverAnchor && identityPopoverAnchor !== anchor) identityPopoverAnchor.setAttribute('aria-expanded', 'false');
  identityPopoverAnchor = anchor;
  anchor.setAttribute('aria-expanded', 'true');
  if (!cached || !cached.fetchedAt) {
    let resolved = null;
    try {
      resolved = await resolveChannelProfile(authorWallet);
    } catch (error) {
      resolved = cachedChannelProfile(authorWallet);
    }
    // Only repaint if THIS popover is still the one open for THIS anchor (the user may have moved on). The loaded
    // description changes the height, so re-position against the real measured size.
    if (!popover.hidden && identityPopoverAnchor === anchor) {
      renderBody(resolved);
      positionIdentityPopover(popover, anchor);
    }
  }
}

// Own-channel "add / edit description" dialog: pre-fills from the cached (or freshly resolved) current profile,
// publishes on submit via publishChannelProfile (errors surface inline, the dialog stays open), and updates the
// local cache so the owner sees their new description immediately. Tags are entered comma/newline-separated and
// normalized (lowercase/trim/dedupe/cap) by the wire codec.
async function openEditChannelProfileDialog() {
  const wallet = rawWalletAddress(plathoWallet?.address);
  if (!wallet) { setPublicStatus('channel description needs a wallet'); return; }
  if (!hasActivePlathoAccount()) { setPublicStatus('channel description needs an active account'); return; }
  let current = cachedChannelProfile(wallet);
  if (!current || !current.fetchedAt) {
    try { current = await resolveChannelProfile(wallet); } catch { current = cachedChannelProfile(wallet); }
  }
  const result = await openActionDialog({
    title: t('public.channelDescriptionTitle'),
    hint: t('public.channelDescriptionHint'),
    submitLabel: t('common.save'),
    checkingHint: t('public.descriptionSaving'),
    summary: (values) => {
      // Show the publish cost, same as the mint / avatar modals — a channel profile is a public post, so saving it
      // is paid straight from the WALLET (the attached value slightly overstates what settles, hence "up to").
      // Shares the generic GRAM-cost strings with the mint dialog. Best-effort: a pricing hiccup must never blank
      // the dialog.
      try {
        const charge = estimatedChannelProfileChargeNanotons(values.description, values.tags);
        return [{ label: t('common.cost'), value: t('common.gramCostValue', { amount: formatTonNanotons(charge) }) }];
      } catch {
        return [];
      }
    },
    fields: [
      {
        id: 'description',
        label: t('public.descriptionLabel'),
        type: 'textarea',
        placeholder: t('public.descriptionPlaceholder'),
        value: current?.description ?? '',
        required: false,
        // Live UTF-8 BYTE budget (the on-chain field is byte-capped; cyrillic is 2 bytes/char) so nothing truncates
        // silently on save. Red once over PROFILE_DESCRIPTION_MAX_BYTES.
        counter: (value) => {
          const used = utf8ByteLength(value);
          return { text: t('public.profileDescriptionBudget', { used, max: PROFILE_DESCRIPTION_MAX_BYTES }), over: used > PROFILE_DESCRIPTION_MAX_BYTES };
        },
      },
      {
        id: 'tags',
        label: t('public.tagsLabel'),
        placeholder: t('public.tagsPlaceholder'),
        value: (current?.tags ?? []).join(', '),
        required: false,
        autocomplete: 'off',
        // Count (≤PROFILE_MAX_TAGS) + per-tag byte cap; red if too many tags OR any tag exceeds PROFILE_TAG_MAX_BYTES.
        counter: (value) => {
          const raw = String(value).split(/[,\n]+/).map((s) => s.trim().toLowerCase()).filter(Boolean);
          const over = raw.length > PROFILE_MAX_TAGS || raw.some((tag) => utf8ByteLength(tag) > PROFILE_TAG_MAX_BYTES);
          return { text: t('public.profileTagsBudget', { count: raw.length, max: PROFILE_MAX_TAGS, bytes: PROFILE_TAG_MAX_BYTES }), over };
        },
      },
    ],
    validateSubmit: async (values) => {
      if (tonRpcLimited()) return { ok: false, error: t('sync.rpcBusy') };
      try {
        const description = String(values.description ?? '').trim();
        const tags = String(values.tags ?? '').split(/[,\n]+/);
        const published = await publishChannelProfile(description, tags);
        const meta = { description: published.description, tags: published.tags, ownerUsername: published.ownerUsername };
        // clean-17 direct pay: the profile IS the wallet transfer. publishPublicLaneParts throws on a failed
        // broadcast and returns { parts, result } — no Vault status, no publishState. So a RETURN means broadcast:
        // report success and show the edit immediately from the in-memory overlay. The durable cache is committed
        // by setChannelProfileFromWalk on the next walk of the author's CHANNEL shard (it carries the real entry
        // id). Reading `published.result.status` here was the clean-15 protocol: it is always undefined under
        // direct pay, so a SUCCEEDED save reported "could not save" and never surfaced the new description.
        setChannelProfileOptimistic(wallet, meta, published.createdAtSec);
        return { ok: true, result: { status: 'submitted' } };
      } catch (error) {
        if (noteTonRpcRateLimit(error)) return { ok: false, error: t('sync.rpcBusy') };
        console.error(error);
        return { ok: false, error: t('public.descriptionSaveFailed') };
      }
    },
  });
  if (result) {
    setPublicStatus('channel description saved');
    if (isPublicViewActive()) renderPublicSurface({ anchorUnread: false });
  }
}

// Generic "Display as" popover used by BOTH the Private conversation header and the Public channel
// detail header. The caller supplies the option list, the current selection, and what to do when an
// option / the local-name action is picked.
function renderDisplayAsPopover({
  options, selectedKey, localLabelExists, anchor, onSelect, onSetLocalName,
  pinned = null, onTogglePin = null, muted = null, onToggleMute = null,
}) {
  if (!anchor) return;
  const popover = ensureIdentityPopover();
  popover.setAttribute('role', 'menu');
  popover.replaceChildren();
  const title = document.createElement('div');
  title.className = 'identity-popover-title';
  title.textContent = t('chat.displayAs');
  popover.append(title);
  const openEdit = () => {
    hideIdentityPopover();
    onSetLocalName();
  };
  // "Pin contact" / "Unpin contact" — the SECOND row of the menu, right under the local-name row, in both menus
  // (Private header chevron, Public channel chevron). `pinned === null` means the row is not offered at all (the own
  // wallet / Saved). Same action-row markup as "Set local name": no new CSS, no inline styles.
  let pinRow = null;
  if (pinned !== null && typeof onTogglePin === 'function') {
    pinRow = document.createElement('button');
    pinRow.type = 'button';
    pinRow.className = 'identity-variant identity-variant-action';
    pinRow.setAttribute('role', 'menuitem');
    const pinLabel = document.createElement('strong');
    pinLabel.textContent = pinned ? t('chat.unpinContact') : t('chat.pinContact');
    const pinType = document.createElement('span');
    // Its OWN hint, not the local-name one: "Only shown on this device" is true of a label, and says nothing about
    // what pinning does. chat.pinHint — "Kept at the top of your contacts — only on this device" — says both, and
    // ships in every locale.
    pinType.textContent = t('chat.pinHint');
    pinRow.append(pinLabel, pinType);
    pinRow.addEventListener('click', () => {
      hideIdentityPopover();
      onTogglePin(!pinned);
    });
  }
  // "Mute contact" / "Unmute contact" — the second action, built the same way. `muted === null` means the row is
  // not offered (the own wallet / Saved), exactly as with the pin.
  let muteRow = null;
  if (muted !== null && typeof onToggleMute === 'function') {
    muteRow = document.createElement('button');
    muteRow.type = 'button';
    muteRow.className = 'identity-variant identity-variant-action';
    muteRow.setAttribute('role', 'menuitem');
    const muteLabel = document.createElement('strong');
    muteLabel.textContent = muted ? t('chat.unmuteContact') : t('chat.muteContact');
    const muteType = document.createElement('span');
    muteType.textContent = t('chat.muteHint');
    muteRow.append(muteLabel, muteType);
    muteRow.addEventListener('click', () => {
      hideIdentityPopover();
      onToggleMute(!muted);
    });
  }
  // Local name at the very top: when none is set yet, the "Set local name" action sits above the identities. (When
  // one IS set it's the first option in the loop below, carrying an edit pencil — already at the top.)
  if (!localLabelExists) {
    const localNameRow = document.createElement('button');
    localNameRow.type = 'button';
    localNameRow.className = 'identity-variant identity-variant-action';
    localNameRow.setAttribute('role', 'menuitem');
    const localNameLabel = document.createElement('strong');
    localNameLabel.textContent = t('chat.setLocalName');
    const localNameType = document.createElement('span');
    localNameType.textContent = t('chat.onlyShownThisDevice');
    localNameRow.append(localNameLabel, localNameType);
    localNameRow.addEventListener('click', openEdit);
    popover.append(localNameRow);
  }
  for (const option of options ?? []) {
    if (option.key === 'local-label') {
      // The local name stays a selectable display option; its edit affordance is now a pencil button
      // on the row itself instead of a separate "Edit local name" menu item.
      const row = document.createElement('div');
      row.className = 'identity-variant-localname';
      row.setAttribute('role', 'none');
      const selectRow = identityVariantRow(option, option.key === selectedKey, (selected) => {
        hideIdentityPopover();
        onSelect(selected);
      });
      const editButton = document.createElement('button');
      editButton.type = 'button';
      editButton.className = 'identity-variant-edit';
      editButton.setAttribute('role', 'menuitem');
      editButton.setAttribute('aria-label', t('chat.editLocalName'));
      editButton.title = t('chat.editLocalName');
      editButton.append(createPencilIcon());
      editButton.addEventListener('click', openEdit);
      row.append(selectRow, editButton);
      popover.append(row);
      continue;
    }
    if (option.identity?.type === RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS && option.identity.value) {
      // The raw-wallet-address option carries a copy affordance (owner request) so the full address is one tap
      // away wherever this menu appears — Private header, public post chevron, discovery card. Mirrors the
      // local-name row's select-row + trailing-icon-button layout. Copying is separate from selecting the
      // display identity, so the click is stopped from bubbling and the popover stays open for a follow-up pick.
      const row = document.createElement('div');
      row.className = 'identity-variant-localname';
      row.setAttribute('role', 'none');
      const selectRow = identityVariantRow(option, option.key === selectedKey, (selected) => {
        hideIdentityPopover();
        onSelect(selected);
      });
      const copyButton = document.createElement('button');
      copyButton.type = 'button';
      copyButton.className = 'identity-variant-edit';
      copyButton.setAttribute('role', 'menuitem');
      copyButton.setAttribute('aria-label', t('profile.copyWalletAddress'));
      copyButton.title = t('profile.copyWalletAddress');
      copyButton.append(createCopyIcon());
      const addressToCopy = option.identity.value;
      copyButton.addEventListener('click', async (event) => {
        event.stopPropagation();
        try {
          await copyTextToClipboard(addressToCopy);
          // In-place confirmation: no global toast exists, and flashWalletIdentityStatus targets the wallet
          // screen (off-screen here). Briefly tint + relabel the button, then restore. If the popover closes
          // first the node is detached and the restore is a harmless no-op.
          copyButton.classList.add('identity-variant-copied');
          copyButton.title = t('wallet.addressCopied');
          copyButton.setAttribute('aria-label', t('wallet.addressCopied'));
          window.setTimeout(() => {
            copyButton.classList.remove('identity-variant-copied');
            copyButton.title = t('profile.copyWalletAddress');
            copyButton.setAttribute('aria-label', t('profile.copyWalletAddress'));
          }, 1200);
        } catch (error) {
          console.error(error);
        }
      });
      row.append(selectRow, copyButton);
      popover.append(row);
      continue;
    }
    popover.append(identityVariantRow(option, option.key === selectedKey, (selected) => {
      hideIdentityPopover();
      onSelect(selected);
    }));
  }
  // ACTIONS ARE NOT A DISPLAY CHOICE [OWNER 2026-08-24: "the items need grouping properly. 'Display as' is only
  // about the way the contact is SHOWN, and we have mute going in there and pin already in there"]. Correct: the
  // title covers the local name and the identity options above, and neither pinning nor muting is a way of showing
  // anybody. So they get their own heading, after the list they never belonged to.
  const actionRows = [pinRow, muteRow].filter(Boolean);
  if (actionRows.length > 0) {
    const actionsTitle = document.createElement('div');
    actionsTitle.className = 'identity-popover-title';
    actionsTitle.textContent = t('chat.contactActions');
    popover.append(actionsTitle, ...actionRows);
  }
  popover.classList.remove('is-closing');   // a reopen mid-exit owns the node again (hidePopoverAnimated stands down)
  popover.hidden = false; // unhide FIRST so positionIdentityPopover can measure the real height (bounded by the CSS max-height)
  positionIdentityPopover(popover, anchor);
  // Track the opening button so its aria-expanded reflects the open state and is reset on close
  // (works for both the Private header button and a Public channel detail button).
  if (identityPopoverAnchor && identityPopoverAnchor !== anchor) {
    identityPopoverAnchor.setAttribute('aria-expanded', 'false');
  }
  identityPopoverAnchor = anchor;
  anchor.setAttribute('aria-expanded', 'true');
}

function showIdentityPopover(thread, anchor) {
  if (!thread || !anchor) return;
  // The pin lives in the shared per-counterparty store (keyed by the peer's wallet); a dialog whose peer wallet is
  // not resolved yet, or the Saved thread, gets no pin row.
  const pinWallet = isSavedMessagesThread(thread) ? null : ownerWalletFromThread(thread);
  // Through the view, so the menu offers every name known for this wallet — the Public chevron already did, and a
  // menu that lists fewer names than the other menu for the same person is how the name went missing here.
  const view = threadDisplayView(thread);
  renderDisplayAsPopover({
    options: identityDisplayOptions(view),
    selectedKey: selectedIdentityDisplayOptionKey(view),
    localLabelExists: Boolean(thread.localLabel),
    pinned: pinWallet ? isContactPinned(pinWallet) : null,
    onTogglePin: pinWallet ? (next) => setContactPinned(pinWallet, next) : null,
    muted: pinWallet ? isContactMuted(pinWallet) : null,
    onToggleMute: pinWallet ? (next) => setContactMuted(pinWallet, next) : null,
    anchor,
    onSelect: (selected) => {
      thread.displayIdentity = selected.identity ?? null;
      applyThreadDisplayFields(thread);
      syncThreadDisplayToContactStore(thread); // write the store BEFORE rendering (hydrate reads it)
      renderThreads();
      renderConversation();
      persistThreadDisplayPreference(thread);
    },
    onSetLocalName: () => {
      promptThreadLocalLabel(thread).catch((error) => console.error(error));
    },
  });
}

// "Display as" for a Public wallet channel — the menu, options, and selection semantics mirror the
// Private conversation header exactly, and every change flows through the shared store so the matching
// Private dialog stays in sync.
function showPublicChannelDisplayPopover(channel, anchor) {
  const wallet = channel?.authorWallet;
  if (!wallet || !anchor) return;
  const context = contactDisplayContextForWallet(wallet);
  // No pin for the OWN channel: the store refuses own-wallet entries, and "My notes" already leads the list.
  const ownAddress = plathoWallet?.address ?? storedPlathoWalletRecord()?.address ?? null;
  const pinnable = !(ownAddress && sameWalletAddress(wallet, ownAddress));
  renderDisplayAsPopover({
    options: identityDisplayOptions(context),
    selectedKey: selectedIdentityDisplayOptionKey(context),
    localLabelExists: Boolean(context.localLabel),
    pinned: pinnable ? isContactPinned(wallet) : null,
    onTogglePin: pinnable ? (next) => setContactPinned(wallet, next) : null,
    muted: pinnable ? isContactMuted(wallet) : null,
    onToggleMute: pinnable ? (next) => setContactMuted(wallet, next) : null,
    anchor,
    onSelect: (selected) => {
      // Re-read the local label from the store at click time (not the captured context): the user may
      // have set one via "Set local name" since this popover was built. Selecting an identity must not
      // wipe it (mirrors Private, where choosing an identity leaves thread.localLabel intact).
      const currentLocalLabel = readContactDisplayPreference(wallet)?.localLabel ?? null;
      applyContactDisplaySelection(wallet, {
        displayIdentity: selected.identity ?? null,
        localLabel: currentLocalLabel,
      });
    },
    onSetLocalName: () => {
      promptContactLocalLabel(wallet).catch((error) => console.error(error));
    },
  });
}

function renderConversationIdentity(thread) {
  const identity = threadSelectedIdentity(thread);
  const labelText = isSavedMessagesThread(thread) ? t('chat.myNotes') : threadDisplayLabel(thread);
  if (!identity) {
    activeTitle.textContent = labelText;
    if (identityMenuButton) {
      identityMenuButton.hidden = identityMenuHidden(thread);
      identityMenuButton.setAttribute('aria-label', t('chat.chooseDisplayNameFor', { name: labelText }));
      identityMenuButton.setAttribute('title', t('chat.chooseDisplayName'));
    }
    return;
  }
  const label = document.createElement('span');
  label.className = `identity-title-label identity-label-${identityTone(identity)}`;
  label.textContent = labelText;
  activeTitle.replaceChildren(label);
  if (identityMenuButton) {
    identityMenuButton.hidden = identityMenuHidden(thread);
    identityMenuButton.setAttribute('aria-label', t('chat.chooseDisplayNameFor', { name: labelText }));
    identityMenuButton.setAttribute('title', t('chat.chooseDisplayName'));
  }
}

/**
 * The chevron is not only a CHOOSER — the popover it opens always offers "Set local name" (showIdentityPopover passes
 * onSetLocalName unconditionally).
 *
 * OBSERVED 2026-08-03 on the owner's phone: a dialog named by its wallet address had no chevron at all, so there was
 * no way to rename it. The gate was `options.length <= 1`, i.e. "hide unless there are at least TWO identities to pick
 * between" — true for every inbound dialog, which has exactly one (the peer's address). Correct for a chooser, wrong
 * for a menu whose first item is an action that never depends on how many identities exist.
 *
 * Saved messages stays without one: "My notes" is the user's own dialog, and offering to re-label it as their own
 * wallet address is not a choice anyone wants.
 */
function identityMenuHidden(thread) {
  if (!thread || isSavedMessagesThread(thread)) return true;
  return false;
}

const MESSAGE_SYNC_LOADING_FRAMES = Object.freeze(['Syncing', 'Syncing.', 'Syncing..', 'Syncing...']);

function conversationSubtitleText() {
  // The sync status moved to the GLOBAL header sync indicator (spinner/check, visible on every tab), so the dialog
  // subtitle no longer carries it. Kept empty — the name above already identifies the conversation.
  return '';
}

function isGlobalSyncActive() {
  return messageAutoSyncPhase === 'syncing' || publicSyncPhase === 'syncing' || prefsSyncInFlight === true;
}

// Drive the green header sync indicator (spinner while any sync runs, check when synced) — shown in the corner on
// every tab. Toggled at every sync phase transition: private via refreshConversationSubtitle (which all private
// transitions call), public via setPublicSyncPhase, prefs via publishPrefsSnapshot.
/**
 * HOW LONG THE SPINNER ACTUALLY SPINS, and which of the three flags held it.
 *
 * MEASURED 2026-08-04: a sync TICK costs 2.7s and three requests, and the whole page had spent 16 requests since
 * load — yet the owner still saw a long "syncing". So the tick was never the thing to measure: the spinner is an
 * OR over three independent flags (private phase, public phase, prefs publish), and any one of them can hold it
 * long after the others are done. I instrumented the tick and learned it was fast, which is the right answer to
 * the wrong question. This records the spinner's own lifetime and names the flag that outlasted the rest.
 */
let globalSyncSpinnerSince = 0;
let globalSyncSpinnerHeldBy = null;

function refreshGlobalSyncIndicator() {
  const active = isGlobalSyncActive();
  if (active) {
    if (!globalSyncSpinnerSince) globalSyncSpinnerSince = Date.now();
    // WHICH flag is still up, sampled every refresh. The last sample before the spinner clears names whatever
    // outlasted the others — the OR hides that completely, and it is the whole question.
    globalSyncSpinnerHeldBy = [
      messageAutoSyncPhase === 'syncing' ? 'private' : null,
      publicSyncPhase === 'syncing' ? 'public' : null,
      prefsSyncInFlight === true ? 'prefs' : null,
    ].filter(Boolean).join('+') || 'unknown';
  }
  if (!active && globalSyncSpinnerSince) {
    const spanMs = Date.now() - globalSyncSpinnerSince;
    const heldBy = globalSyncSpinnerHeldBy;
    globalSyncSpinnerSince = 0;
    globalSyncSpinnerHeldBy = null;
    const previous = globalThis.plathoLastSpinnerSpan;
    globalThis.plathoLastSpinnerSpan = {
      at: new Date().toISOString(),
      ms: spanMs,
      heldBy,
      // The longest one seen this session — a boot that spins once is a different problem from one that spins
      // on every tick, and only the maximum tells them apart.
      maxMs: Math.max(spanMs, Number(previous?.maxMs ?? 0)),
      maxHeldBy: spanMs >= Number(previous?.maxMs ?? 0) ? heldBy : (previous?.maxHeldBy ?? null),
      spans: Number(previous?.spans ?? 0) + 1,
    };
  }
  for (const el of globalSyncIndicators) {
    el.dataset.syncing = active ? 'true' : 'false';
    // Idle = a tappable "sync now" button (see syncNowForCurrentScreen); the tooltip says so.
    el.setAttribute('aria-label', active ? t('sync.syncing') : t('sync.syncNow'));
    el.title = active ? t('sync.syncingEllipsis') : t('sync.syncNow');
  }
}

// The idle sync indicator (check mode) doubles as a "sync NOW" button (owner request), and the tap is
// CONTEXT-AWARE — it means different things on different screens: the discovery overlay wants fresh active
// channels, the Private tab wants the full manual message walk, Vault/Profile want their balances, and the
// public feed / post detail want the unified sync cycle. A tap while any sync is already running (spinner
// mode) is a no-op — the work the user wants is already happening.
function syncNowForCurrentScreen() {
  if (isGlobalSyncActive() || messageSyncManualInFlight) return;
  const view = appShell?.dataset.view;
  if (view === 'public' && publicPane?.dataset?.discoverOpen === 'true') {
    refreshPublicDiscovery().catch((error) => console.error(error));
    return;
  }
  if (view === 'chats') {
    runManualPrivateMessageSync();
    return;
  }
  if (view === 'wallet') {
    refreshVaultNow({ includeActivation: true, includeStats: true }).catch((error) => {
      const rateLimited = noteTonRpcRateLimit(error);
      setVaultStatus(rateLimited ? 'RPC busy, retrying' : 'sync blocked');
      if (!isExpectedVaultProviderUnavailable(error)) console.error(error);
    });
    return;
  }
  if (view === 'profile') {
    refreshProfilePaneReads();
    return;
  }
  // Public feed / post detail (and any future view): run the unified private+public sync cycle now
  // (1s is the scheduler's floor delay). Two gates would silently defeat an explicit tap and are reset
  // for it: the public background-sync cadence window (it skips syncPublicChannels inside its interval)
  // and the degraded-transport backoff (see scheduleMessageAutoSync's manual flag).
  lastPublicBackgroundSyncAt = 0;
  scheduleMessageAutoSync(1_000, { manual: true });
}
for (const indicator of globalSyncIndicators) {
  indicator.addEventListener('click', () => syncNowForCurrentScreen());
}

// Advance the public sync phase and, ONLY when it actually changes, repaint the public Feed so the live sync
// status updates. Gated to the active Public view + change-only so a quiet background sync does not repaint
// every cycle.
function setPublicSyncPhase(phase) {
  if (publicSyncPhase === phase) return;
  publicSyncPhase = phase;
  refreshGlobalSyncIndicator();
  if (isPublicViewActive()) renderPublicSurface({ anchorUnread: false });
}

function refreshConversationSubtitle() {
  // The global sync indicator updates on every private-sync transition (all of which call this), regardless of
  // whether a conversation is open — so refresh it first, before the no-active-thread early return.
  refreshGlobalSyncIndicator();
  const thread = activeThread();
  if (!thread || !activeSubtitle) return;
  activeSubtitle.textContent = conversationSubtitleText(thread);
}

function clearMessageAutoSyncCountdownTimer() {
  if (!messageAutoSyncCountdownTimer) return;
  window.clearTimeout(messageAutoSyncCountdownTimer);
  messageAutoSyncCountdownTimer = null;
}

function scheduleMessageAutoSyncCountdownUi() {
  clearMessageAutoSyncCountdownTimer();
  refreshConversationSubtitle();
  if (!isChatsViewActive() || document.hidden) return;
  // Only re-tick to animate the "Syncing…" frames; there is no longer a "next sync in Ns" countdown to update.
  if (messageAutoSyncPhase === 'syncing') {
    messageAutoSyncCountdownTimer = window.setTimeout(() => {
      messageAutoSyncLoadingFrame = (messageAutoSyncLoadingFrame + 1) % MESSAGE_SYNC_LOADING_FRAMES.length;
      scheduleMessageAutoSyncCountdownUi();
    }, 420);
  }
}

function beginMessageSyncUi() {
  messageAutoSyncPhase = 'syncing';
  messageAutoSyncAt = 0;
  messageAutoSyncLastErrorLabel = null;
  messageAutoSyncLoadingFrame = 0;
  scheduleMessageAutoSyncCountdownUi();
}

function completeMessageSyncUi(result) {
  messageAutoSyncLastResult = result ?? null;
  const status = privateSyncStatusText(result);
  const complete = result
    && result.ok !== false
    && result.scanComplete === true
    && result.rateLimited !== true
    && Number(result.historyUnavailableCount ?? 0) === 0
    && Number(result.skipped ?? 0) === 0
    && Number(result.incompletePrivateStreamCount ?? 0) === 0
    && Number(result.undeliveredCount ?? 0) === 0
    && !['body_history_unavailable', 'catch_up_pending', 'private_key_open_failed', 'partial_stream_pending', 'index_limit_without_cursor', 'private_entry_undelivered'].includes(String(result.reason ?? ''));
  messageAutoSyncPhase = complete ? 'synced' : 'delayed';
  messageAutoSyncLastErrorLabel = complete ? null : status;
  refreshConversationSubtitle();
}

function failMessageSyncUi(label) {
  messageAutoSyncPhase = 'delayed';
  messageAutoSyncLastErrorLabel = label || t('sync.delayed');
  refreshConversationSubtitle();
}

function openNewChatDialog() {
  if (!newChatDialog || !recipientInput || !recipientHint) return;
  recipientInput.value = '';
  if (recipientLocalLabel) recipientLocalLabel.value = '';
  recipientHint.textContent = t('chat.newChatRecipientHint');
  recipientHint.dataset.tone = 'muted';
  newChatDialog.classList.remove('is-closing'); newChatDialog.hidden = false;
  requestAnimationFrame(() => focusComposerField(recipientInput));
}

function closeNewChatDialog() {
  hideDialogAnimated(newChatDialog);
}

function collectActionDialogValues() {
  const values = {};
  for (const field of actionFields?.querySelectorAll('[name]') ?? []) {
    values[field.name] = field.type === 'checkbox' ? field.checked : field.value;
  }
  return values;
}

/** Footnotes under the submit button — explanation the reader can reach for, not wade through. */
function renderActionFootnotes(footnotes) {
  if (!actionFootnotes) return;
  const lines = (typeof footnotes === 'function' ? footnotes() : footnotes) ?? [];
  actionFootnotes.replaceChildren();
  if (!Array.isArray(lines) || lines.length === 0) {
    actionFootnotes.hidden = true;
    return;
  }
  actionFootnotes.hidden = false;
  for (const line of lines) {
    const item = document.createElement('li');
    item.textContent = String(line ?? '');
    actionFootnotes.append(item);
  }
}

function renderActionSummary(summary, values = {}) {
  if (!actionSummary) return;
  const lines = typeof summary === 'function' ? summary(values) : summary;
  actionSummary.replaceChildren();
  if (!Array.isArray(lines) || lines.length === 0) {
    actionSummary.hidden = true;
    return;
  }
  actionSummary.hidden = false;
  for (const line of lines) {
    const row = document.createElement('div');
    if (typeof line === 'string') {
      row.textContent = line;
    } else {
      const label = document.createElement('strong');
      label.textContent = t('dialog.labelPrefix', { label: line.label });
      row.append(label, document.createTextNode(String(line.value ?? '')));
    }
    actionSummary.append(row);
  }
}

function createActionField(field) {
  if (field.type === 'custom') {
    const wrapper = document.createElement('div');
    wrapper.className = field.className ?? 'action-custom-field';
    const rendered = typeof field.render === 'function' ? field.render() : field.node;
    if (rendered instanceof Node) wrapper.append(rendered);
    return wrapper;
  }
  if (field.type === 'credential-username') {
    const input = document.createElement('input');
    input.type = 'text';
    input.id = field.id;
    input.name = field.name ?? 'username';
    input.value = field.value ?? '';
    input.autocomplete = field.autocomplete ?? 'username';
    input.className = 'password-manager-username';
    input.tabIndex = -1;
    input.setAttribute('aria-hidden', 'true');
    input.style.position = 'fixed';
    input.style.left = '-10000px';
    input.style.top = '0';
    input.style.width = '1px';
    input.style.height = '1px';
    input.style.opacity = '0.01';
    input.style.pointerEvents = 'none';
    input.required = false;
    return input;
  }
  if (field.type === 'hidden') {
    const input = document.createElement('input');
    input.type = 'hidden';
    input.id = field.id;
    input.name = field.name ?? field.id;
    input.value = field.value ?? '';
    if (field.autocomplete) input.autocomplete = field.autocomplete;
    return input;
  }
  const wrapper = document.createElement('div');
  wrapper.className = field.type === 'checkbox' ? 'action-field action-checkbox-field' : 'action-field';
  const label = document.createElement('label');
  label.htmlFor = field.id;
  label.textContent = field.label;
  if (field.type === 'checkbox') {
    const input = document.createElement('input');
    input.type = 'checkbox';
    input.id = field.id;
    input.name = field.name ?? field.id;
    input.checked = field.checked === true;
    input.required = field.required !== false;
    const text = document.createElement('span');
    text.textContent = field.label;
    label.textContent = '';
    label.append(input, text);
    wrapper.append(label);
    return wrapper;
  }
  if (field.type === 'image-preview') {
    const card = document.createElement('div');
    card.className = 'image-preview-card';
    const image = document.createElement('img');
    image.id = field.id;
    image.alt = field.alt ?? t('dialog.imagePreviewAlt');
    image.loading = 'eager';
    image.tabIndex = 0;
    image.setAttribute('role', 'button');
    image.title = t('dialog.openFullSizePreview');
    const meta = document.createElement('div');
    meta.id = field.metaId ?? `${field.id}Meta`;
    meta.className = 'image-preview-meta';
    meta.textContent = field.meta ?? t('dialog.preparingPreview');
    card.append(image, meta);
    wrapper.append(label, card);
    return wrapper;
  }
  if (field.type === 'note') {
    // Purely informational block (no label, no [name] — not collected as a value): an intro line and/or a
    // numbered steps list, used by explanatory dialogs like the "Get an RPC key" help modal.
    const note = document.createElement('div');
    note.className = 'action-note';
    if (field.text) {
      const para = document.createElement('p');
      para.textContent = field.text;
      note.append(para);
    }
    if (Array.isArray(field.steps) && field.steps.length > 0) {
      const list = document.createElement('ol');
      list.className = 'action-note-steps';
      for (const step of field.steps) {
        const item = document.createElement('li');
        item.textContent = step;
        list.append(item);
      }
      note.append(list);
    }
    return note;
  }
  let input;
  if (field.type === 'textarea') {
    input = document.createElement('textarea');
  } else if (field.type === 'select') {
    input = document.createElement('select');
    for (const option of field.options ?? []) {
      const item = document.createElement('option');
      item.value = option.value;
      item.textContent = option.label;
      input.append(item);
    }
  } else {
    input = document.createElement('input');
    input.type = field.type ?? 'text';
  }
  input.id = field.id;
  input.name = field.name ?? field.id;
  if (field.placeholder) input.placeholder = field.placeholder;
  if (field.inputMode) input.inputMode = field.inputMode;
  if (field.autocomplete) input.autocomplete = field.autocomplete;
  if (field.autocapitalize) input.autocapitalize = field.autocapitalize;
  if (field.spellcheck !== undefined) input.spellcheck = Boolean(field.spellcheck);
  if (field.minLength) input.minLength = field.minLength;
  if (field.maxLength) input.maxLength = field.maxLength;
  if (field.readOnly) input.readOnly = true;
  if (field.required !== false) input.required = true;
  input.value = field.value ?? '';
  wrapper.append(label, input);
  // Optional live counter (e.g. UTF-8 byte budget for an on-chain field): field.counter(value) -> { text, over }.
  // Recomputed on every input so nothing silently truncates on save; `is-over` flags an exceeded budget in red.
  if (typeof field.counter === 'function') {
    const counter = document.createElement('span');
    counter.className = 'action-dialog-field-counter';
    const updateCounter = () => {
      const info = field.counter(input.value);
      counter.textContent = info?.text ?? '';
      counter.classList.toggle('is-over', Boolean(info?.over));
    };
    input.addEventListener('input', updateCounter);
    updateCounter();
    wrapper.append(counter);
  }
  return wrapper;
}

// v794: modals dismiss ONLY via their explicit ✕ / Cancel — an outside/backdrop tap no longer closes them (a
// stray tap outside used to discard in-progress input). Default-deny: a plain backdrop never closes on tap.
// Two deliberate exceptions keep the outside-tap gesture: the action dialog can opt in per-open via
// dismissOnBackdrop:true (default false), and the image lightbox opts in via allowOutsideTap (a fullscreen
// viewer, not a data dialog — tap-to-dismiss is the expected gesture there).
function closeOnBackdropClick(backdrop, close, { allowOutsideTap = false } = {}) {
  if (!backdrop) return;
  let pointerStartedOnBackdrop = false;
  backdrop.addEventListener('pointerdown', (event) => {
    pointerStartedOnBackdrop = event.target === backdrop;
  });
  backdrop.addEventListener('click', (event) => {
    if (event.target !== backdrop || !pointerStartedOnBackdrop) return;
    pointerStartedOnBackdrop = false;
    if (backdrop === actionDialog) {
      // Action dialogs are X-only unless a caller explicitly opted back into outside-dismiss.
      if (activeActionDialog?.dismissOnBackdrop === false) return;
      close(event);
      return;
    }
    if (!allowOutsideTap) return; // every other modal: closes ONLY via its ✕ / Cancel control
    close(event);
  });
}

function openImageLightbox(src, meta = '') {
  if (!imageLightboxDialog || !imageLightboxImage) return;
  if (!src) return;
  imageLightboxPreviousFocus = document.activeElement instanceof HTMLElement ? document.activeElement : null;
  resetImageLightboxZoom();
  imageLightboxImage.src = src;
  if (imageLightboxMeta) {
    // A fresh open owns the caption: a 'Saved' confirmation left over from the previous picture must not be
    // restored on top of this one when its timer fires.
    delete imageLightboxMeta.dataset.caption;
    imageLightboxMeta.textContent = meta || t('common.finalCompressedImage');
  }
  if (imageLightboxDownloadButton) imageLightboxDownloadButton.disabled = false;
  imageLightboxDialog.classList.remove('is-closing');
  imageLightboxDialog.hidden = false;
  imageLightboxCloseButton?.focus();
}

// Animated hide for every modal backdrop (owner: the QR/receive dialog and friends closed with no exit
// animation, unlike the lightbox). The .is-closing class runs the shared CSS fade/pop-out; the real hidden
// lands on a matched timer. A reopen clears the class first, so a stale close timer can never swallow a
// dialog that was reopened meanwhile.
// `onHidden` runs once the backdrop is actually hidden — immediately under reduced motion, after the exit
// animation otherwise, and NOT AT ALL if the dialog was reopened mid-exit (the opener owns the content then).
function hideDialogAnimated(backdrop, onHidden = null) {
  if (!backdrop || backdrop.hidden) { if (typeof onHidden === 'function') onHidden(); return; }
  if (backdrop.classList.contains('is-closing')) return;
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    backdrop.hidden = true;
    if (typeof onHidden === 'function') onHidden();
    return;
  }
  backdrop.classList.add('is-closing');
  window.setTimeout(() => {
    if (!backdrop.classList.contains('is-closing')) return;   // reopened mid-animation
    backdrop.classList.remove('is-closing');
    backdrop.hidden = true;
    if (typeof onHidden === 'function') onHidden();
  }, 200);
}

// Popovers (the "display as" menu, the emoji picker) leave the way they came: popIn on open, popOut on close (owner:
// every menu exits with motion, not a cut). Reopened mid-exit: the opener clears .is-closing and unhides, and the
// timer stands down. Reduced motion hides at once.
function hidePopoverAnimated(popover) {
  if (!popover || popover.hidden) return;
  if (popover.classList.contains('is-closing')) return;
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) { popover.hidden = true; return; }
  popover.classList.add('is-closing');
  window.setTimeout(() => {
    if (!popover.classList.contains('is-closing')) return;   // reopened mid-animation
    popover.classList.remove('is-closing');
    popover.hidden = true;
  }, 160);
}

function closeImageLightbox() {
  if (!imageLightboxDialog || imageLightboxDialog.hidden) return;
  if (imageLightboxDialog.classList.contains('is-closing')) return;
  // Mirror of the open animation (owner): display:none cannot animate, so the exit fade/pop runs first and
  // the actual hide lands on a timer matched to the CSS duration (reduced motion closes instantly).
  const finishClose = () => {
    imageLightboxDialog.classList.remove('is-closing');
    imageLightboxDialog.hidden = true;
    imageLightboxImage?.removeAttribute('src');
    resetImageLightboxZoom();
    if (imageLightboxDownloadButton) imageLightboxDownloadButton.disabled = true;
    const focusTarget = imageLightboxPreviousFocus;
    imageLightboxPreviousFocus = null;
    focusTarget?.focus?.();
  };
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    finishClose();
    return;
  }
  imageLightboxDialog.classList.add('is-closing');
  window.setTimeout(() => {
    if (imageLightboxDialog.classList.contains('is-closing')) finishClose();
  }, 200);
}

// --- Lightbox zoom/pan engine: pinch (touch), drag-pan when zoomed, double-tap / double-click toggle, wheel ---
// Transforms are applied via CSSOM property assignment (allowed under the prod CSP style-src 'self' — what CSP
// blocks is setAttribute('style'); the avatar backgroundImage path proves CSSOM works live). Geometry: the img's
// untransformed layout box is grid-centered in the viewport; with transform-origin 0 0 and
// transform = translate(tx,ty) scale(s), keeping a screen point fixed across a scale change is
//   t' = t + (point - imgRect.topLeft) * (1 - s'/s)
const IMAGE_LIGHTBOX_MAX_SCALE = 8;
const imageLightboxZoom = { scale: 1, tx: 0, ty: 0 };
const imageLightboxPointers = new Map();
let imageLightboxPinchDistance = 0;
let imageLightboxLastTap = { time: 0, x: 0, y: 0 };

function applyImageLightboxZoom(animated = false) {
  if (!imageLightboxImage) return;
  const zoomed = imageLightboxZoom.scale > 1.001;
  imageLightboxImage.classList.toggle('is-zoom-animated', animated === true);
  imageLightboxImage.classList.toggle('is-zoomed', zoomed);
  // Explicit identity at rest (not '') so an animated zoom-OUT interpolates instead of snapping to `none`.
  imageLightboxImage.style.transform = zoomed || animated === true
    ? `translate(${imageLightboxZoom.tx}px, ${imageLightboxZoom.ty}px) scale(${imageLightboxZoom.scale})`
    : '';
}

function resetImageLightboxZoom() {
  imageLightboxZoom.scale = 1;
  imageLightboxZoom.tx = 0;
  imageLightboxZoom.ty = 0;
  imageLightboxPointers.clear();
  imageLightboxPinchDistance = 0;
  applyImageLightboxZoom(false);
}

// Keep the image anchored: centered on an axis it fits, covering the viewport on an axis it overflows (a pan can
// never fling it away and leave an empty box). Derivation: rest top-left is centered, scaling grows from 0 0, so
// the centered translation is (base - scaled)/2 and the cover band is that ± (scaled - viewport)/2.
function clampImageLightboxPan() {
  if (!imageLightboxViewport || !imageLightboxImage) return;
  const scale = imageLightboxZoom.scale;
  const viewportW = imageLightboxViewport.clientWidth;
  const viewportH = imageLightboxViewport.clientHeight;
  const baseW = imageLightboxImage.offsetWidth;
  const baseH = imageLightboxImage.offsetHeight;
  const scaledW = baseW * scale;
  const scaledH = baseH * scale;
  const centerX = (baseW - scaledW) / 2;
  if (scaledW <= viewportW) {
    imageLightboxZoom.tx = centerX;
  } else {
    const band = (scaledW - viewportW) / 2;
    imageLightboxZoom.tx = Math.min(centerX + band, Math.max(centerX - band, imageLightboxZoom.tx));
  }
  const centerY = (baseH - scaledH) / 2;
  if (scaledH <= viewportH) {
    imageLightboxZoom.ty = centerY;
  } else {
    const band = (scaledH - viewportH) / 2;
    imageLightboxZoom.ty = Math.min(centerY + band, Math.max(centerY - band, imageLightboxZoom.ty));
  }
}

function zoomImageLightboxAt(clientX, clientY, nextScale, animated = false) {
  if (!imageLightboxImage) return;
  const target = Math.min(IMAGE_LIGHTBOX_MAX_SCALE, Math.max(1, nextScale));
  const rect = imageLightboxImage.getBoundingClientRect();
  const factor = target / imageLightboxZoom.scale;
  imageLightboxZoom.tx += (clientX - rect.left) * (1 - factor);
  imageLightboxZoom.ty += (clientY - rect.top) * (1 - factor);
  imageLightboxZoom.scale = target;
  clampImageLightboxPan();
  applyImageLightboxZoom(animated);
}

function imageLightboxPointerSpread() {
  const [a, b] = [...imageLightboxPointers.values()];
  return Math.hypot(a.x - b.x, a.y - b.y);
}

function toggleImageLightboxZoomAt(clientX, clientY) {
  zoomImageLightboxAt(clientX, clientY, imageLightboxZoom.scale > 1.001 ? 1 : 2.5, true);
}

imageLightboxViewport?.addEventListener('pointerdown', (event) => {
  if (!imageLightboxImage?.src) return;
  try { imageLightboxViewport.setPointerCapture(event.pointerId); } catch { /* unsupported */ }
  imageLightboxPointers.set(event.pointerId, { x: event.clientX, y: event.clientY });
  if (imageLightboxPointers.size === 2) imageLightboxPinchDistance = imageLightboxPointerSpread();
  // Double-tap (touch): dblclick does not fire for touch in all engines, so detect it from pointerdown pairs.
  if (event.pointerType === 'touch' && imageLightboxPointers.size === 1) {
    const now = Date.now();
    const isDoubleTap = now - imageLightboxLastTap.time < 350
      && Math.hypot(event.clientX - imageLightboxLastTap.x, event.clientY - imageLightboxLastTap.y) < 40;
    imageLightboxLastTap = { time: now, x: event.clientX, y: event.clientY };
    if (isDoubleTap) {
      toggleImageLightboxZoomAt(event.clientX, event.clientY);
      imageLightboxLastTap = { time: 0, x: 0, y: 0 };
    }
  }
});

imageLightboxViewport?.addEventListener('pointermove', (event) => {
  const pointer = imageLightboxPointers.get(event.pointerId);
  if (!pointer) return;
  const previousX = pointer.x;
  const previousY = pointer.y;
  pointer.x = event.clientX;
  pointer.y = event.clientY;
  if (imageLightboxPointers.size === 2) {
    // Pinch: each finger contributes half the midpoint drift (pan), and the spread ratio scales toward the
    // midpoint. touch-action: none on the viewport keeps the browser's own gestures out of the way.
    imageLightboxZoom.tx += (pointer.x - previousX) / 2;
    imageLightboxZoom.ty += (pointer.y - previousY) / 2;
    const spread = imageLightboxPointerSpread();
    if (imageLightboxPinchDistance > 0 && spread > 0) {
      const [a, b] = [...imageLightboxPointers.values()];
      zoomImageLightboxAt((a.x + b.x) / 2, (a.y + b.y) / 2, imageLightboxZoom.scale * (spread / imageLightboxPinchDistance));
    }
    imageLightboxPinchDistance = spread;
    event.preventDefault();
  } else if (imageLightboxPointers.size === 1 && imageLightboxZoom.scale > 1.001) {
    imageLightboxZoom.tx += pointer.x - previousX;
    imageLightboxZoom.ty += pointer.y - previousY;
    clampImageLightboxPan();
    applyImageLightboxZoom(false);
    event.preventDefault();
  }
});

function releaseImageLightboxPointer(event) {
  imageLightboxPointers.delete(event.pointerId);
  if (imageLightboxPointers.size < 2) imageLightboxPinchDistance = 0;
}
imageLightboxViewport?.addEventListener('pointerup', releaseImageLightboxPointer);
imageLightboxViewport?.addEventListener('pointercancel', releaseImageLightboxPointer);

imageLightboxViewport?.addEventListener('wheel', (event) => {
  if (!imageLightboxImage?.src) return;
  event.preventDefault();
  const factor = Math.exp(-event.deltaY * 0.0022);
  zoomImageLightboxAt(event.clientX, event.clientY, imageLightboxZoom.scale * factor, false);
}, { passive: false });

imageLightboxViewport?.addEventListener('dblclick', (event) => {
  if (!imageLightboxImage?.src) return;
  event.preventDefault();
  toggleImageLightboxZoomAt(event.clientX, event.clientY);
});

// No NATIVE page zoom anywhere (owner request): iOS Safari ignores user-scalable=no, but its WebKit-only
// gesture* events are cancelable — killing them kills the pinch page zoom. Unconditional on purpose: the
// lightbox zooms via its OWN pointer/transform machinery (touch-action:none viewport), so the native page
// zoom is unwanted even there. No-op on non-WebKit (the events never fire).
for (const gestureEventType of ['gesturestart', 'gesturechange', 'gestureend']) {
  document.addEventListener(gestureEventType, (event) => event.preventDefault(), { passive: false });
}

function imageDownloadExtension(src) {
  const match = String(src ?? '').match(/^data:image\/([a-z0-9.+-]+)[;,]/i);
  const type = (match?.[1] ?? 'webp').toLowerCase();
  if (type === 'jpeg') return 'jpg';
  if (/^[a-z0-9]+$/.test(type)) return type;
  return 'webp';
}

function imageLightboxDownloadFilename(src) {
  const stamp = new Date().toISOString().replace(/[-:]/g, '').replace(/\..+$/, '').replace('T', '-');
  return `platho-image-${stamp}.${imageDownloadExtension(src)}`;
}

/**
 * A data: URL as a Blob, decoded HERE rather than through fetch().
 *
 * Not an optimisation: iOS only opens a share sheet from inside the gesture that asked for it, and an `await
 * fetch(...)` first is enough to lose that. The images this viewer shows arrive as data URLs (a private one rides
 * inside its capsule), so the decode can be synchronous and the sheet still counts as user-initiated.
 */
function blobFromDataUrl(dataUrl) {
  const match = /^data:([^;,]*)(;base64)?,([\s\S]*)$/.exec(String(dataUrl ?? ''));
  if (!match) return null;
  const type = match[1] || 'application/octet-stream';
  if (!match[2]) return new Blob([decodeURIComponent(match[3])], { type });
  const binary = atob(match[3]);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  return new Blob([bytes], { type });
}

/**
 * SAVE THE PICTURE — and on iPhone that is not a download [OWNER 2026-08-24: "on the iPhone the image from the
 * viewer doesn't save. Something flickers and that's it … the download isn't visible anywhere. On Android it saves
 * with no problem."]
 *
 * `<a download>` is what every other platform wants and what iOS Safari IGNORES: the attribute does nothing there,
 * so the click navigated for an instant and came back — the flicker, and no file. The platform's own way to put a
 * picture in the camera roll is the share sheet ("Save Image"), which is what canShare({files}) offers.
 *
 * Returns the outcome instead of announcing it: only the caller knows what its surface can say. A dismissed sheet
 * is the user changing their mind, not a failure.
 */
async function saveImageOutOfPlatho(src, filename) {
  if (!src) return 'failed';
  const blob = src.startsWith('data:') ? blobFromDataUrl(src) : null;
  // THE PROVEN PATH, and it was already in this file [OWNER 2026-08-24: "but we do download things on the iPhone
  // somehow — the wallet key, for instance"]. Right, and that is the whole answer: downloadJsonFile makes a BLOB
  // URL and clicks an <a download> at it, and that works on iPhone.
  //
  // So the first diagnosis was wrong. iOS does not ignore the download attribute; it refuses a `data:` URL — which
  // is exactly what this handler used to hand it, because a private image travels as a data URL inside its
  // capsule. Converting first makes this the same one path everywhere, with no platform branch at all. The share
  // sheet is gone with the branch: on a desktop it turned a download into a share sheet, which is not a nicer
  // download — it is a different action the user did not ask for.
  const href = blob ? URL.createObjectURL(blob) : src;
  try {
    if (isTelegramEnv() && blob && navigator.canShare?.({ files: [new File([blob], filename, { type: blob.type })] })) {
      // The ONE place a click cannot work: <a download>.click() fails silently inside Telegram's WebView (the same
      // reason downloadJsonFile shows a manual-copy dialog there). A file has nothing to copy manually, so the
      // system sheet is the only way out — and there it IS the user's only option, not a substituted one.
      await navigator.share({ files: [new File([blob], filename, { type: blob.type || 'image/webp' })] });
      return 'shared';
    }
    const link = document.createElement('a');
    link.href = href;
    link.download = filename;
    link.rel = 'noreferrer';
    document.body.append(link);
    link.click();
    link.remove();
    return 'downloaded';
  } catch (error) {
    if (error?.name === 'AbortError') return 'dismissed';   // the user closed the sheet themselves
    console.error(error);
    return 'failed';
  } finally {
    if (blob) window.setTimeout(() => URL.revokeObjectURL(href), 10_000);
  }
}

async function downloadImageLightboxImage() {
  const src = imageLightboxImage?.currentSrc || imageLightboxImage?.src;
  if (!src) return;
  const outcome = await saveImageOutOfPlatho(src, imageLightboxDownloadFilename(src));
  // A share sheet showed the user something happened and a dismissal was their own doing; the other two outcomes
  // are invisible without this — which is the second half of the owner's report ("the download isn't visible
  // anywhere"). The confirmation goes in the viewer's OWN caption line: the control is an icon button, so
  // replacing its text would replace the icon.
  const said = outcome === 'downloaded' ? t('common.imageSaved')
    : outcome === 'failed' ? t('common.imageSaveFailed')
    : null;
  if (!said || !imageLightboxMeta) return;
  const caption = imageLightboxMeta.dataset.caption ?? imageLightboxMeta.textContent;
  imageLightboxMeta.dataset.caption = caption;
  imageLightboxMeta.textContent = said;
  window.setTimeout(() => {
    if (imageLightboxMeta.textContent !== said) return;   // a reopen already put its own caption back
    imageLightboxMeta.textContent = imageLightboxMeta.dataset.caption ?? caption;
  }, 1800);
}

function closeActionDialog(result = null) {
  if (!activeActionDialog) return;
  const { resolve } = activeActionDialog;
  activeActionDialog = null;
  closeImageLightbox();
  // The fields stay on screen for the exit: clearing them first emptied the card a beat before it left (owner:
  // the receive-GRAM QR vanished, then the sheet closed). A reopen mid-exit rebuilds fields and buttons itself
  // (openActionDialog), so the deferred reset is skipped in that case — see hideDialogAnimated.
  hideDialogAnimated(actionDialog, () => {
    actionFields?.replaceChildren();
    if (actionCancelButton) {
      actionCancelButton.hidden = false;
      actionCancelButton.disabled = false;
    }
    if (actionDismissButton) actionDismissButton.hidden = true;   // opt-in per dialog; never leaks to the next one
  });
  if (actionSubmitButton) actionSubmitButton.disabled = false;
  resolve(result);
  // A dialog just left the screen, so an unlock prompt that was waiting for the way to clear may go ahead.
  //
  // [MEASURED 2026-08-13] The line here used to be a bare `scheduleWalletUnlockPrompt()`, and it could NEVER fire
  // — twice over. That function cannot raise walletUnlockPromptPending, which the prompt body consumes before it
  // awaits; and `resolve` above is synchronous while loadPlathoWallet clears walletUnlockPromise in a `finally`,
  // a microtask later, so the predicate's `!walletUnlockPromise` was still false at this point regardless. A
  // compensator that has never once run is worse than none: it is why the dialog being superseded looked handled.
  //
  // setTimeout(0), not queueMicrotask: it has to land after the await chain in loadPlathoWallet unwinds. Safe to
  // ARM now because the decline is recorded at the tap (noteActionDialogUserDismissed) rather than inferred from
  // the null further down, so this cannot re-open a dialog the user just closed on purpose.
  setTimeout(() => {
    if (activeActionDialog) return;   // something else opened in the meantime; it owns the screen now
    resumeWalletUnlockPrompt();
  }, 0);
}

async function openActionDialog(config = {}) {
  if (!actionDialog || !actionForm || !actionFields || !actionTitle || !actionHint || !actionSubmitButton) {
    throw new Error('Action dialog is unavailable');
  }
  if (activeActionDialog) closeActionDialog(null);
  return new Promise((resolve) => {
    // v794: X-only by default — outside-click / Escape no longer dismiss an action dialog unless the caller
    // explicitly opts back in with dismissOnBackdrop:true. (Was: default true, so every dialog closed on an
    // outside tap.)
    const dismissible = config.dismissOnBackdrop === true;
    // `cancellable` (the explicit ✕ close button) is DECOUPLED from `dismissOnBackdrop` (click-outside /
    // Escape dismiss) and now defaults to ON so every dialog is closable via the ✕ — a caller can still force
    // a decision (no ✕) with cancellable:false (e.g. the seed-backup hard gate). Decoupling matters: since
    // dismissible now defaults false, tying the ✕ to it would have silently removed the ✕ from every dialog.
    const cancellable = config.cancellable ?? true;
    activeActionDialog = {
      resolve,
      summary: config.summary,
      dismissOnBackdrop: dismissible,
      cancellable,
      // Optional async gate: run on submit BEFORE the dialog closes. Resolves { ok, result?, error? }. When it
      // returns ok:false the dialog STAYS OPEN and shows the error inline (no close+reopen flicker).
      validateSubmit: config.validateSubmit ?? null,
      checkingHint: config.checkingHint ?? t('dialog.checking'),
    };
    actionTitle.textContent = config.title ?? t('dialog.defaultTitle');
    actionHint.textContent = config.hint ?? t('dialog.reviewBeforeSigning');
    // An EMPTY hint hides the line rather than leaving a blank paragraph pushing the first control down. A dialog
    // whose explanation lives in footnotes has nothing to say up here, and the gap read as a rendering bug.
    actionHint.hidden = actionHint.textContent === '';
    actionHint.dataset.tone = config.tone ?? 'muted';
    actionForm.autocomplete = config.formAutocomplete ?? 'off';
    actionForm.method = config.formMethod ?? 'post';
    actionForm.action = config.formAction ?? window.location.href;
    if (actionCancelButton) {
      actionCancelButton.hidden = !cancellable;
      actionCancelButton.disabled = !cancellable;
    }
    actionSubmitButton.textContent = config.submitLabel ?? t('common.continue');
    actionSubmitButton.disabled = false;
    // OPT-IN second, LABELLED way out. Most dialogs ask for a decision and close via the ✕; an INFORMATIONAL one
    // needs a named dismiss, because a lone action button beside a bare ✕ reads as "you have to do this". Resolves
    // exactly like the ✕ (null = the user declined), so callers keep one meaning for "no".
    if (actionDismissButton) {
      actionDismissButton.hidden = !config.cancelLabel;
      actionDismissButton.disabled = false;
      if (config.cancelLabel) actionDismissButton.textContent = config.cancelLabel;
    }
    actionFields.replaceChildren(...(config.fields ?? []).map(createActionField));
    renderActionSummary(config.summary, collectActionDialogValues());
    renderActionFootnotes(config.footnotes);
    actionDialog.classList.remove('is-closing'); actionDialog.hidden = false;
    requestAnimationFrame(() => actionFields.querySelector('textarea, input:not([readonly]):not([type="hidden"]):not(.password-manager-username), select')?.focus());
  });
}

function updateActiveActionSummary() {
  if (!activeActionDialog) return;
  renderActionSummary(activeActionDialog.summary, collectActionDialogValues());
}

function appDocById(id) {
  return APP_DOCS.find((doc) => doc.id === id) ?? APP_DOCS[0] ?? null;
}

function renderDocsNav() {
  if (!docsNav) return;
  docsNav.replaceChildren();
  for (const doc of APP_DOCS) {
    const button = document.createElement('button');
    button.type = 'button';
    button.dataset.docId = doc.id;
    button.className = doc.id === activeDocId ? 'is-active' : '';
    button.setAttribute('aria-pressed', doc.id === activeDocId ? 'true' : 'false');
    button.textContent = doc.label;
    docsNav.append(button);
  }
}

function setDocsStatus(message, tone = 'muted') {
  if (!docsContent) return;
  const status = document.createElement('div');
  status.className = `docs-status docs-status-${tone}`;
  status.textContent = message;
  docsContent.replaceChildren(status);
}

function closeDocsDialog() {
  hideDialogAnimated(docsDialog);
}

async function openDocsDialog(docId = activeDocId) {
  if (!docsDialog) return;
  docsDialog.classList.remove('is-closing'); docsDialog.hidden = false;
  await selectDoc(docId);
  requestAnimationFrame(() => docsContent?.focus());
}

async function selectDoc(docId) {
  const doc = appDocById(docId);
  if (!doc || !docsContent) return;
  // Directional slide (owner): the incoming document enters FROM the side of the tab the user pressed —
  // a tab to the right slides in from the right, to the left from the left. CSSOM var (CSP-legal); the
  // docSlideIn keyframe reads it, and a same-tab or first open degrades to a plain fade (0px).
  const previousIndex = APP_DOCS.findIndex((entry) => entry.id === activeDocId);
  const nextIndex = APP_DOCS.findIndex((entry) => entry.id === doc.id);
  const shift = previousIndex >= 0 && nextIndex >= 0 && previousIndex !== nextIndex
    ? (nextIndex > previousIndex ? '40px' : '-40px')
    : '0px';
  docsContent.style.setProperty('--doc-shift', shift);
  activeDocId = doc.id;
  renderDocsNav();
  if (docsTitle) docsTitle.textContent = doc.title;
  if (docsLead) docsLead.textContent = t('docs.lead');
  // The header nodes are reused (textContent swap), so the entrance animation must be restarted by hand:
  // drop the class, force a reflow, put it back (plain fade — owner asked for a simple appearance).
  for (const node of [docsTitle, docsLead]) {
    if (!node) continue;
    node.classList.remove('docs-head-swap');
    void node.offsetWidth;
    node.classList.add('docs-head-swap');
  }
  setDocsStatus(t('docs.loading'));
  try {
    // Docs are localized: cache per (doc, locale) so switching language serves the right translation. The main-app
    // language switch reloads the whole page (appLanguageSelect), so an open doc reopens in the new locale for free.
    const locale = currentLocale();
    const cacheKey = `${doc.id}:${locale}`;
    let markdown = docsCache.get(cacheKey);
    if (!markdown) {
      markdown = await fetchLocalizedDocMarkdown(doc.path, locale);
      docsCache.set(cacheKey, markdown);
    }
    renderMarkdownToNode(markdown, docsContent);
    docsContent.scrollTop = 0;
  } catch (error) {
    console.error(error);
    setDocsStatus(t('docs.unavailable'), 'error');
  }
}

// Docs ship an English base (<name>.md) plus per-locale siblings (<name>.<locale>.md). English uses the base path.
function localizedDocPath(basePath, locale) {
  if (!locale || locale === 'en') return basePath;
  return basePath.replace(/\.md$/, `.${locale}.md`);
}

// Load the current locale's doc, falling back to the English base when the locale IS English or its localized file
// is missing/unfetchable (a language without a translated doc yet degrades to English instead of erroring). The
// English base is SW-precached, so this fallback also keeps docs available offline in any language.
async function fetchLocalizedDocMarkdown(basePath, locale) {
  const localizedPath = localizedDocPath(basePath, locale);
  if (localizedPath !== basePath) {
    try {
      const localized = await fetch(localizedPath, { cache: 'no-store' });
      if (localized.ok) return await localized.text();
    } catch { /* network/missing → fall through to the English base */ }
  }
  const response = await fetch(basePath, { cache: 'no-store' });
  if (!response.ok) throw new Error(`Document fetch failed: ${response.status}`);
  return await response.text();
}

function appendInlineMarkdown(parent, text) {
  const pattern = /(`[^`]+`|\*\*[^*]+\*\*|\[[^\]]+\]\(([^)]+)\))/g;
  let cursor = 0;
  for (const match of text.matchAll(pattern)) {
    if (match.index > cursor) {
      parent.append(document.createTextNode(text.slice(cursor, match.index)));
    }
    const token = match[0];
    if (token.startsWith('`')) {
      const code = document.createElement('code');
      code.textContent = token.slice(1, -1);
      parent.append(code);
    } else if (token.startsWith('**')) {
      const strong = document.createElement('strong');
      strong.textContent = token.slice(2, -2);
      parent.append(strong);
    } else {
      const labelEnd = token.indexOf(']');
      const href = token.slice(labelEnd + 2, -1);
      const anchor = document.createElement('a');
      anchor.textContent = token.slice(1, labelEnd);
      if (/^(https?:|mailto:)/i.test(href)) {
        anchor.href = href;
        anchor.target = '_blank';
        anchor.rel = 'noreferrer';
        if (/^https?:/i.test(href) && isTelegramEnv()) {
          // target=_blank is unreliable inside the Telegram embed; route through the SDK.
          anchor.addEventListener('click', (event) => {
            if (openExternalLinkInTelegram(href)) event.preventDefault();
          });
        }
      }
      parent.append(anchor);
    }
    cursor = match.index + token.length;
  }
  if (cursor < text.length) {
    parent.append(document.createTextNode(text.slice(cursor)));
  }
}

function isMarkdownTableLine(line) {
  const trimmed = line.trim();
  return trimmed.startsWith('|') && trimmed.endsWith('|') && trimmed.includes('|');
}

function isMarkdownTableSeparator(line) {
  if (!isMarkdownTableLine(line)) return false;
  return line
    .trim()
    .replace(/^\||\|$/g, '')
    .split('|')
    .every((cell) => /^:?-{3,}:?$/.test(cell.trim()));
}

function markdownTableCells(line) {
  return line
    .trim()
    .replace(/^\||\|$/g, '')
    .split('|')
    .map((cell) => cell.trim());
}

function markdownStartsBlock(line, nextLine = '') {
  const trimmed = line.trim();
  return !trimmed
    || trimmed.startsWith('```')
    || /^#{1,4}\s+/.test(trimmed)
    || /^[-*]\s+/.test(trimmed)
    || /^\d+\.\s+/.test(trimmed)
    || (isMarkdownTableLine(line) && isMarkdownTableSeparator(nextLine));
}

function renderMarkdownTable(rows) {
  const wrapper = document.createElement('div');
  wrapper.className = 'docs-table-wrap';
  const table = document.createElement('table');
  const thead = document.createElement('thead');
  const headRow = document.createElement('tr');
  for (const cellText of rows[0] ?? []) {
    const cell = document.createElement('th');
    appendInlineMarkdown(cell, cellText);
    headRow.append(cell);
  }
  thead.append(headRow);
  table.append(thead);
  const tbody = document.createElement('tbody');
  for (const row of rows.slice(1)) {
    const tr = document.createElement('tr');
    for (const cellText of row) {
      const cell = document.createElement('td');
      appendInlineMarkdown(cell, cellText);
      tr.append(cell);
    }
    tbody.append(tr);
  }
  table.append(tbody);
  wrapper.append(table);
  return wrapper;
}

function renderMarkdownToNode(markdown, target) {
  const root = document.createElement('div');
  root.className = 'docs-rendered';
  const lines = String(markdown ?? '').replace(/\r\n/g, '\n').split('\n');
  let index = 0;
  while (index < lines.length) {
    const line = lines[index];
    const trimmed = line.trim();
    if (!trimmed) {
      index += 1;
      continue;
    }
    if (trimmed.startsWith('```')) {
      const codeLines = [];
      index += 1;
      while (index < lines.length && !lines[index].trim().startsWith('```')) {
        codeLines.push(lines[index]);
        index += 1;
      }
      index += 1;
      const pre = document.createElement('pre');
      const code = document.createElement('code');
      code.textContent = codeLines.join('\n');
      pre.append(code);
      root.append(pre);
      continue;
    }
    const heading = trimmed.match(/^(#{1,4})\s+(.+)$/);
    if (heading) {
      const level = Math.min(heading[1].length + 1, 5);
      const node = document.createElement(`h${level}`);
      appendInlineMarkdown(node, heading[2]);
      root.append(node);
      index += 1;
      continue;
    }
    if (isMarkdownTableLine(line) && isMarkdownTableSeparator(lines[index + 1] ?? '')) {
      const rows = [markdownTableCells(line)];
      index += 2;
      while (index < lines.length && isMarkdownTableLine(lines[index])) {
        rows.push(markdownTableCells(lines[index]));
        index += 1;
      }
      root.append(renderMarkdownTable(rows));
      continue;
    }
    if (/^[-*]\s+/.test(trimmed) || /^\d+\.\s+/.test(trimmed)) {
      const ordered = /^\d+\.\s+/.test(trimmed);
      const list = document.createElement(ordered ? 'ol' : 'ul');
      const itemPattern = ordered ? /^\d+\.\s+/ : /^[-*]\s+/;
      while (index < lines.length && itemPattern.test(lines[index].trim())) {
        const item = document.createElement('li');
        appendInlineMarkdown(item, lines[index].trim().replace(itemPattern, ''));
        list.append(item);
        index += 1;
      }
      root.append(list);
      continue;
    }
    const paragraphLines = [trimmed];
    index += 1;
    while (index < lines.length && !markdownStartsBlock(lines[index], lines[index + 1] ?? '')) {
      paragraphLines.push(lines[index].trim());
      index += 1;
    }
    const paragraph = document.createElement('p');
    appendInlineMarkdown(paragraph, paragraphLines.join(' '));
    root.append(paragraph);
  }
  target.replaceChildren(root);
}

function activeThread() {
  // NO threads[0] fallback: threads[0] is ALWAYS the Saved "My notes" thread, so falling back to it made an
  // unresolved activeThreadId silently render/enable the composer on "My notes" — a message the user meant for a
  // peer could then be echoed into My notes, and the render disagreed with the send (which never targets threads[0]).
  // Null here = no chat selected → renderConversation shows the empty state and the composer is disabled, matching
  // the design intent (a null activeThreadId means the user is on the dialog LIST, not silently on My notes).
  return threads.find((item) => item.id === activeThreadId) ?? null;
}

// Find an already-open dialog for the same person as `newThread`, even when they were reached by a
// different identity (e.g. an existing chat started via an .ath name vs. opening "Private chat" from a
// Public wallet channel) or the same wallet in a different address format. Order: exact thread id ->
// any shared identity variant -> same counterparty wallet (compared as raw, so friendly/raw forms
// match). Prevents the duplicate empty dialog reported from the Public tab.
function findExistingRecipientThread(newThread) {
  const newWallet = ownerWalletFromThread(newThread);
  const peerRaw = newWallet ? rawWalletAddress(newWallet) : null;
  // Heal-on-touch: a PEER lookup must never hand back the Saved self-thread (and a peer dialog wearing a grafted
  // own-wallet variant is stripped the moment it is touched) — see healThreadWalletVariantConflict.
  const healed = (thread) => (thread ? healThreadWalletVariantConflict(thread, peerRaw) : null);
  const byId = healed(threads.find((thread) => thread.id === newThread.id));
  if (byId) return byId;
  const byVariant = healed(findThreadByIdentityVariants(threads, threadIdentityVariants(newThread)));
  if (byVariant) return byVariant;
  if (newWallet) {
    const byWallet = healed(threads.find((thread) => {
      const wallet = ownerWalletFromThread(thread);
      return wallet && sameWalletAddress(wallet, newWallet);
    }));
    if (byWallet) return byWallet;
  }
  return null;
}

function selectOrCreateRecipientThread(input, options = {}) {
  const result = createRecipientThread(input, options);
  if (!result.ok) return result;
  const existing = findExistingRecipientThread(result.thread);
  if (existing) {
    if (result.thread.localLabel) {
      existing.localLabel = result.thread.localLabel;
      existing.displayIdentity = null;
      existing.name = result.thread.name;
      existing.avatar = result.thread.avatar;
      existing.subtitle = result.thread.subtitle;
      persistThreadDisplayPreference(existing);
    } else {
      // Addressed by a specific identity (e.g. "admin") that resolved to an existing contact's wallet. Record that
      // username among the contact's known identities (the "Display as" list) even though we've never received from
      // it — and, for a username (not a raw wallet address), switch the dialog's display to it, so addressing
      // "admin" doesn't drop you into a dialog still labelled "plato".
      const addressedVariants = threadIdentityVariants(result.thread);
      if (addressedVariants.length > 0) refreshThreadIdentityFromVariants(existing, addressedVariants);
      const addressedIdentity = primaryThreadIdentity(result.thread);
      if (addressedIdentity && addressedIdentity.type !== RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS) {
        existing.displayIdentity = addressedIdentity;
        applyThreadDisplayFields(existing);
        syncThreadDisplayToContactStore(existing);
        persistThreadDisplayPreference(existing);
      }
    }
    activeThreadId = existing.id;
  } else {
    // Stamp creation time: a just-added (still message-less) dialog sorts to the TOP of the recency-ordered list
    // (threadLastActivityMs falls back to this) instead of sinking below every old chat.
    result.thread.createdAtMs = Date.now();
    threads.push(result.thread);
    activeThreadId = result.thread.id;
  }
  appShell.dataset.chatOpen = 'true';
  closeNewChatDialog();
  hydrateThreadAvatarFromPointer(
    threads.find((thread) => thread.id === activeThreadId),
    ownerWalletFromThread(threads.find((thread) => thread.id === activeThreadId)),
    null,
  ).catch((error) => console.error(error));
  renderThreads();
  renderConversation();
  return { ok: true };
}

function readCustomPublicChannels() {
  try {
    const parsed = JSON.parse(localStorageOrNull()?.getItem(PUBLIC_CUSTOM_CHANNELS_STORAGE_KEY) ?? '[]');
    if (!Array.isArray(parsed) || parsed.length === 0) return [];
    const candidates = parsed.filter((item) => (
      item
      && typeof item === 'object'
      && item.id
      && (item.sourceUrl || item.authorWallet || item.author_wallet)
    ));
    return candidates.length > 0 ? normalizePublicChannelRegistry(candidates) : [];
  } catch {
    return [];
  }
}

function writeCustomPublicChannels() {
  try {
    localStorageOrNull()?.setItem(PUBLIC_CUSTOM_CHANNELS_STORAGE_KEY, JSON.stringify(customPublicChannels));
  } catch {
    // Non-persistent mode still keeps custom channels in memory for this tab.
  }
}

function publicChannelMatchesAuthorWallet(channel, authorWallet) {
  const channelWallet = channel?.authorWallet ?? channel?.author_wallet;
  if (!channelWallet || !authorWallet) return false;
  return sameWalletAddress(channelWallet, authorWallet)
    || String(channelWallet) === String(authorWallet);
}

function rebuildPublicChannelRegistry() {
  const baseChannels = normalizePublicChannelRegistry(basePublicChannelRegistry);
  const customChannels = normalizePublicChannelRegistry(customPublicChannels)
    .filter((channel) => !baseChannels.some((base) => publicChannelMatchesAuthorWallet(base, channel.authorWallet)));
  publicChannelRegistry = normalizePublicChannelRegistry([...baseChannels, ...customChannels])
    .map(applyContactDisplayToRegistryChannel);
  return publicChannelRegistry;
}

// Overlay the user's chosen display name (from the shared per-counterparty store) onto a wallet
// channel so the Public channels list, channel detail header, and feed all show the SAME name the
// Private dialog shows. name/avatar survive the registry re-normalization in
// subscribedPublicChannels(); identity tone is re-resolved at render time. The official platho.app
// channel keeps its brand name.
function applyContactDisplayToRegistryChannel(channel) {
  if (!channel?.authorWallet || channel.id === DEFAULT_PUBLIC_CHANNEL_ID) return channel;
  const display = resolveWalletChannelDisplay(channel.authorWallet);
  // An explicit display choice wins; otherwise fall back to the channel's own name made canonical (no ".ath"),
  // so even a registry name persisted/added with the suffix is shown bare everywhere it propagates (feed author,
  // channels list, channel-detail header, and the thread.name the public-feed module derives from it).
  const name = display?.name || canonicalUsernameDisplay(channel.name);
  if (!name || name === channel.name) return channel;
  return {
    ...channel,
    name,
    avatar: publicChannelAvatar(name),
  };
}

function publicChannelAvatar(label) {
  return String(label ?? 'P').trim().slice(0, 1).toUpperCase() || 'P';
}

function publicChannelSubtitleForIdentity(identity) {
  if (identity?.type === RECIPIENT_IDENTITY_TYPES.PLATHO_NFT) return 'Platho NFT public channel';
  if (identity?.type === RECIPIENT_IDENTITY_TYPES.TON_DNS) return 'TON DNS public channel';
  return 'wallet public channel';
}

function publicChannelRouteLabel(identity, authorWallet) {
  if (identity?.type === RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS) return shortAddress(authorWallet ?? identity.value);
  return canonicalUsernameDisplay(identity?.label) || shortAddress(authorWallet);
}

async function resolvePublicChannelIdentity(input) {
  const parsed = parseRecipientIdentity(input);
  if (!parsed.ok) throw new Error(parsed.error);
  const { identity } = parsed;

  if (identity.type === RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS) {
    return {
      identity,
      authorWallet: requireBasechainAddress(identity.value, 'Public channel author'),
    };
  }

  if (identity.type === RECIPIENT_IDENTITY_TYPES.PLATHO_NFT) {
    const resolved = await resolvePlathoUsernameOwner(identity.value);
    return {
      identity,
      authorWallet: requireBasechainAddress(resolved.ownerWallet, 'Public channel author'),
    };
  }

  if (identity.type === RECIPIENT_IDENTITY_TYPES.TON_DNS) {
    const provider = await resolveTonDnsProvider();
    if (!provider?.resolveWallet) throw new Error('TON DNS provider is not configured');
    const walletAddress = await provider.resolveWallet(identity.value, {
      rootAddress: appConfig.tonDns?.rootAddress ?? null,
      ...criticalChainReadOptions(),
    });
    return {
      identity,
      authorWallet: requireBasechainAddress(walletAddress, 'Public channel author'),
    };
  }

  throw new Error('Unsupported public channel identity');
}

function openPrivateThreadForWallet(walletAddress) {
  const result = selectOrCreateRecipientThread(walletAddress);
  if (!result.ok) {
    setPublicStatus(result.error ?? 'private chat unavailable');
    return false;
  }
  setView('chats');
  appShell.dataset.chatOpen = 'true';
  renderThreads();
  renderConversation();
  return true;
}

function addCustomPublicChannel(channel) {
  const normalized = normalizePublicChannelRegistry([channel]).find((item) => item.id === channel.id);
  if (!normalized) throw new Error('Channel needs an author wallet or feed URL');
  customPublicChannels = normalizePublicChannelRegistry([
    ...customPublicChannels.filter((item) => item.id !== normalized.id),
    normalized,
  ]);
  writeCustomPublicChannels();
  rebuildPublicChannelRegistry();
  const subscribedById = new Map((publicChannelSubscriptions?.channels ?? []).map((item) => [item.id, item]));
  subscribedById.set(normalized.id, { id: normalized.id, subscribed: true });
  publicChannelSubscriptions = {
    version: publicChannelSubscriptions?.version ?? 1,
    activeChannelId: normalized.id,
    channels: publicChannelRegistry.map((item) => ({
      id: item.id,
      subscribed: subscribedById.get(item.id)?.subscribed === true,
    })),
  };
  writePublicChannelSubscriptions(publicChannelStorage(), publicChannelSubscriptions);
  rebuildThreadsFromPublicSubscriptions({ preserveActive: true });
  renderPublicSurface();
  resyncPublicForNewSubscription();
  markPrefsDirty();
}

// A newly-followed channel does NOT change the GLOBAL public latest id, so the sync fast-path (latestId unchanged ->
// skip the whole walk) would leave the channel on "Waiting for public feed" until a page reload reset the in-memory
// cursor. Invalidate the fast-path and kick a sync now so the new channel's posts load immediately.
function resyncPublicForNewSubscription() {
  invalidatePublicSyncFastPath();
  syncPublicChannels().catch((error) => { noteTonRpcRateLimit(error); });
}

function isPublicChannelSubscribed(channelId) {
  const id = String(channelId ?? '').trim();
  if (!id) return false;
  return (publicChannelSubscriptions?.channels ?? []).some((item) => item.id === id && item.subscribed === true);
}

function setPublicChannelSubscribed(channelId, subscribed) {
  const id = String(channelId ?? '').trim();
  if (!id) return false;
  const subscribedById = new Map((publicChannelSubscriptions?.channels ?? []).map((item) => [item.id, item]));
  subscribedById.set(id, { id, subscribed: subscribed === true });
  const channels = publicChannelRegistry.map((item) => ({
    id: item.id,
    subscribed: subscribedById.get(item.id)?.subscribed === true,
  }));
  const nextActive = subscribed === false && publicChannelSubscriptions?.activeChannelId === id
    ? channels.find((item) => item.subscribed)?.id ?? null
    : publicChannelSubscriptions?.activeChannelId ?? channels.find((item) => item.subscribed)?.id ?? null;
  publicChannelSubscriptions = {
    version: publicChannelSubscriptions?.version ?? 1,
    activeChannelId: nextActive,
    channels,
  };
  writePublicChannelSubscriptions(publicChannelStorage(), publicChannelSubscriptions);
  // preserveActive: TRUE. Following/unfollowing a public channel must NOT hijack the active PRIVATE dialog. With
  // preserveActive:false this reset activeThreadId to threads[0] (always the Saved "My notes" thread), and the
  // add-contact flow (selectOrCreateRecipientThread(peer) -> followContactPublicChannel(peer) -> here) then grafted
  // the peer's identity onto Saved and sent the first message into "My notes" — the root of "I write to glasnost but
  // it lands in my notes". preserveActive:true keeps the peer dialog selected (or, if the selection genuinely
  // vanished, drops to the LIST — never silently to Saved).
  rebuildThreadsFromPublicSubscriptions({ preserveActive: true });
  renderPublicSurface({ anchorUnread: false });
  setPublicStatus(subscribed ? 'channel followed' : 'channel hidden');
  // Following a channel must pull its posts NOW (the fast-path would otherwise skip the walk until a reload).
  if (subscribed) resyncPublicForNewSubscription();
  markPrefsDirty();
  return true;
}

/**
 * A per-account map in local storage: read it back, or write it. One pair for every "where did this reader get
 * to" record, so a new one is a storage key and nothing else.
 *
 * Reads defend against a hand-edited or half-written value (a non-object, an array) by falling back to empty:
 * these are positions, and losing one costs a scroll, while trusting a malformed one costs a crash on open.
 * Writes swallow their failure on purpose — private browsing has no localStorage, and the position still works
 * for the current tab from memory.
 */
function readScopedJsonMap(storageKey) {
  try {
    const parsed = JSON.parse(localStorageOrNull()?.getItem(scopedStorageKey(storageKey)) ?? '{}');
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
  } catch {
    return {};
  }
}

function writeScopedJsonMap(storageKey, value) {
  try {
    localStorageOrNull()?.setItem(scopedStorageKey(storageKey), JSON.stringify(value));
  } catch {
    // Non-persistent mode still keeps the state for the current tab.
  }
}

function publicEntryIdBigInt(value) {
  if (value === undefined || value === null || value === '') return null;
  try {
    const bigint = BigInt(value);
    return bigint >= 0n ? bigint : null;
  } catch {
    return null;
  }
}

function publicChannelCursor(channelId) {
  return publicEntryIdBigInt(publicReadCursors?.[channelId]) ?? -1n;
}

/**
 * THE READING MARK OF ONE COMMENT THREAD, and the three things that touch it.
 *
 * Stored per post as the newest comment entry id the reader has actually had on screen — not the newest that
 * EXISTS, which would mark a thread read the moment it loaded. A comment with no entry id (one still in flight)
 * can never be the mark: it has no place in the ordering the mark is compared against.
 */
let publicCommentReadCursors = {};

function publicCommentReadCursor(postKey) {
  const stored = postKey ? publicCommentReadCursors?.[postKey] : null;
  if (typeof stored === 'string') return stored !== '' ? stored : null;
  const mark = typeof stored?.mark === 'string' ? stored.mark : '';
  return mark !== '' ? mark : null;
}

// WHERE the marked comment lives — era shard + 0-based row — or null for a mark saved before places existed (a
// bare string) or one whose row was never known (a cached comment from an unstamped snapshot).
function publicCommentReadPlace(postKey) {
  const stored = postKey ? publicCommentReadCursors?.[postKey] : null;
  if (!stored || typeof stored === 'string') return null;
  const shardKey = typeof stored.shardKey === 'string' && stored.shardKey !== '' ? stored.shardKey : null;
  const row = Number.isFinite(Number(stored.row)) ? Number(stored.row) : null;
  return shardKey !== null && row !== null ? { shardKey, row } : null;
}

/**
 * Advance the mark to the last comment whose top has passed the bottom of the viewport — the last one the reader
 * has had a chance to read. Called from the thread's own debounced scroll handler and once after the open scroll
 * settles, so a thread that fits on one screen is marked read without any scrolling at all.
 *
 * BY POSITION, NOT BY COMPARING IDS. A comment's chain entry id is `c-<hash of the body>` — measured on a live
 * thread, not a number and not ordered by anything. "Newer" is therefore a question about the DISPLAYED ORDER,
 * which is the merge's own chronological sort, so the mark is a row KEY and progress is an index in that order.
 *
 * Only ever moves FORWARD (scrolling back up un-reads nothing), and never moves at all while the marked comment
 * is missing from the loaded window — a mark we cannot locate must not be overwritten by a guess.
 */
function rememberPublicPostReadPosition() {
  const postKey = publicPostIdentity(publicPostDetailItem);
  const list = publicPostDetailBody?.querySelector('.comment-list');
  if (!postKey || !list) return;
  const rows = [...list.children];
  const mark = publicCommentReadCursor(postKey);
  const markIndex = mark === null ? -1 : rows.findIndex((row) => row.dataset.rowKey === mark);
  if (mark !== null && markIndex < 0) return;
  const viewportBottom = publicPostDetailBody.getBoundingClientRect().bottom;
  let seenIndex = -1;
  for (let i = 0; i < rows.length; i += 1) {
    if (rows[i].getBoundingClientRect().top > viewportBottom) break;   // oldest first: everything below is unseen
    seenIndex = i;
  }
  if (seenIndex <= markIndex) return;
  const markKey = rows[seenIndex].dataset.rowKey;
  // The PLACE rides with the mark, so a later open can jump straight to it however deep it is. Looked up in the
  // data (the DOM row carries only its key); a comment that cannot name its place — a local pending one, or one
  // restored from a snapshot older than the stamp — stores the bare mark, which is exactly the old behaviour.
  const marked = publicPostDetailMergedComments().find((comment) => publicCommentRowKey(comment) === markKey);
  const place = marked && typeof marked.shardKey === 'string' && marked.shardKey !== '' && Number.isFinite(Number(marked.shardRow))
    ? { shardKey: marked.shardKey, row: Number(marked.shardRow) }
    : null;
  publicCommentReadCursors = { ...publicCommentReadCursors, [postKey]: place ? { mark: markKey, ...place } : markKey };
  writeScopedJsonMap(PUBLIC_COMMENT_READ_CURSORS_STORAGE_KEY, publicCommentReadCursors);
}

/**
 * Open a comment thread where the reader stopped — the same rule as a private dialog, through the same function.
 * A thread never opened has no mark, so its first comment is the first unread and the reader lands at the start
 * of the loaded window: the conversation from its beginning, as far as it has been paged in.
 */
function applyPublicPostDetailOpenScroll() {
  const body = publicPostDetailBody;
  if (!body) return;
  const rows = [...(body.querySelector('.comment-list')?.children ?? [])];
  const mark = publicCommentReadCursor(publicPostIdentity(publicPostDetailItem));
  const markIndex = mark === null ? -1 : rows.findIndex((row) => row.dataset.rowKey === mark);
  // The first unread is simply the row AFTER the marked one. A mark that is not in the loaded window (index -1
  // with a mark set) leaves `firstUnread` undefined, which lands the reader at the end — the honest answer when
  // we cannot say where they stopped.
  const firstUnread = mark !== null && markIndex < 0 ? null : rows[markIndex + 1] ?? null;
  anchorScrollerToFirstUnread(body, firstUnread, (top) => { body.scrollTop = top; });
  rememberPublicPostReadPosition();
}

function isUnreadPublicItem(item) {
  const entryId = publicEntryIdBigInt(item?.readEntryId ?? item?.entryId);
  if (entryId === null) return false;
  return entryId > publicChannelCursor(item.channelId ?? 'platho.app');
}

// ONE LIST BY TIME. publicChannelThreadsToFeedItems returns the posts grouped by channel (reversed, in subscription
// order); sorting that by each post's createdAt is what makes the feed a feed rather than a stack of channels.
// Oldest first — renderPublicFeed slices the newest window from the END and paints it reversed (newest on top);
// publicChannelViewItems / markVisiblePublicFeedRead / the detail lookup are order-agnostic.
function publicFeedItemsChronological() {
  return sortPublicFeedItemsByTime(publicChannelThreadsToFeedItems(publicChannelThreads));
}

function markVisiblePublicFeedRead(items = publicFeedItemsChronological()) {
  let changed = false;
  for (const item of items) {
    const entryId = publicEntryIdBigInt(item.readEntryId ?? item.entryId);
    if (entryId === null) continue;
    const channelId = item.channelId ?? 'platho.app';
    if (entryId > publicChannelCursor(channelId)) {
      publicReadCursors = {
        ...publicReadCursors,
        [channelId]: entryId.toString(),
      };
      changed = true;
    }
  }
  if (changed) writeScopedJsonMap(PUBLIC_READ_CURSORS_STORAGE_KEY, publicReadCursors);
  return changed;
}

// The "History sync — short / long" setting was REMOVED (owner, 2026-08-07). It had been inert for some time:
// publicSyncCutoffMs() normalised the stored value and then returned null unconditionally, so this function
// short-circuited to the whole cache and the date filter below it was unreachable. Both options rendered the
// same feed, which is worse than no control — a user picking "retained history, up to 1 year" was told they had
// widened their history and got nothing. Its vocabulary was pre-shard too ("newest 128 entries" counted the old
// monolithic hub; PublicShard pages 96 rows from the tail).
//
// Nothing replaces it: the feed shows whatever the shard still retains, which is what a channel carrying a long
// work needs. A saved `platho.publicSyncWindow.v1` is left in localStorage on existing devices — orphan data
// nobody reads, not worth a migration.

function isPendingPublicFeedItem(item) {
  return Boolean(item?.publishStatus && (item.entryId === undefined || item.entryId === null || item.entryId === ''));
}

function samePublicBodyHash(left, right) {
  const a = String(left?.bodyHash ?? '').toLowerCase();
  const b = String(right?.bodyHash ?? '').toLowerCase();
  return Boolean(a && b && a === b);
}

function mergeLocalPendingPublicFeed(channelId, chainPosts = []) {
  const cached = publicChannelFeedCache?.[channelId]?.feed ?? publicChannelFeedCache?.[channelId] ?? null;
  const localPosts = Array.isArray(cached?.posts) ? cached.posts : [];
  const merged = chainPosts.map((post) => {
    const matchingLocal = localPosts.filter((local) => (
      samePublicBodyHash(local, post)
      || (local.entryId && post.entryId && String(local.entryId) === String(post.entryId))
    ));
    const chainComments = post.comments ?? [];
    const pendingComments = matchingLocal
      .flatMap((local) => local.comments ?? [])
      .filter((comment) => isPendingPublicFeedItem(comment))
      .filter((comment) => !chainComments.some((chainComment) => samePublicBodyHash(comment, chainComment)));
    return pendingComments.length > 0
      ? { ...post, comments: [...chainComments, ...pendingComments] }
      : post;
  });
  const pendingPosts = localPosts
    .filter((post) => isPendingPublicFeedItem(post))
    .filter((post) => !chainPosts.some((chainPost) => samePublicBodyHash(post, chainPost)));
  return [...merged, ...pendingPosts]
    .sort((a, b) => new Date(a.createdAt ?? 0).getTime() - new Date(b.createdAt ?? 0).getTime());
}

function updatePublicJumpDownVisibility() {
  if (!publicJumpDownButton || !publicFeed) return;
  const maxScroll = Math.max(0, publicFeed.scrollHeight - publicFeed.clientHeight);
  // Newest is at the TOP now (v752): the jump-to-newest affordance shows once the user has scrolled DOWN
  // (away from the top) into older posts.
  const awayFromNewest = publicFeed.scrollTop > 80;
  publicJumpDownButton.hidden = !(maxScroll > 24 && awayFromNewest);
}

function updatePublicModeButtons() {
  // Public has a single view now (the Feed). Keep the dataset.publicMode='feed' marker so the feed-only CSS
  // ([data-public-mode="feed"]) keeps matching.
  if (publicPane) publicPane.dataset.publicMode = 'feed';
  if (publicChannelSearch) publicChannelSearch.placeholder = t('public.searchPlaceholder');
  if (publicDiscoverySearch) publicDiscoverySearch.placeholder = t('public.discoverSearchPlaceholder');
  updatePublicJumpDownVisibility();
  if (publicComposer) publicComposer.hidden = false;
}

function publicFeedItemMatchesSearch(item, query) {
  const needle = String(query ?? '').trim().toLowerCase();
  if (!needle) return true;
  const channel = publicChannelRegistry.find((entry) => entry.id === item.channelId) ?? null;
  const blockText = (blocks = []) => (blocks ?? [])
    .filter((block) => block?.type === 'text')
    .map((block) => block.text ?? '');
  const haystack = [
    item.title,
    item.text,
    ...blockText(item.blocks),
    item.author,
    item.authorWallet,
    item.bodyHash,
    item.channelId,
    channel?.name,
    channel?.subtitle,
    channel?.authorWallet,
    ...(item.meta ?? []),
    ...((item.comments ?? []).flatMap((comment) => [
      comment.author,
      comment.authorWallet,
      comment.text,
      ...blockText(comment.blocks),
    ])),
  ].filter(Boolean).join(' ').toLowerCase();
  return haystack.includes(needle);
}

// SKELETON PLACEHOLDERS (owner): shimmering card outlines while a list is still on its way — the discovery sweep
// before its first card, a comment thread before its first frame, the feed during the first sync. Purely decorative
// (aria-hidden); the status line next to them keeps saying what is happening (and how many buckets are left).
function buildSkeletonNodes(kind, count) {
  const fragment = document.createDocumentFragment();
  for (let i = 0; i < count; i += 1) fragment.append(buildSkeletonNode(kind));
  return fragment;
}

// ONE skeleton card. Split out of buildSkeletonNodes because a reconciled list needs every child to be a node it
// can key (see reconcileKeyedRows) — a fragment of three would arrive as three unkeyed children and be swept.
function buildSkeletonNode(kind) {
  {
    const card = document.createElement('div');
    card.className = `skeleton-card skeleton-${kind}`;
    card.setAttribute('aria-hidden', 'true');
    const head = document.createElement('div');
    head.className = 'skeleton-head';
    const avatar = document.createElement('span');
    avatar.className = 'skeleton skeleton-avatar';
    const title = document.createElement('span');
    title.className = 'skeleton skeleton-line skeleton-line-title';
    head.append(avatar, title);
    const line = document.createElement('span');
    line.className = 'skeleton skeleton-line';
    const short = document.createElement('span');
    short.className = 'skeleton skeleton-line skeleton-line-short';
    card.append(head, line, short);
    return card;
  }
}

function renderPublicEmpty(titleText, bodyText) {
  if (!publicFeed) return;
  const empty = document.createElement('article');
  empty.className = 'feed-item compact';
  const title = document.createElement('h2');
  title.textContent = titleText;
  const text = document.createElement('p');
  text.textContent = bodyText;
  empty.append(title, text);
  publicFeed.append(empty);
}

// Parity with the private .message-image affordance: a public feed/comment image is keyboard-focusable and opens
// the SAME full-size lightbox (delegated click/keydown on publicPane). Meta (dimensions + approx on-chain byte
// size, derivable from the data URL's base64 length) fills in once the image decodes.
function wirePublicImageLightbox(image, src) {
  image.alt = t('public.openImage');
  image.tabIndex = 0;
  image.role = 'button';
  image.title = t('public.openFullSizeImage');
  image.dataset.fullImageSrc = src;
  image.dataset.fullImageMeta = t('public.publicImage');
  image.addEventListener('load', () => {
    const base64 = String(src).split(',')[1] ?? '';
    const bytes = Math.floor(base64.length * 3 / 4);
    const dimensions = image.naturalWidth > 0 ? `${image.naturalWidth}x${image.naturalHeight}` : '';
    image.dataset.fullImageMeta = [dimensions, bytes > 0 ? imageByteCountLabel(bytes) : '']
      .filter(Boolean).join(' - ') || t('public.publicImage');
  }, { once: true });
}

// embedDepth bounds shared-post nesting: a repost OF a repost renders its inner card from the sender's snapshot and
// stops there, instead of each level fetching the next one's original.
function appendPublicItemContent(container, item, embedDepth = 0) {
  const blocks = Array.isArray(item?.blocks) ? item.blocks : [];
  if (blocks.length > 0) {
    for (const block of blocks) {
      if (block?.type === 'reply') {
        // Reply quote strip (tappable — scrolls to the quoted comment within the open post detail).
        container.append(buildReplyQuoteNode(block, publicPostDetailBody));
      } else if (block?.type === 'text' && block.text) {
        // v769: a DIV (not <p>) so the formatting renderer can emit block children (heading/list/quote) validly.
        const text = document.createElement('div');
        text.className = 'feed-block-text';
        appendFormattedMessageText(text, block.text);
        container.append(text);
      } else if (block?.type === 'image' && block.url) {
        const image = document.createElement('img');
        image.className = 'feed-image feed-block-image';
        image.src = block.url;
        image.loading = 'lazy';
        wirePublicImageLightbox(image, block.url);
        container.append(image);
      } else if (block?.type === 'file' && block.url) {
        // Receive-side forward-compat (v652): the public composer has no file attach UI yet, but a FILE block
        // arriving on the public surface renders the same download chip as private bubbles.
        container.append(buildFileBlockChip(block));
      } else if (block?.type === 'share' && block.entryId) {
        // Shared public post (v766): the embed card with the source channel's header.
        container.append(buildSharedPostEmbed(block, embedDepth));
      }
    }
    return;
  }
  if (item?.text) {
    const text = document.createElement('div');
    text.className = 'feed-block-text';
    appendFormattedMessageText(text, item.text);
    container.append(text);
  }
  if (item?.imageUrl) {
    const image = document.createElement('img');
    image.className = 'feed-image';
    image.src = item.imageUrl;
    image.loading = 'lazy';
    wirePublicImageLightbox(image, item.imageUrl);
    container.append(image);
  }
}

// Comment keys already painted: a comment new to the screen surfaces (owner); cleared when a post detail opens so
// its thread rises in again.
const publicCommentSurfacedKeys = new Map();

/**
 * WHAT A COMMENT ROW LOOKS LIKE, as a string — the reuse test for reconcileKeyedRows.
 *
 * The body itself is NOT in here beyond its size, and deliberately: the row's KEY is the chain entry id, or the
 * hash OF THE BODY for a comment that has not landed yet, so under a stable key the text cannot change. What does
 * change under a stable key is everything resolved later — the author's name and avatar arriving from the registry,
 * a pending comment's publish status ticking over, an image data url that persist stripped and a later sync
 * re-hydrated (the feed's signature carries the same term for the same reason) — plus the two display settings
 * baked into every row: the locale (button labels, relative dates) and the timestamp mode.
 */
function publicItemContentSignature(item) {
  const blocks = Array.isArray(item?.blocks) ? item.blocks : [];
  if (blocks.length > 0) {
    return blocks.map((block) => {
      const type = String(block?.type ?? '');
      if (type === 'text') return `t${String(block.text ?? '').length}`;
      if (type === 'image') return `i${block.url ? 1 : 0}`;
      if (type === 'file') return `f${block.url ? 1 : 0}.${String(block.name ?? '').length}`;
      if (type === 'share') return `s${block.entryId ?? ''}`;
      if (type === 'reply') return `r${block.entryId ?? ''}.${String(block.text ?? '').length}`;
      return type;
    }).join(',');
  }
  return `x${String(item?.text ?? '').length}${item?.imageUrl ? 'i' : ''}`;
}

function publicCommentRenderSignature(comment, avatarUrlMemo) {
  return [
    currentLocale(),
    feedTimestampMode(),
    comment?.author ?? '',
    comment?.createdAt ?? '',
    comment?.entryId ?? '',
    comment?.publishStatus ?? '',
    comment?.publishState ? publishStateMeta(comment.publishState) : '',
    (comment?.avatarImageUrl ?? publicAvatarUrlForWallet(comment?.authorWallet, avatarUrlMemo)) ?? '',
    publicItemContentSignature(comment),
  ].join('|');
}

/**
 * THE ROW'S IDENTITY — the same one mergePublicComments uses, so the two agree on what "the same comment" means.
 * A landed comment is its chain entry id; one still in flight is the hash of its body (which is what the merge
 * matches on to drop the local copy once the chain copy appears, so the row is rebuilt exactly once at that
 * moment, not on every render).
 */
function publicCommentRowKey(comment) {
  const entryId = comment?.entryId;
  if (entryId !== undefined && entryId !== null && String(entryId) !== '') return String(entryId);
  const hash = String(comment?.bodyHash ?? '');
  if (hash) return `hash:${hash}`;
  return comment?.id ? `local:${comment.id}` : '';
}

function buildPublicCommentRow(comment, surfacing) {
  {
    const row = document.createElement('article');
    row.className = 'comment-item';
    const surfaceKey = comment?.id ?? comment?.entryId ?? null;
    if (surfaceKey !== null && surfaceKey !== undefined
      && surfaceRow(row, publicCommentSurfacedKeys, String(surfaceKey), surfacing.count)) surfacing.count += 1;
    // Chain anchor (parity with private .message rows): the swipe-to-reply gesture reads it as the reply ref and
    // reply quotes scroll to it. A local-pending comment has none — replying to it waits for the entry id.
    if (comment.entryId !== undefined && comment.entryId !== null && comment.entryId !== '') row.dataset.entryId = String(comment.entryId);
    rememberMessageForRow(row, comment);   // same binding as private rows — long-press copy must not re-derive it
    const commentAuthorRow = document.createElement('div');
    commentAuthorRow.className = 'feed-author-row';
    const commentAvatar = document.createElement('div');
    commentAvatar.className = 'avatar feed-avatar';
    commentAvatar.setAttribute('aria-hidden', 'true');
    setAvatarNode(commentAvatar, String(comment.author ?? 'P').slice(0, 1), comment.avatarImageUrl ?? publicAvatarUrlForWallet(comment.authorWallet));
    const commentMeta = document.createElement('div');
    commentMeta.className = 'feed-meta';
    commentMeta.textContent = [comment.author, formatMetaTimestamp(comment.createdAt)].filter(Boolean).join(' - ');
    // Own pending comments show the SAME live private-style status badge as feed posts (publishStateMeta off
    // the streaming publishState; durable red on a failed terminal). CSS classes only (prod CSP).
    if (isPendingPublicFeedItem(comment) && comment.publishStatus) {
      const statusBadge = document.createElement('span');
      statusBadge.className = `public-publish-status${String(comment.publishStatus).endsWith('failed') ? ' public-publish-status--failed' : ''}`;
      statusBadge.textContent = (comment.publishState ? publishStateMeta(comment.publishState) : null) || comment.publishStatus;
      // Patch anchor for the status-only fast path (a publish tick updates this text in place, no rebuild).
      if (comment.id) statusBadge.dataset.publishLocalId = String(comment.id);
      commentMeta.append(statusBadge);
    }
    commentAuthorRow.append(commentAvatar, commentMeta);
    row.append(commentAuthorRow);
    appendPublicItemContent(row, comment);
    appendRowReplyButton(row, beginPublicCommentReplyForRow);
    appendRowCopyButton(row, copyTextFromContent(comment));
    return row;
  }
}

/**
 * The comment thread, reconciled rather than rebuilt.
 *
 * `keptList` is the .comment-list node from the PREVIOUS render, which renderPublicPostDetail holds on to across
 * its body rebuild. Without it every render would hand reconcileKeyedRows an empty container and rebuild all the
 * rows anyway — the wipe, not the loop, is what made this quadratic.
 */
function appendPublicItemComments(article, item, keptList = null) {
  const comments = Array.isArray(item?.comments) ? item.comments : [];
  if (comments.length === 0) return;
  const commentList = keptList ?? document.createElement('div');
  commentList.className = 'comment-list';
  const avatarUrlMemo = new Map();
  const surfacing = { count: 0 };
  reconcileKeyedRows(commentList, comments.map((comment) => ({
    key: publicCommentRowKey(comment),
    sig: publicCommentRenderSignature(comment, avatarUrlMemo),
    build: () => buildPublicCommentRow(comment, surfacing),
    // A reused row must point at the CURRENT comment object: mergePublicComments returns a fresh object on every
    // merge ({...old, ...new}), so the row's binding — which long-press copy and swipe-to-reply read — would
    // otherwise still hold the object from the render that first built the row.
    adopt: (row) => rememberMessageForRow(row, comment),
  })));
  article.append(commentList);
}

// Whether a public item is the logged-in user's OWN post. Falls back to the wallet address persisted in
// storage (record.address is plaintext — no decryption needed) so ownership is known from the FIRST public
// render, before the full wallet finishes loading. Without the fallback plathoWallet is briefly null at boot,
// so a user's own posts flash the author-only actions (the ▼ "Display as" chevron, "Private chat", "Unfollow")
// that only make sense for OTHER authors, until a later sync re-render corrects them.
function isOwnPublicAuthor(authorWallet) {
  if (!authorWallet) return false;
  const ownAddress = plathoWallet?.address ?? storedPlathoWalletRecord()?.address ?? null;
  return Boolean(ownAddress && sameWalletAddress(authorWallet, ownAddress));
}

// The "Display as" chevron for a public post — relabel another author (.ath / local name), shared
// per-counterparty and in sync with their Private dialog. Returns null for your own post, the official
// platho.app channel, or an item with no author wallet. Lives top-right in the post's author row in BOTH Feed
// and Channels modes (the channel-detail header no longer carries it).
function publicItemIdentityButton(item) {
  const authorWallet = item.authorWallet ?? item.author_wallet ?? null;
  const isOwnPost = isOwnPublicAuthor(authorWallet);
  if (!authorWallet || isOwnPost || item.channelId === DEFAULT_PUBLIC_CHANNEL_ID) return null;
  const identityButton = document.createElement('button');
  identityButton.type = 'button';
  identityButton.className = 'icon-button feed-author-identity';
  identityButton.setAttribute('aria-haspopup', 'menu');
  identityButton.setAttribute('aria-expanded', 'false');
  identityButton.title = t('public.chooseDisplayName');
  const identityIcon = document.createElement('span');
  identityIcon.className = 'icon icon-chevron-down';
  identityButton.append(identityIcon);
  identityButton.addEventListener('click', (event) => {
    event.stopPropagation();
    if (identityPopover && !identityPopover.hidden) {
      hideIdentityPopover();
    } else {
      showPublicChannelDisplayPopover({ authorWallet }, identityButton);
    }
  });
  return identityButton;
}

// The channel-description ("about") button for the post plate: an info glyph that opens the channel's PROFILE
// (description + tags) popover. Shown for any post with an author wallet — including the user's OWN channel and
// the official channel — since every channel can carry a description (the popover offers edit for own channels).
function publicItemDescriptionButton(item) {
  const authorWallet = item.authorWallet ?? item.author_wallet ?? null;
  if (!authorWallet) return null;
  const isOwn = isOwnPublicAuthor(authorWallet);
  const aboutButton = document.createElement('button');
  aboutButton.type = 'button';
  aboutButton.className = 'icon-button feed-author-about';
  aboutButton.setAttribute('aria-haspopup', 'dialog');
  aboutButton.setAttribute('aria-expanded', 'false');
  aboutButton.title = t('public.channelAbout');
  aboutButton.append(createChannelAboutIcon());
  aboutButton.addEventListener('click', (event) => {
    event.stopPropagation();
    if (identityPopover && !identityPopover.hidden && identityPopoverAnchor === aboutButton) {
      hideIdentityPopover();
    } else {
      showChannelDescriptionPopover(authorWallet, aboutButton, { isOwn }).catch((error) => console.error(error));
    }
  });
  return aboutButton;
}

function appendPublicItemActions(article, item) {
  const actions = document.createElement('div');
  actions.className = 'feed-actions';
  // The empty-channel placeholder card that this branch used to skip is gone (v896): a followed channel with no
  // posts is simply not rendered, so every item reaching here is a real post with something to comment on.
  {
    const commentButton = document.createElement('button');
    commentButton.type = 'button';
    const commentsAllowed = publicPostCommentsAllowed(item);
    const hasChainCommentTarget = publicPostHasChainCommentTarget(item);
    // Viewing comments needs no wallet — only an on-chain post to load them from. Posting a comment still
    // requires a wallet (enforced by the post detail composer). "Comments off" / "Preview only" stay disabled.
    const canViewComments = Boolean(commentsAllowed && hasChainCommentTarget);
    if (!commentsAllowed) {
      commentButton.textContent = t('public.commentsOff');
    } else if (!hasChainCommentTarget) {
      commentButton.textContent = t('public.previewOnly');
    } else {
      commentButton.textContent = t('public.comments');
    }
    commentButton.disabled = !canViewComments;
    commentButton.title = !commentsAllowed
      ? t('public.commentsClosedByAuthor')
      : (!hasChainCommentTarget
          ? t('public.previewNotOnChain')
          : t('public.openCommentsForPost'));
    commentButton.addEventListener('click', () => {
      if (!canViewComments) return;
      openPublicPostDetail(item);
    });
    // Pre-warm this post's durable comments (with images) into memory so opening it is instant + flash-free —
    // the private-message model (messages restored to memory before a thread opens). Only for openable posts.
    if (canViewComments) warmPublicPostCommentsCache(item);
    actions.append(commentButton);
  }

  const authorWallet = item.authorWallet ?? item.author_wallet ?? null;
  const isOwnPost = isOwnPublicAuthor(authorWallet);

  // "Share" (v766) — forward this post into My notes / a private contact / the own channel. Needs the post's
  // chain coordinates (same gate the share payload builder enforces): a local-pending post can't be shared yet.
  if (sharePayloadFromPublicItem(item)) {
    const shareButton = document.createElement('button');
    shareButton.type = 'button';
    shareButton.textContent = t('public.share');
    shareButton.title = t('public.sharePostTitle');
    shareButton.addEventListener('click', () => openSharePostDialog(item));
    actions.append(shareButton);
  }

  // "Private chat" — open the author in Private. HIDDEN on your own post: a dialog with yourself is meaningless.
  if (!isOwnPost) {
    const privateButton = document.createElement('button');
    privateButton.type = 'button';
    privateButton.textContent = t('public.privateChat');
    privateButton.disabled = !authorWallet;
    privateButton.title = authorWallet
      ? t('public.openAuthorInPrivate')
      : t('public.authorWalletUnavailable');
    privateButton.addEventListener('click', () => {
      if (!authorWallet) return;
      openPrivateThreadForWallet(authorWallet);
    });
    actions.append(privateButton);
  }

  // "Unfollow" — moved here from the channel-detail header so it sits with the post actions in BOTH Feed and
  // Channels modes. Shown only when the post's channel is currently subscribed (so it is actionable) AND it is not
  // the user's own post: publishing in Channels mode auto-subscribes the OWN channel (ensurePublicChannelForAuthorWallet
  // activate:true), so without the !isOwnPost guard Unfollow would wrongly appear on the user's own posts.
  if (!isOwnPost && isPublicChannelSubscribed(item.channelId)) {
    const unfollowButton = document.createElement('button');
    unfollowButton.type = 'button';
    unfollowButton.textContent = t('public.unfollow');
    unfollowButton.title = t('public.stopFollowingChannel');
    unfollowButton.addEventListener('click', () => {
      // Unfollowing from a card INSIDE the open channel view keeps the view's posts visible (the channel becomes
      // a transient preview source) — the same protocol as the header unfollow; without it the open screen
      // flips to a false "No posts yet".
      if (publicChannelViewOpen && publicChannelViewChannelId === item.channelId) {
        publicChannelPreviewChannelId = item.channelId;
      }
      setPublicChannelSubscribed(item.channelId, false);
    });
    actions.append(unfollowButton);
  }
  article.append(actions);
}

// ---- Share a public post (v766): into My notes / a private contact / the own channel ----
// The modal picks the TARGET; choosing navigates to that composer surface with the share draft attached (a
// cancellable chip + a positional [post] marker). The draft is a SNAPSHOT (entryId + bodyHash + author wallet +
// title/text excerpt) — the send encodes it as a SHARE document block.
let pendingSharePayload = null;

function sharePayloadFromPublicItem(item) {
  // Chain coordinates are REQUIRED (same gate as commenting): a local-pending post has no entryId yet.
  if (item?.entryId === undefined || item?.entryId === null) return null;
  if (!/^0x[0-9a-fA-F]{64}$/.test(String(item?.bodyHash ?? ''))) return null;
  const authorWallet = rawWalletAddress(item.authorWallet);
  if (!authorWallet) return null;
  const blocks = Array.isArray(item.blocks) ? item.blocks : [];
  const fullText = publicPostFullText(item);
  // Truncate at DRAFT time (not just at encode) so the optimistic echo shows exactly what the wire carries.
  const snippet = truncateUtf8ToShareSnippet(fullText);
  return {
    entryId: String(item.entryId),
    bodyHash: String(item.bodyHash),
    authorWallet,
    author: String(item.author ?? '').trim() || publicAuthorLabel(authorWallet) || shortAddress(authorWallet),
    title: String(item.title ?? ''),
    snippet,
    fullText, // untruncated — used by the "copy to clipboard" share target (the wire SHARE block still uses snippet)
    permalink: publicPostPermalink(item), // the external link target; null when the post has no addressable row
    hasImage: blocks.some((block) => block?.type === 'image' && block.url) || Boolean(item.imageUrl),
    textTruncated: snippet.length < fullText.length,
  };
}

// UTF-8-safe byte-bounded cut for the share snippet (matches the codec's truncateUtf8ToBytes semantics).
function truncateUtf8ToShareSnippet(text) {
  const value = String(text ?? '');
  const encoder = new TextEncoder();
  if (encoder.encode(value).length <= SHARE_SNIPPET_MAX_BYTES) return value;
  // Byte length >= char count, so a char-cut to the byte budget lands close; then trim to the exact bound.
  let out = value.slice(0, SHARE_SNIPPET_MAX_BYTES);
  while (out.length > 0 && encoder.encode(out).length > SHARE_SNIPPET_MAX_BYTES) out = out.slice(0, -1);
  return out;
}

function openSharePostDialog(item) {
  const share = sharePayloadFromPublicItem(item);
  if (!share) return;
  pendingSharePayload = share;
  renderSharePostList();
  if (sharePostDialog) { sharePostDialog.classList.remove('is-closing'); sharePostDialog.hidden = false; }
}

function closeSharePostDialog() {
  pendingSharePayload = null;
  hideDialogAnimated(sharePostDialog);
}

// Clipboard-copy glyph for the "copy to clipboard" share target (same inline-SVG style as the Saved pencil).
const SHARE_COPY_ICON_SVG =
  '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'
  + '<rect x="9" y="9" width="11" height="11" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>';

// Chain-link glyph for the "share a link" target (same inline-SVG style as the copy glyph above).
const SHARE_LINK_ICON_SVG =
  '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'
  + '<path d="M10 13a5 5 0 0 0 7.5.5l3-3a5 5 0 0 0-7-7l-1.7 1.7"/>'
  + '<path d="M14 11a5 5 0 0 0-7.5-.5l-3 3a5 5 0 0 0 7 7l1.7-1.7"/></svg>';

/**
 * Should this platform hand the URL to its own share sheet instead of the clipboard?
 *
 * TOUCH ONLY. On a phone the sheet is the whole point — the real messengers are there. On Windows it is a
 * different dialog entirely: it lists Microsoft Store apps that registered a share handler, offers to INSTALL
 * ones that are not present, and cannot see desktop Telegram at all (a classic desktop app registers no share
 * target). MEASURED 2026-08-13 — the owner was offered "Telegram for Windows (Unigram)" with an install button
 * and asked, reasonably, what that was. Nothing on the page can improve that list, so desktop copies instead.
 *
 * `(pointer: coarse)` is the primary-pointer query: true on phones and tablets, false on a desktop, and false on
 * a touch laptop being used with its trackpad — which is the right answer for all three.
 */
function canSystemShareLink(url) {
  if (typeof navigator === 'undefined' || typeof navigator.share !== 'function') return false;
  if (typeof matchMedia === 'function' && !matchMedia('(pointer: coarse)').matches) return false;
  // Some engines expose share() but refuse a url-only payload; canShare is the only honest way to ask.
  if (typeof navigator.canShare === 'function') {
    try { return navigator.canShare({ url }); } catch { return false; }
  }
  return true;
}

function buildShareTargetRow({ label, sublabel, avatarUrl, thread, icon, onChoose }) {
  const row = document.createElement('button');
  row.type = 'button';
  row.className = 'share-target-row';
  const avatar = document.createElement('div');
  avatar.className = 'avatar share-target-avatar';
  avatar.setAttribute('aria-hidden', 'true');
  if (thread) {
    setThreadAvatarNode(avatar, thread); // Saved (My notes) -> its pencil icon, not the wallet-letter avatar
  } else if (icon === 'copy' || icon === 'link') {
    avatar.classList.add('avatar-saved'); // reuse the icon-tinted avatar look
    avatar.innerHTML = icon === 'link' ? SHARE_LINK_ICON_SVG : SHARE_COPY_ICON_SVG;
  } else {
    setAvatarNode(avatar, String(label ?? 'P').slice(0, 1), avatarUrl);
  }
  const text = document.createElement('span');
  text.className = 'share-target-text';
  const name = document.createElement('span');
  name.className = 'share-target-name';
  name.textContent = label;
  text.append(name);
  if (sublabel) {
    const sub = document.createElement('span');
    sub.className = 'share-target-sublabel';
    sub.textContent = sublabel;
    text.append(sub);
  }
  row.append(avatar, text);
  row.addEventListener('click', onChoose);
  return row;
}

function renderSharePostList() {
  if (!sharePostList) return;
  sharePostList.replaceChildren();
  // Order: the two ways OUT of Platho first (link, then the text), then My notes, the own public channel, and
  // private contacts in the THREAD LIST's order (thread-list-order.mjs: pinned by recency, then the rest by recency).
  // The link leads because it is the only target that reaches someone who is not here yet — the others all need a
  // Platho account on the other end.
  const permalink = pendingSharePayload?.permalink ?? null;
  if (permalink) {
    sharePostList.append(buildShareTargetRow({
      // Same row, honest label: a phone hands the URL to its share sheet, a desktop browser can only copy it.
      label: canSystemShareLink(permalink) ? t('dialog.shareLink') : t('dialog.shareCopyLink'),
      sublabel: permalink.replace(/^https?:\/\//, ''),
      icon: 'link',
      onChoose: () => chooseShareLink(),
    }));
  }
  sharePostList.append(buildShareTargetRow({
    label: t('dialog.shareCopyToClipboard'),
    icon: 'copy',
    onChoose: () => chooseShareCopyToClipboard(),
  }));
  const ownWallet = rawWalletAddress(plathoWallet?.address ?? storedPlathoWalletRecord()?.address);
  const own = ownPublicChannel();
  const visible = threads.filter((thread) => !thread.readOnly && !isTransientPendingResolutionThread(thread));
  // My notes (Saved) first — with its pencil icon, not the wallet-letter avatar.
  for (const thread of visible.filter((thread) => isSavedMessagesThread(thread))) {
    const wallet = threadPrimaryWalletRaw(thread);
    if (!wallet) continue;
    sharePostList.append(buildShareTargetRow({
      label: t('chat.myNotes'),
      thread,
      onChoose: () => chooseShareTargetThread(thread),
    }));
  }
  // Then the own public channel (a repost).
  if (own && ownWallet) {
    sharePostList.append(buildShareTargetRow({
      label: t('dialog.shareToOwnChannel'),
      sublabel: t('public.you'),
      avatarUrl: publicAvatarUrlForWallet(ownWallet),
      onChoose: () => chooseShareTargetOwnChannel(),
    }));
  }
  // Then private contacts — the SAME order as the thread list (pinned by recency, then the rest by recency). Saved is
  // already out (rendered above), so only the tail of the shared ordering remains.
  visible.forEach(hydrateThreadDisplayFromContactStore); // a thread never painted in the list still gets its pin flag (no-op once synced)
  const contacts = orderThreadsForList(visible, {
    isSaved: isSavedMessagesThread,
    isPinned: isThreadPinned,
    lastActivityMs: threadLastActivityMs,
  }).filter((thread) => !isSavedMessagesThread(thread));
  for (const thread of contacts) {
    const wallet = threadPrimaryWalletRaw(thread);
    if (!wallet) continue;
    sharePostList.append(buildShareTargetRow({
      label: thread.name || shortAddress(wallet),
      sublabel: shortAddress(wallet),
      avatarUrl: publicAvatarUrlForWallet(wallet),
      onChoose: () => chooseShareTargetThread(thread),
    }));
  }
}

function insertShareMarker(textarea) {
  if (!textarea) return;
  COMPOSER_SHARE_MARKER_RE.lastIndex = 0;
  if (COMPOSER_SHARE_MARKER_RE.test(String(textarea.value ?? ''))) return;
  insertComposerMarker(textarea, '[post]');
}

function chooseShareTargetThread(thread) {
  const share = pendingSharePayload;
  closeSharePostDialog();
  const wallet = threadPrimaryWalletRaw(thread);
  if (!share || !wallet) return;
  // The canonical open path (selectOrCreateRecipientThread) — matches by identity variants, so Saved and every
  // existing dialog resolve to their real thread; view + chatOpen handled inside.
  if (!openPrivateThreadForWallet(wallet)) return;
  setPrivateShareDraft(share);
  insertShareMarker(messageInput);
  focusComposerField(messageInput);
}

function chooseShareTargetOwnChannel() {
  const share = pendingSharePayload;
  closeSharePostDialog();
  const own = ownPublicChannel();
  if (!share || !own) return;
  setView('public');
  openPublicChannelView({ channelId: own.id, authorWallet: rawWalletAddress(plathoWallet?.address ?? storedPlathoWalletRecord()?.address) });
  setPublicShareDraft(share);
  insertShareMarker(publicMessageInput);
  focusComposerField(publicMessageInput);
}

/**
 * Share the post's permalink OUTSIDE Platho. The system share sheet when the platform has one (that is what
 * "share" means on a phone), the clipboard otherwise. A dismissed sheet is the user changing their mind, not a
 * failure, so it reports nothing.
 */
async function chooseShareLink() {
  const share = pendingSharePayload;
  closeSharePostDialog();
  await shareLinkOutOfPlatho(share?.permalink, share?.title);
}

// Copy the shared post's text to the clipboard (title + the UNTRUNCATED body) — a plain "take it elsewhere" affordance.
function chooseShareCopyToClipboard() {
  const share = pendingSharePayload;
  closeSharePostDialog();
  if (!share) return;
  const text = [String(share.title ?? '').trim(), String(share.fullText ?? '').trim()].filter(Boolean).join('\n\n');
  copyTextToClipboard(text)
    .then(() => setPublicStatus(t('dialog.shareCopied')))
    .catch((error) => { console.error(error); setPublicStatus(t('dialog.shareCopyFailed')); });
}

sharePostCloseButton?.addEventListener('click', () => closeSharePostDialog());
// v794: X-only — the share dialog closes ONLY via its ✕ (an outside/backdrop tap no longer dismisses it).

// Ids the feed has already painted (session-long, see surfaceRow): only a post new to the screen rises in.
const publicFeedSurfacedIds = new Map();
function renderPublicFeed(items, options = {}) {
  if (!publicFeed) return;
  publicFeed.dataset.publicMode = 'feed';
  const allItems = items ?? [];
  if (allItems.length === 0) {
    publicFeed.replaceChildren();
    // The discovery CTA sits at the very top for a newcomer (no channels followed) — shown ABOVE the posts, and also
    // above the empty-state so a newcomer with a truly empty feed still gets a way in.
    if (shouldShowDiscoveryCta()) publicFeed.append(buildDiscoveryCtaCard());
    // "No public posts" is a CONCLUSION, and stating it while the first sync is still running would be a guess
    // dressed as one — on a fresh install the feed is empty for the seconds before platho.app's posts land. This
    // used to be masked by a per-channel placeholder card that said "waiting for public feed"; that card is gone
    // (v896, it also held an empty seat for channels that never publish), so the waiting has to be said HERE, once
    // for the whole feed, instead of once per silent channel. setPublicSyncPhase repaints this surface on every
    // transition, so the message settles by itself when the sync finishes.
    if (publicSyncPhase === 'syncing' && !publicChannelSearchQuery) {
      publicFeed.append(buildSkeletonNodes('post', 2));
      renderPublicEmpty(t('public.previewWaitingFeed'), t('common.checking'));
    } else {
      renderPublicEmpty(publicChannelSearchQuery ? t('public.noPostsFound') : t('public.noPosts'), publicChannelSearchQuery ? t('public.tryAnotherSearch') : t('public.followOrPublishFirst'));
    }
    requestAnimationFrame(updatePublicJumpDownVisibility);
    return;
  }
  // F2 cap (newest-first feed: newest at the TOP): render only the newest publicFeedShownCap items; the rest sit
  // behind a "show older" button at the BOTTOM. We do NOT grow the cap toward an old unread anymore: the feed lands on
  // the newest (top), so an old unread stays behind "show older" (still unread until actually revealed) instead of
  // forcing a full-history render on every open and marking an off-screen post read.
  const hiddenOlderCount = Math.max(0, allItems.length - publicFeedShownCap);
  const windowItems = hiddenOlderCount > 0 ? allItems.slice(hiddenOlderCount) : allItems;
  // Preserve the reader's position across a background (non-anchor) re-render: newest-first prepends new posts at the
  // TOP, which would shove a scrolled-down reader's content down (iOS/WebKit has no overflow-anchor). Snapshot the
  // topmost visible article + its viewport offset now, restore it after the DOM is rebuilt below. Skipped at the top
  // (scrollTop 0 -> new posts simply appear) and on an anchorUnread render (we jump to the newest instead).
  let scrollAnchor = null;
  if (!options.anchorUnread && publicFeed.scrollTop > 0) {
    const feedTop = publicFeed.getBoundingClientRect().top;
    for (const node of publicFeed.children) {
      if (!node.dataset?.itemId) continue;
      const nodeTop = node.getBoundingClientRect().top - feedTop;
      if (nodeTop + node.offsetHeight > 0) { scrollAnchor = { id: node.dataset.itemId, offset: nodeTop }; break; }
    }
  }
  // F2 keyed reconciliation, through the shared primitive (reconcileKeyedRows): reuse each <article> whose render
  // signature is unchanged since the last render — the common case on a background sync, post content being
  // immutable — build only new or changed ones, and move the rest. That also keeps the scroll position stable (no
  // replaceChildren flicker) while the user is scrolled up reading, across the frequent background re-renders.
  const avatarUrlMemo = new Map();
  const entries = [];
  // The discovery CTA stays at the very top (a newcomer sees it first).
  if (shouldShowDiscoveryCta()) {
    entries.push({ key: 'cta', sig: `${currentLocale()}`, build: () => buildDiscoveryCtaCard() });
  }
  // Newest-FIRST (v752, owner ask: newer posts on TOP): render the window REVERSED so newer posts sit at the top;
  // the "show older" button then goes at the BOTTOM (below the oldest rendered post). windowItems is oldest→newest.
  let surfacing = 0;
  for (const item of windowItems.slice().reverse()) {
    const key = String(item.id);
    entries.push({
      key,
      sig: publicFeedItemRenderSignature(item, avatarUrlMemo),
      build: () => {
        const article = buildPublicFeedArticle(item, avatarUrlMemo);
        article.dataset.itemId = key;   // the scroll anchor's key, read before the reconcile
        // A post this feed has not shown yet SURFACES (owner) — the first paint, a newly landed post, a revealed
        // older one; a rebuild for a changed signature (locale, timestamp mode) stays still.
        if (surfaceRow(article, publicFeedSurfacedIds, key, surfacing)) surfacing += 1;
        return article;
      },
    });
  }
  if (hiddenOlderCount > 0) {
    entries.push({
      key: 'older',
      sig: `${currentLocale()}|${hiddenOlderCount}`,
      build: () => buildShowOlderButton(hiddenOlderCount),
    });
  }
  reconcileKeyedRows(publicFeed, entries);
  if (options.anchorUnread && publicFeed) {
    // Fresh view: land on the newest, now at the TOP (the old chat-style feed anchored to the oldest unread instead).
    requestAnimationFrame(() => { publicFeed.scrollTop = 0; updatePublicJumpDownVisibility(); });
  } else if (scrollAnchor && publicFeed) {
    // Restore the anchored article to the same viewport offset so a new post added ABOVE doesn't shove the reader;
    // content added BELOW (via "show older") leaves the anchor put, so this is a no-op there.
    const feedTop = publicFeed.getBoundingClientRect().top;
    for (const node of publicFeed.children) {
      if (node.dataset?.itemId !== scrollAnchor.id) continue;
      const nodeTop = node.getBoundingClientRect().top - feedTop;
      publicFeed.scrollTop = Math.max(0, publicFeed.scrollTop + (nodeTop - scrollAnchor.offset));
      break;
    }
  }
  requestAnimationFrame(updatePublicJumpDownVisibility);
  // Viewing the feed marks its (rendered) posts read (only when the Public tab is actually on screen, so a
  // background sync does not pre-clear unread). NOT while an overlay (post detail / discovery / channel view)
  // covers the feed — it is display:none then and the user cannot see the posts being marked. Re-render once to
  // drop the unread badges.
  if (isPublicViewActive() && !publicPostDetailOpen && !publicDiscoveryOpen && !publicChannelViewOpen
    && markVisiblePublicFeedRead(windowItems)) {
    requestAnimationFrame(() => renderPublicSurface({ anchorUnread: false }));
  }
}

// --- Long-post collapse (feed + channel view, v765) ---
// A long post renders clamped to --feed-post-collapsed-max-height with a "Show full post" button; expanding
// releases the clamp IN PLACE (no re-render — content grows downward under the reader). Session-scoped by item
// id, so the signature-driven article rebuilds (unread -> read, identity changes, background syncs) re-render an
// expanded post EXPANDED instead of snapping it shut. Never persisted — a fresh session starts collapsed again.
const publicFeedExpandedPosts = new Set();
// A clamp that hides less than this many pixels is released silently instead of showing the button: a
// "Show full post" that reveals a two-line sliver is worse than just showing the two lines.
const FEED_POST_CLAMP_SLACK_PX = 120;
// One shared observer for every rendered post body. It watches the UNCLAMPED inner wrapper — once the clamp
// bites, the outer clamped box stays at max-height forever, so an observer bound to it would never fire when a
// lazy image decodes later and grows the content. scrollHeight (full content) vs clientHeight (clamped box) on
// the OUTER box then says whether the clamp actually cuts anything. Pre-ResizeObserver engines get null: the
// collapsible class is then never added, so nothing is ever clamped (fail-open to the full-height feed — a
// clamp with no way to ever show the expand button would silently cut content).
const feedPostClampObserver = typeof ResizeObserver === 'function' ? new ResizeObserver((entries) => {
  for (const entry of entries) {
    const body = entry.target.parentElement;
    // The collapsible ROOT is always the clamped body's parent — a feed <article> or a shared-post embed
    // (v766); the CSS clamp rules are direct-child (`.feed-post-collapsible > .feed-post-body`) so a nested
    // embed clamp never leaks into (or inherits from) the post clamp around it.
    const root = body ? body.parentElement : null;
    if (!body || !root || !root.classList.contains('feed-post-collapsible')) continue;
    const clippedHeight = body.scrollHeight - body.clientHeight;
    if (clippedHeight > FEED_POST_CLAMP_SLACK_PX) {
      root.classList.add('feed-post-overflowing');
    } else if (clippedHeight > 0) {
      // Near-miss: the clamp bites but hides less than the slack — release it with no button, so content is
      // never silently cut. Not added to publicFeedExpandedPosts (that set records USER intent); a rebuilt
      // article simply re-measures and re-releases.
      root.classList.remove('feed-post-collapsible', 'feed-post-overflowing');
    } else {
      root.classList.remove('feed-post-overflowing');
    }
  }
}) : null;

// Animated clamp release (owner ask: expanding should feel alive): transition max-height from the clamped
// height to the measured full height, then drop the clamp entirely (max-height:none — later image growth stays
// unclamped). CSSOM per-property assignment only (prod CSP kills setAttribute('style'), allows .style.prop).
// prefers-reduced-motion turns the transition off in CSS — transitionend then never fires, so the timer
// backstop (also covering a mid-flight display:none) guarantees the release either way. The expanded class
// keeps the toggle button visible (relabeled "Collapse" by the caller).
function expandClampedBody(root, body) {
  const fullHeight = body.scrollHeight;
  body.style.maxHeight = `${body.clientHeight}px`;
  root.classList.add('feed-post-expanding', 'feed-post-expanded');
  root.classList.remove('feed-post-collapsible', 'feed-post-overflowing');
  requestAnimationFrame(() => { body.style.maxHeight = `${fullHeight}px`; });
  const release = () => {
    body.style.removeProperty('max-height');
    root.classList.remove('feed-post-expanding');
  };
  body.addEventListener('transitionend', release, { once: true });
  window.setTimeout(release, 450);
}

// Reverse toggle (owner ask v767): re-clamp an expanded post/embed, animated from the current full height down
// to the CSS clamp — the exact MIRROR of expandClampedBody. The clamp target is read from the :root var that
// applies to this root (posts vs shared-post embeds); an unparseable value degrades to an instant un-animated
// re-clamp. The clamp classes (feed-post-collapsible/-overflowing) are re-applied ONLY in settle(), never up
// front: adding feed-post-collapsible before the transition sets max-height to the clamp instantly, and reading
// scrollHeight while it is applied would commit that clamped height as the transition baseline — so the
// 850->480 change nets to zero and the browser skips the animation (the "collapses instantly" bug). settle()
// also pulls the card back into view: collapsing removes the content the reader was level with, which would
// otherwise strand them past the card's new bottom.
function collapseClampedBody(root, body) {
  const varName = root.classList.contains('shared-post-embed') ? '--shared-post-embed-max-height' : '--feed-post-collapsed-max-height';
  const target = Number.parseFloat(getComputedStyle(root).getPropertyValue(varName));
  root.classList.remove('feed-post-expanded');
  let released = false;
  const settle = () => {
    if (released) return;
    released = true;
    body.style.removeProperty('max-height');
    root.classList.remove('feed-post-expanding');
    root.classList.add('feed-post-collapsible', 'feed-post-overflowing');
    root.scrollIntoView({ block: 'nearest' });
  };
  if (!Number.isFinite(target)) { settle(); return; }
  // Pin the CURRENT full height inline (the body still renders unclamped here — no visual change), turn on the
  // transition, then animate down to the clamp value. The 850px baseline is the last rendered height, so the
  // rAF change to the clamp target animates. overflow:hidden comes from feed-post-expanding during the run.
  body.style.maxHeight = `${body.scrollHeight}px`;
  root.classList.add('feed-post-expanding');
  requestAnimationFrame(() => { body.style.maxHeight = `${target}px`; });
  body.addEventListener('transitionend', settle, { once: true });
  window.setTimeout(settle, 450);
}

// The shared expand/collapse toggle button for a clamped root (feed article or shared-post embed): one button,
// relabeled per state, session state carried by `expandedSet[key]` so rebuilds re-render the current state.
function wireClampToggleButton(root, body, inner, expandedSet, key) {
  const expanded = expandedSet.has(key);
  root.classList.add(expanded ? 'feed-post-expanded' : 'feed-post-collapsible');
  const toggleButton = document.createElement('button');
  toggleButton.type = 'button';
  toggleButton.className = 'feed-expand-button';
  toggleButton.textContent = expanded ? t('public.collapsePost') : t('public.showFullPost');
  toggleButton.addEventListener('click', (event) => {
    event.stopPropagation();
    if (expandedSet.has(key)) {
      expandedSet.delete(key);
      toggleButton.textContent = t('public.showFullPost');
      feedPostClampObserver.observe(inner);
      collapseClampedBody(root, body);
    } else {
      expandedSet.add(key);
      toggleButton.textContent = t('public.collapsePost');
      feedPostClampObserver.unobserve(inner);
      expandClampedBody(root, body);
    }
  });
  root.append(toggleButton);
  if (!expanded) feedPostClampObserver.observe(inner);
}

// Session-expanded shared-post embeds, by the SHARED post's entry id: private bubbles and feed articles rebuild
// on every render pass, so a DOM-only expand would snap shut — the builder re-applies from here (the
// publicFeedExpandedPosts pattern one level down).
const expandedSharedEmbeds = new Set();

// The image of a resolved public post (the top-level imageUrl of an image-only post, or the first image block of
// a text+image post), or null when it carries none / hasn't warmed its media yet.
function sharedPostImageUrlFromPost(post) {
  const media = publicPostRenderableImageMedia(post);
  if (!media) return null;
  if (media.imageUrl) return media.imageUrl;
  const imageBlock = (media.blocks ?? []).find((b) => b?.type === 'image' && typeof b.url === 'string' && b.url.length > 0);
  return imageBlock?.url ?? null;
}

// The original public post a SHARE embed references, found in the subscribed/viewed feed cache by entryId (posts
// carry both id and entryId). null when the channel isn't cached locally.
function findCachedPublicPostByEntryId(entryId) {
  const target = String(entryId ?? '');
  if (!target) return null;
  let found = null;
  eachCachedPublicPost((post) => {
    if (found || !post) return;
    if (String(post.entryId ?? '') === target || String(post.readEntryId ?? '') === target) found = post;
  });
  return found;
}

// Canonical 32-byte body hash (lowercase, no 0x), or null when malformed — for comparing a SHARE block's bodyHash
// to a resolved post's, so both forms (with/without 0x, any case) match.
function normalizeBodyHashHex(value) {
  const hex = String(value ?? '').replace(/^0x/i, '').toLowerCase();
  return /^[0-9a-f]{64}$/.test(hex) ? hex : null;
}

// v797: a SHARE is an internal REFERENCE (entryId), not a copy — the original post's image already lives on-chain
// (retained >=1 year by CapsuleHub) and never rides the wire again. Resolve that image by entryId from LOCAL caches
// only: the feed cache (subscribed/viewed channels), warming a stripped light item from the durable post-media
// store. Returns the image data-url, or null when the post isn't cached (a cold recipient who never opened the
// channel — the embed header still taps through to the live original). Best-effort + non-throwing (render backstop).
// REFERENCE INTEGRITY: the whole SHARE block is sender-authored, so the resolved post's bodyHash must match the
// block's expectedBodyHash (content-addressed) — else a crafted entryId could show an UNRELATED cached post's image
// under the sender's claimed channel/label. No match -> null (keep the hint). Only the recipient's OWN decoded media
// is ever shown; sender bytes never cross.
/**
 * A REPOST CARRIES A POINTER. THIS IS WHAT FOLLOWS IT.
 *
 * OBSERVED 2026-08-07 by the owner: a reposted public post arrives incomplete and with no picture.
 *
 * The SHARE block is a reference by design — entry id, body hash, author wallet, a 4KB text snapshot and a
 * "has image" flag — because copying the picture would republish it on chain at full price. What was missing is the
 * other half: NOTHING EVER FOLLOWED THE REFERENCE. The only resolver looked in this device's own feed cache, and the
 * recipient of a repost is by definition someone who probably does not follow that channel. So the picture never
 * appeared and the text stayed a fragment, on a pointer that was complete the whole time.
 *
 * ONE READ, THEN NEVER AGAIN. The result is merged into the SAME feed cache the sync writes, so the second render —
 * and every render after a reload, since commitPublicChannelFeedCache persists text to localStorage and image media
 * to IndexedDB — costs nothing. A cache hit never touches the network at all.
 *
 * ADDRESSED, NOT SCANNED: the feed id IS the coordinates (epochTag.shardSeq.entryId), so this reads one shard from
 * one row. Cost does not grow with the channel, and an old post in a large channel is reachable — readChannelPosts
 * would find neither.
 */
const sharedPostChainReads = new Map();   // feed entryId -> Promise<post|null>
const SHARED_POST_CHAIN_READ_LIMIT = 256;

/** epochTag.shardSeq.entryId -> the three coordinates, or null for a v1 share (a bare uint64, pre-shard). */
function sharedPostShardCoordinates(entryId) {
  const parts = String(entryId ?? '').split('.');
  if (parts.length !== 3 || !parts.every((part) => /^\d+$/.test(part))) return null;
  return { epochTag: parts[0], shardSeq: Number(parts[1]), shardEntryId: parts[2] };
}

/**
 * A public post's CHAIN COORDINATES — author wallet + channel epoch tag + channel shard seq + the RAW per-shard
 * entry id. Both the comment READ and the comment WRITE fold exactly these into the post's thread address.
 *
 * DERIVED, NEVER CARRIED. The feed entryId IS `${epochTag}.${shardSeq}.${shardEntryId}`, so the coordinates are
 * already inside it. They used to be read off separate item fields, and the copy did not survive: neither
 * publicChannelFeedToThread nor publicChannelThreadsToFeedItems ever mapped them, and normalizeFeedPost (a strict
 * whitelist) strips them from the cache. Only a post held in memory straight from the shard walk still had them,
 * so commenting worked from a SHARE embed and NOWHERE ELSE — MEASURED 2026-08-13, the owner commented on a post
 * found through channel search and got "parent is missing its channel coordinates" in the console while the code
 * comment above the read claimed "the opened post carries channelEpochTag/authorWallet from the shard feed".
 *
 * Explicit fields still win when present, so a freshly-walked post behaves exactly as before.
 */
function publicPostChainCoordinates(item) {
  const authorWallet = item?.authorWallet ?? null;
  if (!authorWallet || item?.entryId === undefined || item?.entryId === null) return null;
  const derived = sharedPostShardCoordinates(item.entryId);
  const epochTag = item.channelEpochTag ?? derived?.epochTag ?? null;
  const shardEntryId = item.shardEntryId ?? derived?.shardEntryId ?? null;
  const shardSeq = item.channelShardSeq ?? derived?.shardSeq ?? null;
  if (epochTag === null || shardEntryId === null || shardSeq === null) return null;
  try {
    return {
      authorWallet,
      epochTag: BigInt(epochTag),
      shardSeq: Number(shardSeq),
      shardEntryId: BigInt(shardEntryId),
    };
  } catch {
    return null;   // a malformed id is not a thread address; the caller decides what to say about it
  }
}

/**
 * ONE addressed read of a public post, shared by both ways in: a SHARE block's reference and an external
 * permalink. The caller supplies `selectPost` because the two have DIFFERENT notions of which post answers —
 * see the two call sites — but everything around it (coordinates, shard read, assembly, cache write) is one
 * mechanism, so a fix to it lands on both.
 */
async function fetchPublicPostFromChain(entryId, authorWallet, selectPost) {
  const lane = directPublicLaneReader();
  const wallet = rawWalletAddress(authorWallet);
  const coords = sharedPostShardCoordinates(entryId);
  if (!lane || !wallet || !coords) return null;
  // Registers the channel UNSUBSCRIBED — the same semantics discovery uses, so following a reference never turns
  // into a follow. The id is only needed to key the post in the feed cache.
  const channelId = ensurePublicChannelForAuthorWallet(wallet, { activate: false });
  if (!channelId) return null;
  const shardPosts = await lane.readPostAt(wallet, coords.epochTag, coords.shardSeq, coords.shardEntryId);
  if (shardPosts.length === 0) return null;
  const parts = await publicPostPartsFromShardPosts(shardPosts, { id: channelId, authorWallet: wallet });
  const post = assemblePublicParts(parts).find((item) => selectPost(item)) ?? null;
  if (!post) return null;
  const updatedAt = new Date().toISOString();
  const cachedFeed = publicChannelFeedCache?.[channelId]?.feed ?? publicChannelFeedCache?.[channelId];
  const existing = (cachedFeed?.posts ?? []).filter(publicFeedPostHasChainAnchor);
  const merged = mergeLocalPendingPublicFeed(channelId, upsertPublicChainPosts(existing, [post]));
  publicChannelFeedCache = {
    ...publicChannelFeedCache,
    [channelId]: { feed: { version: 1, channelId, updatedAt, posts: merged }, syncedAt: updatedAt },
  };
  commitPublicChannelFeedCache();   // text -> localStorage, image media -> IndexedDB. Survives the reload.
  return post;
}

/**
 * A SHARE block's original. CONTENT-AUTHENTIC OR NOTHING: the read window holds the neighbouring entries too, and
 * the SENDER chose these coordinates — so only the post whose body hashes to what the reference claims may answer
 * for it. Without that check a crafted reference could show an unrelated post under a trusted sender's quote.
 */
async function fetchSharedPostFromChain(entryId, expectedBodyHash, authorWallet) {
  const want = normalizeBodyHashHex(expectedBodyHash);
  if (!want) return null;
  return fetchPublicPostFromChain(entryId, authorWallet, (item) => normalizeBodyHashHex(item.bodyHash) === want);
}

/**
 * A PERMALINK's post. The author's wallet is in the link itself and the coordinates address one row of THAT
 * author's own shard, so whatever they published there IS the post — there is no second candidate to confuse it
 * with, and no body hash is needed (nor would it fit a readable URL). A forged link can only point at a post its
 * author really published, under that author's own name.
 */
async function fetchPermalinkPostFromChain(entryId, authorWallet) {
  const want = String(entryId ?? '');
  return fetchPublicPostFromChain(entryId, authorWallet, (item) => String(item.entryId ?? '') === want);
}

/**
 * The original of a shared post: cache first, chain once.
 *
 * ONE ATTEMPT PER POST PER SESSION, including a failed one — this runs from a RENDER, and a post that cannot be
 * resolved (older than the shard's reachable history, retired, or a fabricated reference) must not re-read on every
 * scroll. The bound is the promise itself, kept in the map. Eviction is the only retry, and that is deliberate.
 */
function resolveSharedPostOriginal(entryId, expectedBodyHash, authorWallet) {
  const cached = findCachedPublicPostByEntryId(entryId);
  const want = normalizeBodyHashHex(expectedBodyHash);
  if (cached && want && want === normalizeBodyHashHex(cached.bodyHash)) return Promise.resolve(cached);
  const key = String(entryId ?? '');
  if (!key) return Promise.resolve(null);
  const inFlight = sharedPostChainReads.get(key);
  if (inFlight) return inFlight;
  const job = fetchSharedPostFromChain(key, expectedBodyHash, authorWallet)
    .catch((error) => {
      if (!noteTonRpcRateLimit(error)) console.warn('[public] shared post read failed', key, error);
      return null;
    });
  sharedPostChainReads.set(key, job);
  while (sharedPostChainReads.size > SHARED_POST_CHAIN_READ_LIMIT) {
    const oldest = sharedPostChainReads.keys().next();
    if (oldest.done) break;
    sharedPostChainReads.delete(oldest.value);
  }
  return job;
}

// ═══════════════════════════════════════════════════════════════════════════════════════════════════════════
// PERMALINKS — https://platho.app/<username|wallet>/<epochTag.shardSeq.entryId>
//
// The way a public post leaves Platho: a plain https URL that pastes into any chat, forum or tweet. nginx answers
// EVERY path with the app shell (`location / { try_files $uri /index.html; }`), so no route table is needed on
// the server side and no new infrastructure exists to run.
//
// NO ACCOUNT NEEDED TO OPEN ONE. The post is read straight from the author's PublicShard over a keyless RPC read,
// so a stranger who has never touched Platho gets the post, not a sign-up wall. That is the whole point of a link.
//
// A PATH, NOT A #fragment (owner's choice, 2026-08-13): readable. The cost is that a path IS sent to the server
// while a fragment never is. platho.app is served by Caddy, which logs no requests at all unless a `log`
// directive is present, and there is none — VERIFIED on the live journal, not assumed. ADDING `log` TO THE SITE
// TURNS THIS INTO A RECORD OF WHO READ WHAT, and the fragment form would have to be reconsidered.
//
// THE NAME IN THE LINK is the author's .ath when it is registry-VERIFIED, else their wallet address. The two are
// not equivalent over time: a .ath can be TRANSFERRED, and identity in Platho follows the WALLET, so an old link
// carrying a since-transferred name resolves to the NEW owner's shard and stops finding the post. The address
// form cannot rot. Verified name first anyway — a readable link is what was asked for.
// ═══════════════════════════════════════════════════════════════════════════════════════════════════════════

// nginx hard-404s these prefixes (`location ~ ^/(assets|vendor)/ { try_files $uri =404; }`) so that a MISSING
// asset fails as an asset instead of answering with the app shell. A username colliding with one could not be
// linked at the root, so the builder falls back to the wallet address for them — which always resolves.
// `privacy` and `terms` are in here for a DIFFERENT reason than assets/vendor, and it matters: the legal pages
// live at /privacy.html and /terms.html, so the extensionless forms fall through to the app shell today and would
// be read as channel names the moment a bare /<name> means a channel. Both fit the username rules ([a-z0-9_-]{4,16}),
// so somebody could register them. Reserving them keeps the door open for serving those pages extensionless later
// without a link that used to open a channel silently changing meaning.
const PERMALINK_RESERVED_SEGMENTS = new Set(['assets', 'vendor', 'privacy', 'terms']);
// Second segment is the feed entryId (epochTag.shardSeq.entryId) — all digits, so it can never be mistaken for a
// username (which is [a-z0-9_-]{4,16}, no dots) and the two segments cannot swap places.
// `~` joins the name to the author fingerprint (see permalinkWalletFingerprint). It cannot be confused with either
// half: a username is [a-z0-9_-] and a wallet address is base64url, so neither can contain one.
const PUBLIC_POST_PERMALINK_RE = /^\/([A-Za-z0-9_.:~-]{4,90})\/(\d+\.\d+\.\d+)\/?$/;

/**
 * A NAME CAN CHANGE HANDS; A POST CANNOT [OWNER 2026-08-24: "if someone shares a link with a username and then
 * passes the username to another person, the link can be substituted for a post by the NEW owner"].
 *
 * A post link resolves its name to a wallet AT OPEN TIME, so after a transfer the same URL points at whoever holds
 * the name now. Two outcomes, and the second is the dangerous one: either that account has no entry with this id
 * and the link simply breaks, or it HAS one — an entry id is unique within a channel, not across the chain, and
 * early ids are small numbers that collide readily — and a different person's post opens with nothing to show that
 * anything was swapped.
 *
 * So a post link carries a fingerprint of the author's wallet and the open refuses on a mismatch. Eight base36
 * characters of a sha256, i.e. 40 bits: an accidental collision is out of the question, and forging one means
 * grinding a vanity wallet AFTER already acquiring the name, to hijack links to posts one does not own.
 *
 * SYNCHRONOUS on purpose — the link is built inside a render, and an async digest there would mean either a
 * pending link or plumbing a promise through the feed. The vendored sha256 is synchronous.
 *
 * A CHANNEL link deliberately has NO fingerprint [OWNER: "a channel link should lead to the channel of whoever
 * owns the username, that's normal"]. A channel link names an IDENTITY, and the identity is the name; a post link
 * names a piece of CONTENT, and content belongs to whoever wrote it.
 */
const PERMALINK_FINGERPRINT_CHARS = 8;

function permalinkWalletFingerprint(authorWallet) {
  const raw = rawWalletAddress(authorWallet);
  if (!raw) return null;
  const digest = nobleSha256(new TextEncoder().encode(raw));
  let value = 0n;
  for (let i = 0; i < 5; i += 1) value = (value << 8n) | BigInt(digest[i]);   // 40 bits
  return value.toString(36).padStart(PERMALINK_FINGERPRINT_CHARS, '0');
}

/** The author segment for a CHANNEL link: the registry-verified .ath if there is one, else the wallet address. */
function publicPostPermalinkAuthorSegment(authorWallet) {
  const wallet = rawWalletAddress(authorWallet);
  if (!wallet) return null;
  // Same own-wallet blind spot as publicAuthorLabel (the verified-claim cache is only ever filled by RECEIVING
  // posts): a link to your own post shared from your own device carried the address segment while everyone else's
  // device produced the named one. The linked name was chain-verified when it was linked.
  const ownAddress = plathoWallet?.address ?? storedPlathoWalletRecord()?.address ?? null;
  const ownLabel = ownAddress && sameWalletAddress(wallet, ownAddress) ? readLinkedPlathoUsername(ownAddress)?.label : null;
  const verified = ownLabel ?? publicChannelProfileCache[channelProfileCacheKey(wallet)]?.verifiedUsername;
  const name = verified ? canonicalUsernameDisplay(verified).toLowerCase() : '';
  if (name && /^[a-z0-9_-]{4,16}$/.test(name) && !PERMALINK_RESERVED_SEGMENTS.has(name)) return name;
  return displayWalletAddress(wallet) || null;
}

/** The absolute link to a public post, or null when the post has no chain coordinates yet (local-pending). */
function publicPostPermalink(item) {
  if (!item || item.entryId === undefined || item.entryId === null) return null;
  if (!sharedPostShardCoordinates(item.entryId)) return null;   // a pre-shard v1 id has no addressable row
  const segment = publicPostPermalinkAuthorSegment(item.authorWallet);
  if (!segment) return null;
  // The fingerprint rides ONLY on a name. A wallet-address segment already IS the author, so there is nothing for
  // a transfer to change and nothing to check.
  const named = segment !== displayWalletAddress(rawWalletAddress(item.authorWallet));
  const fingerprint = named ? permalinkWalletFingerprint(item.authorWallet) : null;
  const author = fingerprint ? `${segment}~${fingerprint}` : segment;
  return `${location.origin}/${author}/${item.entryId}`;
}

/**
 * {author, fingerprint, entryId} for a permalink path, or null. Pure — resolution of `author` happens on chain.
 *
 * A link made before fingerprints existed has no `~` and parses with fingerprint null. Those keep opening exactly
 * as they did: they are already out in the world, and breaking them would be a second defect on top of the first.
 * Only what a fingerprint CAN answer is answered.
 */
function parsePublicPostPermalink(pathname) {
  const match = PUBLIC_POST_PERMALINK_RE.exec(String(pathname ?? ''));
  if (!match) return null;
  const segment = decodeURIComponent(match[1]);
  const cut = segment.indexOf('~');
  return {
    author: cut < 0 ? segment : segment.slice(0, cut),
    fingerprint: cut < 0 ? null : segment.slice(cut + 1),
    entryId: match[2],
  };
}

// A CHANNEL link is the same idea one segment shorter: https://platho.app/<username|wallet>. Sharing a channel is
// what someone does to introduce it; sharing a post is what they do to quote it. Both had to exist.
//
// DELIBERATELY NARROWER THAN THE POST FORM. A post link is unambiguous because its second segment is digits and
// dots, so the first can be permissive. A single segment has nothing to lean on, and everything the server does
// not have a file for arrives here — so this accepts ONLY the two shapes that can actually name a channel: a
// username exactly as the registry spells it, or a wallet address. Anything with a dot in it (/app.js,
// /favicon.ico, a typo'd asset) fails the username test, is not an address, and is left alone rather than opened
// as somebody's channel.
const PUBLIC_CHANNEL_PERMALINK_USERNAME_RE = /^[a-z0-9_-]{4,16}$/;

/** The absolute link to a channel, or null when the author has no linkable segment. */
function publicChannelPermalink(authorWallet) {
  const segment = publicPostPermalinkAuthorSegment(authorWallet);
  return segment ? `${location.origin}/${segment}` : null;
}

/** {author} for a channel-link path, or null. Pure — resolution of `author` happens on chain. */
function parsePublicChannelPermalink(pathname) {
  const raw = String(pathname ?? '').replace(/\/+$/, '');
  if (!raw.startsWith('/') || raw.length < 2) return null;
  const segment = decodeURIComponent(raw.slice(1));
  if (segment.includes('/')) return null;
  if (PERMALINK_RESERVED_SEGMENTS.has(segment.toLowerCase())) return null;
  if (PUBLIC_CHANNEL_PERMALINK_USERNAME_RE.test(segment)) return { author: segment };
  return rawWalletAddress(segment) ? { author: segment } : null;
}

/**
 * Open the channel a link names. Runs at boot off the address bar, like the post form, and for the same reason
 * works with NO ACCOUNT: the channel is read from its author's PublicShard over a keyless RPC read, so a stranger
 * gets the channel rather than a sign-up wall.
 *
 * The URL is left in place on success so it can be copied back out of the address bar; cleared on failure so a
 * reload lands in the normal app.
 */
async function openPublicChannelFromPermalink(link) {
  if (!link) return false;
  setView('public');
  setPublicStatus(t('public.openingLink'));
  try {
    const wallet = await resolvePermalinkAuthorWallet(link.author);
    if (!wallet) throw new Error('channel link author does not resolve to a wallet');
    openPublicChannelView({ authorWallet: wallet });
    setPublicStatus('feed');
    return true;
  } catch (error) {
    if (!noteTonRpcRateLimit(error)) console.warn('[public] channel link open failed', link, error);
    setPublicStatus(error instanceof UsernameNotRegisteredError ? t('public.linkNoSuchName') : t('public.linkNotFound'));
    clearPublicPostPermalinkFromAddressBar();
    return false;
  }
}

/**
 * Share a link OUT of Platho: the system sheet where there is one, the clipboard otherwise.
 *
 * RETURNS THE OUTCOME because the caller has to be the one that confirms it. A share sheet IS its own
 * confirmation; a silent clipboard write is not, and there is no global toast in this app (see the identity
 * popover's copy button, which relabels itself for the same reason). setPublicStatus is a console.debug wrapper,
 * NOT a UI surface — leaning on it is exactly how the channel Share button shipped looking dead: it copied the
 * link correctly and said so only to a filtered-out debug log.
 */
async function shareLinkOutOfPlatho(url, title = '') {
  if (!url) return 'failed';
  const heading = String(title ?? '').trim();
  if (canSystemShareLink(url)) {
    try {
      await navigator.share(heading ? { title: heading, url } : { url });
      return 'shared';
    } catch (error) {
      // A dismissed sheet is the user changing their mind, not a failure — report nothing and stop.
      if (error?.name === 'AbortError') return 'dismissed';
      console.warn('[share] system share sheet failed, falling back to the clipboard', error);
    }
  }
  try {
    await copyTextToClipboard(url);
    setPublicStatus(t('dialog.shareLinkCopied'));
    return 'copied';
  } catch (error) {
    console.error(error);
    setPublicStatus(t('dialog.shareCopyFailed'));
    return 'failed';
  }
}

/**
 * The author segment -> a wallet address. An address (raw or user-friendly) is taken as itself; anything else is
 * a .ath name and is resolved through the registry, which is the only authority on who owns a name TODAY.
 */
/**
 * The wallet a post link names — and, when the link carries a fingerprint, a REFUSAL rather than a substitution.
 *
 * A name resolves to whoever holds it now. If the link was made while somebody else held it, the fingerprint will
 * not match, and the honest answer is to say the name changed hands. Opening the current holder's post instead
 * would be the silent swap this exists to prevent (see permalinkWalletFingerprint).
 */
class PermalinkOwnerChangedError extends Error {}

async function resolvePermalinkAuthorWallet(author, fingerprint = null) {
  const direct = rawWalletAddress(author);
  if (direct) return direct;   // an address IS the author; a fingerprint would add nothing to check
  const owner = await resolvePlathoUsernameOwner(author);
  const wallet = rawWalletAddress(owner?.ownerWallet) ?? null;
  if (!wallet || !fingerprint) return wallet;
  if (permalinkWalletFingerprint(wallet) !== fingerprint) throw new PermalinkOwnerChangedError('permalink author changed');
  return wallet;
}

/**
 * Open the post a permalink names. Runs once at boot, off the address bar.
 *
 * The URL is LEFT IN PLACE on success: it is the post's permalink, and a reader who wants to pass it on must be
 * able to copy it back out of the address bar. On failure it is cleared, so a reload lands in the normal app
 * instead of retrying a link that cannot resolve.
 */
/** Which of the three honest answers a failed post link deserves. */
function permalinkFailureMessage(error) {
  if (error instanceof PermalinkOwnerChangedError) return t('public.linkOwnerChanged');
  if (error instanceof UsernameNotRegisteredError) return t('public.linkNoSuchName');
  return t('public.linkNotFound');
}

async function openPublicPostFromPermalink(link) {
  if (!link) return false;
  setView('public');
  setPublicStatus(t('public.openingLink'));
  try {
    const wallet = await resolvePermalinkAuthorWallet(link.author, link.fingerprint);
    if (!wallet) throw new Error('permalink author does not resolve to a wallet');
    const post = await fetchPermalinkPostFromChain(link.entryId, wallet);
    if (!post) throw new Error('permalink post not found on chain');
    renderPublicSurface({ anchorUnread: false });   // the fetch cached the post; put it in the feed first
    openPublicPostDetail(post);
    setPublicStatus('feed');
    return true;
  } catch (error) {
    if (!noteTonRpcRateLimit(error)) console.warn('[public] permalink open failed', link, error);
    setPublicStatus(permalinkFailureMessage(error));
    clearPublicPostPermalinkFromAddressBar();
    return false;
  }
}

/** Drop the permalink path so a reload starts clean. Never touches the URL when there is nothing to drop. */
function clearPublicPostPermalinkFromAddressBar() {
  try {
    // BOTH link shapes: this is the failure path for the channel form too, and a channel link left in the bar
    // would be retried on every reload.
    if (parsePublicPostPermalink(location.pathname) || parsePublicChannelPermalink(location.pathname)) {
      history.replaceState(null, '', '/');
    }
  } catch (error) {
    console.warn('[public] could not clear the permalink path', error);
  }
}

/** A public post's whole text, the way the share payload builder reads it — one definition, two callers. */
function publicPostFullText(post) {
  const blocks = Array.isArray(post?.blocks) ? post.blocks : [];
  return (blocks
    .filter((block) => block?.type === 'text' && String(block.text ?? '').trim())
    .map((block) => String(block.text).trim())
    .join('\n\n') || String(post?.text ?? '')).trim();
}

/**
 * A resolved post's image, warmed if the cache is holding only its text.
 *
 * The localStorage feed cache STRIPS image data-urls on persist (omitHeavyFeedMediaForPersist — the iOS freeze), so
 * a post that came back from a reload has its picture in the durable per-post media store instead. This is the same
 * warm the feed does at load time, for one post on demand.
 */
async function sharedPostImageUrlWarm(post) {
  try {
    if (!post) return null;
    const direct = sharedPostImageUrlFromPost(post);
    if (direct) return direct;
    const key = publicPostCacheKey(post);
    if (!key) return null;
    const store = await publicPostMediaStore();
    const raw = await store?.get(key);
    if (!raw) return null;
    let media = null;
    try { media = JSON.parse(raw); } catch { return null; }
    applyPublicPostMediaRecord(post, media);
    return sharedPostImageUrlFromPost(post);
  } catch {
    return null;
  }
}

// The shared-post embed card (v766): source-channel header (recipient-resolved identity; the sender's snapshot
// label only as fallback) + title/text snapshot, clamped with its own smaller max height and the same expand
// machinery as long posts. Snippet renders as PLAIN TEXT (textContent, no linkify): the snapshot is
// sender-authored/unverified — the tappable header leads to the REAL channel (chain truth) instead. v797: when the
// referenced post's image is cached locally, the media hint is swapped for the real image (resolved by entryId, no
// wire copy).
function buildSharedPostEmbed(block, embedDepth = 0) {
  const embed = document.createElement('div');
  embed.className = 'shared-post-embed';
  const wallet = rawWalletAddress(block.authorWallet);
  const label = (wallet ? resolveWalletChannelDisplay(wallet)?.name : null)
    || (wallet ? publicAuthorLabel(wallet) : null)
    || String(block.author ?? '').trim()
    || (wallet ? shortAddress(wallet) : t('public.channel'));
  const header = document.createElement('button');
  header.type = 'button';
  header.className = 'shared-post-embed-header';
  header.title = t('public.openSharedChannel');
  const avatar = document.createElement('div');
  avatar.className = 'avatar shared-post-embed-avatar';
  avatar.setAttribute('aria-hidden', 'true');
  setAvatarNode(avatar, String(label).slice(0, 1), wallet ? publicAvatarUrlForWallet(wallet) : null);
  const headText = document.createElement('span');
  headText.className = 'shared-post-embed-channel';
  const kind = document.createElement('span');
  kind.className = 'shared-post-embed-kind';
  kind.textContent = t('public.sharedPost');
  const name = document.createElement('span');
  name.className = 'shared-post-embed-name';
  name.textContent = label;
  headText.append(kind, name);
  header.append(avatar, headText);
  header.addEventListener('click', (event) => {
    event.stopPropagation();
    if (!wallet) return;
    // Works from the PRIVATE surface too: the channel view lives on the Public pane.
    setView('public');
    openPublicChannelView({ authorWallet: wallet });
    // AND THEN THE POST ITSELF. "The embed's channel link leads to the original" was only ever true down to the
    // CHANNEL: the reader landed in a feed and had to hunt. In a channel serialising a book that is a dead end.
    // The post detail stacks on top of the channel view, so a failed resolve simply leaves the channel open.
    resolveSharedPostOriginal(block.entryId, block.bodyHash, wallet).then((post) => {
      if (post) openPublicPostDetail(post);
    }).catch(() => {});
  });
  embed.append(header);
  const body = document.createElement('div');
  body.className = 'feed-post-body';
  const inner = document.createElement('div');
  inner.className = 'feed-post-body-inner';
  if (block.title) {
    const title = document.createElement('div');
    title.className = 'shared-post-embed-title';
    title.textContent = block.title;
    inner.append(title);
  }
  // The SENDER'S SNAPSHOT paints first, always. It is a 4KB excerpt that already travelled inside the message, so
  // the card is complete the instant it is built — the chain read below is a round trip, and without this every
  // repost would be an empty frame while it runs, and would stay one whenever it cannot run at all.
  // The snapshot lives in its own wrapper so the resolved original can replace the WHOLE body at once. It used to be
  // patched piecewise — text swapped in place, picture swapped into a hint appended after it — which pinned the image
  // to the BOTTOM of the card however the author had laid the post out. OBSERVED 2026-08-07 by the owner: the picture
  // sat under the text instead of where they had placed it.
  const snapshot = document.createElement('div');
  if (block.snippet) {
    // A DIV, NOT A <p>, and the FULL renderer — the same pair the feed itself uses one function above, for the same
    // reason: block children (heading/list/quote) are invalid inside a paragraph, so a <p> forces inlineOnly and
    // inlineOnly leaves "#" and "##" standing in the text as literal characters. OBSERVED 2026-08-07 by the owner:
    // headings did not render in a forwarded post while bold did.
    //
    // The old justification — "a truncated excerpt should not show a half-cut heading" — expired when the card
    // learned to read the original: a repost whose text is short carries it whole, and a long one is replaced by the
    // chain copy below. A cut heading renders as a heading with cut text, which is what the feed does anyway.
    //
    // Links stay safe for the UNVERIFIED sender snapshot: appendInlineFormatted routes every link through
    // buildExternalLinkAnchor (no live href, activateExternalLink interstitial) and only ever appends real nodes —
    // no raw-markup assignment anywhere in this card, which the XSS gate greps for by name.
    const text = document.createElement('div');
    text.className = 'feed-block-text shared-post-embed-text';
    appendFormattedMessageText(text, block.snippet);
    if (block.textTruncated) text.append(document.createTextNode('…'));
    snapshot.append(text);
  }
  if (block.hasImage) {
    const mediaHint = document.createElement('span');
    mediaHint.className = 'shared-post-embed-media-hint';
    mediaHint.textContent = t('public.sharedPostImageHint');
    snapshot.append(mediaHint);
  }
  inner.append(snapshot);
  // THEN THE ORIGINAL REPLACES IT — the whole text and the real picture, from the reader's cache if it is there and
  // otherwise from the chain, ONCE (resolveSharedPostOriginal caches into the feed and persists the media).
  //
  // The substitution only ever runs one way, and that is the point: the snippet is what the SENDER typed into the
  // reference and proves nothing, while a post read back through the lane matched its body_commit and its
  // publisher tag. Chain truth displaces the claim; the claim never displaces chain truth.
  //
  // AND IT REPLACES THE BODY WHOLE, through the SAME renderer the feed and the post detail use — so the post appears
  // in the order its author wrote it: text, picture where they put it, more text. Rebuilding it out of a snippet plus
  // a trailing image could only ever produce one layout, and it was the wrong one.
  if (embedDepth === 0 && block.entryId && (block.hasImage || block.textTruncated)) {
    resolveSharedPostOriginal(block.entryId, block.bodyHash, wallet).then(async (post) => {
      if (!post || !snapshot.isConnected) return;
      // Warm FIRST: the persisted feed cache holds the post's text without its image (the data-urls are stripped on
      // write), and this puts the picture back onto the post object the renderer is about to read.
      await sharedPostImageUrlWarm(post);
      if (!snapshot.isConnected) return;
      const real = document.createElement('div');
      appendPublicItemContent(real, post, embedDepth + 1);
      if (real.childNodes.length === 0) return;   // nothing renderable — keep the snapshot rather than blank the card
      snapshot.replaceWith(real);
    }).catch(() => {});
  }
  body.append(inner);
  embed.append(body);
  if (feedPostClampObserver) {
    wireClampToggleButton(embed, body, inner, expandedSharedEmbeds, String(block.entryId));
  }
  return embed;
}

/**
 * The author label for a feed item — ONE precedence, shared with the channel header and the post detail:
 * an explicit "Display as" choice, then the chain-VERIFIED .ath, then whatever the item carries, then the
 * channel name from its meta line.
 *
 * It resolves from the WALLET, not from a copied name field, because the copy does not survive: the chain walk
 * writes `author` onto the post, and neither publicChannelFeedToThread nor publicChannelThreadsToFeedItems maps
 * it onward — the same two functions that dropped the channel coordinates (see publicPostChainCoordinates).
 */
function publicFeedItemAuthorLabel(item) {
  const wallet = item?.authorWallet ?? null;
  return (wallet ? resolveWalletChannelDisplay(wallet)?.name : null)
    || (wallet ? publicAuthorLabel(wallet) : null)
    || item?.author
    || (item?.meta ?? []).flat().filter(Boolean)[0]
    || t('public.postTitleFallback');
}

// Build one feed <article> (chrome + content) for an item. Extracted so renderPublicFeed can REUSE an article whose
// publicFeedItemRenderSignature is unchanged instead of rebuilding it every render.
function buildPublicFeedArticle(item, avatarUrlMemo) {
  const unread = isUnreadPublicItem(item);
  const article = document.createElement('article');
  article.className = `feed-item${item.compact ? ' compact' : ''}${unread ? ' is-unread' : ''}`;
  if (unread) article.dataset.unread = 'true';
  if (item.entryId !== undefined && item.entryId !== null) article.dataset.entryId = String(item.entryId);
  if (item.channelId) article.dataset.channelId = item.channelId;
  const authorRow = document.createElement('div');
  authorRow.className = 'feed-author-row';
  const authorAvatar = document.createElement('div');
  authorAvatar.className = 'avatar feed-avatar';
  authorAvatar.setAttribute('aria-hidden', 'true');
  // The letter comes from the AUTHOR, resolved from the wallet exactly as the channel header resolves it. It used
  // to read item.author — a field publicChannelThreadsToFeedItems never carries — then item.title, which a post
  // without a title does not have either, so it landed on the literal 'P'. MEASURED 2026-08-13: the owner opened a
  // channel found through search and saw "M moonly" in the header and "P MOONLY" one row below, same channel.
  setAvatarNode(authorAvatar, String(publicFeedItemAuthorLabel(item)).slice(0, 1), item.avatarImageUrl ?? publicAvatarUrlForWallet(item.authorWallet, avatarUrlMemo));
  const meta = document.createElement('div');
  meta.className = 'feed-meta';
  for (const label of [...(item.meta ?? []), unread ? t('public.unread') : null].filter(Boolean)) {
    const span = document.createElement('span');
    span.textContent = displayMetaLabel(label);
    meta.append(span);
  }
  authorRow.append(authorAvatar, meta);
  // Tapping the author NAME/meta block opens the channel screen — this channel's posts only. The AVATAR is NOT
  // wired here: it keeps its v651 tap-to-view meaning (the delegated document click opens an image-bearing avatar
  // in the fullscreen lightbox) — owner: avatar tap = see the avatar, name tap = open the channel.
  // Plain click affordance, NO role/aria-label: an aria-label would wipe the author/date/unread text from the
  // accessibility tree, and the meta block can host interactive children (the publish-status retry chip) — a
  // nested-button-in-button violation. The keyboard path to the channel is the about "i" button's "Open channel"
  // action (a real button). The about "i" + "Display as" chevron stopPropagation, staying independent targets.
  if (item.channelId) {
    const openChannel = (event) => {
      // A click landing on an interactive child (the publish-status/retry chip) is not a channel-open intent.
      if (event.target instanceof Element && event.target !== event.currentTarget
        && event.target.closest('button, .public-publish-status')) return;
      event.stopPropagation();
      openPublicChannelView({ channelId: item.channelId, authorWallet: item.authorWallet });
    };
    meta.classList.add('feed-author-link');
    meta.addEventListener('click', openChannel);
  }
  // Own pending publishes carry a status badge ('public publish submitted…' / 'public publish failed') —
  // CSS classes only (prod CSP style-src 'self' silently kills inline styles).
  if (isPendingPublicFeedItem(item) && item.publishStatus) {
    const statusBadge = document.createElement('span');
    statusBadge.className = `public-publish-status${String(item.publishStatus).endsWith('failed') ? ' public-publish-status--failed' : ''}`;
    // Private-style live status ('sending 2 parts' / 'submitted 1/2, confirming' / …) when a publishState is
    // streaming; the machine-readable publishStatus marker is the fallback.
    statusBadge.textContent = (item.publishState ? publishStateMeta(item.publishState) : null) || item.publishStatus;
    // Patch anchor for the status-only fast path (a publish tick updates this text in place, no rebuild).
    if (item.id) statusBadge.dataset.publishLocalId = String(item.id);
    meta.append(statusBadge);
  }
  // The channel "about" (description + tags) button and the "Display as" chevron live top-right in the author
  // row. Both carry margin-left:auto: the first absorbs the free space (pushing the group right), the second
  // then sits flush beside it — so they render as an adjacent [about][chevron] cluster on the right edge.
  const feedDescriptionButton = publicItemDescriptionButton(item);
  if (feedDescriptionButton) authorRow.append(feedDescriptionButton);
  const feedIdentityButton = publicItemIdentityButton(item);
  if (feedIdentityButton) authorRow.append(feedIdentityButton);
  article.append(authorRow);
  // Long-post collapse: title + content live in a clamped body wrapper (feed + channel view only — the post
  // detail screen and comments call appendPublicItemContent directly and never clamp). The inner wrapper is the
  // observer target; the outer .feed-post-body is what the CSS max-height clamps.
  const body = document.createElement('div');
  body.className = 'feed-post-body';
  const bodyContent = document.createElement('div');
  bodyContent.className = 'feed-post-body-inner';
  if (item.title) {
    const title = document.createElement('h2');
    title.textContent = item.title;
    bodyContent.append(title);
  }
  appendPublicItemContent(bodyContent, item);
  body.append(bodyContent);
  article.append(body);
  // Compact cards (channel plates / empty states) carry a line or two — no clamp machinery for them.
  if (feedPostClampObserver && !item.compact) {
    wireClampToggleButton(article, body, bodyContent, publicFeedExpandedPosts, String(item.id));
  }
  // Comments are no longer rendered inline in the feed — they load on demand on the post detail screen
  // (openPublicPostDetail). appendPublicItemComments is reused there.
  appendPublicItemActions(article, item);
  return article;
}

// A compact string of every MUTABLE input to buildPublicFeedArticle, so a reused article rebuilds when (and only
// when) its appearance would change. Post CONTENT (text/image) is immutable for a chain post, so it is not part of
// the signature. Conservative by design: including more here only costs the occasional needless rebuild (cheap under
// the render cap); a MISSING input would instead leave a stale article. `item.author` carries the resolved
// display-name so an identity / "display as" change reflows; rare channel-profile-only changes self-heal on the next
// signature-changing event.
function publicFeedItemRenderSignature(item, avatarUrlMemo) {
  return [
    // Cards bake t() output into their DOM (action buttons, statuses), so the locale is part of what the
    // rendered node looks like: without this term a re-render after a language switch REUSED every card in
    // the old language (the quick-start switch translates in place — only the profile switch reloads).
    currentLocale(),
    // Timestamp display mode changes what the meta line looks like the same way the locale does.
    feedTimestampMode(),
    isUnreadPublicItem(item) ? 'u' : '',
    item.compact ? 'c' : '',
    // Expanded long posts rebuild expanded on EVERY surface: the click mutates only the tapped article's DOM,
    // so the OTHER surface's reused article (feed vs channel view render the same item independently) would
    // otherwise stay collapsed until an unrelated rebuild.
    publicFeedExpandedPosts.has(String(item.id)) ? 'x' : '',
    (item.meta ?? []).join(''),
    item.author ?? '',
    item.title ?? '',
    item.publishStatus ?? '',
    item.publishState ? publishStateMeta(item.publishState) : '',
    (item.avatarImageUrl ?? publicAvatarUrlForWallet(item.authorWallet, avatarUrlMemo)) ?? '',
    item.commentsAllowed === false ? 'nc' : '',
    isPublicChannelSubscribed(item.channelId) ? 's' : '',
    // Renderable-image presence IS mutable across the persist-strip round-trip: the localStorage feed cache strips
    // image data urls (omitHeavyFeedMediaForPersist), so a reloaded post loses its image, then the post-reload sync
    // re-hydrates it from the durable body cache. Without this term the reused article stayed image-less (the sync
    // repaired the DATA but the signature/DOM never changed -> "the image showed once then vanished"). Count blocks
    // that actually render an image + the legacy image-only imageUrl; stripped (0) vs re-hydrated (1) differ.
    `img${(item.blocks ?? []).filter((block) => block?.type === 'image' && block.url).length}${item.imageUrl ? 'i' : ''}`,
  ].join('');
}

// The "show older" affordance at the BOTTOM of the newest-first feed: reveals another PUBLIC_FEED_RENDER_PAGE of
// older posts. One button, rebuilt each render (cheap), with a fresh listener.
function buildShowOlderButton(hiddenOlderCount) {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'feed-show-older';
  button.textContent = t('public.showOlder');
  button.dataset.hiddenOlder = String(hiddenOlderCount);
  button.addEventListener('click', () => {
    publicFeedShownCap += PUBLIC_FEED_RENDER_PAGE;
    renderPublicSurface({ anchorUnread: false });
  });
  return button;
}

// Show the "edit channel description" header button only when the user has an activatable own channel — i.e. a
// connected wallet with an active Platho account (publishing a profile needs both). Toggled on every public render.
function refreshEditChannelProfileButton() {
  if (!editChannelProfileButton) return;
  editChannelProfileButton.hidden = !(ownPublicChannel() && hasActivePlathoAccount());
}

function renderPublicSurface(options = {}) {
  updatePublicModeButtons();
  refreshEditChannelProfileButton();
  if (publicChannelSearchRow) publicChannelSearchRow.hidden = false;
  const allItems = publicFeedItemsChronological();
  // A transient preview channel (open in the channel view, not followed) is excluded from the MAIN feed and its
  // unread/status counts — its posts show only inside the channel view until the user follows.
  const surfaceItems = publicChannelPreviewChannelId
    ? allItems.filter((item) => item.channelId !== publicChannelPreviewChannelId)
    : allItems;
  const items = surfaceItems.filter((item) => publicFeedItemMatchesSearch(item, publicChannelSearchQuery));
  renderPublicFeed(items, options);
  // Keep the open post detail (per-post comments) in sync with the cache too — a just-published local-pending
  // comment lands in the cache and must show on the detail screen, which is rendered separately from the feed.
  if (publicPostDetailOpen) renderPublicPostDetail();
  // Same for the open channel view — a background sync (or a preview fetch) re-renders its post list.
  if (publicChannelViewOpen) renderPublicChannelView();
  const unread = surfaceItems.filter(isUnreadPublicItem).length;
  setPublicStatus(publicChannelSearchQuery ? `${items.length} found` : (unread > 0 ? `${unread} unread` : 'feed'));
}

function setPublicCommentTarget(item = null, { focus = true, showContext = true } = {}) {
  publicCommentTarget = item;
  const active = Boolean(item);
  // A comment target change (or clear) always drops any pending reply-to-comment quote — it referenced a comment
  // of the PREVIOUS target post.
  publicCommentReplyTo = null;
  if (publicComposer) publicComposer.dataset.mode = active ? 'comment' : 'post';
  // The post detail screen drives comment mode implicitly (the whole screen IS the post), so it suppresses the
  // inline "Comment to X / Cancel" context bar — there a Cancel would silently drop the composer back to post mode
  // while still on the post screen, so a "comment" would publish as a new public post. (Reply mode re-shows the
  // bar on the detail screen — see refreshPublicCommentReplyUi — with a Cancel that clears ONLY the reply.)
  publicCommentContextSuppressed = !active || !showContext;
  if (publicCommentContext) publicCommentContext.hidden = publicCommentContextSuppressed;
  if (publicPostCommentsToggle) publicPostCommentsToggle.hidden = active;
  if (active) {
    setText(publicCommentContextText, t('public.commentTo', { target: item.title ?? item.id ?? t('public.postFallback') }));
    if (publicMessageInput) {
      publicMessageInput.placeholder = publicComposerPlaceholder();
      if (focus) focusComposerField(publicMessageInput);
    }
  } else {
    if (publicMessageInput) {
      publicMessageInput.placeholder = publicComposerPlaceholder();
    }
    if (publicComposerCommentsCheckbox) publicComposerCommentsCheckbox.checked = readPublicCommentsDefault() !== 'disabled';
  }
  updatePublicCommentsToggleUi();
  refreshComposerPublishPolicy();
  refreshComposerCostStatus();
}

// ---- Swipe-to-reply (v646): composer quote strips ---------------------------------------------------------------
// Both strips show "author: snippet" with a Cancel that clears ONLY the reply draft. The reply becomes a REPLY
// document block at send time (composerBlocksFromDraft / publicDocumentBlocksFromDraft read the drafts directly).

function replyStripContent(node, reply, cancelLabelNode) {
  if (!node) return;
  const author = document.createElement('span');
  author.className = 'composer-reply-author';
  author.textContent = reply.author || t('chat.reply');
  const snippet = document.createElement('span');
  snippet.textContent = reply.snippet || '';
  const wrap = document.createElement('span');
  wrap.className = 'composer-reply-text';
  wrap.append(author, snippet);
  node.replaceChildren(wrap);
  if (cancelLabelNode) node.append(cancelLabelNode);
}

function setPrivateReplyDraft(reply) {
  privateReplyDraft = reply ?? null;
  if (privateReplyContext) privateReplyContext.hidden = !privateReplyDraft;
  // The mobile composer grid re-rows around the quote strip via this class — a JS-set class, not :has():
  // :has() silently no-ops on the iOS floor (Safari 14), which left the strip stranded under the buttons.
  // Share (v766) uses the same row, so the class stays while EITHER strip is up.
  composer?.classList.toggle('is-replying', Boolean(privateReplyDraft || privateShareDraft));
  if (privateReplyDraft && privateReplyContextText) {
    replyStripContent(privateReplyContextText, privateReplyDraft);
  }
  if (privateReplyDraft) focusComposerField(messageInput);
  refreshComposerCostStatus();
}

// Strip content for the share chip (v766): "Sharing post" label + the source channel/title as the snippet.
function shareStripContent(node, share) {
  if (!node) return;
  const label = document.createElement('span');
  label.className = 'composer-reply-author';
  label.textContent = t('composer.sharingPost');
  const snippet = document.createElement('span');
  snippet.textContent = [share.author, share.title || share.snippet].filter(Boolean).join(' - ');
  const wrap = document.createElement('span');
  wrap.className = 'composer-reply-text';
  wrap.append(label, snippet);
  node.replaceChildren(wrap);
}

// Cancel path: the [post] marker leaves the text with the draft (mirrors removeImageMarkerForComposer).
function removeShareMarkerForComposer(textarea) {
  if (!textarea) return;
  COMPOSER_SHARE_MARKER_RE.lastIndex = 0;
  let value = String(textarea.value ?? '').replace(COMPOSER_SHARE_MARKER_RE, '');
  value = value.replace(/\n{3,}/g, '\n\n');
  if (!value.trim()) value = '';
  textarea.value = value;
}

function setPrivateShareDraft(share) {
  privateShareDraft = share ?? null;
  if (privateShareContext) privateShareContext.hidden = !privateShareDraft;
  composer?.classList.toggle('is-replying', Boolean(privateReplyDraft || privateShareDraft));
  if (privateShareDraft && privateShareContextText) {
    shareStripContent(privateShareContextText, privateShareDraft);
  }
  refreshComposerCostStatus();
  // A share-only draft (no typed text) IS sendable — the button must open the moment the draft attaches.
  refreshPrivateSendButtonState();
}

function setPublicShareDraft(share) {
  publicShareDraft = share ?? null;
  if (publicShareContext) publicShareContext.hidden = !publicShareDraft;
  if (publicShareDraft && publicShareContextText) {
    shareStripContent(publicShareContextText, publicShareDraft);
  }
  refreshComposerCostStatus();
  refreshPublicSendButtonState();
}

// Suppression state mirrors setPublicCommentTarget's showContext decision so reply mode can temporarily re-show
// the context bar on the post-detail screen and hide it back when the reply is cancelled/sent.
let publicCommentContextSuppressed = true;

function refreshPublicCommentReplyUi() {
  if (!publicCommentContext) return;
  if (publicCommentReplyTo) {
    replyStripContent(publicCommentContextText, publicCommentReplyTo);
    publicCommentContext.hidden = false;
  } else {
    if (publicCommentTarget) setText(publicCommentContextText, t('public.commentTo', { target: publicCommentTarget.title ?? publicCommentTarget.id ?? t('public.postFallback') }));
    publicCommentContext.hidden = publicCommentContextSuppressed;
  }
}

function setPublicCommentReplyTo(reply) {
  publicCommentReplyTo = reply ?? null;
  refreshPublicCommentReplyUi();
  if (publicCommentReplyTo) focusComposerField(publicMessageInput);
  refreshComposerCostStatus();
}

// Rendered quote strip inside a bubble/comment (the received REPLY block). Tapping it scrolls to the original
// row (matched by data-entry-id inside `scroller`) with a brief highlight; a missing original (evicted/unloaded)
// keeps the strip inert — the denormalized author+snippet already tell the story, Telegram-style.
function buildReplyQuoteNode(reply, scroller) {
  const quote = document.createElement('div');
  quote.className = 'message-reply-quote';
  const author = document.createElement('span');
  author.className = 'message-reply-quote-author';
  author.textContent = reply.author || t('chat.reply');
  const snippet = document.createElement('span');
  snippet.className = 'message-reply-quote-snippet';
  snippet.textContent = reply.snippet || '';
  quote.append(author, snippet);
  const refEntryId = reply.refEntryId === undefined || reply.refEntryId === null ? '' : String(reply.refEntryId);
  if (refEntryId && scroller) {
    quote.dataset.refEntryId = refEntryId;
    quote.addEventListener('click', (event) => {
      event.stopPropagation();
      const target = replyQuoteTargetRow(scroller, quote, refEntryId, reply.snippet);
      if (!target) return;
      target.scrollIntoView({ behavior: 'smooth', block: 'center' });
      target.classList.remove('reply-target-flash');
      requestAnimationFrame(() => target.classList.add('reply-target-flash'));
    });
  }
  return quote;
}

/**
 * WHICH row a reply quote scrolls to — the nearest match ABOVE the reply, not the first one in the document.
 *
 * OBSERVED 2026-08-04 (owner): tapping a reply quote scrolled the conversation somewhere else entirely. The lookup
 * was `scroller.querySelector('[data-entry-id="N"]')`, which returns the FIRST match in document order — and
 * data-entry-id is not unique. It is the RecordShard publish `seq`, numbered per shard and restarted every epoch
 * (gate 13653 only requires seq > last_seq within one shard), so a conversation spanning two days holds several
 * rows with entry id "3". The first in document order is the OLDEST one, which is why the jump landed far above
 * the real target rather than a little off.
 *
 * THE THIRD TIME THIS COLLISION HAS SURFACED TODAY — after long-press copy (which copied a different message's
 * text) and reply targeting. Those two were fixed by binding the row to its message object at render time; this
 * one cannot be, because the reference arrives ON THE WIRE as a bare id and must be resolved against the DOM.
 *
 * A reply always refers to something SENT BEFORE IT, so the reply's own position disambiguates: among the rows
 * carrying that id, take the last one above the reply. That is exact for every case a user can actually express —
 * the duplicates are a day or more apart, and the one being answered is the recent one. If nothing precedes the
 * quote (a restored history whose target is not loaded), fall back to the first match rather than doing nothing.
 */
function replyQuoteTargetRow(scroller, quote, refEntryId, snippet) {
  const matches = [...scroller.querySelectorAll(`[data-entry-id="${refEntryId}"]`)];
  if (matches.length <= 1) return matches[0] ?? null;
  // The reply's own row. `closest('[data-entry-id]')` alone is not enough: an optimistic reply has no entry id
  // yet, and without a position to compare against every candidate looked equally good.
  const ownRow = quote.closest('[data-entry-id]') ?? quote.closest('.message, .comment-item');
  const precedes = (row) => Boolean(ownRow && (ownRow.compareDocumentPosition(row) & Node.DOCUMENT_POSITION_PRECEDING));

  // THE SNIPPET IS THE REAL DISAMBIGUATOR, and position alone was not enough — that is what the first attempt got
  // wrong. Each DIRECTION of a conversation has its own shard and its own seq counter, so within one epoch the
  // user's own message #3 and the peer's message #3 both exist. "Nearest above" then lands on whichever came last,
  // which is a coin flip. The quote carries the target's text, denormalized, precisely so the reference survives
  // without a lookup — so use it: the row whose message text matches the quoted snippet IS the target.
  // BOTH SIDES STRIPPED. The snippet is built by replySnippetFromContent, which projects the formatting markers
  // away; the row's message still carries them. Comparing the two forms directly makes every quote of a formatted
  // message ('# Word' vs 'Word') fail to match, and the resolver silently falls back to position — the coin flip
  // this snippet check exists to replace.
  const wanted = messagePreviewText(snippet);
  const matchesSnippet = (row) => {
    if (!wanted) return false;
    const text = messagePreviewText(messageForRow(row)?.text);
    if (!text) return false;
    return text === wanted || text.startsWith(wanted) || wanted.startsWith(text);
  };

  let snippetAbove = null;
  let snippetAny = null;
  let above = null;
  for (const candidate of matches) {
    if (candidate === ownRow) continue;
    const hit = matchesSnippet(candidate);
    if (hit && precedes(candidate)) snippetAbove = candidate;
    if (hit && !snippetAny) snippetAny = candidate;
    if (precedes(candidate)) above = candidate;
  }
  // Best evidence first: the right text above the reply, then the right text anywhere, then merely the nearest
  // above, and finally the first match — a tap must always land somewhere rather than doing nothing.
  return snippetAbove ?? snippetAny ?? above ?? matches[0];
}

// Snippet for a quote strip + the wire block: first text, else a media word (denormalized, like Telegram).
//
// The text is stripped of its formatting markers for the same reason the previews are — a quote of a heading read
// '# Word' inside the strip. The media words are translated in the SENDER's language, which is a real trade and the
// right side of it: the pair that talks to each other shares a language, so localising serves the common case, and
// the alternative was English for every reader including both Russians in the only conversation that exists.
function replySnippetFromContent(item) {
  const blocks = Array.isArray(item?.blocks) ? item.blocks : [];
  const text = String(item?.text ?? '').trim() || String(blocks.find((block) => block?.type === 'text' && String(block.text ?? '').trim())?.text ?? '').trim();
  if (text) return messagePreviewText(text);
  if (blocks.some((block) => block?.type === 'image') || item?.imageUrl || item?.attachment?.type === 'image') return t('chat.previewImage');
  if (blocks.some((block) => block?.type === 'file')) return t('chat.previewFile');
  if (blocks.some((block) => block?.type === 'share')) return t('chat.previewSharedPost');
  return t('chat.previewMessage');
}

// ---- Public post detail screen (per-post comments, opened from the "Comments" action) -------------------------
// The feed no longer loads comments (scalability). Opening a post slides a detail screen over the feed (mirrors the
// private chatOpen pattern via publicPane.dataset.postOpen), shows the post at the top, loads ITS comments on demand
// from chain, and puts the shared composer into comment mode for that post.

// Cached comments for a post (read from the feed cache where rememberLocalPublicComment stores them, and where a
// prior version's comment-walk persisted confirmed ones). Includes BOTH confirmed (entryId) and local-pending
// comments so the detail can fall back to local data when a fresh chain read returns fewer (or none), and so an
// own just-published comment shows instantly. Note the cache is per-account, so a comment seen under another
// account is not here.
/**
 * Is this cached feed post the one `item` names? Used ONLY against a single channel's post list, where entryId is
 * unique — the cache is keyed by channel, so the channel half of the identity is the list you are searching. The
 * body-hash cross-check guards a re-used id. (Across channels, use samePublicPost.)
 */
function sameCachedPublicPost(cachedPost, item) {
  return String(cachedPost?.entryId ?? cachedPost?.id) === String(item?.entryId ?? item?.id)
    && (!item?.bodyHash || !cachedPost?.bodyHash
      || String(cachedPost.bodyHash).toLowerCase() === String(item.bodyHash).toLowerCase());
}

function cachedCommentsForPost(item) {
  if (!item) return [];
  const channelId = item.channelId ?? 'platho.app';
  const cached = publicChannelFeedCache?.[channelId]?.feed ?? publicChannelFeedCache?.[channelId] ?? null;
  const post = (cached?.posts ?? []).find((entry) => sameCachedPublicPost(entry, item));
  return post?.comments ?? [];
}

/**
 * Retire the local "sending/confirming" copy of every comment whose CHAIN twin is now in hand.
 *
 * Nothing else could do it. mergeLocalPendingPublicFeed retires a pending record when the chain twin with the same
 * body hash turns up in the sync — but the channel walk reads the CHANNEL shard, and comments live in the post's
 * THREAD shard, so its comment list is always empty and a pending COMMENT matched nothing, ever. MEASURED
 * 2026-08-13 (owner): the badge sat at "comment published, confirming" with a silent console, and past the
 * no-progress deadline resumePendingPublicPublishConfirmations would have turned it RED for a comment that was on
 * chain the whole time. The post detail already dropped it from the DISPLAY; this makes the fact stick.
 */
function retireConfirmedLocalPublicComments(item, chainComments) {
  const channelId = item?.channelId ?? null;
  if (!channelId || !Array.isArray(chainComments) || chainComments.length === 0) return false;
  const entry = publicChannelFeedCache?.[channelId] ?? null;
  const cached = entry?.feed ?? entry ?? null;
  const posts = Array.isArray(cached?.posts) ? cached.posts : [];
  let changed = false;
  const nextPosts = posts.map((post) => {
    if (!sameCachedPublicPost(post, item)) return post;
    const comments = post.comments ?? [];
    const kept = comments.filter((comment) => !(
      isPendingPublicFeedItem(comment) && chainComments.some((chainComment) => samePublicBodyHash(comment, chainComment))
    ));
    if (kept.length === comments.length) return post;
    changed = true;
    return { ...post, comments: kept };
  });
  if (!changed) return false;
  publicChannelFeedCache = {
    ...publicChannelFeedCache,
    [channelId]: {
      ...(entry ?? {}),
      feed: { version: 1, channelId, updatedAt: new Date().toISOString(), posts: nextPosts },
    },
  };
  commitPublicChannelFeedCache();
  return true;
}

function publicPostDetailMergedComments() {
  const item = publicPostDetailItem;
  if (!item) return [];
  const chain = publicPostDetailChainComments;
  // UNION of both real comment sources. Chain-forensics fact (probe 2026-07-02): every comment published before
  // the publishItemToBatchPart parent_entry_id fix went on-chain with parent_link=0 — AUTHOR-indexed, invisible
  // to get_public_parent_index forever. For those, the FEED SYNC (author-index walk) is the ONLY source, surfaced
  // here via cachedCommentsForPost; the parent-index walk (`chain`) covers comments published after the fix.
  // mergePublicComments favors its SECOND argument on entryId collision, so the chain/durable copy (which carries
  // the image data URL) wins over a feed-cache copy (images stripped on persist). A local-pending copy (no
  // entryId) is dropped once its body hash appears in the chain list.
  const cached = cachedCommentsForPost(item).filter((local) => {
    if (local.entryId !== undefined && local.entryId !== null && local.entryId !== '') return true;
    return !chain.some((chainComment) => samePublicBodyHash(local, chainComment));
  });
  return mergePublicComments(cached, chain);
}

function publicDetailStatusNode(text, { retry = false } = {}) {
  const node = document.createElement('p');
  node.className = 'public-detail-status';
  node.textContent = text;
  if (retry) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'public-detail-retry';
    button.textContent = t('common.retry');
    button.addEventListener('click', () => { refreshPublicPostDetailComments(); });
    node.append(' ', button);
  }
  return node;
}

function renderPublicPostDetail() {
  if (!publicPostDetailBody || !publicPostDetailItem) return;
  // Full rebuild ahead — stop observing the old sentinels (fresh ones re-register below).
  if (publicCommentsSentinelObserver) publicCommentsSentinelObserver.disconnect();
  // Re-find the current feed item by IDENTITY (channel + entry) so a display change (e.g. relabelling the author
  // via the chevron) reflects here without re-opening; fall back to the captured item. Matching on entryId alone
  // painted a different channel's post over the opened one — see publicPostIdentity.
  const fresh = publicFeedItemsChronological().find((it) => samePublicPost(it, publicPostDetailItem));
  const item = fresh ?? publicPostDetailItem;
  // Feed items carry the author NAME in meta[0] (= the channel/thread name) and the date as the last meta entry —
  // there is no item.author / item.createdAt. The header mirrors the private chat conversation header (avatar +
  // name + a short subtitle), so the body below can show just the post content + comments without repeating the
  // author on every row.
  const flatMeta = (item.meta ?? []).flat().filter(Boolean);
  // Same precedence as the feed row and the channel header — resolved from the WALLET. Reading item.author first
  // put the registry's channel name here (often upper-case) while the header showed the verified .ath, so one
  // channel rendered two ways on two screens.
  const authorName = publicFeedItemAuthorLabel(item);
  const dateLabel = flatMeta.length > 1 ? String(flatMeta[flatMeta.length - 1]) : '';
  // Title carries the author's identity tone (e.g. the teal ".ath" colour) — parity with the private chat header
  // (renderConversationIdentity). The date is NOT shown here; it moves into the post card below (like the feed),
  // and the subtitle is left empty so this header matches the private one (just the name).
  const authorTone = item.authorWallet ? resolveWalletChannelDisplay(item.authorWallet)?.tone : null;
  if (authorTone) {
    const toneLabel = document.createElement('span');
    toneLabel.className = `identity-title-label identity-label-${authorTone}`;
    toneLabel.textContent = authorName;
    publicPostDetailTitle.replaceChildren(toneLabel);
  } else {
    setText(publicPostDetailTitle, authorName);
  }
  setText(publicPostDetailSubtitle, '');
  if (publicPostDetailAvatar) {
    setAvatarNode(publicPostDetailAvatar, String(authorName).slice(0, 1), item.avatarImageUrl ?? publicAvatarUrlForWallet(item.authorWallet));
    // The same tier the title above is painted in — a name in gold beside a plain avatar would read as a mistake.
    applyAvatarTier(publicPostDetailAvatar, authorTone);
  }
  // The "Display as" chevron — relabel another author (same as the feed's per-post chevron). Hidden for your own
  // post, the official channel, or an item with no author wallet (matches publicItemIdentityButton's gate).
  if (publicPostAuthorIdentityButton) {
    const authorWallet = item.authorWallet ?? null;
    publicPostAuthorIdentityButton.hidden = !authorWallet
      || isOwnPublicAuthor(authorWallet)
      || item.channelId === DEFAULT_PUBLIC_CHANNEL_ID;
  }
  // READING-POSITION ANCHOR (stability): every rebuild snapshots the topmost visible comment row and its
  // viewport offset, and restores it after the rebuild, because iOS/WebKit has no overflow-anchor.
  //
  // AT scrollTop 0 AS WELL [OWNER 2026-08-24: "I scrolled up, comments started loading, a page appeared, filled the
  // screen and immediately loaded another one. I'd like the position not to jump like that — for older comments to
  // load above, and to be able to scroll up calmly to the next load"]. The guard used to skip the snapshot at the
  // very top, which is a leftover from the newest-first layout: there the top held the FRESHEST comments and a
  // reader sitting at 0 wanted to be shown what had just arrived. Reading runs oldest-first now, so the top is the
  // PAST — and 0 is exactly where a reader ends up after scrolling back through history.
  //
  // That is the whole cascade: no snapshot at 0 meant the prepended page did not push the reader down, so they
  // stayed within the 320px trigger band and the next page fired at once, and the next. With the snapshot the
  // reader travels up with their own rows and has the whole new page to read before reaching the top again.
  let detailScrollAnchor = null;
  {
    const bodyRect = publicPostDetailBody.getBoundingClientRect();
    for (const row of publicPostDetailBody.querySelectorAll('.comment-item[data-entry-id]')) {
      const rect = row.getBoundingClientRect();
      if (rect.bottom > bodyRect.top) {
        detailScrollAnchor = { id: row.dataset.entryId, offset: rect.top - bodyRect.top };
        break;
      }
    }
  }
  // KEEP THE COMMENT LIST ACROSS THE WIPE. Everything around it — the post card, the heading, the sentinels, the
  // status line — is a handful of nodes and is cheapest to rebuild; the thread is the part that grows without
  // bound and is re-rendered while it grows, so it is carried over and reconciled (see reconcileKeyedRows).
  // Detaching it here is safe: a detached node keeps its children, and appendPublicItemComments puts it back.
  //
  // ONLY WITHIN THE SAME POST. A comment row is keyed by its chain entry id, and an entry id is unique inside a
  // channel, NOT across the chain — so carrying the previous post's list into a different post could hand a
  // comment of B a row built for a comment of A that happens to share an id. The post's own identity
  // (channel + entry) is the guard, and it is the same function the comment cache keys on.
  const renderedPostKey = publicPostIdentity(item);
  const keptCommentList = renderedPostKey && renderedPostKey === publicPostDetailRenderedKey
    ? publicPostDetailBody.querySelector('.comment-list')
    : null;
  publicPostDetailRenderedKey = renderedPostKey;
  publicPostDetailBody.replaceChildren();

  // The post content, pinned at the top (no author row — the header already carries the author identity).
  const post = document.createElement('article');
  post.className = 'feed-item public-detail-post';
  // Post date lives on the card (mirrors the feed), not in the header — keeps the header to just the author.
  if (dateLabel) {
    const meta = document.createElement('div');
    meta.className = 'feed-meta public-detail-post-meta';
    const dateSpan = document.createElement('span');
    dateSpan.textContent = displayMetaLabel(dateLabel);
    meta.append(dateSpan);
    post.append(meta);
  }
  if (item.title) {
    const title = document.createElement('h2');
    title.textContent = item.title;
    post.append(title);
  }
  appendPublicItemContent(post, item);
  publicPostDetailBody.append(post);

  // Comments section.
  const section = document.createElement('section');
  section.className = 'public-detail-comments';
  const comments = publicPostDetailMergedComments();
  const heading = document.createElement('h3');
  heading.className = 'public-detail-comments-heading';
  heading.textContent = comments.length > 0 ? t('public.commentsWithCount', { count: comments.length }) : t('public.comments');
  section.append(heading);
  // The author switched comments off. Say so and stop — no list, no "no comments yet" (which invites one), no
  // loading state for a read that is not happening. The composer is hidden by CSS off data-post-comments.
  if (!publicPostCommentsAllowed(publicPostDetailItem)) {
    section.append(publicDetailStatusNode(t('public.commentsClosedByAuthor')));
    publicPostDetailBody.append(section);
    return;
  }
  // OLDEST FIRST — a thread, not a feed [OWNER 2026-08-23: "the developer made our comments backwards … people
  // could be replying to each other, reading it in reverse is perverse"]. The redesign had them newest-first like
  // the feed, and a feed is a list of unrelated posts where the freshest matters most; a comment thread is a
  // CONVERSATION, where a reply means nothing before the comment it answers. So the oldest sits at the top and
  // reading runs downward, exactly like the private conversation.
  //
  // That inverts both sentinels with it: OLDER pages in at the TOP (where the reader is when they want more
  // history), NEWER at the BOTTOM (toward the present, after a date jump). The scroll handler that arms them is
  // inverted to match — see the publicPostDetailBody scroll listener. get_page stays capped at 96 rows.
  if (publicPostDetailHasMoreComments && !publicPostDetailJumpBusy) section.append(buildCommentsLoadSentinel('earlier'));
  else if (publicPostDetailOlderTruncated && comments.length > 0) {
    section.append(publicDetailStatusNode(t('public.olderUnavailable')));
  }
  if (comments.length > 0) appendPublicItemComments(section, { comments }, keptCommentList);
  if (publicPostDetailNewerCursor && !publicPostDetailJumpBusy) section.append(buildCommentsLoadSentinel('newer'));
  if (publicPostDetailLoadState === 'loading') {
    if (comments.length === 0) section.append(buildSkeletonNodes('comment', 3));
    section.append(publicDetailStatusNode(comments.length > 0 ? t('public.loadingMoreComments') : t('public.loadingComments')));
  } else if (publicPostDetailLoadState === 'error' && comments.length === 0) {
    // The read failed (rate-limited / unreachable) after retries — we do NOT know if there are comments.
    section.append(publicDetailStatusNode(t('public.commentsNotLoadedRetry'), { retry: true }));
  } else if (publicPostDetailLoadState === 'ready' && comments.length === 0) {
    // A clean read distinguishes the two honestly: parentExists === false means the post's comment index was
    // genuinely never created (no one has commented). parentExists === true with nothing shown is anomalous (index
    // present but no comment resolved) — treat as not-yet-loaded with a retry, not as "no comments".
    section.append(publicPostDetailParentExists === false
      ? publicDetailStatusNode(t('public.noCommentsYet'))
      : publicDetailStatusNode(t('public.commentsNotLoadedYet'), { retry: true }));
  }
  publicPostDetailBody.append(section);
  if (detailScrollAnchor) {
    const holdAnchor = () => {
      const row = publicPostDetailBody.querySelector(
        `.comment-item[data-entry-id="${CSS.escape(detailScrollAnchor.id)}"]`,
      );
      if (!row) return;
      const delta = (row.getBoundingClientRect().top - publicPostDetailBody.getBoundingClientRect().top)
        - detailScrollAnchor.offset;
      if (delta !== 0) publicPostDetailBody.scrollTop += delta;
    };
    holdAnchor();
    // AND AGAIN AS THE PICTURES ARRIVE. A prepended page is measured before its images have decoded, so every one
    // of them grows the content ABOVE the reader a second time, after the anchor was already restored — the same
    // jump, arriving late. Each undecoded image re-applies the anchor once when it settles; a thread of text pays
    // nothing for this, because a complete image is skipped.
    for (const image of publicPostDetailBody.querySelectorAll('img')) {
      if (image.complete) continue;
      image.addEventListener('load', holdAnchor, { once: true });
      image.addEventListener('error', holdAnchor, { once: true });
    }
  }
  // Consumed by whichever render actually paints the new comment — the optimistic row, or the chain-confirmed one
  // that replaces it — rather than by the submit handler, which cannot know which render wins.
  if (publicPostDetailScrollToLatest) {
    publicPostDetailScrollToLatest = false;
    scrollPublicPostDetailToLatest();
  } else if (publicPostDetailOpenScrollPending && publicPostDetailBody.querySelector('.comment-item')) {
    // The first render with rows in it is the one that can place the reader; after that the anchor above keeps
    // their position across background syncs.
    publicPostDetailOpenScrollPending = false;
    requestAnimationFrame(() => applyPublicPostDetailOpenScroll());
  }
}

// [OWNER 2026-08-13] "the thread should scroll when I write a public comment on a post — right now the new comment
// shows up below the composer." Exactly: comments append at the bottom and the scroll position stayed put, so the
// one comment the author is certain to want to see — their own, just written — landed below the fold.
let publicPostDetailScrollToLatest = false;
// Armed on opening a thread this reader has been in before; consumed by the first render that has comment rows
// to place them against (see applyPublicPostDetailOpenScroll).
let publicPostDetailOpenScrollPending = false;
// Whether the reader is sitting at the END of the comment thread. Kept live by the thread's scroll handler so
// the keyboard handler can still tell after the viewport has shrunk (see pinOpenThreadsToEndAfterViewportChange).
// Starts true: a thread that has not been scrolled at all is at its end by definition.
let publicPostDetailStickToBottom = true;

function scrollPublicPostDetailToLatest() {
  if (!publicPostDetailBody) return;
  const body = publicPostDetailBody;
  // OLDEST FIRST: the freshest comment is the LAST row of the thread, so "latest" is the scroller's end again.
  const toLatest = () => { body.scrollTop = body.scrollHeight; };
  // After layout: the row was appended THIS tick; a post-card image decoding later shifts the section down,
  // so re-anchor once per pending image.
  requestAnimationFrame(toLatest);
  for (const image of body.querySelectorAll('img')) {
    if (image.complete) continue;
    image.addEventListener('load', toLatest, { once: true });
    image.addEventListener('error', toLatest, { once: true });
  }
}

// Warm the durable comment cache (IndexedDB — WITH image data URLs) into the in-memory Map BEFORE the user opens
// the post: the public analogue of restoreEncryptedMessageHistory pre-loading private messages into memory at
// boot, so openPublicPostDetail paints comments-with-images on its FIRST synchronous frame (no text-first flash,
// no chain read). Called when a post's "Comments" button is rendered (the exact set of posts that can be opened).
// Idempotent + cheap-guarded: skips a post already in the Map or already warming; a single IndexedDB get per post.
const warmingPublicPostComments = new Set();
async function warmPublicPostCommentsCache(item) {
  const cacheKey = publicPostCommentsCacheKey(item);
  if (!cacheKey || publicPostCommentsCache.has(cacheKey) || warmingPublicPostComments.has(cacheKey)) return;
  warmingPublicPostComments.add(cacheKey);
  try {
    const durable = await readCachedPublicComments(cacheKey);
    if (!durable || !Array.isArray(durable.comments) || durable.comments.length === 0) return;
    if (publicPostCommentsCache.has(cacheKey)) return; // an authoritative load beat us to it
    publicPostCommentsCache.set(cacheKey, {
      comments: durable.comments,
      parentExists: durable.parentExists === true,
      latestLink: durable.latestLink ?? null,
    });
    while (publicPostCommentsCache.size > 24) {
      publicPostCommentsCache.delete(publicPostCommentsCache.keys().next().value);
    }
    // If the user already has THIS post open and still empty (opened before the warm resolved), paint now.
    if (publicPostDetailOpen && samePublicPost(publicPostDetailItem, item)
      && publicPostDetailChainComments.length === 0) {
      publicPostDetailChainComments = durable.comments;
      publicPostDetailParentExists = durable.parentExists === true;
      publicPostDetailLoadState = 'ready';
      renderPublicPostDetail();
    }
  } catch {
    /* ignore (unavailable / quota) */
  } finally {
    warmingPublicPostComments.delete(cacheKey);
  }
}

/**
 * MAY THIS POST BE COMMENTED ON — the author's own answer, carried in the post body's COMMENTS_DISABLED flag.
 *
 * Shared rather than inlined because it was inlined ONCE, in the feed card, and the feed card is not the only way
 * into a post. FOUND BY THE OWNER 2026-08-20: a permalink opens the detail screen directly, which never asked, so
 * a post with comments switched off arrived with a working comment composer — and nothing on the send path asked
 * either, so the comment would have gone on chain, cost its author money, and stayed invisible to everyone who
 * reached the post through the feed (where the button is correctly disabled).
 *
 * Absence means ALLOWED: posts published before the flag existed carry no bit, and they were commentable.
 */
function publicPostCommentsAllowed(item) {
  return item?.commentsAllowed !== false;
}

/** A post can hold comments only once it has chain coordinates and an authenticated body to anchor them to. */
function publicPostHasChainCommentTarget(item) {
  return item?.entryId !== undefined
    && item?.entryId !== null
    && /^0x[0-9a-fA-F]{64}$/.test(String(item?.bodyHash ?? ''));
}

function openPublicPostDetail(item) {
  if (!item || item.entryId === undefined || item.entryId === null) return;
  closePublicDiscovery();
  publicCommentSurfacedKeys.clear();   // this thread's comments rise in afresh
  publicPostDetailItem = item;
  publicPostDetailOpen = true;
  // Stale-while-revalidate: paint the cached comments immediately (no re-download flash) if we have them, then
  // let refreshPublicPostDetailComments silently reload in the background.
  const cacheKey = publicPostCommentsCacheKey(item);
  const cached = publicPostCommentsCache.get(cacheKey);
  publicPostDetailChainComments = Array.isArray(cached?.comments) ? cached.comments : [];
  publicPostDetailParentExists = cached ? cached.parentExists === true : null;
  // Cursors describe a READ, not a post, so they never come from the cache: opening a post starts at the newest
  // page again. Carrying a stale cursor over would ask the chain for a page the screen is not showing.
  publicPostDetailCommentCursors = null;
  publicPostDetailHasMoreComments = false;
  publicPostDetailLoadingEarlier = false;
  publicPostDetailNewerCursor = null;
  publicPostDetailLoadingNewer = false;
  publicPostDetailJumpBusy = false;
  publicPostDetailHeadSeeded = false;
  publicPostDetailOlderTruncated = false;
  publicCommentsEmptyStreaks.earlier = { key: null, calmEmpties: 0 };
  publicCommentsEmptyStreaks.newer = { key: null, calmEmpties: 0 };
  publicCommentsPagingGeneration += 1;
  // A late clean result from the PREVIOUS post's refresh must die here even when THIS post never starts a
  // refresh of its own (comments-off posts don't) — the token otherwise bumps only inside refresh/close.
  publicPostDetailLoadToken += 1;
  publicPostDetailLoadState = publicPostDetailChainComments.length > 0 ? 'ready' : 'loading';
  if (publicPane) publicPane.dataset.postOpen = 'true';
  // THE AUTHOR'S SETTING IS HONOURED HERE, not only by the feed button that usually guards the door — see
  // publicPostCommentsAllowed. The composer is HIDDEN rather than handed a null target: a null target puts the
  // shared composer back in POST mode, and posting from the post screen publishes a new entry in the reader's own
  // channel, which is a worse outcome than the bug being fixed.
  const commentsAllowed = publicPostCommentsAllowed(item);
  if (publicPane) publicPane.dataset.postComments = commentsAllowed ? 'on' : 'off';
  // Shared composer -> comment mode for this post; no auto-focus (the user opens to read first) and no inline
  // context bar (the screen itself is the context).
  if (commentsAllowed) setPublicCommentTarget(item, { focus: false, showContext: false });
  // Opening a post starts at the TOP — the post itself is what was tapped. A jump-to-latest armed by a comment on
  // the PREVIOUS post must not survive into this one.
  publicPostDetailScrollToLatest = false;
  // ...UNLESS this reader has been here before: a thread with a reading mark reopens where they stopped [OWNER
  // 2026-08-23]. Armed rather than applied, because the comments are not loaded yet — the render that first paints
  // rows consumes it. A first visit has no mark and keeps the plain top, post first.
  publicPostDetailOpenScrollPending = publicCommentReadCursor(publicPostIdentity(item)) !== null;
  renderPublicPostDetail();
  if (publicPostDetailBody) publicPostDetailBody.scrollTop = 0;
  // DURABLE seed: after a full reload the in-memory Map is empty — pull the last-loaded comments (with images)
  // from IndexedDB and paint them instantly, before the background chain re-walk. Guarded so a fast chain result
  // or a post close/reopen is never clobbered.
  if (commentsAllowed && publicPostDetailChainComments.length === 0) {
    readCachedPublicComments(cacheKey).then((durable) => {
      if (!durable || publicPostDetailItem !== item || publicPostDetailChainComments.length > 0) return;
      publicPostDetailChainComments = durable.comments;
      publicPostDetailParentExists = durable.parentExists === true;
      publicPostDetailLoadState = 'ready';
      publicPostCommentsCache.set(cacheKey, { comments: durable.comments, parentExists: durable.parentExists === true, latestLink: durable.latestLink ?? null });
      renderPublicPostDetail();
    }).catch(() => {});
  }
  // No chain read for a post that cannot hold comments: the reads would be paid for and the answer discarded.
  if (commentsAllowed) refreshPublicPostDetailComments();
  else publicPostDetailLoadState = 'idle';
}

function closePublicPostDetail() {
  if (!publicPostDetailOpen && publicPane?.dataset?.postOpen !== 'true') return;
  publicPostDetailOpen = false;
  publicPostDetailItem = null;
  publicPostDetailScrollToLatest = false;
  publicPostDetailChainComments = [];
  publicPostDetailLoadState = 'idle';
  publicPostDetailLoadToken += 1; // invalidate any in-flight comment load so a stale result can't render
  publicPostDetailRenderedKey = null; // the next open reconciles against nothing, never against the closed post
  if (publicPane) {
    publicPane.dataset.postOpen = 'false';
    publicPane.dataset.postComments = 'on';
  }
  setPublicCommentTarget(null);
  renderPublicSurface({ anchorUnread: false });
}

// --- Newcomer discovery panel (Part B) ---
// The per-bucket painter both the open and the refresh hand to the sweep. Built per load so it carries that load's
