// v774: the ↕ dock button flips the formatting toolbar above/below the input, PERSISTED across reloads. iOS pops
// the native selection menu BELOW a selection (colliding with a toolbar-below) while Android pops it above, and
// OEM behavior varies — so it is a manual per-user toggle, not a platform guess. Default = above (right for iOS).
const COMPOSER_DOCK_STORAGE_KEY = 'platho.composerDockBelow';
function composerDockIsBelow() {
  try { return localStorage.getItem(COMPOSER_DOCK_STORAGE_KEY) === '1'; } catch { return false; }
}
function applyComposerDockPosition() {
  document.documentElement.classList.toggle('is-composer-dock-below', composerDockIsBelow());
}
const composerReducedMotion = () => { try { return window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch { return false; } };

function toggleComposerDockPosition() {
  const next = !composerDockIsBelow();
  const reduced = composerReducedMotion();
  // FLIP the composer's NON-toolbar children (input row, attachment panels, cost status): FIRST record their tops so
  // that after the toolbar's flex order flips they SLIDE to the new position instead of jumping (the toolbar keeps its
  // own slide-in). "First" — measure before the order changes.
  const rows = reduced ? [] : [...document.querySelectorAll('.composer > :not(.composer-toolbar)')].filter((el) => el.offsetParent !== null && !el.hidden);
  const firstTops = rows.map((el) => el.getBoundingClientRect().top);
  try { localStorage.setItem(COMPOSER_DOCK_STORAGE_KEY, next ? '1' : '0'); } catch { /* private mode: session-only */ }
  applyComposerDockPosition(); // "Last": the flex order flips (instant)
  if (reduced) return;
  rows.forEach((el, i) => { // "Invert + Play": each child slides from its old top to its new one
    const delta = firstTops[i] - el.getBoundingClientRect().top;
    if (!delta) return;
    el.style.transition = 'none';
    el.style.transform = `translateY(${delta}px)`;
    void el.offsetWidth;
    el.style.transition = 'transform 0.48s cubic-bezier(0.16, 1, 0.3, 1)';
    el.style.transform = 'none';
    const done = (event) => { if (event.target !== el || event.propertyName !== 'transform') return; el.style.transition = ''; el.style.transform = ''; el.removeEventListener('transitionend', done); };
    el.addEventListener('transitionend', done);
  });
  // The toolbar slides back in on its NEW side (below -> drops down; above -> rises up).
  const shift = next ? '-12px' : '12px';
  for (const tb of document.querySelectorAll('.composer-toolbar')) {
    tb.style.setProperty('--dock-shift', shift);
    tb.classList.remove('is-docking');
    void tb.offsetWidth; // reflow so the animation restarts even if it is still mid-play
    tb.classList.add('is-docking');
    const done = () => { tb.classList.remove('is-docking'); tb.removeEventListener('animationend', done); };
    tb.addEventListener('animationend', done);
  }
}
applyComposerDockPosition();
document.querySelector('#privateToolbarDock')?.addEventListener('click', toggleComposerDockPosition);
document.querySelector('#publicToolbarDock')?.addEventListener('click', toggleComposerDockPosition);

function composerMaximizeButtonLabel(button, on) {
  if (!button) return;
  button.setAttribute('aria-pressed', on ? 'true' : 'false');
  const label = t(on ? 'composer.restore' : 'composer.maximize');
  button.setAttribute('aria-label', label);
  button.setAttribute('title', label);
}

// Maximize (v780; REAL geometry animation v784): a full-screen composer for long posts. .is-maximized on the FORM is a
// CSS overlay (styles.css); the editor DOM never moves, so the draft/caret survive. The composer GROWS from its inline
// footprint to full-screen (and shrinks back) by animating its REAL geometry (top/left/width/height) — the content
// stays at natural size and RE-LAYS-OUT as the box changes (NOT a transform:scale, which squished the content and made
// the real composer JERK into place on collapse). NOT persisted.
function composerClearMaxAnimStyles(form) {
  // `bottom` belongs in this list now that the flip drives it — a leftover inline bottom would outlive the
  // animation and pin the resting composer to wherever the flip happened to end.
  for (const prop of ['transition', 'top', 'bottom', 'left', 'right', 'width', 'height']) form.style[prop] = '';
}
// Cancel an in-flight maximize animation (its transitionend listener + fallback timer + inline geometry). MUST run
// before exit (send/nav) or a re-toggle mutates the state, or a stale timer/listener would fire on a changed composer.
function composerCancelMaxFlip(form) {
  const flip = form && form.__maxFlip;
  if (flip) { clearTimeout(flip.timer); form.removeEventListener('transitionend', flip.onEnd); form.__maxFlip = null; }
  if (form) composerClearMaxAnimStyles(form);
}
// While maximized the composer is position:fixed (out of flow), so its inline slot would collapse and the chat/feed
// content would jump to fill it (and jump back on restore). A same-height spacer holds the slot until the composer
// returns to the inline layout.
function composerReserveSpacer(form, height) {
  composerReleaseSpacer(form);
  const spacer = document.createElement('div');
  spacer.setAttribute('aria-hidden', 'true');
  spacer.style.height = `${height}px`;
  spacer.style.flexShrink = '0';
  form.after(spacer);
  form.__spacer = spacer;
}
function composerReleaseSpacer(form) {
  if (form && form.__spacer) { form.__spacer.remove(); form.__spacer = null; }
}
function composerCollapseMaximizeNow(form) {
  composerCancelMaxFlip(form);
  form.classList.remove('is-maximized', 'is-restoring');
  composerReleaseSpacer(form);
  composerMaximizeButtonLabel(form.querySelector('.composer-toolbar-maximize'), false);
}
// growing=true: animate the inline footprint -> full-screen (stays maximized). growing=false: full-screen -> the inline
// footprint, then collapse to the inline layout. Uses form.__inlineRect captured at maximize time.
function composerRunMaximizeGeo(form, growing) {
  composerCancelMaxFlip(form);
  let inlineRect = form.__inlineRect;
  // On a SHRINK the app viewport may have changed since maximize (the keyboard appeared or was dismissed), so the inline
  // TOP captured at maximize time is stale — the composer would shrink to the OLD slot (e.g. behind the keyboard) then
  // JUMP to the real one. The spacer holds the composer's CURRENT inline slot and RIDES the layout (it moves with the
  // keyboard), so shift the captured top by how far the spacer has MOVED since maximize (__spacerTop0). We use the DELTA,
  // not the spacer's absolute top: the spacer sits at a small structural offset from the form's own box (and lacks the
  // public composer's edge-bleed margin), so the delta cancels that offset and a no-viewport-change restore is seamless.
  if (!growing && inlineRect && form.__spacer && form.__spacerTop0 != null) {
    const curTop = form.__spacer.getBoundingClientRect().top;
    inlineRect = { ...inlineRect, top: inlineRect.top + (curTop - form.__spacerTop0) };
  }
  // Re-read the viewport BEFORE measuring the target. [OWNER 2026-08-14] "The composer should expand INTO the
  // right place, not somewhere wrong and then get dragged there." That is exactly what a stale
  // --app-viewport-bottom-gap does: maximizing raises the keyboard, so the visible area is changing in the very
  // frame this measurement happens, and the browser reports the viewport change only afterwards. The animation
  // then flies to yesterday's rectangle and snaps to the real one when the variable catches up.
  syncViewportCssVars();
  const full = form.getBoundingClientRect(); // form currently has .is-maximized -> its full-screen rect
  if (!inlineRect || !full.width || !full.height) { if (!growing) composerCollapseMaximizeNow(form); return; }
  const fullRect = { top: full.top, left: full.left, width: full.width, height: full.height };
  // BY THE TOP EDGE, matching the CSS again now that the composer is top-anchored. The rule is the same either
  // way: the flip must drive the SAME edge the stylesheet pins, or clearing the inline values at the end hands the
  // box to a different position and the user sees it jump.
  const setGeo = (r) => {
    form.style.bottom = 'auto';
    form.style.top = `${Math.round(r.top)}px`;
    form.style.left = `${r.left}px`; form.style.right = 'auto';
    form.style.width = `${r.width}px`; form.style.height = `${r.height}px`;
  };
  const finish = () => {
    // On a shrink, drop .is-maximized WHILE the inline-footprint geometry is still applied (composer already at its
    // resting size -> no full-screen flash), THEN clear the inline geometry -> seamless hand-off to the inline layout.
    if (!growing) { form.classList.remove('is-maximized', 'is-restoring'); composerReleaseSpacer(form); composerMaximizeButtonLabel(form.querySelector('.composer-toolbar-maximize'), false); }
    composerCancelMaxFlip(form); // clears inline geometry + timer + listener
    if (emojiPicker && !emojiPicker.hidden && emojiPickerTargetButton) positionEmojiPicker(emojiPickerTargetButton);
  };
  const onEnd = (event) => { if (event.target === form && event.propertyName === 'height') finish(); };
  form.style.transition = 'none';
  setGeo(growing ? inlineRect : fullRect); // start state
  void form.offsetWidth; // reflow so the next geometry transitions
  const ease = growing ? 'cubic-bezier(0.16, 1, 0.3, 1)' : 'cubic-bezier(0.4, 0, 0.2, 1)';
  // Must name the property setGeo actually drives, or the growth is instant and — worse — the transitionend that
  // finishes the flip never fires.
  form.style.transition = `top 0.5s ${ease}, left 0.5s ${ease}, width 0.5s ${ease}, height 0.5s ${ease}`;
  setGeo(growing ? fullRect : inlineRect); // end state -> the box grows/shrinks and the content re-lays-out
  form.addEventListener('transitionend', onEnd);
  form.__maxFlip = { timer: setTimeout(finish, 700), onEnd }; // fallback so a missed transitionend can't strand mid-animation
}
function toggleComposerMaximize(form, button) {
  if (!form) return;
  const isMax = form.classList.contains('is-maximized');
  const isRestoring = form.classList.contains('is-restoring');
  if (isMax && isRestoring) return; // mid-shrink FLIP — debounce the click
  closeEmojiPicker(); // the emoji button is inside the composer; a picker anchored to it goes stale across the FLIP
  const editorEl = form.querySelector('.composer-input');
  const wasFocused = !!editorEl && document.activeElement === editorEl;
  const keyboardWasOpen = composerKeyboardLikelyOpen(); // soft keyboard actually UP (user typing) vs dismissed-but-focused
  if (isMax) {
    composerMaximizeButtonLabel(button, false);
    if (composerReducedMotion() || !form.__inlineRect) { composerCollapseMaximizeNow(form); }
    else { form.classList.add('is-restoring'); composerRunMaximizeGeo(form, false); } // shrink FLIP still full-screen until it finishes
  } else {
    const r = form.getBoundingClientRect(); // the inline footprint to grow FROM / shrink back TO
    form.__inlineRect = { left: r.left, top: r.top, width: r.width, height: r.height };
    composerCancelMaxFlip(form);
    form.classList.remove('is-restoring');
    composerReserveSpacer(form, r.height); // hold the inline slot so the chat/feed content doesn't jump
    form.classList.add('is-maximized');
    // Reference top of the spacer in the maximized (form-out-of-flow) layout — the shrink retargets by how far it later
    // MOVES from here (the keyboard changed the app viewport), so the composer collapses to the CURRENT inline slot.
    form.__spacerTop0 = form.__spacer ? form.__spacer.getBoundingClientRect().top : null;
    composerMaximizeButtonLabel(button, true);
    if (!composerReducedMotion()) composerRunMaximizeGeo(form, true);
  }
  // Focus across the state change: re-focus ONLY when the keyboard was actually UP (the user is typing) so a geometry
  // change that drops contenteditable focus doesn't hide the keyboard mid-type. When the keyboard is DOWN we do nothing —
  // and the field is already NOT focused in that case, because composerHandleKeyboardVisibility() blurs the composer the
  // moment the soft keyboard is dismissed (so this maximize/restore never faces a focused-but-keyboard-hidden field that
  // the geometry change would re-pop the keyboard for). Desktop has no soft keyboard, so keyboardWasOpen is false and the
  // caret is simply left untouched.
  if (wasFocused && keyboardWasOpen && editorEl && document.activeElement !== editorEl) focusComposerField(editorEl);
}
// Collapse any maximized composer INSTANTLY (after a send clears the draft, or on navigation away — the overlay must
// get out of the way at once, no shrink animation). Cancels any in-flight FLIP first. Returns true if it collapsed one.
function exitComposerMaximize() {
  let collapsed = false;
  for (const id of ['composer', 'publicComposer']) {
    const form = document.getElementById(id);
    if (!form) continue;
    composerCancelMaxFlip(form); // kill any in-flight FLIP so its stale timer/listener can't fire on a changed composer
    composerReleaseSpacer(form);
    if (!form.classList.contains('is-maximized')) continue;
    form.classList.remove('is-maximized', 'is-restoring');
    collapsed = true;
    composerMaximizeButtonLabel(form.querySelector('.composer-toolbar-maximize'), false);
  }
  return collapsed;
}
document.querySelector('#privateToolbarMaximize')?.addEventListener('click', (event) => toggleComposerMaximize(document.getElementById('composer'), event.currentTarget));
document.querySelector('#publicToolbarMaximize')?.addEventListener('click', (event) => toggleComposerMaximize(document.getElementById('publicComposer'), event.currentTarget));
