publicComposer?.addEventListener('submit', async (event) => {
  event.preventDefault();
  enforcePublicComposerByteLimit();
  const text = publicMessageInput?.value.trim() ?? '';
  const attachments = normalizePublicImageAttachments(publicImageAttachments);
  const fileAttachments = normalizePrivateFileAttachments(publicFileAttachments); // captured BEFORE the clear below (v750)
  // Nothing real to publish (empty draft OR an orphaned "[image N]" marker whose attachment was cleared): bail BEFORE
  // the composer clears below, so a Ctrl+Enter requestSubmit() (which bypasses the disabled button) is a clean no-op
  // instead of wiping the draft. The inner submit fns also fail closed as a backstop.
  if (publicDocumentBlocksFromDraft(text, attachments, fileAttachments).length === 0) return;
  if (!plathoWallet) {
    setPublicStatus('create wallet first');
    return;
  }
  if (tonRpcLimited()) {
    refreshComposerCostStatus();
    return;
  }
  // Part-cap gate (v648): block BEFORE the composer clears/signs — the draft stays intact with the split-it
  // message in the cost status (parity with the private composer's limitMessage block).
  if (publicComposerPartLimitMessage(publicComposerSendPlan(text, attachments, fileAttachments).length)) {
    refreshComposerCostStatus();
    setPublicStatus('message too large');
    return;
  }
  const commentsAllowed = publicComposerCommentsCheckbox?.checked !== false;
  if (!publicCommentTarget && commentsAllowed && !(await confirmPublicCommentsRisk())) {
    setPublicStatus('publish cancelled');
    return;
  }
  const send = publicComposer.querySelector('.send-button');
  send?.toggleAttribute('disabled', true);
  // Private-composer parity (owner UX directive): the draft leaves the composer THE MOMENT send is pressed —
  // the optimistic local record (inserted by the submit path with a live 'sending…' status) carries it from
  // here. Capture the comment target + reply quote BEFORE clearing so a cancel can restore the exact draft.
  const draftCommentTarget = publicCommentTarget;
  const draftReplyTo = publicCommentReplyTo;
  const draftShare = publicShareDraft;
  const draftWasMaximized = publicComposer.classList.contains('is-maximized');
  const recordsPlacedBefore = publicOptimisticRecordsPlaced;
  publicMessageInput.value = '';
  exitComposerMaximize(); // a send finishes the post — collapse the full-screen composer back to the feed
  publicImageAttachments = [];
  publicFileAttachments = [];
  updateImageAttachmentUi('public');
  updatePublicFileAttachmentUi();
  refreshComposerCostStatus();
  try {
    // Same lane as private sends: a burst of posts or comments overlaps exactly like a burst of messages, and they
    // share one wallet, one seqno and one RPC budget.
    if (draftCommentTarget) {
      // Armed BEFORE the publish: the optimistic row is painted while this await is still running.
      if (publicPostDetailOpen) publicPostDetailScrollToLatest = true;
      await enqueueOutgoingPublish(() => submitPublicCommentDirect(draftCommentTarget, text, attachments, fileAttachments));
    } else {
      await enqueueOutgoingPublish(() => submitPublicPostDirect({
        text,
        attachments,
        fileAttachments,
        commentsAllowed,
      }));
      // Only after a post that actually went out, and only for POSTS: a comment lands in someone else's thread
      // and says nothing about whether this author's channel is listed.
      void maybeWarnChannelNotDiscoverable();
    }
    // On the post detail screen the composer stays in comment mode for the SAME post (so a follow-up message is
    // another comment, not a public post). Only the inline/feed flow resets the target.
    if (!publicPostDetailOpen) setPublicCommentTarget(null);
  } catch (error) {
    const rateLimited = noteTonRpcRateLimit(error);
    const cancelled = isPublishPriceChangeCancelled(error);
    // THE DRAFT COMES BACK whenever the text is not already on screen — it used to come back only on a
    // price-cancel, so every other refusal ATE what the user had written. MEASURED 2026-08-13: the owner
    // commented on a post found through channel search, the submit threw on a guard before publishing anything,
    // and his text was simply gone with a two-word status line as the only sign.
    //
    // Not unconditional, though: once the optimistic record is placed, the same text IS in the feed (as a red
    // "failed" row that the heal driver may still resend), and restoring it as well would show it twice and
    // invite a duplicate publish. The record counter is what distinguishes the two, and it moves in the two
    // functions that place records rather than at each throw site, so a new throw is classified automatically.
    if (publicOptimisticRecordsPlaced === recordsPlacedBefore) {
      publicMessageInput.value = text;
      publicImageAttachments = attachments;
      publicFileAttachments = fileAttachments;
      if (draftReplyTo) setPublicCommentReplyTo(draftReplyTo);
      if (draftShare) setPublicShareDraft(draftShare);
      updateImageAttachmentUi('public');
      updatePublicFileAttachmentUi();
      refreshComposerCostStatus();
      // Nothing was published — put the user back in the full-screen editor they were in (not the 144px inline one).
      if (draftWasMaximized && !publicComposer.classList.contains('is-maximized')) {
        toggleComposerMaximize(publicComposer, publicComposer.querySelector('.composer-toolbar-maximize'));
      }
    }
    setPublicStatus(cancelled ? 'publish cancelled' : (rateLimited ? 'sync delayed' : (draftCommentTarget ? 'comment blocked' : 'publish blocked')));
    if (!rateLimited && !cancelled) console.error(error);
  } finally {
    refreshPublicSendButtonState();
  }
});

composer?.addEventListener('submit', async (event) => {
  event.preventDefault();
  refreshComposerPublishPolicy();
  enforceComposerByteLimit();
  const text = messageInput.value.trim();
  const attachments = normalizePrivateImageAttachments(privateImageAttachments);
  // v759: file attachments count as content — a file-only draft (its auto-inserted [file N] marker
  // hand-deleted, text empty) must reach the block-based send below, not dead-click here (the send
  // button IS enabled for it via privateComposerHasSendableContent; the public composer's equivalent
  // gate has been block-based all along).
  if (!text && attachments.length === 0 && !privateShareDraft
    && normalizePrivateFileAttachments(privateFileAttachments).length === 0) {
    // Empty submit (e.g. an accidental Send click with nothing typed) — return focus to the input so the user can
    // just start typing, the same as after a real send. A share-only draft (v766) IS content — falls through.
    focusComposerField(messageInput);
    return;
  }
  // NEVER fall back to threads[0] for a SEND: threads[0] is ALWAYS the Saved self-thread (ensureSavedMessagesThread
  // unshifts it), so a stale/unresolved activeThreadId would route the outgoing echo into "My notes" — and the later
  // relocate of that capsule to the real peer would try to graft the own wallet onto the peer. If the active dialog
  // can't be resolved, abort (the typed text stays in the composer); the user reopens the chat and resends.
  const thread = threads.find((item) => item.id === activeThreadId) ?? null;
  if (!thread) return;
  if (thread.readOnly) {
    messageInput.value = '';
    renderConversation();
    return;
  }
  if (!plathoWallet?.address) {
    refreshMessagingControls();
    return;
  }
  if (!localIdentity || !localRecipientKeyPair || !localSignedPublicBundle) {
    if (privateComposerCostStatus) {
      privateComposerCostStatus.textContent = t('chat.activateBeforeSending');
      privateComposerCostStatus.dataset.state = 'short';
    }
    refreshMessagingControls();
    return;
  }
  // Not-activated sender: keys are present (wallet unlocked) but there is no Vault user record. Reject BEFORE
  // inserting the optimistic "sending" bubble so the user sees the activation message instead of a bubble that
  // flips to "not sent". (The button is also disabled via privateSendBlockReason; this covers an Enter-key
  // submit or the brief boot window before activation status loads.) assertVaultHasPrivatePublishHold remains
  // the authoritative downstream check.
  if (!hasActivePlathoAccount()) {
    if (privateComposerCostStatus) {
      privateComposerCostStatus.textContent = t('chat.activateBeforeSending');
      privateComposerCostStatus.dataset.state = 'short';
    }
    refreshPrivateSendButtonState();
    return;
  }
  if (tonRpcLimited()) {
    // Backpressure: while the TON RPC is in an active rate-limit backoff, reject
    // new sends instead of piling another fan of verify:true pre-send reads onto
    // the already-throttled keyless verifier (the burst self-amplification that
    // turns one 429 into a storm). Mirrors the public composer gate (10128).
    if (privateComposerCostStatus) {
      privateComposerCostStatus.textContent = t('chat.rpcBusy');
      privateComposerCostStatus.dataset.state = 'short';
    }
    refreshPrivateSendButtonState();
    return;
  }

  const selectedSuite = currentOutgoingPrivateSuite();
  const senderOptions = currentPrivateSenderOptions();
  const sendPlan = privateComposerSendPlan(text, attachments, senderOptions);
  const limitMessage = privateComposerPartLimitMessage(sendPlan.length);
  if (limitMessage) {
    if (privateComposerCostStatus) {
      privateComposerCostStatus.textContent = limitMessage;
      privateComposerCostStatus.dataset.state = 'short';
    }
    refreshPrivateSendButtonState();
    return;
  }
  // Capture the reply quote + share NOW: the composer state clears below, but the capsule build (and any later
  // manual retry) runs long after — the captured values keep the echo, the wire, and every retry byte-identical.
  const replyDraft = privateReplyDraft ? { ...privateReplyDraft } : null;
  const shareDraft = privateShareDraft ? { ...privateShareDraft } : null;
  const fileAttachments = normalizePrivateFileAttachments(privateFileAttachments);
  const draftBlocks = composerBlocksFromDraft(text, attachments, replyDraft, fileAttachments, shareDraft);
  if (draftBlocks.length === 0) {
    // Nothing real to send (an orphaned "[image N]" marker whose attachment was removed, or an otherwise-empty draft):
    // fail closed at the composer instead of inserting an empty bubble that dead-ends on "Capsule publish payload is
    // missing". The send button is already disabled for this state (refreshPrivateSendButtonState); this backstops a
    // programmatic / Enter-key send.
    if (privateComposerCostStatus) {
      privateComposerCostStatus.textContent = t('composer.nothingToSend');
      privateComposerCostStatus.dataset.state = 'short';
    }
    refreshPrivateSendButtonState();
    return;
  }
  const displayBlocks = displayBlocksFromDocumentBlocks(draftBlocks);
  const message = {
    type: 'out',
    text: messagePreviewFromBlocks(displayBlocks),
    blocks: displayBlocks,
    meta: 'sending',
    privateDraft: {
      text,
      attachments,
      selectedSuite,
      senderOptions,
      replyDraft,
      shareDraft,
      fileAttachments,
    },
    privateManualRetryAvailable: false,
    privateCancelAvailable: false,
    ...localMessageOrderFields(),
  };
  ownSendPendingRender = true; // the user just sent: the next render abandons any open-anchor and scrolls to their message
  insertThreadMessage(thread, message);
  const sendContext = {
    thread,
    message,
    text,
    attachments,
    selectedSuite,
    senderOptions,
    replyDraft,
    shareDraft,
    fileAttachments,
    retryAttempt: 0,
    confirmAttempt: 0,
  };
  refreshThreadAfterMessageChange(thread);
  messageInput.value = '';
  exitComposerMaximize(); // a send finishes the message — collapse the full-screen composer back to the conversation
  privateImageAttachments = [];
  setPrivateReplyDraft(null);
  setPrivateShareDraft(null);
  privateFileAttachments = [];
  updatePrivateFileAttachmentUi();
  updateImageAttachmentUi('private');
  // Return focus to the composer so the user can keep typing without re-tapping the field. Clicking the
  // send button moved focus to the button (and on mobile would drop the keyboard); refocus synchronously
  // within the submit gesture so the keyboard stays up. messageInput is the static shell element (not
  // rebuilt by the renders below), so the focus survives renderThreads()/renderConversation().
  focusComposerField(messageInput);
  refreshComposerCostStatus();
  if (sendButton) sendButton.disabled = true;
  renderThreads();
  renderConversation();

  // clean-17 direct-pay pays the RecordShard straight from the wallet — there is no Vault hold to reserve, so the
  // Vault preflight (assertVaultHasPrivatePublishHold) is gone. Its two guarantees are covered where they belong:
  // "account activated" by canAttemptPrivateSend (the send button is disabled while the KeyShard read says not
  // registered), and "enough GRAM" by attemptConvMessagePublishDirect's own assertWalletGramAtLeast, which measures
  // the ACTUAL per-part transfer cost instead of a custodial hold estimate.

  const keylessBudget = usingKeylessTonRpc();
  const endPrivateOutboundWork = keylessBudget ? beginPrivateOutboundWork() : null;
  try {
    // clean-17 keyless coordination: on the paced ~1 rps keyless path ONLY, yield to an in-flight index-walk sync
    // pass and pause the next one (beginPrivateOutboundWork, above) while this send broadcasts — so the send + its
    // delivery confirm get the scarce budget instead of interleaving with the walk. Capped so a stuck sync can never
    // block a send; skipped entirely with a toncenter key (~8 rps headroom) so keyed sends stay latency-free.
    if (keylessBudget && privateChainSyncPromise) {
      await Promise.race([
        Promise.resolve(privateChainSyncPromise).catch(() => {}),
        delay(PRIVATE_SEND_SYNC_WAIT_CAP_MS),
      ]);
    }
    await enqueueOutgoingPublish(() => attemptPrivateComposerMessagePublish(sendContext));
  } catch (error) {
    await settlePrivateComposerSendError(sendContext, error);
  } finally {
    if (endPrivateOutboundWork) endPrivateOutboundWork();
  }
  refreshThreadAfterMessageChange(thread);
  renderThreads();
  renderConversation();
});

createWalletButton?.addEventListener('click', async () => {
  try {
    if (!(await confirmWalletReplacement(t('wallet.createNewWallet')))) return;
    const walletDraft = await createPlathoWallet(plathoWalletNetworkOptions());
    const password = await requestNewWalletStoragePassword(t('wallet.encryptNewWallet'), {
      passwordManagerUsername: walletDraft.address,
      passwordManagerNetworkGlobalId: walletDraft.networkGlobalId,
    });
    if (!password) return;
    createWalletButton.disabled = true;
    await setPlathoWallet(walletDraft, { password });
    markWalletKeyBackupPending(walletDraft.address);
    // Inside Telegram, force a confirmed seed backup right after generation: the
    // WebView can evict localStorage and the seed is the only recovery path.
    await enforceTelegramSeedBackupGate(walletDraft, { force: true });
    flashWalletIdentityStatus(t('wallet.walletReady'));
  } catch (error) {
    setText(walletAddressStatus, t('common.blocked'));
    console.error(error);
  } finally {
    refreshMessagingControls();
  }
});

importWalletButton?.addEventListener('click', async () => {
  if (!(await confirmWalletReplacement(t('wallet.importAndReplace')))) return;
  const recoveryPhrase = await requestWalletSeedImport();
  if (!recoveryPhrase) return;
  try {
    const walletDraft = await importPlathoWallet(recoveryPhrase, plathoWalletNetworkOptions());
    const password = await requestNewWalletStoragePassword(t('wallet.encryptImportedWallet'), {
      passwordManagerUsername: walletDraft.address,
      passwordManagerNetworkGlobalId: walletDraft.networkGlobalId,
    });
    if (!password) return;
    importWalletButton.disabled = true;
    await setPlathoWallet(walletDraft, { password });
    // The user just typed this phrase, so they demonstrably hold the backup.
    markTelegramSeedBackupConfirmed(walletDraft.address);
    flashWalletIdentityStatus(t('wallet.walletReady'));
  } catch (error) {
    setText(walletAddressStatus, t('wallet.importBlocked'));
    console.error(error);
  } finally {
    refreshMessagingControls();
  }
});

unlockWalletButton?.addEventListener('click', async () => {
  try {
    unlockWalletButton.disabled = true;
    const wallet = await loadPlathoWallet();
    if (!wallet) {
      flashWalletIdentityStatus(t('wallet.walletLocked'));
      return;
    }
    await bootCrypto();
    await enforceTelegramSeedBackupGate(wallet);
    flashWalletIdentityStatus(t('wallet.walletUnlocked'));
    // Return-from-background flow: a user who hopped to another wallet app to top up came back to a locked
    // Platho; on unlock, resume the quick-start at the step they were on (e.g. Top up / Activate).
    maybeResumeQuickStartAfterUnlock();
  } catch (error) {
    setText(unlockWalletStatus, t('common.blocked'));
    console.error(error);
  } finally {
    refreshMessagingControls();
  }
});

