async function confirmWalletPasswordForExport(wallet) {
  const record = readEncryptedPlathoWalletRecord();
  if (!record) return true;
  const unlocked = await requestAndDecryptEncryptedWallet(record, {
    title: t('wallet.showRecoveryPhrase'),
    hint: t('wallet.showRecoveryPhraseHint'),
    submitLabel: t('wallet.showRecoveryPhrase'),
  });
  if (!unlocked) return false;
  if (!sameWalletAddress(unlocked.address, wallet.address)) {
    throw new Error('Unlocked wallet does not match current wallet');
  }
  return true;
}

async function exportEncryptedWalletKeyFile(alreadyUnlocked = null) {
  const record = readEncryptedPlathoWalletRecord();
  if (!record) throw new Error('No encrypted wallet key is stored on this device');
  // The password here buys ONE thing: proof the record actually decrypts, so nobody walks away with a backup they
  // cannot open. A caller holding the already-decrypted wallet has that proof in hand and is not asked again.
  const unlocked = alreadyUnlocked ?? await requestAndDecryptEncryptedWallet(record, {
    title: t('wallet.exportWalletKey'),
    hint: t('wallet.exportWalletKeyHint'),
    submitLabel: t('wallet.exportWalletKey'),
  });
  if (!unlocked) return false;
  await downloadEncryptedWalletKeyBackup(record, unlocked);
  return true;
}

async function activateImportedEncryptedWalletRecord(wallet, record, { toncenterApiKey = null } = {}) {
  prepareWalletScopedRuntimeForWallet(wallet, 'wallet key imported');
  await writeEncryptedPlathoWalletRecord(record);
  // THE IMPORT'S POINT OF NO RETURN — the record is written. A toncenter key carried by the backup (v2+/v3) is applied
  // HERE, not before the write: applyToncenterApiKey overwrites the device key and rebuilds the transports irreversibly,
  // and applied ahead of the write it survived an activation that threw before the record was committed (a failed
  // setItem) — the OLD wallet stayed stored, under the NEW key. Still ahead of the first chain read (bootCrypto below),
  // which is all the pre-read placement was for (PWA-WALLET-REPLACE-03).
  if (toncenterApiKey) applyToncenterApiKey(toncenterApiKey);
  plathoWallet = wallet;
  // Importing an encrypted wallet-key backup proves the key is already backed up (the file IS the export), so
  // clear any "key never exported" pending flag for this address -- in localStorage AND its Telegram CloudStorage
  // mirror, which survives a local-data wipe and would otherwise re-flag a freshly imported wallet on next boot.
  // IMPORT is never a backup-pending state.
  markWalletKeyBackupDone(wallet.address);
  localProfileAvatarPointer = readStoredProfileAvatarPointer(wallet.address);
  markWalletUnlocked();
  refreshMessagingControls();   // same locked-era-paint window as loadPlathoWallet — repaint on assignment
  scheduleWalletAutoLock();
  await bootCrypto();
  // bootCrypto refreshed the avatar at its tail (serialized after sync); fire the vault refresh after it
  // fully settles so the single vault read does not overlap the avatar read on iOS.
  queueVaultRefreshAfterWalletChange();
  refreshMessagingControls();
  renderWalletIdentity(t('wallet.walletKeyImported'));
  return true;
}

async function importEncryptedWalletKeyFile(file) {
  const parsed = await readJsonFile(file);
  const record = encryptedWalletRecordFromBackup(parsed);
  const wallet = await requestAndDecryptEncryptedWallet(record, {
    title: t('wallet.importWalletKey'),
    hint: t('wallet.importWalletKeyHint'),
    submitLabel: t('wallet.importWalletKey'),
  });
  if (!wallet) return false;
  // v2+ backups also carry the user's own toncenter API key — restore it so importing the wallet key on a new device
  // brings the RPC key too. v1 backups (no key) skip this. Keyless toncenter works either way.
  //
  // DECRYPTED HERE, APPLIED BELOW, BEFORE THE FIRST CHAIN READ (PWA-WALLET-REPLACE-03). This used to run AFTER
  // activateImportedEncryptedWalletRecord — i.e. after the whole first boot of the imported wallet (activation read,
  // private sync, avatar, vault refresh) had gone out KEYLESS through the ~1 rps emergency queue, with the profile's
  // key field still empty the whole time. The key needs nothing but the just-decrypted wallet (v3 encrypts it under
  // the seed), so it is ready before anything touches the network. A backup whose key does not decrypt still imports.
  let restoredApiKey = null;
  if (parsed?.kind === PLATHO_WALLET_KEY_BACKUP_KIND) {
    if (parsed.toncenterApiKeyEnc) {
      // v3: encrypted under the wallet seed — decrypt with the just-unlocked wallet.
      try { restoredApiKey = await decryptToncenterApiKeyFromBackup(parsed.toncenterApiKeyEnc, wallet); }
      catch (error) { console.error(error); restoredApiKey = null; }
    } else if (typeof parsed.toncenterApiKey === 'string' && parsed.toncenterApiKey.trim()) {
      restoredApiKey = parsed.toncenterApiKey.trim(); // v2 legacy plaintext backups
    }
  }
  if (!(await confirmWalletReplacement(t('wallet.importWalletKey')))) return false;
  // Past the confirm only, and applied by the activation itself once the record is written (its point of no return):
  // a declined OR failed import must not change the device's RPC key. applyToncenterApiKey drops and rebuilds the
  // transports there, ahead of bootCrypto, so every chain read of the activation still rides the restored key.
  return activateImportedEncryptedWalletRecord(wallet, record, { toncenterApiKey: restoredApiKey?.trim() || null });
}

/**
 * What the LINK dialog says when a name cannot be verified.
 *
 * [OWNER 2026-08-13] A user pressed "Link username" when they meant "Create", owning no names at all, and got a
 * string of messages he could make nothing of. They were the raw internals of resolvePlathoUsernameOwner —
 * "<name>.ath is not registered", "belongs to another wallet", "ownership is not authoritative" — printed straight
 * into the dialog hint. English sentences on a Russian screen, naming a contract concept rather than a next step.
 *
 * Every OTHER caller of that resolver already classified UsernameNotRegisteredError into a localized line (the new
 * chat, the public link, the feed lookups). This dialog was the one that did not — the same one-lane-fixed shape
 * twice more today. Three outcomes, three sentences, and the third one is honest about not knowing.
 */
function usernameLinkErrorText(error, chosen) {
  const name = canonicalUsernameDisplay(String(chosen ?? '').trim());
  if (error instanceof UsernameNotRegisteredError) return t('username.linkNoSuchName', { name });
  if (error?.code === 'PLATHO_USERNAME_OTHER_WALLET') return t('username.linkOtherWallet', { name });
  // Anything else is a read we could not finish — a provider that is not configured, a rate limit, an
  // inconclusive ownership proof. None of those mean the name is bad, so none of them may say so.
  return t('username.linkCouldNotVerify', { name });
}

// The "no name" row in the linked-names picker. OWNING a name and PRESENTING one are different things [OWNER
// 2026-08-24: "a person may not want to link a name and still own the username. Let's put a no-username option in
// this menu, for when someone just wants to unlink theirs"] — the wallet keeps whatever .ath it owns on chain; it
// simply stops putting one on messages and posts. A sentinel no name can be: labels are lower-case letters and
// digits, so nothing typeable collides with it.
const WALLET_DISPLAY_UNLINK_OPTION = '__no_name__';

async function requestWalletDisplayIdentity(mode) {
  const normalizedMode = normalizeWalletDisplayMode(mode);
  if (normalizedMode === WALLET_DISPLAY_MODES.ADDRESS) return { mode: WALLET_DISPLAY_MODES.ADDRESS, label: '' };
  const suffix = '.ath';
  let feedback = t('username.linkNameHint', { suffix });
  let tone = 'muted';
  const current = normalizedMode === WALLET_DISPLAY_MODES.PLATHO_NFT
    ? readLinkedPlathoUsername(plathoWallet?.address)
    : readWalletDisplayIdentity(plathoWallet?.address);
  let value = current?.mode === normalizedMode ? current.label : '';
  // [OWNER 2026-08-09] The quick-pick list comes from the CHAIN now, not from what this device happens to
  // remember. That is the whole difference: the remembered list keeps offering a name that was TRANSFERRED AWAY
  // until the verification on submit refuses it, which makes the app look broken for doing the right thing. A
  // chain-verified list drops it by itself, and picking from it means never typing a name at all.
  let ownedNames = null;
  if (normalizedMode === WALLET_DISPLAY_MODES.PLATHO_NFT && plathoWallet?.address) {
    ownedNames = await loadOwnedUsernameNfts()
      .then((result) => result.owned.map((nft) => nft.label).filter(Boolean))
      .catch(() => null);
  }
  // Falls back to the remembered list when the chain could not be reached. A dialog that refuses to open offline
  // would be worse than one offering a name it re-verifies on submit anyway — and the free-text field below stays
  // in both cases, because the list can be short (indexer down) or hold an item whose name nobody could prove.
  const knownNames = normalizedMode === WALLET_DISPLAY_MODES.PLATHO_NFT
    ? (ownedNames ?? readKnownPlathoUsernames(plathoWallet?.address))
    : [];
  const fields = [];
  // The picker also opens for a wallet whose only pickable thing is "no name" — someone who linked a name and now
  // wants it off must not be blocked by a chain read that came back empty.
  const linkedNow = normalizedMode === WALLET_DISPLAY_MODES.PLATHO_NFT
    ? (readLinkedPlathoUsername(plathoWallet?.address)?.label ?? null)
    : null;
  if (knownNames.length > 0 || linkedNow) {
    fields.push({
      id: 'pick',
      type: 'select',
      label: t('username.yourLinkedNames'),
      required: false,
      options: [
        { value: '', label: t('username.enterNameBelow') },
        ...knownNames.map((label) => ({ value: label, label })),
        // Offered only when there IS something to take off — on a wallet presenting no name it would be a row that
        // does nothing.
        ...(linkedNow ? [{ value: WALLET_DISPLAY_UNLINK_OPTION, label: t('username.noNameOption') }] : []),
      ],
      value: knownNames.includes(value) ? value : '',
    });
    fields.push({
      id: 'displayName',
      label: t('username.orDifferentName', { suffix }),
      placeholder: t('username.namePlaceholder'),
      autocomplete: 'off',
      required: false,
      value: '',
    });
  } else {
    fields.push({
      id: 'displayName',
      label: WALLET_DISPLAY_MODE_LABELS[normalizedMode],
      placeholder: t('username.namePlaceholder'),
      autocomplete: 'off',
      value,
    });
  }
  // [OWNER 2026-08-13] A wallet that owns NO names opened onto a bare text field with nothing saying there was
  // nothing to type — which is exactly how someone ends up here when they meant "Create username". Say it, and say
  // what to do instead. `ownedNames !== null` is load-bearing: null means the CHAIN READ FAILED, and "you own no
  // names" is then a claim we have not earned. In that case the original hint stands and submit re-verifies.
  if (normalizedMode === WALLET_DISPLAY_MODES.PLATHO_NFT && ownedNames !== null && knownNames.length === 0) {
    feedback = t('username.linkNoNamesYet');
  }
  // The name is verified IN-PLACE on submit (validateSubmit): the dialog stays open and shows the error inline if
  // the name is not registered / not owned, instead of closing and immediately re-opening (the flicker the owner
  // reported). It only closes once the name passes verification.
  const verified = await openActionDialog({
    title: t('username.linkPlathoName'),
    hint: feedback,
    tone,
    submitLabel: t('username.linkName'),
    fields,
    checkingHint: t('username.verifyingName'),
    // [OWNER 2026-08-09] The summary row is gone. It restated the button ("verify X is owned by this wallet" above
    // "Link name") and its label was a hardcoded English 'Check' that no locale ever translated — which is why a
    // Russian dialog read "Check:". A line that repeats the button in a language the reader did not choose is
    // worse than no line.
    validateSubmit: async (values) => {
      const typed = values.displayName?.trim() ?? '';
      // The deliberate "no name". Read ONLY from the picked row and only with the free-text box empty: an empty box
      // on its own means "nothing chosen yet", not "take my name off", and a typed string must never stand in for a
      // choice the user did not make. Nothing to verify — this asks the chain for nothing.
      if (!typed && values.pick === WALLET_DISPLAY_UNLINK_OPTION) {
        return { ok: true, result: { mode: WALLET_DISPLAY_MODES.ADDRESS } };
      }
      const chosen = (typed || values.pick || '').trim();
      try {
        const result = await verifyWalletDisplayIdentity(normalizedMode, chosen, plathoWallet);
        if (result?.mode === WALLET_DISPLAY_MODES.PLATHO_NFT && result.label) {
          addKnownPlathoUsername(result.label, plathoWallet?.address);
        }
        return { ok: true, result };
      } catch (error) {
        // NOT error.message: that is the contract's own English, and this line is the whole answer the user gets.
        console.error(error);
        return { ok: false, error: usernameLinkErrorText(error, chosen) };
      }
    },
  });
  return verified ?? null;
}

async function requestUsernameMintName() {
  let feedback = t('username.mintHint');
  let tone = 'muted';
  let usernameValue = '';
  // The number this whole dialog turns on, read BEFORE the first paint. The summary is synchronous (it re-runs on
  // every keystroke), so it can only show what is already cached — and a dialog that opened on a stale or absent
  // balance is what let a user with no ATH get all the way to the mint. One read, fail-open: an unreadable balance
  // stays null and the affordability line is simply omitted.
  await refreshVaultNavBalanceInBackground().catch(() => null);
  while (true) {
    const result = await openActionDialog({
      title: t('username.mintPlathoName'),
      hint: feedback,
      tone,
      submitLabel: t('username.createUsername'),
      fields: [{
        id: 'username',
        label: t('username.usernameLabel'),
        placeholder: t('username.mintPlaceholder'),
        autocomplete: 'off',
        value: usernameValue,
      }],
      summary: (values) => {
        const raw = values.username?.trim() || t('common.notSet');
        const lines = [
          { label: t('username.display'), value: canonicalUsernameDisplay(raw) },
          { label: t('username.athPrice'), value: usernameMintPricePreview(raw) },
        ];
        // The live ATH balance + an affordability flag, read from the WALLET jetton — the thing that pays.
        //
        // [OWNER 2026-08-13] This block was skipped outright whenever direct pay was on, because it read the
        // SYNTHESIZED Vault user, whose ATH is always 0 and would have told everyone "not enough". Skipping it
        // meant the dialog said nothing about ATH at all: a user with none typed a name, pressed Create, and found
        // out only after three chain reads. Pointing it at the real balance brings the line back for everyone.
        //
        // A null balance is UNKNOWN, not zero — the line is omitted rather than guessed.
        const athBalance = connectedWalletAthBalanceAtomic();
        if (athBalance !== null) {
          let priceAtomic = null;
          try { priceAtomic = localUsernameMintPriceAtomic(normalizeUsernameInput(raw)); } catch { priceAtomic = null; }
          const short = priceAtomic !== null && athBalance < priceAtomic;
          lines.push({ label: t('username.yourAth'), value: short ? t('username.athBalanceNotEnough', { amount: formatAthAtomic(athBalance) }) : t('username.athBalance', { amount: formatAthAtomic(athBalance) }) });
        }
        lines.push({ label: t('common.cost'), value: t('common.gramCostValue', { amount: formatTonNanotons(estimatedUsernameMintTonFeeNanotons()) }) });
        // The "Route: Vault" line is GONE with the Vault. Under direct pay the mint request goes from the wallet
        // straight to UsernameRegistry (USERNAME_MINT_DIRECT_REQUEST_VALUE_NANOTONS — the constant says so), so the
        // line named a hop that no longer exists. Naming the wallet as a "route" instead would say nothing: there
        // is only one way a mint can be paid now, and the cost line above already says where the GRAM comes from.
        return lines;
      },
    });
    if (!result) return null;
    usernameValue = result.username;
    try {
      const username = normalizeUsernameInput(result.username);
      // Up-front ATH affordability gate: don't let the user walk into a mint they cannot pay for (price is by
      // length: 6+ chars = 100 ATH, 5 = 1000, 4 = 10000; <4 already rejected above). Only when the balance is
      // KNOWN — submitUsernameMintDirect re-reads the jetton wallet and stays the authority; this exists to spare
      // the user three chain reads and a status line, not to replace it.
      //
      // The sentence is t('errors.notEnoughAth'), the SAME one the authoritative check raises, so one condition
      // has one wording. The old line here was a hand-built English string that also said "top up ATH in Vault" —
      // and the Vault was removed with clean-17, so it named a place that does not exist.
      const priceAtomic = localUsernameMintPriceAtomic(username);
      const athBalance = connectedWalletAthBalanceAtomic();
      if (priceAtomic !== null && athBalance !== null && athBalance < priceAtomic) {
        const error = new Error(t('errors.notEnoughAth', { need: formatAthAtomic(priceAtomic), have: formatAthAtomic(athBalance) }));
        error.code = 'PLATHO_ATH_REQUIRED';
        throw error;
      }
      return username;
    } catch (error) {
      // A shortfall gets the one thing the sentence cannot carry: where to get ATH. Every other failure here is
      // about the NAME itself and needs no such pointer.
      feedback = error?.code === 'PLATHO_ATH_REQUIRED'
        ? `${error.message} ${t('errors.buyAthHint')}`
        : error.message;
      tone = 'error';
    }
  }
}

function avatarCompressionOptions() {
  return Object.values(IMAGE_COMPRESSION_MODES).map((mode) => ({
    value: mode.id,
    label: t('avatar.compressionOption', { label: mode.label, kib: Math.round(mode.maxBytes / 1024) }),
  }));
}

async function requestProfileAvatarUploadDetails(file) {
  return requestCompressedImageFile(file, {
    modeId: pendingProfileAvatarModeId,
    title: t('avatar.setProfileAvatar'),
    hint: t('avatar.uploadHint'),
    submitLabel: t('avatar.useAvatar'),
    extraRows: (attachment) => [
      { label: t('username.athPrice'), value: t('common.athPriceBurn', { price: formatAthAtomic(PROFILE_AVATAR_PRICE_ATH) }) },
      { label: t('avatar.gramFee'), value: profileAvatarTonFeeLabel(attachment) },
      { label: t('avatar.visibility'), value: t('avatar.mediaIsPublic') },
    ],
  });
}


function nextQueryId() {
  const cryptoImpl = globalThis.crypto;
  if (!cryptoImpl || typeof cryptoImpl.getRandomValues !== 'function') {
    throw new Error('crypto.getRandomValues is unavailable for query id generation');
  }
  const entropy = new Uint32Array(1);
  cryptoImpl.getRandomValues(entropy);
  return (BigInt(Math.floor(Date.now() / 1000)) << 32n) | BigInt(entropy[0]);
}

function bytesToHex(bytes) {
  return [...bytes].map((byte) => byte.toString(16).padStart(2, '0')).join('');
}

async function sha256Hex(bytes) {
  const digest = await globalThis.crypto.subtle.digest('SHA-256', bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes ?? []));
  return `0x${bytesToHex(new Uint8Array(digest))}`;
}

function bytesToBase64(bytes) {
  const input = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes ?? []);
  let binary = '';
  for (const byte of input) binary += String.fromCharCode(byte);
  return btoa(binary);
}

function bytesToImageDataUrl(bytes, mime = 'image/webp') {
  return `data:${mime};base64,${bytesToBase64(bytes)}`;
}

async function blobToBytes(blob) {
  return new Uint8Array(await blob.arrayBuffer());
}

let nativeCanvasWebpEncodeSupported = null;

function canvasToNativeWebpBytes(canvas, quality) {
  return new Promise((resolve, reject) => {
    canvas.toBlob(async (blob) => {
      if (!blob) {
        reject(new Error('Image compression failed'));
        return;
      }
      try {
        resolve(await blobToBytes(blob));
      } catch (error) {
        reject(error);
      }
    }, 'image/webp', quality);
  });
}

async function canvasToWebpBytes(canvas, quality) {
  if (nativeCanvasWebpEncodeSupported !== false) {
    try {
      const bytes = await canvasToNativeWebpBytes(canvas, quality);
      if (isWebpBytes(bytes)) {
        nativeCanvasWebpEncodeSupported = true;
        return bytes;
      }
    } catch {
      // Fall through to the bundled encoder.
    }
    nativeCanvasWebpEncodeSupported = false;
  }
  return encodeCanvasToWebp(canvas, quality);
}

async function compressImageFile(file, modeId) {
  if (!file || !/^image\//i.test(file.type ?? '')) throw new Error('Choose an image file');
  const mode = imageCompressionMode(modeId);
  const bitmap = await createImageBitmap(file);
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d', { alpha: false });
  if (!ctx) throw new Error('Canvas is unavailable');
  try {
    const maxOriginalSide = Math.max(bitmap.width, bitmap.height);
    let best = null;
    for (const side of [1024, 896, 768, 640, 512, 448, 384, 320, 256, 192, 160, 128, 96, 64, 48, 32, 24, 16]) {
      const scale = Math.min(1, side / maxOriginalSide);
      canvas.width = Math.max(1, Math.round(bitmap.width * scale));
      canvas.height = Math.max(1, Math.round(bitmap.height * scale));
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.drawImage(bitmap, 0, 0, canvas.width, canvas.height);
      for (const quality of [0.86, 0.76, 0.66, 0.56, 0.46, 0.36, 0.28, 0.2, 0.14, 0.08]) {
        const bytes = await canvasToWebpBytes(canvas, quality);
        if (!isWebpBytes(bytes)) throw new Error('Image encoder did not produce WebP bytes');
        if (!best || bytes.length < best.bytes.length) {
          best = { bytes, width: canvas.width, height: canvas.height, quality };
        }
        if (bytes.length <= mode.maxBytes) {
          return {
            ...best,
            mode,
            name: file.name || 'image.webp',
            sourceFile: file,
            mime: 'image/webp',
            mediaFormat: PLATHO_COMPACT_IMAGE_FORMATS.WEBP,
            dataUrl: bytesToImageDataUrl(bytes, 'image/webp'),
          };
        }
      }
    }
    if (!best) throw new Error('Image compression failed');
    if (best.bytes.length > mode.maxBytes) {
      throw new Error(`Image could not fit ${Math.ceil(mode.maxBytes / 1024)} KiB`);
    }
    return {
      ...best,
      mode,
      name: file.name || 'image.webp',
      sourceFile: file,
      mime: 'image/webp',
      mediaFormat: PLATHO_COMPACT_IMAGE_FORMATS.WEBP,
      dataUrl: bytesToImageDataUrl(best.bytes, 'image/webp'),
    };
  } finally {
    bitmap.close?.();
  }
}

function hexToBytes(hex) {
  const text = String(hex ?? '').trim();
  if (!/^[0-9a-fA-F]+$/.test(text) || text.length % 2 !== 0) {
    throw new Error('Invalid hex bytes');
  }
  const out = new Uint8Array(text.length / 2);
  for (let i = 0; i < out.length; i += 1) {
    out[i] = Number.parseInt(text.slice(i * 2, i * 2 + 2), 16);
  }
  return out;
}

function bytesToBigIntValue(bytes) {
  let value = 0n;
  for (const byte of bytes ?? []) value = (value << 8n) | BigInt(byte);
  return value;
}

function uint256HexToBigInt(value, name = 'uint256') {
  const text = normalizeAvatarHashHex(value).slice(2);
  const bigint = BigInt(`0x${text}`);
  if (bigint < 0n || bigint >= (1n << 256n)) throw new Error(`${name} is out of range`);
  return bigint;
}

const PLATHO_DOCUMENT_MAGIC = new Uint8Array([0x50, 0x44, 0x43, 0x31]); // "PDC1"
const PLATHO_DOCUMENT_VERSION = 1;
const PLATHO_DOCUMENT_HEADER_BYTES = 8;
const PLATHO_DOCUMENT_BLOCK_HEADER_BYTES = 6;
const PLATHO_DOCUMENT_BLOCK_TYPES = Object.freeze({
  TEXT: 1,
  IMAGE: 2,
  // 3 = PAYMENT (removed: in-app payment checks were not anonymous → misleading). Byte value reserved, never reused.
  // A self-addressed subscription snapshot (Phase 2): the body of a private capsule the user sends to THEMSELVES to
  // persist their public-channel subscriptions on-chain. Never rendered as chat — diverted in messageFromOpenedCapsule.
  PREFS: 4,
  // Telegram-style reply reference (v646): a denormalized quote of the replied-to message/comment — refEntryId
  // (chain-global CapsuleHub entry id) + author label + snippet, codec in capsule-part-policy.mjs. Rides as the
  // FIRST block. Symmetric across surfaces (private documents + public document posts/comments share PDC1).
  REPLY: 5,
  // Arbitrary file attachment (v652): name + mime + bytes — codec in capsule-part-policy.mjs. Old clients
  // skip it via the tolerant decode (the REPLY precedent).
  FILE: 6,
  // Channel self-description (description + user tags) published as a normal public top-level POST so any client
  // can read a channel's profile by walking that author's public_author_index. Codec in capsule-part-policy.mjs;
  // old clients skip it via the tolerant public decode (the REPLY/FILE precedent).
  PROFILE: 7,
  // A public post shared into a private chat / the sender's own channel (v766): chain coordinates + a
  // denormalized display snapshot — codec in capsule-part-policy.mjs. Old clients skip it via the tolerant
  // decode on BOTH surfaces (the private DISPLAY decode has been tolerant since v646).
  SHARE: 8,
  // The author's .ath CLAIM riding an ordinary PUBLIC post/comment (2026-08-26). The private surface has carried
  // senderUsername on every message from the start; the public surface carried it ONLY in the channel-profile
  // block, so an author who never saved a profile (or saved it before linking) stayed a bare address on every
  // card [OWNER: "the user posts to the feed. The user has a username, but the app does not see it"]. A claim,
  // never a proof — the receive path verifies it against the registry exactly like the profile claim. PUBLIC
  // documents only (their decode is tolerant, so old clients skip it); the private path neither needs nor takes
  // it — its envelope already carries the same fact.
  SENDER: 9,
});
// v759: `[file N]` joins `[image N]` as a positional composer marker — a file attachment lands at the
// cursor like an image does, instead of silently appending after the body. Group 1 = image index,
// group 2 = file index; the `(?!\()` keeps labeled links ([file 1](url)) out, same as images.
// v766: `[post]` marks where the shared-post block lands (positional like [image]/[file]; single like [check]).
const COMPOSER_SHARE_MARKER_RE = /\[post\](?!\()/ig;
const COMPOSER_MARKER_RE = /\[(?:image|img)\s+(\d+)\](?!\()|\[file\s+(\d+)\](?!\()|(\[post\])(?!\()/ig;

function concatUint8Arrays(parts) {
  const arrays = parts.map((part) => part instanceof Uint8Array ? part : new Uint8Array(part ?? []));
  const out = new Uint8Array(arrays.reduce((sum, part) => sum + part.length, 0));
  let offset = 0;
  for (const part of arrays) {
    out.set(part, offset);
    offset += part.length;
  }
  return out;
}

function uint16Bytes(value, name = 'uint16') {
  const number = Number(value);
  if (!Number.isSafeInteger(number) || number < 0 || number > 0xffff) throw new RangeError(`${name} must fit uint16`);
  return new Uint8Array([(number >> 8) & 0xff, number & 0xff]);
}

function uint32Bytes(value, name = 'uint32') {
  const number = Number(value);
  if (!Number.isSafeInteger(number) || number < 0 || number > 0xffffffff) throw new RangeError(`${name} must fit uint32`);
  return new Uint8Array([
    (number >> 24) & 0xff,
    (number >> 16) & 0xff,
    (number >> 8) & 0xff,
    number & 0xff,
  ]);
}

function readUint16FromBytes(bytes, offset, name = 'uint16') {
  if (offset + 2 > bytes.length) throw new Error(`${name} is truncated`);
  return (bytes[offset] << 8) | bytes[offset + 1];
}

function readUint32FromBytes(bytes, offset, name = 'uint32') {
  if (offset + 4 > bytes.length) throw new Error(`${name} is truncated`);
  return (((bytes[offset] << 24) >>> 0) + (bytes[offset + 1] << 16) + (bytes[offset + 2] << 8) + bytes[offset + 3]) >>> 0;
}

function encodeMessageDocumentBlocks(blocks, options = {}) {
  const normalized = (blocks ?? []).filter((block) => block && block.type);
  if (normalized.length <= 0) throw new Error('Document message is empty');
  if (normalized.length > 0xffff) throw new Error('Document message has too many blocks');
  const encodedBlocks = normalized.map((block) => {
    let type = 0;
    let flags = 0;
    let content = new Uint8Array();
    if (block.type === 'text') {
      type = PLATHO_DOCUMENT_BLOCK_TYPES.TEXT;
      content = new TextEncoder().encode(String(block.text ?? ''));
    } else if (block.type === 'image') {
      type = PLATHO_DOCUMENT_BLOCK_TYPES.IMAGE;
      flags = Number(block.format ?? block.mediaFormat ?? PLATHO_COMPACT_IMAGE_FORMATS.WEBP) & 0xff;
      const bytes = block.bytes instanceof Uint8Array ? block.bytes : new Uint8Array(block.bytes ?? []);
      content = concatUint8Arrays([
        uint16Bytes(block.width ?? 0, 'image width'),
        uint16Bytes(block.height ?? 0, 'image height'),
        bytes,
      ]);
    } else if (block.type === 'prefs') {
      type = PLATHO_DOCUMENT_BLOCK_TYPES.PREFS;
      content = block.bytes instanceof Uint8Array ? block.bytes : new Uint8Array(block.bytes ?? []);
    } else if (block.type === 'reply') {
      type = PLATHO_DOCUMENT_BLOCK_TYPES.REPLY;
      content = encodeReplyBlockContent(block);
    } else if (block.type === 'file') {
      type = PLATHO_DOCUMENT_BLOCK_TYPES.FILE;
      content = encodeFileBlockContent(block);
    } else if (block.type === 'profile') {
      type = PLATHO_DOCUMENT_BLOCK_TYPES.PROFILE;
      content = encodeProfileBlockContent(block);
    } else if (block.type === 'share') {
      type = PLATHO_DOCUMENT_BLOCK_TYPES.SHARE;
      content = encodeShareBlockContent(block);
    } else if (block.type === 'sender') {
      type = PLATHO_DOCUMENT_BLOCK_TYPES.SENDER;
      content = new TextEncoder().encode(canonicalUsernameDisplay(String(block.username ?? '')));
    } else {
      throw new Error('Unsupported document block type');
    }
    return concatUint8Arrays([
      new Uint8Array([type, flags]),
      uint32Bytes(content.length, 'document block length'),
      content,
    ]);
  });
  return concatUint8Arrays([
    PLATHO_DOCUMENT_MAGIC,
    new Uint8Array([PLATHO_DOCUMENT_VERSION, 0]),
    uint16Bytes(encodedBlocks.length, 'document block count'),
    ...encodedBlocks,
  ]);
}

function decodeMessageDocumentBlocks(bytesLike, options = {}) {
  // tolerateUnknownBlocks: forward-compat reader tolerance. The block frame is [type, flags, uint32 len,
  // content] and `offset` is advanced past `content` BEFORE the type dispatch, so an unrecognized block can
  // be SKIPPED while keeping the offset aligned (the trailing-bytes invariant below still holds). PUBLIC
  // decode opts in so a future post that carries a new block type (e.g. an author-username tag added in a
  // later phase) still decodes on this client instead of throwing. PRIVATE decode stays STRICT (default
  // false) — no behavior change for the funds-/correctness-sensitive private path.
  const tolerateUnknownBlocks = options.tolerateUnknownBlocks === true;
  const bytes = bytesLike instanceof Uint8Array ? bytesLike : new Uint8Array(bytesLike ?? []);
  if (bytes.length < PLATHO_DOCUMENT_HEADER_BYTES) throw new Error('Document message is truncated');
  for (let index = 0; index < PLATHO_DOCUMENT_MAGIC.length; index += 1) {
    if (bytes[index] !== PLATHO_DOCUMENT_MAGIC[index]) throw new Error('Unsupported document message magic');
  }
  if (bytes[4] !== PLATHO_DOCUMENT_VERSION) throw new Error('Unsupported document message version');
  const count = readUint16FromBytes(bytes, 6, 'document block count');
  const blocks = [];
  let offset = PLATHO_DOCUMENT_HEADER_BYTES;
  for (let index = 0; index < count; index += 1) {
    if (offset + PLATHO_DOCUMENT_BLOCK_HEADER_BYTES > bytes.length) throw new Error('Document block is truncated');
    const type = bytes[offset];
    const flags = bytes[offset + 1];
    const length = readUint32FromBytes(bytes, offset + 2, 'document block length');
    offset += PLATHO_DOCUMENT_BLOCK_HEADER_BYTES;
    if (offset + length > bytes.length) throw new Error('Document block content is truncated');
    const content = bytes.subarray(offset, offset + length);
    offset += length;
    if (type === PLATHO_DOCUMENT_BLOCK_TYPES.TEXT) {
      blocks.push({ type: 'text', text: new TextDecoder().decode(content) });
    } else if (type === PLATHO_DOCUMENT_BLOCK_TYPES.IMAGE) {
      if (content.length < 4) throw new Error('Document image block is truncated');
      blocks.push({
        type: 'image',
        format: flags || PLATHO_COMPACT_IMAGE_FORMATS.WEBP,
        bytes: content.subarray(4),
        width: readUint16FromBytes(content, 0, 'image width'),
        height: readUint16FromBytes(content, 2, 'image height'),
      });
    } else if (type === PLATHO_DOCUMENT_BLOCK_TYPES.PREFS) {
      blocks.push({ type: 'prefs', bytes: content.slice() });
    } else if (type === PLATHO_DOCUMENT_BLOCK_TYPES.REPLY) {
      // A malformed/future-version reply frame decodes to null and is simply dropped — the quote is cosmetic
      // and must never make the carrying message undecodable.
      const reply = decodeReplyBlockContent(content);
      if (reply) blocks.push({ type: 'reply', ...reply });
    } else if (type === PLATHO_DOCUMENT_BLOCK_TYPES.FILE) {
      // Same null-on-malformed rule as REPLY: a bad file frame is dropped, never poisons the message.
      const file = decodeFileBlockContent(content);
      if (file) blocks.push({ type: 'file', ...file });
    } else if (type === PLATHO_DOCUMENT_BLOCK_TYPES.PROFILE) {
      // Same null-on-malformed rule: a bad profile frame is dropped, never poisons the carrying post.
      const profile = decodeProfileBlockContent(content);
      if (profile) blocks.push({ type: 'profile', ...profile });
    } else if (type === PLATHO_DOCUMENT_BLOCK_TYPES.SHARE) {
      // Same null-on-malformed rule: a bad share frame is dropped, never poisons the carrying message.
      const share = decodeShareBlockContent(content);
      if (share) blocks.push({ type: 'share', ...share });
    } else if (type === PLATHO_DOCUMENT_BLOCK_TYPES.SENDER) {
      const username = new TextDecoder().decode(content).trim();
      if (username) blocks.push({ type: 'sender', username });
    } else if (tolerateUnknownBlocks) {
      // Skip an unrecognized block (offset already advanced past its content above) — forward-compat.
      continue;
    } else {
      throw new Error('Unsupported document block type');
    }
  }
  if (offset !== bytes.length) throw new Error('Document message has trailing bytes');
  return blocks;
}

function isTonRpcVerificationUnavailableForOwnVaultActionError(error) {
  const message = String(error?.message ?? error ?? '');
  return error?.code === 'RPC_VERIFICATION_UNAVAILABLE'
    || /TON RPC verification unavailable|RPC_VERIFICATION_UNAVAILABLE|verification unavailable/i.test(message);
}

function isTonRpcVerificationSoftReadError(error) {
  const message = String(error?.message ?? error ?? '');
  return error?.code === 'RPC_VERIFICATION_UNAVAILABLE'
    || error?.code === 'RPC_DISAGREEMENT'
    || /TON RPC verification unavailable|RPC_VERIFICATION_UNAVAILABLE|TON RPC disagreement|RPC_DISAGREEMENT|verification unavailable/i.test(message);
}

function isTonRpcRecoverableReadError(error) {
  return isTonRpcVerificationSoftReadError(error) || isTonRpcTransientError(error);
}

function tonRpcVerificationStructurallyDegraded() {
  const transport = globalThis.plathoTonRpcTransport;
  if (typeof transport?.isDegraded === 'function' && transport.isDegraded() === true) return true;
  // A dead verifier (for example keyless toncenter blocked for the user's
  // network) breaks dual-provider verification just as hard as a dead
  // primary gateway does.
  return typeof transport?.isVerificationDegraded === 'function' && transport.isVerificationDegraded() === true;
}

async function callWithDegradedTransportReadFallback(readStrict, readUnverified) {
  // Own-action pre-sign reads fail closed on any verification trouble while
  // dual-provider verification is actually possible. The unverified fallback
  // opens only when the transport reports that verification is structurally
  // impossible: the primary gateway is parked (censorship survival) or every
  // verifier transport is dead/blocked for this network.
  if (tonRpcVerificationStructurallyDegraded()) return readUnverified();
  try {
    return await readStrict();
  } catch (error) {
    if (!isTonRpcVerificationUnavailableForOwnVaultActionError(error)) throw error;
    if (!tonRpcVerificationStructurallyDegraded()) throw error;
    return readUnverified();
  }
}

function delay(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function isTonRpcRateLimitError(error) {
  const message = String(error?.message ?? error ?? '');
  return error?.status === 429
    || error?.code === 'RATE_LIMITED'
    || /HTTP 429|Too Many Requests/i.test(message);
}

function tonRpcLimitBackoffMs(error = null) {
  // The configured keyless backoff (~7s) is the CEILING for the app-level limiter park (composer
  // backpressure + send bail). Honor a SMALLER server-supplied retry-after, but never let a large (or a
  // stale-hardcoded) error.retryAfterMs re-introduce a multi-minute idle here — the transport's own
  // state.backoffUntil still honors a real Retry-After for actual request pacing.
  const configured = Number(appConfig.network?.tonRpc?.rateLimitBackoffMs);
  const ceiling = Number.isFinite(configured) && configured > 0
    ? Math.floor(configured)
    : TON_RPC_LIMIT_FALLBACK_BACKOFF_MS;
  const retryAfterMs = Number(error?.retryAfterMs);
  if (Number.isFinite(retryAfterMs) && retryAfterMs > 0) {
    return Math.max(TON_RPC_LIMIT_MIN_BACKOFF_MS, Math.min(Math.floor(retryAfterMs), ceiling));
  }
  return Math.max(TON_RPC_LIMIT_MIN_BACKOFF_MS, ceiling);
}

function tonRpcLimited() {
  return tonRpcLimitedUntil > Date.now();
}

function scheduleTonRpcLimitedClear() {
  if (tonRpcLimitedTimer) {
    clearTimeout(tonRpcLimitedTimer);
    tonRpcLimitedTimer = null;
  }
  if (!tonRpcLimited()) return;
  const waitMs = Math.max(250, tonRpcLimitedUntil - Date.now());
  tonRpcLimitedTimer = setTimeout(() => {
    tonRpcLimitedTimer = null;
    if (tonRpcLimited()) {
      scheduleTonRpcLimitedClear();
      return;
    }
    tonRpcLimitedUntil = 0;
    globalThis.plathoTonRpcLimitedUntil = 0;
    refreshComposerCostStatus();
  }, waitMs);
}

function markTonRpcLimited(error = null) {
  tonRpcLimitedUntil = Math.max(tonRpcLimitedUntil, Date.now() + tonRpcLimitBackoffMs(error));
  globalThis.plathoTonRpcLimitedUntil = tonRpcLimitedUntil;
  scheduleTonRpcLimitedClear();
  refreshComposerCostStatus();
}

function noteTonRpcRateLimit(error) {
  if (!isTonRpcRateLimitError(error)) return false;
  markTonRpcLimited(error);
  return true;
}

// "This read failed for a reason that is not a bug" — a degraded/rate-limited/unverifiable chain read, as opposed to
// a real fault worth a console.error. The Vault provider class it was named for is gone; the predicate stays because
// every clean-17 reader (KeyShard, PublicShard, RecordShard, registries) raises exactly these transport conditions.
function isExpectedVaultProviderUnavailable(error) {
  const message = String(error?.message ?? error ?? '');
  return isTonRpcRateLimitError(error)
    || isTonRpcVerificationUnavailableError(error)
    || /verification unavailable/i.test(message);
}

// Max time a critical read may WAIT in the transport's request queue before it is abandoned. The keyless
// emergency toncenter queue is serial (~1 rps) with a 60s backoff on 429; with the default queueTimeoutMs
// of 0 (no deadline) a read could sit behind that backoff effectively forever, so balance/critical reads
// "never finish" on a degraded network. An 8s queue deadline makes such a read fail fast (caller degrades/
// retries) instead of piling up unbounded. A healthy gateway issues immediately (empty queue), so this
// never bites normal reads.
const CRITICAL_CHAIN_READ_QUEUE_TIMEOUT_MS = 8_000;

// Overall backstop for the WHOLE refreshVaultNow (dashboard + activation + stats jobs). The dashboard read
// deadline above un-freezes the balance render, but the activation/stats jobs do the same verify:true reads
// and would otherwise keep op='vault' + the single-flight lock held for minutes under degraded RPC. Past
// this the caller-visible refresh returns (op -> idle, lock released, auto-refresh resumes); any still-slow
// inner read finishes in the background and renders late.
const VAULT_REFRESH_DEADLINE_MS = 16_000;

function unverifiedCriticalChainReadOptions() {
  return {
    verify: false,
    allowUnverifiedCriticalRead: true,
    priority: 'critical',
    cacheTtlMs: 0,
    queueTimeoutMs: CRITICAL_CHAIN_READ_QUEUE_TIMEOUT_MS,
  };
}

function extractTonWalletBalance(value) {
  if (value === null || value === undefined) return null;
  if (typeof value === 'bigint') return value >= 0n ? value : null;
  if (typeof value === 'number' && Number.isFinite(value) && value >= 0) return BigInt(Math.trunc(value));
  if (typeof value === 'string' && /^[0-9]+$/.test(value.trim())) return BigInt(value.trim());
  if (typeof value === 'object') {
    return extractTonWalletBalance(
      value.balance
      ?? value.ton_balance
      ?? value.tonBalance
      ?? value.account?.balance
      ?? value.result?.balance
      ?? value.result?.account?.balance,
    );
  }
  return null;
}

function walletBalanceInfoEndpoint() {
  const explicit = globalThis.plathoWalletBalanceEndpoint
    ?? globalThis.PLATHO_WALLET_BALANCE_ENDPOINT
    ?? appConfig.network?.walletBalanceEndpoint;
  return explicit ? String(explicit) : null;
}

async function fetchTonWalletBalance(address) {
  const endpoint = walletBalanceInfoEndpoint();
  if (!endpoint || typeof fetch !== 'function') return null;
  const cacheKey = `${endpoint}|${address}`;
  const cached = tonWalletBalanceCache.get(cacheKey);
  if (cached && Date.now() - cached.updatedAt <= TON_WALLET_BALANCE_CACHE_MS) return cached.balance;
  const existing = tonWalletBalanceInFlight.get(cacheKey);
  if (existing) return existing;
  const promise = (async () => {
    const url = new URL(endpoint, window.location.href);
    url.searchParams.set('address', address);
    const apiKey = globalThis.plathoTonRpcApiKey ?? globalThis.PLATHO_TON_RPC_API_KEY ?? appConfig.network?.tonRpc?.apiKey ?? null;
    const controller = typeof AbortController === 'function' ? new AbortController() : null;
    const timer = controller ? setTimeout(() => controller.abort(), TON_WALLET_BALANCE_FETCH_TIMEOUT_MS) : null;
    let response;
    try {
      response = await fetch(url.href, {
        method: 'GET',
        headers: {
          Accept: 'application/json',
          ...(apiKey ? { 'X-API-Key': apiKey } : {}),
        },
        cache: 'no-store',
        ...(controller ? { signal: controller.signal } : {}),
      });
    } finally {
      if (timer) clearTimeout(timer);
    }
    if (!response.ok) {
      const error = new Error(`GRAM wallet balance HTTP ${response.status}`);
      error.status = response.status;
      error.code = response.status === 429 ? 'RATE_LIMITED' : 'HTTP_ERROR';
      if (response.status === 429 && cached) return cached.balance;
      throw error;
    }
    const balance = extractTonWalletBalance(await response.json());
    if (balance !== null) tonWalletBalanceCache.set(cacheKey, { balance, updatedAt: Date.now() });
    return balance;
  })();
  tonWalletBalanceInFlight.set(cacheKey, promise);
  try {
    return await promise;
  } finally {
    tonWalletBalanceInFlight.delete(cacheKey);
  }
}

async function loadConnectedTonWalletBalance(address = requirePlathoWalletAddress()) {
  // One logical external-GRAM read (sequential provider/fetch fallbacks; calls no other wrapped Vault read), held
  // under the shared read mutex so it never overlaps a get_user/get_global on iOS.
  return withVaultReadLock(async () => {
    const candidates = [
      globalThis.plathoWalletBalanceProvider,
      globalThis.plathoTonWalletProvider,
      globalThis.plathoTonRpcTransport,
    ].filter(Boolean);
    for (const provider of candidates) {
      for (const method of ['getTonBalance', 'getWalletBalance', 'getAccountBalance', 'getBalance']) {
        if (typeof provider?.[method] !== 'function') continue;
        try {
          const balance = extractTonWalletBalance(await provider[method](address));
          if (balance !== null) return balance;
        } catch {
          // Try the next provider shape.
        }
      }
      if (typeof provider?.getAccount === 'function') {
        try {
          const balance = extractTonWalletBalance(await provider.getAccount(address));
          if (balance !== null) return balance;
        } catch {
          // Try the next provider.
        }
      }
    }
    try {
      return await fetchTonWalletBalance(address);
    } catch (error) {
      if (!noteTonRpcRateLimit(error)) console.error(error);
      return null;
    }
  });
}

// Shared direct-pay affordability pre-flight. Under Vault the CONTRACT refused an underfunded action before
// anything was spent; direct pay has no such gate — the wallet signs whatever it is handed, and
// storeOutList stamps SendIgnoreErrors (platho-wallet.mjs `sendMode | 2`), so an action the wallet cannot
// fund is SKIPPED SILENTLY: the transaction still commits, seqno still advances, sendBoc still returns 200.
// Nothing throws. That is why the check has to happen HERE, before signing.
//
// The two rules are deliberately asymmetric:
//  - ATH is FAIL-CLOSED. loadConnectedAthWalletBalance already maps "jetton wallet not deployed" to 0n, so a
//    thrown error means the balance is genuinely unknown — and publishing bytes for a payment that cannot
//    settle leaves paid-for garbage on chain (the avatar case: bytes land, the 100 ATH leg bounces, the
//    pointer is never written, and nothing on chain will ever fix it).
//  - GRAM is FAIL-OPEN. That balance is a plain account read that flaps; blocking a funded wallet on a flaky
//    read is worse than letting the send itself be the authority. Same rule the ATH flush already uses.
async function assertConnectedAthAtLeast(requiredAtomic, action) {
  const required = nonNegativeBigInt(requiredAtomic);
  if (required <= 0n) return;
  const balance = await loadConnectedAthWalletBalance();
  if (balance < required) {
    // THE MESSAGE IS SHOWN VERBATIM, so it has to be in the user's language. The avatar and mint handlers print
    // error.message straight into the status line precisely because it carries the exact shortfall — which made an
    // English template a status nobody outside English could read, on the one screen where the number matters.
    //
    // The ACTION is deliberately no longer part of the sentence. It used to be interpolated as an English verb
    // phrase ('set an avatar', 'mint a name'), and translating THAT would mean a localized fragment per call site;
    // the status already sits inside the flow the user just started, so naming it again said nothing.
    const error = new Error(t('errors.notEnoughAth', { need: formatAthAtomic(required), have: formatAthAtomic(balance) }));
    error.code = 'PLATHO_ATH_REQUIRED';
    // Kept for the console, not for the screen: which flow refused is a DIAGNOSTIC, and it is the reason the
    // action argument still earns its place at six call sites now that the sentence no longer carries it.
    error.action = action;
    throw error;
  }
}

async function assertWalletGramAtLeast(requiredNanotons, action) {
  const required = nonNegativeBigInt(requiredNanotons);
  if (required <= 0n) return;
  const balance = await loadConnectedTonWalletBalance().catch(() => null);
  if (balance === null) return;   // fail-open: unreadable balance must not block a funded wallet
  if (nonNegativeBigInt(balance) < required) {
    const error = new Error(t('errors.walletNeedsGram', { amount: formatTonNanotons(required) }));
    error.code = 'PLATHO_WALLET_GRAM_REQUIRED';
    error.action = action;   // diagnostic only — see assertConnectedAthAtLeast
    throw error;
  }
}

async function loadConnectedAthWalletBalance() {
  const athWalletAddress = await loadConnectedAthWalletAddress();
  const provider = createAthWalletTonRpcProvider({ athWalletAddress });
  try {
    const data = await withVaultReadLock(() => provider.getWalletData({ address: athWalletAddress }));
    return nonNegativeBigInt(data.balance);
  } catch (error) {
    if (isAthWalletNotDeployedError(error)) return 0n;
    throw error;
  }
}

function isAthWalletNotDeployedError(error) {
  const message = String(error?.message ?? error ?? '');
  return /get-method exit code -13|cskip_no_state|no state|nonexist|Missing ATH wallet owner|Missing ATH master address/i.test(message);
}

function criticalChainReadOptions() {
  // Critical reads are dual-provider verified while verification is actually
  // possible. When every verifier transport is dead or blocked for this
  // network (for example keyless toncenter answering 403), fail-closed
  // verification would freeze the whole messenger, so reads degrade to the
  // single live provider; entry/key payloads stay hash-bound to local
  // expectations and availability wins by explicit product policy.
  if (tonRpcVerificationStructurallyDegraded()) return unverifiedCriticalChainReadOptions();
  return { verify: true, priority: 'critical', cacheTtlMs: 0, queueTimeoutMs: CRITICAL_CHAIN_READ_QUEUE_TIMEOUT_MS };
}

async function refreshWalletTonBalanceForProfile() {
  if (!plathoWallet?.address) {
    vaultPocketState = {
      wallet: { ton_balance: null, ath_balance: vaultPocketState.wallet?.ath_balance ?? null },
    };
    refreshVaultMoveWidget();
    return null;
  }
  const balance = await loadConnectedTonWalletBalance();
  if (balance === null) {
    // Transient failed read (loadConnectedTonWalletBalance returns null on total failure, it does not throw): do NOT
    // wipe a known balance to "-" and do NOT give up — keep last-known and re-read on a short backoff so the profile
    // eventually shows the balance instead of stranding on a dash until the user leaves and returns.
    scheduleWalletTonProfileBalanceRetry();
    refreshVaultMoveWidget();
    return vaultPocketState.wallet?.ton_balance ?? null;
  }
  clearWalletTonProfileBalanceRetry();
  vaultPocketState = {
    wallet: {
      ton_balance: balance,
      ath_balance: vaultPocketState.wallet?.ath_balance ?? null,
    },
  };
  // The headline card is now the ONLY place this number is rendered, and it is fed by refreshNavVaultBalance. Leaving
  // the old profile-status call here would have updated vaultPocketState and shown nothing.
  refreshVaultMoveWidget();
  return balance;
}

// Bounded, view-gated retry for the profile external-GRAM balance. loadConnectedTonWalletBalance resolves null on a
// failed read (never throws), so without this a single transient failure left the profile on "-" forever. Held under
// the shared read mutex (loadConnectedTonWalletBalance -> withVaultReadLock), so a retry never overlaps a get_user
// on iOS. Stops on success (clear), on leaving the Profile tab, or on a wallet change (clearWalletScopedRuntimeState).
let walletTonProfileBalanceRetryTimer = null;
let walletTonProfileBalanceRetryAttempt = 0;
const WALLET_TON_PROFILE_BALANCE_RETRY_DELAYS_MS = [1500, 3000, 6000, 12000];

function isProfileViewActive() {
  return appShell?.dataset?.view === 'profile';
}

function clearWalletTonProfileBalanceRetry() {
  if (walletTonProfileBalanceRetryTimer) {
    clearTimeout(walletTonProfileBalanceRetryTimer);
    walletTonProfileBalanceRetryTimer = null;
  }
  walletTonProfileBalanceRetryAttempt = 0;
}

function scheduleWalletTonProfileBalanceRetry() {
  if (walletTonProfileBalanceRetryTimer) return; // one already armed
  const attempt = Math.min(walletTonProfileBalanceRetryAttempt, WALLET_TON_PROFILE_BALANCE_RETRY_DELAYS_MS.length - 1);
  walletTonProfileBalanceRetryAttempt += 1;
  walletTonProfileBalanceRetryTimer = setTimeout(() => {
    walletTonProfileBalanceRetryTimer = null;
    // Stop chasing the balance if the wallet went away or the user left the Profile tab.
    if (!plathoWallet?.address || !isProfileViewActive()) return;
    refreshWalletTonBalanceForProfile().catch((error) => { if (!noteTonRpcRateLimit(error)) console.error(error); });
  }, WALLET_TON_PROFILE_BALANCE_RETRY_DELAYS_MS[attempt]);
}

function resetVaultPocketState() {
  vaultPocketState = {
    wallet: { ton_balance: null, ath_balance: null },
  };
  markNavVaultBalanceIdle();
  refreshVaultMoveWidget();
}

// The nav-corner balance. Under clean-17 direct-pay the money IS the wallet balance — there is no custodial Vault
// pocket to read, so this refreshes the external GRAM + ATH balances of the connected wallet. (The cutover gate that
// used to sit here skipped the Vault get_user and returned null, which left the corner permanently `is-pending`: the
// only writers of a "known" balance were the three Vault-pocket paths, and every one of them was behind that gate.)
async function refreshVaultNavBalanceInBackground(options = {}) {
  if (!plathoWallet?.address) {
    delete globalThis.plathoVaultBinding;
    resetVaultPocketState();
    return null;
  }
  if (navVaultBalanceRefreshPromise) return navVaultBalanceRefreshPromise;
  // iOS WebKit/JSC HARD-FREEZES the run loop on 2+ CONCURRENT app-level chain-read CALLS (the documented
  // v509/v515/v516 class — force-reload required). Both balance reads below therefore run STRICTLY one at a time,
  // and this single-flight promise keeps overlapping refreshes (auto-refresh + post-transaction + retry) from
  // stacking a second pair on top.
  markNavVaultBalancePending(options.fromRetry ? 'retrying' : 'refreshing');
  navVaultBalanceRefreshPromise = (async () => {
    const forWalletRaw = rawWalletAddress(plathoWallet.address);
    // GRAM first, then ATH — never concurrently. loadConnectedTonWalletBalance resolves null on a failed read (it
    // does not throw); loadConnectedAthWalletBalance maps "jetton wallet not deployed" to 0n and throws only on a
    // genuinely unknown balance, so its failure is caught here and treated as unknown rather than as zero.
    const ton = await loadConnectedTonWalletBalance();
    const ath = await loadConnectedAthWalletBalance().catch(() => null);
    // The wallet may have switched while these reads were in flight: a stale cross-wallet balance must never be
    // rendered as the new wallet's (the wallet-change refresh reads the new wallet itself).
    if (!plathoWallet?.address || rawWalletAddress(plathoWallet.address) !== forWalletRaw) return null;
    if (ton === null && ath === null) {
      markNavVaultBalanceRetryNeeded('balance unavailable');
      return null;
    }
    // Carry forward last-known on a partial failure instead of wiping to "-": a momentary null must not flicker a
    // known balance to a dash. A real zero balance is a bigint (0n) and is preserved.
    vaultPocketState = {
      wallet: {
        ton_balance: ton ?? vaultPocketState.wallet?.ton_balance ?? null,
        ath_balance: ath ?? vaultPocketState.wallet?.ath_balance ?? null,
      },
    };
    refreshVaultMoveWidget();
    markNavVaultBalanceReady();
    refreshComposerCostStatus();
    return vaultPocketState.wallet;
  })();
  try {
    return await navVaultBalanceRefreshPromise;
  } finally {
    navVaultBalanceRefreshPromise = null;
  }
}

function walletFormattedBalance(asset) {
  const balance = (asset === 'ATH'
    ? vaultPocketState.wallet?.ath_balance
    : vaultPocketState.wallet?.ton_balance) ?? 0n;
  return asset === 'ATH'
    ? formatAthAtomic(balance)
    : formatTonNanotons(balance);
}

function navVaultBalanceHasKnownValue() {
  return vaultPocketState.wallet?.ton_balance !== null
    && vaultPocketState.wallet?.ton_balance !== undefined
    && vaultPocketState.wallet?.ath_balance !== null
    && vaultPocketState.wallet?.ath_balance !== undefined;
}

function refreshNavVaultBalance() {
  // The rail corner ALWAYS reserves its space (its min-height), but stays visually EMPTY until the balance is known
  // \u2014 no spinner (the global header sync indicator already signals activity) and, because the block is never
  // removed from layout, no shift of the rail buttons when the balance arrives. The moment a real balance lands we
  // fill it and fade it in (one-shot; re-armed if the value ever goes unknown again, e.g. on account switch).
  if (!navVaultBalanceHasKnownValue()) {
    for (const container of navVaultBalanceContainers) {
      container.classList.add('is-pending');
      container.classList.remove('rail-vault-balance-reveal');
      container.setAttribute('aria-hidden', 'true');
    }
    // Mobile tab bar: with no known balance the plate cell is dropped entirely, so the four tabs center
    // across the full width; the class puts the cell back the moment a balance exists (owner request —
    // no :has() per the iOS floor rule, so the state rides a JS-toggled ancestor class).
    document.querySelector('.sidebar')?.classList.remove('has-vault-balance');
    return;
  }
  document.querySelector('.sidebar')?.classList.add('has-vault-balance');
  for (const container of navVaultBalanceContainers) {
    if (container.classList.contains('is-pending')) {
      container.classList.remove('is-pending');
      // Fade-in only on the first fill, not on later background value refreshes (the gate is the is-pending class).
      container.classList.add('rail-vault-balance-reveal');
    }
    container.removeAttribute('aria-hidden');
  }
  const tonBalance = `${walletFormattedBalance('TON')} GRAM`;
  const athBalance = `${walletFormattedBalance('ATH')} ATH`;
  for (const node of navVaultTonBalances) {
    setText(node, tonBalance);
  }
  for (const node of navVaultAthBalances) {
    setText(node, athBalance);
  }
}

// clean-17 direct-pay: the deposit/withdraw move widget is gone (custody removed); this now only refreshes the
// nav-corner wallet balance, which the activation/pocket-state KEEP paths still call through here.
function refreshVaultMoveWidget() {
  refreshNavVaultBalance();
}

async function resolveAthMasterProvider() {
  const provider = globalThis.plathoAthMasterProvider
    ?? createAthMasterTonRpcProvider({ athMasterAddress: requireAthMasterAddress() });
  if (!provider?.getWalletAddress) throw new Error('ATHMaster provider is not configured');
  return provider;
}

async function refreshAthProtocolStats() {
  return await refreshAthProtocolStatsRun();
}
/**
 * The reserve seller's live state: the price step, what is left on it, and whether it can take a sale at all.
 *
 * A failed read leaves `marketStabilityState` as it was (or null on the first pass) rather than writing zeros. The
 * distinction matters at the point of sale: "sold out" and "I could not ask" look identical in a zeroed struct, and
 * only one of them should stop a buyer.
 */
async function refreshMarketStabilityState() {
  const address = PLATHO_APP_CONFIG.marketStabilitySeller?.address ?? null;
  const transport = globalThis.plathoWalletRpcTransport ?? globalThis.plathoTonRpcTransport;
  if (!address || !transport?.runGetMethod) return;
  try {
    const state = await createMarketStabilityReader((call) => transport.runGetMethod(call))(address);
    if (state.exists) marketStabilityState = state;
    renderBuyAthStatus();
  } catch (error) {
    if (!noteTonRpcRateLimit(error)) console.warn('[market] reserve seller read failed', error);
  }
}

/** A nanoton figure as a grouped GRAM string, the same shape every other money row on this screen uses. */
function formatGramNanotons(value) {
  return groupDecimalText(formatTonNanotons(value));
}

/** The seller's current price for ONE ATH, as a GRAM string. */
function marketStabilityUnitPriceLabel(state = marketStabilityState) {
  if (!state?.currentMultiplier) return null;
  return formatGramNanotons(quoteNanotonsForAth(ATH_ATOMIC_PER_UNIT, state.currentMultiplier));
}

/**
 * The row's trailing status. It carries the PRICE rather than a word, for the same reason the claim and flush rows
 * carry theirs: a control that spends money should say how much before it is pressed, not after.
 */
function renderBuyAthStatus() {
  if (!buyAthStatus) return;
  if (!marketStabilityState) {
    setText(buyAthStatus, t('profile.statusChecking'));
    return;
  }
  if (maxBuyableAtomic(marketStabilityState) <= 0n) {
    setText(buyAthStatus, t('profile.buyAthSoldOut'));
    return;
  }
  const price = marketStabilityUnitPriceLabel();
  setText(buyAthStatus, price ? t('profile.buyAthFromPrice', { price }) : t('profile.statusChecking'));
}

// [OWNER 2026-08-27] The buy dialog used to carry two more lines — "ATH is earned by writing" and the coming
// pool's launch terms — gated on the airdrop pool's remaining budget, so both would end themselves the moment
// the budget did ("prose about a phase goes stale in silence"). The budget IS spent now (measured 2026-08-26:
// remaining 0, all 15,000,000 ATH delivered), the airdrop UI is removed wholesale along with the pool/ticket
// reads that fed the gate — so the ended-phase branch is deleted rather than kept eternally false.
function buyAthFootnotes(state) {
  const lines = [t('profile.buyAthFootStep', {
    price: marketStabilityUnitPriceLabel(state) ?? '-',
    amount: formatAthAtomicGrouped(maxBuyableAtomic(state)),
  })];
  lines.push(t('profile.buyAthFootSpend'));
  return lines;
}

/**
 * Wait for the seller to be free, then buy.
 *
 * The reserve serves ONE sale at a time (gate 23211 refuses a buy while another is in flight), so a busy seller is a
 * QUEUE, not a failure — and sending into it would bounce the buyer's money back with a red row and no explanation.
 * A dust buy can hold the slot for one round trip, which is seconds. So this waits, and only gives up after the wait
 * stops being plausibly a queue.
 */
async function awaitMarketStabilityIdle(attempts = 6, delayMs = 2500) {
  for (let attempt = 0; attempt < attempts; attempt += 1) {
    await refreshMarketStabilityState();
    if (marketStabilityCanSell(marketStabilityState)) return marketStabilityState;
    if (marketStabilityState && maxBuyableAtomic(marketStabilityState) <= 0n) return null;  // sold out, not busy
    await delay(delayMs);
  }
  return null;
}

async function openBuyAthDialog() {
  if (!plathoWallet?.address) {
    setText(buyAthStatus, t('profile.buyAthWalletRequired'));
    return;
  }
  await refreshMarketStabilityState();
  const state = marketStabilityState;
  if (!state) {
    setText(buyAthStatus, t('profile.buyAthUnavailable'));
    return;
  }
  const maxAtomic = maxBuyableAtomic(state);
  if (maxAtomic <= 0n) {
    setText(buyAthStatus, t('profile.buyAthSoldOut'));
    return;
  }

  // TWO INPUTS, ONE NUMBER. Editing either recomputes the other, and the ATH side is authoritative: the message
  // carries an amount, not a payment, so a GRAM figure is only ever a way of ARRIVING at an amount.
  let amountAtomic = 0n;
  const athInput = document.createElement('input');
  const gramInput = document.createElement('input');
  const setAmount = (atomic, { skip } = {}) => {
    amountAtomic = atomic < 0n ? 0n : (atomic > maxAtomic ? maxAtomic : atomic);
    if (skip !== 'ath') athInput.value = amountAtomic === 0n ? '' : formatAthAtomic(amountAtomic);
    if (skip !== 'gram') {
      const cost = quoteNanotonsForAth(amountAtomic, state.currentMultiplier);
      gramInput.value = amountAtomic === 0n ? '' : formatTonNanotons(cost);
    }
    updateActiveActionSummary();
  };
  const parseDecimal = (text, decimals) => {
    const clean = String(text ?? '').replace(/\s| /g, '').replace(',', '.');
    if (!/^\d*(\.\d*)?$/.test(clean) || clean === '' || clean === '.') return null;
    const [whole, fraction = ''] = clean.split('.');
    const padded = fraction.slice(0, decimals).padEnd(decimals, '0');
    return BigInt(whole || '0') * (10n ** BigInt(decimals)) + BigInt(padded || '0');
  };

  // SHAPED LIKE THE WALLET HEADLINE CARDS, by request — the owner pointed at the GRAM/ATH pair at the top of the
  // Wallet tab and said that is what money should look like here. The visible label is the bare TICKER, exactly as
  // those cards do it: a ticker is not translated, so the pair reads GRAM / ATH in every locale instead of a
  // translated phrase beside an untranslated one. The full question stays as the accessible name.
  const buildField = (input, id, ticker, ariaLabel, onInput) => {
    input.type = 'text';
    input.inputMode = 'decimal';
    input.autocomplete = 'off';
    input.id = id;
    input.className = 'buy-ath-input';
    input.placeholder = '0';
    input.setAttribute('aria-label', ariaLabel);
    input.addEventListener('input', onInput);
    const wrap = document.createElement('label');
    wrap.className = 'buy-ath-card';
    const span = document.createElement('span');
    span.textContent = ticker;
    wrap.append(span, input);
    return wrap;
  };

  // ORDER, and it is the whole point of the v889 rework: the controls come FIRST. What was here before opened with
  // four paragraphs of explanation and put the inputs underneath, so the reader had to read an essay to reach the
  // thing they came for (a wall of text above the buttons, in his words). The prose lost nothing — it moved below the
  // button as footnotes, and the asterisk in the title points at it.
  const fields = [
    {
      type: 'custom',
      className: 'action-custom-field buy-ath-inputs',
      render: () => {
        const box = document.createElement('div');
        box.className = 'buy-ath-pair';
        box.append(
          buildField(athInput, 'buyAthAmountInput', 'ATH', t('profile.buyAthAmountLabel'), () => {
            const parsed = parseDecimal(athInput.value, 9);
            setAmount(parsed ?? 0n, { skip: 'ath' });
          }),
          buildField(gramInput, 'buyAthCostInput', 'GRAM', t('profile.buyAthCostLabel'), () => {
            const parsed = parseDecimal(gramInput.value, 9);
            setAmount(parsed === null ? 0n : athForNanotons(parsed, state.currentMultiplier), { skip: 'gram' });
          }),
        );
        return box;
      },
    },
  ];

  const proceed = await openActionDialog({
    title: t('profile.buyAthTitle'),
    hint: '',
    submitLabel: t('profile.buyAthSubmit'),
    fields,
    footnotes: () => buyAthFootnotes(state),
    summary: () => [
      { label: t('profile.buyAthSummaryAmount'), value: formatAthProfileAmount(amountAtomic) },
      { label: t('profile.buyAthSummaryPrice'), value: `${formatGramNanotons(quoteNanotonsForAth(amountAtomic, state.currentMultiplier))} GRAM` },
      // Named because it is real money leaving the wallet for one hop; whatever is not needed comes back, which is
      // the contract's own behaviour and the reason over-providing is safe.
      { label: t('profile.buyAthSummaryFee'), value: `${formatGramNanotons(MARKET_STABILITY_BUY_OVERHEAD)} GRAM` },
      // The balance belongs next to the price: "can I afford this" is the question the summary is being read for.
      { label: t('profile.buyAthSummaryBalance'), value: `${formatGramNanotons(nonNegativeBigInt(vaultPocketState.wallet?.ton_balance ?? 0n))} GRAM` },
    ],
    validateSubmit: async () => {
      if (amountAtomic <= 0n) return { ok: false, error: t('profile.buyAthEnterAmount') };
      const total = buyValueNanotons(amountAtomic, state.currentMultiplier);
      try {
        await assertWalletGramAtLeast(total + walletSendFeeReserveNanotons(), 'buy');
      } catch {
        return { ok: false, error: t('profile.buyAthLowBalance', { amount: formatGramNanotons(total) }) };
      }
      return { ok: true };
    },
  });
  if (!proceed || amountAtomic <= 0n) return;
  await submitBuyAth(amountAtomic);
}

async function submitBuyAth(amountAtomic) {
  if (marketStabilityBuyInFlight) return;
  marketStabilityBuyInFlight = true;
  if (buyAthButton) buyAthButton.disabled = true;
  setText(buyAthStatus, t('profile.buyAthSending'));
  try {
    const ready = await awaitMarketStabilityIdle();
    if (!ready) {
      setText(buyAthStatus, t('profile.buyAthBusy'));
      return;
    }
    const transport = globalThis.plathoWalletRpcTransport ?? globalThis.plathoTonRpcTransport;
    await publishMarketStabilityBuy({
      wallet: plathoWallet,
      transport,
      sellerAddress: PLATHO_APP_CONFIG.marketStabilitySeller.address,
      recipient: plathoWallet.address,
      amountAtomic,
      multiplier: ready.currentMultiplier,
      lastTerminalQueryId: ready.lastTerminalQueryId,
    });
    setText(buyAthStatus, t('profile.buyAthSent'));
    // The ATH lands when the seller forwards it, a hop later — re-read rather than claim a balance.
    //
    // [OWNER 2026-08-13] "bought it, and nothing updated in the balance." The claim lane was cured of exactly this on
    // 2026-08-03 and the BUY lane kept its own one-shot: a single 8s call to refreshAthProtocolStats, which reads
    // PROTOCOL figures (supply, multiplier) and never touches the wallet's ATH balance — the number the user is
    // actually watching is fed by refreshVaultNavBalanceInBackground. So the balance waited for a background tick
    // that could be three minutes away. Both lanes now queue the same ladder.
    queueAthPostTransactionRefresh();
  } catch (error) {
    if (!noteTonRpcRateLimit(error)) console.warn('[market] buy failed', error);
    setText(buyAthStatus, t('profile.buyAthFailed'));
  } finally {
    marketStabilityBuyInFlight = false;
    if (buyAthButton) buyAthButton.disabled = false;
  }
}

async function refreshAthProtocolStatsRun() {
  renderAthProfileStats();
  // Serialize the ATH-stats reads, one at a time. Reads that overlap are the iOS run-loop-stall pattern (v509).
  try {
    const provider = await resolveAthMasterProvider();
    if (!provider?.getJettonData) return athProtocolState;
    const data = await withVaultReadLock(() => provider.getJettonData({ address: requireAthMasterAddress() }));
    athProtocolState = {
      total_supply: data?.total_supply === null || data?.total_supply === undefined
        ? null
        : nonNegativeBigInt(data.total_supply),
    };
    await refreshMarketStabilityState();
    renderAthProfileStats();
    return athProtocolState;
  } catch (error) {
    noteTonRpcRateLimit(error);
    return athProtocolState;
  }
}

function queueAthPostTransactionRefresh() {
  // [OWNER 2026-08-03] Claimed 100 ATH and the balance did not appear for a long time. The ticket stats were re-read
  // on this schedule, but the ATH BALANCE CARD is fed by a DIFFERENT path (refreshVaultNavBalanceInBackground), which
  // nobody told about the claim — so the number the user was actually watching waited for the next background tick.
  // Refresh BOTH, and start at 2s rather than 5s: post-April TON settles a transaction in well under a second.
  const tick = () => {
    refreshAthProtocolStats().catch(() => {});
    refreshVaultNavBalanceInBackground().catch(() => {});
  };
  tick();
  for (const delayMs of ATH_POST_TRANSACTION_REFRESH_DELAYS_MS) setTimeout(tick, delayMs);
}

function isVaultViewActive() {
  return appShell?.dataset?.view === 'wallet';
}

function clearVaultAutoRefreshTimer() {
  if (!vaultAutoRefreshTimer) return;
  clearTimeout(vaultAutoRefreshTimer);
  vaultAutoRefreshTimer = null;
}

function scheduleVaultAutoRefresh(delayMs = VAULT_AUTO_REFRESH_MS) {
  clearVaultAutoRefreshTimer();
  if (document.hidden || !plathoWallet?.address) return;
  const effectiveDelayMs = delayMs === VAULT_AUTO_REFRESH_MS && !isVaultViewActive()
    ? VAULT_NAV_BACKGROUND_REFRESH_MS
    : delayMs;
  vaultAutoRefreshTimer = setTimeout(() => {
    vaultAutoRefreshTimer = null;
    if (isVaultViewActive()) {
      refreshVaultNow({ includeActivation: false }).catch((error) => {
        const rateLimited = noteTonRpcRateLimit(error);
        setVaultStatus(rateLimited ? 'RPC busy, retrying' : 'sync blocked');
        if (!isExpectedVaultProviderUnavailable(error)) console.error(error);
      });
      return;
    }
    refreshVaultNavBalanceInBackground()
      .catch((error) => {
        const rateLimited = noteTonRpcRateLimit(error);
        if (!rateLimited && !isExpectedVaultProviderUnavailable(error)) console.error(error);
      })
      .finally(() => scheduleVaultAutoRefresh());
  }, effectiveDelayMs);
}

async function refreshVaultNow({ includeActivation = false, includeStats = false } = {}) {
  if (vaultRefreshPromise) {
    // WHAT THE RUNNING REFRESH WAS ASKED FOR. This is single-flight, and it used to hand a late caller the running
    // promise regardless of what that refresh covered — a "read activation too" request arriving while a balance-
    // only refresh ran got the balance-only promise back, and its activation read simply never happened. Now the
    // late caller TOPS UP: it waits for the running refresh, then runs ONLY the jobs it did not cover
    // (PWA-ACTIVATION-04). Nothing overlaps — the running refresh keeps the lock; the delay(0) hop is its release
    // (`finally` below clears the lock a microtask after the work settles; a same-tick follow-up would still see
    // the stale lock and be handed the old promise again).
    const running = vaultRefreshInFlightFlags ?? { includeActivation: false, includeStats: false };
    const missingActivation = includeActivation && !running.includeActivation;
    const missingStats = includeStats && !running.includeStats;
    if (!missingActivation && !missingStats) return vaultRefreshPromise;
    return vaultRefreshPromise
      .catch(() => null)
      .then(() => delay(0))
      .then(() => refreshVaultNow({ includeActivation: missingActivation, includeStats: missingStats }));
  }
  vaultRefreshInFlightFlags = { includeActivation, includeStats };
  const vaultWork = (async () => {
    const results = [];
    // clean-17 direct-pay: the custodial dashboard read (Vault get_user + get_global) is gone. What the tab shows is
    // the WALLET balance, so the balance refresh takes its place as the first job.
    results.push(...await Promise.allSettled([refreshVaultNavBalanceInBackground()]));
    // Run the remaining jobs SEQUENTIALLY (one at a time), not concurrently: on iOS WebKit, activation +
    // ATH-stats firing together (and each fanning out) is the run-loop-stall pattern fixed for the Vault in
    // v509. Build thunks so each job is INVOKED only when the previous has settled.
    const jobThunks = [];
    if (includeActivation) jobThunks.push(() => refreshVaultActivationStatus());
    if (includeStats) jobThunks.push(() => refreshAthProtocolStats());
    for (const job of jobThunks) {
      results.push(...await Promise.allSettled([job()]));
    }
    const rejected = results.find((result) => result.status === 'rejected');
    if (rejected) throw rejected.reason;
  })();
  vaultWork.catch(() => {});
  vaultRefreshPromise = vaultWork;
  const vaultRefreshTimedOut = Symbol('vault-refresh-deadline');
  try {
    const outcome = await Promise.race([
      vaultWork,
      delay(VAULT_REFRESH_DEADLINE_MS).then(() => vaultRefreshTimedOut),
    ]);
    if (outcome === vaultRefreshTimedOut) {
      // Degraded RPC: the inner read/render work blew past the deadline. Stop blocking the caller and the
      // single-flight lock; surface a retry. The inner work keeps running and renders late if it settles.
      setVaultStatus('RPC busy, retrying');
      return null;
    }
    return outcome;
  } finally {
    vaultRefreshPromise = null;
    vaultRefreshInFlightFlags = null;
    scheduleVaultAutoRefresh();
  }
}

function queueVaultPostTransactionRefresh(options = {}) {
  // Account activation (RegisterMessagingKeys) only settles on-chain a few seconds
  // to ~a minute after the external is sent — longer when the verifier is rate-
  // limited. The immediate refresh below almost always runs BEFORE the Vault has
  // created the user, so current_key_id is still 0. When the caller is waiting on
  // activation, the delayed refreshes must KEEP re-reading activation until it
  // confirms (pollActivation); otherwise the button stays on "Activate" even after
  // the account activated, and only a second manual press would catch it up.
  const pollActivation = options.pollActivation === true;
  markNavVaultBalancePending('transaction submitted', {
    resetRetry: true,
    retry: true,
    retryDelayMs: 2_000,
  });
  refreshVaultNow({ includeActivation: true }).catch((error) => {
    if (noteTonRpcRateLimit(error)) setVaultStatus('RPC busy, retrying');
    if (!isExpectedVaultProviderUnavailable(error)) console.error(error);
  });
  const delays = pollActivation
    ? [...VAULT_POST_TRANSACTION_REFRESH_DELAYS_MS, 90_000]
    : VAULT_POST_TRANSACTION_REFRESH_DELAYS_MS;
  for (const delayMs of delays) {
    setTimeout(() => {
      if (!plathoWallet?.address) return;
      refreshVaultNow({ includeActivation: pollActivation }).catch((error) => {
        if (noteTonRpcRateLimit(error)) setVaultStatus('RPC busy, retrying');
        if (!isExpectedVaultProviderUnavailable(error)) console.error(error);
      });
    }, delayMs);
  }
  if (pollActivation) {
    // Safety release: if activation never settles within the poll horizon (dropped
    // external, failed compute, abandoned tab), drop the in-flight lock so the row
    // returns to a clickable "Activate" state for a retry instead of spinning forever.
    const releaseDelayMs = Math.max(...delays) + 5_000;
    setTimeout(() => {
      if (plathoAccountActivationPending && !hasActivePlathoAccount()) {
        plathoAccountActivationPending = false;
        forgetPlathoActivationInFlight();   // one release, both markers — a stale write must not outlive the poll
        refreshMessagingControls();
      }
    }, releaseDelayMs);
  }
}

function queueVaultRefreshAfterWalletChange() {
  // A pending activation belongs to the previous wallet; never carry the in-flight
  // lock across a wallet switch (the new wallet's activation state is read fresh).
  plathoAccountActivationPending = false;
  // The WRITTEN marker is deliberately left alone: it names the wallet that sent the external, so it cannot bleed
  // onto the new one, and switching back inside the horizon must still find its activation protected.
  markNavVaultBalancePending('wallet changed', {
    resetRetry: true,
    retry: true,
    retryDelayMs: 0,
  });
  refreshVaultNow({ includeActivation: true, includeStats: true }).catch((error) => {
    if (noteTonRpcRateLimit(error)) setVaultStatus('RPC busy, retrying');
    if (!isExpectedVaultProviderUnavailable(error)) console.error(error);
  });
  // RESUME THE KNOCKING. This runs on every wallet load, which includes a fresh start of the app — so an external
  // whose tab the phone suspended is picked up here and finished, instead of waiting for someone to notice the
  // account never activated and press the button again. Costs nothing when there is nothing owed:
  // plathoActivationPendingBoc is null unless THIS wallet has an unexpired external on record.
  if (plathoActivationPendingBoc()) forcePlathoActivationDelivery();
}

async function resolveUsernameRegistryProvider() {
  const provider = globalThis.plathoUsernameRegistryProvider
    ?? createUsernameRegistryTonRpcProvider({ usernameRegistryAddress: requireUsernameRegistryAddress() });
  if (
    !provider?.getUsernamePrice
    || !provider?.getUsernameItemAddress
    || !provider?.getGlobal
    || !provider?.getAthWalletAddress
  ) {
    throw new Error('UsernameRegistry provider is not configured');
  }
  return provider;
}

async function readUsernameMintPriceForOwnVaultAction(provider, registry, username) {
  const length = String(username ?? '').length;
  const price = await provider.getUsernamePrice(length, {
    address: registry,
    ...criticalChainReadOptions(),
  });
  const priceAtomic = BigInt(price?.price_ath_atomic ?? 0n);
  if (price?.valid_length !== true || priceAtomic <= 0n) {
    throw new Error('UsernameRegistry rejected this username length');
  }
  return priceAtomic;
}

// Is the name already minted? Asked of the ITEM, because since 2026-07-20 the registry keeps no name_records map
// — the per-name contract IS the record, and it is the only source that follows a TEP-62 transfer.
//
// THE HARD PART IS NOT "IS IT THERE", IT IS "DID I ACTUALLY FIND OUT". A get-method against an account that does
// not exist fails the same way a get-method fails when toncenter is having a bad minute, and the two must not be
// collapsed: reading a hiccup as "free" sends the buyer into a mint that bounces. So an error is never treated as
// an answer — we ask the ACCOUNT, which reports uninitialised as DATA rather than as a failure, exactly as
// walletAccountIsUninitialized does for a never-deployed wallet. If neither question can be answered, this
// refuses rather than guesses: being told "could not verify" costs a retry, guessing wrong costs a failed mint.
async function usernameItemIsMinted(itemAddress) {
  const itemProvider = await resolveUsernameNftItemProvider();
  try {
    const state = await itemProvider.getState({ address: itemAddress, ...criticalChainReadOptions() });
    return state?.initialized === true;
  } catch (getMethodError) {
    const transport = globalThis.plathoTonRpcTransport;
    if (typeof transport?.getAccountState === 'function') {
      try {
        const account = await transport.getAccountState({ address: itemAddress }, { skipIfRateLimited: false });
        const status = String(
          account?.state ?? account?.status ?? account?.account_state
          ?? account?.result?.state ?? account?.result?.status ?? account?.result?.account_state ?? '',
        ).trim().toLowerCase();
        // An account that has never existed is the definitive "this name is free".
        if (status === 'uninit' || status === 'uninitialized' || status === 'nonexist' || status === 'non_exist') {
          return false;
        }
        // NO `active` BRANCH, deliberately. An earlier version of this returned false here with the comment
        // "it exists but its get_state failed — that is a read problem", which contradicted itself: a read
        // problem must fall through to the refusal below, not be answered. Worse, `active` is evidence of the
        // OPPOSITE of free — with name_records deleted, the deployed per-name item IS the record that the name
        // is taken. So on a toncenter hiccup against a genuinely registered name it reported "free" and sent the
        // buyer into a mint that bounces: the exact hazard this helper exists to prevent, in its worst form,
        // because the chain had actually answered and said the item was there.
        // Falling through is also the conservative reading: `active` does not by itself prove initialized.
      } catch { /* fall through to the refusal below */ }
    }
    const error = new Error('Could not verify whether this username is taken');
    error.cause = getMethodError;
    throw error;
  }
}

async function readUsernameMintAvailabilityForOwnVaultAction(provider, registry, username) {
  if (!provider?.getUsernameItemAddress || !provider?.getPendingMint) {
    throw new Error('UsernameRegistry provider cannot verify username availability');
  }
  const readOptions = { address: registry, ...criticalChainReadOptions() };
  const nameHash = await computeUsernameNameHash(username);
  // Sequential, not Promise.all: concurrent toncenter reads stall the iOS run loop (v509 class). Pure
  // availability reads on the username-mint pre-sign path — sequential preserves the same item/pending.
  const itemAddress = await provider.getUsernameItemAddress(nameHash, readOptions);
  const minted = await usernameItemIsMinted(itemAddress);
  const pending = await provider.getPendingMint(nameHash, readOptions);
  if (minted) {
    throw new Error('Username is already registered');
  }
  if (pending?.exists === true) {
    throw new Error('Username mint is already pending');
  }
  return { nameHash, itemAddress, minted, pending };
}

// ── .ath names as property: look at them, and hand them over ────────────────────────────────────────────────────
//
// The names always were TEP-62 NFTs, and Platho always was their owner's wallet. What was missing was the button:
// until now, seeing or moving a name meant connecting the same seed to Tonkeeper — a wallet sending its user off to
// find another wallet.
//
// The LIST is the hard half, and web/username-nft-owned.mjs carries the reasoning: there is no on-chain answer to
// "what does this wallet own", so it is a local floor plus an indexer, and neither is believed — both only propose
// an address that the chain then confirms.
//
// NOTE WHAT THIS DOES NOT DO: it adds no chain read to the wallet tab's refresh. The row's status is computed from
// local storage alone and the reads happen when the dialog opens. Two getters on every refresh to render a row
// nobody had opened is exactly what the ATH-flush row cost, and it was deleted this morning for it.
let ownedUsernameNftsInFlight = false;
// ONE real read per wallet per session, behind the row's first paint (scheduleOwnedUsernameNftsSessionCheck below):
// the remembered list is only a FLOOR and the row quoted it as fact until the dialog was opened — a name transferred
// away from another wallet app kept showing as owned. Keyed by raw wallet; a rate-limited attempt is not counted.
const OWNED_USERNAME_NFTS_SESSION_CHECK_DELAY_MS = 6_000;
const ownedUsernameNftsSessionChecked = new Set();
// [OWNER 2026-08-09] The last CHAIN-VERIFIED count. Without it the row kept claiming four names straight after the
// dialog had just shown three: the row read local storage while the dialog read the chain, so the app displayed a
// number it had itself disproved seconds earlier. The dialog does the expensive work; throwing its answer away was
// the whole bug. `{ count, complete }` — an incomplete read says "3+" rather than claiming three is all there is.
let ownedUsernameNftsVerified = null;

function renderMyUsernamesStatus() {
  if (!myUsernamesButton || !myUsernamesStatus) return;
  myUsernamesButton.disabled = !plathoWallet?.address || ownedUsernameNftsInFlight;
  if (!plathoWallet?.address) {
    setProfileActionStatus(myUsernamesStatus, t('common.walletRequiredStatus'), '');
    return;
  }
  if (ownedUsernameNftsInFlight) {
    setProfileActionStatus(myUsernamesStatus, t('common.checking'), 'busy');
    return;
  }
  if (ownedUsernameNftsVerified) {
    const { count, complete } = ownedUsernameNftsVerified;
    setProfileActionStatus(myUsernamesStatus, complete
      ? (count > 0 ? tPlural('username.knownNames', count) : t('username.openList'))
      : t('username.knownNamesPartial', { count: String(count) }), '');
    return;
  }
  // Nothing verified yet this session — what the device remembers, painted NOW, and ONE real check scheduled behind
  // this first paint (once per wallet per session). The refresh itself still adds no chain read — two getters per
  // wallet refresh to render a row nobody had opened is what the ATH-flush row cost, and it was deleted for it.
  const known = readKnownPlathoUsernames().length;
  setProfileActionStatus(myUsernamesStatus, known > 0 ? tPlural('username.knownNames', known) : t('username.openList'), '');
  scheduleOwnedUsernameNftsSessionCheck();
}

// The session's one real read of the owned names (loadOwnedUsernameNfts: floor + indexer, every item chain-verified,
// memory reconciled), deferred past the post-unlock burst and serialized on the username-hygiene lane so it never runs
// beside another username resolve (the v509 iOS run-loop class). Skipped when the dialog already did the read this
// session; a rate-limited attempt re-arms on the next paint; any other failure counts (the dialog re-reads on open).
function scheduleOwnedUsernameNftsSessionCheck() {
  const owner = rawWalletAddress(plathoWallet?.address);
  if (!owner || ownedUsernameNftsSessionChecked.has(owner) || ownedUsernameNftsInFlight) return;
  ownedUsernameNftsSessionChecked.add(owner);
  setTimeout(() => {
    queueUsernameHygiene(async () => {
      if (rawWalletAddress(plathoWallet?.address) !== owner) { ownedUsernameNftsSessionChecked.delete(owner); return; }
      if (ownedUsernameNftsInFlight || ownedUsernameNftsVerified) return;
      if (tonRpcLimited()) { ownedUsernameNftsSessionChecked.delete(owner); return; }
      ownedUsernameNftsInFlight = true;
      renderMyUsernamesStatus();
      try {
        await loadOwnedUsernameNfts();
        // A rate-limited read comes back complete:false through the caught paths inside the loader, never via the
        // catch below — without this the row quoted "N+" for the whole session and the check never re-armed.
        if (ownedUsernameNftsVerified?.complete === false && tonRpcLimited()) {
          ownedUsernameNftsVerified = null;
          ownedUsernameNftsSessionChecked.delete(owner);
        }
      } catch (error) {
        if (noteTonRpcRateLimit(error)) ownedUsernameNftsSessionChecked.delete(owner);
        else console.warn('[username] owned-names session check failed', error);
      } finally {
        ownedUsernameNftsInFlight = false;
        renderMyUsernamesStatus();
      }
    });
  }, OWNED_USERNAME_NFTS_SESSION_CHECK_DELAY_MS);
}

/** Verify one item address on chain: authoritative, and owned by this wallet. */
async function verifyOwnedUsernameNft(itemAddress) {
  const registryAddress = requireUsernameRegistryAddress();
  const registryProvider = await resolveUsernameRegistryProvider();
  const itemProvider = await resolveUsernameNftItemProvider();
  return withVaultReadLock(() => resolveAuthoritativeUsernameItemOwnership({
    registryProvider,
    itemProvider,
    itemAddress,
    registryAddress,
    registryCallOptions: { address: registryAddress, ...criticalChainReadOptions() },
    itemCallOptions: { address: itemAddress, ...criticalChainReadOptions() },
  }));
}

async function loadOwnedUsernameNfts() {
  const wallet = requirePlathoWallet().address;
  const registryAddress = requireUsernameRegistryAddress();
  const registryProvider = await resolveUsernameRegistryProvider();

  // The floor: names this device already knows. Derived to item addresses locally, then confirmed like any other.
  const candidateAddresses = [];
  // A remembered name whose item address could not even be DERIVED (registry getter failed) was never checked, so the
  // read is not complete — the reconcile below must not forget a name it never asked about. A label the derivation
  // REJECTS (null: not a legal name) is different: nothing on chain can own it, it is simply not a candidate.
  // COUNTED, and handed to collectOwnedUsernameNfts as `candidateFailures`, so `complete` is decided in ONE place
  // (PWA-MYNAMES-01). The first version swallowed this throw (.catch(() => null)): the name was merely absent from a
  // read that then called itself complete, reconcileKnownPlathoUsernames forgot it, and the LINKED name "sometimes
  // dropped on unlock" — on nothing but a failed getter.
  let candidateFailures = 0;
  for (const label of readKnownPlathoUsernames()) {
    let candidate = null;
    try {
      candidate = await usernameNftCandidateFromLabel(label, {
        registryProvider,
        callOptions: { address: registryAddress, ...criticalChainReadOptions() },
      });
    } catch {
      candidateFailures += 1;
    }
    if (candidate?.itemAddress) candidateAddresses.push(candidate);
  }

  // The indexer sees what the floor cannot — a name somebody TRANSFERRED here. Its failure is reported, never
  // silently swallowed into an empty list: this list is a statement about the user's property.
  let indexerAddresses = null;
  let indexerError = null;
  try {
    indexerAddresses = await discoverUsernameNftAddresses({ ownerWallet: wallet, collectionAddress: registryAddress });
  } catch (error) {
    indexerError = error;
    console.warn('username nft discovery unavailable', error);
  }

  const result = await collectOwnedUsernameNfts({
    ownerWallet: wallet,
    candidateAddresses,
    candidateFailures,   // a name not asked about is not "not owned": folded into `complete` by the collector
    indexerAddresses,
    indexerError,
    verifyItem: verifyOwnedUsernameNft,
  });
  // RECONCILE THE MEMORY WITH THE CHAIN. The remembered list is what the row quotes before the dialog opens, so a name
  // transferred away kept showing until this very read disproved it — and then the memory was left as it was. Now the
  // read writes back: remember what was found, and forget ONLY what the chain proved transferred (result.transferred)
  // — never "whatever a complete read did not find": absence is not proof (UNFT-11 / PWA-MYNAMES-01).
  reconcileKnownPlathoUsernames(result, wallet);
  // KEEP the answer. This is the only place in the app that knows how many names the chain will vouch for, and the
  // row above it used to go on quoting local storage regardless.
  ownedUsernameNftsVerified = { count: result.owned.length, complete: result.complete };
  return result;
}

// The write-back half of loadOwnedUsernameNfts. Labels are compared canonically (".ath" stripped, lower-case) because
// the memory stores "<name>.ath" (the linked-name form) while an owned item carries the bare name. Entries still owned
// keep their stored spelling; new finds are stored in the linked-name form.
//   owned       -> added to the stored quick-pick list (complete or not: a name the chain vouches for is a fact);
//   transferred -> removed from it — the ONLY thing that removes anything. The chain read the item as authoritative
//                  under ANOTHER wallet and this side proved the label by name_hash (UNFT-11). A name merely absent
//                  from the owned list — a failed derivation, a check that threw, an indexer that answered short,
//                  even a "complete" read that did not meet it — is NOT forgotten: "not found" was never "not owned",
//                  and acting on it is what made the linked name "sometimes drop on unlock" (PWA-MYNAMES-01).
// The LINKED name is never cleared here either. If it is among the transferred, its verified_at stamp is zeroed and
// the authoritative reconcile (reconcileOwnLinkedUsername: re-verifies, falls back to another owned name, never strips
// on a degraded read) is queued — the single chokepoint that already knows how to give a name up safely.
function reconcileKnownPlathoUsernames(result, owner = plathoWallet?.address) {
  if (!result || !Array.isArray(result.owned) || !owner) return;
  const canonical = (label) => canonicalUsernameDisplay(String(label ?? '')).trim().toLowerCase();
  const found = new Set(result.owned.map((nft) => canonical(nft.label)).filter(Boolean));
  const lost = new Set((Array.isArray(result.transferred) ? result.transferred : []).map((nft) => canonical(nft.label)).filter(Boolean));
  const key = knownPlathoUsernamesStorageKey(owner);
  if (!key) return;
  let stored = [];
  try {
    const parsed = JSON.parse(localStorageOrNull()?.getItem(key) ?? '[]');
    if (Array.isArray(parsed)) stored = parsed.filter((label) => typeof label === 'string' && label.trim());
  } catch {
    stored = [];
  }
  // Forget by PROOF only (see above). One item has one owner, so a name cannot be both owned and transferred in one
  // read; should two proposals ever disagree, the chain-owned answer wins — `found` is checked first.
  const kept = stored.filter((label) => found.has(canonical(label)) || !lost.has(canonical(label)));
  const known = new Set(kept.map(canonical));
  for (const name of found) {
    if (known.has(name)) continue;
    known.add(name);
    kept.push(`${name}.ath`);
  }
  try {
    localStorageOrNull()?.setItem(key, JSON.stringify(kept.slice(0, 24)));
  } catch {
    // Cosmetic quick-pick list; safe to drop on a storage failure.
  }
  const linked = readLinkedPlathoUsername(owner);
  if (linked?.label && lost.has(canonical(linked.label)) && !found.has(canonical(linked.label))) {
    writeLinkedPlathoUsername({ ...linked, verified_at: 0 }, owner); // expire the throttle: verify, don't assume
    queueUsernameHygiene(() => reconcileOwnLinkedUsername());
  }
}

function usernameNftCardNode(nft, onTransfer) {
  const card = document.createElement('div');
  card.className = 'nft-card';
  // THE ART LEADS. It is the reason this screen exists — the names are drawn on chain by the registry itself, and a
  // list that renders them as lines of text throws away the entire point of having them.
  // A SQUARE FRAME, not a bare <img> sized by aspect-ratio. [OWNER 2026-08-22: the names list rendered as thin
  // strips on his Android/Telegram WebView.] REPRODUCED: an engine that does not honour `aspect-ratio` on an <img>
  // (Chrome < 88, the WebView many Telegram clients ship) gives the on-chain SVG — which carries a viewBox but no
  // width/height, so it has no intrinsic pixel height — a height of ZERO under `width:100%`, and the art collapses
  // to a sliver. The frame's height comes from padding-bottom:100% instead, which every engine has always honoured,
  // and the <img> fills it absolutely; nothing depends on aspect-ratio any more. [PWA-NFTART-01]
  const frame = document.createElement('div');
  frame.className = 'nft-card-art-frame';
  frame.hidden = !nft.image;
  const art = document.createElement('img');
  // A data: URI only — see safeInlineImage. Never a remote URL: img-src forbids it, and naming a host would hand
  // that host the wallet's identity.
  if (nft.image) art.src = nft.image;
  art.alt = '';
  art.className = 'nft-card-art';
  art.loading = 'lazy';
  frame.append(art);
  card.append(frame);

  const foot = document.createElement('div');
  foot.className = 'nft-card-foot';
  const name = document.createElement('strong');
  // A name is shown only when hashing it reproduced the item's own name_hash. When it did not, the item is still
  // the user's — the chain said so — but it is honestly presented by the one thing left that identifies it.
  // THAT is the only case where an address belongs on screen: for a named item it is noise nobody can act on.
  name.className = 'nft-card-name';
  name.textContent = nft.label ? `${nft.label}.ath` : shortAddress(nft.itemAddress);
  const send = document.createElement('button');
  send.type = 'button';
  send.className = 'nft-card-send';
  send.textContent = t('username.transferName');
  send.addEventListener('click', () => onTransfer(nft));
  foot.append(name, send);
  card.append(foot);
  return card;
}

async function openMyUsernamesDialog() {
  if (ownedUsernameNftsInFlight) return;
  ownedUsernameNftsInFlight = true;
  renderMyUsernamesStatus();
  let result = null;
  try {
    result = await loadOwnedUsernameNfts();
  } catch (error) {
    console.error(error);
    flashWalletIdentityStatus(t('common.syncDelayed'));
    return;
  } finally {
    ownedUsernameNftsInFlight = false;
    renderMyUsernamesStatus();
  }

  let picked = null;
  const footnotes = [];
  // An indexer that could not be asked leaves the list SHORT, and saying so is not a nicety: an incomplete list of
  // somebody's property that presents itself as complete is the one failure this whole lane is shaped to avoid.
  if (!result.complete) footnotes.push(t('username.listMayBeIncomplete'));
  await openActionDialog({
    title: t('username.myNames'),
    hint: result.owned.length === 0 ? t('username.noNamesFound') : '',
    submitLabel: t('common.close'),
    footnotes,
    fields: [{
      type: 'custom',
      className: 'nft-card-list',
      render: () => {
        const box = document.createDocumentFragment();
        for (const nft of result.owned) {
          box.append(usernameNftCardNode(nft, (chosen) => { picked = chosen; closeActionDialog(null); }));
        }
        return box;
      },
    }],
  });
  if (picked) await openUsernameNftTransferDialog(picked);
}

async function openUsernameNftTransferDialog(nft) {
  const displayName = nft.label ? `${nft.label}.ath` : shortAddress(nft.itemAddress);
  const values = await openActionDialog({
    title: t('username.transferNameTitle', { name: displayName }),
    hint: t('username.transferIrreversible'),
    tone: 'warning',
    submitLabel: t('username.transferName'),
    fields: [{
      type: 'text',
      id: 'usernameTransferRecipient',
      name: 'recipient',
      label: t('username.recipientWallet'),
      placeholder: 'UQ…',
      required: true,
    }],
    footnotes: [
      t('username.transferCostNote', { amount: formatTonNanotons(USERNAME_NFT_TRANSFER_VALUE_NANOTONS) }),
      t('username.transferLosesName'),
    ],
    validateSubmit: async (submitted) => {
      const recipient = String(submitted?.recipient ?? '').trim();
      try {
        // Refused HERE rather than by a bounce: the item rejects a non-basechain owner at 18032, and a typo that
        // costs a round trip and returns an opcode number is not an answer anybody can act on.
        buildUsernameNftTransferBody({ queryId: 1n, newOwner: recipient, responseDestination: plathoWallet.address });
      } catch {
        return { ok: false, error: t('username.recipientInvalid') };
      }
      if (parseTonAddress(recipient).raw === parseTonAddress(plathoWallet.address).raw) {
        return { ok: false, error: t('username.recipientIsSelf') };
      }
      // [OWNER 2026-08-09] THE SEND HAPPENS HERE, not after the dialog closes. It used to run afterwards, so the
      // window vanished the instant the button was pressed and the only feedback was a flash on a row the user was
      // not looking at — the owner's report was, in short, "did it send or not, no idea". Inside validateSubmit the
      // dialog stays open showing the checking hint, a failure is stated in place instead of behind a closed
      // window, and the close itself becomes the signal that the external is away.
      try {
        await submitUsernameNftTransfer(nft, recipient);
      } catch (error) {
        console.error(error);
        return {
          ok: false,
          error: error?.code === 'PLATHO_WALLET_GRAM_REQUIRED'
            ? t('common.needsWalletGram')
            : t('username.transferFailed'),
        };
      }
      return { ok: true, result: { recipient } };
    },
  });
  if (!values?.recipient) return;
  // Said plainly, in its own words, because "the window closed" is not an answer to "did it go?". The chain still
  // has to include it — hence "sent", not "transferred".
  await openActionDialog({
    title: t('username.transferSubmittedTitle'),
    hint: t('username.transferSubmittedHint', { name: displayName, recipient: shortAddress(values.recipient) }),
    submitLabel: t('common.close'),
    fields: [],
  });
}

async function submitUsernameNftTransfer(nft, recipient) {
  requireNoPendingServiceWorkerAppShellReload();
  const wallet = requirePlathoWallet();
  // THROWS on failure, deliberately. The caller runs this inside the dialog's validateSubmit, which turns a throw
  // into a sentence shown in the still-open window; swallowing it here would put the failure behind a window that
  // had already closed, which is exactly what made a transfer indistinguishable from a success.
  const body = buildUsernameNftTransferBody({
    queryId: nextUsernameNftTransferQueryId(),
    newOwner: recipient,
    // The change comes back here rather than settling into the item's balance.
    responseDestination: wallet.address,
  });
  await sendPlathoWalletTransaction(wallet, createWalletTransaction([{
    address: nft.itemAddress,
    amount: USERNAME_NFT_TRANSFER_VALUE_NANOTONS.toString(),
    payload: tonCell.bytesToBase64(serializeBoc(body)),
    // A refused transfer must return the money, not burn it.
    bounce: true,
  }]));
  // GIVING A NAME AWAY MEANS LOSING IT, and the local link has to go with it. Without this the client keeps
  // stamping a name it no longer owns onto everything it sends — recipients re-verify and reject, so it is not a
  // security hole, but it is the app lying to its own user about who they are. (This is the FM-4 note from the
  // v564 transfer audit, closed here because there is finally a place in the app where a name is handed over.)
  if (nft.label && readLinkedPlathoUsername()?.label === nft.label) clearLinkedPlathoUsername();
  removeKnownPlathoUsername(nft.label);
  // The cached chain count is now WRONG by one and must not be quoted as fact. Dropping it rather than decrementing
  // it: the truth is one chain read away and the local floor covers the gap until the list is opened again.
  ownedUsernameNftsVerified = null;
  renderMyUsernamesStatus();
  renderWalletIdentity();
}

myUsernamesButton?.addEventListener('click', () => { openMyUsernamesDialog().catch((error) => console.error(error)); });

async function resolveUsernameNftItemProvider() {
  const provider = globalThis.plathoUsernameNftItemProvider
    ?? createUsernameNftItemTonRpcProvider({});
  if (!provider?.getState) {
    throw new Error('UsernameNFTItem provider is not configured');
  }
  return provider;
}

// Thrown when a .ath name is DEFINITIVELY unregistered (as opposed to a transient RPC failure). Callers that
// address a username can distinguish "no such username" (hard error — don't create a dialog) from "couldn't
// reach the chain" (transient — fall back) via `instanceof`.
class UsernameNotRegisteredError extends Error {}

async function resolvePlathoUsernameOwner(label) {
  const username = normalizeUsernameInput(label);
  const displayLabel = `${username}.ath`;
  const registryAddress = requireUsernameRegistryAddress();
  const registryProvider = await resolveUsernameRegistryProvider();
  if (!registryProvider?.getUsernameItemAddress) {
    throw new Error('UsernameRegistry provider cannot resolve .ath names');
  }
  // The registry's name_records map is gone (2026-07-20). It was never the right source anyway: it recorded the
  // MINTER and a TEP-62 transfer left it stale, so this function already went to the item for the real owner and
  // used the record only to learn the item's address. That address is a pure function of the name, so we ask for
  // the derivation and drop the record entirely — one RPC round trip fewer, and no stale copy in the path.
  const nameHash = await computeUsernameNameHash(displayLabel);
  const itemAddress = await registryProvider.getUsernameItemAddress(nameHash, {
    address: registryAddress,
    ...criticalChainReadOptions(),
  });

  const itemProvider = await resolveUsernameNftItemProvider();
  const proof = await resolveAuthoritativeUsernameItemOwnership({
    registryProvider,
    itemProvider,
    itemAddress,
    registryAddress,
    registryCallOptions: { address: registryAddress, ...criticalChainReadOptions() },
    itemCallOptions: { address: itemAddress, ...criticalChainReadOptions() },
  });
  // "Not registered" is now the item saying it was never initialised, which is the same fact the map used to
  // carry — and it must stay a DISTINCT error from a failed read, because callers branch on it to decide whether
  // to refuse a dialog outright or fall back and retry.
  if (proof.reason === 'item_not_initialized') {
    throw new UsernameNotRegisteredError(`${displayLabel} is not registered`);
  }
  if (proof.authoritative !== true || !proof.owner_wallet) {
    throw new Error(`${displayLabel} ownership is not authoritative`);
  }
  return {
    label: displayLabel,
    ownerWallet: requireBasechainAddress(proof.owner_wallet, `${displayLabel} owner`),
    itemAddress,
    proof,
  };
}

async function waitForPlathoUsernameOwnership(label, ownerWallet, options = {}) {
  const expectedOwner = requireBasechainAddress(ownerWallet, 'Expected username owner');
  const attempts = Math.max(1, Number(options.attempts ?? USERNAME_MINT_CONFIRM_ATTEMPTS));
  const delayMs = Math.max(250, Number(options.delayMs ?? USERNAME_MINT_CONFIRM_DELAY_MS));
  let lastError = null;
  for (let attempt = 0; attempt < attempts; attempt += 1) {
    try {
      const identity = await resolvePlathoUsernameOwner(label);
      if (sameWalletAddress(identity.ownerWallet, expectedOwner)) return identity;
      throw new Error(`${identity.label} belongs to another wallet`);
    } catch (error) {
      lastError = error;
      await delay(delayMs);
    }
  }
  throw lastError ?? new Error('Username mint is not visible on-chain yet');
}

async function autoLinkMintedUsername(username, ownerWallet, options = {}) {
  const owner = requireBasechainAddress(ownerWallet, 'Connected wallet');
  setUsernameMintStatus(t('username.finalizing', { username }));
  const identity = await waitForPlathoUsernameOwnership(username, owner, options);
  if (!plathoWallet?.address || !sameWalletAddress(plathoWallet.address, owner)) return null;
  const linked = {
    mode: WALLET_DISPLAY_MODES.PLATHO_NFT,
    label: identity.label,
    verified_at: Date.now(),
  };
  writeLinkedPlathoUsername(linked, owner);
  addKnownPlathoUsername(identity.label, owner);
  writeWalletDisplayIdentity(linked, owner);
  if (walletDisplayModeSelect) walletDisplayModeSelect.value = WALLET_DISPLAY_MODES.PLATHO_NFT;
  clearPendingUsernameMint(username, owner);
  setUsernameMintStatus(t('username.linked', { name: canonicalUsernameDisplay(identity.label) }), '');
  renderWalletIdentity();
  return linked;
}

async function resolveTonDnsProvider() {
  const providerConfig = appConfig.tonDns?.provider ?? {};
  if (providerConfig.globalName && globalThis[providerConfig.globalName]) {
    return globalThis[providerConfig.globalName];
  }
  if (providerConfig.moduleUrl) {
    if (!tonDnsProviderLoadPromise) {
      const moduleUrl = new URL(providerConfig.moduleUrl, window.location.href).href;
      tonDnsProviderLoadPromise = import(moduleUrl).then((module) => {
        const exportName = providerConfig.exportName ?? 'default';
        return module[exportName] ?? module.default ?? module.provider;
      });
    }
    return tonDnsProviderLoadPromise;
  }
  return createTonDnsProvider({
    rootAddress: appConfig.tonDns?.rootAddress ?? null,
  });
}

// The owner's ATH jetton-wallet address is a deterministic function of (owner, ATHMaster) — it never
// changes — so it was wasteful to re-read get_wallet_address on every Vault refresh cycle (one of the ~5
// reads in the Vault-open burst). Cache it in memory after the first resolve.
async function loadConnectedAthWalletAddress() {
  const owner = requirePlathoWalletAddress();
  requireBasechainAddress(owner, 'Connected wallet');
  requireBasechainAddress(requireAthMasterAddress(), 'ATHMaster');
  const provider = await resolveAthMasterProvider();
  const walletAddress = await withVaultReadLock(() => provider.getWalletAddress(owner, {
    address: requireAthMasterAddress(),
    ...criticalChainReadOptions(),
  }));
  return requireBasechainAddress(walletAddress, 'Connected ATH wallet');
}

async function resolveRecipientWalletForThread(thread) {
  const variants = threadIdentityVariants(thread);
  // The dialog's WALLET is canonical for routing. A .ath username is a movable display alias whose ownership is
  // reconciled at ADDRESSING time (new-chat resolves it to the current owner and keys the dialog by that wallet)
  // and lazily on dialog OPEN — NOT re-resolved on the hot send path. So use the stored wallet variant first
  // (zero chain read); resolve a username/DNS only as a FALLBACK for a username-only dialog that has no wallet
  // variant yet (e.g. first contact before any send). [Reverts the v562 FM-1 band-aid, which made the username
  // win over the wallet — wrong layer: it could route a wallet-A dialog to B just because it still carried the
  // alias. Old-owner dialogs are now stripped+relabelled instead; see reconcileUsernameOwnership.]
  const walletIdentity = variants.find((identity) => identity.type === 'wallet_address');
  if (walletIdentity) return requireBasechainAddress(walletIdentity.value, 'Payment recipient');

  const plathoIdentity = variants.find((identity) => identity.type === 'platho_nft');
  if (plathoIdentity) {
    const resolved = await resolvePlathoUsernameOwner(plathoIdentity.value);
    return requireBasechainAddress(resolved.ownerWallet, 'Payment recipient');
  }

  const tonDnsIdentity = variants.find((identity) => identity.type === 'ton_dns');
  if (tonDnsIdentity) {
    const provider = await resolveTonDnsProvider();
    if (!provider?.resolveWallet) throw new Error('TON DNS provider is not configured');
    const walletAddress = await provider.resolveWallet(tonDnsIdentity.value, {
      rootAddress: appConfig.tonDns?.rootAddress ?? null,
      ...criticalChainReadOptions(),
    });
    return requireBasechainAddress(walletAddress, 'Payment recipient');
  }

  throw new Error('Recipient wallet route is not available');
}

// clean-17 direct-pay username mint values (proven by tests/username-registry-ath-wallet-integration.test.ts). The mint
// deploys a UsernameNFTItem, so it needs far more than an avatar pointer write: the registry retains ~0.91 TON (100-year
// item endowment). notify carries that downstream; the request is notify + forwarding fees; the ATH wallet refunds every
// excess nanoton (refund_owner_excess), so an ample request is free.
// [MOVED 2026-07-30, class sweep 2] These now come from pwa-contract-transactions.mjs, which is also what the fee
// ESTIMATOR reads. They used to be local literals here while the estimator used a separate Vault-era constant, so the
// figure shown before signing and the figure actually signed were different numbers with no connection.
const USERNAME_MINT_DIRECT_NOTIFY_VALUE = USERNAME_MINT_DIRECT_NOTIFY_VALUE_NANOTONS;
const USERNAME_MINT_DIRECT_REQUEST_VALUE = USERNAME_MINT_DIRECT_REQUEST_VALUE_NANOTONS;

// clean-17 DIRECT-PAY username mint: the user's OWN ATH jetton wallet pays the UsernameRegistry directly — the registry
// is Vault-INDEPENDENT by design (UsernameRegistry.tact:588), authenticated by the official ATH wallet's transfer
// notification. The byte-exact ATHTransferRequestRegistryMintUsername (KSG-style) is pinned in pwa-contract-transactions.
async function submitUsernameMintDirect(username) {
  const owner = requireBasechainAddress(requirePlathoWalletAddress(), 'Connected wallet');
  const registry = requireBasechainAddress(requireUsernameRegistryAddress(), 'UsernameRegistry');
  const provider = await resolveUsernameRegistryProvider();
  const priceAtomic = await readUsernameMintPriceForOwnVaultAction(provider, registry, username);   // registry read (Vault-independent)
  setUsernameMintStatus(t('username.checkingAvailability'));
  await readUsernameMintAvailabilityForOwnVaultAction(provider, registry, username);
  assertNoPendingUsernameMintRetry(username, owner);
  // Affordability from the user's OWN ATH jetton wallet, through the shared direct-pay pre-flight (fail-closed:
  // an unreadable jetton wallet must not become "go ahead and mint"). This used to be an inline copy; the avatar
  // lane grew the same check and the two are now one primitive.
  await assertConnectedAthAtLeast(priceAtomic, 'mint a name');
  // AND ENOUGH GRAM TO CARRY IT. The ATH check above was the only affordability gate here, so a wallet with the
  // name's ATH but not its GRAM signed an external the wallet contract could not execute: the send action was
  // SILENTLY SKIPPED (mode IGNORE_ERRORS), the seqno moved, and the client read that as "sent".
  //
  // MEASURED on a real user's failed mint, 2026-08-20: balance 0.266225197 before, 0.265632119 after, the
  // transaction's own action phase reporting `tot_actions 1, skipped_actions 1, msgs_created 0`. They lost 0.0006
  // GRAM to fees, not the 1.1 an explorer displays — an explorer renders the INTENDED action — and they tried
  // nine times because nothing told them what was wrong. The airdrop claim lane guarded its send for exactly
  // this reason (removed with the spent airdrop, 2026-08-27); this lane and the avatar lane below lacked it.
  await assertWalletGramAtLeast(
    USERNAME_MINT_DIRECT_REQUEST_VALUE + walletSendFeeReserveNanotons(), 'mint a name');
  setUsernameMintStatus(t('username.signing'));
  const athWalletAddress = await loadConnectedAthWalletAddress();
  const athRequest = createAthWalletMessage('ATHTransferRequestRegistryMintUsername', {
    query_id: nextQueryId(),
    amount: priceAtomic,
    recipient: registry,
    response_destination: owner,
    notify_value: USERNAME_MINT_DIRECT_NOTIFY_VALUE,
    owner_wallet: owner,
    username: new TextEncoder().encode(username),
  }, { athWalletAddress, valueNanotons: USERNAME_MINT_DIRECT_REQUEST_VALUE });
  const transport = globalThis.plathoWalletRpcTransport ?? globalThis.plathoTonRpcTransport;
  let result;
  try {
    result = await sendPlathoWalletTransaction(requirePlathoWallet(), { messages: [athRequest] }, { transport });
  } catch (error) {
    // AMBIGUOUS broadcast (platho-wallet attaches error.builtBoc when the external may have landed): set the pending
    // marker so a retry is BLOCKED (assertNoPendingUsernameMintRetry) until it expires or the mint confirms — otherwise
    // the retry would sign a FRESH external + a SECOND real ATH payment (the contract refunds it, but it burns TON and
    // confuses the user). A CLEAR pre-broadcast failure (no builtBoc) leaves no marker, so a clean retry is allowed.
    // [mint review: ambiguous-broadcast double-payment — the button flow has no message-object to re-broadcast from]
    if (error?.builtBoc) rememberPendingUsernameMint(username, owner, { clientNonce: error?.builtSeqno ?? null });
    throw error;
  }
  rememberPendingUsernameMint(username, owner, result);
  setUsernameMintStatus(result?.confirmationPending === true ? t('username.mintSubmittedFinalizing') : t('username.mintFinalizing'));
  autoLinkMintedUsername(username, owner, {
    attempts: USERNAME_MINT_BACKGROUND_CONFIRM_ATTEMPTS,
    delayMs: USERNAME_MINT_BACKGROUND_CONFIRM_DELAY_MS,
  }).catch((error) => {
    setUsernameMintStatus(t('username.mintSubmittedLinkAfterSync'));
    console.error(error);
  });
  return result;
}

async function submitUsernameMint() {
  const username = await requestUsernameMintName();
  if (!username) return null;
  // clean-17 direct-pay: the mint is paid from the user's OWN ATH wallet straight to UsernameRegistry
  // (submitUsernameMintDirect). The removed Vault half read the Vault user/global, verified a Vault->registry
  // route and signed a Vault auth external — none of which exists once the wallet pays the registry itself.
  return submitUsernameMintDirect(username);
}

// Direct-pay avatar funding (clean-17). notify_value 66M is above the ~49M a FIRST avatar record needs to land at
// the registry (below it the registry refuses at 21112 and refunds); the request VALUE 200M covers the ATH wallet's
// downstream requirement (notify_value + the notify/ack/storage constants + the owner-request reserve, ~128M
// measured) with headroom. Both are validated end-to-end in tests/ath-avatar-request AAR-02.
const PROFILE_AVATAR_DIRECT_NOTIFY_VALUE = PROFILE_AVATAR_DIRECT_NOTIFY_VALUE_NANOTONS;
const PROFILE_AVATAR_DIRECT_REQUEST_VALUE = PROFILE_AVATAR_DIRECT_REQUEST_VALUE_NANOTONS;

// clean-17 direct-pay avatar: publish the image bytes to the owner's AVATAR PublicShard (kind 3, PPH2 — NO
// profileVersion/avatarHash in the header, those live only in the paid pointer) AND pay 100 ATH to ProfileRegistry,
// which authorises the KeyShard pointer write. Both ride ONE wallet transfer. The pointer's avatar_stream_id is the
// 16-byte streamId as a uint128, avatar_part_count the part count — exactly what readAvatarPartsFromShard matches on.
async function submitProfileAvatarDirect(avatar) {
  if (!plathoWallet?.address) throw new Error('Connect a wallet to set an avatar');
  if (!avatar?.bytes?.length) return null;
  const owner = requireBasechainAddress(requirePlathoWalletAddress(), 'Connected wallet');
  const avatarHash = await sha256Hex(avatar.bytes);
  setProfileAvatarPending(true);
  setProfileAvatarStatus(t('avatar.checkingCurrent'));
  // FAIL-CLOSED idempotence. The pre-pay read is the ONLY thing standing between a re-pick of the same image
  // and a second 100 ATH payment, so "the RPC flapped" must not be silently equal to "no avatar on chain".
  // readCurrentProfileAvatarPointerResultFromChain reports ok:false for a read failure and ok:true/pointer:null
  // for a genuine absence — the old `.catch(() => null)` collapsed both into "go ahead and pay".
  const currentRead = await readCurrentProfileAvatarPointerResultFromChain(owner, { required: false });
  if (!currentRead.ok) {
    const error = new Error('Cannot verify the current avatar right now — try again');
    error.code = 'PLATHO_AVATAR_PRECHECK_UNREADABLE';
    error.cause = currentRead.error;
    throw error;
  }
  const currentPointer = currentRead.pointer;
  if (currentPointer?.avatarHash?.toLowerCase?.() === normalizeAvatarHashHex(avatarHash).toLowerCase()) {
    await writeProfileAvatarMediaCache(avatarHash, bytesToImageDataUrl(avatar.bytes, 'image/webp'));
    setProfileAvatarStatus(t('avatar.active'), '');
    return { status: 'active', registryPointer: currentPointer };
  }
  const parts = imagePartsForSend(avatar, 'profile avatar');
  if (parts.length <= 0) throw new Error('Avatar image is empty');
  if (parts.length > 16) throw new Error('Avatar must fit 16 public capsules');
  const createdAtSec = Math.floor(Date.now() / 1000);
  // DETERMINISTIC streamId: a retry of the SAME image in the SAME era rebuilds byte-identical parts, so the
  // reader (which groups by streamId and authenticates the assembled bytes against the paid pointer) merges
  // them by partIndex instead of accumulating a second orphan stream in the shard. The era is part of the
  // preimage on purpose: after the avatar retention window a re-upload of the same image MUST produce a
  // different pointer, otherwise KeyShard gate 22205 (identical pointer rejected) would make it unrecoverable.
  const streamId = await deriveProfileAvatarStreamId(owner, avatarHash, publicEraOf(3, createdAtSec));
  const payloads = [];
  for (let index = 0; index < parts.length; index += 1) {
    payloads.push(await createPublicPostPayloadV2({
      type: 'avatar', bytes: parts[index].bytes, mediaFormat: PUBLIC_BODY_MEDIA_FORMATS.WEBP,
      streamId, partIndex: index, partCount: parts.length, createdAtSec,
    }, { sizeClass: parts[index].sizeClass }));
  }

  const walletHash = publicWalletHash(owner);
  const avatarPartitionKey = await publicAvatarPartitionKey(walletHash);
  const avatarEpochTag = publicEpochTag(3, publicEraOf(3, createdAtSec));
  const avatarValue = publicPublishValueForKind(3);
  const shardParts = payloads.map((payload) => ({
    kind: 3, keyArg: 0n, header: payload.headerCell, body: payload.bodyCell, value: avatarValue, partitionKey: avatarPartitionKey, epochTag: avatarEpochTag,
  }));

  const athWalletAddress = await loadConnectedAthWalletAddress();
  const athRequest = createAthWalletMessage('ATHTransferRequestRegistryProfileAvatar', {
    query_id: nextQueryId(),
    amount: PROFILE_AVATAR_PRICE_ATH,
    recipient: requireProfileRegistryAddress(),
    response_destination: owner,
    notify_value: PROFILE_AVATAR_DIRECT_NOTIFY_VALUE,
    owner_wallet: owner,
    avatar_hash: uint256HexToBigInt(avatarHash, 'avatar_hash'),
    avatar_entry_id: 0n,   // unused in the shard model (reader matches by streamId + sha256)
    avatar_stream_id: tonCell.bytesToBigInt(streamId),
    avatar_part_count: BigInt(parts.length),
    media_format: BigInt(PUBLIC_BODY_MEDIA_FORMATS.WEBP),
  }, { athWalletAddress, valueNanotons: PROFILE_AVATAR_DIRECT_REQUEST_VALUE });

  // AFFORDABILITY, before anything is signed. Order matters: ATH first (fail-closed, and the expensive leg),
  // then GRAM (fail-open). Without these the wallet happily signs a transfer whose ATH leg cannot settle —
  // SendIgnoreErrors drops that leg silently, the image bytes still land and are still paid for, and the
  // pointer is never written. See assertConnectedAthAtLeast for why the two rules differ.
  await assertConnectedAthAtLeast(PROFILE_AVATAR_PRICE_ATH, 'set an avatar');
  await assertWalletGramAtLeast(
    avatarValue * BigInt(shardParts.length) + PROFILE_AVATAR_DIRECT_REQUEST_VALUE
      // …plus the registry write, a further message in the same transfer (class 1 — a small request body).
      + walletSendFeeReserveNanotons([...payloads.map((payload) => payload.sizeClass), 1]),
    'set an avatar',
  );

  setProfileAvatarStatus(t('avatar.publishing'));
  const transport = globalThis.plathoWalletRpcTransport ?? globalThis.plathoTonRpcTransport;
  let result = null;
  try {
    result = await publishPublicLaneParts({ wallet: plathoWallet, transport }, shardParts, { extraMessages: [athRequest] });
  } catch (error) {
    // A CLEAR pre-broadcast failure spent nothing — surface it. An AMBIGUOUS one (platho-wallet attaches
    // error.builtBoc when the external may already have landed) must NOT be reported as a failure: re-picking
    // the image after a false "failed" is what pays a second 100 ATH. The chain is the authority, so fall
    // through to the confirm loop below and let the pointer decide.
    if (!error?.builtBoc) throw error;
    setProfileAvatarStatus(t('avatar.broadcastUncertainConfirming'));
    result = { ambiguousBroadcast: true, builtSeqno: error.builtSeqno ?? null };
  }
  await writeProfileAvatarMediaCache(avatarHash, bytesToImageDataUrl(avatar.bytes, 'image/webp'));
  globalThis.plathoLastProfileAvatarDirect = { avatarHash, streamId: bytesToHex(streamId), partCount: parts.length, result };
  // CONFIRM the paid pointer write. A broadcast is not an outcome: the 100 ATH ride a two-phase
  // ProfileRegistry -> KeyShard write that can bounce (and refund) without the client noticing. The button
  // stays locked while this runs — an unlocked button on an unconfirmed avatar is exactly what makes an
  // impatient user pay twice.
  const registryPointer = await confirmProfileAvatarPointer(owner, avatarHash);
  if (registryPointer) {
    setProfileAvatarStatus(t('avatar.active'), '');
    return { status: 'active', result, avatarHash, registryPointer };
  }
  // Truthful terminal: the bytes are published and paid, but the pointer is not visible yet. Red + retryable,
  // never a green "submitted" that the user reads as done.
  setProfileAvatarStatus(t('avatar.notActiveYet'), 'error');
  return { status: 'submitted', result, avatarHash };
}

// streamId = first 16 bytes of sha256("PLATHO-AVATAR-STREAM-V1" ‖ owner ‖ avatarHash ‖ era). Domain-separated so
// it can never collide with another derivation, and 16 bytes because the pointer field is a uint128. It is NOT
// a secret: the same image published by the same wallet is meant to be recognisable as the same stream — that
// is what lets a retry merge with the parts already on the shard instead of orphaning them. Deliberately NOT
// generalised to posts/comments: there, re-posting identical text must stay a separate entry.
async function deriveProfileAvatarStreamId(ownerWallet, avatarHash, era) {
  const owner = requireBasechainAddress(ownerWallet, 'Avatar owner');
  const hashBytes = hexToBytes(normalizeAvatarHashHex(avatarHash).replace(/^0x/i, ''));
  const ownerBytes = new TextEncoder().encode(owner);
  const domain = new TextEncoder().encode('PLATHO-AVATAR-STREAM-V1');
  const eraBytes = new Uint8Array(4);
  new DataView(eraBytes.buffer).setUint32(0, Number(era) >>> 0, false);
  const preimage = new Uint8Array(domain.length + ownerBytes.length + hashBytes.length + eraBytes.length);
  preimage.set(domain, 0);
  preimage.set(ownerBytes, domain.length);
  preimage.set(hashBytes, domain.length + ownerBytes.length);
  preimage.set(eraBytes, domain.length + ownerBytes.length + hashBytes.length);
  const digest = await sha256Hex(preimage);
  return hexToBytes(digest.replace(/^0x/i, '').slice(0, 32));
}

// The paid pointer lands via ProfileRegistry -> KeyShard (two-phase, ack/bounce), so it appears some blocks
// AFTER the wallet transfer. Poll the owner's KeyShard until it carries this avatarHash. Reads go through
// enqueueAvatarChainRead: the avatar lane is serial by construction (two concurrent chain reads are the
// documented iOS run-loop freeze), and the ladder is coarse enough that a 2-minute wait costs ~15 reads.
const PROFILE_AVATAR_POINTER_CONFIRM_DELAYS_MS = [3_000, 3_000, 5_000, 5_000, 8_000, 8_000, 12_000, 12_000, 15_000];
const PROFILE_AVATAR_POINTER_CONFIRM_DEADLINE_MS = 120 * 1000;

async function confirmProfileAvatarPointer(owner, avatarHash) {
  const expected = normalizeAvatarHashHex(avatarHash).toLowerCase();
  const startedAt = Date.now();
  setProfileAvatarStatus(t('avatar.confirmingRegistry'));
  for (let attempt = 0; Date.now() - startedAt < PROFILE_AVATAR_POINTER_CONFIRM_DEADLINE_MS; attempt += 1) {
    const delayMs = PROFILE_AVATAR_POINTER_CONFIRM_DELAYS_MS[
      Math.min(attempt, PROFILE_AVATAR_POINTER_CONFIRM_DELAYS_MS.length - 1)
    ];
    await delay(delayMs);
    const read = await enqueueAvatarChainRead(() => readCurrentProfileAvatarPointerResultFromChain(owner, { required: false }));
    if (!read.ok) continue;   // transient read failure: keep waiting, the deadline is the bound
    if (read.pointer?.avatarHash?.toLowerCase?.() !== expected) continue;
    // Paint the new avatar immediately from the sha256-verified media cache written just above, so the tile
    // stops showing the previous image the moment the pointer is real (the profile pane only re-reads on a
    // tab change, and the Set-avatar button lives ON that pane — there is no tab change to ride).
    const imageUrl = await readProfileAvatarMediaCache(read.pointer.avatarHash).catch(() => null);
    if (imageUrl) {
      setAvatarNode(profileAvatar, 'P', imageUrl);
      setOwnPublicFeedAvatar(owner, imageUrl);
    }
    return read.pointer;
  }
  return null;
}

// clean-17 direct-pay: the avatar rides ONE wallet transfer (AVATAR PublicShard parts + the 100 ATH request that
// authorises the KeyShard pointer write) — see submitProfileAvatarDirect. The removed Vault submit phase
// (runProfileAvatarSubmitPhase: CapsuleHub publishState, mobilized confirm loop, entry-scan recovery, inline-key
// exclusion vs the recovery ticks) is off the live path: a direct publish is confirmed by the wallet transfer
// itself, so there is no publishState to heal and no second paid registry submission to guard against.
async function submitProfileAvatarUpdate(avatar) {
  return submitProfileAvatarDirect(avatar);
}

// A never-deployed KeyShard aborts a get-method with the code-less TVM exit (-13 in production, -256 under the sandbox);
// the transport rethrows it as error.exitCode. That is DEFINITIVE "not registered". Any other read failure (429/network)
// is TRANSIENT and must not be mistaken for it — mirrors [[ton-uninit-exit-code-minus13]].
function isKeyShardUninitError(error) {
  const code = Number(error?.exit_code ?? error?.exitCode ?? error?.body?.exit_code ?? NaN);
  return code === -13 || code === -256;
}

// clean-17 DIRECT-PAY register: publish the messaging keys straight to the user's KeyShard from their own wallet, no
// Vault external. sender() == owner_wallet is the shard's whole authorisation. Gated behind privateLane.directPay so the
// clean-15 Vault path below is untouched until cutover; the byte-exact KSG1 builder is pinned in tests/key-shard-register.
async function submitKeyShardRegisterDirect({ preConfirmed = false } = {}) {
  if (!localVaultDraft?.message) throw new Error('Local messaging key draft is not ready');
  const ownerWallet = requireBasechainAddress(requirePlathoWalletAddress(), 'Connected wallet');
  const registry = requireBasechainAddress(requireProfileRegistryAddress(), 'ProfileRegistry');
  const transport = globalThis.plathoWalletRpcTransport ?? globalThis.plathoTonRpcTransport;
  if (!transport?.runGetMethod) throw new Error('KeyShard register: RPC transport unavailable');
  // Read the OWN KeyShard. Registered WITH THE CURRENT keys ⇒ active, no-op. There is no real "rotation" here: the
  // messaging keys are DETERMINISTICALLY derived from the wallet seed with frozen info-strings, so re-deriving always
  // yields the same keys and the conversation keyId (H(enc,mlkem), generation-independent) can never change. So this is
  // register-OR-REPAIR: if the shard holds STALE keys (a derivation-version change or a prior bad write), re-register to
  // overwrite them — KSG1 is register-or-replace and the contract charges the replace floor for a re-write (overpay
  // refunded), so KEYSHARD_REGISTER_VALUE funds both. A TRANSIENT read must NOT drive a write — only a definitive uninit.
  const provider = createKeyShardTonRpcProvider({ profileRegistryAddress: registry, decodeAddressSliceBoc: decodeTonAddressSliceBoc });
  let view = null;
  try {
    view = await withVaultReadLock(() => provider.getView(ownerWallet, criticalChainReadOptions()));
  } catch (error) {
    if (!isKeyShardUninitError(error)) throw error;   // transient — abort rather than write on a bad read
    view = { exists: false };
  }
  const registeredMine = view?.exists === true
    && BigInt(view.enc_pubkey ?? 0n) === BigInt(localVaultDraft.message.enc_pubkey ?? 0n)
    && BigInt(view.sign_pubkey ?? 0n) === BigInt(localVaultDraft.message.sign_pubkey ?? 0n);
  if (registeredMine) { vaultDraftStatus.textContent = t('vault.active'); return null; }
  const needsKeyBackup = walletKeyBackupPendingForStoredWallet();
  // [OWNER 2026-08-10] The wizard has ALREADY walked the user through the backup on its own step and put the fee
  // on screen next to the balance, so re-confirming both here — checkbox by checkbox, plus a second forced key
  // download — is asking the same questions twice. Pressing Activate there means activate.
  if (!preConfirmed) {
    if (!(await confirmPlathoAccountActivation(view ?? { exists: false }, { needsKeyBackup }))) return null;
    if (needsKeyBackup) { await downloadEncryptedWalletKeyBackup(); }
  }
  vaultDraftStatus.textContent = t('vault.signing');
  // Affordability before signing, on the same figure the fee label quoted. Activation is the one send a brand-new
  // wallet makes, so this is exactly where a balance funded to the quoted number gets tested.
  await assertWalletGramAtLeast(
    KEYSHARD_REGISTER_VALUE + walletSendFeeReserveNanotons([KEYSHARD_REGISTER_SIZE_CLASS]), 'activate');
  const result = await publishKeyShardRegister({
    wallet: requirePlathoWallet(), transport, ownerWallet, profileRegistry: registry,
    keyRecord: localVaultDraft.message, value: KEYSHARD_REGISTER_VALUE,
  });
  plathoAccountActivationPending = true;
  // ...and written down WITH the signed external, so a reload inside the settling window neither offers to pay the
  // fee a second time nor abandons the copy already paid for. `pendingBoc` is the LAST chunk's — the one that may
  // still be in flight when the send call returns; the top-level `boc` is the first chunk's and would re-send the
  // wrong bytes.
  rememberPlathoActivationInFlight(ownerWallet, result?.result?.pendingBoc ?? result?.result?.boc ?? null, result?.result?.pendingSeqno ?? result?.result?.seqno ?? null);
  forcePlathoActivationDelivery();
  vaultDraftStatus.textContent = t('vault.activationSent');
  queueVaultPostTransactionRefresh({ pollActivation: true });
  return result;
}

async function submitVaultRegisterMessagingKeys(options = {}) {
  // clean-17 direct-pay: messaging keys are published straight into the owner's KeyShard from their wallet
  // (submitKeyShardRegisterDirect); sender() == owner_wallet is the shard's whole authorisation. The removed
  // half built a Vault RegisterMessagingKeys auth external.
  return submitKeyShardRegisterDirect(options);
}

async function confirmPlathoAccountActivation(user, { needsKeyBackup = true } = {}) {
  const fee = plathoAccountActivationFeeNanotons(user);
  const walletBalance = await refreshWalletTonBalanceForProfile().catch(() => null);
  let feedback = needsKeyBackup
    ? t('vault.activationExportKeyFeedback')
    : t('vault.activationKeyBackedUpFeedback');
  let tone = 'muted';
  if (walletBalance !== null && walletBalance < fee) {
    feedback = t('vault.activationLowBalanceFeedback', { fee: formatTonNanotons(fee) });
    tone = 'error';
  }
  // The forced key-export step (and its acknowledgement checkbox) only appears when the key has not been
  // backed up yet. An imported / already-exported wallet skips it and just confirms the on-chain activation.
  const fields = [];
  if (needsKeyBackup) {
    fields.push({
      id: 'backupConfirmed',
      type: 'checkbox',
      label: t('vault.activationBackupCheckbox'),
    });
  }
  fields.push({
    id: 'activationConfirmed',
    type: 'checkbox',
    label: t('vault.activationConfirmCheckbox', { amount: t('common.gramAmount', { amount: formatTonNanotons(fee) }) }),
  });
  const result = await openActionDialog({
    title: t('vault.activateAccountTitle'),
    hint: feedback,
    tone,
    submitLabel: needsKeyBackup ? t('vault.exportKeyAndActivate') : t('vault.activateAccount'),
    dismissOnBackdrop: false,
    fields,
    summary: [
      { label: t('common.walletGram'), value: walletBalance === null ? t('common.unknown') : t('common.gramAmount', { amount: formatTonNanotons(walletBalance) }) },
      { label: t('vault.activationTxValue'), value: t('common.gramAmount', { amount: formatTonNanotons(fee) }) },
      { label: t('vault.backupLabel'), value: needsKeyBackup ? t('vault.backupEncryptedJson') : t('vault.backupAlreadySaved') },
      { label: t('vault.afterActivationLabel'), value: t('vault.afterActivationValue') },
    ],
  });
  if (!result) return false;
  if (needsKeyBackup && result.backupConfirmed !== true) return false;
  return result.activationConfirmed === true;
}

async function submitVaultReplaceMessagingKeys() {
  // clean-17: there is nothing to rotate. The messaging keys are DERIVED deterministically from the wallet
  // seed with frozen info strings, so a "replace" would re-register the same keys; re-registration that DOES
  // matter (stale keys on the shard) is folded into submitKeyShardRegisterDirect. The button is hidden under
  // direct pay; this throw is the fail-closed backstop for any programmatic caller.
  throw new Error('Key rotation is not yet available on direct-pay (KeyShard replace path pending)');
}

const VAULT_PUBLISH_STATUS_SUBMITTED = 'vault-publish-submitted';
const VAULT_PUBLISH_STATUS_PARTIAL = 'vault-publish-partial';
const CAPSULEHUB_PUBLISH_STATUS_CONFIRMED = 'capsulehub-publish-confirmed';
const PUBLISH_PART_STATUS_SENT = 'sent';
const PUBLISH_PART_STATUS_VAULT_SUBMITTED = 'vault_submitted';
const PUBLISH_PART_STATUS_CAPSULEHUB_CONFIRMED = 'capsulehub_confirmed';
const PUBLISH_PART_STATUS_UNKNOWN = 'unknown';
const VAULT_PUBLISH_PARTIAL_ERROR_CODE = 'PLATHO_VAULT_PUBLISH_PARTIAL';

function publishStatePendingCount(publishState) {
  return (publishState?.parts ?? []).filter((item) => (
    item.status === PUBLISH_PART_STATUS_SENT
    || item.status === PUBLISH_PART_STATUS_UNKNOWN
    || item.status === PUBLISH_PART_STATUS_VAULT_SUBMITTED
    || item.status === PUBLISH_PART_STATUS_CAPSULEHUB_CONFIRMED
  )).length;
}

function publishStateBroadcastCount(publishState) {
  return (publishState?.parts ?? []).filter((item) => (
    item.status === PUBLISH_PART_STATUS_SENT
    || item.status === PUBLISH_PART_STATUS_UNKNOWN
  )).length;
}

function publishStatePriorAttemptCount(publishState) {
  return (publishState?.parts ?? []).filter((item) => publishPartHadPriorChainAttempt(item)).length;
}

function publishStateVisibleSubmittedCount(publishState) {
  const total = Math.max(1, Number(publishState?.partCount) || 1);
  const previous = Math.max(0, Number(publishState?.displaySubmittedCount ?? 0) || 0);
  const current = Math.max(
    Number(publishState?.submittedCount ?? 0) || 0,
    Number(publishState?.confirmedCount ?? 0) || 0,
    publishStatePendingCount(publishState),
    publishStateBroadcastCount(publishState),
    publishStatePriorAttemptCount(publishState),
  );
  return Math.min(total, Math.max(previous, current));
}

function publishStateMeta(publishState) {
  const total = Math.max(1, Number(publishState?.partCount) || 1);
  const confirmed = Math.max(0, Number(publishState?.confirmedCount) || 0);
  const submitted = Math.max(0, Number(publishState?.submittedCount) || 0);
  const broadcast = Math.max(0, publishStateBroadcastCount(publishState));
  const pending = Math.max(submitted, publishStatePendingCount(publishState), publishStateVisibleSubmittedCount(publishState));
  // TWO-PHASE live progress (v763, owner ask — the joint "submitted 8/8, confirming 1/8" read as two
  // counters glued together, and its "submitted" jumped to 8/8 instantly because it counted the
  // sign-time SENT stamp): phase 1 `submitted L/N` ticks batch-by-batch with REAL on-chain landings
  // (vault_submitted+confirmed — submittedCount already includes confirmed); once every part landed,
  // phase 2 `confirming C/N` ticks CapsuleHub confirmations up to 'published'. Each phase keeps its
  // keyword ('submitted' / 'confirming') so every substring gate matches both. Single-part keeps the
  // plain two-word text — one step, nothing to count.
  const landed = Math.max(submitted, confirmed);
  const progressMeta = () => {
    // Single-part gets the SAME two phases, worded without a pointless 0/1 counter (v764, owner ask —
    // the joint text leaked back for every 1-capsule message): 'sending' until the external actually
    // lands on-chain (signed/queued/broadcast are all still "in flight"), then 'confirming'. Both
    // words are in every substring gate (the 24h render backstop regex includes 'sending').
    if (total === 1) return landed < total ? 'sending' : 'confirming';
    return landed < total
      ? `submitted ${landed}/${total}`
      : `confirming ${confirmed}/${total}`;
  };
  if (confirmed >= total) return 'published';
  if (publishState?.status === VAULT_PUBLISH_STATUS_PARTIAL) {
    if (pending <= 0) return 'not sent';
    if (submitted <= 0 && broadcast > 0) return progressMeta();
    if (pending >= total) return progressMeta();
    // Same landed-count semantics as the phase display (review fix): counting PENDING here made the
    // visible "submitted" figure JUMP UP when a part flipped FAILED (pending shrank below total and
    // this branch took over with a bigger number than the landed count).
    return `submitted ${landed}/${total}, retrying`;
  }
  if (submitted <= 0 && broadcast > 0) return progressMeta();
  if (pending > 0 || publishState?.status === VAULT_PUBLISH_STATUS_SUBMITTED) {
    return progressMeta();
  }
  if (publishState?.status === 'failed') {
    // A pre-send failure (RPC 429/500/verification-degraded before anything left
    // the device) flips the part to FAILED while it is still queued for retry.
    // Show a neutral "queued, retrying" then, not a red terminal "not sent" — the
    // genuinely-terminal red is written straight to message.meta by the retry-
    // exhausted / blocked paths, which never route through here.
    return publishStateHasRetryableSendParts(publishState) ? 'queued, retrying' : 'not sent';
  }
  return total > 1 ? `sending ${total} parts` : 'sending';
}

function isVaultPublishPartialError(error) {
  return error?.code === VAULT_PUBLISH_PARTIAL_ERROR_CODE;
}


function privateMessageHasPublishAttempt(message) {
  return (message?.publishState?.parts ?? []).some((part) => publishPartEligibleForChainConfirmation(part));
}

function privateMessageHasPartialRetryablePublish(message) {
  return privateMessageHasPublishAttempt(message)
    && message?.publishState?.status !== CAPSULEHUB_PUBLISH_STATUS_CONFIRMED
    && publishStateHasRetryableSendParts(message?.publishState);
}

function privateMessageHasAutoRecoveryPending(message) {
  if (!message || message.privateManualRetryAvailable === true) return false;
  if (message.privateSendRetryStopped === true || message.privatePublishConfirmStopped === true) return false;
  const hasSendJob = Boolean(message.privateSendRetryKey && privateSendRetryJobs.has(message.privateSendRetryKey));
  const hasConfirmJob = Boolean(message.privatePublishConfirmRetryKey && privatePublishConfirmJobs.has(message.privatePublishConfirmRetryKey));
  const hasStoredCapsules = (Array.isArray(message.capsules) && message.capsules.length > 0) || Boolean(message.capsule);
  const sendPending = hasStoredCapsules
    && publishStateHasRetryableSendParts(message.publishState)
    && (!isStalePrivatePendingPublish(message) || privateMessageHasPublishAttempt(message));
  const confirmPending = privateMessageHasPublishAttempt(message)
    && message.publishState?.status !== CAPSULEHUB_PUBLISH_STATUS_CONFIRMED
    && !isStalePrivatePendingPublishConfirmation(message);
  return hasSendJob || hasConfirmJob || sendPending || confirmPending;
}

function privatePartialPublishStartedAtMs(message) {
  const times = [];
  const createdAtMs = messageCreatedAtMs(message);
  if (createdAtMs !== null) times.push(createdAtMs);
  for (const part of message?.publishState?.parts ?? []) {
    for (const value of [part?.lastBroadcastAt, part?.updatedAt]) {
      const parsed = Date.parse(value ?? '');
      if (Number.isFinite(parsed) && parsed > 0) times.push(parsed);
    }
  }
  if (times.length > 0) return Math.min(...times);
  return publishStateUpdatedAtMs(message?.publishState);
}

function privatePartialSendRetryAgeMs(message) {
  const startedAtMs = privatePartialPublishStartedAtMs(message);
  return startedAtMs === null ? null : Math.max(0, Date.now() - startedAtMs);
}

function privatePartialSendRetryExpired(message) {
  if (!privateMessageHasPartialRetryablePublish(message)) return false;
  const startedAgeMs = privatePartialSendRetryAgeMs(message);
  // QUEUE-PROGRESS anchored like the sibling give-up terminals (v763): a queued PARTIAL in a MOVING
  // queue must not hard-expire on its immovable start time — that resurrected the Retry-oscillation
  // (expire -> red -> manual Retry -> re-bounce behind the still-draining queue -> re-expire within
  // seconds) for exactly the PARTIAL class. While the chain nonce advances under this message's
  // passes (or its own parts land), the window slides; a genuinely stalled queue expires as before.
  const progressMs = Number(message?.publishState?.queueProgressAt ?? 0) || 0;
  const ageMs = startedAgeMs === null
    ? null
    : (progressMs > 0 ? Math.min(startedAgeMs, Math.max(0, Date.now() - progressMs)) : startedAgeMs);
  // Part-count scaled (v648): the partial-retry window must stay ABOVE the scaled no-progress terminal (its
  // calibrated 2-part relation was 15min = 6min terminal + 9min slack) or an honest N>=3 partial would lose its
  // retry machinery while the confirm driver still legitimately waits.
  const deadlineMs = Math.max(
    PRIVATE_SEND_PARTIAL_RETRY_DEADLINE_MS,
    publishConfirmNoProgressDeadlineMs(message?.publishState) + 9 * 60 * 1000,
  );
  return ageMs !== null && ageMs >= deadlineMs;
}

function publishPartAlreadyAttempted(part) {
  return part?.status === PUBLISH_PART_STATUS_SENT
    || part?.status === PUBLISH_PART_STATUS_UNKNOWN
    || part?.status === PUBLISH_PART_STATUS_VAULT_SUBMITTED
    || part?.status === PUBLISH_PART_STATUS_CAPSULEHUB_CONFIRMED;
}

function publishPartHadPriorChainAttempt(part) {
  const previousStatus = part?.retryPreviousStatus;
  return previousStatus === PUBLISH_PART_STATUS_SENT
    || previousStatus === PUBLISH_PART_STATUS_UNKNOWN
    || previousStatus === PUBLISH_PART_STATUS_VAULT_SUBMITTED
    || previousStatus === PUBLISH_PART_STATUS_CAPSULEHUB_CONFIRMED;
}

function publishPartEligibleForChainConfirmation(part) {
  return publishPartAlreadyAttempted(part) || publishPartHadPriorChainAttempt(part);
}

function publishStateHasRetryableSendParts(publishState) {
  return (publishState?.parts ?? []).some((part) => !publishPartAlreadyAttempted(part));
}

function privateSendRetryKey(message) {
  if (!message.privateSendRetryKey) {
    privateSendRetrySeq += 1;
    message.privateSendRetryKey = `private-send-${Date.now()}-${privateSendRetrySeq}`;
  }
  return message.privateSendRetryKey;
}

function privatePublishConfirmRetryKey(message) {
  if (!message.privatePublishConfirmRetryKey) {
    privatePublishConfirmSeq += 1;
    message.privatePublishConfirmRetryKey = `private-confirm-${Date.now()}-${privatePublishConfirmSeq}`;
  }
  return message.privatePublishConfirmRetryKey;
}

function clearPrivateSendRetry(message) {
  const key = message?.privateSendRetryKey;
  if (!key) return;
  const job = privateSendRetryJobs.get(key);
  if (job?.timer) window.clearTimeout(job.timer);
  privateSendRetryJobs.delete(key);
}

function clearPrivatePublishConfirmRetry(message) {
  const key = message?.privatePublishConfirmRetryKey;
  if (!key) return;
  const job = privatePublishConfirmJobs.get(key);
  if (job?.timer) window.clearTimeout(job.timer);
  privatePublishConfirmJobs.delete(key);
}

function refreshPrivateSendRetryUi(thread, message, meta) {
  message.meta = meta;
  thread.state = messageStatusKey(message) === 'sending' ? 'sending' : thread.state;
  refreshThreadAfterMessageChange(thread);
  renderThreads();
  renderConversation();
  updateMessageInEncryptedHistory(thread, message).catch((error) => console.error(error));
}

function publishStateUpdatedAtMs(publishState) {
  const parsed = Date.parse(publishState?.updatedAt ?? '');
  return Number.isFinite(parsed) && parsed > 0 ? parsed : null;
}

function privatePendingPublishAgeMs(message) {
  const timestamp = publishStateUpdatedAtMs(message?.publishState) ?? messageCreatedAtMs(message);
  return timestamp === null ? 0 : Math.max(0, Date.now() - timestamp);
}

function isStalePrivatePendingPublish(message) {
  return privatePendingPublishAgeMs(message) > PRIVATE_PENDING_PUBLISH_STALE_AFTER_MS;
}

function isStalePrivatePendingPublishConfirmation(message) {
  return privatePendingPublishAgeMs(message) > PRIVATE_PENDING_PUBLISH_CONFIRMATION_STALE_AFTER_MS;
}

function stopPrivateSendRetry(context, error = null) {
  const { thread, message } = context;
  if (!thread?.messages?.includes(message)) return;
  clearPrivateSendRetry(message);
  message.privateSendRetryStopped = true;
  message.privateSendRetryStoppedAt = new Date().toISOString();
  message.meta = privateSendRetryExhaustedStatusText(error);
  message.privateManualRetryAvailable = true;
  message.privateCancelAvailable = privateMessageCanLocalCancel(message);
  message.privateSendLastError = shortUiErrorText(error, 'send retry stopped');
  thread.state = 'blocked';
  refreshThreadAfterMessageChange(thread);
  renderThreads();
  renderConversation();
  updateMessageInEncryptedHistory(thread, message).catch((historyError) => console.error(historyError));
}

function schedulePrivateSendRetry(context, error) {
  const { thread, message } = context;
  if (!thread?.messages?.includes(message)) return;
  if (message.privateSendRetryStopped === true) return;
  const attempt = Number(context.retryAttempt ?? message.privateSendRetryAttempt ?? 0) || 0;
  if (isStalePrivatePendingPublish(message) && !privateMessageHasPublishAttempt(message)) {
    stopPrivateSendRetry(context, { message: 'retry window expired', code: 'STALE_PRIVATE_PUBLISH' });
    return;
  }
  if (privatePartialSendRetryExpired(message)) {
    stopPartialPrivatePublishRecovery(context, { message: 'partial publish retry window expired', code: 'PARTIAL_PRIVATE_PUBLISH_RETRY_EXPIRED' });
    return;
  }
  if (attempt >= privateSendRetryMaxAttempts(error, message)) {
    message.privateSendRetryAttempt = attempt;
    if (!message.localHistoryId && !privateMessageHasPublishAttempt(message)) {
      markPrivateMessageManualRecovery(context, error, privateSendRetryExhaustedStatusText(error));
      if (privateComposerCostStatus && thread.id === activeThreadId) {
        privateComposerCostStatus.textContent = privateSendRetryExhaustedStatusText(error);
        privateComposerCostStatus.dataset.state = 'short';
      }
      return;
    }
    if (privateMessageHasPartialRetryablePublish(message)) {
      stopPartialPrivatePublishRecovery(context, { message: 'partial publish retry limit reached', code: 'PARTIAL_PRIVATE_PUBLISH_RETRY_EXPIRED' });
    } else {
      stopPrivateSendRetry(context, error);
    }
    if (privateComposerCostStatus && thread.id === activeThreadId) {
      privateComposerCostStatus.textContent = privateSendRetryExhaustedStatusText(error);
      privateComposerCostStatus.dataset.state = 'short';
    }
    return;
  }
  clearPrivateMessageManualRecovery(message);
  const delayMs = privateSendRetryDelayMs(error, attempt);
  context.retryAttempt = attempt + 1;
  message.privateSendRetryAttempt = context.retryAttempt;
  const scheduledAt = Date.now();
  message.privateSendRetryLastScheduledAt = new Date(scheduledAt).toISOString();
  message.privateSendRetryDelayMs = delayMs;
  message.privateSendRetryNextAt = new Date(scheduledAt + delayMs).toISOString();
  message.privateSendRetryLastError = error ? shortUiErrorText(error, 'send retry delayed') : null;
  refreshPrivateSendRetryUi(thread, message, privateSendRetryMeta(error));
  const key = privateSendRetryKey(message);
  const previous = privateSendRetryJobs.get(key);
  if (previous?.timer) window.clearTimeout(previous.timer);
  const timer = window.setTimeout(() => {
    privateSendRetryJobs.delete(key);
    runPrivateSendRetry(context).catch((retryError) => console.error(retryError));
  }, delayMs);
  privateSendRetryJobs.set(key, { timer, context });
}

function privateSendRetryContextForMessage(thread, message) {
  const draft = message?.privateDraft ?? {};
  return {
    thread,
    message,
    text: draft.text ?? message?.text ?? '',
    attachments: normalizePrivateImageAttachments(draft.attachments ?? []),
    selectedSuite: draft.selectedSuite ?? VAULT_RECEIVE_CRYPTO_SUITE,
    senderOptions: draft.senderOptions ?? message?.senderOptions ?? null,
    replyDraft: draft.replyDraft ?? null,
    shareDraft: draft.shareDraft ?? null,
    fileAttachments: normalizePrivateFileAttachments(draft.fileAttachments ?? []),
    retryAttempt: Number(message?.privateSendRetryAttempt ?? 0) || 0,
    confirmAttempt: Number(message?.privatePublishConfirmAttempt ?? 0) || 0,
  };
}

function revivePartialPrivateSendRetry(message) {
  if (!privateMessageHasPartialRetryablePublish(message)) return false;
  if (privatePartialSendRetryExpired(message)) return false;
  if (message?.privateSendRetryStopped !== true) return false;
  message.privateSendRetryStopped = false;
  message.privateSendRetryStoppedAt = null;
  message.privateSendRetryLastError = 'resuming partial publish';
  message.privateSendRetryAttempt = 0;
  return true;
}

function ensurePendingPrivateSendRetry(thread, message, error = { message: 'resume missing capsule parts', code: 'NETWORK_ERROR' }) {
  const revived = revivePartialPrivateSendRetry(message);
  if (!hasPendingPrivateSendRetry(message)) return false;
  const existingKey = message.privateSendRetryKey;
  if (existingKey && privateSendRetryJobs.has(existingKey)) return false;
  schedulePrivateSendRetry(privateSendRetryContextForMessage(thread, message), revived
    ? { message: 'resuming partial publish send', code: 'NETWORK_ERROR' }
    : error);
  return true;
}

function privatePublishConfirmStoppedStatusText(error = null) {
  if (error?.code === 'INSUFFICIENT_VAULT_GRAM') return 'Insufficient Vault GRAM — top up in Vault, then retry';
  if (error?.code === 'STALE_PRIVATE_PUBLISH') return 'not confirmed: chain lookup expired';
  if (error?.code === 'BROADCAST_REJECTED') return 'not confirmed: RPC broadcast unavailable';
  if (error?.code === 'CONFIRM_RETRY_EXHAUSTED') return 'not confirmed: chain confirmation timed out';
  if (error?.code === 'PARTIAL_PRIVATE_PUBLISH_RETRY_EXPIRED') {
    return /limit/i.test(String(error?.message ?? ''))
      ? 'not confirmed: partial publish retry limit reached'
      : 'not confirmed: partial publish retry window expired';
  }
  if (isTonRpcVerificationUnavailableError(error)) return 'not confirmed: RPC verification unavailable';
  if (isTonRpcRateLimitError(error)) return 'not confirmed: RPC stayed busy';
  const reason = privateSendPreflightStatusText(error);
  return reason && reason !== 'Send blocked'
    ? `not confirmed: ${reason}`
    : 'not confirmed: chain lookup timed out';
}

function stopPartialPrivatePublishRecovery(context, error = { message: 'partial publish retry window expired', code: 'PARTIAL_PRIVATE_PUBLISH_RETRY_EXPIRED' }) {
  const { thread, message } = context;
  if (!thread?.messages?.includes(message)) return false;
  if (!privateMessageHasPartialRetryablePublish(message)) return false;
  const forcedStop = error?.code === 'PARTIAL_PRIVATE_PUBLISH_RETRY_EXPIRED'
    && /limit/i.test(String(error?.message ?? ''));
  if (!privatePartialSendRetryExpired(message) && !forcedStop) return false;
  // NOTE (v760): this stopper is deliberately NOT behind the one-pass-per-session grace. Gating it
  // deadlocked expired partials into a zombie state (review finding): the blocked stop left the
  // message with NO driver either — schedulePrivateSendRetry's expired branch returns without
  // scheduling, and hasPendingPrivatePublishConfirmation excludes expired partials — so the promised
  // healing pass never ran and the terminal it gated could never fire. Its immediate terminal is
  // also the SAFE kind: PARTIAL_PRIVATE_PUBLISH_RETRY_EXPIRED keeps privateManualRetryAvailable
  // (one-click idempotent re-broadcast), unlike the 24h stale fallback the zombie decayed into.
  clearPrivateSendRetry(message);
  clearPrivatePublishConfirmRetry(message);
  message.privateSendRetryStopped = true;
  message.privateSendRetryStoppedAt = new Date().toISOString();
  message.privateSendRetryLastError = shortUiErrorText(error, 'partial publish expired');
  message.privatePublishConfirmStopped = true;
  message.privatePublishConfirmStoppedAt = new Date().toISOString();
  message.privatePublishConfirmLastResult = 'partial-expired';
  message.privatePublishConfirmLastError = shortUiErrorText(error, 'partial publish expired');
  message.meta = privatePublishConfirmStoppedStatusText(error);
  message.privateManualRetryAvailable = true;
  message.privateCancelAvailable = false;
  message.privateSendLastError = shortUiErrorText(error, 'partial publish expired');
  thread.state = 'blocked';
  refreshThreadAfterMessageChange(thread);
  renderThreads();
  renderConversation();
  updateMessageInEncryptedHistory(thread, message).catch((historyError) => console.error(historyError));
  return true;
}

// One-full-pass-per-session grace for the AGE give-up terminals (v760): a RELOAD must give every
// pending publish one REAL healing attempt (fresh nonce read + re-broadcast + confirm + the
// dropped-recovery machinery) BEFORE any age-based terminal may stop its driver. Without it, a queue
// that aged past the windows while wedged came back from a reload pre-buried: the resume/scheduler
// terminals fired before the first pass ever ran, so "reload to recover" silently did nothing (the
// owner's 9-messages-behind-a-file wedge, second act). In-memory ON PURPOSE — a fresh session starts
// with a clean slate, which is exactly the wanted semantics. Public records are REBUILT objects
// (feed-cache rebuilds detach references), so the public side keys by `${channelId}:${localId}`.
const privatePublishConfirmPassRanThisSession = new WeakSet();


function hasPendingPrivatePublishConfirmation(message) {
  return privateMessageHasPublishAttempt(message)
    && message?.privatePublishConfirmStopped !== true
    && !privatePartialSendRetryExpired(message)
    && !isStalePrivatePendingPublishConfirmation(message)
    && message?.publishState?.status !== CAPSULEHUB_PUBLISH_STATUS_CONFIRMED;
}

// Read-only console diagnostics for stuck outbound publishes (v761): one row per NON-confirmed
// message with a publishState, surfacing every predicate the resume/scheduler paths consult — the
// exact data needed to see WHY a pending message is (not) being driven, without a diagnostic build.
// Console: plathoDebugPendingPublishes()
globalThis.plathoDebugPendingPublishes = () => {
  const rows = [];
  for (const thread of threads) {
    for (const message of thread.messages ?? []) {
      const state = message?.publishState;
      if (!state || state.status === CAPSULEHUB_PUBLISH_STATUS_CONFIRMED) continue;
      rows.push({
        thread: String(thread.id ?? '').slice(0, 12),
        preview: String(message.text ?? '').slice(0, 12),
        meta: message.meta ?? null,
        status: state.status ?? null,
        parts: (state.parts ?? []).map((part) => `${part.index ?? part.partIndex ?? '?'}:${part.status ?? '?'}:n${part.clientNonce ?? '?'}${part.error ? ':err' : ''}`),
        confirmStopped: message.privatePublishConfirmStopped === true,
        sendStopped: message.privateSendRetryStopped === true,
        manualRetry: message.privateManualRetryAvailable === true,
        hasAttempt: privateMessageHasPublishAttempt(message),
        partialRetryable: privateMessageHasPartialRetryablePublish(message),
        partialExpired: privatePartialSendRetryExpired(message),
        stale: isStalePrivatePendingPublishConfirmation(message),
        hasPending: hasPendingPrivatePublishConfirmation(message),
        passRan: privatePublishConfirmPassRanThisSession.has(message),
        jobArmed: message.privatePublishConfirmRetryKey ? privatePublishConfirmJobs.has(message.privatePublishConfirmRetryKey) : false,
        lastResult: message.privatePublishConfirmLastResult ?? null,
        lastError: message.privatePublishConfirmLastError ?? null,
        nextAt: message.privatePublishConfirmNextAt ?? null,
      });
    }
  }
  return rows;
};

/**
 * A direct-pay send that is safe to resume automatically after a reload.
 *
 * This is the clean-17 counterpart of the publishState/capsules test below it: direct pay produces NEITHER, so the
 * old predicate answered "nothing pending" for every direct send and the auto-retry simply stopped existing across
 * a reload. Resuming requires proof on three axes — nothing was broadcast, the message can be rebuilt faithfully,
 * and a retry really was in flight (privateSendRetryAttempt only advances when one was scheduled). The age bound
 * is the shared one: isStalePrivatePendingPublish falls back to the message's creation time when there is no
 * publishState, so a direct send goes stale 10 minutes after it was composed, exactly like its Vault-era sibling.
 */
function directPaySendRetryResumable(message) {
  return privateLaneDirectPayEnabled()
    && !directSendReachedWallet(message)
    && message?.privateManualRetryAvailable !== true
    && Number(message?.privateSendRetryAttempt ?? 0) > 0
    && sendContentSurvivesReload(message);
}

function hasPendingPrivateSendRetry(message) {
  if (messageStatusKey(message) === 'failed') return false;
  if (message?.privateSendRetryStopped === true) return false;
  if (isStalePrivatePendingPublish(message) && !privateMessageHasPublishAttempt(message)) return false;
  const hasStoredCapsules = (Array.isArray(message?.capsules) && message.capsules.length > 0) || Boolean(message?.capsule);
  if (publishStateHasRetryableSendParts(message?.publishState) && hasStoredCapsules) return true;
  return directPaySendRetryResumable(message);
}

function resumePendingPrivateSendRetries() {
  if (document.hidden) return;
  for (const thread of threads) {
    for (const message of thread.messages ?? []) {
      if (stopPartialPrivatePublishRecovery({ thread, message })) continue;
      if (message?.privateSendRetryStopped !== true
        && publishStateHasRetryableSendParts(message?.publishState)
        && isStalePrivatePendingPublish(message)
        && !privateMessageHasPublishAttempt(message)) {
        stopPrivateSendRetry({ thread, message }, { message: 'retry window expired', code: 'STALE_PRIVATE_PUBLISH' });
        continue;
      }
      if (!hasPendingPrivateSendRetry(message)) continue;
      ensurePendingPrivateSendRetry(thread, message, { message: 'resume pending capsule send', code: 'NETWORK_ERROR' });
    }
  }
}

function clearPrivateMessageManualRecovery(message) {
  if (!message) return;
  message.privateManualRetryAvailable = false;
  message.privateCancelAvailable = false;
  message.privateSendLastError = null;
}

function privateMessageCanLocalCancel(message) {
  return Boolean(message)
    && !privateMessageHasPublishAttempt(message)
    && !message.localHistoryId;
}

function markPrivateMessageManualRecovery(context, error = null, metaText = null) {
  const { thread, message } = context ?? {};
  if (!thread?.messages?.includes(message)) return;
  clearPrivateSendRetry(message);
  clearPrivatePublishConfirmRetry(message);
  message.privateSendRetryStopped = true;
  message.privateSendRetryStoppedAt = new Date().toISOString();
  message.privateManualRetryAvailable = true;
  message.privateCancelAvailable = privateMessageCanLocalCancel(message);
  message.privateSendLastError = shortUiErrorText(error, 'send stopped');
  message.meta = metaText ?? privateSendBlockedStatusText(error);
  thread.state = 'blocked';
  refreshThreadAfterMessageChange(thread);
  renderThreads();
  renderConversation();
  updateMessageInEncryptedHistory(thread, message).catch((historyError) => console.error(historyError));
}

function privateMessageShouldShowManualActions(message) {
  if (!message?.privateManualRetryAvailable) return false;
  if (message.privateSendRetryKey && privateSendRetryJobs.has(message.privateSendRetryKey)) return false;
  if (message.privatePublishConfirmRetryKey && privatePublishConfirmJobs.has(message.privatePublishConfirmRetryKey)) return false;
  if (message.publishState?.status === CAPSULEHUB_PUBLISH_STATUS_CONFIRMED) return false;
  if (messageStatusKey(message) !== 'failed') return false;
  const meta = String(message.meta ?? '').toLowerCase();
  if (meta.includes('published')
    || meta.includes('sending')
    || meta.includes('submitted')
    || meta.includes('confirming')
    || meta.includes('retrying send')
    || meta.includes('checking rpc')) {
    return false;
  }
  return message.privateSendRetryStopped === true || message.privatePublishConfirmStopped === true;
}

function privateMessageManualActionsElement(thread, message) {
  // "My notes" is a notepad, not a conversation: deleting is a primary action there, and it is the ONLY way out of a
  // full notepad (the lane refuses to save rather than dropping the oldest note). Offered on every note.
  //
  // AN ICON IN THE HOVER CLUSTER, not a standing labelled button [owner 2026-08-04]. It joins Copy in the same
  // cluster, so the two are contiguous and the cluster's own rules place them — no per-button geometry to get wrong.
  // The label survives as the title/aria-label, which is what a screen reader and a tooltip read.
  if (isRealSavedThread(thread)) {
    const remove = document.createElement('button');
    remove.type = 'button';
    remove.className = 'row-reply-button row-note-delete-button';
    remove.title = t('notes.delete');
    remove.setAttribute('aria-label', t('notes.delete'));
    const icon = document.createElement('span');
    icon.className = 'icon icon-trash';
    icon.setAttribute('aria-hidden', 'true');
    remove.append(icon);
    remove.addEventListener('click', (event) => {
      event.stopPropagation();
      void deleteSelfNoteFromUi(thread, message, remove);
    });
    return remove;
  }
  if (!privateMessageShouldShowManualActions(message)) return null;
  const actions = document.createElement('div');
  actions.className = 'message-actions';
  const retry = document.createElement('button');
  retry.type = 'button';
  retry.textContent = t('common.retry');
  retry.addEventListener('click', async () => {
    retry.disabled = true;
    await retryPrivateMessageFromUi(thread, message).catch((error) => {
      markPrivateMessageManualRecovery({ thread, message }, error);
      console.error(error);
    });
  });
  actions.append(retry);
  if (message.privateCancelAvailable === true && privateMessageCanLocalCancel(message)) {
    const cancel = document.createElement('button');
    cancel.type = 'button';
    cancel.textContent = t('common.cancel');
    cancel.addEventListener('click', () => {
      cancelPrivateMessageFromUi(thread, message);
    });
    actions.append(cancel);
  }
  return actions.children.length > 0 ? actions : null;
}

/**
 * Delete one note: confirm, remove it locally, then republish the snapshot.
 *
 * The republish is NOT optional. The chunks on chain are the durable copy, so a note removed only locally comes
 * straight back on the next restore — and the freed space, which is the entire reason the user is deleting, would
 * never materialise. If the republish fails the note is put BACK, so the local view never diverges from the chain
 * silently: the user sees the same notepad they had, plus a reason.
 */
async function deleteSelfNoteFromUi(thread, message, button) {
  if (!thread?.messages?.includes(message)) return;
  // A save on top of an incomplete read would overwrite chunks we could not see — deleting has exactly the same
  // hazard as writing, so it is held by the same guard rather than being allowed through as "just a removal".
  if (selfNotesRestoreIncomplete) { flashWalletIdentityStatus(t('notes.restoreIncomplete')); return; }
  const confirmed = await openActionDialog({
    title: t('notes.deleteTitle'),
    hint: t('notes.deleteHint'),
    submitLabel: t('notes.delete'),
    fields: [],
    summary: [{ label: t('notes.deleteRowNote'), value: String(message.text ?? '').slice(0, 120) }],
  });
  if (!confirmed) return;

  const index = thread.messages.indexOf(message);
  if (index < 0) return;
  if (button) button.disabled = true;
  thread.messages.splice(index, 1);
  refreshThreadAfterMessageChange(thread);
  renderThreads();
  renderConversation();
  try {
    await publishSelfNotesSnapshotForThread(thread);
    // Durable history too: a record left behind here is merged back on the next restore, silently undoing the delete.
    if (message.localHistoryId) await encryptedMessageStore?.deleteMessage?.(message.localHistoryId);
  } catch (error) {
    // Put it back: the chain still holds it, and a local view that quietly disagrees with the durable copy is worse
    // than a failed delete.
    insertThreadMessage(thread, message);
    refreshThreadAfterMessageChange(thread);
    renderThreads();
    renderConversation();
    if (button) button.disabled = false;
    flashWalletIdentityStatus(shortUiErrorText(error, t('notes.deleteFailed')));
    if (!noteTonRpcRateLimit(error)) console.warn('[notes] delete failed', error);
  }
}

async function retryPrivateMessageFromUi(thread, message) {
  if (!thread?.messages?.includes(message)) return;
  clearPrivateSendRetry(message);
  clearPrivateMessageManualRecovery(message);
  message.privateSendRetryStopped = false;
  message.privateSendRetryStoppedAt = null;
  message.privateSendRetryAttempt = 0;
  message.meta = 'sending';
  thread.state = 'pending';
  refreshThreadAfterMessageChange(thread);
  renderThreads();
  renderConversation();

  // clean-17 direct-pay: ONE path. The two Vault branches that used to sit here both keyed on a publishState —
  // re-arming the publish-nonce re-broadcast for an already-signed external, and pre-checking the Vault hold
  // before re-sending — and the direct lane never creates one. The idempotent re-broadcast survives where it
  // belongs: inside attemptConvMessagePublishDirect, keyed on the captured signed BOC (same seqno, at most once).
  const context = privateSendRetryContextForMessage(thread, message);
  try {
    await runPrivateSendRetry(context);
  } catch (error) {
    await settlePrivateComposerSendError(context, error);
  } finally {
    refreshThreadAfterMessageChange(thread);
    renderThreads();
    renderConversation();
  }
}

function cancelPrivateMessageFromUi(thread, message) {
  if (!thread?.messages?.includes(message) || !privateMessageCanLocalCancel(message)) return;
  clearPrivateSendRetry(message);
  clearPrivatePublishConfirmRetry(message);
  thread.messages = (thread.messages ?? []).filter((item) => item !== message);
  refreshThreadAfterMessageChange(thread);
  renderThreads();
  renderConversation();
  if (privateComposerCostStatus && thread.id === activeThreadId) {
    privateComposerCostStatus.textContent = t('composer.messageCancelled');
    privateComposerCostStatus.dataset.state = 'ready';
  }
}

// clean-17 direct-pay CONV publish. Seals the composed document to the peer's KeyShard bundle and publishes every part
// into the conversation-direction RecordShard in ONE wallet transfer. Reuses the shared composer document/part model
// (messageDocumentBytesFromDraft + splitBytesToCapsuleParts) so a CONV body decodes exactly like every other private
// message; the ONLY swap vs the Vault path is the seal (createEncryptedConvCapsule / bucketKey) and the transport
// (publishConvLaneParts / RecordShard) instead of Vault→CapsuleHub. Gated behind privateLane.directPay.
//
// clean-17 first contact (INTRO) direct-pay. A conversation has no K_root until an INTRO mints one, so a peer who has
// never been introduced needs TWO on-chain writes and this function performs both, in one slot of the outgoing queue:
// an INTRO that mints the pairwise K_root and carries NOTHING ELSE, then the user's message on the ordinary CONV lane.
//
// Resolve the recipient's KeyShard bundle (INTRO needs the scan key for the stealth view_tag), seal an empty INTRO,
// publish into a bucket the recipient scans, read back the CONTRACT created_at (never Date.now — a local clock forks a
// later re-INTRO [[reintro-kroot-adoption-invariant]]), adopt the minted K_root, stamp convPeerKeyId, and hand the
// message to the CONV lane. Gated behind privateLane.directPay.
//
// [CHANGED 2026-08-14] The INTRO used to carry the first message, which made that one message different from every
// other in two ways that both cost the user something: it lived on a transient, deliver-once carrier, and it could
// not be split into parts. Neither is true of a CONV record. The cost of the change is one extra publish per first
// contact (~0.019 GRAM, shown in the composer's own cost line, not in a new warning).
async function attemptIntroFirstContactDirect(context) {
  const { thread, message } = context;
  const selfKeyId = localRecipientKeyPair?.keyId;
  if (!selfKeyId || !localIdentity) throw new Error('Messaging identity is not ready');
  const transport = globalThis.plathoWalletRpcTransport ?? globalThis.plathoTonRpcTransport;
  if (!transport?.runGetMethod) throw new Error('INTRO direct-pay: RPC transport unavailable');
  if (!convKeyStore) convKeyStore = createMemoryConvKeyStore();
  // FRESH, never cached. [MEASURED 2026-08-02, owner's first sends on clean-17] This used to pass the call through
  // untouched, so it inherited runGetMethodCacheTtlMs = 15_000 — and the confirm loop below spans ~14s. Every retry
  // after the first therefore re-read the FIRST answer out of the client's own cache: one real request, fired in the
  // instant right after broadcast when the entry cannot possibly be visible yet, then five arguments with itself.
  // The INTRO was on chain within seconds every time (verified: bucket 0 of epoch 20667 holds all three sends), and
  // the client reported "on-chain time is not yet visible" regardless of how long anyone waited or how often they
  // resent. A retry that can be served from the cache of the attempt it is retrying is not a retry.
  const readEntry = createEntryReader((call) => transport.runGetMethod({ ...call, cacheTtlMs: 0, priority: 'critical' }));

  // IDEMPOTENT RETRY: a prior attempt already SIGNED (and maybe broadcast) this INTRO. Re-broadcast the SAME external
  // rather than minting a NEW capsule (new K_root/introNonce) + publishing again — a re-mint double-charges and, if the
  // two INTROs ordered differently on the two sides, could fork. The captured stealth fields (r/view_tag) + K_root drive
  // the confirm + adoption below identically. Only past the validity window is a fresh mint reached (old external dead).
  let sendState = message.introDirectSend;
  if (sendState?.boc && (Date.now() - sendState.at) <= DIRECT_SEND_REBROADCAST_WINDOW_MS) {
    // Through the NEXT door, not the one that already has these bytes: a retry exists because the first entry point
    // did not get them into a block, so re-knocking there is the one thing we know did not work. Once the chain has
    // moved past the signed seqno the re-sends STOP (the bytes can never execute now); the created_at confirm below
    // still runs, so an INTRO that did land is adopted and one that did not fails honestly — the old external is
    // never rebuilt before its validity window closes (a re-mint double-charges and can fork).
    if (!(Number(sendState.seqnoConsumedAt) > 0)) {
      const answer = await rebroadcastSignedExternal(sendState.boc, sendState.seqno ?? null, transport);
      if (answer.verdict === BROADCAST_VERDICT.REJECTED && await directSendSeqnoConsumed(sendState, transport)) {
        sendState.seqnoConsumedAt = Date.now();
      }
    }
  } else {
    // FRESH mint + publish (first attempt, or the prior external has expired so a re-mint cannot double-execute).
    // Resolve the recipient's FULL bundle from their KeyShard (by the wallet the thread targets — a KeyShard is
    // address-bound to its wallet, so the keys are authentic and the resolved keyId defines the peer).
    const peerWallet = requireBasechainAddress(await resolveRecipientWalletForThread(thread), 'Recipient wallet');
    const registry = requireBasechainAddress(requireProfileRegistryAddress(), 'ProfileRegistry');
    const provider = createKeyShardTonRpcProvider({ profileRegistryAddress: registry, decodeAddressSliceBoc: decodeTonAddressSliceBoc });
    const bundle = await resolveRecipientBundleByWallet({ provider, wallet: peerWallet, callOptions: criticalChainReadOptions() });
    const peerKeyId = bundle.keyId;

    // ENCODED HERE ONLY TO PROVE THERE IS SOMETHING TO SEND. These bytes no longer ride the INTRO; the CONV send
    // below re-encodes them from the same draft. Refusing an empty draft before spending anything on chain is worth
    // the duplicate encode.
    const draftBytes = messageDocumentBytesFromDraft(
      context.text, context.attachments, {},
      context.replyDraft === undefined ? privateReplyDraft : context.replyDraft,
      context.fileAttachments === undefined ? privateFileAttachments : context.fileAttachments,
      context.shareDraft === undefined ? privateShareDraft : context.shareDraft);
    if (!draftBytes) throw new Error('INTRO direct-pay: nothing to send');

    // THE INTRO CARRIES NO MESSAGE, and that is the whole point of this change.
    //
    // OWNER, 2026-08-14: the message inside an INTRO is lost over time, so the conversation ends up incomplete.
    // Correct, and it is a property of the carrier rather than a bug in it. An INTRO lives in an IntroShard, the scan
    // hands each
    // entry over exactly once (intro-cursor-store keeps its delivered set), and those shards are retired. A CONV
    // record lives in the conversation's own RecordShard for the retention window and is re-readable. So the first
    // message was the ONE message in every conversation stored on the transient lane, and a conversation that
    // outlives its first shard begins with a hole.
    //
    // It also made the first message the only one that could not be multipart: an INTRO is a single capsule, so an
    // image over the largest size class threw in the seal — measured by the owner at 33370 bytes against a 32768
    // ceiling, i.e. failing by the size of the handshake envelope alone. Sending the message down the ordinary lane
    // removes that ceiling instead of raising it.
    //
    // serializeIntroPayload has always encoded a missing first message as zero bytes, and the receive side already
    // guards on `bytes.length > 0`, so nothing on the wire or at the far end changes shape.
    const capsule = await createEncryptedIntroCapsule(bundle, localIdentity, {
      now: Date.now(), ...currentProfilePointerFields(),
    });
    const { r, viewTag } = introCapsuleStealthFields(capsule);

    const readScanPage = createScanPageReader((call) => transport.runGetMethod(call));
    const introEpochNow = Math.floor(Date.now() / 86400000);
    const slot = await pickIntroSendSlot({ readScanPage, epoch: introEpochNow });
    // Capture everything the confirm + adoption need BEFORE the broadcast, so an ambiguous throw still re-broadcasts.
    const pending = {
      at: Date.now(), boc: null, kRoot: capsule.kRoot, introNonce: capsule.introNonce,
      peerKeyId, peerWallet, epoch: slot.epoch, bucket: slot.bucket, expectedEntryId: slot.expectedEntryId, r, viewTag,
    };
    message.introDirectSend = pending;
    // Affordability before signing — this transfer had NO pre-flight at all, the only direct-pay send without one.
    // It matters here as much as on the message itself: an underfunded INTRO leaves a conversation half-opened (the
    // peer never learns the keys) while the wallet has already paid for whatever did land.
    await assertWalletGramAtLeast(
      INTRO_PUBLISH_VALUE + walletSendFeeReserveNanotons([capsule?.header0?.sizeClass ?? INTRO_CAPSULE_SIZE_CLASS]), 'send');
    try {
      const result = await publishIntroLane({ wallet: plathoWallet, transport, epoch: slot.epoch, bucket: slot.bucket, capsule, value: INTRO_PUBLISH_VALUE });
      pending.boc = result?.result?.boc ?? null;
      pending.seqno = result?.result?.seqno ?? null;   // an INTRO is one message = one external: top-level seqno is its seqno
    } catch (error) {
      if (!pending.boc && error?.builtBoc) { pending.boc = error.builtBoc; pending.seqno = error.builtSeqno ?? null; }
      throw error;
    }
    sendState = pending;
  }

  // Read back the CONTRACT created_at (fork-safety — the recipient stores THIS same value), using the captured stealth
  // fields so a re-broadcast retry confirms identically. Bounded retries cover the indexer lag right after broadcast.
  //
  // [WIDENED 2026-08-02] 6 attempts over ~14s was too short even with the caching bug above fixed. What has to happen
  // first is not one thing but three: the external reaches a validator, the transaction lands in a block, and the
  // endpoint's get-method view catches up to that block. MEASURED the same day: an entry confirmed present on chain
  // read back as ABSENT through toncenter and appeared only on a later poll. The old window could expire before the
  // write it was waiting for was observable through any endpoint, and the user was then told to resend something that
  // had already succeeded — at a fresh 0.0339 GRAM each time.
  let createdAtSec = null;
  for (let attempt = 0; attempt < 14 && createdAtSec === null; attempt += 1) {
    if (attempt > 0) await delay(Math.min(2000 * attempt, 8000));
    try {
      const confirmed = await confirmIntroCreatedAt({
        readEntry, epoch: sendState.epoch, bucket: sendState.bucket, fromEntryId: sendState.expectedEntryId, r: sendState.r, viewTag: sendState.viewTag,
      });
      if (confirmed) createdAtSec = confirmed.createdAt;
    } catch (error) { if (!noteTonRpcRateLimit(error)) console.warn('[intro] created_at confirm read failed', error); }
  }
  if (createdAtSec === null) {
    // FAIL CLOSED — never a local clock. adoptKRoot orders re-INTRO by createdAt, and the recipient stores the CONTRACT
    // created_at; a local time here would let the two sides disagree on which re-INTRO is newest and SILENTLY fork the
    // conversation. The INTRO is on chain and the send state is retained, so a resend RE-BROADCASTS (no re-mint) and
    // re-confirms — it does not establish the conversation on a guessed time. [intro-send review; reintro-kroot-adoption-invariant]
    const error = new Error('INTRO published, but its on-chain time is not yet visible — resend to establish the conversation');
    error.code = 'INTRO_CREATED_AT_UNCONFIRMED';
    throw error;
  }

  // Adopt the minted K_root (idempotent — re-upserting the same kRoot/introNonce is a 'duplicate' no-op) + stamp the thread.
  await convKeyStore.upsertConversationKRoot(selfKeyId, sendState.peerKeyId, {
    kRoot: sendState.kRoot, createdAt: createdAtSec, introNonce: sendState.introNonce, peerKeyId: sendState.peerKeyId, peerEncPublicKey: null, peerWallet: sendState.peerWallet,
  });
  thread.convPeerKeyId = sendState.peerKeyId;
  dropEmptyAnonymousTwin(thread, sendState.peerKeyId);
  scheduleRecoveryBackup(conversationId(selfKeyId, sendState.peerKeyId));   // a new K_root — back its slot up (debounced)
  // The INITIATOR side of the asymmetry (see followPeerChannelOnFirstReply): I chose to write to this person, so
  // following their channel is that same choice restated. Best-effort — a follow must never fail a first contact.
  followContactPublicChannel(sendState.peerWallet);

  globalThis.plathoLastIntroDirectSend = { peerKeyId: sendState.peerKeyId, epoch: sendState.epoch, bucket: sendState.bucket, createdAtSec };

  // AND NOW THE MESSAGE ITSELF, down the same lane as every message that will ever follow it.
  //
  // NOT EARLIER, and this is the one ordering the protocol fixes for us: a CONV capsule seals against the K_root
  // adopted three lines above, and that K_root binds to the INTRO's CONTRACT created_at. Until the confirm loop has
  // read that time back out of the shard there is no conversation to publish into — so "immediately after" is as
  // immediate as first contact can be, not a delay anyone chose.
  //
  // The dispatcher re-reads thread.convPeerKeyId, which is now stamped, so this lands on the CONV branch and cannot
  // recurse. Everything the first message needs — multipart splitting, the idempotent re-broadcast capture, the
  // delivery confirm that turns it green or red — is that branch's, already built and already exercised by every
  // other message. This function deliberately no longer marks anything: the message's state belongs to the send that
  // actually carries it.
  //
  // PARTIAL FAILURE IS SAFE. If the INTRO landed and this throws, convPeerKeyId is stamped and persisted, so the
  // retry routes straight here and never re-mints an INTRO. The user sees a red message next to an established
  // conversation, which is both true and recoverable — where the old path could report the whole first contact
  // delivered while the text it carried was already unreadable.
  return attemptConvMessagePublishDirect(context);
}

// How long a captured direct-pay external stays re-broadcastable. The wallet external is valid for ~300s (its
// timeout), so within this window a retry RE-BROADCASTS the SAME signed external (bound to its seqno → the chain runs
// it at most once, whether or not the first copy landed). Past this — comfortably beyond the 300s validity — the
// external is GUARANTEED dead, so a fresh rebuild cannot double-execute. [direct-pay send hardening]
const DIRECT_SEND_REBROADCAST_WINDOW_MS = 330_000;

/** The identical terminal-delivered bookkeeping both direct-pay send paths (and their idempotent re-broadcast) run. */
/**
 * The broadcast returned. That is NOT delivery, and this no longer claims it is.
 *
 * OWNER, 2026-08-05, on seeing a message go green and then closing the app: would it still reach the peer? The honest
 * answer was: maybe. 'published' used to be painted here, the instant toncenter accepted the POST — while the
 * external was still in flight and MEASURED to take 4-200s to reach a block. If the network then dropped it (which
 * it demonstrably does), the sender had already been told it was delivered, and nothing re-sent it once the app was
 * closed. The confirm driver reddened it — but only on the next launch, up to 24h later.
 *
 * So the green now waits for the chain: `armConvDeliveryConfirm` upgrades this to 'published' when it has actually
 * READ the record out of the shard. Until then the message stays in the sending bucket, which is the truth.
 */
function markDirectSendBroadcast(thread, message, options = {}) {
  clearPrivateSendRetry(message);
  clearPrivateMessageManualRecovery(message);
  // TWO HONEST ANSWERS, one per lane, and each says exactly what is known at this point:
  //
  //   'sending'   (default, CONV) — signed and handed to the network. A delivery confirm will read the shard and
  //               upgrade this to green, or redden it. The bucket is a PROMISE that something resolves it.
  //   'sent'      (awaitsConfirm:false, self-notes) — RecoveryShard slots are never read back. Nothing will ever
  //               resolve this, so 'sending' would hang forever and 'published' would be a claim we cannot support.
  //
  // [WAS THREE, 2026-08-14] A `verified: true` answer existed for the INTRO lane, which read its own entry back
  // inline and could honestly paint green on the spot. That lane no longer marks anything: an INTRO carries no
  // message now, so there is no message whose state it could own — it establishes the conversation and hands the
  // user's text to the CONV lane, which lands here through the default branch like every other message. The option
  // is gone rather than left unused: a branch nothing can reach, documenting proof nothing supplies, is how a
  // reader ends up trusting a mechanism that never runs.
  message.meta = options.awaitsConfirm === false ? 'sent' : 'sending';
  message.privateManualRetryAvailable = false;
  message.privateCancelAvailable = false;
  thread.state = 'sealed';
  refreshThreadAfterMessageChange(thread);
  updateMessageInEncryptedHistory(thread, message).catch((error) => console.error(error));
  refreshMessagingControls();
}

/**
 * ONE re-broadcast of already-signed bytes, through the carousel (or the primary when no doors are configured), that
 * REPORTS THE DOOR'S VERDICT instead of swallowing it. Never throws: a refused or broken door proves nothing about
 * delivery. `seqno` is the seqno the bytes were signed for; it rides with the POST so the answer can be read against it.
 * Returns { verdict, status, exitCode, door, error } — verdict is one of BROADCAST_VERDICT; exitCode is the TVM code a
 * chain rejection carried (broadcastThroughNextDoor / error.chainExitCode), or null — the public lane reads it.
 */
async function rebroadcastSignedExternal(boc, seqno, transport) {
  const rotated = await broadcastThroughNextDoor(boc, { seqno: seqno ?? null });
  if (rotated) return { verdict: rotated.verdict ?? BROADCAST_VERDICT.UNKNOWN, status: rotated.status ?? null, exitCode: rotated.exitCode ?? null, door: rotated.door ?? null, error: null };
  // DOORS-07: the primary sendBoc is a FALLBACK, reached only when no door is configured — never a second knock.
  if (!transport?.sendBoc || !plathoWallet?.address) return { verdict: BROADCAST_VERDICT.UNKNOWN, status: null, exitCode: null, door: null, error: null };
  try {
    await transport.sendBoc({ boc, walletAddress: plathoWallet.address, seqno: seqno ?? null });
    return { verdict: BROADCAST_VERDICT.ACCEPTED, status: 200, exitCode: null, door: 'primary', error: null };
  } catch (error) {
    return { verdict: error?.broadcastVerdict ?? BROADCAST_VERDICT.UNKNOWN, status: error?.status ?? null, exitCode: error?.chainExitCode ?? null, door: 'primary', error };
  }
}

/**
 * A DOOR SAID NO — is the signed seqno still open, or already spent? ONE fresh seqno read, on a rejection only.
 *
 * MEASURED on the owner's wallet: an external signed for N+1 while a recovery backup took N+1 from the same chain
 * state died with exit 133, and its re-broadcasts then collected 406 / 406 / 500 from the three doors every five
 * seconds for eight minutes, because nothing asked the one question that settles it. If the chain has moved PAST the
 * signed seqno, these bytes can never execute now — either they already did (the confirm will find the record) or
 * another external took the slot (it will not) — and re-sending them is pure noise either way. Returns true only
 * on that proof; an unreadable seqno or a record that never captured its seqno returns false and changes nothing.
 */
async function directSendSeqnoConsumed(send, transport) {
  const signed = Number(send?.seqno);
  if (!Number.isFinite(signed) || !plathoWallet?.address || !transport?.runGetMethod) return false;
  try {
    const chainSeqno = await getPlathoWalletSeqno(plathoWallet, transport);
    return Number(chainSeqno) > signed;
  } catch (error) {
    if (!noteTonRpcRateLimit(error)) console.warn('[send] seqno read after a rejected re-broadcast failed', error);
    return false;
  }
}

// ════════════════════════════════════════════════════════════════════════════════════════════════════════════════
// CONV DELIVERY CONFIRM DRIVER. The send path marks a message green OPTIMISTICALLY the moment the wallet external is
// broadcast — but a broadcast is not a landing: the publish can bounce (gate 13653, insufficient value) and the record
// never store, which is exactly the "money spent, nothing arrives" silent success the whole lane is built to avoid.
// This driver reads the shard back and either UPGRADES the message to verified or CORRECTS a false green to red.
//
// WHY THIS ONE IS CORRECT WHERE THE FIRST WAS NOT (reverted 2defbdc5). The first driver compared the shard's GLOBAL
// last_seq high-water: a LATER message reaching that seq while THIS one bounced false-confirmed the bounced message →
// silent loss. This driver matches THIS message's own frame_commit(s) — per-record, unique to its capsule — via
// confirmConvRecordsLanded, so a different write can never satisfy it. Three disciplines make it safe:
//   1. ABSENCE ≠ FAILURE. A read that could not complete (429/network) is transient — NEVER concluded as not-landed.
//      Only a CLEAN, COMPLETE scan (confirmConvRecordsLanded.complete) that reached the bottom counts.
//   2. LAG ≠ LOSS. A clean "not found" early on is indexer lag, not loss. Failure is declared ONLY past
//      CONV_CONFIRM_MAX_AGE_MS — well beyond both the ~300s external validity and any realistic indexer lag — so by
//      then a landed record WOULD be visible, and a subsequent resend safely REBUILDS (the external is provably dead).
//   3. CANCELLABLE + RE-ARMABLE. Every armed timer is tracked so teardown cancels it; unresolved sends re-arm on reload.
// MEASURED 2026-08-04 against live toncenter, five probes of the newest indexed transaction: the index runs
// 1-5 seconds behind the wall clock, median ~3s, and the masterchain head is 1s behind. The old first tick of 12s
// was calibrated when a send went through the Vault and the answer could not exist sooner; under direct pay the
// publish is one wallet transfer and TON has been sub-second since the April upgrade. Twelve seconds was not a
// safety margin any more, it was a stale number nobody re-measured.
//
// TIGHTENING IS SAFE BECAUSE THE READS ARE FRESH. The note in runConvDeliveryConfirm warns that ticks are "spaced
// wider than the 15s read cache" and that tightening the schedule would resurrect the INTRO bug — but the very next
// lines pass cacheTtlMs: 0 on both readers. The hazard was closed in code and the warning outlived it; a cached
// negative can no longer be served to a "has my write landed" question at any spacing.
//
// First tick at 4s clears the measured median with margin; the tail stays wide, because a message that has not
// landed in half a minute is not waiting on the indexer.
const CONV_CONFIRM_SCHEDULE_MS = [4_000, 9_000, 18_000, 30_000, 45_000, 60_000, 90_000, 120_000];
const CONV_CONFIRM_MAX_AGE_MS = 8 * 60 * 1000;   // TERMINAL: past ~8 min the external is long dead (>330s) and a landed record is indexed — decide now
// TERMINAL EARLY once the chain has PROVABLY moved past the signed seqno (convDirectSend.seqnoConsumedAt, stamped by
// the one seqno read a rejected re-broadcast triggers): the bytes can never execute now, so a landed record is either
// already indexed or never will be. Ten seconds covers the measured 1-5s index lag with margin; waiting out the full
// eight minutes only kept a dead message on "sending".
const CONV_CONFIRM_SEQNO_CONSUMED_TERMINAL_MS = 10_000;
const CONV_CONFIRM_BOUNDED_SCAN = 256;           // non-terminal ticks scan only the recent top (a landed message is there); the FULL record_count walk that proves ABSENCE runs once, at the terminal tick
const CONV_CONFIRM_REARM_MAX_AGE_MS = 24 * 60 * 60 * 1000;   // re-arm unresolved sends up to 24h after reload: well under RS_RETENTION (1y), so an absent shard is still "never deployed" (red correct), not "retired"
const convDeliveryConfirmTimers = new Map();     // message -> setTimeout handle, so teardown/re-arm can cancel it
let convDeliveryConfirmGeneration = 0;           // bumped on teardown so a tick begun before it becomes a no-op (no re-arm)

function cancelConvDeliveryConfirm(message) {
  const timer = convDeliveryConfirmTimers.get(message);
  if (timer !== undefined) { clearTimeout(timer); convDeliveryConfirmTimers.delete(message); }
}

/** Cancel every in-flight confirm — called on identity teardown so no timer fires against a torn-down transport. Bumps
 *  the generation so a tick ALREADY past its own timer (suspended on the shard read) cannot re-arm after this runs. */
function cancelAllConvDeliveryConfirms() {
  convDeliveryConfirmGeneration += 1;
  for (const timer of convDeliveryConfirmTimers.values()) clearTimeout(timer);
  convDeliveryConfirmTimers.clear();
}

/** Record what the confirm needs — commits + shard address + my highest part seq — onto message.convDirectSend
 *  (persisted with the message). maxSeq is the cheap authoritative floor: if the shard never reaches it, nothing landed. */
function captureConvDeliveryConfirmTarget(message, { address, epoch, commits, maxSeq }) {
  if (!message || !address || !Array.isArray(commits) || commits.length === 0) return;
  const send = message.convDirectSend ?? (message.convDirectSend = { boc: null, at: Date.now() });
  send.address = address;
  send.epoch = epoch;
  send.commits = commits.map((c) => BigInt(c).toString(16));   // bigint → hex string (survives JSON/history persistence)
  if (Number.isFinite(maxSeq)) send.maxSeq = Number(maxSeq);
}

function armConvDeliveryConfirm(thread, message, attempt = 0, options = {}) {
  const send = message?.convDirectSend;
  if (!send?.address || !Array.isArray(send.commits) || send.commits.length === 0) return;   // nothing to confirm
  if (message.convDelivery === 'verified' || message.convDelivery === 'unlanded') return;    // already resolved
  cancelConvDeliveryConfirm(message);                                                         // never double-arm
  const generation = convDeliveryConfirmGeneration;
  // A consumed seqno pins the next tick to its own short clock (see CONV_CONFIRM_SEQNO_CONSUMED_TERMINAL_MS) instead
  // of wherever the ladder had got to — the ladder was sized for indexer lag, not for a message already known dead.
  const delayMs = Number.isFinite(options.delayMs)
    ? Math.max(250, Number(options.delayMs))
    : CONV_CONFIRM_SCHEDULE_MS[Math.min(attempt, CONV_CONFIRM_SCHEDULE_MS.length - 1)];
  const timer = setTimeout(() => {
    runConvDeliveryConfirm(thread, message, attempt, generation).catch((error) => console.warn('[conv] delivery confirm tick failed', error));
  }, delayMs);
  convDeliveryConfirmTimers.set(message, timer);
}

async function runConvDeliveryConfirm(thread, message, attempt, generation) {
  convDeliveryConfirmTimers.delete(message);
  if (generation !== convDeliveryConfirmGeneration) return;               // a teardown ran after this tick was scheduled — abandon
  if (!thread?.messages?.includes(message)) return;                       // message/thread gone — drop the confirm
  const send = message.convDirectSend;
  if (!send?.address || !Array.isArray(send.commits) || send.commits.length === 0) return;
  if (message.convDelivery === 'verified' || message.convDelivery === 'unlanded') return;
  const transport = globalThis.plathoWalletRpcTransport ?? globalThis.plathoTonRpcTransport;
  const ageMs = Date.now() - Number(send.at ?? Date.now());
  // The chain moved past the signed seqno (stamped by rebroadcastPendingDirectSend / the retry path): the external is
  // provably dead, so the verdict comes on the short clock, not the eight-minute one.
  const consumedAgeMs = Number(send.seqnoConsumedAt) > 0 ? Date.now() - Number(send.seqnoConsumedAt) : -1;
  const seqnoTerminal = consumedAgeMs >= CONV_CONFIRM_SEQNO_CONSUMED_TERMINAL_MS;
  const reArm = () => {
    if (generation !== convDeliveryConfirmGeneration) return;
    // Re-read the stamp HERE: rebroadcastPendingDirectSend may have set seqnoConsumedAt during this very tick, and
    // the next tick belongs on the short clock from the moment of the stamp, not one ladder step later.
    const consumedNow = Number(send.seqnoConsumedAt) > 0 ? Date.now() - Number(send.seqnoConsumedAt) : -1;
    if (consumedNow >= 0 && consumedNow < CONV_CONFIRM_SEQNO_CONSUMED_TERMINAL_MS) {
      armConvDeliveryConfirm(thread, message, attempt + 1, { delayMs: CONV_CONFIRM_SEQNO_CONSUMED_TERMINAL_MS - consumedNow });
      return;
    }
    // Past the consumed terminal only an AUTHORITATIVE read can close the verdict; while reads keep failing (429,
    // network, keyless pump) the wait goes back on the ladder under the eight-minute bound — NEVER a 250 ms spin of
    // full shard walks (the negative remainder used to clamp to the floor). At the bound the message is left
    // unverified, exactly as it would be without a seqno stamp. [port review]
    if (ageMs < CONV_CONFIRM_MAX_AGE_MS) armConvDeliveryConfirm(thread, message, attempt + 1);
    else markConvDeliveryUnverified(thread, message);
  };
  if (!transport?.runGetMethod) { reArm(); return; }
  // FRESH, like the INTRO confirm. This lane was SAVED by its schedule rather than by its code: ticks at 12s/20s/30s
  // are spaced wider than the 15s read cache, so a cached negative expired between them. That was luck holding a
  // correctness property — a question of the form "has my write landed" must never be answerable from a cache filled
  // before the write. The cacheTtlMs: 0 below is what actually closes it, and it is why CONV_CONFIRM_SCHEDULE_MS
  // could be tightened to the measured index lag: the property now lives in the reads, not in the spacing.
  const readView = createRecordShardViewReader((call) => transport.runGetMethod({ ...call, cacheTtlMs: 0, priority: 'critical' }));
  const readRecord = createRecordShardRecordReader((call) => transport.runGetMethod({ ...call, cacheTtlMs: 0, priority: 'critical' }));
  const commits = send.commits.map((h) => BigInt('0x' + h));
  // Only the TERMINAL tick needs the authoritative full-shard walk (to prove ABSENCE via complete). Earlier ticks scan
  // just the recent top — a LANDED message is there and short-circuits to verified; a not-found stays inconclusive and
  // re-arms — so the up-to-record_count walk runs at most once, not on every tick. [confirm review: per-tick re-walk cost]
  const terminal = ageMs >= CONV_CONFIRM_MAX_AGE_MS || seqnoTerminal;
  let res;
  // clean-17 keyless coordination: pause the background index-walk sync for THIS confirm read only (not the whole
  // re-arm window) so on the paced ~1 rps keyless path the read gets the scarce budget without the walk interleaving;
  // between the spaced ticks the sync runs normally. No-op with a toncenter key (~8 rps headroom → no send latency).
  const endConfirmOutboundWork = usingKeylessTonRpc() ? beginPrivateOutboundWork() : null;
  try {
    res = await confirmConvRecordsLanded({ readView, readRecord, address: send.address, commits, minSeq: send.maxSeq ?? null, maxScan: terminal ? null : CONV_CONFIRM_BOUNDED_SCAN });
  } catch (error) {
    // TRANSIENT — a read I could not complete is NEVER "not landed". Retry within the age budget; past it, leave the
    // message optimistically green (the pre-driver residual) rather than falsely reddening it on an endpoint outage.
    if (!noteTonRpcRateLimit(error)) console.warn('[conv] delivery confirm read failed', error);
    reArm();
    return;
  } finally {
    if (endConfirmOutboundWork) endConfirmOutboundWork();
  }
  // Re-check the generation AFTER the await: a teardown during the shard read must not let this tick write state or
  // re-arm against a swapped-out wallet/transport. [confirm review: fire-after-teardown re-arm escape]
  if (generation !== convDeliveryConfirmGeneration || !thread?.messages?.includes(message)) return;
  if (res.landed) {
    message.convDelivery = 'verified';                                    // upgrade: proven on chain
    // THE GREEN IS PAINTED HERE, and only here. Before this the message sits in the sending bucket: the broadcast
    // returning is not delivery, and MEASURED the gap between the two is 4-200s. See markDirectSendBroadcast.
    message.meta = 'published';
    cancelConvDeliveryConfirm(message);
    refreshThreadAfterMessageChange(thread);
    renderThreads();
    renderConversation();
    updateMessageInEncryptedHistory(thread, message).catch((error) => console.error(error));
    refreshMessagingControls();
    return;
  }
  // Definitive non-delivery needs BOTH: the external is provably dead (past max age — it can never land now — OR its
  // seqno was consumed by the chain, see CONV_CONFIRM_SEQNO_CONSUMED_TERMINAL_MS) AND the read was authoritative —
  // the scan reached the bottom (res.complete) OR the shard never accepted my seq (res.seqShort: mine-only +
  // strictly-increasing ⇒ it never will now). Before that it is indexer lag, not loss — keep polling.
  if (terminal) {
    if (res.complete || res.seqShort) markConvDeliveryUnlanded(thread, message);
    else markConvDeliveryUnverified(thread, message);
    return;
  }
  // NOT FOUND YET, AND THE BYTES ARE STILL ALIVE — re-send them. This is the last hole in the send path: the wallet
  // re-broadcasts only while a send is running, so the FINAL external of a message had nobody watching it once the
  // call returned. MEASURED on the owner's wallet: that last external took 148s to reach a block on one send and
  // needed two re-broadcasts on another; if it is dropped and the user sends nothing else, only this driver is left.
  // A consumed seqno is the one case where re-sending is pointless: the bytes can never execute now.
  if (consumedAgeMs < 0) await rebroadcastPendingDirectSend(send, transport);
  reArm();
}

// Never re-send the same external more often than this. The confirm ticks accelerate early (4s, 9s, 18s...), and a
// duplicate costs a POST on the one serial RPC pump every message shares — so the gate is time, not tick count.
const DIRECT_SEND_CONFIRM_REBROADCAST_MS = 5_000;

/**
 * Re-offer the last signed external of a message the shard has not shown us yet.
 *
 * SAFE FOR THE ONE REASON THAT MATTERS: the external is bound to a wallet seqno, so the chain runs it AT MOST ONCE
 * however many copies arrive. This never rebuilds — a rebuild would bump the conversation seq and seal a new capsule,
 * which WOULD double-publish if the first copy was merely late.
 *
 * Bounded by the external's own validity: past `validUntil` the bytes can never be included, and re-sending them is
 * pure noise. The persisted record survives a reload, so an app that was CLOSED during the risky window resumes
 * re-sending when it reopens — which is exactly the case the owner asked about.
 */
async function rebroadcastPendingDirectSend(send, transport) {
  if (!send?.boc || !transport?.sendBoc || !plathoWallet?.address) return;
  if (Number(send.seqnoConsumedAt) > 0) return;   // the chain already moved past these bytes: nothing to re-send
  const now = Date.now();
  const validUntilMs = Number(send.validUntil) > 0
    ? Number(send.validUntil) * 1000
    : Number(send.at ?? 0) + DIRECT_SEND_REBROADCAST_WINDOW_MS;   // pre-v859 records carry no validUntil
  if (now >= validUntilMs) return;
  if (now - Number(send.lastRebroadcastAt ?? 0) < DIRECT_SEND_CONFIRM_REBROADCAST_MS) return;
  send.lastRebroadcastAt = now;
  // Rotate the entry point, do not re-knock: see broadcastThroughNextDoor. Falls back to the primary transport when
  // no doors are configured. The signed seqno rides along so the door's answer can be read against it.
  const answer = await rebroadcastSignedExternal(send.boc, send.seqno ?? null, transport);
  send.lastRebroadcastVerdict = answer.verdict;
  if (answer.verdict === BROADCAST_VERDICT.ACCEPTED) {
    // The INFO line means exactly one thing now: a door TOOK the bytes. It used to print on every attempt, including
    // the 406/406/500 ones, which made a rejected corpse look like a message patiently being re-sent.
    console.info('[conv] re-broadcast pending external while awaiting the shard', { seq: send.maxSeq ?? null, seqno: send.seqno ?? null, door: answer.door });
    return;
  }
  if (answer.verdict === BROADCAST_VERDICT.REJECTED) {
    // The chain refused these bytes. ONE fresh seqno read decides whether the slot is still open (keep offering the
    // bytes — the predecessor may still land) or already spent (stop: the confirm goes terminal on its short clock).
    console.warn('[conv] re-broadcast rejected by the chain', { seq: send.maxSeq ?? null, seqno: send.seqno ?? null, door: answer.door, status: answer.status });
    if (await directSendSeqnoConsumed(send, transport)) send.seqnoConsumedAt = Date.now();
    return;
  }
  // broken / refused / unknown: the SHARD READ is the verdict on delivery, never this POST. A failed re-send changes
  // nothing — the earlier copy may still land — so the confirm keeps polling instead of concluding anything here.
  if (answer.error && !noteTonRpcRateLimit(answer.error)) console.warn('[conv] pending re-broadcast failed', answer.error);
}

/**
 * The deadline passed and the read could prove NEITHER side — the scan never reached the bottom and the shard is not
 * past my seq, so "landed" and "lost" are both still open.
 *
 * This used to fall through and leave the optimistic green, which is the one case where staying silent is a lie in
 * BOTH directions. Neither red (a landed message must never be reddened) nor green (that is the claim we cannot
 * support) is honest here, so the message says exactly what is known: it went out, and we could not confirm it.
 * The status stays in the SENT bucket — this is not a failure, it is an unverified success.
 */
function markConvDeliveryUnverified(thread, message) {
  cancelConvDeliveryConfirm(message);
  if (!thread?.messages?.includes(message)) return;
  if (message.convDelivery === 'verified' || message.convDelivery === 'unlanded') return;
  message.meta = 'sent, not verified';
  refreshThreadAfterMessageChange(thread);
  renderThreads();
  renderConversation();
  updateMessageInEncryptedHistory(thread, message).catch((error) => console.error(error));
  refreshMessagingControls();
}

/** A false green corrected: the shard never stored this message. Red terminal status (no Retry button — the owner's
 *  chosen model, [[failed-send-ui-red-status-enough]]); the external is long dead so a fresh compose sends cleanly. */
function markConvDeliveryUnlanded(thread, message) {
  cancelConvDeliveryConfirm(message);
  if (!thread?.messages?.includes(message)) return;
  message.convDelivery = 'unlanded';
  message.meta = 'not delivered: the shard did not store it — resend';
  message.privateManualRetryAvailable = false;
  message.privateCancelAvailable = false;
  // The unlanded verdict is PROOF the records never existed — shed the pre-broadcast (shard, seq) claim exactly
  // as a failure before broadcast does (attemptConvMessagePublishDirect's catch). The dead anchor otherwise keeps
  // offering Reply on a message the peer can never see, keeps seeding the shard's seq mark at the next boot, and
  // can alias a sibling device's record committed under the very same seq.
  delete message.chainEntryId;
  delete message.chainLastEntryId;
  delete message.convShardAddress;
  thread.state = 'blocked';
  refreshThreadAfterMessageChange(thread);
  renderThreads();
  renderConversation();
  updateMessageInEncryptedHistory(thread, message).catch((error) => console.error(error));
  refreshMessagingControls();
}

/** Re-arm confirms for messages still unresolved after a reload (the timers do not survive a page load, the persisted
 *  convDirectSend does). Bounded by CONV_CONFIRM_REARM_MAX_AGE_MS (24h, not the 8-min terminal): a send reloaded AFTER
 *  the confirm window is exactly the one that must still be resolved — its first re-armed tick runs at age>=terminal and
 *  reddens a genuine bounce (or verifies a late-indexed land). Without covering past-8-min, a bounced green reloaded late
 *  stayed green forever = silent loss. [confirm review: persistence incomplete] */
function rearmConvDeliveryConfirms() {
  for (const thread of Array.isArray(threads) ? threads : []) {
    for (const message of thread?.messages ?? []) {
      const send = message?.convDirectSend;
      if (!send?.address || !Array.isArray(send.commits) || send.commits.length === 0) continue;
      if (message.convDelivery === 'verified' || message.convDelivery === 'unlanded') continue;
      if ((Date.now() - Number(send.at ?? 0)) >= CONV_CONFIRM_REARM_MAX_AGE_MS) continue;
      armConvDeliveryConfirm(thread, message, 0);
    }
  }
}

// FIRST CONTACT vs ESTABLISHED. A thread with no adopted conversation (no convPeerKeyId) is a not-yet-introduced peer:
// the FIRST message routes to attemptIntroFirstContactDirect, which mints the pairwise K_root via an INTRO (carrying
// that first message) and stamps convPeerKeyId — so every message after it lands here on the CONV lane.
// SEND HARDENING: an ambiguous broadcast is retried by RE-BROADCASTING the captured signed external (idempotent),
// never by rebuilding — a rebuild would bump the seq + seal a new capsule and double-publish if the first landed.
async function attemptConvMessagePublishDirect(context) {
  const { thread, message } = context;
  const selfKeyId = localRecipientKeyPair?.keyId;
  if (!selfKeyId || !localIdentity) throw new Error('Messaging identity is not ready');
  // The peer's messaging keyId, stashed on the thread by handleIntroFirstContact / the INTRO send. Absent ⇒ first
  // contact: send an INTRO (which mints the K_root and carries this message) instead of a CONV publish.
  const peerKeyId = thread?.convPeerKeyId ?? null;
  if (!peerKeyId) return attemptIntroFirstContactDirect(context);
  const transport = globalThis.plathoWalletRpcTransport ?? globalThis.plathoTonRpcTransport;

  // IDEMPOTENT RETRY: a prior attempt already signed (and maybe broadcast) this message's external. Re-broadcast the
  // SAME one rather than rebuilding — no seq re-bump, no new capsule, no double-publish. Only past the validity window
  // (below) is a rebuild reached, when the old copy is guaranteed expired.
  const captured = message.convDirectSend;
  if (captured?.boc && (Date.now() - captured.at) <= DIRECT_SEND_REBROADCAST_WINDOW_MS) {
    // Another door, same bytes — see broadcastThroughNextDoor. Falls back to the primary when no doors exist. Once the
    // chain has moved past the signed seqno there is nothing left to re-send: the confirm (armed below) settles it.
    if (!(Number(captured.seqnoConsumedAt) > 0)) {
      const answer = await rebroadcastSignedExternal(captured.boc, captured.seqno ?? null, transport);
      captured.lastRebroadcastVerdict = answer.verdict;
      if (answer.verdict === BROADCAST_VERDICT.REJECTED && await directSendSeqnoConsumed(captured, transport)) {
        captured.seqnoConsumedAt = Date.now();
      }
    }
    markDirectSendBroadcast(thread, message);
    armConvDeliveryConfirm(thread, message);   // re-broadcast re-arms on the SAME captured commits (idempotent)
    return { rebroadcast: true };
  }

  const rec = convKeyStore?.getConversation(selfKeyId, peerKeyId) ?? null;
  if (!rec?.kRootCurrent) throw new Error('CONV direct-pay: no K_root for this conversation — receive/adopt the INTRO first');
  if (!rec.peerWallet) throw new Error('CONV direct-pay: conversation has no peer wallet to resolve the reply bundle');

  // Resolve + VERIFY the peer's full bundle from their KeyShard: by the INTRO src wallet, gated so a wrong/hostile
  // src whose shard hashes to a different keyId is refused (resolvePeerReplyBundle). [Y reply-bundle resolution]
  const registry = requireBasechainAddress(requireProfileRegistryAddress(), 'ProfileRegistry');
  const provider = createKeyShardTonRpcProvider({ profileRegistryAddress: registry, decodeAddressSliceBoc: decodeTonAddressSliceBoc });
  const bundle = await resolvePeerReplyBundle({ provider, peerWallet: rec.peerWallet, peerKeyId, callOptions: criticalChainReadOptions() });

  // Build the composer document + split into capsule-sized parts (the shared private-composer model).
  const senderOptions = context.senderOptions ?? currentPrivateSenderOptions();
  const documentBytes = messageDocumentBytesFromDraft(
    context.text, context.attachments, {},
    context.replyDraft === undefined ? privateReplyDraft : context.replyDraft,
    context.fileAttachments === undefined ? privateFileAttachments : context.fileAttachments,
    context.shareDraft === undefined ? privateShareDraft : context.shareDraft);
  if (!documentBytes) throw new Error('CONV direct-pay: nothing to send');
  const documentParts = splitBytesToCapsuleParts(documentBytes, MAX_CAPSULE_USEFUL_BYTES, {
    perPartOverheadBytes: privateCompactPayloadOverhead(senderOptions),
  });
  assertPrivateComposerPartLimit(documentParts.length);

  // Route: the conversation-direction RecordShard for this send's timestamp (epoch + bucketKey + write keypair),
  // all derived from the adopted K_root with zero on-chain lookups.
  const createdAtSec = Math.floor(Date.now() / 1000);
  // THE SEAL MOMENT, kept on the echo. Every part's header1.createdAt is this second — the signed time a chain copy
  // of this message carries — while the echo's own time is the COMPOSER moment, and between the two sit the serial
  // publish lane, the keyless sync wait, the reply-bundle read, a retry: seconds on the keyless path, more than the
  // ±5 s CONV_OWN_ECHO_TIME_SLACK_MS allows. The echo's history record is first written AFTER this point
  // (markDirectSendBroadcast), so writeMessageToEncryptedHistory stamps the clear header with it: then the stored
  // own-send index (ownSendStoredNear) meets a copy read back beyond the loaded window within the 1 s floor instead
  // of letting it land as a duplicate bubble. An echo already in history keeps its stamp (the retry case). [review]
  message.convSealedAtMs = createdAtSec * 1000;
  const route = await outgoingRecordShard({ kRoot: rec.kRootCurrent, selfKeyId, peerKeyId, createdAtSec });

  // COLD-START SEQ FLOOR. If the local monotonic counter has no value for this (conversation, epoch) — the first send
  // of the day, or a reinstall that restored the K_root but not the per-epoch seq — seed it from the shard's on-chain
  // last_seq, or the send would reuse a seq already committed and bounce gate 13653. Only one read, only on that first
  // send; a fresh shard reads 0. [recovery-wiring review #0]
  let coldFloor = 0;
  if (rec.outgoingSeq?.[route.epoch] === undefined) {
    // FAIL CLOSED, and this used to fail OPEN. The catch here swallowed EVERY failure and carried on with 0 — a 429
    // on the keyless path, a timeout, an endpoint outage, all read as "nothing has ever been published here". When
    // the shard actually holds records, starting the outgoing seq at 0 is rejected by its anti-rollback gate (13653)
    // and the message never lands: a silent loss bought to avoid a visible retry. Only a shard with NO CODE proves
    // emptiness, and the reader now answers 0 for exactly that case and throws for everything else. A throw here
    // surfaces as a failed send and re-enters the retry ladder, which is the honest outcome.
    coldFloor = await createRecordShardLastSeqReader((call) => transport.runGetMethod(call))(route.address);
  }

  // Seal each part as a CONV capsule and assign a strictly-increasing outgoing seq (local monotonic counter,
  // floored by everything this device has seen on the shard — see the allocation below).
  const streamId = randomBytes(16);
  const parts = [];
  for (let index = 0; index < documentParts.length; index += 1) {
    const part = documentParts[index];
    const payloadBytes = encodeCompactPayload({
      type: 'document', bytes: part.bytes, sizeClass: part.sizeClass,
      streamId, partIndex: index, partCount: documentParts.length,
      // The sender's own .ath, so the recipient can show a name instead of an address.
      //
      // The sender WALLET stays out, deliberately and permanently: a CONV body seals to the peer's KeyShard bundle
      // and the identity on the wire is messaging-keys only. The USERNAME is a different thing — it was dropped as
      // collateral when the Vault composer path was deleted, not by any decision about it, and the proof is right
      // here: privateCompactPayloadOverhead has been reserving room for it in every split ever since, so each part
      // was already sized for bytes that never shipped.
      //
      // MEASURED 2026-08-03: without this the recipient had no source for the name at all. There is no reverse
      // wallet -> .ath index on chain (UsernameRegistry resolves name -> owner only), so the wire is the ONLY path.
      // Honours the anonymous toggle: includeSenderWalletMetadata === false leaves senderUsername undefined and
      // nothing is written.
      senderUsername: privateSenderUsernameMetadataLabel(senderOptions) ?? undefined,
      // MUST equal what createEncryptedConvCapsule will reserve, or the pre-encoded payload lands off every size class.
      // This used to name only the sender-recovery section and miss the 68-byte identity one, so every message after
      // the first contact threw "Compact payload must use a supported useful slot size". Shared helper now — the
      // formula lived in four places and the fifth copy is what broke.
      reservedTailBytes: compactPayloadReservedTailBytes({ senderRecovery: true }),
    });
    const capsule = await createEncryptedConvCapsule('', bundle, localIdentity, route.bucketKey, {
      payloadBytes, sizeClass: part.sizeClass, senderRecovery: true, now: createdAtSec * 1000,
      ...currentProfilePointerFields(),
    });
    // BOTH floors: the cold-start chain read (above) and the WARM one — the highest seq this device has SEEN on
    // this shard (read lane + confirmed sends, convBucketSeqMarks). The local counter alone is blind to records
    // committed by this wallet's OTHER devices; a device that fell behind would re-claim committed seqs and bounce
    // off the shard's anti-rollback gate on every send until its own counter caught up.
    const seq = await convKeyStore.nextOutgoingSeq(selfKeyId, peerKeyId, route.epoch, Math.max(coldFloor, convBucketSeqHighWater(route.address)));
    parts.push({ writePublicKey: route.writePublicKey, writeSecret: route.writeSecret, seq, epoch: route.epoch, capsule, value: CONV_PUBLISH_VALUE });
  }

  // MY OWN MESSAGE'S CHAIN ANCHOR — what makes a reply to it possible at all.
  //
  // OWNER, 2026-08-08: "I can only reply to the other person's messages." Correct, and the reason was that nothing
  // ever gave an outgoing message a chainEntryId: privateChainMessageOrderFields runs only on RECEIVED entries, and
  // every reply affordance (swipe, double-click, the hover button) is gated on the row carrying one. The mechanism
  // for the other half was fully built and documented — the conversation render has always given a row its entry
  // id the moment the send gains one — and had no writer, so it never ran once.
  //
  // The id is the publish seq, and it is known HERE rather than read back later: nextOutgoingSeq is the local
  // monotonic counter that IS the record's identity on the shard (floored by what this device has seen there), so
  // the peer stores this exact number for this exact message. MIN, not max, because a multipart message is anchored
  // by its FIRST record on both sides — the receiver takes orderedByChain[0] — and the parts are published with
  // strictly increasing seq in part order.
  //
  // Stamped BEFORE the broadcast, deliberately. Waiting for the delivery confirm would leave the message unrepliable
  // for the 4-200s that MEASURABLY separates a broadcast from a block, which is exactly when someone wants to add to
  // what they just said. If the send then fails, the anchor points at a record the peer does not have — but the peer
  // does not have the quoted message either, so the quote strip falls back to its snippet, which is the honest
  // rendering of "I am answering something you never received".
  message.chainEntryId = String(Math.min(...parts.map((part) => part.seq)));
  // …AND WHICH SHARD, for the same reason the receiver stamps it (privateChainMessageOrderFields): the next boot
  // rebuilds this outgoing shard's seq high-water from the echo (seedConvSeqMarksFromHistory) instead of re-opening
  // my own capsules, and the receive scan recognises MY OWN capsule read back from this shard as THIS echo
  // (findOwnEchoForChainCopy — an echo has no capsule id, so (shard, seq) is its only exact identity). A multipart
  // message also names its last record, as the receiver does, so that range is exact. [PWA-CONVRESTORE-02]
  message.convShardAddress = route.address;
  if (parts.length > 1) message.chainLastEntryId = String(Math.max(...parts.map((part) => part.seq)));

  let result;
  // Diagnostics for the send path, which had none. `sendInFlight` is what tells "the call never returned" apart from
  // "it threw and is retrying" — the dump could not distinguish those, and both render as the word "sending".
  globalThis.plathoConvSendInFlight = (globalThis.plathoConvSendInFlight ?? 0) + 1;
  const sendStartedAt = Date.now();
  try {
    // Affordability before signing. This matters MORE here than on the public lane: the wallet stamps
    // SendIgnoreErrors on every action, so an underfunded multi-part message loses its tail SILENTLY — and a
    // conversation part carries a CONSUMED seq (nextOutgoingSeq already advanced), so the dropped tail cannot be
    // re-sent under the same seq. Fail-open on an unreadable balance; the send stays the authority. INSIDE the
    // try, deliberately: an underfunded send must exit through the same catch as every other pre-broadcast
    // failure and shed its chain claim there.
    await assertWalletGramAtLeast(
      CONV_PUBLISH_VALUE * BigInt(parts.length)
        + walletSendFeeReserveNanotons(parts.map((part) => part.capsule?.header0?.sizeClass)), 'send');
    result = await publishConvLaneParts({ wallet: plathoWallet, transport }, parts);
    // seqno lives at result.result.seqno: publishConvLaneParts returns { parts, result } and `result` is what
    // sendPlathoWalletTransaction returned, which spreads the FIRST built external ({ boc, seqno, wallet }).
    // Reading result.seqno one level up silently produced null on every send — a diagnostic that reports nothing is
    // worse than none, because it looks like an answer. Caught 2026-08-04 by the owner's very first filled-in dump.
    globalThis.plathoLastConvSend = {
      ok: true,
      parts: parts.length,
      seqno: result?.result?.seqno ?? null,
      externals: result?.result?.batchCount ?? 1,
      ms: Date.now() - sendStartedAt,
    };
    // The LAST external — the only one still possibly in flight when the send returned (every earlier chunk was
    // waited out against the chain). `result.result` is the RPC RESPONSE, which carries no boc: this line used to
    // read from it and therefore persisted null on every successful send, leaving the whole re-broadcast path dead
    // except after a throw. `validUntil` travels with it because it is the only thing that says when these bytes
    // stop being re-sendable.
    message.convDirectSend = {
      boc: result?.result?.pendingBoc ?? null,
      // The seqno the pending external was SIGNED for: what a rejected re-broadcast is checked against.
      seqno: result?.result?.pendingSeqno ?? null,
      validUntil: result?.result?.pendingValidUntil ?? null,
      at: Date.now(),
    };
    // Record the parts' frame_commits + shard address + my highest seq for the delivery confirm (below). commits come
    // from the built parts, so a message that later reddens does so on the SAME per-record identity the shard stores.
    captureConvDeliveryConfirmTarget(message, { address: route.address, epoch: route.epoch, commits: result.parts.map((p) => p.commit), maxSeq: Math.max(...parts.map((p) => p.seq)) });
  } catch (error) {
    // Capture the signed external even on an AMBIGUOUS broadcast throw, so the retry re-broadcasts it (never rebuilds/
    // re-seals/re-bumps the seq). Without this a transient sendBoc failure whose external actually landed would
    // double-publish on the next attempt. Capture the commits too (from error.preparedParts) so a later re-broadcast
    // success can arm the confirm on them.
    // UNCONDITIONAL: this catch is only reachable past the idempotent re-broadcast branch, i.e. after a REBUILD with new
    // seqs — so the captured external is the NEW one and must replace whatever older (expired) boc was recorded.
    // Keeping the old record let the next Retry rebuild AGAIN while the new external might still land: double publish.
    if (error?.builtBoc) message.convDirectSend = { boc: error.builtBoc, seqno: error.builtSeqno ?? null, at: Date.now() };
    if (Array.isArray(error?.preparedParts)) captureConvDeliveryConfirmTarget(message, { address: route.address, epoch: route.epoch, commits: error.preparedParts.map((p) => p.commit), maxSeq: Math.max(...parts.map((p) => p.seq)) });
    // NOTHING LEFT THE DEVICE (no signed external captured — the affordability gate, a build or a signing
    // failure): the pre-broadcast (shard, seq) stamp is now a claim about records that will never exist under our
    // bytes, while another device of this wallet may commit those very seqs with different messages [OWNER
    // 2026-08-26]. Shed the claim: without it the red echo can neither alias the foreign record
    // (findOwnEchoForChainCopy) nor seed the shard's seq mark (seedConvSeqMarksFromHistory). The consumed seqs
    // stay consumed — a gap on the shard is the safe direction, and a Retry re-runs the pipeline and stamps fresh.
    if (!error?.builtBoc) {
      delete message.chainEntryId;
      delete message.chainLastEntryId;
      delete message.convShardAddress;
    }
    // `broadcast` distinguishes the two outcomes that matter and that nothing recorded before: a throw with a signed
    // external attached means the request DID go out and the answer was lost (an ambiguous broadcast — the external
    // may well have landed), whereas no external means we failed before anything left the device.
    globalThis.plathoLastConvSend = {
      ok: false,
      parts: parts.length,
      ms: Date.now() - sendStartedAt,
      broadcast: error?.builtBoc ? 'ambiguous' : 'none',
      status: error?.status ?? null,
      code: error?.code ?? null,
      error: String(error?.message ?? error).slice(0, 160),
    };
    throw error;
  } finally {
    globalThis.plathoConvSendInFlight = Math.max(0, (globalThis.plathoConvSendInFlight ?? 1) - 1);
  }

  globalThis.plathoLastConvDirectSend = { peerKeyId, epoch: route.epoch, parts: parts.length, to: result?.parts?.[0]?.to ?? null };
  markDirectSendBroadcast(thread, message);
  armConvDeliveryConfirm(thread, message);   // verify the optimistic green (or correct it to red) in the background
  // The RECIPIENT side of the asymmetry: replying is the moment they chose to engage, so this is where their follow
  // is legitimate — never on receipt, which would let a first-contact blast into everyone's feed.
  followPeerChannelOnFirstReply(thread, rec?.peerWallet);
  return result;
}

async function attemptPrivateComposerMessagePublish(context) {
  // A note to YOURSELF is not a conversation and cannot ride the CONV lane at all: that lane derives its bucket from
  // the DIRECTION between two keyIds, and self==self has none (conversationOrder refuses it by construction). Notes go
  // to the self lane the crypto layer reserves for self-data — named RecoveryShard slots, deterministic from the seed.
  if (isRealSavedThread(context?.thread)) return publishSelfNoteSnapshot(context);
  // clean-17 direct-pay: a CONV message is sealed to the recipient's KeyShard bundle and published straight from the
  // wallet into the conversation-direction RecordShard (attemptConvMessagePublishDirect). The removed Vault→CapsuleHub
  // publish machinery (publishState, publish nonce, confirm retry) is fully off the live send path; the composer
  // send handler still coordinates keyless sync + surfaces errors via settlePrivateComposerSendError around this call.
  return attemptConvMessagePublishDirect(context);
}

/**
 * Publish the whole "My notes" snapshot to the self lane. Unlike a CONV send this is not a per-message publish: the
 * note is ALREADY in the thread (the composer inserted it optimistically before calling here), so what goes on chain
 * is the current note list, packed into the named slots. Only chunks whose content actually changed are written, so a
 * new note usually costs ONE slot write.
 *
 * The notepad has a hard, measured ceiling (~7.4 KB per slot × the slot range). A full notepad REFUSES the write with
 * a localized message instead of dropping the oldest note: these are the user's notes and losing them quietly is the
 * failure this lane exists to prevent.
 */
async function publishSelfNoteSnapshot(context) {
  const { thread, message } = context;
  const seed = plathoWallet?.seed;
  if (!seed) throw new Error(t('notes.walletLocked'));
  const transport = globalThis.plathoWalletRpcTransport ?? globalThis.plathoTonRpcTransport;
  if (!transport?.runGetMethod) throw new Error(t('notes.rpcUnavailable'));

  // A save on top of an incomplete read would overwrite the chunks that read could not see. Refuse instead — the
  // note is already in the thread locally, and the next clean restore unblocks saving.
  if (selfNotesRestoreIncomplete) {
    const error = new Error(t('notes.restoreIncomplete'));
    error.code = 'PLATHO_NOTES_RESTORE_INCOMPLETE';
    throw error;
  }
  const wrote = await publishSelfNotesSnapshotForThread(thread);
  // Self-notes write RecoveryShard slots and are never read back — no verifier exists to lift this out of 'sending'.
  markDirectSendBroadcast(thread, message, { awaitsConfirm: false });
  return { selfNote: true, wrote };
}

/**
 * Pack the thread's notes and publish every chunk whose content changed. Shared by the send path and the delete
 * path — both do the same thing to the same snapshot, and duplicating the packing, the funds check and the transport
 * resolution is how the two would drift apart.
 *
 * Returns the number of slots written (0 when the on-chain copy already matches, which is a success, not a no-op to
 * be retried).
 */
async function publishSelfNotesSnapshotForThread(thread) {
  const seed = plathoWallet?.seed;
  if (!seed) throw new Error(t('notes.walletLocked'));
  const transport = globalThis.plathoWalletRpcTransport ?? globalThis.plathoTonRpcTransport;
  if (!transport?.runGetMethod) throw new Error(t('notes.rpcUnavailable'));
  const notes = selfNotesFromThread(thread);
  const readView = createRecoveryViewReader((call) => transport.runGetMethod(call));
  let built;
  try {
    built = await prepareNotesBackup({
      seed, notes, readView, value: RECOVERY_PUBLISH_VALUE, readStates: createSelfSlotStatesReader(),
    });
  } catch (error) {
    if (error?.code !== 'PLATHO_NOTES_FULL') throw error;
    const full = new Error(t('notes.full'));
    full.code = 'PLATHO_NOTES_FULL';
    throw full;
  }
  if (built.publishes.length === 0) return 0;
  await assertWalletGramAtLeast(
    // A notes publish carries no size class of its own — the SEALED blob is the payload, so its byte count decides
    // what the send costs. That count is `blobBytes`, carried out of sealNotesBlob deliberately: `blob` is a snake
    // CELL, and reading `.length` off it resolves to undefined and prices every slot as the smallest class — a
    // silent 5x under-reserve on a full notepad. (First written that way here; caught in review 2026-08-16.)
    RECOVERY_PUBLISH_VALUE * BigInt(built.publishes.length)
      + walletSendFeeReserveNanotons(built.publishes.map(
        (publish) => capsuleSizeClassForUsefulBytes(minimalCapsuleUsefulBytesForLength(publish.blobBytes)),
      )), 'save a note');
  await sendPlathoWalletTransaction(plathoWallet, {
    messages: built.publishes.map((publish) => ({
      address: publish.to, amount: publish.value, bounce: true,
      payload: tonCell.bytesToBase64(tonCell.serializeBoc(publish.body)), stateInit: publish.init,
    })),
  }, { transport });
  return built.publishes.length;
}

/** The note list a thread carries, oldest first: its own text messages, without the ones that carry no text. */
function selfNotesFromThread(thread) {
  return (thread?.messages ?? [])
    .map((message) => ({ at: messageCreatedAtMs(message) ?? 0, text: String(message?.text ?? '') }))
    .filter((note) => note.text.trim().length > 0)
    .sort((a, b) => a.at - b.at);
}

// clean-17 direct-pay: a send either broadcasts as ONE wallet transfer or throws. The Vault-era outcomes this
// function used to fan out on — a PARTIAL publish (some capsule parts accepted, some not, carried on a
// publishState) and a cancelled price-change dialog — cannot occur: nothing builds a publishState any more and
// there is no pre-sign price dialog to cancel. What remains is the honest three-way split below.
async function settlePrivateComposerSendError(context, error) {
  const { thread, message } = context;
  const rateLimited = noteTonRpcRateLimit(error);
  globalThis.plathoLastPrivateComposerSendError = {
    message: String(error?.message ?? error ?? ''),
    code: error?.code ?? null,
    phase: message?.meta ?? null,
    hasLocalHistory: Boolean(message?.localHistoryId),
    at: new Date().toISOString(),
  };
  if (isRecoverablePrivateSendError(error)) {
    schedulePrivateSendRetry(context, error);
  } else if (!message.localHistoryId) {
    markPrivateMessageManualRecovery(context, error, privateSendBlockedStatusText(error));
    if (privateComposerCostStatus) {
      privateComposerCostStatus.textContent = rateLimited ? TON_RPC_CONNECTING_STATUS : privateSendPreflightStatusText(error);
      privateComposerCostStatus.dataset.state = 'short';
    }
  } else {
    markPrivateMessageManualRecovery(context, error, privateSendBlockedStatusText(error));
  }
  if (privateComposerCostStatus) {
    if (isRecoverablePrivateSendError(error)) {
      refreshComposerCostStatus();
    } else {
      privateComposerCostStatus.textContent = rateLimited ? TON_RPC_CONNECTING_STATUS : privateSendPreflightStatusText(error);
      privateComposerCostStatus.dataset.state = 'short';
    }
  }
  refreshMessagingControls();
  if (!rateLimited && !isRecoverablePrivateSendError(error)) console.error(error);
}

async function runPrivateSendRetry(context) {
  const { thread, message } = context;
  if (!thread?.messages?.includes(message)) return;
  // The shared tonRpcLimited() gate is armed by ANY rate-limit — including the background body-sync
  // hammering the keyless toncenter indexer (~1 rps), which on a keyless build keeps it perpetually hot.
  // Don't let that READ-throttle starve a user's FIRST broadcast: a message that has never been
  // signed/sent (every part still BUILT, privateMessageHasPublishAttempt === false) is allowed through even
  // while the read-limiter is hot, relying on the send transport's own skipIfRateLimited/backoff.
  // (Toncenter-only: with no key, send /api/v3/message and reads /api/v3/messages share ONE ~1 rps
  // anonymous quota, so this is best-effort rather than a separate budget; with a key they share the 10 rps
  // key.) A message that HAS an attempt (some part SENT/SUBMITTED/UNKNOWN, possibly in-flight) keeps the
  // bail, so the key-gated no-double-spend re-sign path is NEVER entered while the limiter is hot.
  if (tonRpcLimited() && privateMessageHasPublishAttempt(message)) {
    schedulePrivateSendRetry(context, { message: TON_RPC_CONNECTING_STATUS, code: 'RATE_LIMITED' });
    return;
  }
  try {
    // Same lane as a fresh send: a burst that failed once would otherwise retry all of itself at once and rebuild
    // exactly the pile-up the queue exists to prevent. Only the ATTEMPT is queued — the backoff already elapsed in
    // the setTimeout that got us here, so a waiting retry never holds the lane.
    await enqueueOutgoingPublish(() => attemptPrivateComposerMessagePublish({ ...context }));
  } catch (error) {
    await settlePrivateComposerSendError(context, error);
  } finally {
    refreshThreadAfterMessageChange(thread);
    renderThreads();
    renderConversation();
  }
}

// ===== PUBLIC publish confirm driver (symmetric to the private one, owner audit 2026-07-02) =====
// A lightweight background job per not-yet-confirmed PUBLIC post/comment that reuses the SAME idempotent core
// as private sends: retryUnconfirmedVaultPublishBroadcasts (fresh-variant heal ladder, <=1 sendBoc per pass —
// the v630 lesson reused as code, not copied) + confirmCapsuleHubPublishEntries + the same cadence/terminal
// constants. Without it a deferred 2nd batch was NEVER POSTed (no healer) and its orphaned nonce poisoned the
// floor for every later send. Resume-on-reload works off the publishState already persisted in
// publicChannelFeedCache. NO re-sign surface here (phase 1): only fixed-nonce re-broadcasts -> no double-spend.
function findLocalPublicPendingRecord(channelId, localId) {
  const cached = publicChannelFeedCache?.[channelId]?.feed ?? publicChannelFeedCache?.[channelId] ?? null;
  const posts = cached?.posts ?? [];
  for (let i = 0; i < posts.length; i += 1) {
    if (posts[i]?.id === localId) return { kind: 'post', item: posts[i], postIndex: i };
    const comments = posts[i]?.comments ?? [];
    for (let j = 0; j < comments.length; j += 1) {
      if (comments[j]?.id === localId) return { kind: 'comment', item: comments[j], postIndex: i, commentIndex: j };
    }
  }
  return null;
}

// Write the driver's LIVE publishState (each feed sync rebuilds the cache via safeClone, detaching references)
// plus any patch back into the cached record, persist, repaint.
function persistPublicPublishProgress(job, patch = {}) {
  const located = findLocalPublicPendingRecord(job.channelId, job.localId);
  if (!located) return null;
  const cached = publicChannelFeedCache?.[job.channelId]?.feed ?? publicChannelFeedCache?.[job.channelId] ?? null;
  if (!cached) return null;
  const feed = { ...cached, posts: [...(cached.posts ?? [])] };
  // Strip the ~16×47KB pre-signed variant BoCs before persisting (same rule as publishStateForHistory for
  // private messages): the driver keeps them in ITS live publishState for rotation; a cross-reload resume
  // falls back to the single externalBoc. Persisting them would write ~1.5MB per status notify.
  const persistedState = publishStateForHistory(job.publishState);
  if (located.kind === 'post') {
    feed.posts[located.postIndex] = { ...located.item, publishState: persistedState, ...patch };
  } else {
    const post = { ...feed.posts[located.postIndex], comments: [...(feed.posts[located.postIndex].comments ?? [])] };
    post.comments[located.commentIndex] = { ...located.item, publishState: persistedState, ...patch };
    feed.posts[located.postIndex] = post;
  }
  feed.updatedAt = new Date().toISOString();
  publicChannelFeedCache = { ...publicChannelFeedCache, [job.channelId]: { feed, syncedAt: feed.updatedAt } };
  commitPublicChannelFeedCache();
  // STATUS-ONLY FAST PATH (public twin of the private-dialog rule: only the act of sending may move a
  // scroller): a publish status tick patches the badge text in place — the feed/comments DOM is NOT rebuilt,
  // so an active scroll is never interrupted. Structural transitions (badge appearing/disappearing, the
  // failed -> retryable wiring, the confirmed merge) fall through to the full render.
  const patchedItem = located.kind === 'post'
    ? feed.posts[located.postIndex]
    : feed.posts[located.postIndex].comments[located.commentIndex];
  if (!patchPublicPublishBadgesInPlace(job, patchedItem)) renderPublicSurface({ anchorUnread: false });
  return located;
}

// Update the live publish badge(s) for a pending record in place (feed article and/or post-detail comment —
// both carry data-publish-local-id). Returns false when the transition is structural or no badge is mounted,
// which sends the caller down the full renderPublicSurface path.
function patchPublicPublishBadgesInPlace(job, item) {
  const status = String(item?.publishStatus ?? '');
  if (!status || status.endsWith('failed')) return false;
  const localId = String(job?.localId ?? '');
  if (!localId) return false;
  const badges = document.querySelectorAll(`.public-publish-status[data-publish-local-id="${localId}"]`);
  if (badges.length === 0) return false;
  const text = (item.publishState ? publishStateMeta(item.publishState) : null) || status;
  for (const badge of badges) badge.textContent = text;
  return true;
}

// ─────────────────────────────────────────────────────────────────────────────────────────────────────────
// AN AMBIGUOUS PUBLIC BROADCAST IS NOT A FAILURE, and calling it one is what costs the user money.
//
// toncenter can answer 200 and not deliver, and a throw out of sendBoc leaves the external in exactly the same
// undecided state: it may already be on chain. The Vault path healed this with a re-broadcast + confirm driver.
// The direct public path had neither, so it wrote "public publish failed" over a post that might exist — and the
// only move that leaves the user is to post again, which DOUBLE-PUBLISHES it: two paid records, both authentic,
// no way to tell them apart. If it genuinely never landed, nothing ever resent it.
//
// The CONV lane already solves this and the public lane simply never got the same treatment: keep the SIGNED
// external and re-broadcast it verbatim. It is bound to ONE seqno, so the chain runs it AT MOST ONCE however many
// times it is sent — which is what makes resending safe where re-posting is not.
//
// Chain confirmation needs nothing new: the feed merge already retires a pending record once its chain twin with
// the same bodyHash appears. So the record stays PENDING (not "failed") while the external is still valid, and the
// existing no-progress deadline remains the honest terminal for the case where it really did not land.
const PUBLIC_REBROADCAST_MIN_INTERVAL_MS = 20_000;   // resume fires on every focus/pageshow; don't hammer the RPC
// Once the chain has moved past a retained external's signed seqno (publicDirectSend.seqnoConsumedAt) the bytes can
// never execute: stop re-sending, give the feed merge one sync to retire a twin that DID land, then terminal. The
// public twin of CONV_CONFIRM_SEQNO_CONSUMED_TERMINAL_MS; resume runs right after each visibility-ladder sync.
// (Named PUBLIC_SEQNO_CONSUMED_TERMINAL_MS in the 1.2.4 port; upstream's name from here on.)
const PUBLIC_CONSUMED_SETTLE_MS = 10_000;
// W5 `error::invalid_seqno`. MEASURED 2026-08-04 on the owner's wallet: a lite-server applying a stale external
// answers `cannot apply external message … exit code 133`. The code is SYMMETRIC (platho-wallet.mjs: "ahead by one ->
// 133, behind -> 133"): it also comes from a door whose node has not yet applied our previous external, i.e. for bytes
// that are still valid. So a 133 at re-broadcast is a reason to ASK the chain (directSendSeqnoConsumed, as the CONV
// twin does on every rejection), never the answer itself; rebroadcastPublicPublish logs it next to the verdict.
const WALLET_V5_INVALID_SEQNO_EXIT_CODE = 133;

/**
 * The patch for a throw that MAY have landed — or null when the failure is unambiguous.
 *
 * platho-wallet attaches error.builtBoc only once an external has been signed and handed to sendBoc. Its absence
 * therefore means the attempt died BEFORE the broadcast (build, funding, address derivation): nothing was signed,
 * nothing is on chain, and "failed" is the honest word. Its presence means the opposite may be true.
 */
function publicAmbiguousPublishPatch(error, status) {
  if (!error?.builtBoc) return null;
  return {
    publishStatus: status,
    // No validUntil on a throw (the wallet attaches only boc + seqno): resume falls back to the fixed window.
    publicDirectSend: { boc: error.builtBoc, at: Date.now(), seqno: error.builtSeqno ?? null, validUntil: null, rebroadcastAt: null },
  };
}

/**
 * The retained external of a send that RETURNED — the public twin of message.convDirectSend (PWA-PUBLIC-RETAIN-01).
 *
 * A door's 200 is a QUEUE, not an execution. Seen on the owner's wallet: toncenter accepted a post's external, another
 * external of the same wallet took its seqno first, the chain never ran the post — and because the public lane kept
 * the signed bytes ONLY on an ambiguous throw, nobody re-sent them and nobody read the verdict: the record sat on
 * "confirming" for the whole six-minute deadline and then went red over a post that a single re-send, or a single
 * seqno read, would have settled in seconds. The CONV lane captures result.result.pendingBoc/pendingSeqno/
 * pendingValidUntil on success for exactly this; the public lane now does the same, for posts and comments alike.
 *
 * `result` is what publishPublicLaneParts returned ({ parts, result }); `result.result` is the wallet send's answer,
 * whose `pending*` fields name the LAST external — the only one still possibly in flight. Null when the send carried
 * no boc to retain (nothing to re-send; the record keeps today's behaviour).
 */
function publicRetainedExternalFromSend(result) {
  const boc = result?.result?.pendingBoc ?? null;
  if (typeof boc !== 'string' || !boc) return null;
  return {
    boc,
    seqno: result?.result?.pendingSeqno ?? null,           // what a rejected re-broadcast is checked against
    validUntil: result?.result?.pendingValidUntil ?? null, // seconds; the only thing that says when re-sending stops
    at: Date.now(),
    rebroadcastAt: null,
  };
}

/**
 * Re-send a retained external. Stamps the attempt BEFORE sending so a failure cannot turn the next focus into a
 * broadcast loop, and swallows transport errors: the next pass retries while the window is open, and the deadline
 * terminal closes it out afterwards.
 */
async function rebroadcastPublicPublish(job, retained) {
  const transport = globalThis.plathoWalletRpcTransport ?? globalThis.plathoTonRpcTransport;
  if (!transport?.sendBoc || !plathoWallet?.address || !retained?.boc) return;
  persistPublicPublishProgress(job, { publicDirectSend: { ...retained, rebroadcastAt: Date.now() } });
  // The public lane rotates too. Every lane that re-sends already-signed bytes goes through the carousel: the
  // external is seqno-bound so the chain runs it at most once whichever door accepts it, and the door that already
  // failed to deliver is the least promising place to knock again. The door's VERDICT is kept: a chain rejection
  // triggers one fresh seqno read, and a consumed seqno stops the re-sends for good (resume terminals it).
  const answer = await rebroadcastSignedExternal(retained.boc, retained.seqno ?? null, transport);
  if (answer.verdict === BROADCAST_VERDICT.ACCEPTED) {
    console.info('[public] re-broadcast retained external', { localId: job?.localId ?? null, seqno: retained.seqno ?? null, door: answer.door });
    return;
  }
  if (answer.verdict === BROADCAST_VERDICT.REJECTED) {
    // THE CHAIN IS ASKED, NOT THE DOOR. Exit 133 (W5 invalid_seqno) is symmetric (WALLET_V5_INVALID_SEQNO_EXIT_CODE):
    // a door whose node has not yet applied our PREVIOUS external answers 133 to bytes that are still valid, so taking
    // it as "consumed" on the spot would stop the re-sends and terminal the record while the original copy lands. One
    // fresh seqno read settles it — what the CONV twin pays on every rejection; the exit code is kept for the log.
    const consumed = await directSendSeqnoConsumed(retained, transport);
    console.warn('[public] re-broadcast rejected by the chain', { localId: job?.localId ?? null, seqno: retained.seqno ?? null, door: answer.door, status: answer.status, exitCode: answer.exitCode ?? null, invalidSeqno: Number(answer.exitCode) === WALLET_V5_INVALID_SEQNO_EXIT_CODE, consumed });
    if (consumed) {
      persistPublicPublishProgress(job, { publicDirectSend: { ...retained, rebroadcastAt: Date.now(), seqnoConsumedAt: Date.now(), lastRebroadcastVerdict: answer.verdict } });
    }
    return;
  }
  if (answer.error && !noteTonRpcRateLimit(answer.error)) console.warn('[public] re-broadcast of a retained external failed', answer.error);
}

/**
 * MAKE A JUST-PUBLISHED POST GO GREEN ON THE INDEXER'S CLOCK, NOT ON THE FEED TIMER.
 *
 * The owner, 2026-08-04: "the private message went in a second, the public post took a while." Both lanes broadcast
 * the same way — one wallet transfer — and both drop an optimistic record on screen immediately. The difference was
 * entirely in what RETIRES the pending badge:
 *
 *   private — its own confirm ladder, armed the moment the send returns;
 *   public  — nothing. The record carried "public published, confirming" until the background feed sync happened to
 *             merge its on-chain twin, and that sync runs at most once every PUBLIC_BACKGROUND_SYNC_MS (30s), yields
 *             to any in-flight send, and is never triggered by the publish itself.
 *
 * So a post that was on chain in a second could sit visibly "confirming" for half a minute or more. Same work on the
 * wire, completely different clocks on screen.
 *
 * This closes it with the machinery that already exists rather than a second confirm driver: the feed merge already
 * retires a pending record when the chain twin with the same bodyHash appears (mergeLocalPendingPublicFeed), so the
 * only thing missing was asking sooner. Ticks follow the same measured index lag the CONV ladder now uses, and stop
 * as soon as nothing is pending — a landed post costs one extra sync, not a standing timer.
 */
const publicVisibilityTimers = new Set();
const PUBLIC_VISIBILITY_SCHEDULE_MS = [4_000, 9_000, 18_000];

function cancelPublicPublishVisibilityChecks() {
  for (const timer of publicVisibilityTimers) window.clearTimeout(timer);
  publicVisibilityTimers.clear();
}

/**
 * Is the post on screen carrying a comment of OUR OWN that has not been confirmed on chain yet?
 *
 * The bound on the only comment read that is not started by a user action. Both halves matter: the detail must be
 * OPEN (so this is the thread the user is looking at, never a walk over the feed), and something must actually be
 * pending (so a quiet screen reads nothing at all).
 */
function openPublicPostHasPendingComment() {
  if (!publicPostDetailOpen || !publicPostDetailItem) return false;
  return cachedCommentsForPost(publicPostDetailItem).some((comment) => isPendingPublicFeedItem(comment));
}

/** Is the post detail on screen showing THIS cached post (same channel key, same entry)? The only screen whose
 *  thread read (refreshPublicPostDetailComments -> retireConfirmedLocalPublicComments) can retire a pending comment. */
function publicPostDetailOpenFor(channelId, cachedPost) {
  if (!publicPostDetailOpen || !publicPostDetailItem || !cachedPost) return false;
  if (String(publicPostDetailItem.channelId ?? 'platho.app') !== String(channelId)) return false;
  return sameCachedPublicPost(cachedPost, publicPostDetailItem);
}

function anyPendingPublicFeedItem() {
  for (const entry of Object.values(publicChannelFeedCache ?? {})) {
    for (const post of entry?.feed?.posts ?? entry?.posts ?? []) {
      if (isPendingPublicFeedItem(post)) return true;
      for (const comment of post?.comments ?? []) if (isPendingPublicFeedItem(comment)) return true;
    }
  }
  return false;
}

// After the three fast checks, keep looking at this cadence while anything is still resolving. The fast ticks were
// calibrated to the indexer, but MEASURED 2026-08-05 a public-sized external can take 100-200s to reach a block —
// and if it is DROPPED, nothing was watching at all: the re-broadcast and the terminal verdict lived ONLY on
// focus/pageshow/restore, so a user who never left the tab got neither. The post then said "confirming" forever.
const PUBLIC_VISIBILITY_TAIL_MS = 30_000;

function schedulePublicPublishVisibilityChecks(attempt = 0) {
  const delayMs = PUBLIC_VISIBILITY_SCHEDULE_MS[attempt] ?? PUBLIC_VISIBILITY_TAIL_MS;
  const timer = window.setTimeout(async () => {
    publicVisibilityTimers.delete(timer);
    // Nothing pending any more (a background sync got there first, or the user cleared it) — stop, do not spend
    // reads proving something already proven.
    if (!anyPendingPublicFeedItem()) return;
    try { await syncPublicChannels(); } catch (error) { noteTonRpcRateLimit(error); }
    // The channel walk proves a POST landed. It says nothing about a COMMENT — those live in the post's THREAD
    // shard, which only this read touches. Without it a just-published comment kept its "confirming" badge until
    // the user closed and reopened the post (owner-reported 2026-08-13: the status freezes at "confirming").
    //
    // THE ONE EXCEPTION TO "comments load only on thread open" (PWA-PUBLIC-COMMENTS-BACKGROUND-FREE). That rule
    // exists for scale: no walker may read comments for posts nobody is looking at. This read is the opposite of
    // a walker — it is the OPEN post, and only while a comment THIS USER just published is still unconfirmed. It
    // stops the moment the record retires, which is what the whole ladder is waiting for anyway.
    if (openPublicPostHasPendingComment() && !publicPostDetailNewerCursor && !publicPostDetailJumpBusy) {
      // Skipped while the reader stands in a jumped window: the refresh's jump-exit REPLACE would teleport
      // them to the present mid-read (review finding 7). The confirmation retries again next pass.
      try { await refreshPublicPostDetailComments(); } catch (error) { noteTonRpcRateLimit(error); }
    }
    // Re-broadcast a retained external and pronounce the verdict past the deadline. Both used to happen only when
    // the window lost and regained focus.
    resumePendingPublicPublishConfirmations();
    // Keep going only while something is still WITHIN its deadline: a terminaled record keeps its publishStatus
    // (that flag marks the local copy the merge must carry, not work in progress), so gating on "anything pending"
    // would spin forever.
    if (anyPublicPublishStillResolving()) schedulePublicPublishVisibilityChecks(attempt + 1);
  }, delayMs);
  publicVisibilityTimers.add(timer);
}

/**
 * Is any published record still WORTH another look — i.e. pending and still inside the no-progress deadline?
 *
 * `isPendingPublicFeedItem` is true for a record that already lost ('public publish failed' is still a truthy
 * publishStatus, because that flag marks the local copy the feed merge must carry, not work in progress). Looping
 * on that predicate would never stop, which is why the tail below gates on this one instead.
 */
function anyPublicPublishStillResolving() {
  for (const entry of Object.values(publicChannelFeedCache ?? {})) {
    for (const post of entry?.feed?.posts ?? entry?.posts ?? []) {
      for (const item of [post, ...(post?.comments ?? [])]) {
        if (!isPendingPublicFeedItem(item)) continue;
        if (String(item.publishStatus ?? '').includes('failed')) continue;
        const createdAt = Date.parse(item.createdAt ?? '') || Date.now();
        if (Date.now() - createdAt < PRIVATE_PUBLISH_CONFIRM_NO_PROGRESS_DEADLINE_MS) return true;
      }
    }
  }
  return false;
}

function resumePendingPublicPublishConfirmations() {
  const channels = publicChannelFeedCache ?? {};
  for (const [channelId, entry] of Object.entries(channels)) {
    const posts = entry?.feed?.posts ?? entry?.posts ?? [];
    for (const post of posts) {
      const candidates = [{ item: post, kind: 'post' }, ...(post?.comments ?? []).map((comment) => ({ item: comment, kind: 'comment' }))];
      for (const { item, kind } of candidates) {
        if (!isPendingPublicFeedItem(item)) continue;
        const createdAt = Date.parse(item.createdAt ?? '') || Date.now();
        // A RETAINED EXTERNAL OUTRANKS THE DEADLINE. An ambiguous broadcast kept its signed external — and since
        // PWA-PUBLIC-RETAIN-01 so does a SUCCESSFUL one (publicRetainedExternalFromSend) — and while that external is
        // still valid the right move is to send it AGAIN — not to declare a failure over a post that may be on chain.
        // Same seqno, so the chain runs it at most once; if it had already landed, the feed merge retires this record
        // when the twin appears.
        const retained = item.publicDirectSend;
        // The record's honest terminal word: a comment that lost says "comment failed", as its own clear-failure
        // path already does — the consumed/deadline terminals used to stamp "public publish failed" on both.
        const failedStatus = kind === 'comment' ? 'comment failed' : 'public publish failed';
        // SEQNO CONSUMED: the retained bytes can never execute now. No more re-sends; after one short settle (the
        // visibility ladder has synced at least once meanwhile, so a twin that landed has had its merge) the record
        // is terminal — on this clock, not the six-minute one.
        const consumedAgeMs = Number(retained?.seqnoConsumedAt) > 0 ? Date.now() - Number(retained.seqnoConsumedAt) : -1;
        if (consumedAgeMs >= 0) {
          // A COMMENT IS NOT TERMINALLED WITHOUT A READ THAT COULD HAVE RETIRED IT. The settle's premise ("the ladder
          // has synced at least once, so a twin that landed has had its merge") holds for posts only: the channel walk
          // cannot see thread comments, and the one read that retires a pending comment (retireConfirmedLocalPublicComments,
          // from refreshPublicPostDetailComments) runs only while THIS post's detail is open. Since PWA-PUBLIC-RETAIN-01
          // every successful comment is re-sent once (exit 133 on an already-landed one -> seqnoConsumedAt), so with the
          // detail closed this branch stamped 'comment failed' over a comment that is on chain. With the detail closed
          // the record now simply stays 'confirming' (no re-sends either way: the seqno is spent) until the user opens
          // the thread and a CLEAN read settles it one way or the other. Residual: under degraded thread reads with
          // the detail open the terminal can still precede a clean read, and the 6-min deadline branch below keeps
          // its pre-port behaviour.
          if (consumedAgeMs >= PUBLIC_CONSUMED_SETTLE_MS && !(kind === 'comment' && !publicPostDetailOpenFor(channelId, post))) {
            persistPublicPublishProgress({ channelId, localId: item.id, publishState: null }, { publishStatus: failedStatus });
          }
          continue;
        }
        // Re-sendable while the external is VALID: its own validUntil when the send returned one (a successful send
        // retains it), else the fixed window for bytes captured off a throw (no validUntil on the error). Past it the
        // bytes are guaranteed dead and the deadline below is the last word.
        const retainedValidUntilMs = retained?.boc
          ? (Number(retained.validUntil) > 0 ? Number(retained.validUntil) * 1000 : Number(retained.at ?? 0) + DIRECT_SEND_REBROADCAST_WINDOW_MS)
          : null;
        if (retainedValidUntilMs !== null && Date.now() < retainedValidUntilMs) {
          if (Date.now() - Number(retained.rebroadcastAt ?? 0) >= PUBLIC_REBROADCAST_MIN_INTERVAL_MS) {
            void rebroadcastPublicPublish({ channelId, localId: item.id, publishState: null }, retained);
          }
          continue;
        }
        // clean-17 direct-pay: a public record NEVER carries a publishState (that was the Vault batch's healing
        // state), so the only thing left on resume is to terminal a record that has been sitting in its optimistic
        // 'sending' state past the no-progress deadline — instead of showing 'sending' forever. The external's
        // validity window (5.5 min) closes BEFORE this deadline (6 min), so a retained send always gets its
        // re-broadcasts first and this stays the honest last word. The Vault confirm driver that used to be started
        // for a publishState record is gone with the state itself.
        if (Date.now() - createdAt >= PRIVATE_PUBLISH_CONFIRM_NO_PROGRESS_DEADLINE_MS) {
          persistPublicPublishProgress({ channelId, localId: item.id, publishState: null }, { publishStatus: failedStatus });
        }
      }
    }
  }
}

/**
 * How many optimistic public records (posts + comments) this tab has placed in the feed.
 *
 * It exists so a FAILED send can tell the composer whether the user's text is already on screen. A failure
 * BEFORE the record is placed leaves the draft nowhere and it must come back; a failure AFTER it (the broadcast,
 * the balance pre-check) leaves it in the feed as a red row, and giving it back too would show the same text
 * twice. Counting at the two functions that place records is complete by construction — enumerating throw sites
 * instead would miss the next one added.
 */
let publicOptimisticRecordsPlaced = 0;

function rememberLocalPublicPost(text, bodyHash, commentsAllowed = true, attachment = null, options = {}) {
  publicOptimisticRecordsPlaced += 1;
  const channelId = ensurePublicChannelForAuthorWallet(plathoWallet?.address, {
    activate: false,
  });
  const profilePointer = currentProfilePointerFields();
  const cached = publicChannelFeedCache?.[channelId]?.feed ?? publicChannelFeedCache?.[channelId] ?? null;
  const feed = cached?.version === 1 && cached?.channelId === channelId
    ? { ...cached, posts: [...(cached.posts ?? [])] }
    : { version: 1, channelId, updatedAt: null, posts: [] };
  const attachments = normalizePublicImageAttachments(attachment);
  const blocks = options.blocks ?? displayBlocksFromDocumentBlocks(publicDocumentBlocksFromDraft(text, attachments));
  const localId = `local-${Date.now()}`;
  feed.posts.push({
    id: localId,
    text: messagePreviewFromBlocks(blocks) || text,
    blocks,
    imageUrl: blocks.length > 0 ? undefined : attachments[0]?.dataUrl,
    createdAt: new Date().toISOString(),
    // Same author label the chain sync will assign (username or short wallet) — never a placeholder 'you',
    // so the optimistic record looks identical to its merged on-chain twin (owner-flagged).
    author: publicAuthorLabel(plathoWallet?.address),
    authorWallet: plathoWallet?.address ?? null,
    profileVersion: profilePointer.profileVersion,
    avatarHash: profilePointer.avatarHash,
    avatarImageUrl: null,
    bodyHash,
    publishStatus: options.publishStatus ?? null,
    publishState: options.publishState ?? null,
    commentsAllowed: commentsAllowed !== false,
  });
  feed.updatedAt = new Date().toISOString();
  publicChannelFeedCache = {
    ...publicChannelFeedCache,
    [channelId]: { feed, syncedAt: feed.updatedAt },
  };
  commitPublicChannelFeedCache();
  rebuildThreadsFromPublicSubscriptions({ preserveActive: true });
  renderPublicSurface({ anchorUnread: false });
  renderThreads();
  renderConversation();
  // Reference for the public publish confirm driver (heal/confirm of a not-yet-confirmed publish).
  return { channelId, localId };
}

function rememberLocalPublicComment(parent, text, bodyHash, attachment = null, options = {}) {
  publicOptimisticRecordsPlaced += 1;
  const channelId = parent.channelId ?? publicChannelSubscriptions?.activeChannelId ?? publicChannelRegistry[0]?.id ?? 'platho.app';
  const profilePointer = currentProfilePointerFields();
  const cached = publicChannelFeedCache?.[channelId]?.feed ?? publicChannelFeedCache?.[channelId] ?? null;
  const feed = cached?.version === 1 && cached?.channelId === channelId
    ? { ...cached, posts: [...(cached.posts ?? [])] }
    : { version: 1, channelId, updatedAt: null, posts: [] };
  const index = feed.posts.findIndex((post) => sameCachedPublicPost(post, parent));
  const commentLocalId = `local-comment-${Date.now()}`;
  if (index >= 0) {
    const post = { ...feed.posts[index], comments: [...(feed.posts[index].comments ?? [])] };
    const attachments = normalizePublicImageAttachments(attachment);
    const blocks = options.blocks ?? displayBlocksFromDocumentBlocks(publicDocumentBlocksFromDraft(text, attachments));
    post.comments.push({
      id: commentLocalId,
      entryId: null,
      parentEntryId: String(parent.entryId),
      parentHash: parent.bodyHash,
      text: messagePreviewFromBlocks(blocks) || text,
      blocks,
      imageUrl: blocks.length > 0 ? undefined : attachments[0]?.dataUrl,
      createdAt: new Date().toISOString(),
      // Same author label the chain sync will assign (username or short wallet), identical to the merged twin.
      author: publicAuthorLabel(plathoWallet?.address),
      authorWallet: plathoWallet?.address ?? null,
      profileVersion: profilePointer.profileVersion,
      avatarHash: profilePointer.avatarHash,
      avatarImageUrl: null,
      bodyHash,
      publishStatus: options.publishStatus ?? null,
      publishState: options.publishState ?? null,
    });
    feed.posts[index] = post;
  }
  feed.updatedAt = new Date().toISOString();
  publicChannelFeedCache = {
    ...publicChannelFeedCache,
    [channelId]: { feed, syncedAt: feed.updatedAt },
  };
  commitPublicChannelFeedCache();
  rebuildThreadsFromPublicSubscriptions({ preserveActive: true });
  renderPublicSurface({ anchorUnread: false });
  // Reference for the public publish confirm driver (heal/confirm of a not-yet-confirmed publish).
  return { channelId, localId: commentLocalId };
}

function imagePartsForSend(attachment, label = 'image') {
  if (!attachment?.bytes?.length) return [];
  return splitBytesToCapsuleParts(attachment.bytes, MAX_CAPSULE_USEFUL_BYTES);
}

// fileAttachments is a PARAM (defaults to the live global) so the SEND path can capture it BEFORE the composer
// clears and thread the exact files through — otherwise the async publish would read an already-cleared global and
// drop the files (same capture-at-submit pattern private uses).
function publicDocumentBlocksFromDraft(text, attachments = publicImageAttachments, fileAttachments = publicFileAttachments) {
  // Explicit replyDraft + shareDraft: the PUBLIC surface reads its OWN drafts (publicCommentReplyTo /
  // publicShareDraft) — never the private composer's (composerBlocksFromDraft defaults to the private ones).
  const blocks = composerBlocksFromDraft(text, normalizePublicImageAttachments(attachments), publicCommentReplyTo, normalizePrivateFileAttachments(fileAttachments), publicShareDraft);
  if (blocks.length <= 0) return blocks;
  // The author's .ath rides every public post and comment, the way senderUsername rides every private message —
  // the public twin the surface never had. Only when a name is LINKED: an unlinked wallet claims nothing.
  const linkedLabel = readLinkedPlathoUsername(plathoWallet?.address)?.label ?? '';
  if (linkedLabel) blocks.push({ type: 'sender', username: canonicalUsernameDisplay(linkedLabel) });
  return blocks;
}

function publicDocumentBytesFromDraft(text, attachments = publicImageAttachments, fileAttachments = publicFileAttachments) {
  const blocks = publicDocumentBlocksFromDraft(text, attachments, fileAttachments);
  if (blocks.length <= 0) return null;
  return encodeMessageDocumentBlocks(blocks);
}

function publicSendPlanFromDocumentBytes(documentBytes) {
  const plan = [];
  if (!documentBytes) return plan;
  for (const part of splitBytesToCapsuleParts(documentBytes, MAX_CAPSULE_USEFUL_BYTES)) {
    plan.push({ type: 'document', bytes: part.bytes, sizeClass: part.sizeClass, usefulBytes: part.usefulBytes });
  }
  return plan;
}

function publicComposerSendPlan(text, attachments = publicImageAttachments, fileAttachments = publicFileAttachments) {
  return publicSendPlanFromDocumentBytes(publicDocumentBytesFromDraft(text, attachments, fileAttachments));
}

let prefsSyncInFlight = false;
// A monotonic token so a NEWER save (or a wallet change) supersedes a still-running background confirm from an
// older one — the stale confirm bails instead of stamping a wrong "saved"/"not saved".
let prefsConfirmGeneration = 0;
// Explicit "Save subscriptions" action: publish a full snapshot as a private capsule to self via the proven publish
// path. Only clears dirty on a CONFIRMED publish (a non-confirmed/failed one stays dirty so the user can retry).
// clean-17 DIRECT-PAY prefs snapshot: publish the seed-sealed prefs (subscriptions) blob to the NAMED recovery slot
// (PREFS_NAMED_SLOT_INDEX — its own address, separate from every conversation slot). A landed recovery publish IS the
// durable save (the slot's anti-rollback seq protects it, and the send-hardening re-broadcast covers an ambiguous
// broadcast), so there is no CapsuleHub-style background confirm. A reinstall restores it via restorePrefsFromRecoveryIfFresh.
async function submitPrefsSnapshotDirect() {
  if (prefsSyncInFlight) return;
  const seed = plathoWallet?.seed;
  if (!plathoWallet || !seed || !hasActivePlathoAccount()) { setText(savePrefsStatus, t('sync.activateFirst')); return; }
  if (tonRpcLimited()) { setText(savePrefsStatus, t('sync.rpcBusy')); return; }
  const transport = globalThis.plathoWalletRpcTransport ?? globalThis.plathoTonRpcTransport;
  if (!transport?.runGetMethod) { setText(savePrefsStatus, t('sync.rpcBusy')); return; }
  prefsSyncInFlight = true;
  refreshPrefsSyncUi();
  refreshGlobalSyncIndicator();
  setText(savePrefsStatus, t('sync.saving'));
  let settled = false;
  try {
    const snapshot = buildPrefsSnapshot();
    const savedEditEpoch = prefsEditEpoch;   // edits after this point are not in `snapshot` — guards the dirty-clear
    const prefsBytes = serializePrefsSnapshotBytes(snapshot);
    const readView = createRecoveryViewReader((call) => transport.runGetMethod(call));
    const built = await preparePrefsBackup({ seed, prefsBytes, readView, value: RECOVERY_PUBLISH_VALUE });
    await sendPlathoWalletTransaction(plathoWallet, {
      messages: [{ address: built.to, amount: built.value, payload: tonCell.bytesToBase64(tonCell.serializeBoc(built.body)), stateInit: built.init, bounce: true }],
    }, { transport });
    setPrefsLastSyncedAt(snapshot.writtenAt);
    if (prefsEditEpoch === savedEditEpoch) writePrefsDirty(false);   // a follow/unfollow mid-send stays dirty (→ "unsaved")
    settled = true;
  } catch (error) {
    const rateLimited = noteTonRpcRateLimit(error);
    setText(savePrefsStatus, rateLimited ? t('sync.rpcBusy') : t('sync.saveFailed'));
    if (!rateLimited) console.error(error);
  } finally {
    prefsSyncInFlight = false;
    if (settled) refreshPrefsSyncUi(); else refreshPrefsSyncButton();
    refreshGlobalSyncIndicator();
  }
}

async function publishPrefsSnapshot() {
  if (prefsSyncInFlight) return;
  return submitPrefsSnapshotDirect();
}

function prefsSyncedDateLabel(sec) {
  if (!sec) return '';
  try { return new Date(sec * 1000).toISOString().slice(0, 16).replace('T', ' '); } catch { return ''; }
}

function refreshPrefsSyncButton() {
  if (!savePrefsButton) return;
  // clean-17: prefs sync works on BOTH paths now — direct-pay publishes the seed-sealed blob to the named recovery slot
  // (submitPrefsSnapshotDirect), clean-15 via CapsuleHub. Enabled whenever there are unsaved changes.
  savePrefsButton.disabled = !(Boolean(plathoWallet && hasActivePlathoAccount()) && prefsDirty && !prefsSyncInFlight);
}

// Resting status for the Save-subscriptions row. A publish in flight owns the status text (saving/saved/failed);
// otherwise show whether there are unsaved changes and the last-synced date.
function refreshPrefsSyncUi() {
  refreshPrefsSyncButton();
  if (prefsSyncInFlight || !savePrefsStatus) return;
  let label;
  if (!plathoWallet) label = t('common.walletRequiredStatus');
  else if (prefsDirty) label = t('sync.unsaved');
  else if (prefsLastSyncedAt) label = t('sync.savedAt', { date: prefsSyncedDateLabel(prefsLastSyncedAt) });
  else label = t('sync.notSaved');
  setText(savePrefsStatus, label);
}

// When appConfig.privateLane.directPay is true, PRIVATE messaging runs on the clean-17 direct-pay shards: CONV
// messages publish straight from the wallet into RecordShard, first contact is scanned off IntroShard and its pairwise
// K_root adopted into the local conv key store, and durability writes go to RecoveryShard. DEFAULT OFF: clean-15 is the
// live genesis and the shards are not deployed yet, so the flag flips at clean-17 genesis alongside publicLane.directPay.
function privateLaneDirectPayEnabled() {
  return appConfig.privateLane?.directPay === true;
}

// PPH2 payload parts for a composed public post — mirrors createPublicPayloadParts' multipart plan, but calls the
// V2 builder (uniform 32-byte header, no profile pointer / parent id / is_profile — all removed in the shard model)
// and returns the client header/body cells the wallet builder consumes directly.
async function createPublicLanePayloadPartsV2({ type, text, attachments = publicImageAttachments, fileAttachments = publicFileAttachments, commentsAllowed = true, documentBytes = null }) {
  const documentParts = documentBytes ? publicSendPlanFromDocumentBytes(documentBytes) : publicComposerSendPlan(text, attachments, fileAttachments);
  const totalParts = documentParts.length;
  if (totalParts <= 0) return [];
  assertPublicComposerPartLimit(totalParts);
  const streamId = randomBytes(16);
  const createdAtSec = Math.floor(Date.now() / 1000);
  const payloads = [];
  for (let index = 0; index < documentParts.length; index += 1) {
    const part = documentParts[index];
    payloads.push(await createPublicPostPayloadV2({
      type: type === 'comment' ? 'document_comment' : 'document',
      bytes: part.bytes,
      commentsAllowed,
      streamId,
      partIndex: index,
      partCount: totalParts,
      createdAtSec,
    }, { sizeClass: part.sizeClass }));
  }
  return payloads;
}

// Publish a composed post DIRECT-PAY into the author's own CHANNEL shard. All N multipart parts ride ONE wallet
// transfer to the same shard (N entries grouped on read by streamId); the first carries the deploy, the rest publish.
async function submitPublicPostDirect(draft = null) {
  if (!plathoWallet?.address) throw new Error('Connect a wallet to publish to the public lane');
  const resolvedDraft = draft ?? {
    text: publicMessageInput?.value?.trim() ?? '',
    attachments: publicImageAttachments,
    fileAttachments: publicFileAttachments,
    commentsAllowed: publicComposerCommentsCheckbox?.checked !== false,
  };
  const attachments = normalizePublicImageAttachments(resolvedDraft.attachments ?? resolvedDraft.attachment);
  const fileAttachments = normalizePrivateFileAttachments(resolvedDraft.fileAttachments);
  const documentBlocks = publicDocumentBlocksFromDraft(resolvedDraft.text, attachments, fileAttachments);
  if (documentBlocks.length === 0) return null;
  setPublicStatus('public publish signing');
  const blocks = displayBlocksFromDocumentBlocks(documentBlocks);
  const payloads = await createPublicLanePayloadPartsV2({
    type: 'post',
    text: resolvedDraft.text,
    attachments,
    fileAttachments,
    commentsAllowed: resolvedDraft.commentsAllowed,
  });
  if (payloads.length === 0) return null;
  setPublicShareDraft(null);
  const ref = rememberLocalPublicPost(resolvedDraft.text, payloads[0]?.bodyHash, resolvedDraft.commentsAllowed, attachments, {
    blocks,
    publishStatus: 'sending',
    publishState: null,
  });

  // Derive the author's CHANNEL shard for the current era. keyArg is unused (0) for CHANNEL — the contract stamps
  // the real sender, so the partition_key over senderHash is what binds the shard to this wallet.
  const walletHash = publicWalletHash(plathoWallet.address);
  const partitionKey = await publicChannelPartitionKey(walletHash, 0);
  const epochTag = publicEpochTag(0, publicEraOf(0, Math.floor(Date.now() / 1000)));
  const value = publicPublishValueForKind(0);
  const parts = payloads.map((payload) => ({
    kind: 0, keyArg: 0n, header: payload.headerCell, body: payload.bodyCell, value, partitionKey, epochTag,
  }));
  const transport = globalThis.plathoWalletRpcTransport ?? globalThis.plathoTonRpcTransport;

  // Affordability before signing: the wallet stamps SendIgnoreErrors on every action (platho-wallet
  // `sendMode | 2`), so an underfunded MULTIPART post does not fail — the fundable prefix lands and the rest
  // is dropped silently, which the reader then discards as an incomplete stream (assemblePublicParts). The
  // user would see "public published" for a post that does not exist. Fail-open on an unreadable balance.
  await assertWalletGramAtLeast(
    value * BigInt(parts.length) + walletSendFeeReserveNanotons(payloads.map((payload) => payload.sizeClass)), 'publish');

  let result;
  try {
    result = await publishPublicLaneParts({ wallet: plathoWallet, transport }, parts);
  } catch (error) {
    // An external that was SIGNED and handed to sendBoc may already be on chain: keep it and resend, never call it
    // failed (see publicAmbiguousPublishPatch). A clear pre-broadcast failure still terminals immediately.
    const ambiguous = publicAmbiguousPublishPatch(error, 'public publish unconfirmed, retrying');
    if (ref) persistPublicPublishProgress({ ...ref, publishState: null }, ambiguous ?? { publishStatus: 'public publish failed' });
    setPublicStatus(ambiguous ? 'public publish unconfirmed, retrying' : 'public publish failed');
    throw error;
  }
  // Keep a TRUTHFY publishStatus: it is what marks the record pending (isPendingPublicFeedItem), and a pending
  // record is the only local copy the sync merge carries over. Under Vault, publishStatus:null meant CHAIN
  // CONFIRMED and was set together with entryId; setting it here on a mere broadcast made the record neither
  // pending nor chain-anchored (publicFeedPostHasChainAnchor), so the next background sync silently dropped
  // the just-published post from the feed. The pending copy retires by itself: the merge drops it once the
  // chain twin with the same bodyHash appears.
  // …AND KEEP THE SIGNED BYTES (PWA-PUBLIC-RETAIN-01): the 200 above queued them, nothing more. resume re-sends them
  // through the door carousel while they are valid and reads the verdict; a consumed seqno turns the record terminal
  // on the short clock instead of the six-minute one. Same shape as message.convDirectSend on the CONV lane.
  const retainedPost = publicRetainedExternalFromSend(result);
  if (ref) persistPublicPublishProgress({ ...ref, publishState: null }, { publishStatus: 'public published, confirming', ...(retainedPost ? { publicDirectSend: retainedPost } : {}) });
  // Ask the chain when the indexer can actually answer, instead of waiting for the 30s feed timer to come round.
  schedulePublicPublishVisibilityChecks();
  // Match the RECORD, which correctly says 'public published, confirming' one line above. The composer used to
  // announce a flat 'public published' on the broadcast return — the same optimistic claim the private lane was
  // making, just in the status line instead of on the post.
  setPublicStatus('public published, confirming');
  globalThis.plathoLastPublicPublish = { text: resolvedDraft.text, blocks, commentsAllowed: resolvedDraft.commentsAllowed, payloads, result, direct: true };
  return result;
}

// Publish/update the connected wallet's CHANNEL PROFILE (description + tags) as a normal public top-level POST whose
// body is a single PROFILE document block. It rides the identical public part-build + broadcast path, lands on the
// author's on-chain public_author_index, and is read back by resolveChannelProfile walking that author's chain.
// Latest profile post per author wins — no on-chain mutation of a prior profile, each save is a fresh post. Unlike a
// composer post, NO optimistic feed record is created: a profile is channel metadata, diverted from the visible feed.
// clean-17 channel profile: publish the profile document into BOTH the author's CHANNEL shard (already-subscribed
// readers pick it up via the profile divert) AND the BEACON directory (Discover finds NEW channels). Both parts ride
// ONE wallet transfer. The beacon bucket is deterministic (walletHash % PUBLIC_BEACON_READ_SPACE) so re-saving a
// profile idempotently updates the same beacon shard; the contract stamps publisher=sender(), so a beacon entry can
// only advertise the announcer's own wallet — which is exactly what makes it findable and self-attributing.
async function publishChannelProfileDirect(description, tags) {
  if (!plathoWallet?.address) throw new Error('Connect a wallet to publish a channel profile');
  const desc = String(description ?? '').trim();
  const normalizedTags = normalizeProfileTags(tags);
  const linkedLabel = readLinkedPlathoUsername(plathoWallet?.address)?.label ?? '';
  const ownerUsername = linkedLabel ? canonicalUsernameDisplay(linkedLabel) : '';
  const createdAtSec = Math.floor(Date.now() / 1000);
  const documentBytes = encodeMessageDocumentBlocks([{ type: 'profile', description: desc, tags: normalizedTags, ownerUsername }]);
  const [profilePayload] = await createPublicLanePayloadPartsV2({ type: 'post', documentBytes, commentsAllowed: false });
  if (!profilePayload) throw new Error('Channel profile produced no payload');

  const walletHash = publicWalletHash(plathoWallet.address);
  const bucket = Number(walletHash % BigInt(PUBLIC_BEACON_READ_SPACE));
  const channelPart = {
    kind: 0, keyArg: 0n, header: profilePayload.headerCell, body: profilePayload.bodyCell,
    value: publicPublishValueForKind(0), partitionKey: await publicChannelPartitionKey(walletHash, 0), epochTag: publicEpochTag(0, publicEraOf(0, createdAtSec)),
  };
  const beaconPart = {
    kind: 2, keyArg: BigInt(bucket), header: profilePayload.headerCell, body: profilePayload.bodyCell,
    value: publicPublishValueForKind(2), partitionKey: await publicBeaconPartitionKey(bucket), epochTag: publicEpochTag(2, publicEraOf(2, createdAtSec)),
  };
  const transport = globalThis.plathoWalletRpcTransport ?? globalThis.plathoTonRpcTransport;
  // Affordability before signing — the eighth direct-pay send, and the only one that never had this check. Both legs
  // ride ONE transfer under SendIgnoreErrors, so an underfunded save could land the channel write and drop the
  // beacon: a description saved but never discoverable, with nothing on screen saying so.
  await assertWalletGramAtLeast(
    channelPart.value + beaconPart.value
      + walletSendFeeReserveNanotons([profilePayload.sizeClass, profilePayload.sizeClass]), 'save a channel description');
  const result = await publishPublicLaneParts({ wallet: plathoWallet, transport }, [channelPart, beaconPart]);
  return { result, description: desc, tags: normalizedTags, ownerUsername, createdAtSec };
}

async function publishChannelProfile(description, tags) {
  return publishChannelProfileDirect(description, tags);
}

// Publish a comment DIRECT-PAY into the parent post's THREAD shard. The thread partition is f(post_uid), post_uid
// folds the parent's channel_pk + channel epoch_tag + entry_id — all carried on the opened post. keyArg = post_uid,
// which is exactly what the contract folds to verify a THREAD publish.
async function submitPublicCommentDirect(parent, bodyText = null, draftAttachments = publicImageAttachments, draftFileAttachments = publicFileAttachments) {
  if (!plathoWallet?.address) throw new Error('Connect a wallet to comment on the public lane');
  if (parent?.entryId === undefined || parent?.entryId === null) throw new Error('Public comment parent is not synced from a shard');
  const parentCoords = publicPostChainCoordinates(parent);
  if (!parentCoords) throw new Error('Public comment parent is missing its channel coordinates');
  if (parent.commentsAllowed === false) throw new Error('Comments are closed for this post');
  const text = bodyText?.trim() ?? publicMessageInput?.value?.trim() ?? '';
  const attachments = normalizePublicImageAttachments(draftAttachments);
  const fileAttachments = normalizePrivateFileAttachments(draftFileAttachments);
  const documentBlocks = publicDocumentBlocksFromDraft(text, attachments, fileAttachments);
  if (documentBlocks.length === 0) return null;
  setPublicStatus('comment signing');
  const blocks = displayBlocksFromDocumentBlocks(documentBlocks);
  const payloads = await createPublicLanePayloadPartsV2({ type: 'comment', text, attachments, fileAttachments });
  if (payloads.length === 0) return null;
  setPublicCommentReplyTo(null);
  setPublicShareDraft(null);
  const ref = rememberLocalPublicComment(parent, text, payloads[0]?.bodyHash, attachments, {
    blocks,
    publishStatus: 'sending',
    publishState: null,
  });

  // Derive the THREAD shard from the parent's coordinates. shardEntryId is the RAW per-shard entry_id post_uid
  // folds (parent.entryId is the collision-safe composite the feed cache uses). shardSeq comes from the same
  // source as the rest — defaulting it to 0 would address the wrong channel shard for an overflow-shard post,
  // and its thread would never be found.
  const channelPk = await publicChannelPartitionKey(publicWalletHash(parentCoords.authorWallet), parentCoords.shardSeq);
  const postUid = await publicPostUid(channelPk, parentCoords.epochTag, parentCoords.shardEntryId);
  const threadPk = await publicThreadPartitionKey(postUid, 0);
  const threadEpochTag = publicEpochTag(1, publicEraOf(1, Math.floor(Date.now() / 1000)));
  const value = publicPublishValueForKind(1);
  const parts = payloads.map((payload) => ({
    kind: 1, keyArg: postUid, header: payload.headerCell, body: payload.bodyCell, value, partitionKey: threadPk, epochTag: threadEpochTag,
  }));
  const transport = globalThis.plathoWalletRpcTransport ?? globalThis.plathoTonRpcTransport;

  // Same two rules as the post path: pre-check the wallet (SendIgnoreErrors drops unfundable actions silently)
  // and keep the record pending after broadcast until the chain twin appears.
  await assertWalletGramAtLeast(
    value * BigInt(parts.length) + walletSendFeeReserveNanotons(payloads.map((payload) => payload.sizeClass)), 'comment');

  let result;
  try {
    result = await publishPublicLaneParts({ wallet: plathoWallet, transport }, parts);
  } catch (error) {
    // Same rule as the post path — a signed external is retained and resent, not written off.
    const ambiguous = publicAmbiguousPublishPatch(error, 'comment unconfirmed, retrying');
    if (ref) persistPublicPublishProgress({ ...ref, publishState: null }, ambiguous ?? { publishStatus: 'comment failed' });
    setPublicStatus(ambiguous ? 'comment unconfirmed, retrying' : 'comment failed');
    throw error;
  }
  // Same retention as the post path (PWA-PUBLIC-RETAIN-01): a comment's external is queued by a 200 exactly as a
  // post's is, and was the twin that got forgotten here too.
  const retainedComment = publicRetainedExternalFromSend(result);
  if (ref) persistPublicPublishProgress({ ...ref, publishState: null }, { publishStatus: 'comment published, confirming', ...(retainedComment ? { publicDirectSend: retainedComment } : {}) });
  schedulePublicPublishVisibilityChecks();   // same clock as a post — a comment is the twin that gets forgotten
  // MATCH THE RECORD, which says "confirming" one line above. A broadcast is not a confirmation: toncenter's 200
  // means QUEUED, and an external whose seqno the chain has not reached is dropped outright. The post path was
  // corrected for exactly this and its twin here was not — the status line kept announcing a flat "published" the
  // moment sendBoc returned.
  setPublicStatus('comment published, confirming');
  return result;
}

// Console/debug surface. It carries only what a human can still MEANINGFULLY call: the direct-pay entry points
// and the message builders. Vault-era entries were removed as their lanes collapsed — an export that resolves to
// a dead branch is worse than no export, because it reads as a supported way in.
globalThis.plathoVaultTransactions = {
  createAthWalletMessage,
  createPublicPostPayload,
  createWalletTransaction,
  submitUsernameMint,
  submitProfileAvatarUpdate,
  submitVaultRegisterMessagingKeys,
  syncPrivateCapsulesFromChain,
};

async function refreshVaultActivationStatus(options = {}) {
  if (!plathoWallet?.address || !localVaultDraft?.message) {
    setText(vaultRecordStatus, plathoWallet ? t('vault.keysPending') : t('common.walletRequiredStatus'));
    refreshMessageActionStatuses();
    refreshComposerPublishPolicy();
    return null;
  }
  // clean-17 DIRECT-PAY activation: the "am I registered" signal comes from the user's OWN KeyShard (address-bound to
  // this wallet — it can only hold keys this wallet registered), NOT a Vault get_user. Synthesize the plathoVaultBinding
  // .user shape the ~15 activation consumers read ({ exists, current_key_id, auth_pubkey } — existence gates, never the
  // Vault key-id formula, which is gone with the Vault). auth_pubkey is the LOCAL auth key: KeyShard omits it by
  // privacy invariant, and for one's OWN identity the local key IS it.
  // The wallet a TRANSIENT failure should re-read for (PWA-ACTIVATION-04). Captured outside the try so the catch can
  // arm the ladder for exactly the wallet the read was issued for — never for whoever is current by then.
  let rereadFor = null;
  try {
    const registry = requireBasechainAddress(requireProfileRegistryAddress(), 'ProfileRegistry');
    const provider = createKeyShardTonRpcProvider({ profileRegistryAddress: registry, decodeAddressSliceBoc: decodeTonAddressSliceBoc });
    // CROSS-WALLET STAMP (the v739 class, carried over from the removed Vault get_user path): capture the wallet this
    // read is ISSUED for BEFORE the network await. A read for wallet A that resolves AFTER an in-app switch to B must
    // never be attributed to B — B's own refresh, queued behind this one, reads B.
    const forWallet = plathoWallet.address;
    const forWalletRaw = rawWalletAddress(forWallet);
    rereadFor = forWalletRaw;
    // A never-deployed shard (uninit) is a DEFINITIVE "not registered" → {exists:false}. Any OTHER read failure is
    // TRANSIENT and must NOT flip a registered user to "activate" (KeyShard registration is monotonic): rethrow to the
    // outer catch, which PRESERVES the existing binding. [activation review: transient read flips activated→activate]
    let view;
    try {
      view = await withVaultReadLock(() => provider.getView(forWallet, { verify: true, priority: 'critical', cacheTtlMs: 0 }));
    } catch (readError) {
      if (!isKeyShardUninitError(readError)) throw readError;
      view = { exists: false };
    }
    // Stale cross-wallet read: drop it whole rather than write a binding that names B and holds A's registration.
    if (!plathoWallet?.address || rawWalletAddress(plathoWallet.address) !== forWalletRaw) return globalThis.plathoVaultBinding ?? null;
    const localAuthPubkey = localVaultAuthKeyPair?.publicKey ? bytesToBigIntValue(localVaultAuthKeyPair.publicKey) : 0n;
    // Registered AND the stored keys are the CURRENT local ones (a local key rotation without re-register shows as
    // "activate", prompting the re-publish that updates the shard) — the address-binding already guarantees it is mine.
    const registeredMine = view?.exists === true
      && BigInt(view.enc_pubkey ?? 0n) === BigInt(localVaultDraft.message.enc_pubkey ?? 0n)
      && BigInt(view.sign_pubkey ?? 0n) === BigInt(localVaultDraft.message.sign_pubkey ?? 0n);
    if (!registeredMine) {
      globalThis.plathoVaultBinding = { walletAddress: forWallet, user: { exists: view?.exists === true, current_key_id: 0n }, keyRecord: null };
      clearPlathoActivationReread();   // a DEFINITE answer (not registered / keys rotated): nothing left to re-ask
      setText(vaultRecordStatus, t('vault.activationRequired'));
      refreshMessageActionStatuses();
      refreshMessagingControls();
      refreshComposerPublishPolicy();
      return null;
    }
    const user = {
      exists: true,
      current_key_id: BigInt(view.key_id),
      auth_pubkey: localAuthPubkey,
      key_generation: BigInt(view.key_generation ?? 0n),
      enc_pubkey: BigInt(view.enc_pubkey),
      sign_pubkey: BigInt(view.sign_pubkey),
      scan_pubkey: BigInt(view.scan_pubkey ?? 0n),
    };
    globalThis.plathoVaultBinding = { walletAddress: forWallet, user, keyRecord: null };
    clearPlathoActivationReread();   // DEFINITE: registered with the current local keys
    setText(vaultRecordStatus, t('vault.activated'));
    // The chain has just confirmed this wallet's keys are registered. Once per wallet, this is where the welcome
    // comes from — see maybeShowActivationWelcome for why the trigger is here and not at the activation send.
    maybeShowActivationWelcome(forWallet);
    refreshMessageActionStatuses();
    refreshMessagingControls();
    refreshComposerPublishPolicy();
    return globalThis.plathoVaultBinding;
  } catch (error) {
    // A transient read must NOT flip a registered user to "activate" — leave the binding untouched and show pending.
    if (!noteTonRpcRateLimit(error)) console.warn('[keyshard] activation status read failed', error);
    // …AND ASK AGAIN ON OUR OWN CLOCK (PWA-ACTIVATION-04). Only for the wallet this read was issued for, and only
    // when the failure happened at the read itself (rereadFor is null before the provider exists — a config fault
    // is not transient and gets no ladder). A wallet switched mid-read gets its own refresh from the switch.
    if (rereadFor && rawWalletAddress(plathoWallet?.address) === rereadFor) schedulePlathoActivationReread(rereadFor);
    setText(vaultRecordStatus, t('vault.keysPending'));
    refreshMessageActionStatuses();
    refreshComposerPublishPolicy();
    return globalThis.plathoVaultBinding ?? null;
  }
}

// ── Boot screen ──────────────────────────────────────────────────────────────────────────────
// A branded loading overlay that masks the several-second post-unlock initial sync. Visible from
// first paint (markup in index.html); the unlock password dialog opens on top (z-index), then it
// swaps to the spinner and lifts once the wallet+vault core is ready (messages keep loading behind).
const bootScreen = document.querySelector('#bootScreen');
let bootSignalCanvas = document.querySelector('#bootSignal');
let bootScreenActive = Boolean(bootScreen) && bootScreen.hidden !== true;
let stopBootSignalField = null;
let bootScreenSafetyTimer = null;
let bootScreenIdleFailsafe = null;

// Boot trace: a console-only [platho boot] line at each step, so a stuck boot can be diagnosed from the
// console without any visible UI. English-only (OPSEC).
function setBootDebug(step) {
  try { console.log('[platho boot]', step); } catch { /* ignore */ }
}

// The signal-field backdrop (ported from about.platho.app): a living teal lattice. Runs OFF the main thread
// on an OffscreenCanvas worker when supported (so it never freezes under the crypto-heavy boot — owner's ask),
// falling back to a main-thread loop otherwise. Returns a stop() that tears the animation down.
function startBootSignalField(canvas) {
  if (!canvas) return () => {};
  // THE LOADING SCREEN WEARS THE SAME BACKGROUND THE APP DOES [OWNER 2026-08-23: "if the user picks plasma, let it
  // slosh on the loading screen too; if they turned the background off, there must be none there either"]. The
  // choice is in localStorage and is read before anything starts, so this needs no app state to be up yet.
  if (backgroundMode === 'none') { canvas.hidden = true; return () => {}; }
  if (backgroundMode === 'plasma') return startBootPlasmaField(canvas);
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  const reduceMotion = Boolean(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
  // Preferred path: transfer the canvas to a worker and animate there, immune to main-thread jank.
  if (typeof Worker !== 'undefined' && typeof canvas.transferControlToOffscreen === 'function') {
    try {
      const worker = new Worker('./boot-signal-worker.js?v=2', { type: 'module' });
      const offscreen = canvas.transferControlToOffscreen();
      worker.postMessage(
        { type: 'init', canvas: offscreen, width: window.innerWidth, height: window.innerHeight, dpr, reduceMotion, ...nodesFieldOptions() },
        [offscreen],
      );
      const onResize = () => { try { worker.postMessage({ type: 'resize', width: window.innerWidth, height: window.innerHeight }); } catch { /* worker gone */ } };
      window.addEventListener('resize', onResize);
      return () => {
        window.removeEventListener('resize', onResize);
        try { worker.postMessage({ type: 'stop' }); } catch { /* ignore */ }
        try { worker.terminate(); } catch { /* ignore */ }
      };
    } catch (error) {
      // transferControlToOffscreen not actually usable here — fall through to the main-thread loop below.
      console.error(error);
    }
  }
  // Fallback: main-thread loop (can jank under heavy crypto, but works everywhere).
  const ctx = canvas.getContext('2d');
  if (!ctx) return () => {};
  const field = createBootSignalField(ctx, { reduceMotion, ...nodesFieldOptions() });
  field.resize(window.innerWidth, window.innerHeight, dpr);
  field.start();
  let raf = null;
  let stopped = false;
  const loop = (now) => { raf = null; if (stopped) return; field.tick(now); raf = requestAnimationFrame(loop); };
  const onResize = () => { field.resize(window.innerWidth, window.innerHeight, dpr); field.paintOnce(); };
  window.addEventListener('resize', onResize);
  if (!reduceMotion) raf = requestAnimationFrame(loop);
  return () => {
    stopped = true;
    if (raf !== null) { cancelAnimationFrame(raf); raf = null; }
    window.removeEventListener('resize', onResize);
  };
}

/**
 * The plasma, on the loading screen, when that is the chosen background.
 *
 * It paints on the SAME element the nodes field would use — the boot screen's own canvas — through the app's aurora
 * painter, on its own single-sun-set stage. ON THE MAIN THREAD, unlike the nodes worker: the plasma painter reads the
 * live theme token and the user's four sliders, and lifting all of that into a worker to keep a backdrop moving
 * during the crypto burst is a trade nobody asked for. The CSS spinner is composited and keeps turning either way.
 */
function startBootPlasmaField(canvas) {
  const screen = canvas.closest('.boot-screen');
  if (!screen) return () => {};
  canvas.hidden = true;   // that canvas belongs to the nodes field; this mode paints on its own layer
  // ITS OWN .aurora-layer, exactly as the app shell has one — NOT the boot canvas directly. The loop decides whether
  // a scene is on screen by `layer.offsetParent`, and offsetParent is null for a POSITION: FIXED element, which the
  // boot screen is: a scene hung on the screen itself was skipped on every frame and never painted a pixel
  // (measured). A layer is `position: absolute` inside it, so its offsetParent is the screen and the check works —
  // and z-index:-1 inside the screen's own stacking context puts the plasma above its background, under the brand
  // and the spinner, which is where the app shell puts it too.
  const layer = attachAuroraLayer(screen);
  const stage = createAuroraStage(auroraCount);
  const view = createAuroraView(layer, stage, 'shell');
  auroraScenes.push(view);
  auroraLastFrameAt = 0;
  startAuroraLoop();
  return () => {
    const sceneAt = auroraScenes.indexOf(view);
    if (sceneAt >= 0) auroraScenes.splice(sceneAt, 1);
    const stageAt = auroraStages.indexOf(stage);
    if (stageAt >= 0) auroraStages.splice(stageAt, 1);
    layer.remove();
  };
}

// Hard idle failsafe: the overlay must NEVER be eternal. If it is still up after 12s WITHOUT the unlock dialog
// open (i.e. we never reached the unlock, not that the user is slow to type), reveal the app anyway. Re-checks
// while the dialog is open so a user taking their time to unlock is never yanked out.
function armBootScreenIdleFailsafe() {
  if (bootScreenIdleFailsafe) clearTimeout(bootScreenIdleFailsafe);
  const tick = () => {
    if (!bootScreenActive) return;
    if (activeActionDialog) { bootScreenIdleFailsafe = setTimeout(tick, 5_000); return; }
    setBootDebug('idle-failsafe:reveal');
    hideBootScreen();
  };
  bootScreenIdleFailsafe = setTimeout(tick, 12_000);
}

function initBootScreen() {
  if (!bootScreenActive) return;
  setBootDebug('init');
  try {
    stopBootSignalField = startBootSignalField(bootSignalCanvas);
    // The chosen background rides the boot trace: which backdrop a boot ran with is the first thing to know when
    // someone reports the loading screen looking wrong, and the screen is gone by the time anyone can inspect it.
    setBootDebug(`init:field-ok:${backgroundMode}`);
  } catch (error) {
    setBootDebug(`init:field-err ${error?.message ?? error}`);
    console.error(error);
  }
  armBootScreenIdleFailsafe();
}

// Re-show the overlay for a RE-UNLOCK (resume after a background auto-lock): mask the app — the wallet is
// locked but the chat list was still showing behind the unlock dialog (privacy) — and host the dialog on the
// branded screen exactly like a cold boot. No-op during the initial boot (already active) or when there is
// nothing to unlock. bootCrypto's core-ready lift (markBootAppReady) hides it again after the re-unlock.
function showBootScreenForRelock() {
  if (!bootScreen || bootScreenActive) return;
  if (plathoWallet || !hasStoredPlathoWalletRecord()) return;
  setBootDebug('relock:show');
  bootScreen.dataset.phase = 'idle';
  bootScreen.classList.remove('is-hiding');
  bootScreen.hidden = false;
  bootScreenActive = true;
  // The OffscreenCanvas was transferred to the (now-terminated) cold-boot worker and cannot be reused — swap in
  // a fresh <canvas> before restarting the field.
  try {
    const fresh = document.createElement('canvas');
    fresh.className = 'boot-signal';
    fresh.id = 'bootSignal';
    fresh.setAttribute('aria-hidden', 'true');
    bootSignalCanvas.replaceWith(fresh);
    bootSignalCanvas = fresh;
    stopBootSignalField = startBootSignalField(bootSignalCanvas);
  } catch (error) {
    console.error(error);
  }
  armBootScreenIdleFailsafe();
}

// Idle (unlock dialog on top) -> loading (spinner). No-op once the screen is gone or was never up. The failsafe
// timer is armed on entering 'loading' — that is the only state where a milestone (post-unlock sync) could
// hang; 'idle' always resolves on its own (the unlock dialog is awaited and either unlocks or cancels).
function setBootScreenPhase(phase) {
  if (!bootScreenActive || !bootScreen) return;
  bootScreen.dataset.phase = phase;
  if (phase === 'loading' && !bootScreenSafetyTimer) {
    bootScreenSafetyTimer = setTimeout(() => hideBootScreen(), 45_000);
  }
}

// Drives the startup unlock DIRECTLY on the boot screen: opens the password dialog now (no visibility-gated
// deferral that races the overlay on a slow mobile cold-start), and keeps the overlay up until the wallet+vault
// core is ready (bootCrypto lifts it) or the user cancels.
async function runBootScreenUnlock() {
  try {
    setBootDebug('unlock:open');
    const wallet = await loadPlathoWallet();
    // Same rule as the resume path: this null is not evidence of a decision. Unlike that path it never had the
    // pending flag set in the first place (promptStoredWalletUnlockOnStartup runs only on the quick-start branch),
    // so before the resume path learned to arm, a cold start that lost its dialog for ANY reason was silent from
    // then until a manual unlock or a reload.
    if (!wallet) { setBootDebug('unlock:cancel'); markBootAppReady(); return; }
    // loadPlathoWallet already switched the overlay to the spinner phase on success.
    setBootDebug('unlock:ok');
    await bootCrypto();
    await enforceTelegramSeedBackupGate(wallet);
    flashWalletIdentityStatus(t('wallet.unlocked'));
  } catch (error) {
    setBootDebug(`unlock:err ${error?.message ?? error}`);
    markBootAppReady();
    console.error(error);
  }
}

// Posts painted UNDER the boot screen rose while nobody could see it; as the screen lifts, the feed on screen rises
// in for real (owner: the moment loaded posts appear to the reader must animate). Re-registers each article as fresh
// and restarts its animation (class off → reflow → on). A feed hidden behind another tab starts the rise when shown.
function surfaceFeedOnReveal() {
  if (!publicFeed) return;
  let index = 0;
  for (const node of Array.from(publicFeed.children)) {
    const key = node.dataset?.itemId;
    if (!key) continue;
    node.classList.remove('is-surfacing');
    void node.offsetWidth;
    publicFeedSurfacedIds.delete(key);
    if (surfaceRow(node, publicFeedSurfacedIds, key, index)) index += 1;
  }
}

function hideBootScreen() {
  if (!bootScreenActive || !bootScreen) return;
  setBootDebug('ready');
  bootScreenActive = false;
  try { surfaceFeedOnReveal(); } catch (error) { console.warn('[feed] reveal surfacing skipped', error); }
  if (bootScreenSafetyTimer) { clearTimeout(bootScreenSafetyTimer); bootScreenSafetyTimer = null; }
  if (bootScreenIdleFailsafe) { clearTimeout(bootScreenIdleFailsafe); bootScreenIdleFailsafe = null; }
  bootScreen.classList.add('is-hiding');
  const finalize = () => {
    bootScreen.hidden = true;
    if (typeof stopBootSignalField === 'function') { try { stopBootSignalField(); } catch { /* ignore */ } stopBootSignalField = null; }
  };
  // Remove after the fade; a fallback timer covers a missed transitionend (reduced-motion / display quirks).
  let done = false;
  const once = () => { if (done) return; done = true; bootScreen.removeEventListener('transitionend', once); finalize(); };
  bootScreen.addEventListener('transitionend', once);
  setTimeout(once, 620);
}

// The wallet+vault core is ready (keys derived, activation known) — messages keep loading behind the app.
function markBootAppReady() {
  hideBootScreen();
}

async function bootCrypto() {
  try {
    if (!plathoWallet) {
      const hasStoredWallet = hasStoredPlathoWalletRecord();
      const requiredStatus = hasStoredWallet ? t('wallet.unlockRequired') : t('common.walletRequiredStatus');
      await bootWalletScopedLocalStores();
      localIdentity = null;
      localVaultAuthKeyPair = null;
      localRecipientKeyPair = null;
      localSignedPublicBundle = null;
      localVaultDraft = null;
      clearMessageAutoSyncTimer();
      refreshMessagingControls();
      renderWalletIdentity();
      setText(encryptionStatus, requiredStatus);
      setText(keyAuthStatus, requiredStatus);
      vaultDraftStatus.textContent = requiredStatus;
      setText(vaultRecordStatus, requiredStatus);
      setText(vaultRotateStatus, requiredStatus);
      localProfileAvatarPointer = null;
      refreshComposerPublishPolicy();
      // No stored wallet (first run / public-only browsing): nothing to unlock or sync, so lift the boot
      // screen immediately. A stored-but-locked wallet keeps it up until the unlock dialog + core sync run.
      if (!hasStoredWallet) markBootAppReady();
      return null;
    }
    await bootWalletScopedLocalStores();
    renderWalletIdentity();
    localProfileAvatarPointer = readStoredProfileAvatarPointer(plathoWallet.address);
    // Restore the own avatar from the media cache right after unlock — before the sync and the first feed render —
    // so it does not flash the letter tile on reload; the tail refreshOwnProfileAvatar then confirms it on-chain.
    await restoreOwnAvatarFromCacheFast(plathoWallet.address).catch(() => {});
    localVaultAuthKeyPair = await deriveVaultAuthKeyPairFromWallet(plathoWallet);
    localIdentity = await loadMessagingIdentityFromWallet(VAULT_RECEIVE_CRYPTO_SUITE);
    localRecipientKeyPair = localIdentity?.encryptionKeyPair ?? null;
    localSignedPublicBundle = await exportSignedPublicKeyBundle(localIdentity, {
      purpose: appConfig.crypto?.signedBundlePurpose ?? 'pwa-runtime',
      ownerWallet: plathoWallet.address,
      // The deployment this identity belongs to. Under clean-17 that is the ProfileRegistry (the KeyShard register
      // path already binds to it), so the bundle cannot be replayed into a different generation of the contracts.
      vaultAddress: appConfig.profileRegistry?.address ?? null,
    });
    const verifiedBundle = await verifySignedPublicKeyBundle(localSignedPublicBundle);
    localVaultDraft = await createVaultMessagingKeyDraft(verifiedBundle.bundle, verifiedBundle.signingPublicKey, {
      authPublicKey: localVaultAuthKeyPair.publicKey,
    });
    globalThis.plathoRefreshVaultActivation = async (provider) => refreshVaultActivationStatus({ provider });
    setText(vaultRecordStatus, t('common.checking'));
    setText(vaultDraftStatus, t('common.checking'));
    await refreshVaultActivationStatus({ skipGlobal: true });
    // The crypto self-test is a DIAGNOSTIC-ONLY status indicator (~9 synchronous ML-KEM-768 ops:
    // keygen/encap/decap + tamper re-runs); it gates nothing functional. Running it inline here blocked
    // the first seconds after unlock on a slow single-thread device, compounding the post-unlock burst.
    // Show a neutral status now, run it deferred (after the first paint + sync start), and fill the real
    // verdict when it resolves — the message sync below proceeds immediately without waiting on it.
    setText(encryptionStatus, t('common.checking'));
    setText(capsulePolicyStatus, t('common.checking'));
    setText(keyAuthStatus, verifiedBundle.signingPublicKey.length === 32 ? t('vault.signedBundle') : t('vault.review'));
    refreshMessagingControls();
    // The wallet+vault core is ready here (keys derived, activation known) — reveal the app now. The message
    // sync below and the vault balance refresh keep running behind the live interface, as the owner asked.
    markBootAppReady();
    new Promise((resolve) => setTimeout(resolve, 0))
      .then(() => runPlathoCryptoSelfTest())
      .then((result) => {
        setText(encryptionStatus, result.hybrid.aadTamperRejected ? t('vault.hybridPassed') : t('vault.review'));
        setText(capsulePolicyStatus, result.capsule.replayRejected ? t('vault.replayGuarded') : t('vault.review'));
      })
      .catch((error) => {
        console.error(error);
        setText(encryptionStatus, t('vault.review'));
        setText(capsulePolicyStatus, t('vault.review'));
      });
    // After unlock, sync private messages immediately + arm the unified background loop — regardless of the
    // active tab, so messages are there the moment you open chats (the loop keeps running on every tab).
    beginMessageSyncUi();
    const syncResult = await syncPrivateCapsulesFromChainOnce({ mode: 'auto' }).catch((error) => {
      refreshMessagingControls();
      if (noteTonRpcRateLimit(error)) {
        failMessageSyncUi(t('sync.delayedLabel'));
      } else {
        failMessageSyncUi(t('sync.failedLabel'));
        console.error(error);
      }
      return null;
    });
    if (syncResult) completeMessageSyncUi(syncResult);
    // Refresh the OWN profile avatar here — the single canonical post-unlock spot — serialized AFTER the
    // activation + private-sync reads above and BEFORE the background loop / vault auto-refresh timers are
    // armed below, so no avatar read overlaps another chain read on iOS (v509 class). Cached avatars resolve
    // instantly (IndexedDB) so this rarely blocks; an uncached avatar pays one serial read, never a freeze.
    await refreshOwnProfileAvatar().catch((error) => console.error(error));
    scheduleMessageAutoSync();
    armIntroReceiveLane().catch((error) => console.warn('[intro] arm on unlock failed', error));
    if (isVaultViewActive()) {
      await refreshVaultNow({ includeActivation: true, includeStats: true }).catch((error) => {
        if (noteTonRpcRateLimit(error)) setVaultStatus('RPC busy, retrying');
        if (!isExpectedVaultProviderUnavailable(error)) console.error(error);
      });
    } else {
      scheduleVaultAutoRefresh(2_000);
    }
  } catch (error) {
    setText(encryptionStatus, t('vault.unavailable'));
    localVaultAuthKeyPair = null;
    setText(keyAuthStatus, t('common.blocked'));
    vaultDraftStatus.textContent = t('common.blocked');
    setText(capsulePolicyStatus, t('common.blocked'));
    refreshMessagingControls();
    setText(walletAddressStatus, t('common.blocked'));
    setText(vaultRecordStatus, t('common.blocked'));
    // Never strand the user behind the overlay on a boot error — show the app with its error statuses.
    markBootAppReady();
    console.error(error);
  }
}

initTelegramMiniApp();

if ('serviceWorker' in navigator && window.isSecureContext) {
  let serviceWorkerRefreshing = false;
  navigator.serviceWorker.addEventListener('controllerchange', () => {
    if (serviceWorkerRefreshing) return;
    serviceWorkerRefreshing = true;
    handleServiceWorkerControllerChange();
  });
  // ROOT-ABSOLUTE, not './sw.js': a permalink is served at /<name>/<post>, and a document-relative path would
  // register /<name>/sw.js — a 404 (or, on this server, the app shell) and no service worker at all.
  navigator.serviceWorker.register('/sw.js', { updateViaCache: 'none' })
    .then((registration) => registration.update().catch(() => null))
    .catch(() => {});
}

// The install state changes in exactly two places, and both are event handlers. This block used to claim they
// "can only fire after this module has finished evaluating" and called the quick-start refresh directly on that
// strength — FALSE: a top-level await suspends evaluation and turns the event loop, and Edge fired
// beforeinstallprompt inside such a gap while the wizard's state further down was still in its temporal dead
// zone (uncaught ReferenceError, 2026-08-26). So each handler does the always-safe half immediately — capture
// the event into state declared at the top of the module — and the UI half runs only once the module tail has
// flipped installPromptUiReady; a prompt captured before that is replayed by the tail exactly once.
function applyDeferredInstallPromptUi() {
  refreshInstallButtons();
  refreshQuickStartInstallStep();
  openInstallDialogIfUseful();
}
window.addEventListener('beforeinstallprompt', (event) => {
  event.preventDefault();
  deferredInstallPrompt = event;
  installedRelatedPwaDetected = false;
  if (installPromptUiReady) applyDeferredInstallPromptUi();
});
window.addEventListener('appinstalled', () => {
  deferredInstallPrompt = null;
  installedRelatedPwaDetected = true;
  markInstallPromptDismissed();
  closeInstallDialog({ dismissed: false });
  if (!installPromptUiReady) return;   // mid-evaluation install: the tail repaints from current state anyway
  refreshInstallButtons();
  refreshQuickStartInstallStep();
});
window.matchMedia?.('(display-mode: standalone)')?.addEventListener?.('change', refreshInstallButtons);
refreshInstallButtons();
refreshInstalledRelatedPwaState().catch(() => {});
for (const eventName of ['pointerdown', 'keydown', 'touchstart']) {
  window.addEventListener(eventName, noteWalletActivity, { passive: true });
}
document.addEventListener('visibilitychange', () => {
  if (document.hidden) {
    clearMessageAutoSyncTimer();
    clearVaultAutoRefreshTimer();
    stopIntroReceiveLane();
    noteWalletUnlockInterruptedByBackground();
    lockPlathoWalletForBackground();
  } else {
    enforceBackgroundGraceLockOnReturn();
    resumeWalletUnlockPrompt();
    scheduleMessageAutoSync(2_000);
    armIntroReceiveLane().catch((error) => console.warn('[intro] arm on visible failed', error));
    // Retry a recovery restore that a transient RPC error left incomplete (it did not latch), and re-fire a backup a
    // background-lock cancelled — a foreground-only session never re-boots, so this is the only place these recover.
    restoreConvKeysFromRecoveryIfBehind().then(rearmRecoveryBackupIfDirty).then(runRecoveryFreezeSweep).catch((error) => console.warn('[recovery] visible retry failed', error));
    // Return-from-wallet-app: refresh a quick-start balance step so topped-up funds show right away.
    quickStartRefreshCurrentBalanceStep();
    if (isVaultViewActive()) {
      refreshVaultNow({ includeActivation: true }).catch((error) => {
        if (noteTonRpcRateLimit(error)) setVaultStatus('RPC busy, retrying');
        if (!isExpectedVaultProviderUnavailable(error)) console.error(error);
      });
    } else {
      scheduleVaultAutoRefresh(2_000);
    }
  }
});
window.addEventListener('pagehide', () => {
  noteWalletUnlockInterruptedByBackground();
  clearMessageAutoSyncTimer();
  clearVaultAutoRefreshTimer();
  lockPlathoWalletForBackground();
});
window.addEventListener('pageshow', () => {
  enforceBackgroundGraceLockOnReturn();
  resumePendingPublicPublishConfirmations();
  resumePendingPrivateSendRetries();
  resumeWalletUnlockPrompt();
  scheduleMessageAutoSync(2_000);
  if (isVaultViewActive()) {
    refreshVaultNow({ includeActivation: true }).catch((error) => {
      if (noteTonRpcRateLimit(error)) setVaultStatus('RPC busy, retrying');
      if (!isExpectedVaultProviderUnavailable(error)) console.error(error);
    });
  } else {
    scheduleVaultAutoRefresh(2_000);
  }
});
window.addEventListener('focus', () => {
  enforceBackgroundGraceLockOnReturn();
  resumePendingPublicPublishConfirmations();
  resumePendingPrivateSendRetries();
  // THE THIRD RETURN DOOR, and it was the only one not asking. This handler is otherwise a line-for-line copy of
  // pageshow above; the omission meant a return that fires focus without visibilitychange or pageshow — which on
  // Android happens routinely, e.g. dismissing a system sheet or the app switcher over a still-visible page — came
  // back to a locked app in silence. Same call, same place in the sequence, so the three doors cannot drift again.
  resumeWalletUnlockPrompt();
  scheduleMessageAutoSync(2_000);
  if (isVaultViewActive()) {
    refreshVaultNow({ includeActivation: true }).catch((error) => {
      if (noteTonRpcRateLimit(error)) setVaultStatus('RPC busy, retrying');
      if (!isExpectedVaultProviderUnavailable(error)) console.error(error);
    });
  } else {
    scheduleVaultAutoRefresh(2_000);
  }
});
syncViewportCssVars();
window.addEventListener('resize', syncViewportCssVars, { passive: true });
window.visualViewport?.addEventListener?.('resize', syncViewportCssVars, { passive: true });
window.visualViewport?.addEventListener?.('scroll', syncViewportCssVars, { passive: true });
// touchstart decides (passive: it never refuses anything), touchmove enforces (NOT passive: refusing the gesture
// is the entire point). See refusePageDragWhileKeyboardIsUp for why this exists at all — WebKit 191204.
document.addEventListener('touchstart', armPageDragRefusal, { passive: true });
document.addEventListener('touchmove', refusePageDragWhileKeyboardIsUp, { passive: false });
// ...and the flag falls with the gesture that raised it, so it can never be inherited by the next one.
document.addEventListener('touchend', releasePageDragRefusal, { passive: true });
document.addEventListener('touchcancel', releasePageDragRefusal, { passive: true });

// Composer textareas auto-size on input, but a window/pane resize re-wraps EXISTING text (a one-liner
// becomes two lines when the window narrows) with no input event — so refit both fields on resize too.
window.addEventListener('resize', () => {
}, { passive: true });

customPublicChannels = readCustomPublicChannels();
rebuildPublicChannelRegistry();
publicChannelSubscriptions = readPublicChannelSubscriptions(publicChannelStorage(), publicChannelRegistry);
writePublicChannelSubscriptions(publicChannelStorage(), publicChannelSubscriptions);
loadPrefsSyncMeta();
refreshGlobalSyncIndicator();
publicChannelFeedCache = readPublicChannelFeedCache(publicChannelStorage());
publicChannelProfileCache = readPublicChannelProfileCache(publicChannelStorage());
// Warm per-wallet avatars from the IndexedDB media store BEFORE the first render so reloaded public feeds show
// faces immediately (no letter-tile placeholder + chain-refetch flash). Top-level await (app.js is a module),
// bounded by a short deadline so a slow/unavailable IndexedDB can never hang boot — past it the remaining
// avatars just hydrate from chain. Then migrate any legacy localStorage avatar cache off-thread.
// Start the branded boot-screen backdrop animation as early as possible (before the avatar-warm wait below),
// so the overlay that is already painted from HTML comes alive immediately.
initBootScreen();
// Warm public POST images from IndexedDB in parallel with author avatars — BOTH before the first render — so a
// reloaded post shows its own image in milliseconds. The localStorage feed cache stripped the image data-url on
// persist, so without this warm the image only came back after the full serial chain walk (~a minute — the
// owner-flagged "re-downloads from the blockchain every time"; it does not re-download, the walk that
// rediscovers the per-part entry ids to consult the durable body cache is what takes the minute). warm mutates
// the in-memory cache posts in place; rebuildThreadsFromPublicSubscriptions below reads them. If the IndexedDB
// read loses the 400ms boot-render race (rare — getMany is ms), re-render once it lands (flag-gated so a warm
// that WON the race — already reflected in the boot render — does not trigger a redundant repaint).
let publicBootFeedRendered = false;
// Warm BOTH media caches from IndexedDB before the first render — sequentially, never a concurrent Promise.all
// (the blanket no-concurrent-read guard; these are local IndexedDB reads, but the rule is a literal ban and
// serial is plenty fast). Bounded by one boot deadline so a slow/unavailable IndexedDB can never hang boot.
const publicBootMediaWarm = (async () => {
  await warmPublicChannelAvatarsFromCache();
  const changed = await warmPublicPostImagesFromCache().catch(() => false);
  // If this warm already landed BEFORE the boot render (won the race), the boot render below reflects it and
  // publicBootFeedRendered is still false → no redundant repaint. If it lands AFTER (slow IndexedDB lost the
  // race), re-render so the post image still appears in ms, not only after the serial chain sync.
  if (changed && publicBootFeedRendered) {
    rebuildThreadsFromPublicSubscriptions({ preserveActive: true });
    renderThreads();
    renderConversation();
  }
  return changed;
})();
await Promise.race([publicBootMediaWarm, delay(400)]);
setTimeout(() => { void migrateLegacyAvatarMediaCacheToIndexedDb(); }, 0);
// One-time cleanup: an EXISTING device cache (written before the strip below) may still hold megabytes of
// base64 media in localStorage — the root of the iOS Vault freeze. Re-persist it through the now-stripping
// writer so the on-disk store shrinks to light metadata. Deferred (setTimeout 0) so the single heavy
// re-serialize of the old store does not block boot; it runs before the user can navigate to the Vault tab.
// The in-memory cache keeps its media for rendering; only the persisted copy is lightened.
setTimeout(() => { try { writePublicChannelFeedCache(publicChannelStorage(), publicChannelFeedCache); } catch {} }, 0);
publicReadCursors = readScopedJsonMap(PUBLIC_READ_CURSORS_STORAGE_KEY);
publicCommentReadCursors = readScopedJsonMap(PUBLIC_COMMENT_READ_CURSORS_STORAGE_KEY);
rebuildThreadsFromPublicSubscriptions({ preserveActive: false });
renderConfiguredShell();
renderDocsNav();
// The boot public-feed render has now run; a post-image warm that lands AFTER this may re-render (see above).
publicBootFeedRendered = true;
