// ── App language (i18n) ─────────────────────────────────────────────────────────────────────
const appLanguageSelect = document.querySelector('#appLanguageSelect');
const quickStartLanguageSelect = document.querySelector('#quickStartLanguageSelect');

function populateLanguageSelect(select) {
  if (!select) return;
  select.innerHTML = '';
  for (const locale of I18N_LOCALES) {
    const option = document.createElement('option');
    option.value = locale.code;
    // Endonyms on purpose: a user hunting for their language must recognize it without knowing the current one.
    option.textContent = locale.native;
    select.append(option);
  }
  select.value = currentLocale();
}

populateLanguageSelect(appLanguageSelect);
populateLanguageSelect(quickStartLanguageSelect);

// Profile switch reloads: dynamic renders bake t() output into DOM all over the app, and a reload is the only
// switch that provably leaves no stale-language text (sends survive reloads by design — persisted publish state).
appLanguageSelect?.addEventListener('change', () => {
  setLocale(appLanguageSelect.value);
  window.location.reload();
});

// Quick-start switch applies in place: pre-wallet there is nothing dynamic rendered yet, and a reload here
// would visibly restart the dialog the user just opened.
quickStartLanguageSelect?.addEventListener('change', () => {
  setLocale(quickStartLanguageSelect.value);
  applyStaticTranslations();
  refreshProfileFeeLabels();
  // The public feed IS already rendered behind this dialog (it renders pre-wallet), and its cards bake t()
  // output into DOM. Re-render the public surfaces in the new locale — the locale term in
  // publicFeedItemRenderSignature forces the card rebuild that node reuse would otherwise skip.
  renderPublicSurface({ anchorUnread: false });
  if (appLanguageSelect) appLanguageSelect.value = currentLocale();
  // Re-render the stepper ONLY if it is actually open: renderQuickStartStep persists progress (resume-on-boot)
  // and may auto-advance — neither is welcome while the user is still on the welcome view.
  if (quickStartStepsView && !quickStartStepsView.hidden) renderQuickStartStep();
});

const QUICK_START_DISMISSED_KEY = 'platho.quickstart.dismissed.v1';
const QUICK_START_DISMISSED_CLOUD_KEY = 'platho_quickstart_dismissed_v1';
// Persisted so an in-progress quick start SURVIVES a reload or a background auto-lock (going to another wallet
// app to top up then returning locks Platho — without this the stepper is gone and, since a wallet now exists,
// never re-surfaces). Stores the active step index; cleared on finish / dismiss-forever.
const QUICK_START_PROGRESS_KEY = 'platho.quickstart.step.v1';

function quickStartDismissedForever() {
  try { return globalThis.localStorage?.getItem(QUICK_START_DISMISSED_KEY) === '1'; } catch { return false; }
}

function saveQuickStartProgress(stepIndex) {
  try { globalThis.localStorage?.setItem(QUICK_START_PROGRESS_KEY, String(stepIndex)); } catch { /* ignore */ }
}

function readQuickStartProgress() {
  try {
    const raw = globalThis.localStorage?.getItem(QUICK_START_PROGRESS_KEY);
    if (raw === null || raw === undefined || raw === '') return null;
    const n = Number(raw);
    return Number.isInteger(n) && n >= 0 ? n : null;
  } catch { return null; }
}

function clearQuickStartProgress() {
  try { globalThis.localStorage?.removeItem(QUICK_START_PROGRESS_KEY); } catch { /* ignore */ }
}

// Last-read external wallet GRAM balance in nanotons (from the shared vaultPocketState), or null if unknown.
function quickStartWalletTonNanotons() {
  const raw = vaultPocketState?.wallet?.ton_balance;
  if (raw === null || raw === undefined) return null;
  try { return BigInt(raw); } catch { return null; }
}

// iOS Telegram can evict localStorage between sessions, so a wallet-less user who
// dismissed the welcome would re-see it every launch. Mirror the dismissal into
// Telegram CloudStorage (no-op outside Telegram) and restore it on boot.
async function restoreQuickStartDismissalFromTelegramCloud() {
  if (!telegramCloudStorage()) return;
  if (quickStartDismissedForever()) return;
  try {
    if ((await telegramCloudGet(QUICK_START_DISMISSED_CLOUD_KEY)) === '1') {
      try { globalThis.localStorage?.setItem(QUICK_START_DISMISSED_KEY, '1'); } catch { /* ignore */ }
    }
  } catch { /* ignore */ }
}

async function runQuickStartCreateWallet(collectedPassword = null, { deferSeedGate = false } = {}) {
  if (hasStoredPlathoWalletRecord()) return true;
  const walletDraft = await createPlathoWallet(plathoWalletNetworkOptions());
  // The quick-start step collects the password in its own body and passes it here, so no dialog opens over the
  // wizard. Every other caller passes nothing and still gets the standalone prompt.
  const password = collectedPassword ?? await requestNewWalletStoragePassword(t('wallet.encryptNewWallet'), {
    passwordManagerUsername: walletDraft.address,
    passwordManagerNetworkGlobalId: walletDraft.networkGlobalId,
  });
  if (!password) return false;
  await setPlathoWallet(walletDraft, { password });
  markWalletKeyBackupPending(walletDraft.address);
  // The wizard shows the words as its own backup STEP; a hard dialog here would stack on the wizard card.
  if (!deferSeedGate) await enforceTelegramSeedBackupGate(walletDraft, { force: true });
  flashWalletIdentityStatus(t('wallet.walletReady'));
  refreshMessagingControls();
  return true;
}

// Refresh the external wallet GRAM balance into vaultPocketState (no step re-render — callers update in place).
// Reads the RECEIVE ADDRESS balance directly (public info) instead of requiring the unlocked wallet: onboarding can
// reach the top-up/activate steps with the wallet record stored but NOT loaded into runtime (step 1 auto-dones on
// the stored record after a resume/background-lock without unlocking), and requiring plathoWallet left the balance
// stuck on "checking…" forever.
async function quickStartRefreshWalletBalanceRaw() {
  const address = currentWalletReceiveAddress();
  if (!address) return;
  try {
    const balance = await loadConnectedTonWalletBalance(address);
    vaultPocketState = {
      wallet: { ton_balance: balance, ath_balance: vaultPocketState.wallet?.ath_balance ?? null },
    };
  } catch (error) { if (!noteTonRpcRateLimit(error)) console.error(error); }
}

// Top-up step body: receive address + a LIVE balance line so a user who just sent GRAM from another wallet app
// sees it arrive (auto-checked on entry + a manual "Check balance"). In-place text updates, never a re-render.
function buildQuickStartTopUpBody() {
  const wrap = document.createElement('div');
  wrap.className = 'quick-start-key-body';
  // [OWNER 2026-08-09] The address row carries its OWN copy button. The step's primary button used to BE the copy
  // action and silently doubled as Next, so a step with Back and Skip had no visible way forward — copying was the
  // only way on, which nobody can guess.
  const addrRow = document.createElement('div');
  addrRow.className = 'quick-start-address-row';
  const addr = document.createElement('div');
  addr.className = 'quick-start-step-address';
  const addressText = currentWalletReceiveAddress() || storedWalletAddressForCopy() || '';
  addr.textContent = addressText || t('quickstart.createWalletFirst');
  const copyBtn = document.createElement('button');
  copyBtn.type = 'button';
  copyBtn.className = 'icon-button quick-start-address-copy';
  copyBtn.title = t('wallet.copyAddress');
  copyBtn.setAttribute('aria-label', t('wallet.copyAddress'));
  copyBtn.disabled = !addressText;
  copyBtn.append(Object.assign(document.createElement('span'), { className: 'icon icon-copy', ariaHidden: 'true' }));
  copyBtn.addEventListener('click', async () => {
    if (!addressText) return;
    await copyTextToClipboard(addressText);
    flashWalletIdentityStatus(t('wallet.addressCopied'));
  });
  addrRow.append(addr, copyBtn);
  const balanceLine = document.createElement('div');
  balanceLine.className = 'quick-start-balance-line';
  const check = document.createElement('button');
  check.type = 'button';
  // Same full-width plate as the two steps before it (owner, 2026-08-10). The activate step builds its own
  // check-balance button separately and is deliberately left alone here.
  check.className = 'discovery-cta-action quick-start-key-cta';
  check.textContent = t('quickstart.checkBalance');
  const renderBalance = () => {
    const bal = quickStartWalletTonNanotons();
    balanceLine.textContent = bal === null ? t('quickstart.balanceChecking') : t('quickstart.walletBalance', { balance: formatTonNanotons(bal) });
  };
  const refresh = async () => {
    balanceLine.textContent = t('quickstart.balanceChecking');
    await quickStartRefreshWalletBalanceRaw();
    renderBalance();
  };
  check.addEventListener('click', () => { refresh(); });
  renderBalance();
  refresh();
  wrap.append(addrRow, balanceLine, check);
  return wrap;
}

// Activation step body: shows balance vs the activation fee and GATES on funds — an underfunded wallet cannot
// activate, so instead of letting the on-chain send fail, disable the action and offer "Back to Top up".
/** Short of the activation fee, as far as we currently know. `null` balance means "not read yet", not "empty". */
function quickStartActivationUnderfunded() {
  const bal = quickStartWalletTonNanotons();
  return bal !== null && bal < plathoAccountActivationFeeNanotons();
}

// The activation-is-impossible predicate lived here and is GONE with its only caller: the footer label used to fork
// on it ("Done" when activation could not run, "Continue" when it could) because this was the last step. Installing
// the app is the last step now, so the footer is plainly Next and the fork had nothing left to decide. The two
// states it combined are still read INSIDE applyGate, where they say which of the plate and the hint is on screen:
//
//   locked      — [MEASURED 2026-08-10] activation signs from the wallet, and locking clears localVaultDraft, so
//                 submitKeyShardRegisterDirect() threw on its first line and the user was told "could not complete,
//                 you can skip this" — the wrong problem, and it walks them away from a five-second fix.
//   underfunded — a button that is going to refuse reads as broken, which is the complaint that started this pass.

// CONFIRMED BY THE CHAIN, never by the broadcast. [OWNER 2026-08-13] The step reported "Done" the instant the
// external was accepted, and the Profile tab — which reads the shard — went on offering activation. Two surfaces
// disagreeing about one account, both seen within a minute. The transaction did land later, so this is not a lost
// send; it is the app stating a settled fact it had not read. Same rule the public lane was cured of this week.
let quickStartActivationDone = false;
// Sent and not yet settled. Hides the plate (re-pressing pays the fee twice) without claiming the account is active.
let quickStartActivationInFlight = false;
// Every rebuild of this step invalidates the confirmation wait belonging to the previous one, so a loop that
// outlives its body — the user went back a step, closed the wizard, or the wallet auto-locked — writes nothing.
let quickStartActivationGeneration = 0;

function buildQuickStartActivateBody() {
  quickStartActivationGeneration += 1;
  quickStartActivationDone = false;
  quickStartActivationInFlight = plathoActivationInFlightForCurrentWallet();
  // [OWNER 2026-08-10] TWO states, not one screen with four buttons.
  //
  //   funded  -> the balance line and ONE full-width "Activate account" plate. Footer: Back + Continue.
  //   short   -> the balance line and a sentence saying activation cannot happen yet and where to do it later.
  //              No action plate at all: offering a button that is going to refuse is the thing being removed.
  //
  // "Back to top up" is gone outright — it was a second copy of the footer's Back. "Check balance" is gone too:
  // the balance refreshes when this body is built and again whenever the app returns to the foreground, so the
  // button only ever restated something that already happens by itself.
  const wrap = document.createElement('div');
  wrap.className = 'quick-start-key-body';
  const summary = document.createElement('div');
  summary.className = 'quick-start-balance-line';
  const hint = document.createElement('div');
  hint.className = 'quick-start-step-hint';
  const activate = document.createElement('button');
  activate.type = 'button';
  activate.className = 'discovery-cta-action quick-start-key-cta';
  activate.textContent = t('quickstart.activateAction');
  activate.addEventListener('click', async () => {
    const generation = quickStartActivationGeneration;
    const mine = () => generation === quickStartActivationGeneration;
    activate.disabled = true;
    setText(quickStartStepStatus, t('quickstart.working'));
    try {
      const published = await submitVaultRegisterMessagingKeys({ preConfirmed: true });
      if (!mine()) return;
      // A null result means the shard ALREADY holds these keys and nothing was sent. Both paths fall through to the
      // same chain read below — "nothing to do" and "sent" differ only in what the step says while it waits.
      if (published !== null) {
        // [OWNER 2026-08-10] The plate stayed live after a successful activation, offering to do again a thing that
        // costs GRAM and is already done. applyGate re-reads this, so a later balance refresh cannot bring it back.
        quickStartActivationInFlight = true;
        applyGate();
        setText(quickStartStepStatus, t('quickstart.activationSent'));
      }
      await confirmActivation(generation);
    } catch (error) {
      console.error(error);
      if (!mine()) return;
      // The send itself failed — nothing is in flight, so the plate comes back for a retry.
      quickStartActivationInFlight = false;
      applyGate();
      setText(quickStartStepStatus, t('quickstart.couldNotCompleteLater'));
    } finally {
      if (mine()) activate.disabled = false;
    }
  });
  const applyGate = () => {
    const bal = quickStartWalletTonNanotons();
    const fee = plathoAccountActivationFeeNanotons();
    summary.textContent = bal === null
      ? t('quickstart.activationNeedsChecking', { fee: formatTonNanotons(fee) })
      : t('quickstart.balanceActivationNeeds', { balance: formatTonNanotons(bal), fee: formatTonNanotons(fee) });
    // Locked outranks short of funds: it blocks regardless of the balance, and unlike an empty wallet it is
    // fixable on the spot. maybeResumeQuickStartAfterUnlock re-renders this step, so unlocking updates it.
    const locked = !plathoWallet;
    const underfunded = quickStartActivationUnderfunded();
    const done = quickStartActivationDone || hasActivePlathoAccount();
    const inFlight = quickStartActivationInFlight && !done;
    const blocked = locked || underfunded;
    // The plate disappears once the fee is COMMITTED — settled or merely sent. Offering it during the settling
    // window is offering to pay a second time for one registration.
    activate.hidden = blocked || done || inFlight;
    hint.hidden = done || !(blocked || inFlight);
    hint.textContent = inFlight
      ? t('quickstart.activationSentHint')
      : locked
      ? t('quickstart.unlockToActivate')
      : underfunded
      ? t('quickstart.notEnoughGramHint')
      : '';
    // Waiting is not an error: nothing has gone wrong, so the line stays in the ordinary tone.
    hint.classList.toggle('is-error', blocked && !inFlight);
    // The footer label is NOT set from here any more. This step no longer ends the wizard — installing the app
    // does — so it is plainly "Next", which the step's own action() already says on every render.
  };
  // Watch the chain until this wallet's keys are registered, then — and only then — call it done. Shared by the
  // press and by a step that is REBUILT inside the settling window, so both surfaces resolve the same way.
  const confirmActivation = async (generation) => {
    const mine = () => generation === quickStartActivationGeneration;
    const confirmed = await waitForPlathoAccountActivation(mine);
    if (!mine()) return;
    if (confirmed) {
      quickStartActivationDone = true;
      quickStartActivationInFlight = false;
      applyGate();
      setText(quickStartStepStatus, t('quickstart.activationConfirmed'));
      return;
    }
    // Past the horizon and still not on chain. NOT a failure and NOT a reason to offer the plate again: the
    // external is out there, the Profile tab keeps watching, and the wizard says exactly that.
    applyGate();
    setText(quickStartStepStatus, t('quickstart.activationStillConfirming'));
  };
  const refresh = async () => {
    await quickStartRefreshWalletBalanceRaw();
    applyGate();
  };
  applyGate();
  refresh();
  // Rebuilt INTO the settling window — a reload, a language switch, or walking back to this step while an external
  // is still on its way. Nothing else is watching for this step (the previous body's wait died with its
  // generation), so it would sit on "sent, confirming" until some unrelated background refresh happened to land.
  if (quickStartActivationInFlight) {
    setText(quickStartStepStatus, t('quickstart.activationSent'));
    void confirmActivation(quickStartActivationGeneration);
  }
  wrap.append(summary, hint, activate);
  return wrap;
}

// The backup step's body: one full-width plate that saves the encrypted key file, built the same way as the
// get-a-key plate one step earlier (owner, 2026-08-10 — same style, its own row, stretched). Moving the real
// action out of the footer leaves the footer doing one job: Back and Continue, which is all a stepper footer
// should ever mean. Feedback goes to the step status line, mirroring what the footer action used to report.
function buildQuickStartBackupBody() {
  // [OWNER 2026-08-10] TWO buttons, each with a line saying what it saves. The inline phrase + "type SAVED" that
  // stood here read as a school exercise and, worse, the file button sat under the words with nothing explaining
  // it was a different thing. Both actions reuse the flows the Wallet tab already uses.
  const wrap = document.createElement('div');
  wrap.className = 'quick-start-key-body';
  const plate = (note, label, onClick) => {
    const hint = document.createElement('div');
    hint.className = 'quick-start-step-hint';
    hint.textContent = note;
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'discovery-cta-action quick-start-key-cta';
    button.textContent = label;
    button.addEventListener('click', async () => {
      button.disabled = true;
      try { await onClick(); } catch (error) { console.error(error); } finally { button.disabled = false; }
    });
    wrap.append(hint, button);
  };
  plate(t('quickstart.seedPlateNote'), t('quickstart.saveSeedAction'), async () => {
    const wallet = requirePlathoWallet();
    // NO PROMPT ONLY WHILE THE FOREGROUND STRETCH BELONGS TO WHOEVER TYPED THE PASSWORD. The old rule was "an
    // unlocked wallet can only exist because the password was entered in this session" — true until the 5-minute
    // background grace, under which an unlocked session is inherited by whoever picks the device up inside the
    // window [OWNER 2026-08-25]. The seed is the one secret that never expires, and this wizard resurfaces ON ITS
    // OWN for any wallet whose backup is pending, so it was the one password-free road to it. The boundary that
    // separates the two readers is a BACKGROUND TRANSITION: the creating user goes create -> save seed without
    // leaving, the thief by definition arrives after one. So that transition, not a timer, is the gate — and the
    // creation flow keeps exactly the frictionless step the no-prompt rule existed for.
    if (walletLeftForegroundSinceUnlock && !(await confirmWalletPasswordForExport(wallet))) return;
    await showWalletSeed(t('wallet.recoveryPhrase'), exportPlathoWalletRecoveryPhrase(wallet));
  });
  plate(t('quickstart.keyFilePlateNote'), t('quickstart.saveWalletKeyAction'), async () => {
    const ok = await exportEncryptedWalletKeyFile(plathoWallet ?? null);
    setText(quickStartStepStatus, ok === false ? t('quickstart.notCompleted') : t('quickstart.done'));
  });
  return wrap;
}

// Step 1's body IS the password form — no dialog over the wizard. It renders the shared field specs with
// createActionField, so the credential-username field and the autocomplete hints that make password managers work
// are the same nodes the standalone dialog builds, from one definition.
function buildQuickStartCreateWalletBody() {
  const wrap = document.createElement('div');
  wrap.className = 'quick-start-key-body';
  for (const field of walletPasswordFieldSpecs({ confirm: true, create: true })) {
    wrap.append(createActionField(field));
  }
  const summary = document.createElement('div');
  summary.className = 'quick-start-step-summary';
  for (const line of [
    t('wallet.passwordNotSentSummary'),
    t('wallet.passwordManagerSummary', { min: PLATHO_WALLET_PASSWORD_MIN_LENGTH, recommended: PLATHO_WALLET_PASSWORD_RECOMMENDED_LENGTH }),
    t('wallet.recoveryPhraseEncryptedSummary'),
  ]) {
    const row = document.createElement('div');
    row.textContent = line;
    summary.append(row);
  }
  wrap.append(summary);
  return wrap;
}

/** Read the two password boxes out of the step body and validate them the same way the dialog loop does. */
function quickStartCreateWalletPassword() {
  const read = (id) => normalizeWalletPasswordInput(quickStartStepBody?.querySelector(`#${id}`)?.value ?? '');
  const password = read('walletPassword');
  const confirmPassword = read('walletPasswordConfirm');
  if (password.length < PLATHO_WALLET_PASSWORD_MIN_LENGTH) {
    return { error: t('wallet.passwordTooShort', { min: PLATHO_WALLET_PASSWORD_MIN_LENGTH }) };
  }
  if (password !== confirmPassword) return { error: t('wallet.passwordsDoNotMatch') };
  return { password };
}

// ── INSTALL, AS A STEP RATHER THAN AN AFTERTHOUGHT ────────────────────────────────────────────────────────────
//
// [OWNER 2026-08-13] "the last step offered to install the app. That part is fine, but the last step is a modal,
// not in the wizard's style. Fold it into the wizard's steps and dress it properly. And the step before it should
// say Next, not Finish." Exactly: the wizard finished, and a modal in a different visual language arrived on top of
// it to ask for one more thing. So the ask moves INTO the wizard as its final step — same header, same counter,
// same footer — and the modal is dropped for anyone who saw the step (dropDeferredInstallPrompt).
//
// The copy comes from installCopyForState, the same definition the modal reads, so the two can never drift.
let quickStartInstallStepShown = false;
// Set while the step's own button is driving the browser's install sheet. refreshInstallButtons fires during that
// (the deferred event is spent the moment it is used), and re-rendering the step would pull the button out from
// under the tap that is still running.
let quickStartInstallPromptRunning = false;

function quickStartInstallCopy() {
  return installCopyForState();
}

/** Repaint the install step when the browser's install sheet becomes available — or stops being. */
function refreshQuickStartInstallStep() {
  if (quickStartInstallPromptRunning) return;
  if (!quickStartStepsView || quickStartStepsView.hidden) return;
  const step = QUICK_START_STEPS[quickStartStepIndex];
  // A step that has just become inapplicable (the app went standalone mid-step) is LEFT on screen: the footer's
  // Done still ends the wizard, which is the right ending, whereas re-running the skip logic would jump the user.
  if (step?.key !== 'install' || step.skip?.()) return;
  renderQuickStartStep({ skipCompleted: false });
}

function buildQuickStartInstallBody() {
  quickStartInstallStepShown = true;
  const copy = quickStartInstallCopy();
  const wrap = document.createElement('div');
  wrap.className = 'quick-start-key-body';
  const lead = document.createElement('div');
  lead.className = 'quick-start-step-hint';
  lead.textContent = copy.lead;
  wrap.append(lead);
  // ONE state has a button behind it: 'prompt', where the browser is holding an install sheet this tap can open.
  // The others are instructions — there is nothing to press, and a plate whose only effect was to reopen a modal
  // repeating these very words is the duplication this step exists to remove.
  if (copy.state === 'prompt') {
    const install = document.createElement('button');
    install.type = 'button';
    install.className = 'discovery-cta-action quick-start-key-cta';
    install.textContent = copy.action;
    install.addEventListener('click', async () => {
      install.disabled = true;
      quickStartInstallPromptRunning = true;
      setText(quickStartStepStatus, t('quickstart.working'));
      let message = '';
      try {
        const accepted = await firePendingInstallPrompt();
        // Declining is a DECISION, not a failure — the step is optional and Platho runs perfectly in a tab.
        message = accepted === true ? t('quickstart.installStarted') : t('quickstart.installNotNow');
      } catch (error) {
        console.error(error);
        message = t('quickstart.installUseBrowserMenu');
      } finally {
        quickStartInstallPromptRunning = false;
        install.disabled = false;
        // REPAINT FIRST, then speak. The sheet has been spent, so the step must fall back to its instructions —
        // and renderQuickStartStep blanks the status line on the way, which silently ate this message when it was
        // written before the repaint. [MEASURED 2026-08-13 in the preview: the tap left an empty status line.]
        refreshQuickStartInstallStep();
        setText(quickStartStepStatus, message);
      }
    });
    wrap.append(install);
  }
  if (copy.steps.length > 0) {
    const list = document.createElement('ol');
    list.className = 'install-steps';
    for (const text of copy.steps) {
      const item = document.createElement('li');
      item.textContent = text;
      list.append(item);
    }
    wrap.append(list);
  }
  const summary = document.createElement('div');
  summary.className = 'quick-start-step-summary';
  for (const line of [copy.body, copy.help]) {
    if (!line) continue;
    const row = document.createElement('div');
    row.textContent = line;
    summary.append(row);
  }
  wrap.append(summary);
  return wrap;
}

const QUICK_START_STEPS = [
  {
    title: () => t('quickstart.createWalletTitle'),
    action: () => t('quickstart.createWalletAction'),
    optional: false,
    why: () => t('quickstart.createWalletWhy'),
    autoDone: () => hasStoredPlathoWalletRecord(),
    body: () => buildQuickStartCreateWalletBody(),
    run: async () => {
      const { password, error } = quickStartCreateWalletPassword();
      if (error) return error;                       // shown on the step's own status line, nothing to dismiss
      return runQuickStartCreateWallet(password, { deferSeedGate: true });
    },
  },
  {
    key: 'toncenter',
    title: () => t('quickstart.addKeyTitle'),
    action: () => t('common.next'),
    optional: true,
    why: () => t('quickstart.addKeyWhy'),
    autoDone: () => false,
    body: () => {
      // Input FIRST, the get-a-key CTA below it with a clear gap (owner: the old order glued a
      // button-that-didn't-look-like-one on top of the field). The CTA reuses the shared plate-action
      // button class so it reads unmistakably as a button (same look as "Add contact").
      const wrap = document.createElement('div');
      wrap.className = 'quick-start-key-body';
      const input = document.createElement('input');
      input.type = 'text';
      input.id = 'quickStartKeyInput';
      input.autocomplete = 'off';
      input.spellcheck = false;
      input.placeholder = t('quickstart.pasteKeyPlaceholder');
      if (globalThis.plathoToncenterApiKey) input.value = globalThis.plathoToncenterApiKey;
      const getKey = document.createElement('button');
      getKey.type = 'button';
      // The extra class widens THIS plate to the full body (owner: stretch it), leaving the shorter Check-balance
      // plates on the top-up and activate steps hugging their text as before.
      getKey.className = 'discovery-cta-action quick-start-key-cta';
      getKey.textContent = t('quickstart.getFreeKey');
      getKey.addEventListener('click', () => { openToncenterBotLink(); });
      wrap.append(input, getKey);
      return wrap;
    },
    run: async () => {
      const value = quickStartStepBody?.querySelector('#quickStartKeyInput')?.value;
      const trimmed = String(value ?? '').trim();
      // An empty field is a DECISION, not a failure: the step is optional and Platho works without a key. Returning
      // false here is what made a Skip button necessary — the only way past an empty field was a second button.
      // A previously stored key is deliberately left alone, so a blank field can never silently drop one.
      if (!trimmed) return true;
      const result = await validateToncenterApiKey(trimmed);
      // A 401 HERE IS ALMOST NEVER A WRONG KEY. This step is reached seconds after the @toncenter bot issued
      // one, and toncenter answers 401 until it activates — which the settings path has always known (it saves
      // the key, shows 'activating' and re-verifies in the background) while this one did the opposite: refused
      // the key, saved nothing, scheduled nothing, and told a first-time user their brand-new key was rejected.
      // OBSERVED on the first real user, 2026-08-18.
      //
      // So onboarding now behaves like settings — keep the key, say it is activating, and let the background
      // re-verify settle it. Nothing is lost if the key really is wrong: the final attempt reverts to keyless,
      // which is the mode the user would have been in anyway had they skipped this step.
      applyToncenterApiKey(trimmed);
      if (result.reason === 'invalid') {
        setToncenterKeyStatusIcon('activating');
        scheduleToncenterKeyReverify(trimmed);
      }
      return true;
    },
  },
  {
    key: 'export',
    title: () => t('quickstart.backupKeyTitle'),
    action: () => t('common.next'),
    optional: false,
    why: () => t('quickstart.backupKeyWhy'),
    autoDone: () => false,
    body: () => buildQuickStartBackupBody(),
    // Both actions are one tap and neither leaves proof behind, so the footer simply moves on; the
    // pending-backup nudge is what re-opens this step for anyone who did neither.
    run: async () => true,
  },
  {
    key: 'topup',
    title: () => t('quickstart.topUpTitle'),
    action: () => t('common.next'),
    optional: true,
    why: () => t('quickstart.topUpWhy'),
    autoDone: () => false,
    body: () => buildQuickStartTopUpBody(),
    // Plain Next. Copying lives on the address row where the thing being copied is.
    run: async () => true,
  },
  {
    key: 'activate',
    title: () => t('quickstart.activateTitle'),
    // [OWNER 2026-08-13] Plainly "Next". This used to be the last step and said "Done", which is why the install
    // invitation had to arrive afterwards as a modal in nobody's style; now installing IS the last step and this
    // one only moves on, whether the activation ran, is settling, or has to wait for funds.
    action: () => t('common.next'),
    optional: true,
    why: () => t('quickstart.activateWhy'),
    autoDone: () => hasActivePlathoAccount(),
    body: () => buildQuickStartActivateBody(),
    // Activation itself is the plate in the body; the footer only moves on.
    run: async () => true,
  },
  {
    key: 'install',
    title: () => quickStartInstallCopy().title,
    action: () => t('common.done'),
    optional: true,
    why: () => t('quickstart.installWhy'),
    autoDone: () => false,
    // Nothing to offer: inside Telegram the PWA is meaningless, and an app already running standalone is already
    // installed. `skip` (not `autoDone`) because this is about the DEVICE, not about work the user has finished —
    // and unlike a satisfied step it must be stepped over going backwards too.
    skip: () => isTelegramEnv() || isStandaloneApp(),
    body: () => buildQuickStartInstallBody(),
    run: async () => true,
  },
];

let quickStartStepIndex = 0;

// The steps that exist ON THIS DEVICE. A skipped step must not leave a dot nobody can reach or make the counter
// promise a sixth screen that never arrives — the count the user is shown has to be the count they will walk.
function applicableQuickStartSteps() {
  return QUICK_START_STEPS.filter((step) => !step.skip?.());
}

function renderQuickStartProgress() {
  if (!quickStartProgress) return;
  quickStartProgress.innerHTML = '';
  const applicable = applicableQuickStartSteps();
  const currentIndex = applicable.indexOf(QUICK_START_STEPS[quickStartStepIndex]);
  applicable.forEach((_, i) => {
    const dot = document.createElement('span');
    dot.className = 'quick-start-progress-dot';
    if (currentIndex >= 0 && i < currentIndex) dot.classList.add('is-done');
    else if (i === currentIndex) dot.classList.add('is-current');
    quickStartProgress.appendChild(dot);
  });
}

function renderQuickStartStep({ skipCompleted = true } = {}) {
  const step = QUICK_START_STEPS[quickStartStepIndex];
  if (!step) { finishQuickStart(); return; }
  // A mandatory step that is already satisfied (e.g. a wallet already exists) is auto-skipped — but ONLY when
  // moving forward. [OWNER 2026-08-10] Back looked dead on the key step: it did fire and the index did
  // move, onto step 1 (create wallet), whose autoDone() is true by then — which advanced straight forward again,
  // so nothing ever appeared to happen. Going back is a request to LOOK at a step, not to complete it.
  // A step that does not apply to THIS DEVICE at all — the install step inside Telegram, or in an app already
  // running standalone — is stepped over in BOTH directions. That is what separates skip() from autoDone(): a
  // satisfied step is worth looking back at, a step that was never on this device's path is not.
  if (step.skip?.()) {
    if (skipCompleted) { quickStartAdvance(); return; }
    if (quickStartStepIndex > 0) { quickStartStepIndex -= 1; renderQuickStartStep({ skipCompleted: false }); return; }
    finishQuickStart();
    return;
  }
  if (skipCompleted && !step.optional && step.autoDone()) { quickStartAdvance(); return; }
  renderQuickStartProgress();
  const applicable = applicableQuickStartSteps();
  setText(quickStartStepCounter, t('quickstart.stepCounter', { n: applicable.indexOf(step) + 1, total: applicable.length }));
  // title/why/action are FUNCTIONS, resolved on every render. [MEASURED 2026-08-10] They used to be plain strings
  // built once when the module loaded, so `t()` had already run: switching language from the picker inside this very
  // dialog re-translated the static heading and left the step's own title, explanation and button in the old
  // language. The language row lives here, which makes the stepper the most likely place in the app to hit it.
  setText(quickStartStepTitle, step.title());
  setText(quickStartStepWhy, step.why());
  setText(quickStartStepStatus, '');
  if (quickStartStepBody) {
    quickStartStepBody.innerHTML = '';
    const body = step.body();
    if (body) quickStartStepBody.appendChild(body);
  }
  if (quickStartActionButton) quickStartActionButton.textContent = step.action();
  if (quickStartBackButton) quickStartBackButton.hidden = quickStartStepIndex === 0;
  // Persist the active step so a reload / background auto-lock resumes here (NOT in backup-only mode, which
  // re-surfaces on its own via the pending-backup nudge).
  if (!quickStartBackupMode) saveQuickStartProgress(quickStartStepIndex);
}

function quickStartAdvance() {
  if (quickStartStepIndex >= QUICK_START_STEPS.length - 1) { finishQuickStart(); return; }
  quickStartStepIndex += 1;
  renderQuickStartStep();
}

// When the quick-start is re-opened ONLY to finish the mandatory wallet-key backup (a wallet already
// exists), closing it must NOT permanently dismiss onboarding — the backup is still pending and should
// re-surface next launch. quickStartBackupMode tracks that so closeQuickStart skips the dismissed-forever flag.
let quickStartBackupMode = false;

function closeQuickStart() {
  hideDialogAnimated(quickStartDialog);
  // Every exit runs through here — finish, ✕ and skip-out alike — so the deferred welcome is released once, from
  // one place, whichever way the overlay was left.
  flushPendingActivationWelcome();
  // ...and only THEN the install card. If the line above just opened the welcome, this defers again and fires when
  // that closes — which is the order the owner asked for: "activated" first, "install Platho" after.
  //
  // Unless the wizard ALREADY asked. The install invitation is now a step of its own, so releasing the modal here
  // would put the same question on screen twice, the second time in the style the owner objected to.
  if (quickStartInstallStepShown) dropDeferredInstallPrompt();
  else offerDeferredInstallPrompt();
  quickStartInstallStepShown = false;
  if (!quickStartBackupMode) {
    // Explicit dismissal (X / Skip-out): stop onboarding for good AND drop the in-progress resume marker.
    try { globalThis.localStorage?.setItem(QUICK_START_DISMISSED_KEY, '1'); } catch { /* ignore */ }
    try { telegramCloudSet(QUICK_START_DISMISSED_CLOUD_KEY, '1').catch(() => {}); } catch { /* ignore */ }
    clearQuickStartProgress();
  }
  quickStartBackupMode = false;
}

function finishQuickStart() {
  clearQuickStartProgress();
  closeQuickStart();
  flashWalletIdentityStatus(t('quickstart.setupComplete'));
}

// ── ACTIVATION WELCOME ────────────────────────────────────────────────────────────────────────────────────────
//
// Activation used to complete in silence: the button vanished and nothing said what had changed (owner,
// 2026-08-07). It is also the single moment a user is certain to read something, so the two facts they cannot
// undo afterwards — nothing is deletable, public is public — are stated here rather than in a document nobody opens.
//
// THE TRIGGER IS THE CHAIN, NOT THE BROADCAST. It fires where refreshVaultActivationStatus has just read the
// user's OWN KeyShard and found their current keys registered. An activation external can be accepted by an RPC
// and never land; congratulating someone on an activation that did not happen is the same optimistic lie the send
// lanes were cured of this week.
const activationWelcomeDialog = document.querySelector('#activationWelcomeDialog');
const activationWelcomeCloseButton = document.querySelector('#activationWelcomeCloseButton');
const activationWelcomeStartButton = document.querySelector('#activationWelcomeStartButton');
const ACTIVATION_WELCOME_SHOWN_KEY_PREFIX = 'platho.activationWelcome.v1.';
// Shown once per WALLET: a second wallet on the same device is a different account and deserves its own briefing.
const activationWelcomeShownThisSession = new Set();
// Set when the account went active while the quick-start overlay owned the screen. Stacking a second backdrop over
// it is the v473 Telegram trap — both are .modal-backdrop, the later one paints on top and swallows the pointer, and
// in a Mini App that wedged the flow outright. So the welcome waits and becomes the LAST thing quick-start shows.
let pendingActivationWelcomeWallet = null;

function activationWelcomeStorageKey(walletAddress) {
  const raw = rawWalletAddress(walletAddress);
  return raw ? `${ACTIVATION_WELCOME_SHOWN_KEY_PREFIX}${raw}` : null;
}

function activationWelcomeAlreadyShown(walletAddress) {
  const key = activationWelcomeStorageKey(walletAddress);
  if (!key) return true;                                       // nothing to key it to — never pop it blind
  if (activationWelcomeShownThisSession.has(key)) return true; // covers a browser with no usable localStorage
  try { return globalThis.localStorage?.getItem(key) === '1'; } catch { return false; }
}

function markActivationWelcomeShown(walletAddress) {
  const key = activationWelcomeStorageKey(walletAddress);
  if (!key) return;
  activationWelcomeShownThisSession.add(key);
  try { globalThis.localStorage?.setItem(key, '1'); } catch { /* private mode / quota: the session set still holds */ }
}

function openActivationWelcomeDialog() {
  if (activationWelcomeDialog) { activationWelcomeDialog.classList.remove('is-closing'); activationWelcomeDialog.hidden = false; }
}

function closeActivationWelcomeDialog() {
  hideDialogAnimated(activationWelcomeDialog);
  // The install invitation waited for this. Now it may speak.
  offerDeferredInstallPrompt();
}

function maybeShowActivationWelcome(walletAddress) {
  if (!walletAddress || activationWelcomeAlreadyShown(walletAddress)) return;
  if (quickStartDialog && !quickStartDialog.hidden) { pendingActivationWelcomeWallet = walletAddress; return; }
  markActivationWelcomeShown(walletAddress);
  openActivationWelcomeDialog();
}

/** Quick-start has released the screen — show the welcome it deferred, if the account went active during it. */
function flushPendingActivationWelcome() {
  const wallet = pendingActivationWelcomeWallet;
  pendingActivationWelcomeWallet = null;
  if (!wallet || activationWelcomeAlreadyShown(wallet)) return;
  markActivationWelcomeShown(wallet);
  openActivationWelcomeDialog();
}

activationWelcomeCloseButton?.addEventListener('click', () => closeActivationWelcomeDialog());
activationWelcomeStartButton?.addEventListener('click', () => closeActivationWelcomeDialog());

// Resume the stepper at a specific step (reload / after a background auto-lock + unlock). Unlike openQuickStart,
// it skips the welcome view and jumps straight to where the user left off.
function openQuickStartAtStep(index) {
  if (!quickStartDialog) return;
  quickStartBackupMode = false;
  quickStartStepIndex = Math.max(0, Math.min(Number(index) || 0, QUICK_START_STEPS.length - 1));
  if (quickStartWelcomeView) quickStartWelcomeView.hidden = true;
  if (quickStartStepsView) quickStartStepsView.hidden = false;
  quickStartDialog.classList.remove('is-closing'); quickStartDialog.hidden = false;
  renderQuickStartStep();
}

// After a background auto-lock + unlock, bring the user straight back to the quick-start step they were on
// (e.g. they hopped to another wallet app to top up). No-op if it was dismissed.
function maybeResumeQuickStartAfterUnlock() {
  if (!quickStartDialog) return;
  if (quickStartDismissedForever()) return;
  if (quickStartDialog.hidden === false) {
    // Still open (it sat behind the lock screen): just re-check a balance step now that reads work again.
    quickStartRefreshCurrentBalanceStep();
    return;
  }
  const savedStep = readQuickStartProgress();
  if (savedStep !== null) openQuickStartAtStep(savedStep);
}

// Re-render the stepper IF it is showing a balance step (Top up / Activate) so it re-reads the wallet balance —
// used on return-to-foreground and after unlock so arrived funds show without a manual "Check balance".
function quickStartRefreshCurrentBalanceStep() {
  if (!quickStartDialog || quickStartDialog.hidden !== false) return;
  if (!quickStartStepsView || quickStartStepsView.hidden) return;
  const key = QUICK_START_STEPS[quickStartStepIndex]?.key;
  if (key === 'topup' || key === 'activate') renderQuickStartStep();
}

function openQuickStart() {
  if (!quickStartDialog) return;
  quickStartBackupMode = false;
  quickStartStepIndex = 0;
  if (quickStartWelcomeView) quickStartWelcomeView.hidden = false;
  if (quickStartStepsView) quickStartStepsView.hidden = true;
  quickStartDialog.classList.remove('is-closing'); quickStartDialog.hidden = false;
}

function quickStartStepIndexByKey(key) {
  const i = QUICK_START_STEPS.findIndex((step) => step.key === key);
  return i >= 0 ? i : 0;
}

// Re-open the quick-start jumped straight to the mandatory wallet-key backup step (used when a wallet exists
// but its key was never exported). The export step itself prompts for the password, so the wallet does not
// need to be unlocked first.
function openQuickStartAtBackup() {
  if (!quickStartDialog) return;
  quickStartBackupMode = true;
  quickStartStepIndex = quickStartStepIndexByKey('export');
  if (quickStartWelcomeView) quickStartWelcomeView.hidden = true;
  if (quickStartStepsView) quickStartStepsView.hidden = false;
  quickStartDialog.classList.remove('is-closing'); quickStartDialog.hidden = false;
  renderQuickStartStep();
}

function maybeShowQuickStartOnFirstRun() {
  if (!quickStartDialog) return false;
  // Resume an in-progress quick start FIRST (user began, then reloaded / backgrounded-and-locked): jump straight
  // to the saved step even though a wallet now exists — otherwise onboarding silently vanishes after step 1.
  const savedStep = readQuickStartProgress();
  if (savedStep !== null && !quickStartDismissedForever()) {
    openQuickStartAtStep(savedStep);
    return true;
  }
  if (!hasStoredPlathoWalletRecord()) {
    if (quickStartDismissedForever()) return false;
    openQuickStart();
    return true;
  }
  // A wallet exists but its encrypted key was never exported — keep nudging the backup until it is done.
  if (walletKeyBackupPendingForStoredWallet()) {
    openQuickStartAtBackup();
    return true;
  }
  return false;
}

quickStartBeginButton?.addEventListener('click', () => {
  quickStartStepIndex = 0;
  if (quickStartWelcomeView) quickStartWelcomeView.hidden = true;
  if (quickStartStepsView) quickStartStepsView.hidden = false;
  renderQuickStartStep();
});
quickStartCloseButton?.addEventListener('click', () => closeQuickStart());
quickStartImportButtonEl?.addEventListener('click', () => { closeQuickStart(); walletKeyBackupInput?.click(); });
quickStartBackButton?.addEventListener('click', () => {
  // skipCompleted:false — otherwise a finished mandatory step bounces the user straight back forward, which is
  // exactly how this button spent its life looking broken.
  if (quickStartStepIndex > 0) { quickStartStepIndex -= 1; renderQuickStartStep({ skipCompleted: false }); }
});
// The stepper's primary action, as a named function so the auto-start can take EXACTLY this path — same status
// line, same failure wording, same advance rule. A second copy of it would drift.
async function runQuickStartPrimaryAction() {
  const step = QUICK_START_STEPS[quickStartStepIndex];
  if (!step || !quickStartActionButton) return;
  quickStartActionButton.disabled = true;
  setText(quickStartStepStatus, t('quickstart.working'));
  try {
    const ok = await step.run();
    if (typeof ok === 'string') {
      // The step supplied its own failure message (e.g. an invalid key) — show it, do not advance.
      setText(quickStartStepStatus, ok);
    } else if (ok === false) {
      setText(quickStartStepStatus, step.optional ? t('quickstart.nothingEntered') : t('quickstart.notCompleted'));
    } else {
      setText(quickStartStepStatus, t('quickstart.done'));
      quickStartAdvance();
    }
  } catch (error) {
    console.error(error);
    setText(quickStartStepStatus, step.optional
      ? t('quickstart.couldNotCompleteLater')
      : t('quickstart.couldNotComplete', { reason: error?.message ?? t('quickstart.tryAgain') }));
  } finally {
    quickStartActionButton.disabled = false;
  }
}

quickStartActionButton?.addEventListener('click', () => { runQuickStartPrimaryAction(); });

// ---- Emoji picker ----------------------------------------------------------------------------------------------
// A self-contained unicode-emoji picker (NO external font/library — CSP style-src 'self'). ONE global fixed popover
// shared by the private + public composers (kept out of the panes so a tab switch never hides it), inserts at the
// target textarea's caret and dispatches 'input' so the composer's cost/draft/auto-resize listeners fire. Positioned
// via CSSOM left/bottom (per-property assignment is CSP-allowed, unlike setAttribute('style')).
const PLATHO_EMOJI_LIST = [
  '😀','😃','😄','😁','😆','😅','😂','🤣','🥲','😊','🙂','🙃','😉','😌','😍','🥰','😘','😋','😛','😜','🤪','😝','🤗','🤭','🤔','🤐','😶','😏','😒','🙄','😬','😔','😴','😷','🤒','🤢','🤮','🥵','🥶','😵',
  '🤯','🥳','😎','🤓','🧐','🙁','😣','😖','😫','😩','🥺','😢','😭','😤','😠','😡',
  '👍','👎','👌','🤌','🤏','✌️','🤞','🤟','🤘','🤙','👈','👉','👆','👇','☝️','✋','👋','💪','🙏','🤲','👐','🙌','👏','🤝',
  '❤️','🧡','💛','💚','💙','💜','🖤','🤍','🤎','💔','❣️','💕','💞','💓','💗','💖',
  '🔥','✨','⭐','🌟','💫','💥','💯','🎉','🎊','🎈','🎁','🌈','☀️','🌙','⚡','👑','💎','🥂','🍻','☕','🍕','🍑','👀','💀',
];
const emojiPicker = document.querySelector('#emojiPicker');
const emojiPickerGrid = document.querySelector('#emojiPickerGrid');
let emojiPickerTargetInput = null;
let emojiPickerTargetButton = null;

// Insert emoji (or the link dialog's markup) at the editor caret. A picker opened BEFORE the composer got
// blocked can outlive its (now-disabled) trigger button — never write into a disabled editor.
function insertEmojiAtCaret(input, emoji) {
  if (!input || input.disabled) return;
  composerEditorInsertText(input, emoji);
}

function positionEmojiPicker(button) {
  if (!emojiPicker || !button) return;
  const rect = button.getBoundingClientRect();
  const width = emojiPicker.offsetWidth; // measured after the picker is shown (display:block)
  const height = emojiPicker.offsetHeight;
  const left = Math.max(8, Math.min(rect.left, window.innerWidth - width - 8));
  emojiPicker.style.left = `${left}px`;
  // Normally open UPWARD (the composer sits at the bottom). But a MAXIMIZED composer puts the toolbar/emoji button at
  // the TOP of the full-screen overlay, so opening up would run off-screen — fall back to opening downward when there
  // isn't room above. (CSSOM per-property assignment only — prod CSP blocks setAttribute('style').)
  if (rect.top >= height + 8) {
    emojiPicker.style.top = 'auto';
    emojiPicker.style.bottom = `${Math.max(8, window.innerHeight - rect.top + 8)}px`;
  } else {
    emojiPicker.style.bottom = 'auto';
    emojiPicker.style.top = `${Math.min(rect.bottom + 8, Math.max(8, window.innerHeight - height - 8))}px`;
  }
}

function closeEmojiPicker() {
  if (!emojiPicker || emojiPicker.hidden) return;
  hidePopoverAnimated(emojiPicker);
  emojiPickerTargetButton?.setAttribute('aria-expanded', 'false');
  emojiPickerTargetInput = null;
  emojiPickerTargetButton = null;
}

function openEmojiPicker(button, input) {
  if (!emojiPicker || !button) return;
  emojiPickerTargetInput = input;
  emojiPickerTargetButton = button;
  emojiPicker.classList.remove('is-closing');
  emojiPicker.hidden = false;
  positionEmojiPicker(button);
  button.setAttribute('aria-expanded', 'true');
}

function toggleEmojiPicker(button, input) {
  if (!emojiPicker) return;
  if (!emojiPicker.hidden && emojiPickerTargetButton === button) { closeEmojiPicker(); return; }
  openEmojiPicker(button, input);
}

function setupEmojiPicker() {
  if (!emojiPicker || !emojiPickerGrid) return;
  for (const emoji of PLATHO_EMOJI_LIST) {
    const item = document.createElement('button');
    item.type = 'button';
    item.className = 'emoji-picker-item';
    item.textContent = emoji;
    item.setAttribute('aria-label', emoji);
    item.addEventListener('click', () => {
      const target = emojiPickerTargetInput;
      closeEmojiPicker(); // pick-then-close: one tap inserts and dismisses the panel
      if (target) insertEmojiAtCaret(target, emoji);
    });
    emojiPickerGrid.appendChild(item);
  }
  privateEmojiButton?.addEventListener('click', () => toggleEmojiPicker(privateEmojiButton, messageInput));
  publicEmojiButton?.addEventListener('click', () => toggleEmojiPicker(publicEmojiButton, publicMessageInput));
  document.addEventListener('click', (event) => {
    if (emojiPicker.hidden) return;
    if (emojiPicker.contains(event.target) || privateEmojiButton?.contains(event.target) || publicEmojiButton?.contains(event.target)) return;
    closeEmojiPicker();
  });
  document.addEventListener('keydown', (event) => { if (event.key === 'Escape' && !emojiPicker.hidden) closeEmojiPicker(); });
  window.addEventListener('resize', () => { if (!emojiPicker.hidden && emojiPickerTargetButton) positionEmojiPicker(emojiPickerTargetButton); });
}
setupEmojiPicker();

renderAthProfileStats();
refreshProfileFeeLabels();
updatePublicCommentsDefaultUi();
updatePrivateSenderModeUi();
setPublicCommentTarget(null);
rebuildThreadsFromPublicSubscriptions({ preserveActive: false });
if (activeThreadId) {
  appShell.dataset.chatOpen = 'true';
} else if (publicChannelThreads.length > 0) {
  appShell.dataset.chatOpen = 'false';
  setView('public');
} else {
  appShell.dataset.chatOpen = 'false';
}
installNavBackHandling();
renderThreads();
renderConversation();
refreshMessagingControls();
// Start the unified background sync loop regardless of the initial tab or wallet state: it ticks the public
// feed immediately and picks up private messages once a wallet/keys are present. It self-suspends on
// document.hidden and re-arms on visibility/focus/pageshow.
scheduleMessageAutoSync(2_000);
document.documentElement.dataset.plathoAppJs = 'ready';
bootCrypto()
  .then(() => { setBootDebug('crypto-locked'); })
  // ALL Telegram-CloudStorage restores are bounded by a single race: telegramCloudGet has no timeout, so a slow
  // or hung CloudStorage (mobile / Telegram WebView) could otherwise stall the whole chain BEFORE the unlock
  // decision — an eternal boot screen with no modal. They keep running in the background; the decision below
  // uses whatever local state is ready by the cap. (CloudStorage reads, not toncenter — outside the
  // PWA-FUNDS-SERIAL-01 concern; and no Promise.all array literal: the reads are chained, then raced.)
  .then(() => {
    setBootDebug('restore');
    const walletRestore = restoreWalletRecordFromTelegramCloud().catch(() => false);
    const dismissalRestore = restoreQuickStartDismissalFromTelegramCloud().catch(() => {});
    const backupRestore = restoreWalletKeyBackupPendingFromTelegramCloud().catch(() => {});
    return Promise.race([
      walletRestore.then(() => dismissalRestore).then(() => backupRestore),
      delay(2500),
    ]).catch(() => {});
  })
  .then(() => {
    try { refreshWalletBackupWarning(); } catch (error) { console.error(error); }
    // If we are driving the user through the mandatory wallet-key backup (a wallet exists but its key was
    // never exported), the backup step does its own unlock — don't also pop the startup unlock prompt
    // (avoids a confusing double password). Otherwise unlock as usual.
    const drivingBackup = walletKeyBackupPendingForStoredWallet();
    let quickStartShown = false;
    try { quickStartShown = maybeShowQuickStartOnFirstRun(); } catch (error) { console.error(error); }
    const hasWallet = hasStoredPlathoWalletRecord();
    setBootDebug(`decide wallet=${hasWallet ? 1 : 0} locked=${plathoWallet ? 0 : 1} backup=${drivingBackup ? 1 : 0} qs=${quickStartShown ? 1 : 0}`);
    // Quick-start / backup dialogs are modal-backdrops (z-index 40) that the overlay (55) would bury — reveal
    // the app before they show. The overlay stays up ONLY for the pure password-unlock path.
    if (quickStartShown || drivingBackup) {
      markBootAppReady();
      if (!drivingBackup) promptStoredWalletUnlockOnStartup().catch((error) => console.error(error));
      return;
    }
    if (hasWallet && !plathoWallet) {
      // Stored + locked: drive the unlock ON the overlay and keep it up until the core is ready / cancelled.
      void runBootScreenUnlock();
    } else {
      // Nothing to unlock (no wallet, or already unlocked) — reveal the app.
      markBootAppReady();
    }
  })
  .then(() => {
    // AN EXTERNAL PERMALINK is the only way into the app that is not a tap inside it. It runs AFTER the boot
    // decision so the post lands on a live surface, and INDEPENDENTLY of which branch that decision took — a
    // reader arriving from a link may have no wallet at all, which is exactly who a shared link is for. Its own
    // failures are handled inside (status + a cleared address bar), so nothing here can break the boot chain.
    // POST FORM FIRST: it is the stricter of the two (two segments, the second all digits and dots), so a path
    // that satisfies it can never have been meant as a channel.
    const link = parsePublicPostPermalink(location.pathname);
    if (link) return openPublicPostFromPermalink(link).catch((error) => console.error(error));
    const channelLink = parsePublicChannelPermalink(location.pathname);
    if (channelLink) return openPublicChannelFromPermalink(channelLink).catch((error) => console.error(error));
    return undefined;
  })
  .catch((error) => { setBootDebug(`boot-chain-err ${error?.message ?? error}`); console.error(error); });

// LAST TOP-LEVEL STATEMENT, deliberately: nothing after this line can be in a temporal dead zone, whatever
// top-level awaits suspended above. If the browser offered the install prompt while evaluation was suspended,
// run the UI half the handler had to skip.
installPromptUiReady = true;
if (deferredInstallPrompt) applyDeferredInstallPromptUi();
